INSERT INTO commentary_fts (unit_id,author,canonical_ref,language,content_type,content) VALUES
('purushottama-sc:source:6.2','Puruṣottamajī','gita.6.2','sa','commentary','।।6.2।।ननु कथमुक्तत्यागवान् योगी न भवेत् इत्याशङ्क्याह यं सन्न्यासमिति। यं सन्न्यासमिति प्राहुः प्रकर्षेण सर्वात्मभावरूपेण आहुस्तत्स्वरूपविदो भक्ताः तेऽधुनाऽधिकाराभावान्नोच्यन्ते अग्रे वाच्याः तं हे पाण्डव। योगं योगरूपं विद्धि जानीहि।पाण्डव इतिसम्बोधनेन ज्ञानयोग्यता निरूपिता। तस्मिन् सन्न्यासे विप्रयोगरसानुभवरूपे स्वाकाङ्क्षितफलत्यागो भवत्यतः संयोगसिद्धिः। अस्मिंस्तदभावान्न तत्सिद्धिरित्याह न हीति। असन्न्यस्तसङ्कल्पः न त्यक्तो मानसो नियमः स्वसुखानुभवरूपो येन तादृश कश्चन भावादिमानपि योगो न भवति। हीति युक्तश्चायमर्थः। यतः स्वसुखानुभवेच्छोः प्रभुसुखानुभवेच्छा नोदेति परस्परमुभयोः स्थितिरेकत्र न सम्भवति अतः स्वसुखानुभवरूपमानसनिश्चयत्यागवान् योगी भवतीति भावः।'),
('purushottama-sc:source:6.3','Puruṣottamajī','gita.6.3','sa','commentary','।।6.3।।ननु स्वसुखानुभवसङ्कल्पत्यागः सिद्धस्य भवति साधनदशापन्नस्य किं कर्त्तव्यं इत्यत आह आरुरुक्षोरिति। योगं आरुरुक्षोः संयोगरसप्राप्तीच्छोर्मुनेर्मननशीलस्य कारणं कर्म सेवात्मकमनुकारणरूपमुच्यते कथ्यत इत्यर्थः तस्यैव सेवादिकरणेन योगारूढस्य संयोगरसव्याप्तमनसः शमः अनुकरणादिकृतिरहितभावनाप्रवणस्थितिः कारणमुच्यते कथ्यते तत्प्राप्त्यर्थमिति शेषः।'),
('purushottama-sc:source:6.4','Puruṣottamajī','gita.6.4','sa','commentary','।।6.4।।स योगारूढः कथं ज्ञातव्यः इत्यत आह यदा हीति। यदा इन्द्रियार्थेषु रूपादिषु उत्कटतापनिवृत्त्यर्थं स्वप्नादिप्राप्तेषु हीति निश्चयेन पुरुषार्थरूपेण नानुषज्जते नाऽऽसक्तो भवति। न कर्मसु तत्साधककृतिरूपेषु अनुषज्जते नाऽऽसक्तो भवति। सर्वसङ्कल्पसन्न्यासी मनोनिश्चयात्मकस्वभोगेच्छादित्यागवान् यो नासक्तो भवेत्तदा योगारूढः संयोगभावे प्रतिष्ठित उच्यते कथ्यत इत्यर्थः।'),
('purushottama-sc:source:6.5','Puruṣottamajī','gita.6.5','sa','commentary','।।6.5।।ननु कर्मसु भगवल्लीलानुकरणरूपेषु मनोहरणैकस्वभावेषु कथमासक्तिर्न स्यात् इत्याकाङ्क्षायामाह उद्धरेदिति। आत्मना पुरुषोत्तमरूपेण आत्मानं जीवं कर्मभ्य उद्धरेत् आत्मानं न अवसादयेत् तत्रैवासक्तियुक्तं न कुर्यात्। हि युक्तश्चायमर्थः। आत्मनो जीवस्य आत्मैव जीव एव बन्धुः हितकृत्। आत्मनो जीवस्य आत्मैव स एव रिपुः शत्रुः अत्र आत्मना आत्मानमुद्धरेद्बन्धुभावेन न रिपुभावेन अवसादयेत्।'),
('purushottama-sc:source:6.6','Puruṣottamajī','gita.6.6','sa','commentary','।।6.6।।ननु कथं स एव बन्धुः कथं वा स एव शत्रुः अत आह बन्धुरिति। येन आत्मना भावस्वरूपेण आत्मा जितः वशीकृतः अधिकरणादिदेहकृतिभ्यो भावरूपे स्थापित इत्यर्थः। तस्य आत्मन आत्मैव बन्धुर्हितकृद्भवतीत्यर्थः। स्वस्य दास्यार्थे प्रकटितस्य तदुचितकरणैकभावप्रयुक्तसन्तोषेण बन्धुस्तद्भावस्वरूप एव स्वाधिदैविकस्वरूपेण भवतीति भावः। तु पुनः। अनात्मनो भावस्वरूपरहितस्य आत्मैव शत्रुवत् शत्रुत्वे तद्भावप्रतिबन्धके वर्तेत। तथा चायमर्थः भावरहितकेवलकर्मासक्तस्वदास्यार्थप्रकटितप्रयोजनरहितस्वस्य स्वरूपानर्थक्यकृतिरोषेणाधिदैविक आत्मा अत्र कर्मसु सेवादिषु तदावेशप्रतिबन्धको भवेत्।'),
('purushottama-sc:source:6.7','Puruṣottamajī','gita.6.7','sa','commentary','।।6.7।।ननु बन्धुत्वे कथं हितकृद्भवेत् इत्यत आह जितात्मन इति। जितात्मनः वशीकृतभावात्मनः। शीतोष्णसुखदुःखेषु संयोगविप्रयोगेषु प्रशान्तस्य संयोगे स्वसौभाग्यादिमदरहितस्य विप्रयोगे क्लेशेन प्रिये दोषारोपरहितस्य। तथा भगवतः सकाशान्मानापमानयोः समस्य। परमात्मा पुरुषोत्तमः समाहितस्तदर्थं दास्यदाने सावधानस्तिष्ठति। तद्धृदय एव समाहितस्तिष्ठतीति भावः।'),
('purushottama-sc:source:6.8','Puruṣottamajī','gita.6.8','sa','commentary','।।6.8।।ननु परमात्मा हृदयस्थोऽस्तीति कथं ज्ञातव्यः इत्याकाङ्क्षायामाह ज्ञानविज्ञानतृप्तात्मेति। ज्ञाने शास्त्ररीत्या भगवत्स्वरूपज्ञाने विज्ञाने भावात्मकत्वरूपानुभवे तृप्तः संशयकोटिरहित आत्मा अन्तःकरणं यस्य कूटस्थः निर्विकारः भगवच्चरणस्वरूपैकनिष्टः विजितेन्द्रियः स्वभोगेच्छारहितः युक्तो योगारूढ इत्युच्यते। समलोष्टाश्मकाञ्चनः मृत्पाषाणसुवर्णेषु समो भगवदीयभावरूपवान् योगी मत्संयोगवानुच्यते मयेति शेषः। अत्रायं भावः मृत्तिकायां भगवदङ्गसौगन्ध्यस्मरणेन सेवौपायिकशरीराप्तितापभाववान् पाषाणे भगवद्विप्रयोगजडतास्मरणेन स्वस्य तदभावतापात्तत्र स्निग्धभाववान् सौवर्णे चालौकिककान्तिदर्शनेन रसभाववांस्तथोच्यत इति भावः।'),
('purushottama-sc:source:6.9','Puruṣottamajī','gita.6.9','sa','commentary','।।6.9।।किञ्च एतत्ित्रतय एव न समः किन्तु सर्वत्रैव समबुद्धिरुत्तम इत्याह सुहृदिति। सुहृत् सर्वहितोपदेशकृत्। मित्रं स्नेहपरवशः अरिः स्वस्मिन् शत्रुबुद्धिमान् उदासीनो निरपेक्षः मध्यस्थो विवदमानयोः सदसद्वाक्यविचारकः द्वेष्यः सद्भावहीनः बन्धुः सम्बन्धी एतेषु साधुषु सदाचारेषु। अपि च किं पुनः पापेषु धर्मविरोधिषु समबुद्धिः भगवद्विप्रयोगेन भगवदात्मबुद्धिस्तेषु वा तद्विप्रयोगेन तथाभावदर्शी विशिष्यते योगयुक्तेपूत्तम इत्यर्थः। अत्रायं भावः भगवद्विप्रयोगे तत्सौहार्दस्मरणेनायं सर्वेषु सौहार्दधर्मवान् तथैव च मित्रधर्मवान् तद्रहितेषु अरिबुद्धिमान् तत्तद्दुःखेन सर्वत्रौदासीन्यधर्मवान् विप्रयोगावस्थायां तदनुकरणेन मध्यस्थधर्मवान् तथैव तत्क्लेशेन द्वेषधर्मवान् तत्सम्बन्धस्मरणेन बन्धुधर्मवान् तदर्थं सदाचारवान् तत्तापातिशयेन पापरूपवान् जडत्वधर्मेण एवं यः समबुद्धिः स विशिष्ट इत्यर्थः।'),
('purushottama-sc:source:6.10','Puruṣottamajī','gita.6.10','sa','commentary','।।6.10।।एवं योगारूढस्वरूपमुक्त्वा तस्य भावस्वरूपसिद्ध्यर्थं योगसाधनप्रकारमाहयोगी इत्यारभ्यस योगी परमो मतः 6।32 इत्यन्तम्। योगी योगारूढः आत्मानं भावात्मकं रूपं रहसि एकान्ते भगवच्चिन्तनस्थाने स्थितः सन् समाहितः सन् सततं युञ्जीत भगवति युक्तं कुर्यात्। एकाकी सङ्गदोषरहितः। यतचित्तात्मा यर्त वशीकृतं स्वभोगादिरहितं चित्तं भावरूपमात्मा देहेऽधिकरणात्मको येन। निराशीर्निर्गता मोक्षाद्याऽऽकाङ्क्षा यस्य। अपरिग्रहः संसर्गदुःखज्ञानेन त्यक्तपरिग्रहः सर्वापेक्षारहितः। एव युक्तचित्तः सन् मद्ध्यानं कुर्यादित्यर्थः।'),
('purushottama-sc:source:6.11','Puruṣottamajī','gita.6.11','sa','commentary','।।6.11।।ससामग्रीकं ध्यानस्वरूपमाह शुचाविति चतुष्टयेन। शुचौ देशे भावात्मकवृन्दावनादौ आत्मनो भगवतः स्थिरमासनं भावरूपं नात्युच्छ्रितं हृदयाद्बहिः केवलक्रीडायामेव स्थितम् नातिनीचं भावरहितानुकरणात्मकम्। कीदृशं चैलाजिनकुशोत्तरं चैलं वस्त्रं भावरूपंस्वैरुत्तरीयैः कुचकुङ्कुमाङ्कितैः भाग.10।32।13 इति न्यायेन अजिनं अधिकरणदेहस्थहृदयकमलात्मकं चैलाजिने कुशेभ्यः श्रीगोवर्धनादिस्थिततृणादिरूपेभ्य उत्तरे यस्मिन्। पूर्वं भावरूपतृणानि तदुपरि हृदयात्मकं तदुपरि भावात्मकं वस्त्रमेवं प्रतिष्ठाप्य।'),
('purushottama-sc:source:6.12','Puruṣottamajī','gita.6.12','sa','commentary','।।6.12।।तत्र भगवत्स्वरूपे एकाग्रं केवलदास्यभावेऽनन्यतया स्थितं मनः कृत्वा। यताः शान्ताश्चित्तन्द्रियक्रिया यस्य। चित्तक्रियाः स्वभोगचाञ्चल्यादयः इन्द्रियक्रियाः स्वतापनिवृत्त्यर्थं दर्शनाद्यभिलाषाः तादृशो भूत्वा आसने उपविश्य आत्मशु द्ध्यर्थं भावस्वरूपसिद्ध्यर्थं योगं भगवत्संयोगं युञ्ज्यात् अभ्यसेत्।'),
('purushottama-sc:source:6.13','Puruṣottamajī','gita.6.13','sa','commentary','।।6.13।।समं कायशिरोग्रीवं कायश्च शिरश्च ग्रीवा चकायशिरोग्रीवम्। कायपदेन चरणमारभ्य सर्वोऽपि देहः। भक्तिमार्गानुसारेण शिरः सत्यलोकात्मकम् ग्रीवा मुक्तिस्थानम्। समं यथास्थितरूपमचलं धारयन् ध्यानंकुर्वन्। स्थितः सन् स्वनासिकाग्रं सम्प्रेक्ष्य अर्धनिमीलितनेत्रो भावस्थः दिशश्चानवलोकयन् दिग्भावज्ञानशून्यः सर्वत्र भगवद्दर्शनवान्।'),
('purushottama-sc:source:6.14','Puruṣottamajī','gita.6.14','sa','commentary','।।6.14।।प्रशान्तात्मा भक्तिरसाभिनिविष्टचित्तः विगतभीःब्रह्मचारीश्रुत्यादिदुरापचरणरेणुभगवत्प्राप्तिसन्देहरहितः। ब्रह्मचारिव्रते स्थितः भगवदर्थेन्द्रियनिग्रहवान्। तादृशः सन् मनः संयम्य सर्वतः आकृष्य वशे कृत्वा मच्चित्तो मय्येव चित्तं यस्य। मत्परः अहमेव परः पुरुषार्थरूपो यस्य। एतादृशो भूत्वा युक्तः मद्योगस्थ आसीत तिष्ठेत्।'),
('purushottama-sc:source:6.15','Puruṣottamajī','gita.6.15','sa','commentary','।।6.15।।एवं योगाभ्यासकर्तुः फलमाह युञ्जन्निति। एवं सदा निरन्तरं नियतमानसः दास्यैकपरचित्तः आत्मानं युञ्जन्नपि युक्तं कुर्वन् योगी मयि योगवान् निर्वाणपरमां मोक्षाधिकां मत्संस्थां मत्स्वरूपरसात्मिकां शान्तिं वियोगक्लेशादिरहितभावमधिगच्छति प्राप्नोति।'),
('purushottama-sc:source:6.16','Puruṣottamajī','gita.6.16','sa','commentary','।।6.16।।एवं योगफलमुक्त्वा तस्य स्थित्यर्थमाहारादिकमाह नात्यश्नतस्त्विति। अति अश्नतः अधिकभोक्तुर्देहपुष्ट्यर्थं भुञ्जानस्य न च। एकान्तं सर्वथा अभुञ्जानस्य भगवत्स्वरूपमज्ञात्वा उपवासं कुर्वतः अतिस्वप्नशीलस्य निद्राशीलस्य सर्वविस्मरणैकस्वभावस्य जाग्रतश्च न चैव योगो मत्संयोगोऽस्ति।'),
('purushottama-sc:source:6.17','Puruṣottamajī','gita.6.17','sa','commentary','।।6.17।।यत एतादृशस्य योगो न भवतीत्यतो यथा योगसिद्धिः स्यात्तथोपायमाह युक्ताहारेति। युक्त आहारो विहारश्च यस्य भगवत्सेवार्थदेहपोषार्थं प्रसादं भुञ्जानस्य भगवत्सेवार्थानुकरणात्मककर्मसु प्रातरारभ्य स्नापानकादिरूपेषु नियुक्ता भगवदर्थैकरूपा चेष्टा यस्य युक्तौ स्वप्नावबोधौ भगवद्विश्रामोत्तरक्षणे सेवायां देहालस्यनिवारणार्थं स्वापः सेवासामग्रीसम्पादनादिष्ववबोधः एतादृशौ तौ यस्य। तस्य योगो भावात्मको मत्सङ्गात्मको दुःखहा तद्भावाभावतापादिहर्ता भवतीत्यर्थः।'),
('purushottama-sc:source:6.18','Puruṣottamajī','gita.6.18','sa','commentary','।।6.18।।नन्वेवं प्रवृत्तस्य भगवद्योगसिद्धिः कदा स्यात् इत्याकाङ्क्षायामाह यदेति। यदा यस्मिन् समये भगवत्सम्बन्धलक्षणभद्रकाले विनियतं वशीभूतं चित्तमात्मन्येव भावात्मकस्वरूप एव अवतिष्ठते स्थिरं भवति सर्वकामेभ्यो लौकिकेभ्यो निस्स्पृहो विगतेच्छो भवति तदा युक्त इत्युच्यते। सिद्धयोग उच्यत इत्यर्थः।'),
('purushottama-sc:source:6.19','Puruṣottamajī','gita.6.19','sa','commentary','।।6.19।।विनियतचित्तः कीदृग्विधः स्यात् इत्याकाङ्क्षायामाह यथेति। यथा दीपो वायुरहितप्रदेशस्थितो नेङ्गते न चलति यतचित्तस्यात्मनो भगवति योगं युञ्जतो भावयतो योगिनः सा उपमा स्मृता। अत्र दीपदृष्टान्तस्वायं भावः दीपस्य तापरूपत्वाद्वायोश्च शैत्यधर्मत्वात् तद्रहितदेशे तस्य नाशार्थं चाञ्चल्यं न भवति तथा भगवद्विप्रयोगतापनिवर्तकधर्मभावेन योगं युञ्जतो मनश्चञ्चलं न भवति।'),
('purushottama-sc:source:6.20','Puruṣottamajī','gita.6.20','sa','commentary','।।6.20।।यस्मिन् योगे मनश्चञ्चलं न भवति स कीदृशो योगः इत्यपेक्षायामाह यत्रेति सार्धैस्त्रिभिः। यत्र यस्यामवस्थायां योगसेवया भावात्मकसंयोगरूपभगवत्सेवया स्वभोगादिभ्यो निरुद्धं चित्तमुपरमते संयोगावस्थाभावरूपसमीपे रमते। यत्र चावस्थाविशेषे विविधभावस्फूर्तावात्मना भावरूपेणाऽऽत्मानं भावरूपं पश्यन् आत्मन्येव भावरूप एव तुष्यतितं योगसंज्ञितं विद्यात् इति तुर्ये 23 श्लोकत्रयस्याऽन्वयः।'),
('purushottama-sc:source:6.21','Puruṣottamajī','gita.6.21','sa','commentary','।।6.21।।तेषामुत्पत्तिप्रकारमाह सुखमिति। यत्र अवस्थाविशेषे तथाभूतसेवानुभव जाताग्रिमविविधमनोरथरूपे৷৷৷৷৷৷৷৷৷৷৷৷৷৷. आत्यन्तिकमतिशयितं जीवभावप्राप्तिफलात्मकं सुखं बुद्धिग्राह्यं भावात्मकस्वरूपात्मबुद्धिग्राह्यमतीन्द्रियं लौकिकेन्द्रियसम्बन्धाविषयं यत् तद्वेति। च पुनः अयं पुञ्जीवः यत्रावस्थायां तत्त्वतो भावात्मकदास्यफले रसकोटिस्फूर्तिरहितभावेन स्थितो नैव चलतितं विद्यात् 23 इत्यभिभ()श्लोकेनैव सम्बन्धः।'),
('purushottama-sc:source:6.22','Puruṣottamajī','gita.6.22','sa','commentary','।।6.22।।ननु तत्र स्थितस्य चलनाभावः कथं इत्यपेक्षायामाह यं लब्ध्वेति। यं सुखं लब्ध्वाततोऽधिकमपरं लाभं न मन्यते तत उत्तमत्वाभावात्। यस्मिन् स्थितो गुरुणाऽपि दुःखेन अधिकरणात्मकविप्रयोगादिना न विचाल्यते।'),
('purushottama-sc:source:6.23','Puruṣottamajī','gita.6.23','sa','commentary','।।6.23।।तं योगसंज्ञितं मद्योगसंज्ञात्मकं विद्यात् जानीयात्। कीदृशं तं दुःखसंयोगवियोगं दुःखात्मको यः संयोगो लौकिकोऽधिकरणदेहस्थो वा तस्य वियोगरूपम्। यतोऽयं योगः फलसाधकोऽतः स कार्य इत्याह सार्द्धेन स इति। स पूर्वोक्तः फलसाधकरूपो योगो निश्चयेन गुरूपदिष्टेन अनिर्विण्णेन दुःखज्ञानजप्रपत्तिशैथिल्येन हितेन मनसा योक्तव्यः कर्तव्य इत्यर्थः।'),
('purushottama-sc:source:6.24','Puruṣottamajī','gita.6.24','sa','commentary','।।6.24।।किञ्च सङ्कल्पप्रभवान् स्वभोगार्थकस्वमनोनिश्चयजान् कामान् स्वरमणेच्छादिरूपान् सर्वान् भावानन्तरमपि स्वेङ्गितज्ञरूपान् अशेषतः फलाभावज्ञाने त्यक्त्वा मनसैवेन्द्रियग्रामं नियम्य भगवदंशात्मकलावण्यादिरसान् पश्यन् मनसैव स्वार्थभोगरूपेणैव ततः विषयेभ्यो विनियम्य वशे संस्थाप्य योगो योक्तव्य इत्यर्थः।'),
('purushottama-sc:source:6.25','Puruṣottamajī','gita.6.25','sa','commentary','।।6.25।।ननु कथमिन्द्रियग्रामं विनियच्छेदित्यपेक्षयामाह शनैः शनैरिति। धृतिगृहीतया वियोगतापादिदुःखसहनशीलधैर्यगृहीतया बुद्ध्या मनः आत्मसंस्थं भावात्मकस्थितं कृत्वा शनैःशनैरुपरमेत् स्वभोगरूपेभ्य उपशमयेत्। कथमुपरतिर्भवेदित्यत आह न किञ्चिदपि चिन्तयेदिति। भावात्मकस्वरूपातिरिक्तं किञ्चिदपि न चिन्तयेन्न भावयेत्।'),
('purushottama-sc:source:6.26','Puruṣottamajī','gita.6.26','sa','commentary','।।6.26।।शनैरित्युक्तेः स्वरूपमाह यत इति। मनो यतो यतः स्वभावतश्चञ्चलं अस्थिरं यं यं प्रति निश्चलति ततस्ततो नियम्य वशीकृत्य एतन्मन आत्मन्येव भावात्मके भगवत्येव वशं नयेत् प्रापयेत्। अत्रायं भावः पूर्वं यत्र स्थितं मनस्ततोऽन्यत्र वैशिष्ट्यबुद्ध्या ततो निर्गत्याऽपगच्छति। तत्राऽपि स्वचाञ्चल्यधर्मेण न स्थिरीभविष्यति तस्माद्भगवत्स्वरूपतोऽन्यत्रोत्तमत्वाभावान्नाग्रे चलिष्यत्यतोऽन्यतो वशीकृत्य भगवति स्थापयेत्।'),
('purushottama-sc:source:6.27','Puruṣottamajī','gita.6.27','sa','commentary','।।6.27।।एवम्भावात्मके भगवति मनस्स्थैर्ये यत्फलं स्यात्तदाह प्रशान्तमनसमिति। प्रशान्तमनसं भगवति स्थिरमनसमेनं योगिनं शान्तरजसं विक्षेपदोषरहितमुत्तमं सुखं ब्रह्मभूतं भगवद्रसात्मकमकल्मषं स्वभोगादिसुखदोषरहितमुपैति।'),
('purushottama-sc:source:6.28','Puruṣottamajī','gita.6.28','sa','commentary','।।6.28।।एवं सुखाप्तौ किं स्यात् इत्यत आह युञ्जन्निति। एवं पूर्वोक्तप्रकारेण सदा भगवति आत्मानं भावात्मकं युञ्जन् योगी विगतकल्मषः स्यात्। ततः प्राप्तेनानेन सुखेन ब्रह्मसंस्पर्शं भगवच्चरणारविन्दसंवाहनादिसेवारूपमत्यन्तं सुखं दास्यात्मकमश्नुते भुञ्जत इत्यर्थः।'),
('purushottama-sc:source:6.29','Puruṣottamajī','gita.6.29','sa','commentary','।।6.29।।ब्रह्मसंस्पर्शसुखं स्पष्टयति सर्वभूतस्थमिति। योगयुक्तात्मा भगवत्संयोगयुक्त आत्मा सर्वत्र संयोगविप्रयोगभावे समदर्शन आत्मानं भगवन्तं सर्वभूतस्थं विप्रयोगावस्थायां च पुनरात्मनि भगवत्स्वरूपे संयोगावस्थायां सर्वभूतानि सेवास्थितानि ईक्षते पश्यतीत्यर्थः। एतेन भगवत्स्वरूपज्ञानात्मसुखमुक्तमिति भावः।'),
('purushottama-sc:source:6.30','Puruṣottamajī','gita.6.30','sa','commentary','।।6.30।।एवं स्वरूपज्ञानफलमाह यो मामिति। यः सर्वत्र जीवेषु वियोगावस्थायां मां पश्यति संयोगावस्थायां मयि सर्वं पश्यति तस्याहं न प्रणश्यामि न कदाचिदपि वियुक्तो भवामि। स च मे मत्तः न प्रणश्यति न वियुक्तो भवतीत्यर्थः।'),
('purushottama-sc:source:6.31','Puruṣottamajī','gita.6.31','sa','commentary','।।6.31।।किञ्च यः सर्वभूतस्थितं सर्वजीवेषु रसभोगार्थं वाऽलौकिकेषु निरोधार्थं स्थितं एकत्वं भगवदीयत्वेन सजातीयत्वमास्थितं मां भजति स योगी उच्यते। अथवा सर्वथा तेषु दास्यादिभावशिक्षणार्थं वर्त्तमानो यः स मयि च वर्तते मत्स्वरूपे तिष्ठतीत्यर्थः।'),
('purushottama-sc:source:6.32','Puruṣottamajī','gita.6.32','sa','commentary','।।6.32।।ननु सर्वत्र कथमेकात्मत्वेन वर्तते इत्यत आह आत्मौपम्येनेति। आत्मौपम्येन स्वसादृश्येन यथा स्वस्य कृपया संयोगरसाप्तौ सुखं वियोगरसाप्तौ दुःखं तथा सर्वत्र सर्वजीवेषु सुखं यदि वा दुःखं समं यः पश्यति स योगी मम परम उत्कृष्टो मतोऽभिमत इत्यर्थः। अत्रायं भावः योऽलौकिकसुखदुःखाभिनिविष्टेष्वपि जीवेषु यथा स्वस्य तदंशलेशज्ञानेन सुखदुःखरसानुभवो भवति तथैव सर्वेषामप्यस्ति एवं यस्य सर्वत्रालौकिकस्फूर्तिः स्यात् स उत्तम इति भावः।'),
('purushottama-sc:source:6.33','Puruṣottamajī','gita.6.33','sa','commentary','।।6.33।।उक्तभावसिद्ध्यर्थं साधनमर्जुनः पृच्छति अर्जुन उवाचयोयं योग इति। हे मधुसूदन दुष्टनिराकरणसमर्थ अयं योगस्त्वया साम्येन सुखदुःखसाम्येन स्वसाम्येन सर्वेषु प्रोक्तः। एतस्य योगस्याऽहं अभिमानयुक्तत्वान्मनसश्चञ्चलत्वात् स्थितिं स्थिरां निश्चलां न पश्यामि।'),
('purushottama-sc:source:6.34','Puruṣottamajī','gita.6.34','sa','commentary','।।6.34।।मनसश्चाञ्चल्यमेवाह चञ्चलं हीति। हे कृष्ण सदानन्द मनो हीति निश्चयेन चञ्चलं स्वभावत एव चपलम् अन्यथा सदानन्दोक्तौ कथं पुनः प्रश्नार्थमहमुद्युक्तः इति कृष्णेति सम्बोधनेन ज्ञापितम्। किञ्च प्रमाथि प्रकर्षेण मथनशीलं इन्द्रियक्षोभकम्। किञ्च बलवत् अतिप्रबलं ज्ञानादिवचनासाध्यम्। किञ्च दृढं स्वविषयानुरागाऽत्यागस्वभावम्। तस्य मनसो निग्रहं वशीकरणं आकाशे दोधूयमानस्य स्वसुखार्थं तापनिवारणाय गृहादिषु वायोरिव निरोधनं सुदुष्करं सर्वथा कर्त्तुमशक्यमहं मन्ये। यद्वा वायोः प्राणवायोर्गच्छतो निरोधमशक्यं मन्य इति भावः।'),
('purushottama-sc:source:6.35','Puruṣottamajī','gita.6.35','sa','commentary','।।6.35।।एवमर्जुनोक्तचञ्चलत्वादिकमङ्गीकृत्य तन्निग्रहसाधनमाह भगवान् श्रीभगवानुवाच असंशयमिति। हे महाबाहो क्रियाशक्तिसमर्थ मनो दुर्निग्रहं चञ्चलं यद्वदसि तदसंशयं निस्सन्दिग्धं तादृशमेवास्तु। तु पुनस्तथापि कौन्तेय मदुक्तिविश्वसनैकयोग्य भक्तपुत्र अभ्यासेनयतो यतो निश्चलति 26 इति पूर्वोक्तप्रकारेणाऽन्यत्र हीनत्वज्ञानपूर्वकमप्युत्तमज्ञानेन चाञ्चल्यानुसरणप्रकारेण गृह्यते। च पुनः। तथा ज्ञानेन मत्सम्बन्धातिरिक्तेषु वैराग्येण गृह्यते वशीक्रियत इत्यर्थः।'),
('purushottama-sc:source:6.36','Puruṣottamajī','gita.6.36','sa','commentary','।।6.36।।अथ यो मनश्चञ्चलमिति ज्ञात्वाऽभ्यासवैराग्ययोर्यत्ननिरपेक्षः स नाप्नोतीत्याह असंयतात्मनेति। असंयतात्मना उक्तप्रकारेणाभ्यासवैराग्याभ्यामसंयतः अवशीकृत आत्माऽन्तःकरणं यस्य तेन योगो मत्संयोगात्मको दुष्प्रापः दुःखेनापि प्राप्तुमशक्यः। वश्यात्मना तु अभ्यासवैराग्यवशीकृतयत्नेन यतता मत्संयोगार्थं यत्नं कुर्वता उपायतोऽवाप्तुं शक्य इति मे मतिः। अत्र स्वमतित्वकथनेन मदुक्तिविश्वासपूर्वकं यो यतेत तस्याऽवश्यं मया संयोगः फलदानं कर्तुं मनोनिग्रहः करणीय इति व्यञ्जितम्।'),
('purushottama-sc:source:6.37','Puruṣottamajī','gita.6.37','sa','commentary','।।6.37।।अथ भवदुक्तिविश्वासेन केवलं श्रद्धया अभ्यासवैराग्यरहितो यत्नं कुर्वन् पश्चात्सिद्धिं प्राप्नोति न वा इति प्रभुं विज्ञापयत्यर्जुनः अर्जुन उवाच अयतिरिति। श्रद्धया भवदुक्तिश्रद्धामात्रत उपेतो भगवत्संयोगात्मकयोगार्थे प्रवृत्तः अयतिः अभ्यासवैराग्ययोः शिथिलप्रयत्नः स्वरूपज्ञानाभावाद्योगाच्चलितमानसो भवति। ततो योगसिद्धिमपि न प्राप्नुयात् तदाह योगसंसिद्धिमप्राप्य कृष्ण सदानन्द त्वदुक्तिविश्वासप्रवृत्तस्य सिद्धिरेवोचितेति विज्ञाप्य कां गतिं गच्छतीति पृष्टवान्।'),
('purushottama-sc:source:6.38','Puruṣottamajī','gita.6.38','sa','commentary','Sri Purushottamji did not comment on this sloka'),
('purushottama-sc:source:6.39','Puruṣottamajī','gita.6.39','sa','commentary','।।6.39।।हे कृष्ण दास्येन सदानन्ददानसमर्थ एतन्मे संशयं मन्मनोगतसंशयम्। स तु न नश्यत्येवत्वदुक्तिविश्वासात् परं मत्संशयमशेषतः सोपपत्तिकाज्ञारूपवाक्यैश्छेत्तुं दूरीकर्तुमर्हसि। नन्वन्यत्र गुर्वादिषु भक्तेषु च विज्ञाप्य संशयं दूरीकुर्वित्यत आह त्वदन्य इति। अस्य मद्गतस्य त्वदेकवाक्यैकनिष्ठस्य मम संशयस्य छेत्ता त्वदन्यः त्वां विना हि निश्चयेन अन्यो नोपपद्यते।'),
('purushottama-sc:source:6.40','Puruṣottamajī','gita.6.40','sa','commentary','।।6.40।।एवं निश्चयात्मकमर्जुनस्य संशयवाक्यं श्रुत्वा भगवांस्तमाह श्रीभगवानुवाच पार्थेति। हे पार्थ तथासंशयानर्ह इह लोके पूर्वत्यक्तकर्मानुकरणविहितधर्मभक्त्यादौ अमुत्र लोके परदास्यादिरूपे तस्य मदुक्तिविश्वासप्रवृत्तस्य विनाशः विशेषेण नाशो मददर्शनं न विद्यते। श्रद्धया मदुक्तिविश्वासप्रवृत्तौ कथं नाशः स्यात् यतोऽसाधारण्येनोत्तमकृतिप्रवृत्तस्य नाशो न भवतीत्याह नहीति। भक्तत्वात्स्वबालकत्वेन तातेति सम्बोध्योपदिष्टम्। कल्याणकृत् धर्मादिबुद्ध्या फलेच्छासाधारण्येन शुभकृत् हीति निश्चयेन दुर्गतिं न गच्छति। तत्र श्रद्धयाऽत्र प्रवृत्तः कथं नश्येदित्यर्थः।'),
('purushottama-sc:source:6.41','Puruṣottamajī','gita.6.41','sa','commentary','।।6.41।।एवं नाशाभावमुक्त्वा तस्य गतिस्वरूपमाह प्राप्येति। स योगभ्रष्टः स्वरूपाज्ञानादभ्यासवैराग्याभावादभ्यस्यमानमार्गाद्भ्रष्टः पुण्यकृतां यज्ञादिकारिणां लोकान् श्रद्धामात्रप्रवृत्तिसाधनेन तत्फलभोगविचिकित्साजनितपूर्वप्रवृत्तमार्गस्वरूपज्ञानार्थं प्राप्य तत्र शाश्वतीः समाः बहून् संवत्सरान् उषित्वा स्थित्वा तत्फलभोगं कृत्वा तत्र विचिकित्सयाऽभावकेन मनसा पूर्वश्रद्धासाधनेनैव भवति। जन्मप्रार्थनया शुचीनां कापट्यादिदोषरहितानां श्रीमतां भगवच्छोभायुक्तानां भक्तानां गृहेऽभिजायते जन्म प्राप्नोति। उपसर्गेण स৷৷৷৷৷৷৷৷৷৷৷৷৷৷.रतिपूर्वकं प्राप्तिर्ज्ञापिता।'),
('purushottama-sc:source:6.42','Puruṣottamajī','gita.6.42','sa','commentary','।।6.42।।पक्षान्तरमाह अथवा धीमतां स्वरूपज्ञानवतां कुले भवति जन्म प्राप्नोति। धीमत्त्वोक्त्या तत्कुलप्रसूतिमात्रेण ज्ञानोत्पत्तिर्व्यञ्जिता। जन्म विशिनष्टि एतदिति। हीति निश्चयेनैतद्दुर्लभतरं यल्लोके ईदृशं भगवत्स्वरूपज्ञानात्मकं जन्म।'),
('purushottama-sc:source:6.43','Puruṣottamajī','gita.6.43','sa','commentary','।।6.43।।तादृशजन्मानन्तरं किं स्यात् इत्यत आह तत्र तमिति। तत्र तस्मिन् जन्मद्वयेऽपि तं पौर्वदेहिकं भगवत्कृपालब्धजीवभावानन्तरप्राप्तं प्रथमदेहसम्बन्धिनं बुद्धिसंयोगं भगवत्सेवार्थप्रकटितज्ञानरूपं भगवदीयकुलजन्ममात्रेण लभते। च पुनः तं लब्ध्वा भूयः सिद्धौ सम्यक् सिद्ध्यर्थं तथा भगवत्प्राप्त्यर्थं यतते यत्नं करोति। कुरुनन्दनेतिसम्बोधनं विश्वासार्थम्।'),
('purushottama-sc:source:6.44','Puruṣottamajī','gita.6.44','sa','commentary','।।6.44।।ननु भूयोऽपि यत्ने पूर्ववदेव चेत्स्यात्तदा किं जन्मना यत्नेन चेत्याशङ्क्याह पूर्वाभ्यासेनेति। तेनैव पूर्वाभ्यासेन श्रद्धामयेन अवशोऽपि तादृक्कुलजन्मप्राप्त्या कुलरीत्यापि अन्यभावेभ्यो हीयते परावर्त्तते भगवत्संयोगरसनिष्ठः क्रियत इति भावः। ननु पूर्वप्रवृत्त्या श्रद्धायुक्तया चेन्न सिद्धिरभूत् तदा कथमिदानीं तेनैव साधनेन सिद्धिर्भविष्यति इत्याशङ्क्याह जिज्ञासुरपीति। योगस्य स्वरूपजिज्ञासुरेव शब्दब्रह्म नामरूपात्मकं विप्रयोगसामयिकजीवनहेतुरूपमतिवर्त्तते अतिक्रामति। परमक्लेशाविर्भावेन गुणगानादित्यागेन लौकिकदेहत्यागेनालौकिकदेहमाप्नोतीति भावः। तथा चायमर्थः पूर्वश्रद्धया प्रवृत्तस्तु योगजिज्ञासया न प्रवृत्तः किन्तु साधारण्येन वाक्यश्रद्धयैव प्रवृत्तौ तेन सिद्धिरभूत्। अधुना तूत्तमकुलजन्माप्त्या तत्स्वरूपं कुरुते अतः प्राप्स्यतीति।'),
('purushottama-sc:source:6.45','Puruṣottamajī','gita.6.45','sa','commentary','।।6.45।।एतादृशकुलजन्मभावेऽपि यत्नवा प्राप्नुयात् तत्र तादृक्कुलोत्पन्नप्राप्तौ किं वक्तव्यं इत्याह प्रयत्नादिति। यः सामान्यो न तु तादृशजन्मवानेव प्रयत्नाद्यतमानः संशुद्धकिल्बिषः तद्भावज्ञानप्रतिबन्धपापरहितो योगी योगस्वरूपज्ञानवान् भवति। तु पुनः। अनेकजन्मसंसिद्धः अनेकजन्मभिर्यतमानः सन् सिद्धः प्राप्तयोगरूपो भवति। ततः परां गतिं दास्यरूपां याति प्राप्नोतीत्यर्थः। यतो मत्संयोगात्मको योग उत्तमस्तस्मात्त्वं योगी भवेति।'),
('purushottama-sc:source:6.46','Puruṣottamajī','gita.6.46','sa','commentary','।।6.46।।योगस्य सर्वाधिकत्वं प्रतिपादयन्नेवाह तपस्विभ्य इति। तपस्विभ्यः योगस्वरूपाज्ञानेतदभिलाषाभावेन केवलक्लेशसहनशीलेभ्यो योगी अधिकः। किञ्च ज्ञानिभ्यः ज्ञानेन सन्न्यासादिधर्मयुक्तेभ्योऽपि योगी अधिको मतः मेऽभिमतः। ज्ञानी च पुनः कर्मिभ्यो यज्ञनित्यादिनिष्ठेभ्यो योगी अधिको मतः। तस्मात् हे अर्जुन मत्स्नेहैकयोग्य त्वं योगी भव युक्तो योगनिष्ठो भवेत्यर्थः।'),
('purushottama-sc:source:6.47','Puruṣottamajī','gita.6.47','sa','commentary','।।6.47।।योगिनोऽपि बहुविधा इति तन्मध्ये दास्यधर्मेण भजनवानुत्तम इत्याह योगिनामपीति। सर्वेषामपि योगिनां मध्ये योगिनस्त्रिविधाः योगाभ्यासेन भगवद्ध्याननिष्ठाः भक्तियोगेन साधनसेवनपराः रसात्मकस्वसंयोगभावनिष्ठाः तन्मध्ये मद्गतेन अन्तरात्मना भावात्मकस्वरूपेण मम स्वशक्तिसंयोगेच्छारूपयोगेन मदर्थं श्रद्धावान् प्रेमयुक्तो यो मां भजते स मे मम युक्ततमः अत्यन्तं युक्तः प्रियो मतोऽभिमत इत्यर्थः। अतस्तथाभावेन त्वं योगी भवेति भावः।दास्यात्मकस्वयोगेन भक्तिमार्गभ्रमं हि यः। नाशयामास पार्थस्य स मे कृष्णः प्रसीदतु।।1।।'),
('purushottama-sc:source:7.1','Puruṣottamajī','gita.7.1','sa','commentary','।।7.1।।भगवद्योगयुक्तात्मा युक्तो रूपप्रबोधने। अतः पार्थाय श्रीकृष्णः स्वरूपज्ञानमुक्तवान्।।1।।पूर्वाध्यायान्तेश्रद्धावान् भजते यो मां स मे युक्ततमो मतः 6।47 इति योगसहितस्वभजनकर्त्तुरुत्तमत्वं स्वाभिमतत्वमुक्तं तत्र स्वरूपाज्ञाने भजनं न भवेत् तज्ज्ञानं च योगज्ञानोत्तरभावीति योगस्वरूपमुक्त्वा अथ भजनार्थं स्वरूपज्ञानमाह श्रीभगवानुवाच मय्यासक्तमना इति। हे पार्थ एतच्छ्रवणयोग्य मदाश्रयः मदर्थमेवाऽनन्यशरणः सन् मत्क्रीडार्थं संयोगार्थमाश्रयं कृत्वा योगं युञ्जन् दास्याभ्यासं कुर्वन् असंशयं संशयरहितं यथा स्यात्तथा समग्रं संयोगात्मकं सर्वरससहितं मां यथा ज्ञास्यसि तदिदमग्रे वक्ष्यमाणं ज्ञानस्वरूपं मय्यासक्तमनाः मयि आसक्तं स्वापेक्षारहितं मत्सुखाभिलाषिमनाः शृणु।'),
('purushottama-sc:source:7.2','Puruṣottamajī','gita.7.2','sa','commentary','।।7.2।।ननु योगस्वरूपनिरूपणे पूर्वमपि स्वरूपज्ञानमुक्तमेव पुनरेतज्ज्ञानं किंरूपं इत्याशङ्क्याह ज्ञानं तेऽहमिति। अहं पुरुषोत्तमः ते तव त्वदर्थं ज्ञानं शास्त्रोक्तप्रकारेण मत्स्वरूपविषयं अशेषतः सम्पूर्णं लीलादिसहितं वक्ष्यामि। कीदृशं तत् सविज्ञानं स्वरूपानुभवसहितम्। अनुभवस्वरूपमेवाह इदमिति अनुभूयमानस्वस्वस्पात्मकम्। एतज्ज्ञानान्तरं पुनरन्यज्ज्ञेयं नास्तीत्याह यदिति। यत् स्वस्वरूपानुभवसहितं स्वस्वरूपं ज्ञात्वा इह अस्मिन् मद्भक्तिमार्गे भरतखण्डे अस्मिन्मनुष्यजन्मनि वा ज्ञातव्यं न अवशिष्यते। एतज्ज्ञानेनैव दास्यानुभवो भवतीत्यर्थः।'),
('purushottama-sc:source:7.3','Puruṣottamajī','gita.7.3','sa','commentary','।।7.3।।ज्ञातव्यं कुतो नावशिष्यते इत्यत आह मनुष्याणामिति। पूर्वं तु भगवत्सन्निधानान्निस्सृतानां जीवानां मध्ये मनुष्यत्वं प्राप्तानामेव भजनाधिकारस्तत्प्राप्तिश्च दास्यदानानुग्रहैकसाध्या तत्प्राप्त्यनन्तरं च भावार्थं समर्पितस्य देहस्य तदाप्त्यर्थं लीलया प्राकट्यमतिदुर्लभं तत्रापि भावसेवया प्रीतेन भगवदुक्तस्वस्वरूपज्ञानमतिदुर्लभम्। एतत्सर्वसिद्धिर्यज्ज्ञानेन भवति तज्ज्ञाने न किञ्चिदवशिष्यते तदाह मनुष्याणां सहस्रेषु भजनौपयिकप्राप्तदेहानां सहस्रेषु असङ्ख्यातेषु कश्चित् दुर्लभो मदनुग्रहैकरूपः सिद्धये मत्सिद्धिस्वरूपनिमित्तं यासिद्धिर्द्वितीयस्कन्धे अ.1 उक्ता तदर्थं यतति यत्नवान् भवति। यततामपि यत्नं कुर्वतामपि सिद्धानां मध्ये कश्चित् स्वरमणेच्छादिभावरहितस्तत्स्वरूपात्मकधामरममाणं मां तत्त्वतस्तदनुग्रहैकलभ्यत्वेन वेत्ति जानाति। यत एतज्ज्ञानमतिदुर्लभम्। यज्ज्ञानान्तरं न किञ्चिदवशिष्यते तन्मया त्वदर्थमुच्यत इति भावः।'),
('purushottama-sc:source:7.4','Puruṣottamajī','gita.7.4','sa','commentary','।।7.4।।एवं सावधानतया श्रोतव्यत्वेनार्जुनं बोधयित्वा पूर्वप्रतिज्ञातस्वस्वरूपज्ञानार्थं स्वस्य सर्वकर्त्तृत्वं सर्वस्वरूपत्वं चाह भूमिराप इत्यादिभिः। भूमिः आपः अनलः वायुः खम् एवं पञ्च महाभूतानि। मनः सङ्कल्पादिसाधनम् बुद्धिर्ज्ञानात्मिका अहङ्कारोऽभिमानादिरूपः इति। अनेन प्रकारेण इयं मे अष्टधा प्रकृतिर्माया भिन्ना विभागं प्राप्ता। लौकिककार्यार्थमिति भावः।'),
('purushottama-sc:source:7.5','Puruṣottamajī','gita.7.5','sa','commentary','।।7.5।।तदेवाह अपरेति। इयं अपरा नीचेत्यर्थः। तु पुनः। हे महाबाहो क्रियासमर्थ एतज्ज्ञानयोग्य इतः सकाशादन्यां परामुत्कृष्टां जीवभूतां में प्रकृतिं विद्धि जानीहि। परत्वमेवाह ययेदमिति। यया इदं परिदृश्यमानं जगद्धार्यते ध्रियते पोष्यते च।अत्रायं भावः भगवान् स्वक्रीडार्थं जगत् सृजति तत्र प्रकृत्या स्वशक्त्या क्रीडाधिकरणभूतजगत्सृष्टिं विधाय तद्भोगार्थं क्रीडार्थकया स्वशक्त्या तद्रूपजीवसृष्टिं कृतवान् तया इदं पूर्वकृतं भोगादिरूपेण धार्यते। तस्माल्लौकिकसृष्टौ जीवरूपेण भगवान् भोगं कुर्वन् क्रीडतीति ज्ञानेन तस्यां बन्धो न स्यात्। एतत्स्वरूपज्ञानाद्रसानुकरणज्ञानं स्यादिति भावः। यद्वा या पूर्वमष्टधोक्ता सा अपरा प्रकृतिः शक्तिः क्रीडार्थं शक्त्यंशभूतेति भावः। संयोगविलासे अनेकधा रसोत्पत्त्यर्थमाविर्भूतेत्यर्थः। अतएव भिन्नातद्विलासेच्छया जाता। इतः सकाशादन्या विप्रयोगे तदन्वेषणार्थ पुनर्दास्यरससिद्ध्यर्थमाविर्भूता जीवभूता दास्यरूपा सा मच्छक्तिस्तां परां केवलमदंशामुत्कृष्टां जानीहि। उत्कृष्टरूपतामेवाह यया इदं जडात्मकं जगद्धार्यते जीवप्राकट्यानन्तरं तद्भावेन सर्वं क्रीडौपयिकत्वेन पोष्यत इति भावः।'),
('purushottama-sc:source:7.6','Puruṣottamajī','gita.7.6','sa','commentary','।।7.6।।एतज्ज्ञानेन किं स्यादित्यत आह एतदिति। सर्वाणि भूतानि स्थावरजङ्गमात्मकानि एतद्योनीनि एते प्रकृती योनी कारणरूपे येषां तथा तदुपधारय उप समीपे हृदये पोषय। एतद्योनिज्ञानेन मत्क्रीडौपयिकत्वं सर्वेषु भविष्यतीति भावः। यतस्तद्योनीनि सर्वाणि ते च मदंशे अतः कृत्स्नस्य सम्पूर्णस्य जगतोऽहं प्रभवः प्रकर्षेण भवत्यस्मादिति प्रभव उत्पत्तिस्थानं मूलकारणमित्यर्थः। तथा प्रकर्षेण लीयते अनेनेति लयस्थानं प्रलयकर्ताऽप्यहमेवेत्यर्थः।'),
('purushottama-sc:source:7.7','Puruṣottamajī','gita.7.7','sa','commentary','।।7.7।।यत उत्पत्तिप्रलयकारणमहमेवातो हे धनञ्जय मद्विभूतिरूप एतज्ज्ञानयोग्य मत्तः परतरं श्रेष्ठं जगत् जगति वा किञ्चित् अहं स इति भेदेनापि अन्यन्नास्ति एवमुत्पत्तिप्रलयकारणेन स्वत उत्तमत्वाभावमन्यस्योक्त्वा स्थितिहेतुत्वेनाऽपि तथा त्वमेवेति स्वस्य स्थितिहेतुत्वमाह मयीति। इदं सर्वं जगत् मयि प्रोतं ग्रथितं मदाश्रयत्वेन तिष्ठतीत्यर्थः। अत्र दृष्टान्तमाह सूत्रे प्रोता मणिगणा इव। अत्रायं भावः मणिगणाः क्रीडास्थजीवाधिदैविकरूपा यथा मयि तिष्ठन्ति तथेदं जगदप्याधिदैविकं मयि तिष्ठतीति भावः।'),
('purushottama-sc:source:7.8','Puruṣottamajī','gita.7.8','sa','commentary','।।7.8।।आधिदैविकरूपेण जगतः स्थितिं स्वस्मिन्नाह रसोऽहमिति पञ्चभिः। हे कौन्तेय मद्भक्त एतज्ज्ञानयोग्य अहमप्सु जलेषु रसरूपः। जले शैत्याद्याह्लादकानन्दादिगुणो मद्रूपस्थरसांशसम्बन्धादाविर्भवतीत्यर्थः। तथा शशिसूर्ययोः प्रभा प्रकाशकतेजोरूपोऽस्मि मद्रूपस्थसंयोगविप्रयोगानन्दरूपतेजस्सम्बन्धेनोभयोस्तद्रूपानन्दप्रकाशकत्वं भवतीति भावः। सर्ववेदेषु शब्दरसात्मके प्रणवे च ओङ्कारत्रिरूपाक्षररूपोऽस्मि शक्तिद्वयसहितपुरुषरूपोऽस्मि तत्सम्बन्धेनैव वेदशब्देषु रसरूपता अत एव श्रुतीनां भावोत्पत्तिः। खे आकाशे शब्दरूपोऽस्मि।अत्रायं भावः आकाशस्वरूपात्मकभगवद्वेणुसम्बन्धेन शब्देष्वानन्दरूपत्वं भवति। नृषु मनुष्येषु पौरुषांशत्वम् पुरुषांशानामेव भजनयोग्यतेति तत्सम्बन्धेनैव सर्वमनुष्याणामुत्तमत्वमुच्यत इति भावः।'),
('purushottama-sc:source:7.9','Puruṣottamajī','gita.7.9','sa','commentary','।।7.9।।च पुनः पृथिव्यां पुण्यो गन्धोऽस्मि येन गन्धेन पुलिन्द्यादिषु भगवद्रसोत्पत्तिः स्यात् स पुण्यरूपो गन्धस्तत्सम्बन्धेन पृथिव्या गन्धवत्त्वं तद्वत्त्वेनात्रत्यामोदेनाऽऽह्लादकवृन्दावनाधारत्वादिकं चेति भावः। तथा विभावसौ अग्नौ यत्तेजस्तापकत्वं कान्तिस्तदहमस्मि।अत्रायं भावः विप्रयोगतापरूपाग्नेर्ममांशसम्बन्धेनाग्नौ तापस्तेन सर्वपरिपाकं कृत्वा सर्वस्यान्नादेर्मद्भोग्यतासम्पादकत्वं भवतीति भावः। सर्वभूतेषु जीवनं प्राणधारणम् अन्यथा भगवद्वियुक्तानां तेषां तदाधारतां विना कथं स्थितिः स्यात्। तपस्विषु तापप्रयत्नवत्सु तपःक्लेशानन्दरूपोऽस्मि। अन्यथा तदभावे सुखादित्यागेन दुःखे को वा प्रवर्तते।'),
('purushottama-sc:source:7.10','Puruṣottamajī','gita.7.10','sa','commentary','।।7.10।।किञ्चबीजमिति। हे पार्थ मत्कृपाश्रय सर्वभूतानां सनातनं नित्यं बीजं मां विद्धि।अत्रायं भावः पुरुषोत्तमलीलास्थजीवास्तदात्मका एव तदंशा एवात्र प्रकटीकृताः अन्यथा लीलोपयोगिनो न भवेयुः तेन तद्बीजजाता एतेऽपि सेवायोग्या इति सर्वेषां बीजं मां विद्धि तज्ज्ञानं स्वरूपज्ञानप्रयोजकमिति भावः। तथैव बुद्धिमतां मत्स्वरूपज्ञानकुशलप्रयत्नवतां बुद्धिः कौशलमस्मि। तेजस्विनां दुराधर्षिणां तेजो दुराधर्षता अहमस्मि।'),
('purushottama-sc:source:7.11','Puruṣottamajī','gita.7.11','sa','commentary','।।7.11।।किञ्च बलवतां मद्वशीकरणलक्षणवतां बलं वशीकरणलक्षणमहम्। चकारेण तद्रूपोऽपि। कीदृशं बलं कामरागविवर्जितं वशीकृते मयि स्वाभिलाषत्वं स्वरञ्जनादिवर्जनम् किन्तु मदभिलाषादिभावः। तथा हे भरतर्षभ सत्कुलोत्पन्न तथा कामभावयोग्य धर्माविरुद्धः धर्मेण अविरुद्धो भूतेषु कामोऽस्मि। अत्रायं भावः लौकिककामस्तु धर्मविरुद्धोऽस्ति यतोऽयं रसः स्वाऽविवाहितायामेव भवति प्रकटः सर्वधर्मविरुद्ध एव। अलौकिकस्तु रसात्मको धर्मरूप इति भावः।'),
('purushottama-sc:source:7.12','Puruṣottamajī','gita.7.12','sa','commentary','।।7.12।।किञ्च ये चैवेति। ये च पुनः सात्त्विका एव भावा मत्सम्बन्धिदर्शनेन रोमाञ्चादयः राजसात्मकविक्षेपादयः न पुनस्तामसा विप्रयोगस्वरूपस्मरणे मूर्छाभ्रमादयस्ते सर्व एव। इति अमुना प्रकारेण तान् मत्त एव विद्धि जानीहि। तेषु तत्सामर्थ्येन अहं तत्प्रकारेण न प्रकटो भवामि किन्तु ते मयि प्रकटीभवन्तीत्यर्थः। अत्रायं भावः एते गुणा रसार्थं मया प्रकटिताः स्वरसात्मकगुणसाफल्याय मत्सम्बन्धेन स्वयमुद्बुद्धरसाः सन्तः सेवां कुर्वन्तीति ते मयि सन्ति नत्वहं जीववत्तेषूत्पन्नेषु रसयुक्तो भवामीति भावः।'),
('purushottama-sc:source:7.13','Puruṣottamajī','gita.7.13','sa','commentary','।।7.13।।एवं लीलया रसार्थं प्रकटितान् गुणान् मयि दृष्ट्वा सर्वे मोहं प्राप्य मां न जानन्तीत्याह त्रिभिरिति। एभिः परिदृश्यमानैर्मत्सम्बन्धेन स्नेहलीलारसतः प्रकटभूतैस्त्रिभिः सात्त्विकादिभिर्गुणमयैर्मद्गुणात्मकैर्भावैर्भावनात्मकैरिदं परिदृश्यमानमधिकरणात्मकमाध्यात्मिकं जगत् मामेभ्यः पूर्वोक्तभावेभ्यः परमुत्कृष्टं केवलं रसात्मकमत एवाव्ययं विप्रयोगादिभावेषु न्यूनतादिरहितं नाभिजानाति।'),
('purushottama-sc:source:7.14','Puruṣottamajī','gita.7.14','sa','commentary','।।7.14।।नन्वेवं चेदस्माभिः कथं ज्ञातव्य इत्याकाङ्क्षायामाह दैवीति। एषा मम गुणमयी मद्गुणात्मिका दैवी केषुचिद्भाग्यवत्सु रसदानेच्छया प्रकटीकृतक्रीडात्मिका माया अलौकिकसामर्थ्येनान्यथाभावोत्पादनसमर्था। अतएव दुरत्यया दुःखेनापि जेतुमशक्या। एतादृशीमपि ये मामेव केवलमनन्यभावेन पुरुषोत्तमं प्रपद्यन्ते प्रपन्ना भवन्ति ते एतां मायां मोहनात्मिकां तरन्ति। मां जानन्तीत्यर्थः।मामेव ये इत्यत्रैवकारेणमाम् इत्येकवचनेन च भावात्मकतया केवलं पुरुषोत्तमत्वेन स्वभजनं दास्यभावेनोक्तं न तु लीलादिसहितदर्शनेन स्वरमणेच्छादिकतया। एतेन त्वमपि तथा प्रपन्नो भवेत्युक्तम्।'),
('purushottama-sc:source:7.15','Puruṣottamajī','gita.7.15','sa','commentary','।।7.15।।नन्वेवं सति कथं न सर्वे प्रपन्ना भवन्ति इत्याह न मामिति। मां दुष्कृतिनो दुष्टकर्मकर्त्तारः पापाः मूढाः पशुवद्विवेकरहिताः नराधमाः नरेषु अधमाः केवलं वैचित्र्यार्थं जगत्पूरणार्थं सृष्टाः मां न प्रपद्यन्ते। ननूपदेशादिना कथं न पापकर्मादित्यागेन प्रपद्यन्ते इत्यत आह माययेति। मायया अपहृतं गुरूपदेशादिजनितं ज्ञानं येषाम्। मायेतिपदेन ज्ञाननाशनसामर्थ्यमुक्तम्। अत एव देवीपुराणेज्ञानिनामपि चेतांसि देवी भगवती हि सा। बलादाकृष्य मोहाय महामाया प्रयच्छति मा.पु.78।42सप्तश.1।55 इत्युक्तम्। ननु भगवत्प्रपत्तीच्छूनां कथं न भगवान् रक्षतीत्यत आह आसुरं भावमाश्रिताः मद्विरोध्यासुरसङ्गेन तद्भावं प्राप्ताः अतो मया न रक्ष्यन्त इति भावः। एतेन दुस्सङ्गराहित्येन प्रपत्तिः कार्येत्युपदिष्टम्। अतएव दुस्सङ्गनिषधः श्रीभागवतेन तथाऽस्य भवेन्मोहः 3।31।35सङ्गस्तेव्वपि ते प्रार्थ्यः 3।25।24 इत्यादिभिरुक्तः।');
INSERT INTO commentary_fts (unit_id,author,canonical_ref,language,content_type,content) VALUES
('purushottama-sc:source:7.16','Puruṣottamajī','gita.7.16','sa','commentary','।।7.16।।एवं दुष्टकर्मकर्त्तारो न भजन्तीत्युक्तं तर्हि के भजन्ति इत्याकाङ्क्षायामाह चतुर्विधा इति। हे अर्जुन सावधानतया श्रोतव्यत्वेन सम्बोध्य सुकृतिनः पूर्वजन्मसञ्चितपुण्यराशयो जनाः मां भजन्ति। अन्यथा भजने प्रवृत्तिरेव न स्यात्। अतएवनराणां क्षीणपापानां कृष्णे भक्तिः प्रजायते इति श्रीभागवते उक्तम्। ते च चतुर्विधाः। चतुर्विधत्वं प्रकटयति आर्त इति। आर्तः संसारक्लेशादियुक्तः तन्निवृत्त्यर्थं धर्मरूपेण मां भजति। जिज्ञासुः कामात्मकमत्स्वरूपज्ञानेच्छुः कामरूपेण मां भजति। अर्थार्थी मत्सेवौपयिकसाधनसम्पत्त्यर्थरूपेण मां भजति। च पुनः। ज्ञानी शास्त्रार्थज्ञानवान्न मोक्षरूपेण मां भजति। भरतर्षभ इति सम्बोधनं सत्कुलोत्पन्नानामेव भजनप्रवृत्तिर्भवतीति ज्ञापनार्थम्।'),
('purushottama-sc:source:7.17','Puruṣottamajī','gita.7.17','sa','commentary','।।7.17।।एवं चतुर्विधानुक्चैतेषु ज्ञानी मोक्षार्थं भजनकर्त्ता उत्तम इत्याह तेषामिति। तेषां पूर्वोक्तचतुर्विधानां मध्ये ज्ञानी नित्ययुक्तः नित्यं मया युक्त इत्यर्थः। एतेभ्यश्चतुर्विधेभ्योऽपि एकभक्तिरनन्यत्वेनैकान्तभजनकृत् दासवत् स विशिष्यते उत्तमत्वेनेत्यर्थः। तस्य विशेष्यधर्ममाह प्रिय इति। हीति निश्चयेन ज्ञानिनः सकाशात् अत्यर्थं सर्वभावे अहमेव तस्य प्रियः। अतएव श्रीभागवते भगवद्वाक्यंमदन्यत्ते न जानन्ति नाहं तेभ्यो मनागपि इति।'),
('purushottama-sc:source:7.18','Puruṣottamajī','gita.7.18','sa','commentary','।।7.18।।नन्वेषु चतुर्विधेषु ज्ञानी उत्तम उक्तस्ततोऽपि भक्तस्तदा पूर्वोक्तानां किं फलं इत्यपेक्षायामाह उदारा इति। एते सर्व एव स्वार्थपरित्यागेन मदर्थधर्मादित्रयभजनकर्त्तारः उदाराः मोक्षाधिकारिणः। तु पुनः ज्ञानी आत्मैव मदात्मक एव मुक्त एवेत्यर्थ इति मे मतम्। हीति निश्चयेन। अनन्यमनसा सर्वत्यागेन अनुत्तमां न विद्यते उत्तमा यस्यास्तादृशीं गतिं प्राप्य स्थानं ज्ञात्वा मामेवास्थितः स युक्तात्मा मत्संयोगयुक्तो दास्यादिभावेनेत्यर्थः। स उत्तम इति भावः।'),
('purushottama-sc:source:7.19','Puruṣottamajī','gita.7.19','sa','commentary','।।7.19।।ये पूर्वोक्तास्ते कथं मोक्षमनुभवन्ति इत्याकाङ्क्षायामाह बहूनामिति। बहूनां जन्मनां धर्मादित्रययुक्तानामन्ते अन्तिमजन्मनि ज्ञानवान् भवति। ततो मां प्रपद्यते मुक्तो भवतीत्यर्थः। यस्तु भक्त उक्तः स तु दुर्लभ इत्याह वासुदेव इति। सर्वमैहिकं पारलौकिकं च वासुदेवः स महात्मा महान् मदर्थमेव अहमेव वा आत्मा तादृशः स दुर्लभोऽप्राप्य इत्यर्थः। यद्वा दुःखेन क्लेशेन भगवानिव लभ्य इति भावः।'),
('purushottama-sc:source:7.20','Puruṣottamajī','gita.7.20','sa','commentary','।।7.20।।स कथं दुर्लभः इत्यत आह कामैरिति। तैस्तैः कामैः पूर्वोक्तैःआर्तः 7।16 इत्यादित्रिरूपैर्हृतज्ञानाः सन्तोऽन्यदेवताः क्षुद्राः शिवादयो भूतप्रेतादयश्च स्वया प्रकृत्या कृत्वा तं तं नियमं देवताराधने उपवासादिलक्षणमास्थाय प्रपद्यन्ते। अत्रायमर्थः कामनार्थं मत्सेवायां प्रवृत्ताः न तु मोक्षार्थं भक्त्यर्थं वा अहं तु मोक्षभक्त्यननुरूपं कामितफलं न ददामि तत्फलमननुभूय तैः कामैः हृतं मत्स्वरूपज्ञानं येषां तादृशाः सन्तः स्वया प्रकृत्या नियताः प्रकृत्यंशत्वाच्छीघ्रं तत्फलदा अन्यदेवता भजन्ति। अतएवयो यदंशः स तं भजेत् इत्युक्तम्।'),
('purushottama-sc:source:7.21','Puruṣottamajī','gita.7.21','sa','commentary','।।7.21।।अतोऽहमपि तान् स्वरूपरसदानायोग्यांस्तद्देवताभजने दृढान् करोमीत्याह यो य इति। यो यो भक्तो यां यां तनुं यां यां देवतामूर्तिं श्रद्धया स्वकामसिद्ध्यर्थं शुद्धान्तःकरणेन अर्चितुमिच्छति तस्य भक्तस्य तामेव श्रद्धामचलां शास्त्रज्ञानादिना वा चालयितुमयोग्यामहमेव विदधामि करोमि पोषयामि चेत्यर्थः।'),
('purushottama-sc:source:7.22','Puruṣottamajī','gita.7.22','sa','commentary','।।7.22।।ततः स मत्कृतश्रद्धया तस्याऽऽराधनं करोतीत्याह स तयेति। स तया मत्कृतया श्रद्धया युक्तस्तस्या मूर्तेराराधनमीहते करोति। ततः श्रद्धातः स्वशुद्धान्तःकरणतस्तान् कामान् स्वमनोरथरूपान् मयैव विहितान् निर्मितान् अन्यया मदाज्ञां विना देवादीनां न सामर्थ्यम् अतो मयैव निश्चयेन विहिताँल्लभते प्राप्नोतीत्यर्थः।'),
('purushottama-sc:source:7.23','Puruṣottamajī','gita.7.23','sa','commentary','।।7.23।।तर्हि त्वन्निर्मितफलाप्त्या चोत्तमत्वमेव तत्फलस्य कथं न इत्यत आह अन्तवत्त्विति। तु पुनः मन्निर्मितमपि फलं तेषामल्पमतिमतां भक्तिं विहाय कामपरत्वात् अन्तवत् विनाशयुक्तं भवतीत्यर्थः। तच्छब्देन तद्बुद्ध्यनुसारेण मया तत्फलं विधीयत इति व्यज्यते। ननु देवा अपि त्वदंशास्तद्भजने कथं नोत्तमफलम् इत्यत आह देवानिति देवयजः৷৷৷৷৷৷৷৷৷৷ पूर्वोक्तप्रकारेण स्वकामितफलाप्त्यर्थं देवभजनकर्त्तारः। अथवा देवत्वेन तद्भजनकर्त्तारः न तु मदंशत्वेन स्फुरितस्तमानाः৷৷৷৷৷৷৷৷৷৷৷৷৷৷. अतो देवान् यान्ति मत्सायुज्यकामाभावे प्राप्नुवन्ति। कामनायां तु तदेव प्राप्नुवन्तीत्यर्थः। अन्यदेवेषु देवत्वेन भजनकर्त्तारस्तत्सायुज्यमेव प्राप्नुवन्ति। कामनायां तु तदपि न प्राप्नुवन्त्यतः कामनयाऽपि मद्भजनमुत्तममित्याह मद्भक्ता इति। मद्भक्ताः मद्भजनकर्तारो मामपि यान्ति। कामनयाऽपि प्रवृत्ताः पूर्वोक्तप्रकारेण। मामपि प्राप्नुवन्ति। अतएवउदाराः सर्व एवैते 7।18 इति पूर्वमुक्तम्। अतोऽग्रे तेषां मोक्षः। अक्षरसायुज्यमपि प्राप्नुवन्ति। अतएव हरिवंशेअपत्यं द्रविणं दारा हारा हर्म्यं हया गजाः। सुखानि स्वर्गमोक्षौ च न दूरे हरिभक्तितः।।इति। इदमेवापिशब्देन व्यज्यते।'),
('purushottama-sc:source:7.24','Puruṣottamajī','gita.7.24','sa','commentary','।।7.24।।तर्हि कथं न सर्वे त्वामेव भजन्ति इत्यत आह अव्यक्तमिति। अबुद्धयः कामहृतज्ञाना अव्यक्तं न विद्यते व्यक्तो लौकिकवत् प्रकटो व्यवहारो यस्य व्यक्तिर्जात्यादिर्वा यस्य तादृशं पुरुषोत्तमं व्यक्तिमापन्नं मनुष्यादिभावेन जगति प्रकटं लौकिकत्वेन अन्यदेवसमं मनुष्यादिसमं वा मन्यन्ते। कुतः इत्याकाङ्क्षायामाह परमिति। मम पुरुषोत्तमस्य अव्ययं नाशरहितं लीलात्मकं केषुचित्। भाग्यवत्सु प्रकटीभूय तद्रसपोषार्थं तत्समानाकारेण लीलारूपमजानन्तः। किञ्च अनुत्तमं न विद्यते उत्तमो यस्मात्तादृशं परं भावंपुरुषोत्तमात्मकमजानन्तो मां तथा मन्यन्ते। अतः स्वकामितफलक्षिप्रप्रसादार्थमन्यदेवता एव भजन्ति न तु मामित्यर्थः।'),
('purushottama-sc:source:7.25','Puruṣottamajī','gita.7.25','sa','commentary','।।7.25।।ननु मनुष्या विवेकादिसहिताः कथं न त्वां जानन्ति इत्यत आह नाहमिति। अहं सर्वस्य साधारणस्य प्रकाशः प्रकटो न भवामि किन्तु कस्यचिद्भक्तस्यैव। तत्र हेतुमाह योगमायासमावृत इति। योगार्थमेव या माया अन्तरङ्गा दासीभूता शक्तिस्तया आवृतो रसार्थमाच्छन्नः। अतो मूढो भक्त्यालोचनादिज्ञानशून्योऽयं परिदृश्य৷৷৷৷৷৷৷৷৷৷৷৷৷৷৷৷मानो मां पश्यन्नपि स्वरूपज्ञानरहितो लोको बहिर्दृष्टिर्मामजं जन्मरहितं लीलया प्रकटमव्ययं नित्यं नाभिजानाति अभितः सर्वभावेन न जानाति।'),
('purushottama-sc:source:7.26','Puruṣottamajī','gita.7.26','sa','commentary','।।7.26।।ननु याँस्त्वं स्वसेवार्थं प्रकटीकृतान् पुनः स्वकीयत्वेन न जानासि तदा माया तान् व्यामोहयति उतान्यथा वा इत्याशङ्क्याह वेदाहमिति। अहं समतीतानि सेवामकृत्वा नष्टानि वर्त्तमानानि साम्प्रतं सेवां कुर्वाणानि भविष्याणि सेवार्थं प्रकटानि यानि भूतानि मत्सत्तया प्रकटानि स्थावरजङ्गमानि त्रिकालवर्तीनि मदीयत्वेन वेद जानामि। तु पुनः मज्ज्ञानानन्तरमपि कश्चन त्रिकालवर्तिषु मां प्रभुत्वेन न वेद। न जानातीत्यर्थः।'),
('purushottama-sc:source:7.27','Puruṣottamajī','gita.7.27','sa','commentary','।।7.27।।तर्हि त्वज्ज्ञाने तान् माया कथं मोहयति इत्यत आह इच्छेति। सर्गे सृष्टावुत्पत्त्यनन्तरम् इच्छा स्वेष्टवस्तुषु द्वेषस्तद्विपरीतवस्तुषु ताभ्यां सम्यक् प्रकारेणोत्थितो यो द्वन्द्वमोहः सुखदुःखरूपस्तेन हे भारत भक्तवंशज सर्वभूतानि सम्मोहं यान्ति प्राप्नुवन्ति। भारतेति सम्बोधनेन भरतवत् कस्यचिदेव भक्तस्य न मोहो भवतीति व्यञ्जितम्। अत्रायं भावः मत्क्रीडार्थं सेवार्थं वा ये सृष्टास्तैर्मत्संयोगवियोगसुखदुःखविचार एव कर्तव्यः न तु स्वस्वविचारकाणां भगवत्कार्यानुपयुक्तत्वान्माया मोहयतीति भावः।'),
('purushottama-sc:source:7.28','Puruṣottamajī','gita.7.28','sa','commentary','।।7.28।।ननु ये मोहयुक्तास्तन्मध्ये तत्सङ्गिन एव केचन पूर्वमभजन्तः पश्चात् त्वद्भजनप्रवृत्ताः कथं भवन्ति इत्यत आह येषामिति। येषां दुर्लभानां भाग्यवतां पुण्यकर्मणां मद्दर्शनादिना पुण्याचरणशीलानां महत्सु विनयादियुक्तानाम्। तु पुनः जनादिक्लेशयुक्तानां पापं मत्स्वरूपज्ञानप्रतिबन्धकं अन्तभावं गतं प्राप्तं नष्टमिति यावत्। ते द्वन्द्वमोहनिर्मुक्ताः स्वसुखदुःखादिमोहनिर्मुक्ताः दृढव्रताः द़ृढसङ्कल्पाः मदेकनिष्ठाः मां भजन्ते। अत्रायं भावः पूर्वजन्मकृतं यत्किञ्चित् पुण्यकर्म तेन जन्मान्तरे प्रवृद्धमाने वाऽनेकजन्मनि वयसः परिपाके पुण्योपचितमरणभयेन तन्निवृत्त्यर्थं मद्भजनप्रवृत्ता भवन्ति। अतएवजन्मान्तरसहस्रेषु तपोज्ञानसमाधिभिः। नराणां क्षीणपापानां कृष्णे भक्तिः प्रजायते पां.गी.40 इति भागवतैरुक्तम्।'),
('purushottama-sc:source:7.29','Puruṣottamajī','gita.7.29','sa','commentary','।।7.29।।एवं भजनप्रवृत्ता मां जानन्तीत्याह जरामरणेति। जरामरणयोः भगवद्भजनप्रतिबन्धकभगवद्विस्मरणरूपयोर्मोक्षाय निवारणार्थं मामाश्रित्य अनन्यैकचित्तेन ये यतन्ति भजनार्थं यत्नं कुर्वन्ति भजन्ति वा ते तत् परं ब्रह्म पुरुषोत्तमात्मकं विदुः जानन्ति। कृत्स्नं पूर्णमध्यात्मं भजनौपयिकं साधनरूपं विदुः। च पुनः कर्म सेवारूपं तत्साधनात्मकमखिलं भावादियुक्तं जानन्तीत्यर्थः।'),
('purushottama-sc:source:7.30','Puruṣottamajī','gita.7.30','sa','commentary','।।7.30।।एवं ज्ञानस्य फलमाह साधिभूताधिदेव मेति। साधिभूताधिदैवम् अधिभूतेन अधिकरणात्मकेन अधिदेवेन मूलरूपेण सह अधियज्ञेन अंशात्मककर्मरूपेण च सहितं ये मां विदुस्ते युक्तचेतसः युक्तं तन्निष्ठं चेतो येषां तादृशा भवन्ति मां प्राप्नुवन्तीत्यर्थः। च पुनः प्रयाणकाले मरणसमयेऽपि भ्रमादिरहितास्ते मां विदुः जानन्ति मरणकाले स्वज्ञानोक्त्याअन्ते या मतिः सा गतिः [ ] इति वाक्योक्तरीत्या प्राप्नुवन्तीति व्यञ्जितम्।भक्तानामेव श्रीकृष्णज्ञानविज्ञानयोग्यता। अतोऽत्र ज्ञानविज्ञानयोगं हरिरुवाच हि।।7।।'),
('purushottama-sc:source:8.1','Puruṣottamajī','gita.8.1','sa','commentary','।।8.1।।पूर्वोक्तब्रह्मकर्मादिरूपजिज्ञासुरर्जुनः। पृष्टवान् स्पष्टमेतस्य कृष्ण उत्तरमुक्तवान्।।1।।पूर्वाध्यायान्ते भगवताते ब्रह्म [7।29] इत्यादिना समपदार्थज्ञानमुक्तं भक्तानाम् तत्स्वरूपजिज्ञासुरर्जुनः प्रभुं विज्ञापयामास -- अर्जुन उवाच किं तद्ब्रह्मेति द्वयेन। हे पुरुषोत्तम तद्ब्रह्म यदुक्तं तत्किम् अध्यात्मं किं कर्म किं च पुनः अधिभूतं किं प्रोक्तं च पुनः अधिदैवं किमुच्यते अधियज्ञः यज्ञाधिष्ठाता फलदाता कः। अत्र उक्तप्रकारेषु कथं केन प्रकारेण नियतात्मभिरनन्यैकपरिचित्तैर्ज्ञेयोऽसि। हे मधुसूदन सर्वानिष्टनिवर्तक अस्मिन् देहे प्रयाणकाले अन्तकाले कथं केन प्रकारेण ज्ञेयोऽसि। अत्रायं भावः -- पुरुषोत्तमेति सम्बोधनेन त्वमेव पुरुषोत्तमः त्वत्तः पराभावात्। कथं तद्ब्रह्मेत्युक्तम् आधिदैविकं तु त्वत्स्वरूपमेव अतस्त्वत्तोऽन्याधिदैवं किम् अध्यात्मादयस्तु৷৷৷৷৷৷৷৷৷৷৷৷৷৷৷৷. हीना एव तेषां ज्ञानं किं प्रयोजनकम् सेवा च कथं कार्या इत्यादिव्यञ्जितम्। मधुसूदनेति सम्बोधनेन त्वदीयानां मरणादिभयाभावे तत्समये त्वं कथं स्वज्ञानमुक्तवानिति ज्ञापितमिति भावः।'),
('purushottama-sc:source:8.2','Puruṣottamajī','gita.8.2','sa','commentary','।। 8.2 पूर्वोक्तब्रह्मकर्मादिरूपजिज्ञासुरर्जुनः। पृष्टवान् स्पष्टमेतस्य कृष्ण उत्तरमुक्तवान्।।1।।पूर्वाध्यायान्ते भगवताते ब्रह्म [7।29] इत्यादिना समपदार्थज्ञानमुक्तं भक्तानाम् तत्स्वरूपजिज्ञासुरर्जुनः प्रभुं विज्ञापयामास -- अर्जुन उवाच किं तद्ब्रह्मेति द्वयेन। हे पुरुषोत्तम तद्ब्रह्म यदुक्तं तत्किम् अध्यात्मं किं कर्म किं च पुनः अधिभूतं किं प्रोक्तं च पुनः अधिदैवं किमुच्यते अधियज्ञः यज्ञाधिष्ठाता फलदाता कः। अत्र उक्तप्रकारेषु कथं केन प्रकारेण नियतात्मभिरनन्यैकपरिचित्तैर्ज्ञेयोऽसि। हे मधुसूदन सर्वानिष्टनिवर्तक अस्मिन् देहे प्रयाणकाले अन्तकाले कथं केन प्रकारेण ज्ञेयोऽसि। अत्रायं भावः -- पुरुषोत्तमेति सम्बोधनेन त्वमेव पुरुषोत्तमः त्वत्तः पराभावात्। कथं तद्ब्रह्मेत्युक्तम् आधिदैविकं तु त्वत्स्वरूपमेव अतस्त्वत्तोऽन्याधिदैवं किम् अध्यात्मादयस्तु৷৷৷৷৷৷৷৷৷৷৷৷৷৷৷৷. हीना एव तेषां ज्ञानं किं प्रयोजनकम् सेवा च कथं कार्या इत्यादिव्यञ्जितम्। मधुसूदनेति सम्बोधनेन त्वदीयानां मरणादिभयाभावे तत्समये त्वं कथं स्वज्ञानमुक्तवानिति ज्ञापितमिति भावः।'),
('purushottama-sc:source:8.3','Puruṣottamajī','gita.8.3','sa','commentary','।।8.3।।एतत्प्रश्नोत्तरं साभिप्रायज्ञानार्थं श्रीभगवानुवाच -- अक्षरमिति त्रयेण। न क्षरति न चलतीत्यक्षरं सदैकरसरूपं पुरुषोत्तमचरणात्मकं भक्तहृदयादचलं गृहात्मकं वा स्थिरं तत्। परमं परः पुरुषोत्तमो मीयत अस्मिन्निति परमं ब्रह्म बृहत् व्यापकं च। स्वभावः स्वस्य भगवतो दास्यादिसेवासिद्ध्यर्थं जीवरूपेण भवनम्। अध्यात्मम् आत्मानमविकृतं सेवायोग्यं देहमधिकृत्य तदनुभवे वर्त्तमानो जीवभावोऽध्यात्मशब्देनोच्यत इत्यर्थः। भूतानां जीवानां भावस्य भगवद्रसरूपस्योद्भवकरः प्रकटकारको यो विसर्गो भगवदथद्रव्यादिविनियोगेन सेवारूपः स कर्मसंज्ञितः क्रियारूपः कर्मशब्दवाच्य इत्यर्थः।'),
('purushottama-sc:source:8.4','Puruṣottamajī','gita.8.4','sa','commentary','।।8.4।।एवं ब्रह्माध्यात्मकर्मोत्तराण्युक्त्वाऽधिभूताद्युत्तराण्याह -- अधिभूतमिति। क्षरो भावो विनश्वरो देहो भगवद्विप्रयोगतापाधिक्येन नाशभावयुक्तोऽधिभूतं जीवमात्रमधिकृत्य भवतीति अधिभूतं दास्यार्थमाविर्भावितस्वांशे विप्रयोगतापार्थं प्रकटीक्रियत इति तथोच्यत इति भावः। च पुनः। पुरुषो मम जीवहृदि पुरुषत्वेन रसात्मको भावः स अधिदैवः तं क्रीडात्मकभावमधिकृत्य भवतीति सर्वमूलरूप इति तथोच्यत इति भावः। किञ्च हे देहभृतां वर मत्सेवौपयिकसामर्थ्ययुक्त अत्र जगति देहे देहनिमित्तं सेवौपयिकोपचयार्थं अधियज्ञः यज्ञादिकर्मात्मकस्तत्प्रवर्तकश्चेत्यर्थः।'),
('purushottama-sc:source:8.5','Puruṣottamajī','gita.8.5','sa','commentary','।।8.5।।प्रयाणकाले च कथं ज्ञेयोऽसि इत्यस्योत्तरमाह -- अन्तकाल इति। अन्तकाले एतद्देहावसानसमये वा अन्तरूपस्य अन्तिमजन्मनो देहस्य काले नाशसमये प्राप्ते सति मामेव स्मरन् यः प्रयाति देहं मुञ्चति स कलेवरं मृतदेहं भजनायोग्यं मुक्त्वा मद्भावं सेवौपयिकस्वरूपं याति प्राप्नोति। अत्रार्थे संशयो नास्ति न वर्त्तते। अतः सन्देहो न कर्त्तव्य इत्यर्थः। चकारेण शुद्धावस्थादिकं न विचारणीयमिति ज्ञापितम्। एवकारेण कामनयाऽन्यत् किञ्चिदपि फलत्वेन न स्मरणीयमिति ज्ञापितम्।'),
('purushottama-sc:source:8.6','Puruṣottamajī','gita.8.6','sa','commentary','।।8.6।।अन्यास्मरणे हेतुमाह -- यं यमिति। हे कौन्तेय तत्स्मरणायोग्य यं यं देवतान्तरमपि वा स्वमनोभिलषितजीवस्वरूपं स्मरन् अन्ते कलेवरं त्यजति स तमेव तत्सारूप्यमेति प्राप्नोतीत्यर्थः। अपीति निश्चयार्थे वा। अत एव भरतस्य अन्ते मृगस्मरणे मृगशरीराप्तिः अयमेवार्थोऽपिशब्देन द्योतितः। यतोऽन्तकाले यत्स्मरणेन म्रियते तमेव प्राप्नोत्यतः साधारण्येनापि मत्स्मरणेन मरणे मत्प्राप्तौ न सन्देह इत्यर्थः। नन्वन्ते वैकल्ये देवतान्तरस्मरणं स्वाभिलषितस्मरणं वा कथं स्यात् इत्यत आह -- सदा तद्भावभावितः निरन्तरं,तद्भावेन भावितो यो भवति स तमेवान्ते स्मरति।'),
('purushottama-sc:source:8.7','Puruṣottamajī','gita.8.7','sa','commentary','।।8.7।।अतः सदा त्वं मद्भावयुक्तो भवेत्याह -- तस्मादिति। तस्मात् पूर्वोक्तात् कारणात् सर्वेषु कालेषु लौकिकवैदिकक्रियायोग्येषु मय्यर्पितं मनश्चाञ्चल्यदोषनिवारणार्थं बुद्धिरन्यत्र व्यवसायदोषनिवारणार्थं येन तादृशः सन् मामनुस्मर चिन्तय। अनुस्मरणेन मया कृपया सर्वदा त्वं स्मर्यसे तस्मात्सर्वदा मत्स्मरणं फलरूपं भविष्यतीति भावो व्यञ्जितः। युद्ध्य च युध्यस्व सद्भावनया मदाज्ञया युद्धमपि कुर्वित्यर्थः। एवमनुस्मरणेन असंशयः सन्देहरहितः सन् मामेव एष्यसीत्यर्थः। असंशयः अत्र च सन्देहो नास्तीति भावः।'),
('purushottama-sc:source:8.8','Puruṣottamajī','gita.8.8','sa','commentary','।।8.8।।अथ तव तु मत्प्राप्तिर्निस्सन्दिग्धा साक्षान्मयोपदिष्टत्वात् किन्तु मदाज्ञाव्यतिरेकेणापि येऽनन्यभावेन स्मरन्ति तेऽपि मां प्राप्नुवन्तीत्याह -- अभ्यासेति। हे पार्थ मद्भक्त अभ्यासो भगवत्सङ्गानुशीलनं स एव योग उपायः तद्युक्तेन नान्यगामिना अन्यत्रोत्तमत्वज्ञानजचाञ्चल्यदोषरहितेन चेतसा दिव्यं क्री़डात्मकं परमं पुरुषं पुरुषोत्तमभावं निर्जितचेतसा अनुचिन्तयन् भगवत्कृतस्मरणानन्तरं चिन्तयन् स्मरन् हे पार्थ तमेव याति प्राप्नोतीत्यर्थः। पार्थेति सम्बोधनेन पृथासम्बन्धान्मत्कृतस्मरणानन्तरस्मरणेन यथा त्वं मामाप्नोषीति बोध्यते।'),
('purushottama-sc:source:8.9','Puruṣottamajī','gita.8.9','sa','commentary','।।8.9।।चिन्तनीयस्वरूपधर्मानाह द्वाभ्याम् -- कविमिति। कविं शब्दार्थरसिकं स्वगुणानुवर्णनश्रवणानन्दसंसूचितानुग्रहम् पुराणं अनादिसिद्धं सर्वदैकरसम् अनुशासितारं भावादिधर्मनियन्तारम् अणोरणीयांसं अणोः सूक्ष्मात् अणीयांसं सूक्ष्मम्। अयं भावः -- सूक्ष्माज्जीवात् सूक्ष्मं जीवभावभावनयोग्यस्वरूपप्राकट्येन तद्वृदि बहिस्तद्दृष्ट्यादिस्थितियोग्यम्। सर्वस्य स्वक्रीडायोग्यस्य भावादिरूपाक्षरादिरूपपदार्थस्य धातारं पोषकम्। अचिन्त्यरूपं अलौकिकक्रीडाद्यपरिमेयमहिमानम्। आदित्यवर्णं रसात्मकतापतेजसा सर्वप्रकाशकम्। तमसः परस्तात् प्रकृतेः परस्ताद्वर्त्तमानम्। अत्रायं भावः -- भावात्मकप्राप्तभक्तस्वरूपं प्रकटितलीलास्वरूपात् सर्वदा रसात्मकत्वेन वर्तमानमेवं पुरुषं पुरुषोत्तमम्।'),
('purushottama-sc:source:8.10','Puruṣottamajī','gita.8.10','sa','commentary','।।8.10।।प्रयाणकाले अन्तकाले मनसा निश्चलेन मनसा सर्वकामरहितेन च पुनः योगबलेनैव संयोगात्मकभावेनैव भ्रुवोर्मध्ये भाग्यस्थाने सन्तं विद्यमानं योऽनुस्मरेद्भगवत्कृतस्मरणानन्तरं स्वार्थप्रकटज्ञानेन स्मरेत् स तस्मिन्नेव प्राणमावेश्य सम्यक् भावात्मकस्वरूपप्राप्त्या परं पुरुषं पुरुषोत्तमं दिव्यं क्रीडात्मकं उपैति समीपे दास्येन प्राप्नोतीत्यर्थः।'),
('purushottama-sc:source:8.11','Puruṣottamajī','gita.8.11','sa','commentary','।।8.11।।ननु भक्तियुक्ता अपि तदेव प्राप्नुवन्ति योगयुक्ता अपि च तदा तयोः को विशेषः इत्याकाङ्क्षायां तयोः प्राप्यरूपमाह -- यदक्षरमिति। वेदविदो वेदान्तज्ञा यदक्षरं वदन्ति यत् वीतरागो विरागिणो यतयः सर्वत्यागादिप्रयत्नवन्तो विशन्ति यत्रैक्यं प्राप्नुवन्ति यदिच्छन्तो यत्स्वरूपज्ञानेन प्राप्तीच्छवः ब्रह्मचर्यमिन्द्रियनिग्रहं गुरुकुले चरन्ति तत्पदं तेषां प्राप्यं ते तुभ्यं सङ्ग्रहेण सङ्क्षेपेण ज्ञानार्थं प्रवक्ष्ये कथयिष्यामीत्यर्थः।'),
('purushottama-sc:source:8.12','Puruṣottamajī','gita.8.12','sa','commentary','।।8.12।।प्रतिज्ञातस्वरूपमाह द्वाभ्याम् -- सर्वद्वाराणीति। सर्वाणि इन्द्रियद्वाराणि संयम्य वशीकृत्य लौकिकविषयान्मनोनिरुन्धनं कृत्वा मनश्च विकल्पादिधर्मत्यागेन हृदि निरुद्ध्य मूर्ध्नि भ्रुवोर्मध्ये भाग्यस्थाने प्राणमाधाय आत्मनो योगधारणामास्थित आश्रितः सन्।'),
('purushottama-sc:source:8.13','Puruṣottamajī','gita.8.13','sa','commentary','।।8.13।।ओमिति। एकाक्षरं शक्तिद्वयसम्बद्धपुरुषवद्वर्णत्रयात्मकमेकं यदक्षरं ब्रह्मवाचकत्वात्तत्सरूपत्वाद्वा ब्रह्मात्मकं व्याहरन्नुच्चारयन् मामेवंरूपं प्रकटमनुस्मरन् यो देहं त्यजन् प्रयाति प्रकर्षेण भावात्मतया गच्छति स परमां परो मीयते यया यत्र वा तां गतिं अक्षरात्मिकां याति प्राप्नोतीत्यर्थः।'),
('purushottama-sc:source:8.14','Puruṣottamajī','gita.8.14','sa','commentary','।।8.14।।एवं योगयुक्तानां स्वांशाक्षरात्मकगतिस्वरूपमुक्त्वा भक्तियुक्तस्य स्वप्राप्तिमाह -- अनन्य इति। सततं निरन्तरमव्यवच्छिन्नतया न अन्यस्िमँल्लौकिकालौकिकविषये चेतो यस्य तादृशो यो मां नित्यशः प्रत्यहं,स्मरति तस्य नित्ययुक्तस्य मम नित्यं सम्मतस्य योगिनः सकाशादहं सुलभः सुखेन लभ्यः प्राप्यः। पार्थेति सम्बोधनेन यथा त्वन्मातृस्मरणबलेन तव सुलभो जातस्तथेति व्यञ्जितम्।'),
('purushottama-sc:source:8.15','Puruṣottamajī','gita.8.15','sa','commentary','।।8.15।।नन्वेवमेव तत्तद्देवोपासकास्तत्तत्सायुज्यं प्राप्नुवन्तीति तत्तच्छास्त्रेषु निगद्यत इति भवत्प्राप्तौ को विशेषः इत्याकाङ्क्षायां स्वप्राप्तेर्विशेषमाह -- मामुपेत्येति। महात्मानो महात्मका भक्ता परमां संसिद्धिं भावरूपां गताः सन्तो मामेकं पुरुषोत्तममुपेत्य समीपे प्राप्य पुनः दुःखालयं संसारात्मकं अशाश्वतमनित्यं लौकिकं जन्म न प्राप्नुवन्तीत्यर्थः।'),
('purushottama-sc:source:8.16','Puruṣottamajī','gita.8.16','sa','commentary','।।8.16।।अथान्येषां पुनर्जन्म भवतीत्यर्थः -- आब्रह्मेति। आब्रह्मभुवनात् ब्रह्मभुवनमभिव्याप्य सर्वे लोकाः पुनरावर्तिनः सर्वे पुनर्जन्मभाजो भवन्ति। मां तु उपेत्य कौन्तेय परमस्निग्ध परं जन्म न विद्यते न स्यादित्यर्थः। तुशब्देन मन्मार्गे प्रवृत्तस्य अत एव शङ्का न भवतीति ज्ञापितम्।'),
('purushottama-sc:source:8.17','Puruṣottamajī','gita.8.17','sa','commentary','।।8.17।।ननु ब्रह्मलोकगतास्तेन सह मुच्यन्तेब्रह्मणा सह मुच्यन्ते इत्यादिभ्यस्तेऽपि पुनरावृत्तिरहिता भवन्त्येवेत्याशङ्क्य तेषां तदभावमाह -- सहस्रेति। सहस्रयुगपर्यन्तं चतुर्युगसहस्रं पर्यन्तोऽवसानं यस्य तत् ब्रह्मणो यदहर्दिनं तद्ये विदुर्जानन्ति युगसहस्रान्तां चतुर्युगसहस्रं अन्तो यस्यास्तादृशीं रात्रिं ये विदुस्ते अहोरात्रविदः। तत्र कालगणने मनुष्याणां यद्वर्षं तद्देवानामहोरात्रः तादृगहोरात्रगणितद्वादशवर्षसहस्रेण चतुर्युगं तच्च तद् ब्रह्मणो दिनं तावत्येव रात्रिस्तद्गणनक्रमेण वर्षशतं तत् ब्रह्मणः परमायुरित्युच्यते तदवसाने तत्सहितमुक्तानामक्षरप्राप्तिः परम्परया भवति।'),
('purushottama-sc:source:8.18','Puruṣottamajī','gita.8.18','sa','commentary','।।8.18।।पुनस्तत्प्रकटसमये तत्सहितानामागमनमित्याह -- अव्यक्तादिति। अव्यक्तादक्षराद्भगवच्चरणरूपात् व्यक्तयः स्थावरजङ्गमादयः सर्वाः देवादिकीटतृणादयः अहरागमे ब्रह्मदिनोद्गमे प्रभवन्ति उत्पद्यन्ते। तत्रैवाव्यक्तसंज्ञके अक्षरे रात्र्यागमे रात्र्युद्गमे प्रलीयन्ते लीना भवन्तीति तद्विदो जनास्तत्र प्रविशन्तीत्यर्थः।'),
('purushottama-sc:source:8.19','Puruṣottamajī','gita.8.19','sa','commentary','।।8.19।।तत्र प्रलीनाश्च पुनरुत्पद्यन्त इत्याह -- भूतग्राम इति। स एव पूर्वोक्त एवायं परिदृश्यमानो मत्सम्बन्धरहितो भूतग्रामश्चराचरसमूहो भूत्वा भूत्वा उत्पद्योत्पद्य रात्र्यागमे दिवसावसाने अवशः परवशः सन् प्रलीयते। हे पार्थेति सावधानः श्रृण्वित्यर्थः। तथैव अहरागमे दिनागमेऽवश एव प्रभवति उत्पद्यत इत्यर्थः।'),
('purushottama-sc:source:8.20','Puruṣottamajī','gita.8.20','sa','commentary','।।8.20।।एवं तेषां पुनरुद्गममुक्त्वा स्वप्राप्तौ तदभावाय स्वस्थानस्वरूपमाह -- परस्तस्मादिति। तुशब्देन पूर्वस्य परत्वं व्यावर्त्तयति तस्मात्पूर्वोत्पत्तिकारणात्मकादन्यो भावः अव्यक्तः तस्यापि मूलभूत इत्यर्थः। अव्यक्तात्सनातनः अनादिसिद्धः परः सर्वोत्तम इत्यर्थः। तत्स्वरूपमाह -- यः सर्वेषु भूतेषु नश्यत्सु सत्सु न विनश्यति न विकारमाप्नोतीत्यर्थः।'),
('purushottama-sc:source:8.21','Puruṣottamajī','gita.8.21','sa','commentary','।।8.21।।एवमव्यक्तपरस्वरूपमुक्त्वा ज्ञानार्थं विशिनष्टि -- अव्यक्त इति। अव्यक्तः अप्रकटः ज्ञातुभशक्यो यो भावः स अक्षरः न क्षरति न चलति मच्चरणांशरूप इत्युक्तः तमक्षरं वेदादिविदः परमां परस्य अनुमेयां गतिमाहुः। ननु ते तस्य परमगतित्वं कुतो वदन्ति। इत्याशङ्क्याह -- यं प्राप्य न निवर्तन्ते इति। यत्स्थानं प्राप्य न निवर्तन्ते पुनर्जन्मानो न भवन्ति अतस्तथा वदन्तीत्यर्थः। तथात्वं तस्य स्वसम्बन्धादित्याह -- तदिति। तदक्षरात्मकं मम परममुत्कृष्टं धाम गृहमित्यर्थः। मद्गृहत्वात् पुनरावृत्तिर्न भवतीति भावः।'),
('purushottama-sc:source:8.22','Puruṣottamajī','gita.8.22','sa','commentary','।।8.22।।ननु यद्धामगता न निवर्तन्ते स त्वं कथं प्राप्यः इत्याकाङ्क्षायामाह -- पुरुष इति। हे पार्थ मद्भक्त सोऽहं परः पुरुषोत्तमः अनन्यया ऐहिकपारलौकिकयोर्मच्छरणैकरूपया मदितरज्ञानरहितया भक्त्या स्नेहेन लभ्यः प्राप्यः। स कीदृशः इत्यत आह -- यस्येति। यस्य अन्तस्स्थानि भूतानि चराचराणि रमणकारणात्मकानि यस्य मध्ये स्वरूपे तिष्ठन्ति येन इदं परिदृश्यमानं सर्वं जगत् ततं व्याप्तम्। अत्रायं भावः -- लौकिकाः सर्वे क्रीडोपयुक्ता न भवन्ति आचरणस्थितत्वात् अतस्ते ज्ञानादिना मद्धाम प्राप्यं लीनास्तत्रैव,मुक्ता भवन्तीत्यर्थः। येन क्रीडार्थमाविर्भूतेन तदधिष्ठानत्वादिदं मयि जगत् व्याप्तं सत् ततं विस्तृतं विभातीति भावः।'),
('purushottama-sc:source:8.23','Puruṣottamajī','gita.8.23','sa','commentary','।।8.23।।नन्वितो गता य आवर्तन्ते निवर्तन्ते वा ये तेऽत्र कथं ज्ञेयाः इत्याशङ्क्याह -- यत्रेति। यत्र काले यस्मिन् काले प्रयाता योगिनः अनावृत्तिं यान्ति प्राप्नुवन्ति च पुनः यस्मिन् काले प्रयाता आवृत्तिमेव प्राप्नुवन्ति हे भरतर्षभ ज्ञानयोग्यकुलोत्पन्न तं कालं वक्ष्यामि कथयामीत्यर्थः।,'),
('purushottama-sc:source:8.24','Puruṣottamajī','gita.8.24','sa','commentary','।।8.24।।तत्र पूर्वमनावृत्तिज्ञापककालस्वरूपमाह -- अग्निरिति। अग्निर्ज्योतिः। तापयुक्तज्योतिर्युक्तः अहः दिवसः। शुक्लः शुक्लपक्षः। षण्मासा उत्तरायणं प्राप्य भवन्ति। तत्र तस्मिन् काले प्रयाता ब्रह्मविदो जना भक्ताः। ब्रह्म भगवत्स्वरूपमनावृत्त्यात्मकं गच्छन्ति। अत्रायं भावः आयुर्भोगपूर्णतया कालवशेनोत्तरायणादिविशिष्टकालमृताः सर्व एव न तत् प्राप्नुवन्ति किन्तु भगवद्भक्ता भीष्मवत् तत्काल आगते भगवन्निष्ठैकतया ये प्राणांस्त्यक्त्वा यातास्ते प्राप्नुवन्तीत्यर्थः। एतज्ज्ञापनायैव ब्रह्मविद इत्युक्तम्। एतदेव तज्ज्ञापकमित्यर्थः।'),
('purushottama-sc:source:8.25','Puruṣottamajī','gita.8.25','sa','commentary','।।8.25।।आवृत्तिकालरूपमाह -- धूम इति। धूमस्तापरूपाग्न्यात्मकप्रतिबन्धरूपः रात्रिर्निशा कृष्णः पक्षः एवं षण्मासा दक्षिणायनम्। तत्र योगी सकामः प्रयातः सन् चान्द्रमसं स्वर्गादिसुखं शीतलात्मकं प्राप्य सुखभोगं कृत्वा निवर्तते पुनर्जन्म प्राप्नोतीत्यर्थः।'),
('purushottama-sc:source:8.26','Puruṣottamajī','gita.8.26','sa','commentary','।।8.26।।एवं कालस्वरूपद्वयमुक्त्वोपसंहरति -- शुक्ल इति। शुक्लकृष्णे पूर्वोक्ता शुक्ला इतरा कृष्णा एते गती ज्ञानप्रकाशकगमनात्मके जगतस्तत्तदधिकारिणः शाश्वते सनातने अनादी मते मन्मत इत्यर्थः। एकया पूर्वोक्तया अनावृत्तिं याति अन्यया कृष्णया पुनः वर्तते आवर्त्तते। अनेन प्रकारेण गमनादिना स्वरूपमत्रैव ज्ञेयमित्यर्थः।'),
('purushottama-sc:source:8.27','Puruṣottamajī','gita.8.27','sa','commentary','।।8.27।।एतज्ज्ञानफलं वदन्नुपसंहरति -- नैते इति। एते सृती मार्गौ हे पार्थ मद्भक्त जानन् कश्चन योगी मत्सम्बन्धियोगं विना केवलयोगी भूत्वा न मुह्यति न मोहं प्राप्नोति। सकामो भूत्वा केवलयोगाद्यासक्तो न भवतीत्यर्थः। यत एतज्ज्ञानिनो मोहो न भवति तस्मात् मदुक्तज्ञानयुक्तः सर्वत्र मोहरहितः सर्वेषु कालेषु लौकिकालौकिकेषु पूर्वोक्तेषु वा अर्जुन मोक्षजातीयनामयुक्त योगयुक्तो मद्योगयुक्तो भवेत्यर्थः।'),
('purushottama-sc:source:8.28','Puruṣottamajī','gita.8.28','sa','commentary','।।8.28।।एवमष्टप्रश्नोत्तरमुक्त्वैतज्ज्ञानयुक्तयोगिनः सर्वकालप्राप्तिमुक्त्वोपसंहरति -- वेदेष्विति। वेदेषु अध्ययनादिभिः यज्ञेषु यज्ञानुष्ठानादिभिः तपस्सु परमसन्तापेन क्लेशसहनादिभिः दानेषु तुलापुरुषादिभिर्यत्पुण्यफलं प्रदिष्टम् उक्तमिति यावत् तत्सर्वं फलमिदं समस्ताध्यायार्थं विदित्वा अभ्येति प्राप्नोति ततोऽधिकमपि योगी मद्योगयुक्तः सन् परं मत्सेवारूपं आद्यं सकलकारणरूपं मच्चरणात्मकम् (स्थानं) उपैति मत्समीपे प्राप्नोतीति भावः।भक्तैः शुद्धात्मभक्त्यैव संयोगः पुरुषोत्तमे।प्राप्यते कृष्णदेवेन तदुक्तमिह चाष्टमे।।1।।महापुरुषसंयोगो जीवानां तु यथा भवेत्।कृपया कृष्णदेवेन पार्थायोक्तं तदष्टमे।।2।।इति श्रीभगवद्गीतामृततरङ्गिण्यामष्टमोऽध्यायः।।8।।'),
('purushottama-sc:source:9.1','Puruṣottamajī','gita.9.1','sa','commentary','।।9.1।।प्रोवाच कृष्णः कृपया नवमे पाण्डवं प्रति। राजविद्या राजगुह्यं योगं स्वैश्वर्यबोधकम्।।1।।एवं पूर्वाध्याये स्वस्वरूपं भक्त्यैकलभ्यमुक्त्वा भक्तिस्वरूपज्ञानमाह कृष्णः कृपया -- इदं त्विति। इदं तु गुह्यतममत्यन्तं गुप्तं भगवद्विषयकभक्त्यात्मकं ज्ञानं विज्ञानसहितमनुभवसहितं भक्तिप्रतिफलनरूपं अनसूयवे प्रतिक्षणमुत्तरोत्तरमतिकाठिन्यभक्त्यैकलभ्यस्वरूपकथनेऽपि दोषरहितश्रवणैकपरचित्ताय ते तुभ्यं प्रवक्ष्यामि? प्रकर्षेण स्वरूपज्ञानसहितं कथयिष्यामीत्यर्थः। यज्ज्ञात्वा यत्स्वरूपं ज्ञात्वा अशुभात् स्वरूपाज्ञानात्मकसंसारात् मोहाद्वा मोक्ष्यसे? मुक्तो भविष्यसीत्यर्थः। तुशब्देन सर्वेषामकथनीयत्वं ज्ञापितम्। ते इति कथनेन कृपया वक्ष्यामीति व्यञ्जितम्।'),
('purushottama-sc:source:9.2','Puruṣottamajī','gita.9.2','sa','commentary','।।9.2।।गुह्यतमत्वज्ञापनायोच्यमानस्य सर्वोत्तमत्वमाह -- राजविद्येति। इदमुच्यमानं राजविद्या विद्यानां राजा? ब्रह्मविद्यात्मकमित्यर्थः। राजगुह्यं गुह्यानां गोप्यानां राजा? विद्यासु मुख्यत्वात् गोप्येषु मुख्यत्वात् कस्यापि न वक्तव्यमिति भावः। पवित्रं? परमपावनमित्यर्थः। उत्तमं सर्वोत्कृष्टम्। प्रत्यक्षावगमं साक्षात्फलात्मकं? दृष्टफलरूपमित्यर्थः। धर्म्यं धर्मोत्पादकं? कर्तुं सुसुखं सुखेन कर्तुं योग्यम्? अव्ययं अविनाशि। यद्वा -- अव्ययं कर्तुं स्वसुखं सुसुखं परमसुखमित्यर्थः।'),
('purushottama-sc:source:9.3','Puruṣottamajī','gita.9.3','sa','commentary','।।9.3।।एवं पूर्वंते प्रवक्ष्यामि [9।1] इत्यनेन श्रद्दधानाय तुभ्यं कथयामीति प्रतिज्ञाय एतदश्रद्दधानाः संसारं प्राप्नुवन्तीति कथनेनैतस्योत्तमत्वं प्रतिपादयति -- अश्रद्दधाना इति। हे परन्तप मत्प्रसादात्मकोत्कृष्टतपोयुक्त इदं ज्ञानं मद्वाक्यरूपमश्रद्दधानाः पुरुषाः योगज्ञा अपि अस्य धर्मस्य फलरूपं मां अप्राप्य मृत्युयुक्ते संसारमार्गे निवर्तन्ते परिभ्रमन्ति जायस्व म्रियस्व [छां.उ.5।10।8] इति तृतीयमार्गाभिनिविष्टा भवन्तीत्यर्थः।अश्रद्दधानाः इति कथनेन श्रद्धामात्रेणापि संसाराभावो व्यञ्जितः।'),
('purushottama-sc:source:9.4','Puruṣottamajī','gita.9.4','sa','commentary','।।9.4।।एवं प्रतिज्ञाय तत्स्वरूपं च स्तुत्वा ज्ञानमेवाह द्वाभ्याम् -- मयेति। अव्यक्तातिरिक्तेषु लौकिकेन्द्रियागोचरा स्वक्रियेच्छैकदृश्या मूर्तिः स्वरूपं यस्य। वक्ष्यति चाग्रेदिव्यं ददामि ते चक्षुः [11।8]भक्त्या त्वनन्यया [11।54] इत्यादि। एतादृशेन मया इदं जगत् सर्वं जडजङ्गमात्मकमातृणस्तम्बान्तं ततं व्याप्तं? मत्क्रीडार्थं मदात्मकं मया सृष्टमित्यर्थः। यद्वा अव्यक्तमूर्तिना मया व्याप्तमिदं सर्वं जगत् अस्तीति शेषः।अयं भावः -- आतृणस्तम्बान्तं सर्ववस्तुषु तत्तत्स्वरूपोऽहमेवास्मि? अव्यक्तत्वात्तथा सवैर्न ज्ञायते एवं चेत्सर्वेषु भूतेषु तद्रूपः प्रविष्टो भवानाधिदैविकन्यायेन भविष्यतीत्यत आह -- मत्स्थानीति। मत्स्वरूपस्थानि सर्वाणि सन्ति? सर्वाधारत्वात्। क्रीडेच्छया पृथक् तत्तद्रूपं प्रकटयामीति भावः। अपरिच्छिन्नत्वात् प्रकटमपि जगन्मय्येव तिष्ठति। तेषु न च अहम्। तेषु परिच्छिन्नतया न तिष्ठामीत्यर्थः।'),
('purushottama-sc:source:9.5','Puruṣottamajī','gita.9.5','sa','commentary','।।9.5।।मत्स्थानि सर्वभूतानि [9।4] इत्युक्त्या भगवतस्ते भिन्ना भविष्यन्तीति ज्ञानेन व्यापकत्वे भ्रमो मा भवत्वित्यत आह -- न च मत्स्थानीति। च पुनः। तानि भूतानि जातान्यपि भिन्नतया मत्स्थानि न? किन्तु मदात्मकान्येवेत्यर्थः। ननु तर्हि कथं भेदप्रतीतिः इत्यत आह -- पश्य मे योगमैश्वरमिति। मे ऐश्वरं कर्तुमकर्तुमन्यथाकर्तुं समर्थत्वरूपं क्रीडात्मकं योगं पश्य।अयमर्थः -- मया क्रीडार्थमभेदेऽपि भेदो बोध्यते। एतदेव विशदयति -- भूतभृदिति। भूतानि आधारत्वेन धारयति स्वरसार्थं पोषयतीति भूतभृत्। भूतानि पालयति तथा भावयति स्वभावभावितानि करोतीति भूतभावनः। एतादृशोऽपि सन् ममात्मा मदात्मस्वरूपं भूतस्थो न भवति। अयं भावः -- तेषु क्रीडां कुर्वन्नपि यथा ते क्रीडार्थं सृष्टास्तत्र स्थिताः स्वाभिमानेन भिन्नतया,तिष्ठन्ति तथाऽहं न तिष्ठामि।'),
('purushottama-sc:source:9.6','Puruṣottamajī','gita.9.6','sa','commentary','।।9.6।।तर्हि भवतो व्यापकत्वज्जीवस्याणुत्वादव्यापकत्वाच्च मत्स्थानीत्याधाराधेयभावः। कथं इत्यत आह सदृष्टान्तम् -- यथेति। यथा सर्वगो महानपि वायुर्नित्यमाकाशस्थितो भवति आकाशेन च न स्पृश्यते। नित्यपदेनाकाश एव सर्वत्र गतियुक्तो भवतीति व्यञ्जितम्। तथा सर्वाणि भूतानि सर्वत्रगतियुक्तानि मत्क्रीडेच्छयैव मत्स्थानीत्युपधारय जानीहि। उप समीपे मत्समीपे धारय पश्येत्यर्थः।'),
('purushottama-sc:source:9.7','Puruṣottamajī','gita.9.7','sa','commentary','।।9.7।।ननु भगवद्गतानां भवति स्थितानां नाशः कथं इत्याशङ्क्याह -- सर्वभूतानीति। हे कौन्तेय कृपैकपात्र कल्पक्षये कल्पसमाप्तौ सर्वभूतानि मामिकां प्रकृतिं स्वरतीच्छारूपां यान्ति। पुनस्तानि कल्पादौ प्रपञ्चक्रीडेच्छया अहं विसृजामि विशेषेण नीचोच्चप्रकारेण वैचित्र्यार्थं सृजामि।'),
('purushottama-sc:source:9.8','Puruṣottamajī','gita.9.8','sa','commentary','।।9.8।।ननु त्वयि लीनानामानन्दनिमग्नानां पुनः सृष्टौ किं तात्पर्यं इत्याशङ्क्याह -- प्रकृतिमिति। स्वां प्रकृतिं असाधारणीं रमणात्मिकामवष्टभ्याधिष्ठाय रमणभावमङ्गीकृत्य पुनःपुनः वारंवारं मम क्रीडायोग्यं मद्दर्शनयोग्यं च भूतग्रामं चतुर्विधं कृत्स्नं पूर्णं अवशं मदिच्छाधीनं प्रकृतेर्वशात् क्रीडात्मकस्वरूपवशात् सृजामि। अन्यथा सृष्टानां पूर्वोक्तदूषणं स्यात् स्वक्रीडार्थं सृष्टानामत्राप्यानन्दरूपतैवेति भावः।'),
('purushottama-sc:source:9.9','Puruṣottamajī','gita.9.9','sa','commentary','।।9.9।।ननु रमणात्मकशक्तिवशसृष्टानि तानि त्वां वशीकृत्य प्रपञ्चरमण एवं कथं न स्थापयन्ति इत्याशङ्क्याह -- न च मामिति। हे धनञ्जय लौकिकपरवशैकचित्त तानि भूतानि उदासीनवत् आसीनं तेषु? परमकृपया कृतार्थीकरणार्थं तेषु तिष्ठन्तं मां न निबध्नन्ति न वशीकुर्वन्ति। च पुनः कर्माणि क्रीडात्मकानि च मां न वशीकुर्वन्ति। कुतः तेषु कर्मसु क्रीडात्मकेष्वपि असक्तमनासक्तम्? आत्मारामत्वात् शक्तिषु रसदानार्थं क्रीडाकरणात्। एतदेवोक्तंवैकुण्ठः कल्पितो येन लोको लोकनमस्कृतः। रमया प्रार्थ्यमानेन देव्या तत्प्रियकाम्यया [भाग.8।5।5] इति।'),
('purushottama-sc:source:9.10','Puruṣottamajī','gita.9.10','sa','commentary','।।9.10।।ननूदासीनस्तेषु त्वं चेत्तदा प्रकृतिवशोत्पन्ना जीवाः कथं क्रीडायोग्या भवन्ति कथं वा त्वं कर्ता इत्याशङ्क्याह -- मयेति। मया परिदृश्यमानेन अध्यक्षेण अधिष्ठात्रा सकलकर्त्रा क्रीडाधिष्ठिता सती प्रकृतिः सचराचरं जडजीवसहितं जगत् सूयते जनयति। अनेन क्रीडात्मकेन हेतुना कारणेन जगत् विशेषेण परिवर्त्तते जायते च। अतो योग्या भवन्तीत्यर्थः।'),
('purushottama-sc:source:9.11','Puruṣottamajī','gita.9.11','sa','commentary','।।9.11।।नन्विदं स्वरूपं सर्वाधिष्ठातृ सर्वे कथं न जानन्ति इत्यत आह -- अवजानन्तीति द्वयेन। मूढा असुराः केवलमिच्छयैव सृष्टाः? मम भूतमहेश्वरं सर्वाधिष्ठातृ सर्वाधिदैविकरूपं परं भावं पुरुषोत्तमात्मकं अजानन्तो मानुषीं तनुं मायिनं स्वाज्ञानेन मां ज्ञात्वा अवजानन्ति अवमन्यन्ते।अत्रायं भावः -- पुरुषोत्तमोऽयं येन स्वरूपेण वदति तदेव स्वरूपं ब्रह्मरूपमानन्दमयम्? तमेव मानुर्षी तनुमाश्रितं जानन्ति अज्ञत्वात्।'),
('purushottama-sc:source:9.12','Puruṣottamajī','gita.9.12','sa','commentary','।।9.12।।तेषां मूढत्वं विशदयति -- मोघाशा इति। मोघाशाः मोघं निष्फलं असमर्पितान्नं केवलं देहपोषार्थं अश्नन्ति भक्षयन्तीति तथा। मोघं निष्फलमेव भगवत्सेवातिरिक्तकर्मकर्त्तारः। मोघज्ञानाः मोघं निष्फलं मोहकशास्त्रोक्तभगवत्स्वरूपज्ञानातिरिक्तज्ञानयुक्ताः। विचेतसः अव्यवस्थितमनसः। राक्षसीं स्वदेहपोषणरूपाम्। च पुनः। आसुरीं परोपद्रवकरणरूपां मोहिनीं मद्विस्मारिकां प्रकृतिमेव मायामेव स्वभावमाश्रिताः। अतएव मां मानुषीं तनुमाश्रितं ज्ञात्वा अवमन्यन्त इति पूर्वेणान्वयः।'),
('purushottama-sc:source:9.13','Puruṣottamajī','gita.9.13','sa','commentary','।।9.13।।एवमासुराणां स्वाज्ञानमुक्त्वा देवानां स्वज्ञानमाह -- महात्मानस्त्विति। हे पार्थ भक्तस्वरूपश्रवणैकयोग्य महात्मानस्तु महान् अहमेव आत्मा येषां ते महात्मानः। तुशब्दः प्रकरणान्तरज्ञापनाय। तदेवाह -- दैवीं क्रीडात्मिकां देवरूपां वा प्रकृतिं स्वभावं आश्रिताः। अनन्यमनसः न विद्यते अन्यत्र मद्व्यतिरिक्ते मनो येषां ते मां भूतादिं सकलजगत्कारणं अव्ययं नित्यं यथार्थरूपं ज्ञात्वा भजन्ति।');
INSERT INTO commentary_fts (unit_id,author,canonical_ref,language,content_type,content) VALUES
('purushottama-sc:source:9.14','Puruṣottamajī','gita.9.14','sa','commentary','।।9.14।।ते च द्विविधाः? भक्ता ज्ञानिनश्च? तत्र प्रथमं भक्तानां भजन प्रकारमाह -- सततमिति। सततं निरन्तरं मां कीर्तयन्तः लीलास्वरूपज्ञानेन श्रीभागवतोक्तप्रकारेण गुणगानं कुर्वन्तः? सर्वत्र मदुत्कर्षं कथयन्तः। यतन्तश्च कीर्तने यत्नादिकं कुर्वाणाः? इन्द्रियनिग्रहं वा कुर्वन्तः। चकारेण श्रवणादिकं ज्ञाप्यते। पुनः कीदृशाः दृढव्रताः दृढं ऐहिकपारलौकिकयोर्मदेकनिष्ठं मोहशात्रा৷৷৷৷৷৷৷৷৷৷৷৷द्यपरिभूतं व्रतं निश्चयो येषां तादृशाः। किञ्च नमस्यन्तश्चकिमासनं ते गरुडासनाय इत्यादिना परमकाष्ठापन्नवस्तुरूपनमस्कारं कुर्वन्तः स्वदैन्याविर्भावपूर्वकं? चकारेण नृत्यादिकमपि कुर्वन्तः। पुनः कीदृशाः। नित्ययुक्ताः सावधानाः मदेकपरचित्ताः। भक्त्या स्नेहेन? न तु विहितत्वेन? मामुपासते सेवन्त इत्यर्थः।'),
('purushottama-sc:source:9.15','Puruṣottamajī','gita.9.15','sa','commentary','।।9.15।।एवं भक्तानां भजनप्रकारमुक्त्वा ज्ञानिनामाह -- ज्ञानयज्ञेनेति। अन्ये ज्ञानिनो ज्ञानयज्ञेन चापि ज्ञानात्मकयजनप्रकारेण चापि यजन्तो हृद्येव मां पूजयन्त उपासते भजन्त इत्यर्थः। अपिशब्देन चकारेण च पूर्वोक्तभजनापेक्षया हीनत्वं व्यज्यते। ज्ञानभजने बहवः प्रकाराः सन्ति? तानाह -- एकत्वेनसोऽहं ब्रह्मास्मि [ ] इति प्रकारेण पृथक्त्वेन योगेन शरणागमनरीत्या बहुधा सर्वत्र तद्रूपेण विश्वतोमुखं सर्वात्मकं माम्? एवमनेकप्रकारेण मामुपासते भजन्त इत्यर्थः।'),
('purushottama-sc:source:9.16','Puruṣottamajī','gita.9.16','sa','commentary','।।9.16।।नन्वेकमेव त्वां बहुधा ये भजन्ति ते च ज्ञानिन एव? तेषामज्ञाने ज्ञाने कथं प्रवेशः इत्याशङ्क्य तत्तदात्मकं मां ज्ञात्वैव भजन्तीति ज्ञापनाय स्वस्य सर्वात्मत्वं प्रकटयति -- क्रतुरित्यादिचतुर्भिः। क्रतुः यज्ञाधिष्ठात्री देवता अहम्? आधिदैविकरूपस्तत्फलदातेत्यर्थः। यज्ञो धर्मात्मकोऽग्निहोत्रादिर्यज्ञात्मकोऽहम्। स्वधा पित्रर्थे श्राद्धादिपितृयज्ञरूपोऽहम्। औषधं सकलरोगनिवर्तनात्मकभैषज्यरूपोऽन्नरूपो वा अहम्। मन्त्रः ऋगादिरहम्। आज्यं होमद्रव्यं हविः। अग्निराहवनीयादिः। हुतं होमः।'),
('purushottama-sc:source:9.17','Puruṣottamajī','gita.9.17','sa','commentary','।।9.17।।किञ्च। अस्य जगतो मदात्मकस्य अहमेव पिता उत्पादकः। माता योनिः। धाता कर्मफलदाता। पितामहो ब्रह्मा। वेद्यं सर्वज्ञानादिसाधनैर्वेद्यवस्तु। पवित्रं पावनम्। कारः अक्षरात्मकब्रह्मबीजम्? ऋगादिः वेदत्रयात्मा।'),
('purushottama-sc:source:9.18','Puruṣottamajī','gita.9.18','sa','commentary','।।9.18।।गतिर्मोक्षादिफलरूपः। भर्त्ता पोषकः। प्रभुः समर्थः सर्वनियन्ता। साक्षी द्रष्टेत्यर्थः। निवासः स्थानं सर्वदेहस्वरूपात्मक इति। शरणं अभयदाता मृत्युप्रभृतिभय रक्षकः। सुहृत् अप्रार्थितहितकर्ता। प्रभवः प्रकर्षेण भवत्यस्मादिति जगत्स्रष्टा। प्रलयः प्रकर्षेण लीयतेऽस्मिन्निति लयस्थानम्। स्थानं तिष्ठत्यस्मिन्निति स्थानं सकलाधारः। निधानं निधीयते स्थाप्यतेऽनेनेति निधानं? रक्षक इत्यर्थः। अव्ययं बीजम्? अविनाशि बीजं मूलकारणमित्यर्थः।'),
('purushottama-sc:source:9.19','Puruṣottamajī','gita.9.19','sa','commentary','।।9.19।।तपामि रसास्वादनार्थं सर्वेषां तापं करोमि। यदा तपामि तदा वर्षं रसात्मकं निगृह्णामि आकर्षामि स्वस्मिन् स्थापयामि। च पुनः तद्दानसमये पुनरुत्सृजामि। अमृतं जीवनमक्षयम्। मृत्युश्च मृत्युरूपः। सत् स्थूलं परिदृश्यमानम्। असत् सूक्ष्ममदृश्यम्। हे अर्जुन एतत्सर्वं पूर्वोक्तमहमेवेत्यर्थः। एवं बहुधा मामुपासत इति पूर्वेणैव सम्बन्धः।'),
('purushottama-sc:source:9.20','Puruṣottamajī','gita.9.20','sa','commentary','।।9.20।।एवं बहुप्रकारकं यत्स्वस्वरूपमुक्तं तदज्ञात्वा ये यज्ञाद्रिकमन्यया कुर्वन्ति सकामास्ते जन्ममरणात्मके संसारे तिष्ठन्तीत्याह द्वाभ्याम् -- त्रैविद्या इति। त्रैविद्याः वेदत्रयीनिरूपितकर्मकर्त्तारः। सोमपाः यज्ञशेषामृतपातारः। पूतपापाः कर्मिणां पापसम्भवाद्विधूतकल्मषाः। यज्ञैरेव वा विधूतकल्मषाः। मां यज्ञैरिष्ट्वा मदाज्ञारूपत्वेन भक्तिप्रतिबन्धनिवर्तकत्वमज्ञात्वा तत्स्वरूपं चाज्ञात्वा स्वर्गतिं इन्द्रादिलोकं प्रार्थयन्ते।'),
('purushottama-sc:source:9.21','Puruṣottamajī','gita.9.21','sa','commentary','।।9.21।।ते पुण्यात्मकं सुरेन्द्रलोकमासाद्य प्राप्य दिवि स्वर्गे स्वर्गलोकं विशालं सकलविषयभोगयोग्यं भुक्त्वा भोगेन पुण्ये क्षीणे सति मर्त्यलोकं विशन्ति? प्राप्नुवन्तीत्यर्थः। एवं प्रकारेण त्रयीधर्ममिष्टं৷৷৷৷৷৷৷৷৷৷৷৷৷৷৷৷. परित्यज्य,कामकामाः सन्तोऽनुप्रपन्नाः गतागतं जन्ममरणात्मकप्रवाहं लभन्ते प्राप्नुवन्तीत्यर्थः।'),
('purushottama-sc:source:9.22','Puruṣottamajī','gita.9.22','sa','commentary','।।9.22।।अथ ये पूर्वोक्तसर्वस्वरूपं मदंशबलयुक्तं ज्ञात्वा सर्वं परित्यज्य मां भजन्ति? तेषां सर्वमहमेव करोमि? त उत्तमा इति तत्स्वरूपमाह -- अनन्या इति। अनन्याः न विद्यते अन्यो लौकिकालौकिकादिषु प्रार्थ्यत्वेन येषां? वा मत्सेवनातिरिक्तं फलं येषां ते तथाभूताः सन्तो मामेकं चिन्तयन्तः सर्वतो मनोनिरोधेन मां स्मरन्तो ये दुर्लभा जनाः जन्मभाजो मत्सेवार्थकजन्मज्ञानवन्तः पर्युपासते परितः सर्वात्मभावेन सेवन्त इत्यर्थः। तेषां नित्याभियुक्तानां नित्यस्वरूपस्य मम सेवनपराणां मम नित्यमभियुक्तानां सम्मतानां योगं सेवार्थधनादिसम्पत्तिलाभं सेवने मद्योगं वा? क्षेमं तत्पालनं भक्त्युन्मुखीकरणात्मकं मद्भावरूपं वा अहं पुरुषोत्तमः वहामि पालयामीत्यर्थः। वहनोक्त्या तदशक्तौ स्वशक्त्याविर्भावेन तत्करोमीति व्यञ्जितम्।'),
('purushottama-sc:source:9.23','Puruṣottamajī','gita.9.23','sa','commentary','।।9.23।।नन्वन्यदेवभजनकर्त्तारोऽपि त्वदंशत्वात् त्वद्भजनमेव कुर्वन्तीति कथं न तेषु त्वत्कृपा तद्भजनं च कथं भोग एव क्षीयते इत्यत आह -- येऽपीति। येऽपि श्रद्धयाऽन्विताः श्रद्धायुक्तास्तदासक्तत्वधर्मयुक्ता अन्यदेवता यज्ञादिसाधनैस्तदधिष्ठातृरूपेण मदंशाज्ञानेन भजन्ति तेषु मदंशत्वात् मामेव भजन्ति? परन्तु मत्स्वरूपाज्ञानादविधिपूर्वकं भजन्ति? अतस्तेषां तद्भजनानुरूपं क्षयिष्ण्वेव फलं भवति अहं च न कृपां करोमीत्यर्थः। अत एव स्मृतिष्वविधिकरणनिषेधःविधिहीनं भावदुष्टं कृतमश्रद्धया च यत्। तद्धरन्त्यसुरास्तस्य सुमूढस्याऽकृतात्मनः इति।'),
('purushottama-sc:source:9.24','Puruṣottamajī','gita.9.24','sa','commentary','।।9.24।।विधिहीनरूपमाह -- अहमिति। हि निश्चयेन सर्वयज्ञानां भोक्ता तदधिष्ठातृदेवानां मदंशत्वात्तद्रूपेण अहं भोक्ता। चकारेण तद्रूपोऽपि। प्रभुरेव च? फलदाता चेत्यर्थः। एवकारेण৷৷৷৷৷৷৷৷৷৷৷৷৷৷. द्वितीयचकारेण च सर्वप्रभुत्वेन भोक्तृत्वेऽपि मदेकांशप्रीणनमेव भवति? न तु सर्वप्रभुमत्प्रीतिरिति ज्ञापितम्। एतादृशं मां तु पुनस्तत्त्वेन मूलरूपेण न अभितः सर्वप्रकारेण जानन्तियावान् यश्चास्मि (तत्त्वतः) यादृशः [18।55] इति। अतस्ते च्यवन्ति पर्यावर्तन्ते। मत्तो वा च्यवन्ति भ्रश्यन्ति। अत्रायं भावः -- भगवदंशदेवताभजनत्वेन यज्ञादिना वा यत्फलं भवति तन्महाप्रभुभजनेन भवतिमूलनिषेकः शाखायामपि इति न्यायेन प्रभुभजने तेऽपि प्रसीदन्ति? तद्भजने त एव प्रसीदन्ति तदंशप्राकट्य च भवेत्। अत एव युधिष्ठिरेण श्रीभागवतेक्रतुराजेन गोविन्द राजसूयेन पावनीः। यक्ष्ये विभूतीर्भवतस्तत्सम्पादय नः प्रभो [10।72।3] इति विज्ञापितम्। तेन भगवदिच्छया भगवद्भजनं कुर्वता तदिच्छां ज्ञात्वा तदंशप्राकट्यं चेत्तदा तद्रीत्यैव৷৷৷৷৷৷৷৷৷৷৷৷৷৷৷৷৷৷৷৷৷৷৷৷৷৷. कार्यमन्यथा न कार्यमेतदज्ञानात्तत्त्वज्ञानाभावः।'),
('purushottama-sc:source:9.25','Puruṣottamajī','gita.9.25','sa','commentary','।।9.25।।ननु त्वदंशाज्ञाने यजनकर्त्तारश्च्यवन्ति? येषां तु त्वदंशज्ञानेन तद्देवयजनकर्तृत्वं तेषां किं फलं इत्यत आह -- यान्तीति। देवव्रताः इन्द्रादिषु मदंशज्ञानेन तद्भूपेषु सनियमाः। देवान् तानेव यान्ति प्राप्नुवन्ति। पितृव्रताः श्राद्धादिविधिभिः पितृयाजकाः पितृ़न् यान्ति प्राप्नुवन्ति। भूतेज्याः विनायकदुर्गादिपूजकाः भूतानि तान्येव यान्ति। अत्रायमर्थः -- तत्तद्देवान् प्राप्य तत्सङ्गेन परम्परया मां प्राप्नुवन्ति। मद्याजिनः कर्मादिभिस्तदाधिदैविकरूपं मद्यजनकर्त्तारोऽपि मां प्राप्नुवन्ति। ते परम्परया मां प्राप्नुवन्ति। एते साक्षादिति विशेषः। अपिशब्देन कर्माङ्गत्वेन भजनेऽपि मुक्त्यात्मकस्वप्राप्तिरूपविशेषो व्यञ्जितः।'),
('purushottama-sc:source:9.26','Puruṣottamajī','gita.9.26','sa','commentary','।।9.26।।भक्तेषु विशेषमाह -- पत्रमिति। पत्रं तुलस्यादीनां प्रियरूपम्। पुष्पं अलङ्कारात्मकम्। फलं सामग्रीरूपम्। तोयं सामग्रीभेदरूपम्। यो मे मम भक्त्या स्नेहेन? न तु विहितत्वेन? प्रयच्छति प्रकर्षेण भावात्मकतया समर्पयति? तत् पूर्वोक्तं सर्वं भक्त्युपहृतं स्नेहेन समर्पितं प्रयतात्मनः मदेकपरतया वशीकृतचेतसः अहं पुरुषोत्तमः अश्नामि भुनज्मीत्यर्थः। अनायासप्राप्त्यर्थं पत्रादिकमुक्तम्। अशनोक्त्या तदङ्गीकारेणाग्रे स्वभोगयोग्यसर्वसामग्रीसम्पादनं व्यज्यते। अत एव सुदामार्थं स्वसम्पद्दाने पृथुकमुष्टिमङ्गीकृतवान्।,'),
('purushottama-sc:source:9.27','Puruṣottamajī','gita.9.27','sa','commentary','।।9.27।।यतोऽहं भक्त्युपहृतमङ्गीकरोम्यतः पूर्वकृतानां कुर्वतां च कर्मणां फलभोगरूपप्रतिबन्धनिवृत्त्यर्थं तत्सर्वं मदर्पितं कुर्वित्याह -- यत्करोषीति। यत् लौकिकं वैदिकं करोषि? यदश्नासि भुङ्क्षे? यज्जुहोषि होमं,करोषि? यद्ददासि दानं करोषि? तत्सर्वं मदर्पणं मत्समर्पितं कुरुष्व। देहादिधर्मान् विवाहपुत्रोत्पत्त्यर्थकामादीन् निद्राजागरणमूत्रपुरीषादिकाँस्तानपि भगवत्सेवाद्यर्थप्रतिबन्धाभावार्थविचारेण कुर्यात्? न तु स्वसुखेच्छया। तथा भोजनादिकमपि तत्र प्रसादजपुष्ट्या सेवार्थबलाप्त्यर्थम्। होमश्च तद्वियोगजदुःखास्ये (दुःखमुखे)। दानं च तदीयत्वेन द्रव्यशुद्ध्या भगवद्विनियोगप्रतिबन्धनिवृत्त्यर्थम्। तपश्च भगवतः कारुण्योदयार्थम्। एवमेतत्सर्वं भगवत्समर्पितं भवति।'),
('purushottama-sc:source:9.28','Puruṣottamajī','gita.9.28','sa','commentary','।।9.28।।एवं मत्समर्पितेषु तत्कृतबन्धो न भविष्यतीत्याह -- शुभाशुभफलैरिति। एवं मत्समर्पणेन शुभाशुभफलैः -- शुभानि शुभपुत्रादीनि? अशुभानि क्लेशदारिद्र्यादीनि यानि कर्मजानि फलानि तैर्मोक्ष्यसे मुक्तो भविष्यसीत्यर्थः। तानि फलानि मत्सेवौपयिकान्येव भविष्यन्तीति भावः। ततः सन्न्यासयोगयुक्तात्मा सन्न्यासः कर्मणां मत्समर्पणं तेन यो योगो मद्भक्त्यात्मकस्तेन युक्त आत्मा अन्तःकरणं यस्य तादृशः सन् कर्मबन्धनैर्विमुक्तो मामुपैष्यसि प्राप्स्यसीत्यर्थः।'),
('purushottama-sc:source:9.29','Puruṣottamajī','gita.9.29','sa','commentary','।।9.29।।एवं कर्मसमर्पणेन तद्बन्धनिवृत्त्युक्त्या असमर्पकाणां च बन्ध एव पर्यवसितस्तेन स्ववैषम्यमाशङ्कमानमाह -- समोऽहमिति। अहं सर्वभूतेषु समः। न मे द्वेष्यः कोऽपि। न प्रियः। अत्रायं भावः -- स्वक्रीडार्थं सर्वभूतानि मया सृष्टानि? अतस्तेषु सर्वेष्वहं समः ये क्रीडार्थकत्वमज्ञात्वाऽन्यथाकर्मादिकर्तारो मयि विषमत्वं कुर्वन्ति? अतस्तेषां त्वात्मदोषेणैव बन्धादिकं भवति ये तु मां भक्त्या स्नेहेन क्रीडारूपं ज्ञात्वा भजन्ति ते स्वभजनात्मकधर्मेण मयि तिष्ठन्ति? तेष्वहं तत्कृतितुष्टस्तिष्ठामि? तेन न वैषम्यमिति भावः।'),
('purushottama-sc:source:9.30','Puruṣottamajī','gita.9.30','sa','commentary','।।9.30।।ननु ये त्वां भजन्ति तेषु चेत्त्वं तिष्ठसि? कथं तदा ते विषयाद्यभिभूता भवन्ति इत्यत आह -- अपीति। चेत् सुदुराचारोऽपि? अनन्यभाक् मां भजते स साधुरेव मन्तव्यः।अत्रायं भावः -- विषयादिमहापापौघाचरणशीलस्तन्निवृत्तिनिमित्तान्यदेवभजनप्रायश्चित्तादिधर्मानुपायज्ञानेन अन्यभजनरहितस्तत्त्यागाशक्तस्त्यक्तुकामः स्वदैन्याविर्भावेन यो मां भजते स साधुरेव मान्यः। त्वयेति शेषः।अपि चेत् इत्यनेन तादृशाचारस्यानन्यभजनत्वे दुर्लभत्वं ज्ञापितम्। कुतः इत्यत आह -- सम्यग्व्यवसितः स पूर्वोक्तः सम्यगध्यवसायं निश्चयं यतः कृतवान् यन्मम महापातकनिवारकः श्रीकृष्णं विना नान्य इति। हीति निश्चयार्थम्। अत्र सन्देहो नास्तीत्यर्थः।'),
('purushottama-sc:source:9.31','Puruṣottamajī','gita.9.31','sa','commentary','।।9.31।।एवं प्रवृत्तस्य दुराचारादिकं नश्यतीत्याह -- क्षिप्रमिति। क्षिप्रं शीघ्रं धर्मात्मा मत्सेवनयोग्यो भवति? ततः शश्वच्छार्न्ति शाश्वतीं शान्तिं मद्रूपां नितरां भावात्मरूपेण गच्छति प्राप्नोतीत्यर्थः। तस्मात् हे कौन्तेय मत्कृपापात्र तथा दुराचरणशीलेऽपि मद्भक्ते निर्दोषभावेन साधुत्वं मत्वा मद्भक्ते दोषदृष्टिषु प्रतिजानीहि प्रतिज्ञां कुरु यन्मे भक्तो दुराचारादिदोषैर्न प्रणश्यति दोषा एव नश्यन्तीत्यर्थः। एवं मद्भक्ताधिक्यवर्णनेनाहं तुष्टो भविष्यामीति भावः।'),
('purushottama-sc:source:9.32','Puruṣottamajī','gita.9.32','sa','commentary','।।9.32।।नन्वेवं भक्ते हीनाधिकारित्वं स्यादित्यत आह -- मां हीति। हे पार्थ मातृसम्बन्धेनोत्पन्नभक्तिरूप हीति निश्चयेन मां व्यपाश्रित्य विशेषेण आश्रित्य संसेव्य ये पापयोनयोऽपि स्युः नीचयोनयः अन्त्यजादयो म्लेच्छादयश्च? स्त्रियः परतन्त्रैकयोनयः? वैश्याः केवलं कृष्यादिपरा उदरम्भराः? तथा शूद्राः शोकेन द्रवीभूता अनुपदेश्याः तेऽपि परां गतिं मोक्षं सायुज्यं यान्ति प्राप्नुवन्तीत्यर्थः। तत्रये इतिपदेन स्वसेवार्थोत्पादितातिरिक्ता इति ज्ञापितम्।'),
('purushottama-sc:source:9.33','Puruṣottamajī','gita.9.33','sa','commentary','।।9.33।।यत्र हीनाधिकारिणः परमां गतिं प्राप्नुवन्ति? तत्रोत्तमाधिकारिणां किं वक्तव्यं इत्याह -- किं पुनरिति। पुण्याः वेदोक्तमत्स्वरूपज्ञानार्थं पूर्वं वेदाध्ययनकारिणा ब्राह्मणाः? तथा पुण्यधर्मादिकरणेन प्रजापतिपालकाः राजर्षयः राजानः क्षत्ित्रया भूत्वा ऋषयः ब्रह्मकर्मनिष्ठा उत्तमाधिकारिणो भक्ताः सन्तः परां गतिं प्राप्नुवन्तीति किं पुनर्वक्तव्यम्। तेषां तु साक्षाद्भजनौपयिकत्वमेव भवतीति भावः। एतेन उत्तमाधिकारिणां तु भवत्येव यत्र हीनाधिकारिणामपि भवतीत्यनेनअधिकं तत्रानुप्रविष्टं? न तु तद्धानिः इत्ययं न्यायः प्रदर्शितः।,एतेनोत्तमानामेतदभावे हीनत्वमेवेति व्यञ्जितम्। यत उत्तमाधिकारिणामावश्यकमतस्तव क्षत्ित्रयत्वात् स्वधर्मनिष्ठत्वात् भक्तपुत्रत्वाच्चोत्तमाधिकारित्वेनावश्यं कर्त्तव्यमित्याह -- अनित्यमिति। इमं लोकमधिकरणं देहं प्राप्य अनित्यं असुखं संसारं त्यक्त्वा ज्ञात्वा वेति शेषः मां भजस्व।'),
('purushottama-sc:source:9.34','Puruṣottamajī','gita.9.34','sa','commentary','।।9.34।।भजने प्रकारमाह -- मन्मना इति। मय्येव मनो यस्य तादृशो भूत्वा मद्भक्तो मयि स्नेहयुक्तश्च सन् मद्याजी मत्पूजकः परिचर्याकरणशीलो मां नमस्कुरु। मनोनिवेशनेन मनोभजनमुक्तम्। पूजनेन कायिकम्। नमनोक्त्या वाचिकम्। ततः कायवाङ्मनोभिर्भजनं कुर्वित्युक्तम्। एवं मत्परायणः सन् आत्मानं मयि युक्त्वा युक्तं कृत्वा अवश्यं मामेव पुरुषोत्तमं एष्यसि प्राप्स्यसि। एवकारेणाक्षरांशादिप्राप्तिर्निवारिता।एवं स्वभक्तिमाहात्म्यं भजनार्थं ससाधनम्।प्रोवाच नवमेऽध्याये श्रीकृष्णो ह्यर्जुनाय तु।।9।।'),
('purushottama-sc:source:10.1','Puruṣottamajī','gita.10.1','sa','commentary','।।10.1।।नवमे भक्तिरूपं यदुक्तं तत्सिद्धये हरिः। स्वविभूतिस्वरूपं च कृपया दशमेऽब्रवीत्।।1।।पूर्वाध्याये सर्वकर्मसमर्पणमुक्तं? ततश्च भक्ितकरणमाज्ञप्तम्? तच्च स्वरूपाज्ञानेन कृतमप्यकृतप्रायमिति स्वरूपज्ञानार्थं स्वस्वरूपं स्वविभूतिरूपं वदन् पार्थं श्रवणार्थं सावधानतया सम्मुखीकुर्वन् प्रतिजानीते -- श्रीभगवानुवाच भूय एवेति। हे महाबाहो भजनौपयिककृपाशक्ितमन् भूय एव पुनरपि मम वचनश्रवणेन प्रीयमाणाय परमानन्दं प्राप्नुवते ते हितकाम्यया यदहं वक्ष्यामि तत् परमं परो मीयते ज्ञायतेऽनेनेति परमार्थरूपमुत्कृष्टं मे वचः शृणु।प्रीयमाणाय इति पदेनान्येभ्योऽवक्तव्यत्वं गोप्यत्वं च ज्ञापितम्।हितकाम्यया इतिपदेन परमकृपा दर्शिता।'),
('purushottama-sc:source:10.2','Puruṣottamajī','gita.10.2','sa','commentary','।।10.2।।अथ स्वकृपां विना अस्योक्तस्वस्वरूपस्यातिदुर्ज्ञेयत्वेन दुर्लभत्वमाह -- न म इति। मे मम प्रभवं प्रकृष्टं भवं जन्म -- प्रादुर्भावमिति यावत् -- सुरगणा ब्रह्मेन्द्रादयो महर्षयो भृग्वादयो न विदुः न जानन्ति। अहं देवानां ब्रह्मादीनां सर्वशः सर्वप्रकारैः आधिदैविकत्वेन देवत्वेन च आदिर्मूलभूतः। च पुनस्तथैव महर्षीणाम्। हीति निश्चयेन सन्देहाभावार्थं देवत्वात् ऋषित्वात् स्वमूलभूतत्वेन ज्ञानमावश्यकं? तथापि भूभारहरणार्थं स्वरक्षार्थं धर्मरक्षार्थं प्रादुर्भावं जानन्ति परं यदर्थं यद्रूपश्च प्रादुर्भावस्तं मत्कृपां विना न जानन्तीति भावः।'),
('purushottama-sc:source:10.3','Puruṣottamajī','gita.10.3','sa','commentary','।।10.3।।एवं स्वकृपां विना स्वाज्ञानात् देवानां देवत्वमपि जातं व्यर्थमेवेत्युक्त्वा स्वकृपया ज्ञानेन मनुष्याणामप्युत्तमत्वं भवतीत्याह -- यो मामजमिति। यो मां मनुष्येषु च अजं जन्मादिदोषरहितम्? अनादिं लीलादिभिर्नित्यमेवम्भूतमेव लोकमहेश्वरं लोकानां परमेश्वरं कर्तुमन्यथाकर्तुं समर्थम्? असम्मूढः प्रमादरहितः सन् जानाति स सर्वपापैः मद्भक्तिप्रतिबन्धरूपैः प्रमुच्यते प्रकर्षेण मुच्यतेः मनुष्यभावरहितो देवरूपो भवतीत्यर्थः।'),
('purushottama-sc:source:10.4','Puruṣottamajī','gita.10.4','sa','commentary','।।10.4।।एवं ये जानन्ति तेषामन्येषामजानतां च सर्वेश्वरत्वात् मत्त एव नानाविधा भावास्तत्तज्ज्ञानानुरूपा भवन्तीत्याह द्वयेन -- बुद्धिर्ज्ञानमसम्मोह इति। बुद्धिः धर्मज्ञानकौशलं? ज्ञानं स्वरूपात्मकम्? असम्मोहो मायाविलासेषु? क्षमा दुष्टादिकृतिसहिष्णुता? सत्यं आपदादिष्वपि यथार्थभाषणं? दम इन्द्रियनिग्रहः? शमः परमानन्दाप्तिरूपा शान्तिः? सुखं मद्भावानन्दरूपं? दुःखं आनन्दतिरोधानात्मकं? भवः संसारात्मकः? अभावो नाशः? भयं मृत्युकालादीनाम्। चकारेण यमयातनादयः। अभयं मच्चरणाप्त्या कालादिभयाभावः।'),
('purushottama-sc:source:10.5','Puruṣottamajī','gita.10.5','sa','commentary','।।10.5।।अहिंसा दयात्मिका? समता सर्वत्र मद्भावः? तुष्टिः सदा मद्भावसन्तोषः? तपो मदर्थक्लेशसहनं? दानं मदुपदेशादीनां? यशो मत्सेवकत्वेन सत्कीर्तिः? अयशो दुष्टत्वादिलक्षणात्मिकाऽपकीर्तिः। भूतानां एते भावाः पृथग्विधाः भिन्नाः मत्कृपाविशिष्टमज्ज्ञानवतां बुद्ध्यादयः सर्वे भवन्ति। अन्येषाप्नयशस्सहितदुःखादिचतुष्टया भावा भवन्तीति भावः।'),
('purushottama-sc:source:10.6','Puruṣottamajī','gita.10.6','sa','commentary','।।10.6।।ननु कृष्यादिप्रयुक्तधर्माचरणादिभिः सर्वेषां तत्तत्फलरूपा भावा भवन्ति? तत्कथं भवत एव इत्याकाङ्क्षायामाह -- महर्षय इति। महर्षयः सप्त भृग्वादयः? ततः पूर्वे अन्ये चत्वारो महर्षयः? तथा स्वायम्भुवादयो मनवः? हिरण्यगर्भात्मनो मम मानसा मद्भावा मदीयोऽनुभावो मत्क्रीडार्थरूपो येषु तादृशा जाताः। येषां लोके इमाः प्रजास्तदुक्तप्रवर्तमाना भवन्तीत्यर्थः। अतोऽपि मत्त एव भवन्तीति भावः।'),
('purushottama-sc:source:10.7','Puruṣottamajī','gita.10.7','sa','commentary','।।10.7।।एतन्निरूपणप्रयोजनमाह -- एतामिति। एतां मदनुभावरूपां भृग्वादिलक्षणां तां मम विभूतिं क्रीडार्थैकप्रकटिताम् च पुनः क्रीडार्थप्रकटितसामग्र्या मम योगं तत्त्वतः मल्लीलारूपेण यो वेत्ति सः? अविकम्पेन निश्चलेन मद्वियोगादिरहितेन योगेन मत्संयोगेन भक्तिरूपेण युज्यते? युक्तो भवतीत्यर्थः। नात्र संशयः? अत्र सन्देहो नास्तीत्यर्थः। अनेन सन्देहे सति न भवतीति ज्ञापितम्।'),
('purushottama-sc:source:10.8','Puruṣottamajī','gita.10.8','sa','commentary','।।10.8।।एवं ज्ञानिनो भक्तियुक्तत्वं विशदयति -- अहमिति चतुर्भिः। अहं सर्वस्य जगतः प्रभव उत्पत्तिस्थानं? सर्वं जगत् मत्तःबुद्धिर्ज्ञानं [10।4] इत्यादिरीत्या भृग्वाद्युक्तधर्मादिरीत्या च प्रवर्तते? मत्क्रीडार्थकभावयुक्तं भवतीत्यर्थः। भावंसमन्विताः मत्सेवनैकप्रयत्नवन्तः सन्तो बुधाः पण्डिता विवेकिनः? इति अमुना प्रकारेण क्रीडात्मकतया प्रकटीभूतरूपं मां भजन्ते सेवन्ते।'),
('purushottama-sc:source:10.9','Puruṣottamajī','gita.10.9','sa','commentary','।।10.9।।भजने प्रकारमाह -- मच्चित्ता इति। मय्येव चित्तं येषां ते मच्चिन्तनपराः लीलावस्थमत्स्वरूपविचारणपराः। मद्गतप्राणाः मय्येव गताः प्राप्ताः प्राणा येषां ते? मद्दुःखदुःखिता मत्सुखसुखिता इत्यर्थः। तादृशाः सन्तः परस्परं तादृशानेव मामेतादृशं स्वानुभवप्रमाणादिभिर्बोधयन्तस्तदनुकथयन्तः कीर्तनरीत्या कीर्तयन्तः। चकारेणाऽन्यकीर्त्तनं श्रृण्वन्तः। च पुनः। तद्भाने सति तुष्यन्ति ज्ञानेन वा रमन्ते च। स्वयं कीर्त्तनेनानन्दयुक्ता भवन्ति रमन्ते वा। तोषमानन्दं च प्राप्नुवन्तीति भावः। यद्वा मां विप्रयोगादिलीलावस्थासु नित्यं कथयन्तः सततं परस्परं बोधयन्तः।'),
('purushottama-sc:source:10.10','Puruṣottamajī','gita.10.10','sa','commentary','।।10.10।।एवम्भावेन भजतामहं फलं ददामीत्याह -- एवमिति। एवममुना प्रकारेण सततयुक्तानां निरन्तरं मत्कृपाविशिष्टानां प्रीतिपूर्वकमनुद्वेगेन भजतां तं बुद्धियोगं मत्स्वरूपानुभवात्मकभक्त्युपायरूपं ददामि? येन ते मामुपयान्ति प्राप्नुवन्ति। उपसर्गेण तथा यान्ति यथा तद्भावच्युतिः कदापि न भवतीति ज्ञापितम्।'),
('purushottama-sc:source:10.11','Puruṣottamajī','gita.10.11','sa','commentary','।।10.11।।नन्वन्यबोधने तेषामज्ञत्वाद्बहुकालव्यासङ्गेन सेवावियोगक्लेशः स्यादिति कथं बोधनं स्यात् इत्याशङ्क्याहतेषामेवेति। तेषामेव भक्तानामेव अनुकम्पार्थं मत्सेवाविप्रयोगक्लेशाभावार्थम्? आत्मभावस्थेषु तेषु स्वीयत्वभावयुक्तोऽहमन्येषामज्ञानजं तमः संसारात्मकं भास्वता स्फुरद्रूपेण ज्ञानदीपेन नाशयामि। ततः संसाराज्ञानविमुक्तानां शीघ्रं स्वरूपबोधात् पुनः परस्परं मद्गुणकथनेन परमानन्द एव भवति? न तु क्लेश इति भावः।'),
('purushottama-sc:source:10.12','Puruṣottamajī','gita.10.12','sa','commentary','।।10.12।।एवंन मे विदुः सुरगणाः [10।2] इत्यादिना सर्वेषां स्वावेदनयुक्तानांयो मामजमनादिं च [10।3] इत्यादिना स्वज्ञानस्योत्तमत्वं प्रतिपादितम्। ततः सर्वभावोत्पत्तिः स्वत उक्ता स्वरूपा या? स्वस्वविभूतिज्ञस्य स्वभजने स्वप्राप्तिमुक्तवान्? एतत्सर्वजिज्ञासुरर्जुनः प्रभुं विज्ञापयति सप्तभिः। विज्ञप्तेरपि भगवदात्मत्वाय षड्गुणधर्मिसमसङ्ख्यैः श्लोकैर्विज्ञापयति -- अर्जुन उवाच। परं ब्रह्मेति। परं पुरुषोत्तमाख्यं ब्रह्म बृहद्व्यापकं परं धाम पुरुषोत्तमात्मकतेजोरूपं रमणात्मगृहात्मकं वा? परमं पवित्रं सर्वोत्कृष्टं सर्वपावनम्? एतत्सर्वरूपो भवान् सत्यमेवेत्यर्थः। कथमेवमवगतं इत्यत आह -- पुरुषमिति। पुरुषं पुरुषोत्तमम्। अन्यत्रापि तथात्वमाशङ्क्य शाश्वतं नित्यमिति। अक्षरादिष्वपि नित्यत्वमाशङ्क्य दिव्यमित्याह क्रीडनैकरूपम्। अवतारादिष्वपि तथात्वमाशङ्क्याह -- आदिदेवमिति। मूलरूपमित्यर्थः। परिदृश्यमानजन्माद्याशङ्कायामाह -- अजमिति। जन्मरहितम्। जन्माभावे जन्मप्रतीतिः कथं इत्यत आह -- विभुमिति। समर्थमित्यर्थः। तथाप्रतीतिकरणसमर्थमिति भावः।'),
('purushottama-sc:source:10.13','Puruṣottamajī','gita.10.13','sa','commentary','।।10.13।।एवंविधं त्वां सर्वे वदन्तीत्यनेनावगतमित्याह -- आहुरिति। सर्वे ऋषयो भृग्वादयः? तथा देवर्षिः देवानामपि मन्त्रद्रष्टा नारदः सर्वमोक्षदः। असितः भगवद्धर्मरूपः। देवलः देवानुग्रहकृत्। व्यासः ज्ञानावतारः च पुनः स्वयमेव त्वमेव साक्षान्मे मह्यम्अहमादिर्हि देवानाम् [10।2] इत्यादिना ब्रवीषि। अतस्त्वां तथा जानामीत्यर्थः।'),
('purushottama-sc:source:10.14','Puruṣottamajī','gita.10.14','sa','commentary','।।10.14।।परोक्ते स्वानुभवाभावे न विश्वासः स्यादित्यत आह -- सर्वमेतदिति। सर्वं पूर्वोक्तं परं ब्रह्म [श्वे.उ.3।7गी.10।12] इत्यादि अहं स्वानुभवात् ऋतं सत्यं मन्ये। किञ्चन मे विदुः [10।2] इत्यादिना देवाः क्रीडारूपाः। दानवाविरोधेऽपि मोक्षदातुः हे भगवन् ते व्यक्तिं प्राकट्यं स्वरूपं वा न विदुरिति। केशव दुष्टगुणव्याप्तयोरपि मोक्षदायक यत् मां वदसि एतत्सर्वं हि निश्चयेन ऋतं मन्ये।'),
('purushottama-sc:source:10.15','Puruṣottamajī','gita.10.15','sa','commentary','।।10.15।।यतोऽन्ये न विदुरतः स्वस्वरूपं स्वयमेव जानासीत्याह৷৷৷৷৷৷৷৷৷৷৷৷৷৷৷৷৷৷. -- स्वयमेवेति। स्वयं स्वेच्छयैव? न केनचित् प्रेरितः। आत्मना स्वस्वरूपेणैव आत्मानं यादृशोऽसि तादृशं त्वमेव वेत्थ? जानासीत्यर्थः। अन्यथा ज्ञानहेतुभूतत्वेन सम्बोधयति। हे पुरुषोत्तम केन कथं वा ज्ञातुं योग्य इत्यर्थः। अतएव ब्रह्माण्डपुराणे -- नैष भावयितुं योग्यः केनचित् पुरुषोत्तम् इत्युक्तम्। ननु तर्हियो मामजमनादिं च वेत्ति [10।3] इति कथमुक्तं इत्याशङ्क्य तत्कृपया स्ववेदनात्मकस्वशक्तिदानेन ज्ञापयतीतिददामि बुद्धियोगं तम् [10।10] इत्यादिनोक्तम्। तथात्वेनैव सम्बोधयन्नाह -- भूतभावनेत्यादिभिः। हे भूतभावन भूतानि भावयसि स्वभावयुक्तानि करोषीति तथा। कथमेवं करोतीत्यत आह -- भूतेश तेषां स्वामी नियामकः तेन स्वीयत्वेन करोतीति भावः। ईशत्वेऽपि कथमेवं करोति इत्यत आह -- देवदेव पूज्यानामपि पूज्य तत्पूजादिसन्तुष्टस्तथा करोतीति भावः। तर्हि देवेष्वेव तथोचितं? न तु सर्वेष्वित्यत आह -- जगत्पते इति। जगतः सर्वस्यैव पतिः पालको रक्षक इति यावत् रक्षार्थं तथा करोतीति भावः।'),
('purushottama-sc:source:10.16','Puruṣottamajī','gita.10.16','sa','commentary','।।10.16।।एवं सम्बोध्य जगत्पतित्वेन स्वस्यापि पतित्वं सम्पाद्येदानीं स्वीयत्वेनानुग्रहं कुरु यथाऽहं पूर्वोक्तं त्वत्स्वरूपं ज्ञात्वा प्रपन्नो भवामीत्याह -- वक्तुमर्हसीति। दिव्याः क्रीडारूपाः? आत्मविभूतयः स्वविभूतयः कार्यार्थं स्वयमेवांशरूपाः? अशेषेण वक्तुं त्वमेवार्हसि योग्योऽसि। योग्यत्वोक्त्या विभूतिज्ञानमपि नान्यस्य? यत्र तत्र साक्षात् त्वदज्ञाने किं वाच्यमिति व्यञ्जितम्। यतस्त्वमेव योग्योऽस्यतः कृपया वदेति भावः। याभिर्विभूतिभिः इमान् लोकान् व्याप्य स्वीयत्वेनाङ्गीकृत्य तिष्ठसि ता वक्तुमर्हसीत्यर्थः।'),
('purushottama-sc:source:10.17','Puruṣottamajī','gita.10.17','sa','commentary','।।10.17।।कथनप्रयोजनमाह -- कथमिति। हे योगिन् सर्वव्यापक सर्वकरणसमर्थ अहं प्रकटरूपमानन्दमयं त्वां सदा परिचिन्तयन् परितो बाह्याभ्यन्तरभेदेन चिन्तयन् विभूतीः कथ विद्यां जानामीत्यर्थः।अत्रायं भावः -- साक्षाद्भगवच्चिन्तने विभूतिज्ञाने तत्र मनोनिवेशने चिन्तनविच्छेदो भविष्यतीति कथं जानामि ननु तर्हि प्रश्नः किमर्थं इत्याशङ्क्य यत्पूर्वमुक्तम्एतां विभूतिं [10।7] इत्यारभ्ययेन मामुपयान्ति ते [10।7] इत्यन्तं तेन त्वत्प्राप्त्यर्थं पृच्छामि? तत्रापि स्वाधिकारानुसारेण यत्स्वस्यावश्यकं तत्कथयेति विज्ञापयति -- केष्विति। केषु लोकेषु? च पुनः केषु भावेषु पदार्थेषु भगवन् षड्गुणैश्वर्य पूर्णगुणैः सर्वव्यापक मया चिन्तनीयोऽसि।'),
('purushottama-sc:source:10.18','Puruṣottamajī','gita.10.18','sa','commentary','।।10.18।।यच्चिन्तनात् त्वां प्राप्नोमि याथातथ्येन जानामि तादृशमात्मनो योगं पदार्थेषु क्रीडात्मकं योगम्। च पुनः। तादृशीमेव विभूतिं हे जनार्दन सर्वाविद्यानाशक पूर्वं सङ्क्षेपकथितामपि भूयो विस्तारेण कथय। हि यस्मात् अमृतं मोक्षात्मकं मरणनिवर्तकमानन्दरूपं त्वद्वाक्यं शृण्वतो मे तृप्तिः अलम्भावो न भवतीत्यर्थः।'),
('purushottama-sc:source:10.19','Puruṣottamajī','gita.10.19','sa','commentary','।।10.19।।एवं जिज्ञासुनाऽर्जुनेन प्रार्थित आह -- हन्तेति। स्वस्वरूपज्ञानार्थकतादृक्प्रार्थनया हन्तेति हर्षे। हे कुरुश्रेष्ठ भक्तवंशोद्भव दिव्याः क्रीडारूपा विभूतयः ते प्राधान्यतस्त्वद्योग्यास्त्वदर्थं कथयिष्यामि। ननु विस्तरेण कथं नोच्यते इत्यत आह -- नास्तीति। मे विभूतीनां विस्तरस्य अन्तो नास्ति। अतस्त्वत्पृष्टत्वाद्योग्या एव कथयिष्यामीति भावः।'),
('purushottama-sc:source:10.20','Puruṣottamajī','gita.10.20','sa','commentary','।।10.20।।एवं कथनं प्रतिज्ञाय प्रथमं सर्वत्र स्वयोगमाह -- अहमिति। अतन्द्रितभावेन श्रवणार्थं सम्बोध यति -- हे गुडाकेश सर्वभूतानामाशयेषु अन्तःकरणेषु स्थितः आत्मा अहम्? तेन मदात्मकात्मसम्बन्धेन सर्वेषां जीवानां विषयानन्दमारभ्य ब्रह्मानन्दानुभवान्तानन्दानुभवो भवतीत्यर्थः। त्वयाऽपि तेषु आनन्दानुभवार्थकमदंशात्मकसंयोगात्मकोऽहं चिन्तनीय इति भावः। एतच्चिन्तनं च माहात्म्यज्ञानायोपयोक्ष्यतीति भावः। ननु त्वदात्मसंयोगे नाशः कथं भवति इत्याकाङ्क्षायामाह -- अहमिति। भूतानामादि उत्पत्तिस्थानं,चाहम्? च पुनः मध्यं स्थितिः। अन्तश्च लयस्थानमहमेव। यतो मदिच्छया मत्क्रीडार्थमुत्पादिताः यावत्क्रीडनं च रक्षिताः? क्रीडोपसंहारेच्छायां च लयं प्रापिता अतो न दोष इति भावः। मयोत्पादितानां मदात्मांशसंयुक्तानामन्यतो नाशेऽन्यलीनत्वे दोषः स्यात्? न तु मयि लीनानाम्। इदमेवैवकारेण द्योतितम्। अत एव निर्दोषभावेन मदंशात्मसंयोगं सर्वेषु चिन्तयेति भावः।'),
('purushottama-sc:source:10.21','Puruṣottamajī','gita.10.21','sa','commentary','।।10.21।।योगयुक्ता विभूतीः कथयति -- आदित्यानामित्यारभ्य यावदध्यायसमाप्ति। आदित्यानां द्वादशानां मध्ये विष्णुः व्यापकधर्मात्मको बिम्बप्रकाशकोऽहं ज्योतिषां बहिर्जगत्प्रकाशकानां मध्ये अंशुमान् सर्वप्रकाशकरश्मियुक्तो रविः सूर्योऽस्मीत्यर्थः। मरुतां वायूनां मध्ये मरीचिर्नाम कश्चन सर्वसुखोत्पादनरूपो वायुरस्मि। नक्षत्राणां मध्ये शशी चन्द्रोऽस्मि।शशी इति नाम्ना रोहिण्यासक्तिजलाञ्छनवत्त्वेन रसात्मकासक्तिधर्मरूपशृङ्गाररसात्मकत्वं व्यञ्जितम्।'),
('purushottama-sc:source:10.22','Puruṣottamajī','gita.10.22','sa','commentary','।।10.22।।वेदानां चतुर्णामपि मध्ये सामवेदोऽस्मि। गानात्मकमाधुर्यरसवत्त्वेनाऽधिक्यं तत्रेति भावः। देवानां मध्ये वासव इन्द्रोऽस्मि? शतमखत्वेन सर्वक्रियांशभोक्तृत्वेन राज्यभोक्तृत्वेन च। इन्द्रियाणां आधिदैविकेन्द्रियरूपोऽस्मि। च पुनः सर्वप्रेरकत्वान्मनोऽस्मि। भूतानां चेतनानां चेतना ज्ञानशक्तिरस्मि।'),
('purushottama-sc:source:10.23','Puruṣottamajī','gita.10.23','sa','commentary','।।10.23।।रुद्राणां तामसानामेकादशानां च मध्ये शङ्करः सुखकरः सर्वेषां भक्तिज्ञानोपदेशकोऽस्मि। यक्षरक्षसां वित्तेशः कुबेरोऽस्मि। वसूनां मध्ये मुख्यतया द्रोणोऽस्मि। अतएवद्रोणो वसूनां प्रवरः इति श्रीभागवते [10।8।48] उक्तम्। च पुनः पावकः अग्निरस्मि। शिखरिणां शिखरवतामुच्चानां मध्ये मेरुरहमस्मि।'),
('purushottama-sc:source:10.24','Puruṣottamajī','gita.10.24','sa','commentary','।।10.24।।हे पार्थ पुरोधसां च मध्ये मुख्यं बृहस्पतिं मां विद्धि। पार्थेति सम्बोधनेन पृथासम्बन्धेन त्वयि कृपां करोमि। तथा निन्दिते पौरोहित्येऽपि देवक्रियया तस्मिन् बुद्ध्यादिशक्तिरूपेण तिष्ठामि? तेन मत्स्वरूपं विद्धीति व्यञ्जितम्। सेनानीनां सेनामध्ये देवसेनापतित्वात् स्कन्दोऽस्मि। सरसां रसयुतानां स्थिरजलानां मध्ये सागरः समुद्रोऽस्मि? रत्नाकर इत्यर्थः।'),
('purushottama-sc:source:10.25','Puruṣottamajī','gita.10.25','sa','commentary','।।10.25।।महर्षीणां सर्ववेदात्मको भृगुरस्मि। गिरां पदात्मकानां मध्ये एकाक्षरम् कारात्मकमहमस्मि। यज्ञानां कर्मणां मध्ये जपयज्ञोऽस्मि। स्थावराणामचलानां हिमालयोऽस्मि।'),
('purushottama-sc:source:10.26','Puruṣottamajī','gita.10.26','sa','commentary','।।10.26।।सर्ववृक्षाणां मध्ये अश्वत्थः पिप्पलोऽस्मि। देवर्षीणां देवमन्त्रद्रष्टृ़णां मध्ये मदिङ्गितोपदेशकत्वान्नारदोऽस्मि। गन्धर्वाणां गायकानां मध्ये चित्ररथोऽस्मि। सिद्धानां अघिगतपरमार्थानां मध्ये स्वतोऽधीतपरमार्थरूपः कपिलो मुनिरस्मि।'),
('purushottama-sc:source:10.27','Puruṣottamajī','gita.10.27','sa','commentary','।।10.27।।अश्वानां अमृतमथने अमृतसङ्गोत्पन्नमुच्चैश्श्रवसं मदंशं विद्धि। गजेन्द्राणां ऐरावतं विद्धि। नराणां मध्ये पालकं नरं राजानं विद्धि।'),
('purushottama-sc:source:10.28','Puruṣottamajī','gita.10.28','sa','commentary','।।10.28।।आयुधानां शस्त्राणां मध्ये वज्रं अस्मि। धेनूनां दोग्ध्रीणां कामधुक् कामधेनुरस्मि। प्रजनः प्रजोत्पादकः कन्दर्पश्च कामोऽस्मि। चकारेण केवलसम्भोगहेतुर्निवारितः। सर्पाणां विषधराणां गतिमतां वा वासुकिरस्मि।'),
('purushottama-sc:source:10.29','Puruṣottamajī','gita.10.29','sa','commentary','।।10.29।।नागानां अविषाणां स्थिराणां मध्ये अनन्तस्तेषामधीशः शेषोऽस्मि। यादसां जलचराणां पतिर्वरुणोऽस्मि। पितृ़णां मुख्यः अर्यमा चास्मि। चकारेण सर्वेषां पितृरूपत्वमपि ज्ञापितम्। संयमतां नियमं कुर्वतां मुख्यो यमोऽस्मि।'),
('purushottama-sc:source:10.30','Puruṣottamajī','gita.10.30','sa','commentary','।।10.30।।दैत्यानां च असम्भावितत्वात् मध्ये दैत्यकुलोद्धारकः प्रह्लादोऽस्मि। कलयतां व्याकुर्वतां,कालोऽहमस्मि। मृगाणां मृगेन्द्रः सिंहः। पक्षिणां पक्षवतां मध्ये वैनतेयस्तेषां राजा गरुडोऽस्मि।'),
('purushottama-sc:source:10.31','Puruṣottamajī','gita.10.31','sa','commentary','।।10.31।।पवतां वेगवतां मध्ये पवनः वायुरस्मि। शस्त्रभृतां रामः दशरथात्मजोऽस्मि। झषाणां मध्ये मकरः मत्स्यजातिविशेषोऽस्मि। स्रोतसां प्रवहज्जलानां मध्ये जाह्नवी गङ्गाऽस्मि।'),
('purushottama-sc:source:10.32','Puruṣottamajī','gita.10.32','sa','commentary','।।10.32।।सर्गाणामिति। सृज्यन्त इति सर्गा भूतादयश्च। स त्रिविधः कार्यसर्गः कारणसर्गः लीलात्मकश्च। तत्र कार्यसर्गो लौकिको बहिस्सृष्टिरूपः? स च जीवनाशरूपत्वात् प्रलयात्मकः। कारणसर्गस्तु मोक्षात्मकत्वादलौकिकः। तृतीयो भगवल्लीलात्मकः। तत्राऽप्यवान्तरभेदास्तत्त्वकालजीवादिरूपाः सन्ति तेषां सर्गाणां मध्ये आदिः कारणरूपोऽहम्। च पुनः। अन्तः रजोगुणात्मकब्रह्मकृतोऽन्तात्मकोऽप्यहम्। मध्यं लीलात्मसर्गोऽहमेव? च मत्स्वरूपमेवेत्यर्थः। हे अर्जुन मुक्त्यधिकारजातीय असताममुक्त्यर्थमेव सर्गत्रयं मद्रूपत्वेन चिन्तयेत्यर्थः।अध्यात्मेति। विद्यानां सर्वासां मध्ये अध्यात्मविद्याऽहमस्मि। प्रवदतां वादिनां वादः? वितण्डाजल्पपक्षत्रयमध्ये वादस्तत्त्वस्वरूपनिर्णयात्मकोऽहमस्मि।'),
('purushottama-sc:source:10.33','Puruṣottamajī','gita.10.33','sa','commentary','।।।10.33।।अक्षराणां वर्णानां मध्ये अकारोऽस्मि? सर्वाक्षरगतत्वात्। सामासिकस्य समाससमूहस्य मध्ये द्वन्द्वःगोपीमाधवौ इत्यादिरस्मि। अक्षयः लीलात्मकोऽलौकिकः कालोऽहमेवास्मि। एवकारेण तस्य साक्षात्स्वरूपात्मकत्वाद्विभूतित्वे किं वाच्यमिति ज्ञापितम्। विधातृ़णां मध्ये विश्वतोमुखः सर्वतोमुखश्चतुर्मुखो धाता अलौकिकसृष्टिकर्त्ताऽहमस्मीत्यर्थः।'),
('purushottama-sc:source:10.34','Puruṣottamajī','gita.10.34','sa','commentary','।।10.34।।मृत्युरिति। संहारिणां मध्ये सर्वसंहारकोऽहम्। च पुनः मृत्युरपि। भविष्यतां निखिलानां प्राणिनां पदार्थानां उद्भवोऽभ्युदयः भाग्यरूपोऽहम्।कीर्तिरिति। कीर्तिः धर्मस्य स्त्री? श्रीः लक्ष्मीः? वाक् सरस्वती श्रीभागवतादिरूपा? स्मृतिर्भगवत्स्मरणात्मिका? मेधा बुद्धिः भगवद्गुणैकनिष्ठा? धृतिः आपत्सु धर्मैकनिष्ठता? क्षमा सर्वातिक्रमसहनरूपा? नारीणां मध्ये एता मद्विभूतिरूपाः।'),
('purushottama-sc:source:10.35','Puruṣottamajī','gita.10.35','sa','commentary','।।10.35।।साम्नां सामऋचां मध्ये बृहत्साम मद्विभूतिरित्यर्थः। छन्दसां मध्ये गायत्री मद्विभूतिः। मासानां मध्ये मार्गशीर्षोऽहम्। ऋतूनां मध्ये कुसुमाकरो वसन्तोऽस्मि।'),
('purushottama-sc:source:10.36','Puruṣottamajī','gita.10.36','sa','commentary','।।10.36।।द्यूतमिति। छलयतां वञ्चकानां मध्ये द्यूतमस्मि? येन क्रीडाक्षात्त्रादिधर्मज्ञानेन मोहितो जानन्नपि वञ्चति। तेजस्विनां प्रभावतां मध्ये तेजः प्रभा अहमस्मि। जयतां मध्ये जयोऽस्मि। व्यवसायिनामुद्यमवतां निश्चयवतां वा व्यवसायः उद्यमः निश्चयो वाऽस्मि। सत्त्ववतां सात्त्विकानां मध्ये सत्त्वमहम्।'),
('purushottama-sc:source:10.37','Puruṣottamajī','gita.10.37','sa','commentary','।।10.37।।वृष्णीनामिति। वृष्णीनां यादवानां सर्वेषां मध्ये हृदये वासुदेवः सर्वमोक्षदाता क्रीडार्थम् अंशैरस्मि? सर्वे यादवा मद्विभूतिरूपा इत्यर्थः। पाण्डवानां मध्ये धनञ्जयस्त्वमेवास्मि। मुनीनां ब्रह्ममननशीलानां मध्ये व्यासः कृष्णद्वैपायनोऽस्मि। कवीनां निर्दुष्टस्वरशब्दप्रदर्शिनां मध्ये उशना कविः शुक्रोऽस्मि।'),
('purushottama-sc:source:10.38','Puruṣottamajī','gita.10.38','sa','commentary','।।10.38।।दण्ड इति। दमयतां दमकारिणां मध्ये दण्डोऽस्मि? सर्वदोषहरत्वेनेति भावः। जिगीषतां जेतुमिच्छतां नीतिरस्मि। गुह्यानां गोप्यानां मध्ये मौनमवचनमस्मि। ज्ञानवतां ज्ञानिनां मध्ये ज्ञानमहमस्मि।'),
('purushottama-sc:source:10.39','Puruṣottamajī','gita.10.39','sa','commentary','।।10.39।।यदिति। यत्सर्वभूतानां बीजमुत्पत्तिकारणं तदपि अहमेव। अपिशब्देन योनिस्तद्रूपं चाऽहमेवेति व्यञ्जितम्। यत् चराचरं भूतं तज्जातं तन्मया विना किञ्चिन्नास्ति।'),
('purushottama-sc:source:10.40','Puruṣottamajī','gita.10.40','sa','commentary','।।10.40।।एवं विभूतिमुक्त्वोपसंहरति -- नान्तोऽस्तीति। मम स्वच्छन्दचारिणो दिव्यानां क्रीडात्मिकानां विभूतीनामन्तो नास्ति। परन्तपेति सम्बोधनं विश्वासार्थम्। नन्वन्ताभावे कथमेता एवोक्ताः इत्याकाङ्क्षायामाह -- एष इति। एष तूद्देशतः सङ्क्षेपतो विभूतेर्विस्तरो मया प्रोक्तः। प्रोक्तत्वेनान्येषामेतावज्ज्ञानेऽप्यसामर्थ्यं,द्योतितम्।'),
('purushottama-sc:source:10.41','Puruṣottamajī','gita.10.41','sa','commentary','।।10.41।।ननु मया सर्वस्वरूपज्ञानेन सर्वत्र त्वच्चिन्तनार्थं विभूतिविस्तारः पृष्टः? तस्यान्ताभावोक्त्या मया कुत्र कथं चिन्तनीयः इत्याकाङ्कायामाह -- यद्यदिति। यत् यत् सत्त्वं वस्तुमात्रं विभूतिमत् ऐश्वर्ययुक्तं श्रीमत् सम्पत्तियुक्तं ऊर्जितमेव केनापि प्रकारेणोत्कृष्टतां प्राप्तं रमणीयतरं वा तत्तदेवं मम तेजोंशसम्भवं ममानुभावसम्भूतं अवगच्छ जानीहि।');
INSERT INTO commentary_fts (unit_id,author,canonical_ref,language,content_type,content) VALUES
('purushottama-sc:source:10.42','Puruṣottamajī','gita.10.42','sa','commentary','।।10.42।।एवं विभूत्यादिमत्सु भगवदंशज्ञानेनान्यत्र हेयत्वादिबुद्धौ सर्वस्य भगवदात्मकत्वं भज्येतेत्यन्यं प्रकारमाह -- अथवेति। अथवा पक्षान्तरेण। हे अर्जुन तव बहुना नानाविधेन ज्ञातेन किं कार्यम् न किमपीत्यर्थः। यत एतेन नानाज्ञानेन न किञ्चित् कार्यम्? अतः कार्योपयोगिस्वरूपमाह -- इदं परिदृश्यमानं जगत् कृत्स्नं सम्पूर्णं एकांशेन क्रीडात्मकेन विष्टभ्य धृत्वा स्थितोऽस्म्यहमेवेत्यर्थः। अनेन सर्वं मत्क्रीडारूपमेव चिन्तयेति भावो बोधितः।प्रतीयते जगन्नानाविधं स्वाज्ञानभावतः।विभूतिरूपं श्रीकृष्णस्तन्नाशायाऽब्रवीन्नरम्।।10।।इति श्रीभगवद्गीतामृततरङ्गिण्यां दशमोऽध्यायः।।10।।'),
('purushottama-sc:source:11.1','Puruṣottamajī','gita.11.1','sa','commentary','।।11.1।।कृष्णात्मत्वं हि जगतो विभूतिकथनान्नरः। अवगत्य च तद्रूपं द्रष्टुं हरिमथाऽब्रवीत्।।1।।पूर्वाध्यायान्तेविष्टम्याहं [10।42] इत्यनेन स्वक्रीडात्मकत्वेन विश्वस्य स्वात्मकत्वं प्रतिपादितम्? तद्रूपदर्शनेच्छुरर्जुनो भगवन्तं विज्ञापयति -- मदनुग्रहायेति चतुर्भिः। मदनुग्रहाय मम स्वीयत्वेन ग्रहणाय परमं परः पुरुषोत्तमो मीयते अनुमीयते यस्मात्तादृशम्। अतएव गुह्यं सर्वेषामनाख्येयम्। अध्यात्मसंज्ञितं आत्मानात्मविवेकविषयत्वेन सर्वात्मरूपं यत् त्वया वचोविष्टभ्याहं इत्युक्तं? तेन ममाऽयं रूपे मोहो विशेषेण गतो नष्ट इत्यर्थः।'),
('purushottama-sc:source:11.2','Puruṣottamajī','gita.11.2','sa','commentary','।।11.2।।किञ्च -- भवाप्ययाविति। भूतानां भवाप्ययौ उत्पत्तिनाशौअहमादिश्च [10।20] इत्यादिना हे कमलपत्राक्ष दृष्ट्यैव तापनाशक त्वत्तो मया विस्तरशः श्रुतौ। अव्ययं स्थितिरूपं पालनरूपं माहात्म्यं महत्त्वं नाशानन्तरपालनरूपं चापि श्रुतं?तेन मोहो नष्टः इति पूर्वेणैवान्वयः।'),
('purushottama-sc:source:11.3','Puruṣottamajī','gita.11.3','sa','commentary','।।11.3।।कथं ज्ञातव्यं मोहो नष्ट इति इत्याशङ्कृय नष्टमोहानां भगवद्वाक्ये विश्वासो नियत इति तदाह -- एवमिति। हे परमेश्वर सर्वाधीश यथा त्वमात्मानं स्वस्वरूपमात्थ वदसिन मे विदुः [10।2] इत्यनेन सर्वाज्ञातत्वं?विष्टभ्याहम् [10।42] इत्यनेन सर्वात्मत्वंददामि बुद्धियोगं तं [10।10] इत्यादिना स्वकृपयैव ज्ञातत्वम्? एवमेतत् यथार्थमेवेत्यर्थः। यथार्थत्वोक्त्या पूर्वमज्ञातस्वरूपोऽहम्? अधुना विभूतिनिरूपणेनविष्टभ्याहं इति कृपोक्त्या च तच्चिन्तनेन सर्वात्मत्वज्ञानयुक्तो जात इति स्वानुभवो व्यञ्जितः। अथातो ज्ञातस्वरूपस्तद्रूपं दर्शयेत्याह -- द्रष्टुमिति। हे पुरुषोत्तम ते तवैव तत्सम्बन्धिनामैश्वरं नानाविलासकं रूपं द्रष्टुमिच्छामि।'),
('purushottama-sc:source:11.4','Puruṣottamajī','gita.11.4','sa','commentary','।।11.4।।स्वेच्छायां सत्यामपि भगवदिच्छाभावे च द्रष्टुमपि निर्बन्धेन न फलतीति विज्ञापयति -- मन्यस इति। हे प्रभो सर्वकरणसमर्थ यदि तद्रूपं मया द्रष्टुं शक्यं दर्शनानन्तरं फलरूपं भवति तथा चेन्मन्यसे फलरूपं भवत्विति? तदा योगेश्वर योगिनः स्वयोगबलेन सामर्थ्यं प्रकटयन्ति तेषां योग आगन्तुको धर्मः त्वं तु योगस्यापीश्वरस्तेन मम दर्शनसामर्थ्यमपि कृपया दत्त्वा दर्शय। एवं प्रार्थनायां प्रभुस्तद्रूपं दर्शयित्वा तत्रैव लीनं कुर्यात् तदा भक्तिरसानुभूतपुरुषोत्तमरूपानुभवो न भवेदतो विज्ञापयति -- तत इति। तत एतन्मनोरथपूर्त्यनन्तरम्। अव्ययमविनाशिनं आत्मानं पुरुषोत्तममानन्दमयं दर्शयेति भावः।'),
('purushottama-sc:source:11.5','Puruṣottamajī','gita.11.5','sa','commentary','।।11.5।।एवं प्रार्थितः सन् तद्रूपं दर्शयिष्यन्नर्जुनं सावधानं करोति भगवान् -- पश्येत्यादिचतुर्भिः। हे पार्थ भक्तपुत्र कृपया दर्शयामीति सम्बोधनम्। अन्यथा पुरुषोत्तमदर्शनतोऽन्यदर्शनेच्छायामेतद्रसानुभवमपि न कारयेदिति भावः। मे मम शतशः सहस्रशः असङ्ख्यातानि? शतशः सहस्रशः यावदिच्छसि तावद्वा? नानाविधानि नानाफलकारकाणि रूपाणि यस्य नानाविधान्यपि दिव्यानि अलौकिकानि क्रीडात्मकानि? न तु प्रदर्शनार्थमेव कृतानि च पुनः तथैव नानावर्णाकृतीनि नाना अनेके वर्णाः शुक्ललोहितादयः आकृतयः अवयवादिविशेषाश्च येषां तानि।'),
('purushottama-sc:source:11.6','Puruṣottamajī','gita.11.6','sa','commentary','।।11.6।।तान्येव पश्येति नामभिर्विशेषेणाह -- पश्येति। आदित्यान् द्वादशात्मकान्? वसून् अष्टसङ्ख्याकान्? रुद्रानेकादशसङ्ख्यान्? अश्िवनौ अश्िवनीकुमारौ? मरुतः देवगणविशेषान् तथा बहून्यसङ्ख्येयानि अदृष्टपूर्वाणि सर्वैः? आश्चर्याणि अलौकिकानि हे भारत उत्तमवंशोद्भव योग्यत्वात् पश्य।'),
('purushottama-sc:source:11.7','Puruṣottamajī','gita.11.7','sa','commentary','।।11.7।।किञ्च -- इहेति। कोटिजन्मभिरपि सम्पूर्णं द्रष्टुमशक्यं कृत्स्नं समस्तं जगत् विरुद्धत्वेन परिदृश्यमानमपि मम देहे एकस्थमेकत्र स्थितं सचराचरं जडजीवसहितं इह अस्मिन्नेव जन्मनि। अद्य तत्कालमेव यच्च अन्यत् सर्वेषां विभूतित्वेन कथं मारयामीति विचारेण मरणमारणादिरूपं यत् द्रष्टुमिच्छसि तत्पश्य।'),
('purushottama-sc:source:11.8','Puruṣottamajī','gita.11.8','sa','commentary','।।11.8।।एवमुक्ते दर्शनोद्यतं प्रत्याह -- नत्विति। तु पुनः एवमेव द्रष्टुं न शक्यसे न शक्तोऽसि। अतस्ते दिव्यमलौकिकं चक्षुर्ददामि। तेन स्वचक्षुषा मत्कृपादृष्ट्या मां पुरुषोत्तमं पश्य। अतो दृष्टपुरुषोत्तमेन अनेनैव मे ऐश्वरं करणाकरणान्यथाकरणसामर्थ्यरूपं योगयुक्तं पश्य। पुरुषोत्तमस्वरूपज्ञानदर्शनाभावे सर्वस्वरूपदर्शनं न स्यात्? पुरुषोत्तमदर्शनं चासाधारणदृष्ट्या भवेदिति भावः।'),
('purushottama-sc:source:11.9','Puruṣottamajī','gita.11.9','sa','commentary','।।11.9।।एवमुक्त्वा अर्जुनाय स्वरूपं दर्शयामास भगवानिति धृतराष्ट्रं प्रति सञ्जय उवाच -- एवमिति। राजन्याभिमानेन दिव्यदृष्ट्यसुरावेशिभीष्मादिमारणेन सर्वदुःखनिराकरणार्थं महायोगेश्वरः सर्वकरणसमर्थः सर्वात्मकयोगबलेन एवमुक्त्वा अलौकिकीं दृष्टिं दत्त्वा पार्थाय स्वाङ्गीकृताय परमं रूपं पुरुषोत्तमरूपं दर्शयामास। ततस्तद्दर्शनानन्तरं ऐश्वरं रूपं दर्शयामास।'),
('purushottama-sc:source:11.10','Puruṣottamajī','gita.11.10','sa','commentary','।।11.10।।उभयोः स्वरूपमाह -- अनेकेति। अनेकानि वक्त्राणि नयनानि च यस्मिंस्तत्? निखिललीलात्मकरूपसहितम्। अनेकाद्भुतदर्शनं अनेकानि अलौकिकानि लीलामयानि दर्शनानि यस्मिंस्तत्। अनेकानि दिव्यानि अलौकिकानि आभरणानि यस्मिंस्तत्। दिव्यानि अलौकिकानि अनेकानि उद्यतानि सकलदुःखनिवारकाणि आयुधानि शङ्खगदादीनि यस्मिंस्तत्।'),
('purushottama-sc:source:11.11','Puruṣottamajī','gita.11.11','sa','commentary','।।11.11।।दिव्यानि क्रीडोपयुक्तानि माल्यानि अम्बराणि बिभर्तीति तथा। दिव्यः क्रीडोद्भूतो गन्धो यस्य तादृशमनुलेपनं यस्य तत्। सर्वाश्चर्यमयं दुर्वितर्क्यं देवं सर्वपूज्यम्? अनन्तमपरिच्छन्नम् व्यापकम्। विश्वतोमुखं सर्वं पश्यन्तं सर्वसन्मुखम्।'),
('purushottama-sc:source:11.12','Puruṣottamajī','gita.11.12','sa','commentary','।।11.12।।तस्य स्वरूपस्याऽप्रमेयं तेजस्स्वरूपमाह -- दिवीति। दिवि स्वर्गे सूर्यसहस्रस्य युगपत् एकदैव उदितस्य युगपदेव उत्थिता भाः प्रभा यदि भवेत् सा तस्य महात्मनः पुरुषोत्तमस्य अनेकात्मरूपस्य भासः सदृशी स्यात्। किन्तु न स्यादेवेति काकूक्तिः। एतादृशं स्वरूपम्।'),
('purushottama-sc:source:11.13','Puruṣottamajī','gita.11.13','sa','commentary','।।11.13।।तत्र तस्मिन्नेव रूपे? एकस्थमेकत्र स्थितं कृत्स्नं सम्पूर्णं जगत्? अनेकधा प्रविभक्तं नानाप्रकारविभागयुक्तं दर्शयामासेति पूर्वेणैवान्वयः। यदा दर्शितं तदा देवदेवस्य पूज्यानामपि पूज्यस्य शरीरे पूर्वप्रतीयमानसूक्ष्मरूप एव पाण्डवः अर्जुनः अपश्यत् दृष्टवान्।'),
('purushottama-sc:source:11.14','Puruṣottamajī','gita.11.14','sa','commentary','।।11.14।।दर्शनानन्तरं किं कृतवानित्यत आह -- तत इति। ततस्तदनन्तरं स पूर्वोक्तः प्राप्तदिव्यदृष्टिः विस्मयाविष्टः। आश्चर्यरसनिमग्नः हृष्टरोमा उत्पुलकिताङ्गः अन्तरानन्दयुक्तः धनञ्जयः प्रादुर्भूतविभूतिरूपः शिरसा मस्तकेन देवं पूज्यं नमस्करणीयं प्रणम्य नमस्कृत्य कृताञ्जलिः विनीतः सन् अभाषत विज्ञप्तिं कृतवान्।'),
('purushottama-sc:source:11.15','Puruṣottamajī','gita.11.15','sa','commentary','।।11.15।।तद्वाक्यमेवाह -- पश्यामीति सप्तदशभिः। हे देव पूज्य तव देहे उपचितस्वरूपे देवान् इन्द्रादीन् क्री़डामयान्? तथा क्रीडात्मकानेव सर्वान् भूतविशेषाणां चतुर्विधानां सङ्घान् समूहान्। दिव्यान् क्रीडार्थप्रकटितान्? ऋषीन् नारदादीन्? पुनस्तामसान् उरगान् शेषादीन्? तन्मूलभूतं कमलासनस्थं नाभिपद्मस्थं? ब्रह्माणम्? ईशं महादेवम्? एवमेतान् सर्वान् पश्यामि।'),
('purushottama-sc:source:11.16','Puruṣottamajī','gita.11.16','sa','commentary','।।11.16।।यस्य देहे न एतान् पश्यामि तादृशं त्वां च पश्यामीत्याह भ्रमाभावाय -- अनेकेति। अनेकानि बाह्वादीनि यस्य। सर्वतोऽनन्तानि रूपाणि यस्यैतादृशं त्वां पश्यामि। तादृशानेकरूपस्यापि तव अन्तं पूर्णभावं?,मध्यं स्थितिस्थानम्? आदिमुत्पत्तिस्थानं न पश्यामि। विश्वेश्वर विश्वपरिपालक किं बहुना विश्वरूपं पश्यामि।'),
('purushottama-sc:source:11.17','Puruṣottamajī','gita.11.17','sa','commentary','।।11.17।।किञ्च किरीटिनं मुकुटालङ्कारयुक्तं रसात्मकम्। गदिनं सकलप्राणाधिदैविकधर्मधारिणम्। चक्रिणं तेजोरूपसुदर्शनधारिणम्। चकारेण तद्वत् मोक्षदानार्थमपि चक्रधारित्वं ज्ञापितम्। तेजोराशिं तेजःपुञ्जात्मकम्। सर्वतो दीप्तिमन्तं परित उद्दीपककिरणयुक्तम्। तेजोयुक्तत्वे दीप्तियुक्तत्वे च दृष्टान्तमाह -- दीप्तानलार्कद्युर्ति दीप्तौ यावनलार्कौ तयोर्द्युतिरिव द्युतिर्यस्य तादृशम्। अप्रमेयं प्रमातुमयोग्यं त्वां समन्तात् दुर्निरीक्ष्यं पश्यामि।'),
('purushottama-sc:source:11.18','Puruṣottamajī','gita.11.18','sa','commentary','।।11.18।।एवम्भूतस्वरूपदर्शनेन स्वज्ञानार्थं निवेदयति -- त्वमिति। अक्षरं अक्षरस्वरूपं त्वमेव परमं ब्रह्म। त्वं वेदितव्यं भक्तानां ज्ञानिनां ज्ञेयरूपस्त्वमेव। अक्षरत्वेन सर्वोत्पत्तिकारणता निरूपिता। लयस्वरूपमाह -- त्वमस्यविश्वस्य परमुत्कृष्टं मोक्षरूपं निधानं निधीयतेऽस्मिन्निति लयस्थानम्। पालकत्वमाह -- शाश्वतस्य नित्यस्य धर्मस्य गोप्ता पालको रक्षकस्त्वम्। एवमपि न गुणात्मकः? किन्तु अव्ययोऽविनाशी नित्यः। एवं सर्वधर्मानुक्त्वा मुख्यं स्वनिश्चिततामाह -- सनातनः पुरुषः पुरुषोत्तमो मे मम मतः सम्मत इत्यर्थः।'),
('purushottama-sc:source:11.19','Puruṣottamajī','gita.11.19','sa','commentary','।।11.19।।एवं पुरुषोत्तममुक्त्वा दृष्टं विश्वरूपमाह -- अनादीत्यादिना। अनादिमध्यान्तं न विद्यते आदिर्मध्यं अन्तश्च यस्य उत्पत्तिस्थितिप्रलयरहितम्? -- अनन्तं वीर्यं पराक्रमो यस्य तम्। अनन्तबाहुं अनन्ताः क्रियाशक्तयो यस्य? शशिसूर्यनेत्रं शशिसूर्यौ नेत्रे यस्य? दीप्तहुताशवक्त्रं दीप्तो धूमादिरहितो हुताशः अग्निर्वक्त्रेषु यस्य तम्? स्वतेजसा इदं परिदृश्यमानं विश्वं तपन्तं तेजोयुक्तं त्वां पश्यामि।'),
('purushottama-sc:source:11.20','Puruṣottamajī','gita.11.20','sa','commentary','।।11.20।।किञ्चद्यावापृथिव्योरिति। इदं द्यावापृथिव्योः अन्तरमन्तरिक्षं एकेन त्वया व्याप्तम्। च पुनः? दिशः सर्वास्त्वया व्याप्ताः पश्यामि। किञ्च हे महात्मन् इतोऽप्यधिकप्रकटनसमर्थ तव इदमद्भुतमलौकिकं उग्रं अदृष्टं रूपं दृष्ट्वा लोकत्रयं प्रव्यथितं प्रकर्षेण व्यथितं भीतं पश्यामीति पूर्वेणान्वयः।'),
('purushottama-sc:source:11.21','Puruṣottamajī','gita.11.21','sa','commentary','।।11.21।।किञ्चअमी हीति। अमी सुरसङ्घाः देवसमूहाः त्वां त्वत्समीपे विशन्ति शरणमागच्छन्तीत्यर्थः। हीति युक्तमेव पुरुषोत्तमशरणागमनं देवानाम्। केचित् इतरे असुरा इत्यर्थः? भीताः सन्तः प्राञ्जलयो बद्धाञ्जलिपुटाः गृणन्ति? रक्षेति वदन्तीत्यर्थः। महर्षिसिद्धसङ्घाः महर्षीणां सिद्धानां च समूहाःस्वस्ति अस्माकमस्तु इत्युक्त्वा पुष्कलाभिः पूर्णाभिः स्तुतिभिस्त्वां स्तुवन्ति।'),
('purushottama-sc:source:11.22','Puruṣottamajī','gita.11.22','sa','commentary','।।11.22।।No commentary.'),
('purushottama-sc:source:11.23','Puruṣottamajī','gita.11.23','sa','commentary','।।11.23।।किञ्चरूपमिति। हे महाबाहो महत्कृपाशक्तियुक्त ते रूपं दृष्ट्वा लोकास्त्वत्स्वरूप एव स्थिताः प्रव्यथिताः? भीता इत्यर्थः। तथाऽहं च प्रव्यथितः। भयजनकत्वेन रूपं वर्णयति -- बह्वित्यादिविशेषणैः। बहूनि वक्त्राणि नेत्राणि च यस्मिन्। बहवः बाहव ऊरवः पादाश्च यस्मिन्। बहूनि उदराणि यस्मिन्। बह्वीभिर्द्रंष्ट्राभिः करालं भयानकम्। वक्त्रबाहुल्येन गिलनसामर्थ्यं? नेत्रबाहुल्येन सर्वतो दर्शनसामर्थ्यं? तेन निलायनाद्यशक्यत्वम्? क्रियाबाहुल्येन ग्रहणसामर्थ्यम्? ऊरुपादबाहुल्येन धावनसामर्थ्यं? तेन पलायनाद्यशक्तत्वम् उदरबाहुल्येन जारणसामर्थ्यम्? दंष्ट्राबाहुल्येन चर्वणसामर्थ्यं द्योतितम्। अत एवंविधं दृष्ट्वा त्वद्रूपस्थाश्चेल्लोकाः प्रव्यथितास्तदा मम कः सन्देह इति तथेति पदेन द्योतितम्।'),
('purushottama-sc:source:11.24','Puruṣottamajī','gita.11.24','sa','commentary','।।11.24।।किञ्च केवलस्वाधिष्ठितदेहाध्यासेन जीवस्यैव न भयं? किन्तु त्वदंशस्यान्तरात्मनोऽपि भयं समुत्पन्नमित्याह -- नभस्स्पृशमिति। नभ आकाशं स्पृशति तदाकाशव्यापि ज्ञातुमशक्यम्। दीप्तं प्रज्वलत्तेजोराशिं ध्यानैकयोग्यम्। अनेकवर्णम् अनेके शुक्ललोहितादयो वर्णा यस्य तं निश्चययोग्यम्। व्यात्ताननं व्यात्तानि प्रसारितानि आननानि यस्य तं प्रार्थनायोग्यम्? दीप्तविशालनेत्रंदीप्तानि ज्वलद्रूपाणि विशालानि नेत्राणि यस्य तं दर्शनायोग्यम्। एतादृशं त्वां दृष्ट्वा प्रव्यथितः अतरात्मा यस्य तादृशो हि निश्चयेन धृतिं धैर्यं शमं च शान्तिं? न विन्दामि न प्राप्नोमीत्यर्थः। स्वरक्षणार्थं विष्णो इति सम्बोधनम्।'),
('purushottama-sc:source:11.25','Puruṣottamajī','gita.11.25','sa','commentary','।।11.25।।किञ्च भयाधिक्येन पुनर्विज्ञापयति -- दंष्ट्राकरालानीति। हे देवेश सर्वपूज्य ते मुखानि दंष्ट्राभिः करालानि भयोत्पादकानि। च पुनः कालानलसन्निभानि प्रलयाग्निसन्निभानि दृष्ट्वैव भयाद्दिशो न जाने गत्वा प्राप्यस्थानं न जानामि। शर्म त्वदवलोकनरूपं च सुखं न लभे। अतो हे जगन्निवास जगत्पालक जगतः सुखस्थितिरूप प्रसन्नो भव प्राप्यं स्थानं दर्शयेति भावः।'),
('purushottama-sc:source:11.26','Puruṣottamajī','gita.11.26','sa','commentary','।।11.26।।एवं भगवत्स्वरूपस्थं जगद्दृष्ट्वा विज्ञाप्ययच्चान्यद्द्रष्टुमिच्छसि [11।7] इति भगवतोक्तं तदर्थं बाह्यस्थः स्वपरसैन्यस्वरूपज्ञानदर्शनेच्छया दृष्ट्वा विज्ञापयति -- अमी चेति पञ्चभिः। च पुनः। बाह्यस्थाः अमी परिदृश्यमानाः धृतराष्ट्रस्य पुत्रा आलोचनरहिताः सर्वे अवनिपालसङ्घैः जयद्रथादिसमूहैः सह? भीष्मो योद्धा च? द्रोणः शास्त्रविशारदः? सूतपुत्रः कर्णः अस्मदीयैरपि योधमुख्यैः घृष्टद्युम्नादिभिः सह।'),
('purushottama-sc:source:11.27','Puruṣottamajī','gita.11.27','sa','commentary','।।11.27।।त्वरमाणा वेगवत्तराः दंष्ट्राकरालानि स्वतोऽपि भयानकानि वक्त्राणि विशन्ति प्रविशन्ति। प्रवेशानन्तरं दृष्टमाह। केचित् एके दशनान्तरेषु दन्तच्छिद्रेषु विलग्ना लम्बमानाः चूर्णितैः चूर्णीकृतैः उत्तमाङ्गैः सन्दृश्यन्ते।'),
('purushottama-sc:source:11.28','Puruṣottamajī','gita.11.28','sa','commentary','।।11.28।।प्रवेशे दृष्टान्तमाह -- यथेति। यथा नदीनां बहुधा प्रसरन्तीनां बहवोऽम्बुवेगाः जलप्रवाहाः समुद्रमेव स्वलयस्थानमेव अभिमुखाः सन्मुखाः सन्तो द्रवन्ति प्रविशन्ति तथा अमी नरलोकवीराः अभिविज्वलन्ति परितो दीप्यमानानि तव वक्त्राणि विशन्ति।'),
('purushottama-sc:source:11.29','Puruṣottamajī','gita.11.29','sa','commentary','।।11.29।।नदीदृष्टान्ते प्रकटतया नाशो न दृश्यत इति नाशार्थप्रवेशे दृष्टान्तान्तरमाह -- यथेति। यथा पतङ्गाः सूक्ष्मकीटाः शलभाः स्वपक्षवेगमदावलिप्ताः नाशाय मरणार्थं प्रदीप्यमानं ज्वलनमग्निं विशन्ति तथैव समृद्धवेगाः मदावलिप्ता एते लोकाः पूर्वोक्ता नाशाय मरणाय तवापि वक्त्राणि विशन्ति।'),
('purushottama-sc:source:11.30','Puruṣottamajī','gita.11.30','sa','commentary','।।11.30।।ननु भगवान् न नाशयेत्तदा किं तत्प्रवेशेन इत्यत आह -- लेलिह्यस इति। ग्रसमानः ग्रासं कुर्वन् समन्तात् सर्वतः समग्रान् लोकान् ज्वलद्भिः देदीप्यमानैर्वदनैः लेलिह्यसे भक्षयसि। तवापि तन्नाशेच्छैव दृश्यत इति भावः। भगवानेवं कथं कुर्यात् अत आह। हे विष्णो सर्वपालक सात्त्विकरक्षणार्थमेव। उग्राः प्रतपनसमर्थाः तव भासः किरणाः तेजोभिः स्फुरत्कान्तिभिः समग्रं जगदापूर्य प्रतपन्ति सन्तापयन्ति। अत्रायं भावः -- विष्णुः सात्त्विकाधिष्ठाता सात्त्विकरक्षणार्थमेव दुष्टनाशं करोत्यत उचितमेव तथाकरणम्।'),
('purushottama-sc:source:11.31','Puruṣottamajī','gita.11.31','sa','commentary','।।11.31।।एवं समग्रजगत्तापनेन ममाऽपि सन्तापो भवत्यतो मयि प्रसन्नो भवेत्याह -- आख्याहीति। भवान् पूर्वरूपेण परिदृश्यमानः कः उग्ररूपः कः एतत् मे मह्यं हि निश्चयेन आख्याहि वद। तवाख्याने किं साधनं इत्यत आह। हे देववर देवश्रेष्ठ देवाः पूजनेन तुष्यन्ति? त्वं तु तेषामपि श्रेष्ठः प्रभुरतस्ते नमोऽस्तु।किमासनं ते गरुडासनाय इत्यादिवाक्यैस्तव प्रसादे नमस्कार एव साधनमित्यर्थः। अतः प्रसीद प्रसन्नो भव। ननु प्रसादे स्वरूपाख्यानं किम्प्रयोजनकं इत्यत आह -- विज्ञातुमिति। आद्यं पुरुषोत्तमं मूलभूतं भवन्तं विज्ञातुं विशेषेण सलीलं ज्ञातुमिच्छामि वाञ्छामि। यतस्तव प्रवृत्तिं अत्र प्राकट्यरूपां चेष्टां लीलां हि निश्चयेन न प्रजानामि स्वरूपज्ञाने सति तज्ज्ञानमपि भविष्यतीत्यर्थः। एवं सलीलं त्वज्ज्ञानेन भजनं करिष्याम्यतो विज्ञातुमिच्छामीति भावः।'),
('purushottama-sc:source:11.32','Puruṣottamajī','gita.11.32','sa','commentary','।।11.32।।एवं विज्ञप्तः सन् श्रीभगवान् उवाच -- कालोऽस्मीति त्रयेण। लोकक्षयकृत् लोकानां विनाशकः प्रवृद्धः ऊर्जितः? लोकान् प्राणिनः? इह बाह्यतः समाहर्तुं संहर्तुं स्वलीनान् कर्तुं प्रवृत्तः कालोऽस्मि। यद्दशनान्तरेषु योधास्त्वया दृष्टास्तत्कालात्मकं मत्स्वरूपमिति भावः। त्वां द्रष्टारं मत्कृपापात्रं ऋते विना प्रत्यनीकेषु अनीकानि प्रत्यवस्थिताः ये योधास्ते सर्वेऽपि न भविष्यन्ति न स्थास्यन्तीति। यतोऽहं कालरूपः सर्वसंहारार्थं प्रवृत्तोऽस्मि। त्वां ऋते सर्वे न भविष्यन्तीत्युक्त्या त्वदर्थमेवैते मारिता इति ज्ञापितम्।'),
('purushottama-sc:source:11.33','Puruṣottamajī','gita.11.33','sa','commentary','।।11.33।।अत एव त्वमनायासेन यशो गृहाणेत्याह -- तस्मादिति। हे सव्यसाचिन् सव्येन वामेन हस्तेन सचितुं सन्धातुं शीलं यस्य तादृशस्त्वमुत्तिष्ठ युद्धार्थं सज्जो भव। यशो लभस्व सव्यहस्तेनैव सर्वे मारिता इत्यादिरूपम्। शत्रून् दुर्योधनादीन् जित्वा समृद्धं राज्यं भुङ्क्ष्व। एते मया पूर्वमेव त्वन्मारणात् प्रथममेव निहताः मारिताः? अतो निमित्तमात्रं भव लोककथनार्थमर्जुनेन सर्वे मारिता इति।'),
('purushottama-sc:source:11.34','Puruṣottamajī','gita.11.34','sa','commentary','।।11.34।।द्रोणो ब्राह्मणत्वाद्भगवता कथं वध्यः तथा भीष्मो भक्तः? तथैव जयद्रथः शिवात्प्राप्तप्रसादः? कर्णः कुन्तीपुत्रः? एतेषाममारणे कथं जयो भवेत् अतस्तन्नाम्ना प्राह -- द्रोणं चेति। च पुनः। ब्राह्मणमपि द्रोणं? भीष्मं च भक्तमपि? जयद्रथं चकारेण प्राप्तवरमपि? कर्णं च कुन्तीपुत्रमपि तथाभूतानन्यानपि योधवीरान् युद्धविशारदान् मया हतांस्त्वं जहि मारय। स्वहतत्वोक्त्याइषुभिः कथं पूजार्हान् प्रति योत्स्यामि [2।4] इति यत् पूर्वमुक्तं स दोषोऽत्रानुकूल्यकरणेन निवारितः। यत एते मया हता अतो निश्शङ्कं युद्ध्यस्वः रणे सपत्नान् शत्रून् जेतासि जेष्यसि।'),
('purushottama-sc:source:11.35','Puruṣottamajī','gita.11.35','sa','commentary','।।11.35।।ततोऽर्जुनः किं कृतवान् इत्याकाङ्क्षायां सञ्जयो धृतराष्ट्रं प्रत्याह -- एतदिति। एतत् पूर्वोक्तं केशवस्य ब्रह्मशिवयोरपि मोक्षदातुः वचनं श्रुत्वा किरीटी अर्जुनः वेपमानः भगवता राजभोगे विनियुक्तस्तदयुक्तं मन्वानो मोक्षाभिलाषवत्त्वात् कम्पमानो जातः। ततो विज्ञापनार्थं कृताञ्जलिः भीतभीत इति भगवदाज्ञायां पुनर्विज्ञापने कदाचिदप्रसन्नो भवेदिति महाभीतः सन् प्रणम्य प्रकर्षेण मनसा नमस्कृत्य कृष्णं सदानन्दं सगद्गदं प्रेमोपरुद्धकण्ठं यथा तथा भूयः पुनः नमस्कृत्यैव अतीव दीनो भूत्वा आह विज्ञप्तिं कृतवानित्यर्थः।'),
('purushottama-sc:source:11.36','Puruṣottamajī','gita.11.36','sa','commentary','।।11.36।।किमर्जुनो विज्ञापितवान् इत्याकाङ्क्षायामर्जुनवाक्यान्याह -- अर्जुन उवाचस्थाने इत्येकादशभिः। एकादशेन्द्रियैरपि शुद्धैर्विज्ञाप्यमित्येकादशभिर्विज्ञापयति। हे हृषीकेश यतस्त्वं सर्वेन्द्रियप्रेरकस्तस्मात् स्थाने स्थितौ तव प्रकीर्त्या तव गुणसङ्कीर्तनेन जगत् प्रहृष्यति हर्षमाप्नोति। च पुनः।अन्यत् कीर्तनश्रवणेन अनुरज्यते अनुरागयुक्तं भवति ननु बाधकेषु विद्यमानेषु कीर्तनं कर्तुं कथं शक्यं इत्याशङ्क्य कीर्तनेनैव बाधनाशो भवतीत्याह -- रक्षांसीति। तव कीर्तनेनैव भीतानि सन्ति रक्षांसि दिशः प्रति द्रवन्ति पलायन्ते। तथा सिद्धसङ्घाः सिद्धानां प्राप्तज्ञानानां समूहाः नमस्यन्ति प्रणमन्तीत्यर्थः।'),
('purushottama-sc:source:11.37','Puruṣottamajī','gita.11.37','sa','commentary','।।11.37।।ननु सिद्धाः किमिति नमन्ति इत्यत आह -- कस्मादिति। हे महात्मन् महतामात्मस्वरूप यस्मांत्तषां भक्तानां स्वरूपं त्वमेवातस्ते तुभ्यं कस्मान्न नमेरन् न नमस्कुर्युः। कीदृशाय गरीयसे गुरवे। ब्रह्मणोऽप्यादिकर्त्रे जनकाय। किञ्च। हे अनन्तदेवेश अनन्तानां देवानामीश प्रभो हे जगन्निवास सकलाश्रय अक्षरं त्वमेव? सत् असच्च सर्वं त्वमेव? यत् परं पुरुषोत्तमाख्यं ब्रह्मतत्त्वम् अतो नमन्तीत्यर्थः।'),
('purushottama-sc:source:11.38','Puruṣottamajī','gita.11.38','sa','commentary','।।11.38।।किञ्च -- त्वमादिदेव इति। त्वं देवानामादिः तथा त्वं ब्रह्मणोऽप्यसीत्यत आह -- पुरुषः। तत् त्वमक्षरेऽपि वर्तस इत्यतः पुराणः पुरुषोत्तम इत्यर्थः। पुरुषोत्तमधर्मानेवाह -- त्वमस्य परिदृश्यमानस्य विश्वस्य परमुत्कृष्टं आधिदैविकरूपेण स्वस्मिन् स्थानं स्वरतीच्छारूपं निधानं लयस्थानं परं विश्वस्य क्रीडाप्रकटितस्वरूपज्ञानेन सर्वत्र रमणकर्ता त्वमसि विश्वस्य विश्वस्मिन् वा। वेद्यं ज्ञेयं त्वं च त्वमेवेत्यर्थः। च पुनः परं धाम वैकुण्ठाख्यं तेजोरूपं पुरुषोत्तमगृहात्मकं वा त्वम्। हे अनन्तरूप इदं विश्वं त्वया ततं व्याप्तं त्वद्रूपमेवेत्यर्थः।अनन्तरूपमिति।'),
('purushottama-sc:source:11.39','Puruṣottamajī','gita.11.39','sa','commentary','।।11.39।।वायुरिति। वायुः सर्वप्रेरकः सर्वप्राणरूपः? यमः सर्वनियमनः? अग्निः सर्वाधारः वरुणः जलाधिपः सर्वरसपूरकः? शशाङ्कः सर्वानन्दकरः? प्रजापतिः सर्वोत्पादकः। च पुनः प्रपितामहः ब्रह्मणोऽपि पिता अतः सर्वरूपस्त्वं तस्मात् पूर्वोक्ताः कथं तुभ्यं न नमस्कुर्युः। अतः सर्वरूपत्वादाधिदैविकत्वात् त्वमेव नमस्यः। अतोऽहमपि नमस्करोमि सहस्रकृत्वः सहस्रशः ते तुभ्यं नमो नमोऽस्तु। अस्त्वितिपदेन त्वमङ्गीकुर्विति ज्ञापितम्। पुनश्चाङ्गीकारानन्तरमपि भूयः वारंवारं ते नमो नमः करोमीत्यर्थः।'),
('purushottama-sc:source:11.40','Puruṣottamajī','gita.11.40','sa','commentary','।।11.40।।किञ्च -- नम इति। हे सर्व सर्वात्मन् पुरस्तात् पूर्वदिशि पृष्ठतः पश्चिमायां सर्वतः दक्षिणोत्तरकोणादिषु सर्वासु दिक्षु ते नमो नम एवाऽस्तु।किमासनं ते गरुडासनाय इत्यादिवाक्यैर्नान्यत्किञ्चिदपि कर्तुं शक्यमिति भावः। इदमेवैवकारेण व्यञ्जितम्। यद्वा पृष्ठतः पश्चात् सर्वतः दक्षिणोत्तरादिभागेषु नमः कृतो नमस्कारः ते पुरस्तादेव पूर्वभाग एव सन्मुख एवाऽस्त्विति वाऽर्थः। ननु पश्चाद्भागकृतो नमस्कारः कथं पूर्वभागीयः स्यादत् आह -- अनन्तेति। अनन्तं वीर्यं सामर्थ्यम्? अभितो बहुतरः पराक्रमो यस्य तादृशस्त्वं सर्वं जगत् समाप्नोषि तत्तद्रूपनामभेदेन सर्वरूपो भूत्वा वर्तसे? ततः सर्वः सर्वरूपस्त्वमसि? अतः पृष्ठतोऽपि नमस्कृतौ पूर्वभागो न बाध्यत इत्यर्थः।'),
('purushottama-sc:source:11.41','Puruṣottamajī','gita.11.41','sa','commentary','।।11.41।।एवं नमस्कृत्य पूर्वाज्ञानजापराधान् क्षमापयति -- सखेति द्वयेन। मया तव इदं पुरुषोत्तमत्वेन सर्वरूपात्मकरूपं महिमानमजानता प्रमादादनवधानतया प्रणयेन स्नेहेन वाऽपि प्रसभं बलात्कारेण अकार्येषु योजनार्थं हे कृष्ण इति नामत्वेन? न तु सदात्मकत्वेन हे यादव इति तत्कुलोद्भवत्वेन? न तु तदुद्धारार्थप्रकटत्वेन हे सखेति मित्रत्वेन लौकिकबुद्ध्या? न तु परमात्मत्वेन यदुक्तम्।'),
('purushottama-sc:source:11.42','Puruṣottamajī','gita.11.42','sa','commentary','।।11.42।।च पुनः। सखेति मत्वा अवहासार्थं मिथ्यावादादिभिः एकः केवलो मां विहाय विहारादिकं करोषीत्यादिभिः। अथवा मत्समक्षं विहारे द्यूतमृगयादिषु स्वजनत्वमुद्भावयता? शय्यायां सहशयनेन? आसने सहोपवेशेन? भोजने सहभुञ्जता? इत्यादिषु यत् असत्कृतोऽसि अवमानितोऽसि हे अच्युत च्युतिरहित स्वाङ्गीकृतपरिपालक। अहं त्वामप्रमेयं प्रमातुमयोग्यं तत्सर्वं क्षामये क्षमां कारयामि अप्रमेयत्वेनाऽज्ञानजापराधनिवृत्तिः सूचिता।'),
('purushottama-sc:source:11.43','Puruṣottamajī','gita.11.43','sa','commentary','।।11.43।।क्षमापने सन्बन्धस्यावश्यकत्वायाह -- पितेति। अस्य चराचरस्य स्थावरजङ्गमात्मकस्य ब्राह्मणक्षत्रिययोर्वापिता उत्पादकः? च पुनः गरीयान् पूज्यः देवोत्तमः तद्द्रष्टा गुरुः त्वमसि। तर्हि त्वत्समो भविष्यतीति नेत्याह। हे अप्रतिमप्रभाव उपमारहितानुभाव लोकत्रये अन्यस्त्वत्समोऽपि नास्ति कुतोऽभ्यधिको भवेत् येन त्वं तत्समः स्याः।'),
('purushottama-sc:source:11.44','Puruṣottamajī','gita.11.44','sa','commentary','।।11.44।।यतः सर्वेषां पिता गुरुः पूज्यश्च त्वमेवाऽतो ममापि सर्वं त्वमेवेति मदपराधं क्षन्तुमर्हसीति विज्ञापयति -- तस्मादिति। तस्मात्कारणात् अहं त्वां ईशं प्रभुं ईड्यं स्तुत्यं कायं प्रणिधाय दण्डवत् पतित्वा प्रणम्य नत्वा प्रसादये प्रसादयामि। हे देव जगत्पूज्य त्वं पूर्वोक्तान् ममापराधान् सोढुम् अर्हसि। क इव पुत्रस्य पितेव सख्युर्मित्रस्य सखा इव? प्रियायाः प्रीतियोग्यायाः स्त्रियाः प्रिय इव।'),
('purushottama-sc:source:11.45','Puruṣottamajī','gita.11.45','sa','commentary','।।11.45।।एवं क्षमाप्य विज्ञापयति -- अदृष्टपूर्वमिति द्वयेन। अदृष्टपूर्वं तव रूपं विश्वात्मकं अनेकलीलायुतं दृष्ट्वा हृषितोऽस्मि हर्षं प्राप्तोऽस्मि। च पुनः मे मनः भयेन प्रव्यथितं प्रकर्षेण व्यथां प्राप्तम्। अयं भावः -- द्रष्टुकामस्य तादृशं रूपं दर्शयित्वा पुरुषोत्तमदर्शनवतोऽन्यरूपदर्शनाभिलाषापराधिनः पुनः पुरुषोत्तमरूपं दर्शयिष्यति न वेति भयमभूत्? अतः प्रसादं प्रार्थयित्वा तद्दर्शनं प्रार्थयति। देवेश देवानामपीन्द्रादीनामीश नियामक जगन्निवास प्रसीद प्रसन्नो भव। प्रसन्नो भूत्वा हे देव सेवनार्थं तदेव पुरुषोत्तमरूपं दर्शय।'),
('purushottama-sc:source:11.46','Puruṣottamajī','gita.11.46','sa','commentary','।।11.46।।रूपं विशिनष्टि -- किरीटिनमिति। किरीटवन्तं गदावन्तं चक्रहस्तं त्वामहं तथैव पूर्ववदेव द्रष्टुमिच्छामि। अतो हे सहस्रबाहो अगणितक्रियाशक्तिमन् विश्वमूर्ते तेनैव चतुर्भुजेन रूपेण भव प्रकटो भवेत्यर्थः।'),
('purushottama-sc:source:11.47','Puruṣottamajī','gita.11.47','sa','commentary','।।11.47।।एवं प्रार्थितोऽर्जुनमाश्वासयन् स्वरूपं दर्शयामास? तत्र पूर्वमाश्वासनमाह -- श्री भगवानुवाच मयेति। हे अर्जुन मया सर्वदा त्वयि प्रसन्नेन आत्मयोगात् स्वकीयत्वयोगाच्च तव परं इच्छया इदं रूपं दर्शितम्। कीदृशं तेजोमयं? विश्वं विश्वात्मकम्? अनन्तमन्तरहितम्? आद्यं सनातनं? यत् मे रूपं त्वदन्येन त्वां,विना केनाऽपि दृष्टपूर्वं न। तादृशं रूपं त्वदिच्छया दर्शितमित्यर्थः।'),
('purushottama-sc:source:11.48','Puruṣottamajī','gita.11.48','sa','commentary','।।11.48।।एवं त्वदिच्छयैवेदं रूपं दर्शितं? इदानीं च पूर्वतनमेव रूपं पश्य? दर्शनीयस्य रूपस्य दुर्लभत्वायाऽर्जुने कृपाधिक्यमाह -- न वेदेति। न वेदयज्ञाध्ययनैः वेदानां सार्थकशब्दात्मकानां यज्ञानामानुपूर्व्यादिसहितविद्याक्रियाणां अध्ययनैः? न दानैः तुलापुरुषादिभिः? न च क्रियाभिरग्निहोत्रादिरूपाभिः? न तपोभिरुग्रैः कृच्छ्रचान्द्रायणादिभिः नृलोके मनुष्यलोके एवंरूपः अहं पुरुषोत्तमः हे कुरुप्रवीर भक्तकुलश्रेष्ठ त्वदन्येन त्वामपहायान्येन द्रष्टुं पूर्वोक्तैः साधनैरपि न शक्यः न समर्थः।'),
('purushottama-sc:source:11.49','Puruṣottamajī','gita.11.49','sa','commentary','।।11.49।।यदन्येन न शक्यस्ततः पूर्वोक्तभयाशङ्कादिरहितस्तदेव रूपं पश्येत्याह -- मा त इति। ते व्यथा न दर्शयिष्यामीत्यादिरूपा माऽस्तु। च पुनः मम घोरं भयानकम्? ईदृक् सर्वग्रसनादिधर्मयुक्तम्? इदं परिदृश्यमानं दृष्ट्वा विमूढभावः मोहरूपो माऽस्तु। व्यपेतभीः विगतभयः प्रीतमनाः संस्तदेव पूर्वदृष्टमेव मे इदं रूपं प्रपश्य प्रकर्षेण यथाभिलाषं भक्तियुतः पश्येत्यर्थः।'),
('purushottama-sc:source:11.50','Puruṣottamajī','gita.11.50','sa','commentary','।।11.50।।एवमुक्त्वा स्वरूपं दर्शयामासेति सञ्जय आह -- इतीति। अमुना प्रकारेण वासुदेवो मोक्षदाता परमकृपालुः अर्जुनं तथा पूर्वप्रकारेणोक्त्वा स्वकं स्वीयं पुरुषोत्तमरूपं भूयः पुनः दर्शयामास। एवं दर्शयित्वा सौम्यवपुर्भूत्वा च पुनः पूर्वरूपदर्शनभीतं एनं अर्जुनं पुनराश्वासयामास। नन्वेवं वारं वारं कथं कृतवान् इत्यत आह -- महात्मेति। महांश्चासौ आत्मा च तेन कृपया तथा कृतवानिति भावः। यद्वा महतां भक्तानां आत्मा अतो भक्तत्वात्तथा कृतवानित्यर्थः।'),
('purushottama-sc:source:11.51','Puruṣottamajī','gita.11.51','sa','commentary','।।11.51।।दर्शितस्वरूपं दृष्ट्वाऽर्जुनो विज्ञापयति -- दृष्ट्वेति। हे जनार्दन अविद्यानाशक इदं पुरतो दृश्यमानं मानुषं मनुष्यैर्द्रष्टुं योग्यं सौम्यं दयापरीतं दयायुक्तं तव रूपं दृष्ट्वा इदानीमधुना सचेताः सावधानचित्तः संवृत्तः जातोऽस्मि। प्रकृतिं भक्तिरूपां गतः प्राप्तोऽस्मि (च)।'),
('purushottama-sc:source:11.52','Puruṣottamajī','gita.11.52','sa','commentary','।।11.52।।स्वस्य रूपस्य स्वानुग्रहैकसाध्यत्वेन परमदुर्लभत्वमाह -- श्रीभगवानुवाच सुदुर्दर्शमिति। इदं परिदृश्यमानं मम रूपं सुदुर्दर्शं सुष्ठु दुःखेनाऽपि द्रष्टुमशक्यं यत् त्वं दृष्टवानसि। देवा अपि मत्क्रीडायोग्या मदंशा अपि अस्य नित्यं प्रत्यहं दर्शनकाङ्क्षिणः दर्शनेच्छवस्तिष्ठन्तीत्यर्थः।अत्रायं भावः -- ब्रह्मादयो देवाः श्रीदेवकीगृहे स्तुत्वा गतास्तदा गर्भ एव प्राकट्यं? न बहिः बहिः प्राकट्यानन्तरं तु मातृप्रार्थनया तिरोहितं कृत्वा ध्यानास्पदत्वेन स्थापितं देवादीनां तु तद्वृत्तान्ताज्ञानाद्वेदोक्तरीत्या भजनात्तादृक्स्वरूपदर्शनमेव भवति इदं च स्वरूपं भावात्मकं वेदाद्यगम्यं भक्तमुखात् श्रुतत्वाच्चाकाङ्क्षिणस्तिष्ठन्तीति तथा।'),
('purushottama-sc:source:11.53','Puruṣottamajī','gita.11.53','sa','commentary','।।11.53।।ननु ते वेदाद्युक्तसाधनैः कथं न पश्यन्ति इत्यत आह -- नाहमिति। यथा त्वं मां दृष्टवानसि एवंविधः पुरुषोत्तमोऽहं परिदृश्यमानवेदैः वेदोक्तसाधनैः वेदैरेव वा न अतएव यतो वाचो निवर्त्तन्ते अप्राप्य मनसा सह [तै.उ.2।4।12।9।1] इत्युक्तम्। तपसा क्लेशात्मकेनाऽपि न? दानेन सर्वस्वदक्षिणात्मकेन न? इज्यया यागेन न द्रष्टुं शक्यः।'),
('purushottama-sc:source:11.54','Puruṣottamajī','gita.11.54','sa','commentary','।।11.54।।तदा कथं द्रष्टुं शक्यः इत्यत आह -- भक्त्येति। हे अर्जुन हे परन्तप इति स्नेहेन वीप्सया सम्बोधनम्। एवंविधोऽहं अनन्यया न विद्यते अन्यः पारलौकिकैएहिकयत्नो यस्यां तादृश्या भक्त्या तत्त्वेन याथार्थ्यस्वरूपेण ज्ञातुं च पुनरलौकिकभावदृष्ट्या द्रष्टुं च पुनः प्रवेष्टुं अलौकिकरूपेण लीलासु सेवनार्थं शक्यः? अस्मीति शेषः।'),
('purushottama-sc:source:11.55','Puruṣottamajī','gita.11.55','sa','commentary','।।11.55।।नन्वनन्यभक्तः कथं ज्ञेयः इत्याकाङ्क्षायामाह -- मत्कर्मकृदिति। मदर्थं स्वस्य सहजदासत्वेन? न तु कामनया? कर्म सेवादिरूपं करोति स तथा। मत्परमः अहमेव परमः सर्वस्वं यस्य। मद्भक्तः मद्भजनकृत् मदाश्रितो वा। सङ्गवर्जितः पुत्रादिलौकिकावैष्णवादिसङ्गवर्जितः। सर्वभूतेषु निर्वैरः द्वेषरहितः। हे पाण्डव,उत्पत्त्यैव भक्त एवंविधो यः स मामेति प्राप्नोति? सोऽनन्यो ज्ञातव्य इति भावः।प्रदर्श्य विश्वरूपं स्वं दृढीकृत्याऽर्जुनाय वै।श्रीकृष्णः साधनासाध्यं स्वस्वरूपमदर्शयत्।।1।।'),
('purushottama-sc:source:12.1','Puruṣottamajī','gita.12.1','sa','commentary','।।12.1।।पुरुषोत्तमभक्तानामक्षराभिनिवेशिनाम्। स्वरूपतारतम्यार्थं श्रीकृष्णं ह्यर्जुनोऽब्रवीत्।।1।।पूर्वाध्यायान्तेमत्कर्मकृत् [11।55] इत्यनेन भक्तानां स्वभजनैकनिष्ठानां स्वप्राप्तिरुक्ता? पूर्वं चाष्टमाध्यायेयदक्षरं वेदविदो वदन्ति [11] इत्यारभ्यस याति परमां गतिम् [8।13] इत्यन्तमक्षरोपासकानां परमगतिरुक्ता? एतदुभयोस्तारतम्यजिज्ञासुरर्जुनो भगवन्तं विज्ञापयति -- एवमिति। एवं पूर्वोक्तप्रकारेण सर्वसङ्गपरित्यागेन अनन्यभक्ता ये त्वां प्रकटमानन्दरूपं पर्युपासते ध्यायन्ति तेषामुभयेषां मध्ये के योगवित्तमाः अतिशयितत्वत्संयोगविदः श्रेष्ठा इत्यर्थः। तान् कृपया आज्ञापयेति भावः।'),
('purushottama-sc:source:12.2','Puruṣottamajī','gita.12.2','sa','commentary','।।12.2।।तत्र ये प्रकटपुरुषोत्तमरूपमद्भजनकर्तारस्त उत्तमा इत्याशयेनोत्तरमाह श्रीभगवान् -- मयीति। मयि प्रकटरूपे सम्यक् निष्कामतया मनः सर्वदैकरूपमावेश्य आसमन्तात् सर्वात्मभावेन निवेश्य ये भाग्यवन्तो नित्ययुक्ताः मत्सेवैकतत्पराः परया प्रेमैकलक्षणया श्रद्धया उपेताः युक्तास्ततो मामुपासते सेवन्ते ते युक्ततमा उत्तमाः मे मताः सम्मता इत्यर्थः।'),
('purushottama-sc:source:12.3','Puruṣottamajī','gita.12.3','sa','commentary','Sri Purushottamji did not comment on this sloka'),
('purushottama-sc:source:12.4','Puruṣottamajī','gita.12.4','sa','commentary','।।12.4।।इन्द्रियग्रामं सन्नियम्य वशीकृत्य सर्वत्र मयि देवादिषु लौकिकेषु सुखदुःखेषु वा समबुद्धयः सर्वभूतहिते रताः सन्तो ये पर्युपासते ध्यायन्ति ते मामेव प्राप्नुवन्ति। एवकारेणाक्षरसम्बन्धव्यवहिताः। प्राप्नुवन्तीति भावः? स्वयुक्ततमत्वाभावश्च ज्ञापितः।'),
('purushottama-sc:source:12.5','Puruṣottamajī','gita.12.5','sa','commentary','।।12.5।।किञ्च मदभिमता भावात्परम्पराप्राप्तावपि तेषां क्लेशः? अप्रकटरूपासक्तचित्तानां सेवार्थप्रकटितसर्वेन्द्रियवैकल्यात् क्लेशः अधिकतरो भवति? आसक्तचित्तत्वाद्दर्शनाद्यभिलाषे सति तदभावादाधिक्यं भवति साधनदशायामपि? अत एवाधिकतरत्वमुक्तम्। फलमपि दुःखेन प्राप्यत इत्याह -- अव्यक्तेति। देहवद्भिः देहात्मसेवमानवद्भिः अव्यक्ता गतिः अव्यक्तनिष्ठा गतिः दुःखं दुःखेन अवाप्यते प्राप्यते। हीति युक्तत्वाय। भगवत्सेवैकयोग्यदेहस्य व्यर्थगमनेन सा गतिर्दुःखेनैव प्राप्यते। प्राप्त्यनन्तरमप्यलौकिकदेहाद्यभावादव्यक्ततया प्रवेशे तदात्मकांशस्य पूर्वानुभूतलौकिकेन्द्रियरसस्मरणेन जले निमग्नस्य जलपानवद्दुःखं प्राप्यत इति भावः।'),
('purushottama-sc:source:12.6','Puruṣottamajī','gita.12.6','sa','commentary','।।12.6।।अक्षरोपासकानां साक्षात्कारेऽपि क्लेशः? मद्भक्तानां तु मत्स्वरूपध्यानेन मत्प्रतिमादिसेवतामप्यहमुद्धारं करोमीत्याह -- ये त्विति द्वाभ्याम्। ये तु सर्वाणि लौकिकवैदिकादीनि मयि मन्निमित्तं सन्न्यस्य त्यागं कृत्वा? मत्पराः अहमेव पर उत्कृष्टः प्राप्यो येषां तादृशाः सन्तोऽनन्येनैव योगेन? नैव अन्यो भजनीयो यस्मिंस्तादृशेन भक्तियोगेन मां ध्यायन्तः मद्ध्यानं कुर्वन्त उपासते सेवन्ते मूर्त्यादिष्विति शेषः।'),
('purushottama-sc:source:12.7','Puruṣottamajī','gita.12.7','sa','commentary','।।12.7।।हे पार्थ मद्भक्त मयि आ समन्तात् सर्वभावेनाऽऽवेशितं चेतो येषां तेषां मृत्युसंसारसागरात् वारंवारं मरणधर्मयुक्तशरीरप्रापकरूपात् अलौकिकभजनौपयिक स्वरूपदानेन उद्धर्ता। न चिरात् शीघ्रमेवाऽहं भवामि?,ध्याने मूर्तौ वा प्रकटो भवामीत्यर्थः।'),
('purushottama-sc:source:12.8','Puruṣottamajī','gita.12.8','sa','commentary','।।12.8।।यतो ध्यानादिभिः सेवतामप्युत्तमफलप्राप्तिर्भवति? तत्र साक्षान्मद्भजनकर्तृ़णां किं वाच्यं अतस्त्वं मत्परो भवेत्याह -- मयीति। मय्येव प्रकटरूप एव मनः सङ्कल्पविकल्पात्मकमाधत्स्व आ समन्तात् स्थैर्येण सर्वत आकृष्य स्थापय। बुद्धिं व्यवसायात्मिकां मय्येव निवेशय। अत ऊर्ध्वं बुद्धिप्रवेशानन्तरं मय्येव पुरुषोत्तमे निवसिप्यसि नितरां सेवादियोग्यतया निकट एव स्थास्यसि। न संशयः अत्र न सन्देहः। संशयं मा कुर्य्या इत्यर्थः।'),
('purushottama-sc:source:12.9','Puruṣottamajī','gita.12.9','sa','commentary','।।12.9।।ननु मनश्च़ञ्जलत्वात् कथं त्वयि स्थिरं स्यात् अत आह -- अथेति।धनञ्जय इति सावधानार्थे सम्बोधनम्। अथ चेत् मयि स्थिरं चित्तं समाधातुं न शक्नोषि समर्थो न भवसि? तदा अभ्यासयोगेन मच्छ्रवणानुस्मरणादिरूपेण मामाप्तुं प्राप्तुं इच्छ यतस्व। विचार्य प्रयत्नपरो भवेत्यर्थः।'),
('purushottama-sc:source:12.10','Puruṣottamajī','gita.12.10','sa','commentary','।।12.10।।एवं चित्तधारणार्थमभ्यासः साधनत्वेनोक्तस्तत्साधनमप्याह -- अभ्यास इति। अभ्यासे निरन्तरानुस्मरणे अपि चेत् असमर्थोऽसि तदा मत्कर्मपरमः मत्प्रीति हेतुपूजादिरूपाणि यानि तदनुष्ठानमेव परममुत्कृष्टं यस्य? तादृशो भव। एवं मदर्थं मत्प्रीत्यर्थं? न तु फलकामनया कर्माण्यपि कुर्वन् सिद्धिमभ्याससिद्धिं प्राप्स्यसि।'),
('purushottama-sc:source:12.11','Puruṣottamajī','gita.12.11','sa','commentary','।।12.11।।एतत्प्राप्त्यर्थमतिसुगमोपायमाह -- अथैतदिति। अथ चेत् एतदपि मदर्थकं कर्तुमशक्तोऽसि न समर्थोऽसि? स्वरूपाज्ञानात् तदा मद्योगं मम योगः संयोगो यस्मिन् यस्य वा तादृशं भक्तमाश्रितः सन् यतात्मवान् तदेकपरचित्तो भूत्वा सर्वकर्मफलत्यागं सन्ध्यावन्दनाग्निहोत्रादीनां स्वर्गादिरूपफलानां त्यागं कुरु? चिन्तनं त्यजेत्यर्थः। तत्फलानभिलाषे मदाज्ञया करणात् कर्मभिश्चित्तशुद्ध्या मद्भक्तोपदिष्टं ज्ञानं स्थिरीभविष्यति? तेन मत्कर्मसिद्धिर्भविष्यतीति भावः।'),
('purushottama-sc:source:12.12','Puruṣottamajī','gita.12.12','sa','commentary','।।12.12।।एवमुक्तानामुत्तरोत्तरकर्त्तव्यानां स्वरूपमाह -- श्रेय इति। अभ्यासात् केवलचित्ताकर्षणेनाऽनुस्मरणरूपात् ज्ञानं श्रेयः? श्रेष्ठमित्यर्थः। अतो ज्ञानयुक्तोऽभ्यास उत्तम इति भावः। ज्ञानात् केवलात् ध्यानं मत्स्वरूपानुचिन्तनात्मकं विशिष्टं भवतीत्यर्थः। तेन ज्ञानाभ्यासयुक्तं ध्यानमुत्तममिति भावः। ध्यानात् केवलात् कर्मफलत्याग उत्तमः। तेन ज्ञानाभ्यासध्यानसहितमदर्थकमत्कर्मकरणमुत्तममित्यर्थः। यत एवमतस्तादृशत्यागादनन्तरं शीघ्रमेव शान्तिर्मद्भक्ितस्थितिरूपा भवेदिति शेषः।');
INSERT INTO commentary_fts (unit_id,author,canonical_ref,language,content_type,content) VALUES
('purushottama-sc:source:12.13','Puruṣottamajī','gita.12.13','sa','commentary','।।12.13।।तस्य स्वरूपमाह -- अद्वेष्टेति। सर्वभूतानां प्राणिमात्राणां मत्क्रीडात्मकत्वात् अद्वेष्टा आधिक्यादिदर्शने द्वेषरहितः मैत्रः भक्तेषु मित्रतया वर्त्तमानः करुणः भक्तिरहितेषु संसारदुःखनिश्चयात् करुणः उपदेशादिदानार्थं करुणावान्। एकारेण न कदाचित् कर्कशस्तिष्ठेदिति ज्ञापितम्। निर्ममः उपदेशदानानन्तरं तेषु सर्वत्र च ममत्वरहितः? निरहङ्कारः स्वस्योत्तमत्वज्ञानेनाऽहङ्काररहितः समदुःखसुखः समे दुःखसुखे वियोगसंयोगात्मके यस्य? क्षमी क्षमावान् दुष्टकृतावमानादिसहनशीलः।'),
('purushottama-sc:source:12.14','Puruṣottamajī','gita.12.14','sa','commentary','।।12.14।।किञ्चसन्तुष्ट इति। सततं सन्तुष्टः निरन्तरं हृदयस्थितमत्स्वरूपेण आनन्दयुक्तः? योगी मच्चिन्तनशीलः? यतात्मा वशीकृतस्वभावः दृढनिश्चयः दृढः कामाद्यनुपहतो मत्परीक्षितदुःखादिष्वचलो मयि सर्वकरणसमर्थत्वेन निश्चयो यस्य? मयि अर्पिते मनोबुद्धी येन? य एतादृशः स मद्भक्तः मे प्रियः मदिङ्गितकरणादिति भावः।'),
('purushottama-sc:source:12.15','Puruṣottamajī','gita.12.15','sa','commentary','।।12.15।।किञ्च -- यस्मादिति। यस्मात् सकाशाल्लोकः न उद्विजते ध्रुवादिवत् सकामभजनादिना लोकः क्लेशं नाप्नोति। च पुनः लोकात् स्वस्योत्सादनार्थं तपआदियत्नवतो यो न उद्विजते भयं न प्राप्नोतीत्यर्थः। च पुनः हर्षामर्षभयोद्वेगैर्मुक्तः हर्षः स्वेष्टाप्त्या तद्राहित्येन सर्वत्र भगवदात्मकत्वेनेतरास्फूर्त्या सर्वदैव हर्षात्मक,एवेत्यर्थः अमर्षः परोत्कर्षासहिष्णुता? तद्राहित्येन भगवल्लीलात्मकज्ञानवानित्यर्थः। भयं त्रासः? तदभावेन भगवद्रक्षणसामर्थ्यज्ञानवानित्यर्थः। उद्वेगश्चित्तलोभस्तेन सेवादिसमये चित्तचाञ्चल्यरहित इत्यर्थः। एतादृशो यः स मे प्रियः।'),
('purushottama-sc:source:12.16','Puruṣottamajī','gita.12.16','sa','commentary','।।12.16।।किञ्च। अनपेक्षः सेवादौ स्वमनोऽतिरिक्तापेक्षारहितः समर्थ इति यावत्। शुचिः मत्स्मरणवान्? दक्षः भजनस्वरूपज्ञानवान्? उदासीनः लोकेषु? गतव्यथः मानसिकक्लेशरहितः? सर्वारम्भपरित्यागी दृष्टश्रुतफलककर्माऽनुद्यमानस्वभावः। एतादृशो मद्भक्तः मद्भजनकर्त्ता स मे प्रियः।'),
('purushottama-sc:source:12.17','Puruṣottamajī','gita.12.17','sa','commentary','।।12.17।।किञ्च -- यो नेति। यः लौकिकप्रियाप्त्या न हृष्यति? तथैवाप्रियादिना न द्वेष्टि तथाच सेवार्थवस्तुनाशे न शोचति? न तदाकाङ्क्षति। शुभाशुभे स्वर्गनरकादिरूपे त्यजति। सर्वत्र भगवदिच्छां ज्ञात्वा लीलात्वेन व्यवहरतीत्यर्थः। एतादृशो यो भक्तिमान् भक्तियुक्तः स मे प्रियः।'),
('purushottama-sc:source:12.18','Puruṣottamajī','gita.12.18','sa','commentary','Sri Purushottamji did not comment on this sloka'),
('purushottama-sc:source:12.19','Puruṣottamajī','gita.12.19','sa','commentary','।।12.19।।तुल्ये निन्दास्तुती यस्य? निन्दितो च व्यथति? स्तुतो न हृष्यति स्वयं च न कञ्चन निन्दति न च स्तौति। मौनी वशवाक्। येनकेनचिद्भगवदिच्छाप्राप्तेन सन्तुष्टः। अनिकेतः गृहाद्यासक्तिरहितः। स्थिरमतिः? मयीत्यर्थः। एतादृशो यो भक्तिमान् भक्तियुक्तो नरः स मे प्रियः? प्रियो भवतीत्यर्थः।'),
('purushottama-sc:source:12.20','Puruṣottamajī','gita.12.20','sa','commentary','।।12.20।।उक्तभक्तिरूपमुपसंहरति -- ये त्विति। य इति सामान्योक्त्या नात्र वर्णादिनियमः किन्तु ये केचन भाग्यवन्त इदं पुरत उक्तं धर्म्यामृतम् अक्षयं मत्प्रसादात्मकफलरूपं यथोक्तं श्रद्दधानाः मदुक्तं सत्यमिति ज्ञानवन्तो मत्परमाः मदेकनिष्ठाः सन्तः पर्युपासते मां सेवन्ते ते भक्ता मे अतीव स्वात्मनः प्रिया भवन्तीत्यर्थः।नाऽहमात्मानमाशासे [भाग.9।4।64] इतिवत्।एवमर्जुनमासिञ्चद्भक्तियोगामृतोक्तिभिः। सर्वसंशयमाच्छिद्य लोकोद्धारपरो हरिः।।1।।'),
('purushottama-sc:source:13.2','Puruṣottamajī','gita.13.1','sa','commentary','।।13.2।।भगवान् कृपयाऽवोत्तरमाह -- इदमिति। हे कौन्तेय कृपापात्र इदं शरीरं दृश्यमानं मरणादिधर्मयुक्तं क्षेत्रं ज्ञानादिप्ररोहस्थानं लीलार्थं स्वांशजीवोत्पत्तिस्थानं तद्विदा अभिधीयते कथ्यत इत्यर्थः। एतत् याथातथ्येन यो वेत्ति तं तद्विदः क्षेत्रविदो ज्ञानिनः क्षेत्रज्ञं प्राहुः। अन्योक्तिकथनेन तथा न भवतीति ज्ञापितम्।'),
('purushottama-sc:source:13.3','Puruṣottamajī','gita.13.2','sa','commentary','।।13.3।।अथाऽर्जुनज्ञानार्थं स्वमते यथा तत्स्वरूपमस्ति तथाऽऽह -- क्षेत्रज्ञमिति। क्षेत्रज्ञं बीजम्। अपिशब्देनाणुरूपमपि मां मदंशं रसानुभवार्थं सर्वक्षेत्रेषु चकारेण मद्रूपेषु स्थितं विद्धि जानीहि। भारतेति सम्बोधनं विश्वासार्थम्। क्षेत्रक्षेत्रज्ञयोर्मदंशत्वेन लीलार्थत्वेन यज्ज्ञानं तत् मम मतं सम्मतमित्यर्थः। एतद्विपरीतं देहादीनां कर्मादिजन्यत्वं तज्ज्ञानवत्त्वं जीवस्य क्षेत्रज्ञत्वं असम्बद्धमित्यर्थः स्वमतोक्त्या ज्ञापितः।'),
('purushottama-sc:source:13.4','Puruṣottamajī','gita.13.3','sa','commentary','।।13.4।।एवं प्रतिज्ञाय क्षेत्रक्षेत्रज्ञस्वरूपं सभेदकं कथयामि तच्छृण्वित्याह -- तत् क्षेत्रमिति। तन्मदुक्तं क्षेत्रं यत् मत्सत्तात्मकं? जडादिरूपमपि यादृक् यादृशं मल्लीलेच्छात्मकम्। यद्विकारि विचित्रक्रीडेच्छया नानाविकारयुक्तम्। यतश्च मदंशात्मकमत्क्रीडार्थप्रकृतिपुरुषसंयोगजम्। तत्स्थावरजङ्गमपक्ष्यादिविचित्ररूपम्। स च क्षेत्रज्ञः स्वरूपतो मदंशरूपो यत्प्रभावः सूक्ष्मोऽपि व्यापकादिसेवनयोग्याद्यचिन्त्यप्रभाववांस्तदन्यैर्याथातथ्यस्वरूपाज्ञानाद्बहुविधमुक्तं तत्सर्वं समासेन सङ्क्षेपतो मे मत्तः शृणु।'),
('purushottama-sc:source:13.5','Puruṣottamajī','gita.13.4','sa','commentary','।।13.5।।बहुधान्योक्तभ्रमाभावाय प्रपञ्चयति -- ऋषिभिरिति। ऋषिभिः स्वानुभवोत्पन्नफलनिरूपणेन बहुधा बहुप्रकारेण गीतम्। किञ्च? छन्दोभिर्वेदैर्विविधैः कर्मज्ञानोपासनकाम्यादिभिः पृथक् भिन्नतया अधिकारपरत्वेन गीतम्। तथैव ब्रह्मसूत्रपदैश्च ब्रह्म सूत्र्यते एभिरिति ब्रह्मसूत्राणिजन्माद्यस्य यतः [ब्र.सू.1।1।2] इत्यादीनि। तथाच ब्रह्म प्रपद्यते गम्यते एभिरिति पदानि एको देवो बहुधा निविष्टः [तै.आ.3।14] इत्यादीनि तैर्बहुधा श्रुत्यनुसारेणैव गीतम्। कीदृशैस्तैः हेतुमद्भिः सहेतुकैः को ह्येवान्यात् कः प्राण्यात्? यदेष आकाश आनन्दो न स्यात् [तै.उ.2।7] एष ह्येव तं साधु कर्म कारयति [कौ.उ.3।9] इत्यादिभिः। विनिश्चितैः निस्सन्दिग्धैः स्वानुभवप्रतिपादकैरित्यर्थः। एवं विस्तरेणैतैरुक्तं दुर्बोधं याथातथ्येन तत् समासेन मे मत्तः उक्तं शृणु। कथयामीत्यर्थः।'),
('purushottama-sc:source:13.6','Puruṣottamajī','gita.13.5','sa','commentary','।।13.6।।तत्क्षेत्रस्वरूपमाह द्वयेन -- महाभूतानीति। महाभूतानि पृथिव्यादीनि। अहङ्कारस्तत्कारणात्मकः। बुद्धिर्विज्ञानात्मिका। अव्यक्तं मूलप्रकृतिः। इन्द्रियाणि दश। च पुनः एकं मनः। इन्द्रियगोचरास्तन्मात्रात्मकाः शब्दादयः पञ्च। एवं चतुर्विंशतितत्त्वानि प्रतिपादितानि।'),
('purushottama-sc:source:13.7','Puruṣottamajī','gita.13.6','sa','commentary','।।13.7।।इच्छा अभिलषितार्थरूपा? द्वेषः प्रतीपस्फूर्त्या? सुखं स्वाभिलषितप्राप्त्या? दुःखं स्वाज्ञानकल्पितं?,सङ्घातः शरीरं? चेतना ज्ञानरूपा मनोवृत्तिः? धृतिः धैर्यम्। इच्छादयोऽपि मनोधर्मा अतः सविकारम् इन्द्रियादिविकारसहितं क्षेत्रं सर्वोत्पत्तिस्थानं सङ्क्षेपेण सम्यक्प्रकारेण उदाहृतं लीलार्थं प्रकटितमिति ज्ञानार्थं कथितमित्यर्थः।'),
('purushottama-sc:source:13.8','Puruṣottamajī','gita.13.7','sa','commentary','।।13.8।।एवं क्षेत्रस्वरूपमुक्त्वा ससाधनं ज्ञानस्वरूपमाह पञ्चभिः -- अमानित्वमिति। अमानित्वं स्वगुणोत्कर्षवर्णनप्रबोधराहित्यम्। अदम्भित्वं लोकदर्शनार्थधर्माद्यनुष्ठानाभावत्वम्। अहिंसा परपीडाराहित्यम्। क्षान्तिः दुष्टाद्यतिक्रमसहनम्। आर्जवमकौटिल्यम्। आचार्योपासनं गुरुसेवनम्। शौचं बाह्याभ्यन्तरभेदेन द्विविधम् बाह्यं मृत्तिकाजलादिना? आभ्यन्तरं भगवत्स्मरणात्मकम्। स्थैर्यं क्लेशादिष्वपि भगवत्परतया स्थितिः। आत्मविनिग्रहः क्षुधाशीतादिसहनेन शरीरसंयमः।'),
('purushottama-sc:source:13.9','Puruṣottamajī','gita.13.8','sa','commentary','।।13.9।।इन्द्रियार्थेषु इन्द्रियभोगेषु वैराग्यम्। अनहङ्कार एव च? च पुनः अहङ्कारराहित्यम्। एवकारेणाऽस्यावश्यकत्वं ज्ञापितम्। जन्मादिषु दुःखदोषयोरनुदर्शनं विचारः। तथाहि। जन्म -- अजन्मनो ब्रह्मांशस्याऽपि योनिमलादिसम्बन्धः। मृत्युर्भगवद्विस्मरणं? जरा शक्तिह्रासः? व्याधिः रोगादिक्लेशः।'),
('purushottama-sc:source:13.10','Puruṣottamajī','gita.13.9','sa','commentary','।।13.10।।किञ्चअसक्तिरिति। पुत्रदारगृहादिपदार्थेष्वसक्तिः आसक्तिराहित्यम्। अनभिष्वङ्गः तेषु समदुःखसुखतया तन्मयत्वाभावः। इष्टानिष्टोपपत्तिषु इष्टानिष्टप्राप्तिषु नित्यं भगवदिच्छाविचारेण समचित्तत्वम्।'),
('purushottama-sc:source:13.11','Puruṣottamajī','gita.13.10','sa','commentary','।।13.11।।च पुनः मयि अनन्ययोगेन लौकिकालौकिकेषु मच्छरणतया अव्यभिचारिणी अन्यत्र सद्बुद्धिराहित्येन भक्तिः? विविक्तदेशसेवित्वं भगवत्परिपन्थिरहिततद्देशसेवनशीलत्वम्? अरतिर्जनसंसदि जननादिक्लेशयुक्तलौकिकजीवसभायां अरतिः प्रतिष्ठाद्यनाकाङ्क्षा।'),
('purushottama-sc:source:13.12','Puruṣottamajī','gita.13.11','sa','commentary','।।13.12।।अध्यात्मज्ञाने आत्मस्वरूपज्ञाने नित्यभावः। तत्त्वज्ञानस्य अर्थात्मको भगवान् मोक्षो वा तस्य दर्शनं आलोचनरीत्या विचारः। एतत्पञ्चश्लोकोक्तं ज्ञानमिति प्रोक्तम्। एतद्युक्तो ज्ञानवान्। अतोऽन्यथा यत् विपरीतत्वं मानित्वादिभावयुक्तं तत् अज्ञानं? न ज्ञानमित्यर्थ। सङ्गानर्हा एतेऽपि त्याज्याः।'),
('purushottama-sc:source:13.13','Puruṣottamajī','gita.13.12','sa','commentary','।।13.13।।एवं ज्ञानस्वरूपमुक्त्वा৷৷৷৷৷৷৷৷৷৷৷৷. तेन ज्ञेयस्वरूपमाह -- ज्ञेयमित्यादिषड्भिः। स्वगुणरूपैरेवं पूर्वोक्तसाधनैर्यत् ज्ञेयं तत् प्रकर्षेण सर्वाङ्गयुक्तं वक्ष्यामि? कथयामीत्यर्थः। तत्कथनप्रयोजनमाह -- यत् ज्ञात्वा अमृतं मोक्षं अश्नुते प्राप्नोति। एवं कथनं प्रतिज्ञाय तत्स्वरूपमाह -- अनादीति। न विद्यते आदिरुत्पत्तिर्यस्य तादृशं? मत्परं अहमेव परो यस्य मत्स्थानभूतं ब्रह्म बृहत् व्यापकं च। तदेवाह -- न सत् सन्न भवति। तर्ह्यसद्भवति इति चेदित्याशङ्क्याह -- तत् असत् न उच्यते। सदसदनिश्चयोक्त्या दुर्ज्ञेयत्वेन ब्रह्मत्वं प्रतिपादितम्।'),
('purushottama-sc:source:13.14','Puruṣottamajī','gita.13.13','sa','commentary','।।13.14।।एवं सर्वाविषयत्वे ज्ञेयत्वं बाध्यते इति ज्ञेयत्वेन स्वरूपमाह -- सर्वत इति। सर्वतः पाणयः पादाश्च यस्य तत्। एवं विशेषणद्वयेन सर्वत्र क्रियाशक्तिः सर्वसेव्यत्वं च निरूपितम्। सर्वतः अक्षीणि शिरांसि मुखानि च यस्य। एवं विशेषणत्रयेण सर्वज्ञानवत्त्वं सर्वमुख्यत्वं ज्ञापितम्। सर्वतश्श्रुतिमत् सर्वतः श्रवणेन्द्रिययुक्तम्। अनेन भक्तादिस्तुतिश्रवणे योग्यत्वेन कृपालुत्वं प्रदर्शितम्। लोके स्वकीय इति शेषः। तर्हि परिच्छिन्नं भविष्यति इत्याशङ्क्याह -- सर्वं आवृत्य व्याप्य सर्वेन्द्रियादियुक्तमेव तिष्ठतीति भावः।'),
('purushottama-sc:source:13.15','Puruṣottamajī','gita.13.14','sa','commentary','।।13.15।।किञ्च -- सर्वेन्द्रियगुणाभासमिति। सर्वेषामिन्द्रियाणां चक्षुरादीनां गुणेषु रूपादिषु भासमानम्। अनेन यत्र सौन्दर्यादिकं यत्किञ्चिदपि तद्भगवत्सम्बन्धादेवेति ज्ञापितम्। तर्हि लौकिकेन्द्रियादियुक्तं भविष्यति इत्यत आह -- सर्वेन्द्रियैर्विवर्जितं? रहितमित्यर्थः। अनेनेन्द्रियाणां पूर्वोक्तानामलौकिकत्वं ज्ञापितम्। एतदेव विवेचयति -- असक्तमित्यादिना। असक्तं सर्वत्राऽऽसक्तिरहितं तेन सङ्गाभावः सूचितः। च पुनस्तादृशमेव,सर्वभृत् सर्वाधारभूतम्। सर्वधारणेन सगुणत्वमाशङ्क्याऽऽह -- निर्गुणं सत्त्वादिगुणरहितम्৷৷৷৷৷৷৷৷৷৷৷৷৷৷৷৷৷৷৷৷৷৷৷৷৷৷.। एवं गुणवैयर्थ्यमाशङ्क्याह -- गुणभोक्तृ च गुणेषु स्थित्वा तद्भोगं करोतीत्यर्थः। चकारेण तत्पालकमपीति ज्ञापितम्।'),
('purushottama-sc:source:13.16','Puruṣottamajī','gita.13.15','sa','commentary','।।13.16।।एवं भोगकर्तृत्वे व्यापकत्वं बाध्यत इत्यत आह -- बहिरिति। भूतानां चराचराणां बहिः भोक्तृत्वेन? अन्तस्तद्रूपेणात्मरूपेण वा तदेव? एवं बहिरन्तस्स्थत्वे सति भिन्नत्वेन व्यापकत्वहानिमाशङ्क्याह -- अचरं स्थावरं? चरमेव च जङ्गमं च। एवकारेण स्थावरत्वसहितमेव जङ्गमत्वं जङ्गमत्वसहितमेव स्थावरत्वं? तेन विरुद्धधर्माश्रयत्वं ज्ञापितम्। एवं सति सर्वज्ञेयत्वमेव स्यात्। पूर्वोक्तसाधनवत्सु को विशेषः इत्यत आह -- सूक्ष्मत्वादिति। तत् ब्रह्म तत्र तत्र लीलार्थरूपेण सूक्ष्मत्वात् साधनाभावे अविज्ञेयं विशेषेण ज्ञातुमशक्यमित्यर्थः। एतदेवाह दूरस्थं चान्तिके च तत्? बहिर्मुखानां दूरस्थं? भक्तानां च अन्तिके निकटे स्थितमित्यर्थः। चकारद्वयेनैतदुभयस्याऽपि लीलात्मकत्वं ज्ञापितम्। यद्वामर्यादास्थानां दूरस्थं? पुष्टिस्थानामन्तिके स्थितम्। यद्वा पुष्टिमार्गीयाणामेव विरहदशायामतितापेन पुरस्कृतं तच्च विरहरीत्या दूरस्थमेव? अन्तिके हृदये परोक्षरीत्या। तदज्ञानेन तज्जीवनार्थं निकटे च स्थितम्।मया परोक्षं भजता तिरोहितम् [भाग.10।32।21] इति रीत्येति भावः।'),
('purushottama-sc:source:13.17','Puruṣottamajī','gita.13.16','sa','commentary','।।13.17।।किञ्च -- अविभक्तमिति। भूतेषु स्थावरजङ्गमेषु स्वलीलार्थस्वस्वरूपात्मकत्वेन सर्वस्य प्रकटितत्वात् अभिन्नं रसार्थं द्वितीयरूपेण कृतत्वात् विभक्तमिव भिन्नमिव स्थितम्। इवपदेन स्वेच्छया तथा प्रदर्शयतीति ज्ञापितम्। किञ्च तत् पूर्वोक्तं ज्ञेयं भूतानां भर्तृ रक्षकं पोषकम्। भर्तृपदेन रमणशीलत्वं ज्ञापितं? तेन रमणार्थमेव स्थितिकाले रक्षकमित्यर्थः। वियोगात्मकप्रलयकाले ग्रसिष्णु ग्रसनशीलं? स्वस्मिन्नवरोधकमित्यर्थः। च पुनः सृष्टिकाले लीलात्मकरसदानात्मके प्रभविष्णु नानास्वरूपैः प्रभवनशीलम्।'),
('purushottama-sc:source:13.18','Puruṣottamajī','gita.13.17','sa','commentary','।।13.18।।किञ्च -- ज्योतिषामिति। ज्योतिषां रविचन्द्रादीनामन्यप्रकाशमानानामपि तदेव ज्योतिः प्रकाशकमित्यर्थः।अत्रायं भावः -- न तत्र सूर्यो भाति [कठो.5।15श्वे.उ.6।14मुण्ड.2।2।10] इत्यादिश्रुत्या तत्रैतेषामभानमुक्तं? तथाच तत्प्रकटनवैयर्थ्यं स्यात्तदर्थं तत्प्रकाशनेन तत्र शोभादिकारकमित्यर्थः। अन्यथाऽन्यत्र सर्वप्रकाशकत्वमपि न भवेत् [इति]। तर्हि मुख्यतमोरूपं सर्वप्रकाश्यत्वेन भविष्यतीत्यत आह -- तमसः परमिति। तमसः मुख्यतमसोऽपि परम् उपरि उत्कृष्टं वा उच्यते श्रूयते इत्यर्थः। अतएव श्रुतिरपि -- तमसा गूढमग्रे प्रकेतम् [ऋक्सं.8।7।17।3] इत्याह। ननु स्वप्रकाश्यत्वे स्वस्यैव नानास्वरूपात्मके सर्वेषां कथं न तज्ज्ञानं इत्यत आह -- ज्ञानमिति। ज्ञानबुद्धिवृत्त्यभिव्यक्त्यात्मकं च तदेव। तेन यत्र ज्ञापनेच्छा तत्रैव तद्रूपेणाविर्भवतीत्यर्थः। तथैव ज्ञेयं ज्ञेयरूपेणाविर्भूतमित्यर्थः। तथापि पुरुषोत्तमगृहात्मकमेवेत्याह -- ज्ञानगम्यमिति। ज्ञाने ज्ञानेन पूर्वोक्तरूपेण गम्यं प्राप्यं तेनाऽक्षरात्मकत्वं ज्ञापितम्। ननु पूर्वं ज्ञानरूपत्वेन सर्वागम्यत्वमुक्तं तत्कथं ज्ञानगम्यं इत्याह -- हृदीति। सर्वस्य प्राणिमात्रस्य हृदि धिष्ठितम्? अधिष्ठितमित्यर्थः। सर्वप्रेरकत्वेन स्थितं तेन यत्र तथेच्छा तत्र ज्ञानरूपेणाविर्भवति? यत्र न ज्ञापनेच्छा तत्राऽऽच्छादकत्वेन भवतीति भावः।'),
('purushottama-sc:source:13.19','Puruṣottamajī','gita.13.18','sa','commentary','।।13.19।।उपसंहरति -- इतीति। इति अमुना प्रकारेणमहाभूतानि [13।6] इत्यादिना क्षेत्रंअमानित्वं [13।8] इत्यादिना ज्ञानंअनादिमत्परं ब्रह्म [13।13] इत्यादिना ज्ञेयं? चकारेण सर्वमक्षरात्मकं समासतः सङ्क्षेपेण सौकर्यबोधार्थमुक्तम्। यदर्थमुक्तं तदाह -- मद्भक्त इति। एतदुक्तरूपं विज्ञाय विशेषेण मद्विभूत्यक्षरात्मकं ज्ञात्वा मद्भक्तो मद्भजनशीलः सन् मद्भावाय भावात्मकस्वरूपलाभाय उपपद्यते योग्यः समर्थो वा भवतीत्यर्थः।'),
('purushottama-sc:source:13.20','Puruṣottamajī','gita.13.19','sa','commentary','।।13.20।।एवं पूर्वप्रतिज्ञातंतत्क्षेत्रं यच्च यादृक्च [13।4] इति निरूपितम् स्वांशत्वेन तत्र क्षेत्रक्षेत्रज्ञसंज्ञा कथं इत्याशङ्क्ययद्विकारि [13।4] इत्यादिना पूर्वमेव प्रतिज्ञातं उभयोः स्वरूपं निरूपयति -- प्रकृतिमित्याद्यैः पञ्चभिः पद्यैः। प्रकृतिं सर्वजननसमर्था व्यापकत्वादिधर्मयुतां भगवच्छक्तित्वादनादिं? पुरुषं च,तद्रसभोक्तारं भोक्त्रंशरूपं भगवदंशत्वादनादिम्? एवमुभावपि अनादी विद्धि जानीहि।अत्रायं भावः -- पूर्वं ब्रह्मप्रकृतिपुरुषरूपेण त्रिचित्ररसभोगार्थमाविभूर्य ततः सर्वं कृतवान्? स्वांशानां जीवानां ज्ञापनार्थं तत्र मोहकस्वभावमायासम्बन्धादन्यथा ज्ञानेन सम्बन्धो भवति? तदभावायाऽनादिस्वभगवच्छक्तिभगवदंशादिज्ञानेन मोहो न भवेदित्यर्थः। एवं तावनादी ज्ञात्वा विकारान् देहेन्द्रियादीन् सेवौपयिकान् गुणान् सुखदुःखमोहात्मकान् प्रकृतिसम्भवानेव विद्धि।अत्रायं भावः कयाचिदवस्थयाऽवस्थितस्वस्वरूपेण स्वरसानुभवार्थं देहादीन् सत्तात्मकान् शक्तितः प्रकटीकरोति? तथैव सङ्गमसुखानुभवविरहदुःखानन्दानुभवासक्त्यात्मकानन्दमोहात्मकान् गुणानपि प्रकटयति? अतस्तथा विद्धि। एवं ज्ञानप्रयोजनं चाग्रे स्फुटीभविष्यति।'),
('purushottama-sc:source:13.21','Puruṣottamajī','gita.13.20','sa','commentary','।।13.21।।एतदेव विशदयति -- कार्येति। कार्यस्य स्वरसानुभवात्मकस्य कारणानि देहगुणादीनि तेषां कर्तृत्वे प्रकटकरणे हेतुः प्रकृतिः पूर्वोक्तरूपा शक्तिरुच्यते। तथैव पुरुषः सुखदुःखानां सङ्गमविरहात्मकादीनां भोक्तृत्वे तद्रसज्ञत्वे हेतुः कारणमुच्यते।'),
('purushottama-sc:source:13.22','Puruṣottamajī','gita.13.21','sa','commentary','।।13.22।।ततः किमत आह -- पुरुष इति। पुरुषः पुरुषरूपेण प्रकटो भगवान्? प्रकृतिस्थः स्वरसानुभवस्थानस्थितः सन् प्रकृतिजान् गुणान् भुङक्ते इतरसम्भोगं करोतीत्वर्थः। न तु पुरुषरूपस्य सदसद्योनिदेवतिर्यगादिरूपजन्मसु गुणरसभोगेच्छा कारणं हेतुरित्यर्थः।'),
('purushottama-sc:source:13.23','Puruṣottamajī','gita.13.22','sa','commentary','।।13.23।।एवं रसभोगेच्छां कारणत्वेनोक्त्वा तत्र देहादिषु प्रविष्टस्य स्वल्पांशस्याविद्यात्मकजीवस्य भोगादिदर्शने पुरुषस्य कथं भोगः कथं तेन जीवस्य संसारः इत्याशङ्कायां समाधत्ते -- उपद्रष्टेति। परः पुरुषः पुरुषोत्तमः अस्मिन्देहे उपद्रष्टा? उपसमीपे द्रष्टा साक्षी? तथा अनुमन्ता अनुमोदिता? भर्त्ता धारकः? भोक्ता रक्षकः? महेश्वरः महांश्चासावीश्वरश्च सः। तथैव परमात्मा। चकारेण प्राणजीवादिरप्युक्त इत्यर्थः।अयं भावः -- देहादिकं सर्वं भगवति निवेद्य तद्दत्तप्रसादत्वेन सेवार्थोपयोगिभोगकर्तुः साक्षी -- मुख्यसेवायां तदुपयोगकारयिता। एवमेव कृतसमर्पणमोदे अनु पश्चान्मोदिता। एवमेव भर्त्ता? पतित्वेन धारकपोषक इत्यर्थः। तथैव भोक्तृत्वेन स्वीयत्वज्ञानेन रक्षकः। तथैव महेश्वरः कर्तृ़णां ब्रह्मादीनामपि प्रभुः? तेन तादृग्वस्तुकर्त्तेत्यर्थः। तथैव परमात्मा तादृग्धर्मवतो मित्ररूप इत्यर्थः।'),
('purushottama-sc:source:13.24','Puruṣottamajī','gita.13.23','sa','commentary','।।13.24।।एवमनूद्यैवंविदः संसाराभावमाह -- य एवमिति। एवं पूर्वोक्तप्रकारेण यः पुरुषं प्रकृतिं च गुणैः सह भगवद्रूपं वेत्ति जानाति? ज्ञात्वा तथा सर्वथा वर्तमानोऽपि तथाऽऽचरणशीलो यो भवति? स भूयो नाभिजायते संसारे नोत्पन्नो भवति। किन्तु मुक्त एव भवतीत्यर्थः।'),
('purushottama-sc:source:13.25','Puruṣottamajī','gita.13.24','sa','commentary','।।13.25।।नन्वेवं ज्ञानेनैव मुक्तिश्चेत्तदाऽन्यसाधनानामप्रयोजकत्वं स्यादित्याशङ्क्यान्यसाधनस्वरूपमाह -- ध्यानेनेति द्वयेन। केचित् ज्ञानिनः ध्यानेन परिकल्पनेन आत्महृदये आत्मना मनसा आत्मानं आत्मरूपं भगवन्तं पश्यन्ति। अन्ये साङ्ख्येन नित्यानित्यवस्तुविवेकात्मकेन योगेन तथा पश्यन्ति। अपरे कर्मयोगेन कर्मसु तदात्मकप्राकट्यरूपयोगेन पश्यन्ति तद्रूपम्।'),
('purushottama-sc:source:13.26','Puruṣottamajī','gita.13.25','sa','commentary','।।13.26।।अन्ये तु मूर्खाः अजानन्तः अन्येभ्यो गुरुभ्यः श्रुत्वा विनैवानुभवम्? एवं पूर्वोक्तप्रकारैरुपासते उपासनां कुर्वन्ति? तेऽपि च सर्वे मृत्युमतितरन्त्येव युक्ता भवन्तीत्यर्थः। कथं इत्यत आह -- श्रुतिपरायणाः? श्रुत्युक्तप्रकारत्वात् श्रद्धया करणादित्यर्थः। अयमर्थः -- स्ववाक्यसत्यत्वाय तानपि तारयामि निर्बन्धेन? न तु स्नेहेन इदमेवैधकारापिशब्दाभ्यां व्यञ्जितम्।'),
('purushottama-sc:source:13.27','Puruṣottamajī','gita.13.26','sa','commentary','।।13.27।।एतेषु पूर्वोक्तप्रकारेषु किमुत्तमम् अथ च कथं ज्ञेयम् इत्यत आह -- यावदिति। यावद्वस्तुमात्रं स्थावरजङ्गमं तत् क्षेत्रक्षेत्रज्ञयोः पूर्वोक्तस्वरूपयोगात् क्रीडार्थकमत्संयोगात् सत्त्वं सत्त्वात्मकं विद्धि जानीहि। भरतर्षभ इतिसम्बोधनं तदर्थज्ञानयोग्यत्वाय।'),
('purushottama-sc:source:13.28','Puruṣottamajī','gita.13.27','sa','commentary','।।13.28।।एतदेव फलरूपत्वेन विशदयति -- सममिति। सर्वेषु प्रपञ्चान्तःपातिस्थावरजङ्गमात्मकेषु भूतेषु लीलया अनेकविधरसभोगार्थं तिष्ठन्तं रसानुभवार्थं नीचोच्चादिधर्मरहितं समं? तेषु विनश्यत्सु च अविनश्यन्तं तादृग्लीलावबोधरहितत्वाद्विनाशं प्राप्तेषु अन्यथाभावेन क्रोधादिराहित्येन तथैव लीलानुभवं कुर्वन्तं यः पश्यति? स परमेश्वरं पश्यति। अत एवंदर्शनाभावे सापराधो भवत्येव।'),
('purushottama-sc:source:13.29','Puruṣottamajī','gita.13.28','sa','commentary','।।13.29।।पश्यन् मुक्तो भवतीत्याह -- सममिति। सर्वत्र प्रापञ्चिकपदार्थमात्रे समवस्थितं सम्यक्प्रकारेण तथाभूतलीलार्थमवस्थितं ईश्वरं सर्वसामर्थ्ययुक्तं समं पश्यन् आत्मना स्वलीलात्मरूपेण आत्मस्वरूपमविकृतमात्मानं हि निश्चयेन न हिनस्ति अन्यथा न प्राप्नोति? यथार्थरूपेण ज्ञात्वा प्रपद्यते। ततः परामुत्कृष्टां वैकुण्ठाख्यां गतिं याति। हीति युक्तत्वम् अन्यथाप्रपत्तेर्निषिद्धत्वात्। अत एवयोऽन्यथा सन्तमात्मानमन्यथा प्रतिपद्यते। किं तेन न कृतं पापं चौरेणाऽऽत्मापहारिणा [म.भा.1।74।27] इति सम्पठ्यते।'),
('purushottama-sc:source:13.30','Puruṣottamajī','gita.13.29','sa','commentary','।।13.30।।ननु सर्वरूपेण यदि सर्वत्र स एवास्ति? तदा कथं न सर्वे तथा पश्यन्ति इत्याशङ्क्याऽऽह -- प्रकृत्यैवेति। प्रकृत्या लीलोपयोगीन्येव क्रियमाणानि कर्माणि यः पश्यति? चकारेण कार्यमाणानि? तथा आत्मानं जीवमकर्तारं तदिच्छाभावे सर्वकरणाशक्तं यः पश्यति स पश्यति परमेश्वरमिति शेषः। अथवा स एव पश्यति अन्ये त्वन्धा एवेति भावः।'),
('purushottama-sc:source:13.31','Puruṣottamajī','gita.13.30','sa','commentary','।।13.31।।एवमेव सर्वेषां लये सूक्ष्मत्वमुत्पत्तौ विस्तरं च यदा ब्रह्मणः सकाशादेव तद्रूपं पश्यति तदा ब्रह्मत्वमाप्नोतीत्याह -- यदेति। यदा भूतानां स्थावरजङ्गमानां पृथग्भावं ब्रह्मणो भेदं विचित्रानेकरूपात्मकं एकस्थं संहारेच्छात्मकरमणात्मकब्रह्मस्वरूपस्थं प्रलये अनुपश्यति? च पुनः तत एव प्रपञ्चरमणेच्छुब्रह्मण एव सृष्टिसमये विस्तारमनुपश्यति? तदा ब्रह्म सम्पद्यते ब्रह्मत्वमाप्नोतीत्यर्थः।'),
('purushottama-sc:source:13.32','Puruṣottamajī','gita.13.31','sa','commentary','।।13.32।।ननु यथा ब्रह्मांशस्यादिजीवस्य देहसम्बन्धात् कर्मलेपस्तेनैवाज्ञानं तन्नाशश्च प्रेरकात्मसम्बन्धात्तस्यैव जीवसम्बन्धालेपे सति कथं समदर्शनं इत्याशङ्क्याऽऽह -- अनादित्वादिति। यस्यैवोत्पत्तिस्तस्यैवान्यसम्बन्धेन नाशः। स च अनादिर्नत्वाविद्यकजीवभाववदुत्पत्तिरतएव तत्सम्बन्धाभावार्थं साक्षित्वं पूर्वं निरूपितम्। तस्मात् गुणसम्बन्धिन एव तन्नाशे नाशः? स च निर्गुणस्तस्मादयं परमात्मा अव्ययः परसम्बन्धादिनाशशून्यः। अतः शरीरस्थोऽपि कर्माणि न करोति? अत एव न लिप्यते।'),
('purushottama-sc:source:13.33','Puruṣottamajī','gita.13.32','sa','commentary','।।13.33।।एतदर्थं दृष्टान्तमाह -- यथेति। यथा सर्वगतं सर्वत्र जडजीवान्तर्गतमाकाशं सौक्ष्म्यात् स्वरूपाभावात् सङ्गरहितं तेन सह नोपलिप्यते? तथा सर्वत्र उच्चनीचोऽपि देहावस्थितोऽप्यात्मा न लिप्यते।'),
('purushottama-sc:source:13.34','Puruṣottamajī','gita.13.33','sa','commentary','।।13.34।।नन्वलेपे देहादिगुणप्रकाशकत्वं कथं इत्याशङ्क्याऽऽह -- यथेति। यथैको रविर्मदंशात्मकत्वात् कृत्स्नं सम्पूर्णमिमं लोकं प्रकाशयति? तथा मदंशकत्वादेव क्षेत्री क्षेत्रं कृत्स्नं सम्पूर्णं प्रकाशयति। रवेर्लोचनात्मकत्वात्तद्दृष्टान्ते मत्कृपादृष्ट्या क्रीडोपयोग्यत्वायाऽऽत्मापि क्षेत्रं प्रकाशयतीति ज्ञापितम्। भारतेतिसम्बोधनेन सैन्यमध्ये स्थितो मदंशत्वात्तद्दोषैस्त्वं यथा न लिप्यस इति ज्ञापितम्।'),
('purushottama-sc:source:13.35','Puruṣottamajī','gita.13.34','sa','commentary','।।13.35।।उपसंहरति -- क्षेत्रक्षेत्रज्ञयोरिति। एवं पूर्वोक्तप्रकारेण क्षेत्रक्षेत्रज्ञयोरन्तरं भेदं लौकिकसृष्टितः ज्ञानचक्षुषा ये विदुः? च पुनः भूतानां सम्बन्धिनी या प्रकृतिः संसारोपयोगिनी ततो मोक्षसाधनं ध्यानाद्यात्मकं ये विदुस्ते परं मोक्षं यान्ति प्राप्नुवन्तीत्यर्थः।क्षेत्रक्षेत्रज्ञयोरेवं रूपमुक्त्वेश्वरः स्वयम्। मोहं निवारयामास फाल्गुनस्य नमामि तम्।।'),
('purushottama-sc:source:14.1','Puruṣottamajī','gita.14.1','sa','commentary','।।14.1।।कृष्णः स्वगुणसम्बन्धात्प्रपञ्चस्य विचित्रताम्। बोधनार्थं पाण्डवाय वर्णयामास विस्तरात्।।1।।अथ स्वक्रीडार्थं विरचितसत्त्वादिगुणसङ्गजप्रपञ्चवैचित्र्यस्वरूपेण फलात्मकं निरूप्य वर्णयति? तत्र श्लोकद्वयेन फलरूपस्वरूपमाह -- परमिति। परं भगवत्सम्बन्धिफलात्मकं ज्ञानं ज्ञेयसाधनं तेन भूयः पूर्वमुक्तं साधारण्येन? पुनः प्रकर्षेण ससाधनं वक्ष्यामि कथयामीत्यर्थः। भूयः प्रकर्षकथने विशेषणेन विशेषयति। कीदृशं तत् ज्ञानानां पूर्वोक्तज्ञेयसाधनानां मध्ये उत्तमं मुख्यमित्यर्थः। एवं कथनं प्रतिज्ञाय फलरूपत्वमाह -- यदिति। यत् ज्ञानं ज्ञात्वा मुनयो मननशीलास्तदभ्यसनपराः सर्वे परां सिद्धिमनुभवात्मिकां इतः लौकिकदेहात् गताः प्राप्ताः।सर्वे इतिपदेन येषां सिद्धिर्जाता तेषामनेनैवेति ज्ञापितम्। ज्ञानानामुत्तममनेन विशेषणेन ज्ञानेष्वेवोत्तमत्वं? न तु भक्तित इति व्यञ्जितम्।'),
('purushottama-sc:source:14.2','Puruṣottamajī','gita.14.2','sa','commentary','।।14.2।।ज्ञानेन कथं सिद्धिं प्राप्ताः इत्यत आह -- इदमिति। इदं वक्ष्यमाणं ज्ञानमुपाश्रित्य साधनानुष्ठानं कृत्वा मम साधर्म्यं समानधर्मत्वं लीलायोग्यत्वमागताः सन्तः सर्गेऽपि आदिसर्गे ब्रह्मादिसृष्टावपि नोपजायन्ते। च पुनः प्रलये सृष्टिसंहारे न व्यथन्ति? न पुनरावर्तन्त इत्यर्थः।'),
('purushottama-sc:source:14.3','Puruṣottamajī','gita.14.3','sa','commentary','।।14.3।।एवं फलरूपतामुक्त्वा तदेव प्रपञ्चयति -- ममेति। महत् देशकालाद्यपरिच्छिन्नं ब्रह्म बृहत्त्वाद्बृंहणत्वेन मल्लीलार्थवस्तुवृद्धिहेतुत्वात् ब्रह्म प्रकृतिः मम पुरुषोत्तमस्य योनिः क्रीडार्थविचित्रानेकवस्तुरूपप्रकटनात्मकगर्भाधानस्थानम्। तस्मिन् गर्भं क्रीडेच्छात्मकभावं दधामि स्थापयामि। ततो गर्भाधानानन्तरं सर्वभूतानां सम्भव उत्पत्तिर्भवति। भारत इति सम्बोधनं विश्वासार्थम्।'),
('purushottama-sc:source:14.4','Puruṣottamajī','gita.14.4','sa','commentary','।।14.4।।नन्वनेकविधवस्तूनामनेकयोनिषु नानाविधप्रतीतौ कथमेकयोनित्वं इत्यत आह -- सर्वयोनिष्विति। पूर्वं तु सर्वोत्पत्तिरूपसर्वयोन्युत्पत्तिः? ततः सर्वयोनिषु हे कौन्तेय या मूर्तयः स्वरूपाणि सम्भवन्ति? तासां महद्ब्रह्म प्रकृतियोनिरुत्पत्तिस्थानं मातृस्थानीयं बीजप्रदः इच्छाज्ञानात्मकबीजप्रदः पिता उत्पादकः? अहमेवेत्यर्थः। तदेव ब्रह्म मदिच्छया नानायोनिरूपेण भूत्वा भासते इत्यर्थः।'),
('purushottama-sc:source:14.5','Puruṣottamajī','gita.14.5','sa','commentary','।।14.5।।ननु लीलात्मकप्रकृत्युत्पादितलीलार्थदेहादिषु स्थितस्य बीजस्य बन्धः कथं इत्यत आह -- सत्त्वमिति। सत्त्व रजस्तम इति संज्ञका गुणाः प्रकृतिसम्भवाः प्रकृतितः सम्भव उत्पत्तिर्येषां तादृशाः ते अव्ययं विनाशादिधर्मरहितं भगवतश्चिदंशात्मकं देहिनं जीवं तद्रूपेण तद्द्वारा गुणभोगार्थमाविर्भूतं निबध्नन्ति वशीकुर्वन्ति? रसपरत्वादित्यर्थः।'),
('purushottama-sc:source:14.6','Puruṣottamajī','gita.14.6','sa','commentary','।।14.6।।अथ त्रयाणां बन्धनरीतिं सलक्षणामाह -- तत्रेति। तत्र गुणत्रये सत्त्वं निर्मलत्वाद्भगवदिच्छात्मकपदार्थस्थितिहेतुत्वेन शुद्धत्वात् प्रकाशकं भगवद्रमणात्मकसर्वस्वरूपप्रकटीकरणसमर्थम् अनामयं भगवत्सेवाप्रतिबन्धात्मकरागादिदोषरहितम्? अतः सुखसङ्गेन भगवतः साधनात्मकसेवनसुखजनकदेहाद्युत्तमत्वसङ्गेन बध्नाति। च पुनः ज्ञानसङ्गेन ज्ञानोत्पत्तिसाधकत्वेन बध्नाति। अनघ इतिसम्बोधनेन मत्कृपाविशिष्टत्वात्तव बन्धाभाव इति ज्ञापितम्।'),
('purushottama-sc:source:14.7','Puruṣottamajī','gita.14.7','sa','commentary','।।14.7।।सत्त्वलक्षणमुक्त्वा रजोलक्षणमाह -- रजो रागात्मकमिति। रजः रजोगुणं रागात्मकं अनुरञ्जनात्मकं नानापदार्थोत्पादनेन भगवद्रञ्जनात्मकं विद्धि। तत् तृष्णासङ्गसमुद्भवं तृष्णा,भगवदर्थोत्पन्नवस्तुमात्राज्ञानेन स्वाभिलाषः? तत्सङ्गेन समुद्भव उत्पत्तिर्यस्य तादृशं देहिनं? न तु भगवदर्थकज्ञानात्मकम्। कर्मसङ्गेन तत्स्वाभिलषितप्राप्त्यर्थं क्रियासङ्गेन बध्नाति लौकिकासक्तिं जनयतीत्यर्थः।'),
('purushottama-sc:source:14.8','Puruṣottamajī','gita.14.8','sa','commentary','।।14.8।।तमसो लक्षणं सबन्धकमाह -- तमस्त्विति। तमः पूर्वोक्तभगवल्लीलाद्यज्ञानाज्जातं प्रलयात्मकत्वात् भगवद्विस्मारणात्मकं सर्वदेहिनां मोहनं भ्रमजनकं विद्धि। प्रमादालस्यनिद्राभिर्भगवत्सेवाप्रतिबन्धात्मकत्रयरूपाभिरन्यथाज्ञानेन तं बध्नाति। प्रमादो भगवदनवधानता। आलस्यं भगवत्सेवानुद्यमः। निद्रा चित्तस्थ ज्ञाननाशः।'),
('purushottama-sc:source:14.9','Puruṣottamajī','gita.14.9','sa','commentary','।।14.9।।एवं सत्त्वादीनां स्वरूपमुक्त्वा तेषां स्वकार्यकरणातिशयत्वमाह -- सत्त्वमिति। सत्त्वं सत्त्वगुणः सुखे भगवज्ज्ञानात्मके सञ्जयति संयोजयति। एवमेव रजः कर्मणि पूर्वोक्ते संयोजयति। तथा तमो भगवदीयसङ्गादिना जायमानं ज्ञानं निद्रालस्याद्यैरावृत्य प्रमादे अनवधानतायां संयोजयति। यद्वा सुख उत्पादिते सत्त्वं सञ्जयति सर्वोत्कर्षेण तिष्ठति? तथैव कर्मणि रजः? प्रमादे तमः।अत्रायं भावः -- भगवता त्रयोऽपि गुणा एतद्वैचित्र्यार्थमेवोत्पादितास्तेषां तत्कृतकार्यदर्शनेन सन्तुष्यति प्रभुस्तेनैव तदुत्कर्षः सिद्ध्यतीति।'),
('purushottama-sc:source:14.10','Puruṣottamajī','gita.14.10','sa','commentary','।।14.10।।ननु सुखदुःखाद्यदृष्टसाधनत्वे सति स्वकार्यकरणमन्यथाभावकत्वं कथं इत्याशङ्क्य तेषां तथा सामर्थ्यं मया दत्तमस्तीति ज्ञापनाय सिद्धवत्कारेणानुवदति -- रजस्तम इति। रजस्तमः दुःखाज्ञानात्मकगुणद्वयमभिभूय तिरस्कृत्य सत्त्वं भवतीत्यर्थः। भारत इतिसम्बोधनेन यथा मदिच्छया सर्वपराभवेन त्वं जयसि तथेत्यर्थो द्योतितः। एवं रजोऽपि सत्त्वं तमश्चेति गुणद्वयाभिभवेन भवति। एवकारेण तमसो मोहकसामर्थ्याधिक्येऽपि तथाकर्तृत्वं व्यज्यते। तथा तमः सत्त्वं रजश्चाभिभूय भवतीत्यर्थः।'),
('purushottama-sc:source:14.11','Puruṣottamajī','gita.14.11','sa','commentary','।।14.11।।ननु तदभिभवेन तत्तदुत्पत्तिः कथं न ज्ञातव्या इत्यत आह -- सर्वद्वारेष्विति। अस्मिन् देहे साधनात्मके सर्वद्वारेषु श्रोत्रादिषु यदा भगवत्सम्बन्धित्वेन प्रकाशो दर्शनमुपजायते? अथवा ज्ञानं? तदा सत्त्वं विवृद्धं विशेषेण भगवत्सम्बन्धित्वेन विवृद्धं विद्यात्।अयमर्थः -- श्रोत्रद्वारेण भगवत्कथाश्रवणात्मकः? वचनद्वारेण च कीर्तनात्मकः? प्रसादग्रहणात्मकः? नासाद्वारेण च गन्धादिग्रहणम्। एवं सर्वत्रेति भावः।'),
('purushottama-sc:source:14.12','Puruṣottamajī','gita.14.12','sa','commentary','।।14.12।।एवं सत्त्वज्ञानमुक्त्वा रजोज्ञानरूपमाह -- लोभ इति। लोभो भगवत्सेवार्थं स्वेच्छया दत्ताप्तव्यवहारयोगद्रव्ये सत्यपि लौकिकासक्त्या पुनर्द्रव्येच्छयेतस्ततो मनोधावनेन तद्यत्नादिकरणे प्रवृत्तिः क्रियाकरणम्। आरम्भः कर्मणां लौकिकस्वोपभोग्यवस्तुकरणम्? अशमः अशान्तिःप्रातरिदं कर्त्तव्यमद्येदं कृतं इत्यादिविचारेण चित्तोद्वेगः? स्पृहा स्वायोग्यवस्तुन्यपीच्छा? रजसि विवृद्धे एतानि जायन्ते। एतदुत्पत्तौ रजोविवृद्धिं विद्यादित्यर्थः। भरतर्षभ इति सम्बोधनं राज्याद्यर्थस्पृहाभावेनैतद्दोषराहित्याय।'),
('purushottama-sc:source:14.13','Puruṣottamajī','gita.14.13','sa','commentary','।।14.13।।तमसो ज्ञानायाऽऽह -- अप्रकाश इति। अप्रकाशश्चित्ताप्रसादः। अप्रवृत्तिः भगवत्सेवनभगवदीयसङ्गाद्यनुद्यमः। प्रमादो भगवद्भजनाननुसन्धानम्। मोहः संसारासक्तिः। हे कुरुनन्दन तमसि विवृद्धे सत्येतानि जायन्ते।'),
('purushottama-sc:source:14.14','Puruṣottamajī','gita.14.14','sa','commentary','।।14.14।।एवं विवृद्धौ सत्यां मरणान्तं तेन यान्त्यतस्तत्सम्बन्धिदेहाप्तिर्भवतीत्याह -- यदेतिपद्येन। सत्त्वे प्रवृद्धे -- तुशब्दोऽन्यव्यवच्छेदकः -- यदा देहभृज्जीवः प्रलयं याति मृत्युमवाप्नोति तदोत्तमविदान् उत्तमैर्ज्ञानिभिर्ये ज्ञातुं योग्यास्तान् लोकान् अमलान् वैष्णवब्राह्मणादीन् प्रतिपद्यते प्राप्नोतीत्यर्थः।'),
('purushottama-sc:source:14.15','Puruṣottamajī','gita.14.15','sa','commentary','।।14.15।।किञ्चैवमेव रजसि प्रवृद्धे प्रलयं गत्वा मृत्युमवाप्य कर्मसङ्गिषु कर्मासक्तेषु तेषु नरेषु पुनस्तदाचरणेन तत्फलभोगार्थं जायते। तथा तमसि प्रवृद्धे प्रलीनो मृतो मूढयोनिष्वासुरेषु जायते।'),
('purushottama-sc:source:14.16','Puruṣottamajī','gita.14.16','sa','commentary','।।14.16।।तथाजातानां किं फलं इत्यत आह -- कर्मण इति। सुकृतस्य सुष्ठु भगवदाज्ञया भगवत्तोषहेतुत्वेन कृतस्य सात्त्विकस्य कर्मणः सात्त्विकं विष्णुप्रसादात्मकं निर्मलं दोषरहितं फलमाहुः व्यासकपिलादय इत्यर्थः। तु पुनः रजसो राजसकर्मणो दुःखं संसारात्मकं फलमाहुः। तथा तमसः कर्मणोऽज्ञानं भगवद्वैमुख्यात्मकं फलमाहुः। कर्मस्वरूपं चाऽग्रेऽष्टादशे [श्लो.2325] वक्ष्यति।'),
('purushottama-sc:source:14.17','Puruṣottamajī','gita.14.17','sa','commentary','।।14.17।।ननु स्वरूपज्ञानाभावे कथं तादृक्कर्मकरणं सम्भवति इत्यत आह -- सत्त्वादिति। सत्त्वात् ज्ञानं सञ्जायते? तादृक्स्वभावविशिष्टस्यैव प्रकटनात्। तथा रजसो रजोगुणाल्लोभः पापमूलको भवतीति। तस्य च दुःखात्मकत्वात्तदेव भवति। तमसस्तामसगुणात् प्रमादमोहौ भवतः। ततस्ताभ्यां चाज्ञानमेव भवतीत्यर्थः।'),
('purushottama-sc:source:14.18','Puruṣottamajī','gita.14.18','sa','commentary','।।14.18।।अथ तेषां फलं तद्रूपं चाह -- ऊर्ध्वमिति। सत्त्वस्थाः सात्त्विककर्मनिरता ऊर्ध्वं सत्यादिलोकं गच्छन्ति। राजसा राजसकर्मनिरता मध्ये मनुष्यलोके दुःखावृते राज्यादिसुखफले तिष्ठन्ति। जघन्यगुणतामसतद्वृत्तिस्थास्तत्कर्मसु वर्तमानास्तामसा अधो नरकादिनीचयोनिषु गच्छन्ति।'),
('purushottama-sc:source:14.19','Puruṣottamajī','gita.14.19','sa','commentary','।।14.19।।एवं स्वेच्छया स्वक्रीडार्थोत्पादितगुणादिरूपमुक्त्वा कृतोच्चमध्यनीचादिधर्मेषूच्चत्वादिबुद्धिरहितो मत्क्रीडाज्ञानवांस्तत्सङ्गरहितो यः स मद्भक्तिमाप्नोतीत्येतदर्थमेतन्निरूपितमित्याह -- नान्यमिति। यदा मत्कृपाविशिष्टकाले द्रष्टा विवेकवान् गुणेभ्यः स्वक्रीडार्थप्रकटरूपेभ्यः कृत्वा कर्तारं सर्वमूलभूतमनुपश्यति? नान्यम् च पुनः गुणेभ्यो विचित्ररूपेभ्यः परं पुरुषोत्तमं वेत्ति स मद्भावं मद्भक्तिमधिगच्छति? प्राप्नोतीत्यर्थः।अत्रायं भावः -- गुणकृतनानावैचित्र्यदर्शनेन पुरुषोत्तममाहात्म्यज्ञानेन सर्वत्र तद्वैचित्र्यं पश्यन्तं तत्कर्तारं तद्रूपेणाऽऽविर्भूतम् अनु तद्वदेव यथा भगवान् स्वात्मकमेव पश्यति तथा पश्यति? नान्यं कञ्चन पश्यति स मद्भावं प्राप्नोति।'),
('purushottama-sc:source:14.20','Puruṣottamajī','gita.14.20','sa','commentary','।।14.20।।ततो मद्भावयुक्तो गुणदोषाभिभूतो न भवतीत्याह -- गुणानेतानिति। देही जीवो देहसमुद्भवान् देहानां समुद्भव उत्पत्तिर्येभ्यस्तादृशानेतान् लौकिकान् न त्वलौकिकान् त्रीन् गुणानतीत्य अतिक्रम्य? जन्म तत्कर्मभोगार्थकं? मृत्युस्तद्भोगसमाप्तिरूपो भगवद्विस्मरणरूपो वा? जरा सेवाप्रतिबन्धरूपा? दुःखं संसारात्मकम्? एतैर्विमुक्तः अमृतं मरणादिदोषरहितम् लौकिकं देहमश्नुते भुङ्क्ते प्राप्नोतीत्यर्थः। अथवा अमृतमलौकिकं देहं प्राप्य मया सह सर्वकामानश्नुते सोऽश्नुते सर्वान् कामान् सह [तै.उ.2।1] इति श्रुत्युक्तरीत्या देहीतिपदादिदं व्यज्यते अन्यथा देहवत्पदं व्यर्थं स्यादिति भावः।'),
('purushottama-sc:source:14.21','Puruṣottamajī','gita.14.21','sa','commentary','।।14.21।।एवमेतांस्त्रीन् गुणानिति भगवतोक्तं? तेनान्येऽपि गुणाः सन्ति? यैरेतदतिक्रमो भवतीति विचार्याऽर्जुनस्तथैव विज्ञापयति -- कैर्लिङ्गैरिति। हे प्रभो सर्वकरणसमर्थ कैर्लिङ्गैश्चिह्नैरेतान् बन्धनात्मकांस्त्रीन् गुणान् अतीतो भवति? अतिक्रमं कृत्वा अलौकिकदेहवान् भवतीत्यर्थः। ततो देहाप्त्यनन्तरं किमाचारः कीदृगाचारवान् च पुनः एतांस्त्रीन् गुणानतीत्य कथं केनोपायेन वर्त्तते तं कथयेत्यर्थः।'),
('purushottama-sc:source:14.22','Puruṣottamajī','gita.14.22','sa','commentary','।।14.22।।अत्रोत्तरं मद्गुणैरेव सर्वं भवतीति ज्ञापनाय गुणसङ्ख्याकैः श्लोकैराह भगवान् -- प्रकाशं चेति। प्रकाशं सर्वद्वारेष्वलौकिकानुभवसिद्ध्यर्थं मदीयालौकिकमत्स्वरूपात्मकसत्त्वोपस्थापितालौकिकानुकरणात्मकलौकिकरूपम्। इदमेव चकारेण व्यञ्जितम्। च पुनः तथैव प्रवृत्तिं? चस्त्वर्थे। तथाच महदनुभवरससिद्ध्यर्थं विप्रयोगलयात्मकरूपं मोहमेव केवलं मोहं वा? एतादृक्श्रवणेऽपि भयाभावाय हे पाण्डव न द्वेष्टि मदिच्छागतानलौकिकान् लौकिकसरूपान्। किञ्चैवं सात्त्विकादित्रयाण्येव कार्याणि प्रवृत्तानि मदिच्छया प्राप्नोति। अतएव स्वतः प्रवृत्तिरुक्ता। स्वेच्छात्वज्ञापनाय लौकिकत्वेन प्रतिबन्धकतया न द्वेष्टि तत्त्यागाय यत्नं न करोति। तथैव मदिच्छाभावे निवृत्तानि न काङ्क्षति स गुणातीत उच्यते इति चतुर्थश्लोकेनाऽन्वयः।'),
('purushottama-sc:source:14.23','Puruṣottamajī','gita.14.23','sa','commentary','।।14.23।।एवं लिङ्गोत्तरमुक्त्वा आचारोत्तरमाह -- उदासीन इति। उदासीनवत्,सुखदुःखप्राप्त्यभावराहित्येन मत्कृतिं साक्षिरूपेण पश्यन्नासीनो गुणैर्लौकिकैर्मत्कृतिं पश्यन्नात्मस्वरूपान्न विचाल्यते। किञ्च गुणाः भगवदात्मकाः गुणेषु स्वकार्येषु वर्तन्ते स्वत एव भगवदिच्छयेत्येवं प्रकारेणैवावतिष्ठति? नेङ्गते न चलति पूर्वरूपात्।');
INSERT INTO commentary_fts (unit_id,author,canonical_ref,language,content_type,content) VALUES
('purushottama-sc:source:14.24','Puruṣottamajī','gita.14.24','sa','commentary','।।14.24।।किञ्च समदुःखसुखः समे दुःखसुखे विप्रयोगसंयोगात्मके लौकिकालौकिकदेहरूपे वा यस्य सः। स्वस्थः मत्स्वरूपे स्थितः। अतएव समलोष्टाश्मकाञ्चनः समानि लोष्टाश्मकाञ्चनानि यस्य? सर्वस्य भगवदात्मकत्वात्तादृशः। तुल्यप्रियाप्रियः तुल्ये प्रियाप्रिये संयोगवियोगात्मके यस्य सः। भगवदिच्छाया एव मुख्यत्वादुभयोस्तुल्यत्वम्। धीरः विप्रयोगादितीक्ष्णदुःखसहनशीलः। तुल्यनिन्दात्मसंस्तुतिः तुल्या निन्दा आत्मसंस्तुतिश्च यस्य।अयं भावः -- दुष्टकृता निन्दाऽपि भक्तत्वेन स्तुतिप्रायैव।'),
('purushottama-sc:source:14.25','Puruṣottamajī','gita.14.25','sa','commentary','।।14.25।।किञ्च मानापमानयोस्तुल्यः भगवत्कृतमानापमानयोः स्वीयत्वेन कृतत्वात्तुल्यः। तुल्यो मित्रारिपक्षयोः? भगवदीयेन तदीयत्वेन? मित्रपक्षे कृते तुल्यः भगवदीयभावेन अरिपक्षे आसुरैर्भगवदीयत्वेन विचारिते भगवदीयत्वेन तथा विचारयन्तीति तेषामुचितमेवेति तद्दोषाविचारकत्वात्तुल्यः। सर्वारम्भपरित्यागी सर्वेषां पदार्थानामारम्भानां दृष्टप्रत्ययानां परित्यजनशीलवान्। एवमाचारवान् यः सगुणातीत उच्येते? कथ्यत इत्यर्थः। ,'),
('purushottama-sc:source:14.26','Puruṣottamajī','gita.14.26','sa','commentary','।।14.26।।कथं गुणानतिवर्त्तते इत्यत्रोत्तरमाह -- मां चेति। चस्त्वर्थे। मां मदर्थे अव्यभिचारेण अनन्यात्मकेन भक्ितयोगेन यः सेवते? स एतान् गुणान् समतीत्य सम्यगतिक्रम्य ब्रह्मभूयाय ब्रह्मभावाय कल्पते समर्थो भवति।'),
('purushottama-sc:source:14.27','Puruṣottamajī','gita.14.27','sa','commentary','।।14.27।।ब्रह्मशब्दस्याऽक्षरवाचकत्वे तद्भावे धर्मात्मकभाव एव भविष्यति? न मुख्यभाव इत्यत आह -- ब्रह्मण इति। हीति निश्चयेन यस्माद्धेतोः ब्रह्मणः अक्षरात्मकस्यापि प्रतिष्ठा स्थितिरूपोऽहमेव? अमृतस्य मोक्षस्य? अव्ययस्य नित्यात्मकवैकुण्ठस्यापि? शाश्वतस्य नित्यरूपस्य? शास्त्रीयभक्त्यादिरूपस्य धर्मस्य च। च पुनः। तथा एकान्तिकस्य रक्षात्मकस्य भावादिरूपस्य सुखस्याऽहं प्रतिष्ठा? मूलमित्यर्थः। अतएवमेतैरुत्पन्नो भावो मदात्मक एवेति भावः।एवं चतुर्दशेऽध्याये गुणानां स्वस्वरूपताम्।द्विरूपतां च क्रीडार्थं प्रोक्तवानर्जुनं हरिः।।'),
('purushottama-sc:source:15.1','Puruṣottamajī','gita.15.1','sa','commentary','।।15.1।।स्वरूपज्ञानरहिता भक्तिर्नैवोपयुज्यते। पुरुषोत्तमरूपं तु ततः पञ्चदशेऽवदत्।।1।। परीतः पार्थकृपया श्रीकृष्णः करुणानिधिः। उद्दिधीर्षुश्च तद्द्वारा लोकं भक्तिप्रवर्तितम्।।2।।पूर्वाऽध्यायेमां च योऽव्यभिचारेण भक्तियोगेन सेवते [14।26] इत्यनेनाऽनन्यभजनमुक्तम् तत्सिद्ध्यर्थं स्वपुरुषोत्तमस्वरूपं सपरिकरं वदिष्यन् सार्धश्लोकद्वयेन तदङ्गत्यागज्ञापनाय स्वलीलात्मकसंसारवृक्षाद्भिन्नं संसारस्वरूपं वृक्षरूपेणाऽऽह -- ऊर्ध्वमूलमित्यादिना। ऊर्ध्वः पुरुषोत्तमो मूलं यस्य? स्वक्रीडार्थं प्रकटितत्वात्। अधः जीवादयः सेवार्थोत्पादिताः शाखा यस्य तम्। अव्ययं लीलार्थकत्वान्नित्यं स्थास्यति? दुर्लभत्वाज्जीवदर्शनयोग्यं? अतो व्यासादयोऽश्वत्थं प्राहुः। यस्य पर्णानि पत्राणि छायोपयोग्यानि तापापहानि। भगवत्स्वरूपभगवद्भजनादिप्रतिपादकत्वेन छन्दांसि वेदाः।यः इति दुर्लभाधिकारित्वम्। वेदं वेत्ति जानाति स वेदवित्? वेदार्थज्ञानवानित्यर्थः।'),
('purushottama-sc:source:15.2','Puruṣottamajī','gita.15.2','sa','commentary','।।15.2।।एवं क्रीडात्मकं वृक्षं निरूप्य तत एव संसारात्मकवृक्षोत्पत्तिमाह -- अधश्चोर्ध्वमिति। तस्य अलौकिकवृक्षस्य अधः विविधजीवादिषु? ऊर्ध्वं लीलावतारादिषु? शाखाः प्रसृताः अनेकरूपेण विस्तारं गताः। चकारेणाऽधः प्रसृतानामपि दर्शनानन्दप्रकारेण लीलौपयिकता ज्ञापिता। किञ्च गुणैः सात्त्विकादिभिः सेचनेनैव प्रकर्षेण वृद्धाः वृद्धिं गताः। किञ्च विषयरूपादयः प्रवालाः पल्लवस्थानीया जाताः। किञ्च तासां शाखानां लौकिकानुबन्धार्थं अधः जीवादिषु मूलान्यनुसन्ततानि प्ररूढानि। प्रयोजनमाह -- मनुष्यलोके कर्म अनुबन्धः पश्चाद्भवनं येषां तदर्थं तादृशानि? मनुष्यलोकोत्पन्नानां कर्मप्रवृत्त्या सृष्ट्याद्यर्थम्।'),
('purushottama-sc:source:15.3','Puruṣottamajī','gita.15.3','sa','commentary','।।15.3।।ननु कथं तैः सृष्टिः इत्यत आह -- न रूपमिति। इहाऽस्मिन् लौकिके संसारे कर्मासक्तानामस्य तच्छाखारूपत्वे सत्यपि तथाऽलौकिकक्रीडात्मकं रूपं न लभ्यते। न च अन्तः? क्रीडात्मकेन नित्यत्वात्। न च आदिः? पुरुषोत्तममूलकत्वेनाऽनादित्वात्। न च पुनः सम्प्रतिष्ठा स्थितिः तस्माल्लौकिकसंसारात्मकवृक्षं छित्त्वा पुनरलौकिकान्वेषणं कार्यमित्याह -- अश्वत्थमिति। एनं परिदृश्यमानं लौकिकमश्वत्थं नश्वरं सुविरूढमूलं दृढं? दृढेन निश्चयात्मकेन असङ्गशस्त्रेण एतन्मध्यपातिदुष्टविषयादिदोषपर्यालोचनसङ्गाभावात्मकेन शस्त्रेणैतच्छेदपटुना च्छित्त्वा भिन्नं कृत्वा।'),
('purushottama-sc:source:15.4','Puruṣottamajī','gita.15.4','sa','commentary','।।15.4।।ततः पदमिति। ततस्तदनन्तरं तत्पदं अलौकिकस्य तस्य मूलभूतं परिमार्गितव्यं परितो विचारपूर्वकमालोचनरीत्या मार्गितव्यमन्वेषणीयम्। अन्वेषणे प्रयोजनमाह -- यस्मिन्निति। यस्मिन् पदे गताः प्राप्ता भूयो न निवर्तन्ते? संसारे नागच्छन्तीत्यर्थः। कथमन्वेषणीयं इत्यत आह -- तमेवेति। यतः पुरुषोत्तमात् पुराणी सनातनी नित्या प्रवृत्तिर्भक्त्यात्मिका भगवदनुप्रवृत्तिः प्रसृता विस्तृता प्रकटिता तमेव आद्यं च पुनः पुरुषं भावात्मतया पुरुषरूपं शरणं प्रपद्ये व्रजामीति भावः।'),
('purushottama-sc:source:15.5','Puruṣottamajī','gita.15.5','sa','commentary','।।15.5।।शरणागतिं विना दोषानिवृत्तौ तत्प्राप्तिर्न भवेदिति शरणागतौ च स्यादेवेत्यन्यथा अनिवृत्तित्वाद्दोषनिरूपणपूर्वकं तद्रहितानां तत्पदप्राप्तिरुच्यते -- निर्मानमोहा इति। निर्गतौ मानमोहौ येषां ते। मानस्तु भगवत्सम्बन्धजः? मोहः स्वरूपाज्ञानात्मकः। तथा जितः सङ्गदोषः अवैष्णवादिसङ्गदोषो यैः। अध्यात्मनित्याः भगवत्स्वरूपतत्त्वविचारपरिनिष्ठिताः। विनिवृत्तकामाः विशेषेण मनसा विचारराहित्येन विनिवृत्तः कामो येभ्यः। सुखदुःखसंज्ञैः सांसारिकैर्द्वन्द्वैर्विमुक्ताः। अमूढाः भगवत्परिचिन्तनेन मोहरहिताः? तदव्ययं नित्यं पदं गच्छन्ति। यत एतद्दोषरहिता उक्तगुणवन्तश्च गच्छन्ति तद्द्वयमपि शरणातिरिक्तसाधनासाध्यं तस्मात् शरणं प्रपद्य इति शरणगमनमन्वेषणप्रकार इत्यर्थः।'),
('purushottama-sc:source:15.6','Puruṣottamajī','gita.15.6','sa','commentary','।।15.6।।अथ तत्पदस्वरूपमाह -- न तदिति। तत्पदं सूर्यो न भासयते न प्रकाशयति। एतेन स्वयम्प्रकाशत्वमुक्तम्। न शशाङ्कश्चन्द्रोऽपि तापहरणपूर्वकशीतादिना न प्रकाशयति। न पावकः? अग्निः शीतादिनिवारकत्वेन न प्रकाशयति। किञ्च यत्पदं गत्वा न निवर्तन्ते न पुनरागच्छन्ति। कुतः इत्यत आह। तत् मम परममुत्कृष्टं धाम गृहरूपमित्यर्थः।'),
('purushottama-sc:source:15.7','Puruṣottamajī','gita.15.7','sa','commentary','।।15.7।।ननु पूर्वं क्षेत्रक्षेत्रज्ञप्रकृतिपुरुषजडजङ्गमादीनां स्वांशत्वक्रीडौपयिकत्वस्वक्रीडार्थोपसादितत्वमुक्तमधुना चयद्गत्वा न निवर्त्तन्ते [5।6] इत्युक्तं तत्कथं सम्भवति इत्याकाङ्क्षायामाहममैवेति पञ्चभिः। जीवलोके मत्क्रीडार्थप्रकटिते जीवभूतः आनन्दांशतिरोधानेनाऽनीशितृत्वोद्भावनेन क्रीडारसभोगार्थसेवारसानुभवार्थजीवत्वलक्षणो ममैवांशः सनातनः सदा मयि विद्यमानः। मनः षष्ठं येषां तादृशानि प़ञ्चेन्द्रियाणि प्रकृतौ क्रीडार्थमाविर्भूतायां स्थितानि तद्भोगाद्यनुभवार्थं कर्षति।अत्रायं भावः -- साक्षात्स्वक्रीडानुभवार्थप्रकटितो जीवभावः सनातनः पुरुषोत्तमांश एव साक्षात् तद्द्वारा प्रकृत्युत्पादितभोगानुभवार्थं प्रकृटितोंऽशः सांसारिको जीवो मूलभूतजीवांशः स स्वांशं तत्र नयति यत्र तदिच्छा। अतएव तमुत्क्रामन्तं प्राणोऽनुत्क्रामति [बृ.उ.4।4।2] इत्यादिश्रुतिः।'),
('purushottama-sc:source:15.8','Puruṣottamajī','gita.15.8','sa','commentary','।।15.8।।तदेव विस्तरेणाऽऽह -- शरीरमिति। ईश्वरः मूलभूतो जीवो यत् यदा शरीरभोगार्थमवाप्नोति? च पुनः यदा भोगसमाप्तौ उत्क्रामति तदा एतानि पूर्वोक्तानीन्द्रियाणि स्वभोगार्थकानि सूक्ष्माणि संस्कारात्मकानि गृहीत्वैव सम्यक् स्वांशजीवभावेन सह याति प्राप्नोति। तत्र दृष्टान्तमाह वायुः आशयात् पुष्पादितो गन्धान् सूक्ष्मांशानिव।'),
('purushottama-sc:source:15.9','Puruṣottamajī','gita.15.9','sa','commentary','।।15.9।।किमर्थं गृहीत्वा गच्छति इत्यत आह -- श्रोत्रमिति। श्रोत्रादीनीन्द्रियाणि लौकिकस्थूलशरीरे स्थूलानि मनः अन्तःकरणं च अधिष्ठाय मुख्यरूपेण तत्र स्वयं स्थितिं कृत्वा अग्रे अलौकिकतदनुभवार्थं विषयान् उप स्वांशजीवसमीपे सेवते भोगं करोतीत्यर्थः।,'),
('purushottama-sc:source:15.10','Puruṣottamajī','gita.15.10','sa','commentary','।।15.10।।एवम्भूतं कथं सर्वे न पश्यन्ति तत्राह -- उत्क्रामन्तमिति। उत्क्रामन्तं भजनरसानुपयुक्तदेहात् उपयुक्ताय गच्छन्तं वा विकल्पेन तादृगीक्षणेच्छया तत्रैव स्थितमपि वा भुञ्जानं तादृग्विषयरसानुभावकं गुणान्वितं तद्भोगपटुभिरिन्द्रियैर्युक्तं मुख्यजीवं विमूढाः सत्सङ्गाभावेन स्वोपभोगैकपराक्षिप्तदृशो नानुपश्यन्ति। तद्दृष्ट्वाऽपि स्वयं न पश्यन्ति। ज्ञानचक्षुषः सत्सङ्गलब्धस्वरूपाः पश्यन्ति।'),
('purushottama-sc:source:15.11','Puruṣottamajī','gita.15.11','sa','commentary','।।15.11।।अथ चैनं भक्ता एव पश्यन्ति नान्य इत्याह -- यतन्त इति। योगिनश्च योगिनोऽपि यतन्तः ज्ञानार्थं यत्नं कुर्वन्तः एनमात्मन्यवस्थितं अधिष्ठितं पश्यन्ति तथाभोगं कुर्वन्तमित्यर्थः। अकृतात्मानः सत्सङ्गादिभक्तत्वरहिताः? ज्ञानाभावेन केवलयोगादिना यतन्तोऽप्येनं न पश्यन्ति? यतोऽचेतसः मन्दमतयः चैतन्यरहिता इत्यर्थः।'),
('purushottama-sc:source:15.12','Puruṣottamajī','gita.15.12','sa','commentary','।।15.12।।ननु योगादीनां जडत्वेन दर्शनासाधकत्वमास्तां? परं सूर्यादीनां तेजस्त्वात्तदाराधनादिना दर्शनं स्यादित्याशङ्क्याऽऽह -- यदिति। आदित्यगतं यत्तेजो जगदखिलं भासयते प्रकाशयति? यच्चन्द्रमसि तेजो जगदाप्यायनादिना भासयते? यच्चाग्नौ हुतादिना तोषजननेन हृदयं प्रकाशयति? तत् तेजो मामकं विद्धि जानीहि। स्वतेजस्त्वोक्त्या स्वेच्छां विना तेषामसाधकत्वं ज्ञापितम्। एतेन मत्क्रीडनेच्छया तद्रूपो भूत्वा जगत्प्रकाशयतीति भावो बोधितः।'),
('purushottama-sc:source:15.13','Puruṣottamajī','gita.15.13','sa','commentary','।।15.13।।एवमेव सर्वरूपो भूत्वा सर्वं करोमीत्याह -- गामाविश्येति। गां पृथ्वीं ओजसा बलेन आविश्य अहं भूतानि धारयामि। अहमेव सोमः अमृतमयरसात्मको रसमयो भूत्वा औषधीः सर्वा व्रीह्यादिकाः भूतानां पृथ्वीरूपेण धृतानां रसपोषार्थं पुष्णामि पुष्टाः करोमि वर्धयामीत्यर्थः।'),
('purushottama-sc:source:15.14','Puruṣottamajī','gita.15.14','sa','commentary','।।15.14।।ततस्तेषां पोषार्थमेव तद्भक्षितमन्नं पचामीत्याह -- अहमिति। अहं वैश्वानरो जाठराग्निरूपो भूत्वा प्राणिनां देहमाश्रितोऽन्तःप्रविष्टः सन् प्राणापानाभ्यां तदुद्दीपकाभ्यां युक्तश्चतुर्विधमन्नं भुक्तं भक्ष्यं भोज्यं लेह्यं चोष्यं पचामि।'),
('purushottama-sc:source:15.15','Puruṣottamajī','gita.15.15','sa','commentary','।।15.15।।नन्वेवं प्राणिमात्रस्य भगवद्रूपाग्निपाचितान्नपोषात् केषाञ्चिद्भगवत्स्मरणं केषाञ्चिदस्मरणादिकं च कथं इत्यत आह -- सर्वस्य चेति। चकारोऽपिशब्दार्थे। सर्वस्यापि अहं हृदि प्रेरकत्वेनेश्वररूपेण प्रविष्टः तिष्ठामीत्यर्थः। ततः किं अत आह -- मत्तः प्रविष्टात्मकत्वान्मद्विचित्रेच्छया स्मृतिः पूर्वानुभूतमत्स्वरूपस्मरणपुष्ट्या तदुद्धारार्थम्। तथैव मुक्तिदानेच्छया ज्ञानम्। च पुनः। मोहोत्पादनेन नरकादियातनेच्छया अपोहनं स्मृतिज्ञानयोः प्रमोषो विस्मरणमित्यर्थः। भवतीति शेषः। ननु वेदास्तु शब्दात्मकास्तदध्ययनेन सूत्रैः गुरूक्तप्रकारेण च कथं न ज्ञानोदयः इत्यत आह। सर्वैः काण्डद्वयात्मकैर्वेदैरहमेव वेद्यः ज्ञेयः। अतो मदिच्छयैव वेदशब्दानां मद्वाक्यरूपाणामलौकिकानामर्थप्रकाशः? नान्यथेत्यर्थः। वेदान्तकृत् सूत्रप्रदर्शनेन सम्प्रदायप्रवर्त्तको व्यासादिरूपो गुरुरहमेवेत्यर्थः। च पुनः अहमेव वेदवित् तदुक्तप्रकारेण शिष्यादिहृदयस्थो ज्ञानप्रकाशेन ज्ञानवानित्यर्थः। अतो न वेदादिभिरपि ज्ञानमिति भावः।'),
('purushottama-sc:source:15.16','Puruṣottamajī','gita.15.16','sa','commentary','।।15.16।।अथ स्वज्ञापितस्वरूपज्ञानार्थं सपरिकरं स्वस्वरूपमाह -- द्वाविमाविति त्रिभिः। लोके प्रपञ्चस्थिते सर्वत्र द्वाविमावेव पुरुषौ सर्वपदार्थभोक्तारौ आधिभौतिकाध्यात्मरूपौ क्षरः अक्षरश्च। उभयोः स्वरूपमाह -- क्षरः पुरुषः सर्वाणि भूतानि ब्रह्मादिस्थावरान्तानि शरीराणि नानाविधानि लीलौपयिकलीलात्मकत्वेनानेकरूपाणि? क्षरशब्दवाच्यः पुरुषांशरूपः पुरुष इत्यर्थः। कूटः शिलासमूहः पर्वतस्तद्वत् सर्वपदार्थेषु शरीरादिषु विनश्यत्स्वपि तत्समूहस्थः अविनाशी भोक्ता मच्चरणात्मको यः? स अक्षरः पुरुष इत्यर्थः।'),
('purushottama-sc:source:15.17','Puruṣottamajī','gita.15.17','sa','commentary','।।15.17।।पुरुषोत्तमज्ञानार्थमेतौ निरूपिताविति तदाह -- उत्तम इति। तुशब्द एव तत्समत्वव्यावर्तनार्थः। उत्तमः पुरुषः अन्यः सर्वाज्ञातः सर्वव्यतिरिक्त इत्यर्थः। कीदृशः इत्याकाङ्क्षायामाह -- परमात्मेत्युदाहृतः परमश्चासावात्मेति परमः सर्वोत्कृष्ट आत्मा अविकृतः इति अमुना प्रकारेण श्रुत्यादिभिरुदाहृतः कथितः? यो लोकत्रयं तत्तद्रसानुभवार्थमाविर्भवति धारयति पोषयति च। एवं चेन्नयूनाधिक्यं भविष्यतीत्याशङ्क्याऽऽह -- अव्यय इति। निर्विकार इत्यर्थः। तर्हि धारणमनुपपन्नमित्यत आह -- ईश्वर इति। कर्तुमन्यथाकर्तुं च समर्थः। अतस्तथेत्यर्थः।'),
('purushottama-sc:source:15.18','Puruṣottamajī','gita.15.18','sa','commentary','।।15.18।।तद्रूपश्चाऽयमेवातः सोऽहमेवेत्याह -- यस्मादिति। यस्मात् क्षरं जडादिदेहधर्मं अतीतोऽतिक्रान्तोऽहं परिदृश्यमान आनन्दरूपः। अक्षरादपि कूटस्थचेतनात्मकादपि उत्तमोऽस्मि? अतो लोके चतुर्दशभुवनात्मके? वेदे? चकारेण सूत्रस्मृत्यादिष्वपि पुरुषोत्तमः प्रथितः कथितो विख्यात इति भावः।'),
('purushottama-sc:source:15.19','Puruṣottamajī','gita.15.19','sa','commentary','।।15.19।।अतोऽहं पुरुषोत्तमः? अतो मज्ज्ञानवान् सर्वज्ञः सोऽन्यभजनरहितो मां भजतीत्याह -- यो मामिति। यो दुर्लभो मामसम्मूढो मोहादिदोषरहितो व्यवसितमतिरेवं पूर्वोक्तप्रकारेण पुरुषोत्तमं जानाति? स सर्ववित् सर्वज्ञ इत्यर्थः? सर्वविद्भवतीति वा। सर्वज्ञत्वलक्षणमाह मां सर्वभावेन भजति। भारतेति विश्वासाय।'),
('purushottama-sc:source:15.20','Puruṣottamajī','gita.15.20','sa','commentary','।।15.20।।उपसंहरति -- इतीति। इति अमुना प्रकारेण गुह्यतममतिगुप्तरहस्यं शास्त्रं शासनधर्मरूप हे अनघ निष्पाप कुतर्काद्यनुपहतमते इदं प्रत्यक्षं मया कृपालुनेत्यर्थः। उक्तं कथितमित्यर्थः। प्रयोजनमाह -- एतदिति। बुद्धिमान् कुशल एतद्बुद्धा कृतं कृत्यमेतत्सेवारूपं येन तादृशो भवेदित्यर्थः। यद्वा बुद्धिमान् स्यात् कृतकृत्य इत्यर्थः। अनेन सर्वेषां दैवजीवानां स्वरूपज्ञानार्थं प्रकटितमिति भावः। भारतेतिसम्बोधनेन साहजिकबुद्धिमतो येन कृतकृत्यता स्यात्तत्र वंशोद्भवे त्वयि किं वक्तव्यं इति भावो व्यञ्जितः।कृष्णः पञ्चदशेऽध्याये लोकानां हितकाम्यया। पुरुषोत्तमयोगं हि पार्थाय कृपयाऽऽदिशत्।'),
('purushottama-sc:source:16.1','Puruṣottamajī','gita.16.1','sa','commentary','।।16.1।।विमुक्तिबन्धज्ञानार्थं दैवीसम्पत्तथाऽऽसुरी। सलक्षणा सकार्या च षोडशे विनिरूप्यते।।1।।पूर्वाध्यायान्तेएतद्बुद्धा बुद्धिमान् कृतकृत्यः स्यात् [15।20] इत्युक्तम्? तत्र सृष्टौ बहव एव बुद्धिमन्तो दृश्यन्ते ते कथं नैतज्ज्ञानार्थं यतन्ते यतमानेष्वपि कथं न सर्वे एव ज्ञात्वा भजनेन कृतकृत्या भवन्ति इत्याशङ्क्याऽत्र दैवजीवा दैव्यामेव सम्पदि जाता अधिकारिणो यतमानाः कृतकृत्या भवन्तीति ज्ञापनाय दैवीसम्पत्स्वरूपमाह -- अभयमित्यादित्रयेण। अभयं भयाभावः? कालादिसर्वनियामकत्वेनेश्वरज्ञानात् सत्त्वस्य चित्तस्य सम्यक् शुद्धिः गुरूपसत्त्यादिना प्राप्तभगवन्नामावृत्त्या भगवत्परत्वम्? ज्ञानयोगव्यवस्थितिः ज्ञानयोगे भगवज्ज्ञानोपाये व्यवस्थितिरेकाग्रतया स्थितिः? दानं यथाशक्त्यनभिलाषेण भगवत्प्रीत्यर्थमन्नादिविभागः? दम इन्द्रियनिग्रहः? यज्ञो यथाशक्ति यथाविधि यथाधिकारमग्निहोत्रादिकरणम्। चकारेण भगवद्विभूतिज्ञानेन? नान्यथेत्युच्यते। स्वाध्यायो ब्राह्मयज्ञादिः? तपो भगवदर्थं देहादिक्लेशः? आर्जवं कौटिल्यराहित्यम्।'),
('purushottama-sc:source:16.2','Puruṣottamajī','gita.16.2','sa','commentary','।।16.2।।अहिंसा परपीडाराहित्यं? सत्यं स्वार्थपरार्थलोभादिराहित्येन यथार्थभाषणम्? अक्रोधो निष्कारणताडनादिभिरपि क्षोभाभावः? त्यागः अनासक्तिः? शान्तिः चित्तस्थैर्यम्? अपैशुनं सर्वत्र भगवदात्मबुद्ध्या परापवादराहित्यम्? भूतेषु दया जीवेषु भगवद्वियुक्तत्वेन दया तत्स्मरणोपदेशादिरूपा? अलोलुप्त्वं भोगेच्छया मनोधावनत्वाभावः? मार्दवं मृदुत्वं परदुःखाभिज्ञत्वम्? ह्रीः लज्जा प्रभुविप्रयोगजीवने सेवाद्यकरणेन लौकिकप्रवृत्तौ च? अचापलं लौकिकक्रियासक्त्या भगवत्क्रियादिषु शैघ्र्याभावः।'),
('purushottama-sc:source:16.3','Puruṣottamajī','gita.16.3','sa','commentary','।।16.3।।तेजो भगवत्कृपाप्रागल्भ्येनाधृष्यत्वम्? क्षमा विद्यमाने सामर्थ्ये परिभवादिषु क्रोधानुत्पत्तिः? धृतिः लौकिकालौकिकदुःखादिषु चित्तस्थैर्यम्? शौचं स्नानादिभगवत्स्मरणादिना च बाह्याभ्यन्तरशुद्धिः? अद्रोहः परानिष्टचिन्तनाभावः? अतिमानिता आत्मनि सर्वाधिक्यज्ञानं तदभावो नातिमानिता। एतानि सर्वाणि दैवीं भगवत्क्रीडौपयिकीं सात्त्विकीं सम्पदमभिजातस्य भगवदाभिमुख्येन भगवत्कृपया तस्य भवन्ति। एतद्धर्मवत्त्वे भगवदाभिमुख्यं ज्ञेयमिति भावः। भारतेति विश्वासार्थं सम्बोधनम्।'),
('purushottama-sc:source:16.4','Puruṣottamajī','gita.16.4','sa','commentary','।।16.4।।एवं सलक्षणां दैवीं सम्पदमुक्त्वा आसुरीमाह -- दम्भ इति। दम्भो धर्मध्वजित्वं अन्तस्तदभावेन बहिर्धर्मप्रकटनम्? दर्पो विद्यामदेन स्वात्मविस्मरणेन सर्वोपमर्दतयाऽऽधिक्येन स्थितिः? क्रोधः स्वबलाधिक्यभावनया निष्ठुरवाक्यतानिष्टचिन्तनं च? पारुष्यं कार्कश्यं परदुःखानभिज्ञता। एवकारेण (न) क्वचिदपि कदाचिदप्यपारुष्यमिति ज्ञापितम्। च पुनः अज्ञानं सर्वस्वरूपानभिज्ञता। आसुरीं सम्पदमभिजातस्य मदिच्छया जातस्यैतानि लक्षणानि भवन्तीत्यर्थः।'),
('purushottama-sc:source:16.5','Puruṣottamajī','gita.16.5','sa','commentary','।।16.5।।उभयोः सम्पदोः कार्यमाह -- दैवी सम्पदिति। दैवी सम्पत् विमोक्षाय विशेषेण मोक्षाय पुष्टिमर्यादाभेदेन मता? मत्सम्मतेत्यर्थः। आसुरी निबन्धाय नितरां बन्धाय पुनः संसारपर्यावर्तनेनान्ते अन्धंतमःप्रवेशाय मता? सम्मतेत्यर्थः। एतच्छ्रवणेन युद्धोपस्थितौ कौरवादिषु क्रोधोत्पत्त्या शोचन्तमर्जुनमाश्वासयति -- मा शुच इति। हे पाण्डव क्षत्रियात्मजत्वेन शोकानर्ह दैवीं सम्पदमभिजातोऽसि मदिच्छयाऽतो मा शुचः शोचं मा कार्षीः।'),
('purushottama-sc:source:16.6','Puruṣottamajī','gita.16.6','sa','commentary','।।16.6।।ननु दैव्यां सम्पदि जातस्य मम कथं क्रोधोत्पत्तिर्मनसि जायते इत्याशङ्क्य नैकदोषेणैवाऽऽसुरत्वं? तदुत्पत्तिरस्तु सङ्गदोषजेति तत्त्यागार्थं विस्तरेण सर्वलक्षणपूर्वकमासुरीं सम्पदं प्रपञ्चयितुं प्रतिजानीते -- द्वाविति। अस्िमँल्लोके भूतसर्गौ जीवसर्गौ द्वौ? एको दैवो द्वितीय आसुर एव चकारेण राक्षसादिरपि गृहीतः। तत्र दैवो विस्तरशो विस्तारपूर्वकः पूर्वं प्रोक्तः प्रकर्षेण फलादिसहितो मे मया उक्तः कथितः। हे पार्थ कृपापात्र,आसुरः पूर्वं सङ्क्षेपेणोक्तोऽतो मे मत्तो विस्तरेणोच्यमानमासुरं सर्गं श्रृणु।'),
('purushottama-sc:source:16.7','Puruṣottamajī','gita.16.7','sa','commentary','।।16.7।।एवं प्रतिज्ञाय विस्तरेणाऽऽह द्वादशभिः -- प्रवृत्तिमित्यादिभिः। आसुरा जीवा आसुरसर्ग एवोत्पन्नाः प्रवृत्तिं मदिच्छया मत्सेवानुकूलधर्मपदार्थादिषु प्रवृर्त्तिं तथैव तदननुकूलेषु च निवृत्तिं न विदुः? न जानन्तीत्यर्थः। अज्ञाने निदर्शनमाह -- न शौचमिति। बाह्याभ्यन्तरभेदेन शौचं मत्सेवानुकूलदेहशुद्धिस्तेषु न? नापि च आचारः आचरणं न च? न सत्यं असत्यं तेषु विद्यते सत्यं नास्तीत्यर्थः।'),
('purushottama-sc:source:16.8','Puruṣottamajī','gita.16.8','sa','commentary','।।16.8।।किञ्च। असत्यं वेदपुराणाद्यप्रमाणम्? अप्रतिष्ठं अव्यवस्थितम्? अनीश्वरं न विद्यते ईश्वरः कर्ता यस्य तादृशं जगत् ते असुरा आहुः वदन्ति। ननु कर्त्रभावेन कथमुत्पत्तिं वदन्ति इत्याह -- अपरस्परेति। अपरश्च परश्चेत्यपरस्परं स्त्रीपुरुषसंयोगस्ततो जातं कामहैतुकं स्त्रीपुरुषयोः काम एव हेतुर्यस्य तादृशम्। अन्यत् एतदतिरिक्तं किं कारणम् न किमपीत्यर्थः।'),
('purushottama-sc:source:16.9','Puruṣottamajī','gita.16.9','sa','commentary','।।16.9।।किञ्चएतामिति। एतां कामहैतुकरूपां लौकिकीं दृष्टिं दर्शनं अवष्टभ्य आश्रित्य नष्टात्मानः अदृष्टात्मस्वरूपाः? अल्पबुद्धयः प्रत्यक्षमतयः? उग्रकर्माणः उग्रं हिंसाप्रधानं कर्म येषां ते? अहिताः शत्रुरूपाः? जगतः सर्वलोकस्य क्षयाय नरकादिपातनार्थं प्रभवन्ति उत्पद्यन्त इत्यर्थः।'),
('purushottama-sc:source:16.10','Puruṣottamajī','gita.16.10','sa','commentary','।।16.10।।किञ्च -- काममाश्रित्येति। दुष्पूरं दुःखेनापि पूरयितुमशक्यं काममाश्रित्य दम्भः पारलौकिकवेषधारणेन धार्मिकज्ञापनं? मानं लोकपूज्यत्वम्? मदः स्वरूपविस्मरणेन कामैकपरत्वम्? एतैरन्विताः युक्ताः असद्ग्राहान् क्षुद्रदेवमन्त्रान् मोहात् भ्रमात् सकलकार्यसाधकान् ज्ञात्वा गृहीत्वा स्वीकृत्य अशुचिव्रताः अपेयपानादिरताः सन्तस्तदाराधनादौ प्रवर्तन्ते।'),
('purushottama-sc:source:16.11','Puruṣottamajī','gita.16.11','sa','commentary','।।16.11।।किञ्च -- चिन्तामिति। अपरिमेयां परिमातुमशक्यां प्रलयान्तां मरणान्तां चिन्तामुपाश्रिताः? अहर्निशं चिन्तापरा इत्यर्थः। कामोपभोग एव परमः फलरूपो येषां? एतावत्पुरुषार्थकामोपभोग एवेति निश्चिताः कृतनिश्चयाः।'),
('purushottama-sc:source:16.12','Puruṣottamajī','gita.16.12','sa','commentary','।।16.12।।तदर्थमेव आशा एव पाशास्तेषां शतानि तैर्बद्धास्तद्वशेनाऽनेकतुच्छदैवाद्याश्रयणशीलाः? कामक्रोधावेव परमयनं मूलं आश्रयणं येषां तादृशाः। कामोपभोगस्य कृतपुरुषार्थनिश्चयत्वेन कामभोगार्थमन्यायेन चौर्यापहारहिंसादिना अर्थसञ्चयान् ईहन्ते इच्छन्ति।'),
('purushottama-sc:source:16.13','Puruṣottamajī','gita.16.13','sa','commentary','।।16.13।।एवं तेषां कर्मादिलक्षणमुक्त्वा मनसोऽसदर्थाभिनिवेशान्नरकप्राप्तिमाह -- इदमद्येति। मया कृतयत्नेन इदमद्य लब्धं? न तु यदृच्छयेति जानन्ति। एवमेव यत्नं कुर्वाण इदं मनोरथं मनस इष्टं प्राप्स्ये प्राप्स्यामि। इदं भोगाद्यर्थं धनं मेऽस्ति मदिच्छया स्थास्यति? गमिष्यतीति न जानन्ति। इदमपि धनं मे पुनः भविष्यति।'),
('purushottama-sc:source:16.14','Puruṣottamajī','gita.16.14','sa','commentary','।।16.14।।असौ अयं मम शत्रुर्मया हतः? अपरानपि तादृशान् हनिष्ये? भगवदिच्छया विपरीतं न जानन्ति। ईश्वरोऽहं सर्वकरणसमर्थः? अहं भोगी भोगसाधनवान् कर्त्ता च? सिद्धोऽहं कृतकृत्यः? बलवान् परोपकारमर्दनसमर्थः? सुखी सिद्धेष्टसाधनः।'),
('purushottama-sc:source:16.15','Puruṣottamajī','gita.16.15','sa','commentary','।।16.15।।किञ्च आढ्यो विपुलधनवान्? अभिजनवान् सत्कुलोत्पन्नः? मया सदृशः समोऽन्यः कोऽस्ति न कोऽपीत्यर्थः। तथापि यक्ष्ये यज्ञादिभिः प्रतिष्ठार्थमित्यर्थः। दास्यामि अधमेभ्योऽनुवर्तिभ्यः? मोदिष्ये हर्षमाप्स्यामि? इति अमुना प्रकारेण अज्ञानेन विमोहिताः पूर्वोक्तधर्मेष्वभिनिविष्टा भवन्तीत्यर्थः।'),
('purushottama-sc:source:16.16','Puruṣottamajī','gita.16.16','sa','commentary','।।16.16।।एवमभिनिविष्टानां फलमाह -- अनेकेति। अनेकेषु क्षुद्रादिदेवेषु मनोरथेषु वा व्याप्तं चित्तं तेन,विभ्रान्ताः विशेषेण भ्रान्ता विक्षिप्ताः? तेनैव भ्रान्तिपरिकल्पितेन मोहमयेन जालेन समावृताः सम्यगावृताः शकुन्ता इव सूत्रजाले ततो निस्सरणासमर्थाः -- तत्रापि चेन्मत्स्मरणादिकं कुर्युस्तदा तु न पतेरन्? किन्तु खगादिवत् स्वकुटुम्बचिन्तनपराः? कामभोगेषु पूर्वोक्तरीत्या प्रसक्ताः सन्तः? अशुचौ पापात्मके परमदुःखनिधाने नरके विषयसुखात्मके आसक्त्युत्पादके पतन्ति। पतनोक्त्या वैवश्यं ज्ञापितम्।'),
('purushottama-sc:source:16.17','Puruṣottamajī','gita.16.17','sa','commentary','।।16.17।।तत्र संसारविषयात्मके सुखे पतित्वा यत्कुर्वन्ति तेन च यत्फलमनुभवन्ति तदाह -- आत्मेत्यादिचतुर्भिः। आत्मना स्वेनैव सम्भाविताः स्वधर्माविष्कारेण लोकेषु उत्तमतां पूज्यतां नीताः? न तु भगवदीयैः अतएव स्तब्धाः अनम्राः स्थाणुप्रायाः। किञ्च धनेन यो मानो मदश्च ताभ्यामन्विताः युक्ताः। यद्वा धनमानमदैरन्विताः तादृशाः सन्तः नामयज्ञैः शब्दात्मकैः प्रतिष्ठार्थमविधिपूर्वकं मदंशादिज्ञानाभावेन मद्भजनराहित्येन ते पूर्वोक्ता आसुरा यज्ञादिकं कुर्वन्ति।'),
('purushottama-sc:source:16.18','Puruṣottamajī','gita.16.18','sa','commentary','।।16.18।।अविधिपूर्वकं यजनं पूर्वं विवेचयति -- अहङ्कारमिति। अहङ्कारं सत्त्वाभिमानं? बलं स्वसामर्थ्यं? दर्पं गर्वं? कामं मनोभिलाषं? क्रोधं व्यर्थं हृदयक्लेशं? -- चकारेण हर्षोद्वेगादयः सङ्गृहीताः -- तान् संश्रिताः सन्तः? आत्मपरदेहेषुमयि ते तेषु चाप्यहम् [9।29] इत्युक्तरीत्या स्थितं मां प्रद्विषन्तः प्रकर्षेण द्वेषं कुर्वन्तो मद्भजनादिनिन्दां कुर्वन्तः? अभ्यसूयकाः दोषरहितेषु दोषारोपकाः सन्तो यजन्त इति पूर्वेणैव सम्बन्धः।'),
('purushottama-sc:source:16.19','Puruṣottamajī','gita.16.19','sa','commentary','।।16.19।।सर्वफलदाता च स्वयमेव? अतः स्वभक्तद्वेषिणां फलं न प्रयच्छामीत्याह -- तानहमिति। अहं तान् द्विषतः क्रूरान् कठिनान् नराधमान् तामसान् संसारेषु अहम्ममाप्तरूपेषु जन्ममरणादिरूपेषु वा? तेष्वप्यासुरीष्वेव मत्प्रतिपक्षरूपासु योनिषु अजस्रं निरन्तरं क्षिपामि पातयामीत्यर्थः। क्षिपामीत्युक्त्या क्रोधः सूचितः।'),
('purushottama-sc:source:16.20','Puruṣottamajī','gita.16.20','sa','commentary','।।16.20।।तद्योनिप्राप्तानां फलमाह -- आसुरीमिति। जन्मनि जन्मनि -- तथात्वज्ञापनाय वीप्सा -- हे कौन्तेय आसुरीं योनिं मद्धर्माचरणप्रतिकूलां योनिं प्राप्य मत्प्राप्तिसाधनाभावात् मामप्राप्यैव ततो जन्मसमाप्तौ अधमां गतिमन्धन्तमःप्रवेशरूपां यान्ति? प्राप्नुवन्तीत्यर्थः। एवकारेणाऽवतारदशायां सर्वदर्शनयोग्यायामपि स्वरूपाज्ञानान्मद्दर्शनमप्राप्य गच्छन्तीति ज्ञापितम्। कौन्तेयेति सम्बोधनाद्भक्त गृहजन्मप्राप्त्या स्वप्राप्तियोग्यत्वं ज्ञापितम्।'),
('purushottama-sc:source:16.21','Puruṣottamajī','gita.16.21','sa','commentary','।।16.21।।तेषु तदभावात्तथा उक्तासुरसङ्गात्तन्मुख्यधर्मत्रयोत्पत्तिः स्यात्तच्च नरकद्वारं तत्र गमनसाधनरूपमतस्तत्सङ्गत्यागमाह -- त्रिविधमिति। इदमग्रे वक्ष्यमाणं त्रिविधं नरकस्य द्वारं प्रवेशसाधनमित्यर्थः। कीदृशं द्वारम् आत्मनो जीवस्य नाशनं विनाशकर्तृ? संसारपातनात् तद्विवेचयतिकामः क्रोधस्तथा लोभः इति। कामः स्वरमणानन्देच्छारूपः? क्रोधः अकारणहृत्तापरूपः? लोभः सर्वगुणनाशकपरस्वप्राप्तीच्छारूपः? तस्मात् असुरात् () एतत् त्रितयं स्यादतस्त्यजेत् तत्सङ्गमिति शेषः।'),
('purushottama-sc:source:16.22','Puruṣottamajī','gita.16.22','sa','commentary','।।16.22।।तत्सङ्गत्यागेन तत्ित्रतयरहितः स्यादित्याह -- एतैरिति। कौन्तेय सत्सङ्गगुणसम्पन्न तत्तत्सङ्गत्यागे एतैस्त्रिभिस्तमोद्वारैर्विमुक्तो नरः आत्मनः श्रेयो भजनादिकमाचरति? ततस्तेन परां गतिं याति प्राप्नोति।'),
('purushottama-sc:source:16.23','Puruṣottamajī','gita.16.23','sa','commentary','।।16.23।।किञ्च -- असुराश्च अशास्त्रविहिताः असत्कर्मणि निरता अतो यश्चैतत्सङ्गत्यागी न किन्तु तद्भक्तोऽशास्त्रं कर्म करोति न स मुक्तिं प्राप्नोतीत्याह -- यः शास्त्रेति। आसुरसङ्गात्तु यः शास्त्रविधिमुत्सृज्य अवगणय्य कामकारतः स्वेच्छातः अशास्त्रेषु वर्तते? स न सिद्धिं स्वमनोभिलाषं? न सुखं मनोनिर्वृतिं? न परां गतिं मोक्षं प्राप्नोतीत्यर्थः।'),
('purushottama-sc:source:16.24','Puruṣottamajī','gita.16.24','sa','commentary','।।16.24।।तस्मादिति। तस्मात् कारणात्ते तव दैव्यां सम्पदि जातस्य कार्याकार्यव्यवस्थितौइदं कार्यम्? इदमकार्यम् एतयोर्व्यवस्थितौ व्यवस्थायां शास्त्रं प्रमाणं? अतः शास्त्रं विधानोक्तं ज्ञात्वैतत्सङ्गेन त्वं कर्म,कर्तुमिह प्रपञ्चे अर्हसि।दैवासुरीयसम्पत्तिविवेकेन तु षोडशे। सङ्गत्यागविभागेन बन्धमोक्षौ विवेचितौ।।1।।'),
('purushottama-sc:source:17.1','Puruṣottamajī','gita.17.1','sa','commentary','।।17.1।।शास्त्रविध्ययुता श्रद्धा निर्गुणैवोत्तमा मता। इति दर्शयितुं श्रद्धा त्रिविधाऽन्न निरूप्यते।।1।।पूर्वाध्याये शास्त्रविधिरहितकामकारतः कर्मसु वर्त्तमानस्य न फलमित्युक्तं? तत्र कामकाराभावे शास्त्रविधिरहितस्य श्रद्धया वर्त्तमानानामग्रे सात्त्विकत्वाद्याश्रयेण किमपि ज्ञानादिकं सत्फलं भवति न वा इति जिज्ञासुरर्जुनः पृच्छति -- ये शास्त्रेति। ये सर्वत्यागादनन्यत्वादिशास्त्रविधिं दुस्तरत्वेनोत्सृज्य परम्पराचारप्रवाहप्रवृत्तभजनादिषु श्रद्धया आदरेण युक्ताः यजन्ते देवादिपूजनं कुर्वन्ति? हे कृष्ण तेषां का निष्ठा क आश्रयः सत्त्वं आहो रजः तमो वा।अयं भावः -- पूर्वं चेत् सत्त्वाश्रयस्तदा तत एव ज्ञानोदयः? पूर्वं चेद्रजस्तदा? तथा कुर्वतोऽग्रे सात्त्विकत्वं? पूर्वं चेत्तमस्तदाऽग्रे राजसत्वं ततस्तथा कुर्वतोऽग्रे सात्त्विकत्त्वं? ततो ज्ञानोदयस्ततो निर्गुणत्वेन त्वत्प्राप्तिः। फलात्मकनामसम्बोधनेन फलाभावे तत्कारणं व्यर्थमेव तदाचारादिप्रामाण्यं निष्प्रयोजनकमतस्तेषामाश्रय स्वरूपं वक्तव्यमिति भावो व्यञ्जितः।'),
('purushottama-sc:source:17.2','Puruṣottamajī','gita.17.2','sa','commentary','।।17.2।।अत्रोत्तरमाह श्रीकृष्णः -- त्रिविधेति। देहिनां देहाभिमानवतां लौकिकानां श्रद्धा त्रिविधा भवति? सात्त्विकी च पुनः राजस्येव? तथा तामसी चेत्यमुना प्रकारेण त्रिविधा। सा च स्वभावजा स्वस्यौत्पत्तिकगुणजा? न तु निर्गुणा। तथाचायं भावः -- शास्त्रोक्तविद्ध्युक्तमद्भजनश्रद्धातो लौकिकादिगुणज्ञानोदयो भवति निर्गुणत्वाज्जीवस्यापि निर्गुणत्वेन सत्त्वसङ्गाभावान्मत्प्राप्तिफला श्रद्धैकरूपैव? भिन्ना गुणस्वभावजा? त्रिविधा च भिन्ना न तत्फलसाधिकेति भिन्नत्वज्ञापनाय तां त्रिविधां मयोच्यमानां श्रृणु? तच्छ्रवणादेव त्वत्सन्देहनिवृत्तिर्भविष्यतीति।'),
('purushottama-sc:source:17.3','Puruṣottamajī','gita.17.3','sa','commentary','।।17.3।।एवं श्रोतारं श्रवणे सावधानतयाऽभिमुखीकृत्याऽऽह श्रद्धास्वरूपम् -- सत्त्वानुरूपेति। हे भारत सत्त्वानुरूपा मूलसत्त्वस्य अनुरूपा सदृशा अन्यधर्मास्फूर्तिपूर्वकसर्वसामर्थ्यस्फुरणासक्त्युत्पत्तिप्रसरणादररूपा श्रद्धा सर्वस्य सात्त्विकादित्रयस्य भवति। भारतेतिसम्बोधनं तथात्वज्ञानाधिकारित्वबोधनाय। तर्हि त्रिविधत्वं कथं इत्यत आह -- श्रद्धामय इति। अयं पुरुषो मदंशोऽपि नरात्मकः श्रद्धामयः श्रद्धाप्रचुरः? स तु यः सात्त्विकादिभेदेन यच्छ्रद्धः यस्य श्रद्धायुक्तो भवति सः स एव तद्रूप एव भवतीत्यर्थः।'),
('purushottama-sc:source:17.4','Puruṣottamajī','gita.17.4','sa','commentary','।।17.4।।तदेव प्रपञ्चयति -- यजन्त इति। सात्त्विका जना देवान् सूर्येन्द्रादीन् यजन्ते पूजयन्ति राजसाः पुनः यक्षान् धनदाधिष्ठितराक्षसान् यजन्ते। अन्ये सत्त्वसम्बन्धरहितास्तामसा जनाः प्रेतान् भूतगणांश्च यजन्ते तत्तत्पूजारुच्यैव ते तद्रूपा ज्ञातव्या इत्यर्थः।'),
('purushottama-sc:source:17.5','Puruṣottamajī','gita.17.5','sa','commentary','।।17.5।।अथ सात्त्विकानामपि देवादिपूजननिश्चयोऽप्यासुर एव? अनुक्तत्वादित्याह द्वयेनअशास्त्रेति। ये जनाः जननादिक्लेशेन अज्ञाः अशास्त्रविहितं अन्धपारम्पर्यागतं शास्त्रनिषिद्धं वा दम्भाहङ्कारसंयुक्ताः परप्रतारणस्वोत्तमत्वख्यापनाज्ञानाभ्यां देवताप्रसादार्थं सात्त्विकवदाभासमानं निश्चयेन तपः देहक्लेशं अभोजनादिना ये तप्यन्ते कुर्वन्ति। ये च घोरं यक्षादिप्रसादरूपं राज्यधनाद्यपेक्षार्थं तपः कुर्वन्ति। कामरागबलान्विताः? कामो विषयाभिलाषः? रागो भोगासक्तिः? बलमाग्रहस्तैरन्विताः प्रेरिताः सन्तः।'),
('purushottama-sc:source:17.6','Puruṣottamajī','gita.17.6','sa','commentary','।।17.6।।किञ्च -- कर्षयन्त इति। भूतग्रामं पृथिव्यादिसमूहं शरीरस्थं भगवत्क्रीडार्थमास्थितं देहे कर्षयन्तः भगवत्तोषादिरहितवृथोपवासादिभिः कृशं कुर्वन्तः? अचेतसः ज्ञानशून्याः मां च स्वलीलार्थं प्रेरकत्वेन अन्तश्शरीरस्थं शरीरमध्ये स्थितं भजनादिरूपमदाज्ञोल्लङ्घनेन मदंशं कर्षयन्तः क्लेशयन्तः पूर्वोक्तरीत्या ये तपः कुर्वन्ति तान् आसुरनिश्चयान् आसुरो मत्प्रतिपक्षरूपो निश्चयो येषां तादृशान् विद्धि जानीहि। एतेन ये मत्सम्बन्धरहिततपस्यादिधर्मानपि कुर्वन्ति ते त्याज्या एवेति ज्ञापितम्।'),
('purushottama-sc:source:17.7','Puruṣottamajī','gita.17.7','sa','commentary','।।17.7।।एवं धर्मभेदानुक्त्वा आहारादिभेदेनापि तद्भेदज्ञानमाह -- आहारस्त्वित्याद्यैः। तु पुनः आहारोऽपि सर्वस्य त्रिविधस्य लोकस्य त्रिविधः सात्त्विकादिरूपः प्रियो भवति। तथा यज्ञो यजनं? तपः देहादिक्लेशः? दानं? तेषां भेदं अग्रे मया प्रोच्यमानमिमं शृणु।'),
('purushottama-sc:source:17.8','Puruṣottamajī','gita.17.8','sa','commentary','।।17.8।।एवं सावधानं कृत्वाऽऽह -- आयुरिति। आयुर्जीवितं? सत्त्वं हृदयं शुद्धम्? बलं सामर्थ्यम्? आरोग्यं रोगाभावः? सुखं मनस्तोषः? प्रीतिः स्नेहः? एतेषां विवर्द्धनाः? विशेषेण सफलतया धर्मादर्थोपयोगित्वेन वृद्धिकराः। तत्र आयुर्वृद्धिकरः पर्वयज्ञावशेषः? सत्त्वसाधको गुर्वाद्युच्छिष्टरूपः? बलकरः पितृदेवादिशेषः? आरोग्यकरो जनन्याद्युपस्कृतः? सुखकरः सन्मार्गोपार्जितः? प्रीतिकरो मित्रादिगृहस्थः। ते च स्वरूपतोऽप्येतादृशाः रस्याः रसयुक्ताः? स्निग्धाः स्नेहयुक्ताः? स्थिराः चिरकालावस्थायित्वाद्देहपोषकाः? हृद्याः हृष्टा एव हृदयानन्दकर्त्तारः। एतादृशा आहाराः सात्त्विकानां प्रियाः? भवन्तीति शेषः। एवमाहारकर्तारः सात्त्विका ज्ञेया इत्यर्थः।'),
('purushottama-sc:source:17.9','Puruṣottamajī','gita.17.9','sa','commentary','।।17.9।।राजसानाह -- कट्विति। अतिशब्दः सर्वत्रानुसम्बद्ध्यते कट्वादिषु। अतिकटुः कारवेल्लादिः? अत्यम्ल आम्रातकादिः? अतिलवणः क्षारबहुलरोचकशाकादिः? अत्युष्णः सबाष्पपक्वान्नादिः? अतितीक्ष्णो मरिचादिः? अतिरूक्षश्चणकमसूरकोद्रवादिः? अतिविदाही राजकादिः। एवमेतेऽतिकट्वादयः पञ्चयज्ञादिरहिताः स्वार्थकृता आहारा राजसस्येष्टाः प्रियाः। दुःखशोकामयप्रदाः दुःखं भक्षणसमय एव रसनाविकारादिरूपं? शोको भक्षणानन्तरमजीर्णोद्गारादिना भक्षितपश्चात्तापादिरूपः? आमयो रोगो ज्वरादिः? एतानि सर्वाणि प्रददति यच्छन्तीति तथा। एतादृगाहारकर्त्तारो राजसा ज्ञेया इत्यर्थः।'),
('purushottama-sc:source:17.10','Puruṣottamajī','gita.17.10','sa','commentary','।।17.10।।अथ तामसमाह -- यातयाममिति। यातो व्यतीतो यामः प्रहरो यस्य तादृशं पक्वान्नकृषिरादिकं? शैत्यादिना भक्षणायोग्यमित्यर्थः। गतरसं शुष्कं? पूति दुर्गन्धं? पर्युपितं व्यतीतरात्रम्? उच्छिष्टं अन्यभुक्तावशिष्टम्? अमेध्यं कलिङ्गमूलकबिम्बादिकम्। एतादृशं भोजनं तामसानां प्रियम्। एतस्य फलकीर्तनं स्वरूपत एव दुष्टत्वात्। एवंभोजनप्रियो तामसो ज्ञेय इत्यर्थः। निर्गुणाहारकैर्मदुच्छिष्टभोक्तृभिः पूर्वोक्तत्रिविधमभोजनं तद्भोजिनश्च त्याज्या इत्यर्थश्चैतन्निरूपणेन ज्ञापितः।'),
('purushottama-sc:source:17.11','Puruṣottamajī','gita.17.11','sa','commentary','।।17.11।।आहारानन्तरं यज्ञस्य प्रतिज्ञातत्वात् [17।7] त्रिविधयज्ञरूपमाह -- अफलेति। न विद्यतेऽन्यत्फलं यस्मात्तादृशः स्वयमेव फलरूपो भगवत्प्रसादस्तदाकाङ्क्षिभिः पुरुषैः विधिना अवश्यकर्त्तव्यत्वेन दृष्टो बोधितो यो यज्ञो भगवदाज्ञप्तत्वात्यष्टव्यमेव? न तु फलानुसन्धानेन इति मनः समाधाय निश्चलं कृत्वा इज्यते अनुष्ठीयते स यज्ञः सात्त्विक इत्यर्थः। एतादृग्यज्ञकर्ता सात्त्विको ज्ञेयः।'),
('purushottama-sc:source:17.12','Puruṣottamajī','gita.17.12','sa','commentary','।।17.12।।राजसमाह -- अभिसन्धायेति। तु पुनः फलं स्वर्गादिकमभिसन्धाय उद्दिश्य दम्भार्थं लोके स्वख्यापनार्थं चाप्येव यत्तु इज्यतेऽनुष्ठीयते तं यज्ञं राजसं विद्धि। तत्कर्त्तारश्च राजसा ज्ञेयाः।'),
('purushottama-sc:source:17.13','Puruṣottamajī','gita.17.13','sa','commentary','।।17.13।।तामसमाह -- विधिहीनमिति। वेदोक्तविधिरहितम्? असृष्टान्नं पात्रान्नरहितं? मन्त्रैर्देवताह्वानादिरूपैर्हीनं शून्यम्? अदक्षिणं वैधदक्षिणारहितं? श्रद्धया आदरेण विरहितं शून्यं यज्ञं तामसं परिचक्षते कथयन्ति महान्त इति शेषः।'),
('purushottama-sc:source:17.14','Puruṣottamajī','gita.17.14','sa','commentary','।।17.14।।अथ यज्ञानन्तरं तपसः प्रतिज्ञातत्वात् तपसस्त्रैविध्यं वक्तुं? तस्य च शरीरवाङ्मनोभेदेन त्रिविधत्वात्तत्ित्रतयनिरूपणपूर्वकं त्रैविध्यकथनार्थं शारीरादिकत्रयमाह -- देवद्विजेति त्रयेण। देवाः ब्रह्माद्याः? द्विजाः वेदैकनिष्ठाः? गुरवः सरहस्यमन्त्रोपदेष्टारः? प्राज्ञाः पण्डिताः शास्त्रपरिनिष्ठितबुद्धयः? तेषां पूजनं यथाविधि। शौचं मृदादिना? आर्जवं ऋजुता? ब्रह्मचर्यं इन्द्रियनिग्रहः? अहिंसा परद्रोहराहित्यं? चकारेणेर्प्यादयः। एतत्सर्वं शारीरं शरीरसम्बन्धि तप उच्यते कथ्यते इत्यर्थः।'),
('purushottama-sc:source:17.15','Puruṣottamajī','gita.17.15','sa','commentary','।।17.15।।वाचिकमाह -- अनुद्वेगेति। उद्वेगं भयं नोत्पादयति कस्यापि तादृशं वाक्यं? सत्यं लोभादिराहित्येन यथार्थभाषणरूपं? यत् प्रियं परलोकसाधकं? हितं लौकिकादिसाधकम्। चकारेण लौकिकस्यानावश्यकत्वेऽपि वक्तव्यता सूचिता। स्वाध्यायस्य वेदस्य अभ्यसनमभ्यासः। चकारेण स्मृतीनामपि। एवकारेण वेदाविरोधेन स्मृत्याद्यभ्यासः। एतत्सर्वं वाङ्मयं वाचः सम्बन्धि तप उच्यते।'),
('purushottama-sc:source:17.16','Puruṣottamajī','gita.17.16','sa','commentary','।।17.16।।मानसमाह -- मनःप्रसाद इति। मनःप्रसादः मनस्स्वच्छता सत्परिचिन्तनं? सौम्यत्वमक्रूरता? मौनं मननम्? आत्मविनिग्रहः आत्मनो विषयेभ्य आकर्षणं? भावसंशुद्धिः स्नेहादिविषयेषु कापट्याभावः। इति अमुना प्रकारेणैतत्सर्वं मानसं मनस्सम्बन्धि तप उच्यते।');
INSERT INTO commentary_fts (unit_id,author,canonical_ref,language,content_type,content) VALUES
('purushottama-sc:source:17.17','Puruṣottamajī','gita.17.17','sa','commentary','।।17.17।।एवं शारीरादित्रैविध्यं तपस उक्त्वा सात्त्विकादिभेदत्रैविध्यमाह -- श्रद्धयेति। तत्तपः त्रिविधं शारीरादिकं? परया श्रद्धया अनन्यादरेण? अफलाकाङ्क्षिभिः फलापेक्षारहितैः युक्तैः शास्त्राज्ञाकारिभिः तप्तं सात्त्विकं परिचक्षते कथयन्ति।'),
('purushottama-sc:source:17.18','Puruṣottamajī','gita.17.18','sa','commentary','।।17.18।।राजसमाह -- सत्कारेति। तत् त्रिविधं तपः इह लोकेषु सत्कारः साधुत्वादिशब्दः? मानः उत्तमत्वेन सभादिषूच्चोपवेशनादिरूपः पूजालाभः। एतदर्थं दम्भेनैव च परप्रतारणरूपेण यत्क्रियते तु चलं पूर्वोक्ताभावे अध्रुवं परलोकादिसाधनरहितं तत्तपः राजसं प्रोक्तं शास्त्रेषु कथितमित्यर्थः।'),
('purushottama-sc:source:17.19','Puruṣottamajī','gita.17.19','sa','commentary','।।17.19।।तामसमाह -- मूढेति। मूढग्राहेण मूर्खताजनितदुराग्रहेण आत्मना जीवस्य पीडया यत्तपः क्रियते? वा परस्योत्सादनार्थं अन्यस्य विनाशार्थं तत्तामसमुदाहृतं? सम्यक् न युक्तमित्यर्थः।'),
('purushottama-sc:source:17.20','Puruṣottamajī','gita.17.20','sa','commentary','।।17.20।।अथ पूर्वप्रतिज्ञातदानत्रैविध्यमाह -- दातव्यमिति।धनं मूलमनर्थानां इत्यादिवाक्यैः सञ्चितानर्थकारित्वज्ञानपूर्वकदत्तेष्टभक्त्यादिसाधकत्वज्ञानेन दातव्यमिति ज्ञात्वा अनुपकारिणे प्रत्युपकारासमर्थाय दीनायसीदत्कुटुम्बेभ्यः इत्याद्युक्तधर्मविशिष्टाय यद्दानं दीयते? देशे कुरुक्षेत्रादौ ग्रहणादौ चकारेण अकाले विवाहाद्युपस्थितौ याचमानाय पात्रे वेदविशारदाय चकारेण अपात्रे बुभुक्षिताय यत्तद्दानं सात्त्विकं स्मृतं प्रसिद्धमित्यर्थः।'),
('purushottama-sc:source:17.21','Puruṣottamajī','gita.17.21','sa','commentary','।।17.21।।यत्त्विति। तुशब्देन तादृग्दानस्यानुचितत्वं ज्ञाप्यते। यत्तु प्रत्युपकारार्थं महाराजकृपापात्रब्राह्मणाय अग्रे स्वोपकारकादित्वोद्देशेन दानं वा पुनः फलधर्मादिचतुष्टयमुद्दिश्य परिक्लिष्टं चित्तक्लेशयुक्तं फलोपकारासन्देहेन दीयते तत् दानं राजसमुदाहृतं? कथितमित्यर्थः।'),
('purushottama-sc:source:17.22','Puruṣottamajī','gita.17.22','sa','commentary','।।17.22।।तामसमाह -- अदेश इति। अदेशे कीकटादौ म्लेच्छादिसन्निधाने वा? अकाले अश्रद्धावस्थायामाशौचादौ? अपात्रेभ्यः गणिकाचारणबन्दिभ्यो यद्दानं दीयते तत्तामसं फलादिरहितमुदाहृतम्। च पुनः देशादिसम्पत्तौ पात्रेभ्योऽपि यत् असत्कृतं सत्कारपूजादिरहितं अवज्ञातं स्वरूपज्ञानपूर्वकतिरस्कारं यद्दीयते तदपि तथेत्यर्थः। एवं यज्ञादीनां त्रैविध्यनिरूपणेनैतत्त्रैविध्यरहितं निर्गुणमेव तत्सर्वं यज्ञादिकं कर्त्तव्यमिति ज्ञापितम्। तथाहि भगवदिच्छायां सत्यां तज्ज्ञानपूर्वकं भगवद्विभूतियागो भक्त्यङ्गत्वेन कार्यो युधिष्ठिरवत्यक्ष्ये विभूतीर्भवतः [भागः10।72।3] इत्यादिविज्ञापनपूर्वकम्। तपोऽपि भगवदर्थकसर्वसुखपरित्यागपूर्वकक्लेशादिसहनरूपे৷৷৷৷৷৷৷৷৷৷৷৷৷৷৷৷. ज्ञानरूपं वा कार्यम्। दानं च भक्तिसिद्ध्यर्थं भगवद्भक्ताय वेदविदे ब्राह्मणाय दातव्यम्।'),
('purushottama-sc:source:17.23','Puruṣottamajī','gita.17.23','sa','commentary','।।17.23।।ननु देशकालाद्यभावकृतानां यज्ञानां यदि तामसत्वं तदा निर्गुणेष्वपि समः समाधिः इत्याशङ्क्य तेषां देशकालादिसम्पत्त्यभावेऽपि तत्सम्पत्तिर्भवतीत्याशयेनाऽऽह -- ओं तत्सदिति।ओं तत्सत् इत्येवरूपो ब्रह्मणः पुरुषोत्तमस्य त्रिविधो निर्द्देशो नामव्यपदेशः स्मृतो भक्तैः तत्रओमित्येकाक्षरं ब्रह्म [8।13] इत्यादिभिःम् इति ब्रह्मणः संज्ञा नामेति। यतो वाचो निवर्तन्ते [तै.उ.2।42।9] आनन्दमात्रमितियत् इत्यारभ्य,ततो न ज्ञायते तु तत् इत्यन्तादिवाक्येभ्यस्तदित्यपि ब्रह्मण एव नाम। मूलसत्तावाचकत्वेन सच्छब्दोऽपि ब्रह्मवाचक एव। एतत्ित्रविधमपि ब्रह्मणो नाम। स्वरूपज्ञानपूर्वकं सर्वत्र यज्ञादिक्रियासु आदौ विनियुक्तं सर्वदेशादिसम्पत्तिसाधकमिति ज्ञापनाय पूर्वसिद्धं तथात्वमाह -- ब्राह्मणा इति। येन त्रिविधनिर्देशेन ब्राह्मणा ब्रह्मज्ञा ब्रह्मप्रापका वा वेदाः ब्रह्मस्वरूपास्तज्ज्ञा वा चकारेण सशब्दार्थाः। यज्ञाः यजनात्मकाः? चकारेण साधिदैवाः। पुरा सृष्ट्यादौ विहिता विधात्रा निर्मिताः? अतः पूर्वमेतदुदाहरणात्सर्वं सम्पद्यत इति भावः। अथवा तेन ब्रह्मणोऽयं त्रिविधो निर्देशस्तेन ब्रह्मणा पूर्वमेते निर्मिताः स्वार्थं? ततस्तत्स्वरूपं ज्ञानपूर्वकनामत्रयोदाहरणसंसूचनात्मकेन निर्गुणानां सर्वं सम्पत्स्यत इति भावः।'),
('purushottama-sc:source:17.24','Puruṣottamajī','gita.17.24','sa','commentary','।।17.24।।यत एतदुदाहरणेन सर्वं सम्पद्यते तत्तस्मात् त्रिगुणानां भक्तानां मुमुक्षूणां च लौकिके सतां चैतन्नामत्रितयं साधकमित्याह -- तस्मादिति। तस्मात्कारणाद्ब्रह्मवादिनां भगवद्भक्तानां यज्ञदानतपःक्रियाः भगवदर्थिकाःओम् इत्युदाहृत्य ताः सततं निरन्तरं विधानोक्ताः भगवत्प्रीत्यर्थं प्रवर्त्तन्ते प्रकर्षेण वर्त्तन्ते भवन्तीत्यर्थः।'),
('purushottama-sc:source:17.25','Puruṣottamajī','gita.17.25','sa','commentary','।।17.25।।भक्तानामुक्त्वा ज्ञानिनां द्वितीयनामसम्बन्धिफलमाह -- तदिति।तत् इति उदाहृत्य तद्ब्रह्मत्वाज्ञापरिपालनेन प्रीयादित्युदाहृत्य फलं स्वर्गादिसुखरूपम्? अनभिसन्धाय फलाभिलाषं मनस्यकृत्वा मोक्षकाङ्क्षिभिर्निर्दोषैर्यज्ञतपःक्रियाः यज्ञः अग्निहोत्रादिः? तपः कृच्छ्रादि? तदादयः क्रियाः क्रियन्ते। तच्छब्दोदाहणात्ताश्च सम्पन्ना भूत्वा मोक्षसम्पादिका भवन्तीत्यर्थः।'),
('purushottama-sc:source:17.26','Puruṣottamajī','gita.17.26','sa','commentary','।।17.26।।लौकिकसत्सु सदिति नाम तत्सम्पादकं भवतीत्याह -- सद्भाव इति। सद्भावे आस्तिक्यभावे साधुभावे उत्तमत्वभावे चसत् इत्येतन्नाम प्रयुज्यते तथा प्रशस्ते कर्मणि भगवदर्थके कर्मणि हे पार्थसत् इतिशब्दो युज्यते युक्तो भवतीति भावः।'),
('purushottama-sc:source:17.27','Puruṣottamajī','gita.17.27','sa','commentary','।।17.27।।अथ भगवत्परत्वं सर्वत्रैव सच्छब्दे एवोच्यते इत्याह -- यज्ञे तपसीति। यज्ञे अग्निहोत्रादौ? तपसि कृच्छ्रादौ? दाने तुलापुरुषादौ या स्थितिः भगवदेकनिष्ठतया करणं तद्रूपा च सा सदिति उच्यते। च पुनः। तदर्थीयमेव कर्म यस्यैतन्नामत्रयं तस्य भगवत एव अर्थीयं सेवादिसामग्री सम्पादनरूपं सदित्येव अभिधीयते।'),
('purushottama-sc:source:17.28','Puruṣottamajī','gita.17.28','sa','commentary','।।17.28।।अथैतदतिरिक्तं श्रद्धाविहीनमेतदपि असदित्युच्यत इत्याह -- अश्रद्धयेति। अश्रद्धया श्रद्धां विना हुतं हवनादिकं? दत्तं दानादि? तप्तं तपः? च पुनः यत्किञ्चित् कृतं कर्म यागतीर्थस्नानादिकं? हे पार्थ मद्भक्त तत्सर्वं असदित्युच्यते? तच्च प्रेत्य परलोके न फलति मत्सम्बन्धाभावात्। इह लोके न फलं? सदनादृतत्वात्। अतो मत्सम्बन्ध्येव लौकिकालौकिकं फलतीति तदेव कर्त्तव्यमिति निरूपितम्।निष्फलं त्रिगुणं कर्म सश्रद्धमपि यत्कृतम्। सफलं निर्गुणं चातः कर्त्तव्यमिति रूपितम्।'),
('purushottama-sc:source:18.1','Puruṣottamajī','gita.18.1','sa','commentary','।।18.1।।अष्टादशानां विद्यानां फलमेतद्यतो मतम्। सर्वत्यागेन कर्त्तव्यो ह्याश्रयः सर्वभावतः।।1।।अतः पार्थाय सुप्रीतः प्राहाष्टादशसंज्ञके। अध्याये स्वाश्रयं श्रीमत्कृष्णो देवकिनन्दनः।।2।।अत्र सप्तदशाध्यायैर्भगवद्वाक्यतरणिकिरणविपाटितहृदयमोहान्धकारोऽर्जुनः सन्न्यासकर्मफलत्यागयोरेव भगवत्प्राप्तिहेतुत्वनिश्चयप्रकाशितहृत्सरोरुहः स्वबुद्धिनिश्चयेन सन्न्यासोत्तमज्ञानोऽपि भगवदुक्तस्वमुख्यज्ञानेन तत्सिसाधयिषुस्तयोस्तत्त्वं पृच्छति -- सन्न्यासस्येति। हे हृषीकेश एतत्तत्त्वज्ञानार्थं मदिन्द्रियप्रेरक सर्वकर्माणि मनसा सन्न्यस्याऽऽस्ते सुखं वशी। सन्न्यासयोगयुक्तात्मा विमुक्तो मामुपैष्यसि [5।13] इत्यादिना सन्न्यासस्य स्वप्राप्तिरुक्ता? तत्र तस्य तत्त्वं यादृशेन त्वत्प्राप्तिर्भवति तादृक् तत्त्वं? हे महाबाहो अहं वेदितुं ज्ञातुमिच्छामि? तज्ज्ञापयेत्यर्थः। महत् क्रियाशक्तिमत्? स्वोद्धारणसमर्थ त्वत्सम्बन्धेनैतत्तत्त्वोपदेशेन मामुद्धरेत्युक्तं भवति। च पुनः हे केशिनिषूदन दैत्यनिवारक दैत्यावेशेन कायक्लेशादिककृतत्यागात् पृथक् त्यागस्य त्वत्सेवार्थकृतत्यागस्य तत्त्वं मुख्यरूपं वेदितुं ज्ञातुमिच्छामि।'),
('purushottama-sc:source:18.2','Puruṣottamajī','gita.18.2','sa','commentary','Sanskrit Commentary By Sri Purushottamji
INSERT INTO commentary_fts (unit_id,author,canonical_ref,language,content_type,content) VALUES
('purushottama-sc:source:18.59','Puruṣottamajī','gita.18.59','sa','commentary','।।18.59।।किञ्च -- यदहङ्कारमिति। यत् पूर्वोक्तं गुर्वादिहननाद्यधर्मरूपं अहङ्कारं तदज्ञानमाश्रित्य मद्वाक्याश्रवणेन न योत्स्ये न युद्धं करिष्यामीति मन्यसे अध्यवस्यसे? एष ते व्यवसायो निश्चयो मिथ्या? असद्रूपो निष्फल इत्यर्थः। पराधीनत्वादित्याह -- प्रकृतिः मदधीना मदाज्ञाविमुखं त्वां नियोक्ष्यति युद्धे प्रवर्त्तयिष्यतीत्यर्थः।अत्रायं भावः -- मदाज्ञाविमुखस्य प्राकृतत्वेन ज्ञाते प्रकृतिनियोज्यत्वं? मदाज्ञाप्रवर्तमानस्य तदनियोज्यत्वम्।'),
('purushottama-sc:source:18.60','Puruṣottamajī','gita.18.60','sa','commentary','।।18.60।।किञ्च -- स्वभावजेनेति। हे कौन्तेय स्नेहपात्र स्वभावजेन मत्क्रीडोत्पन्नेन स्वेन क्षात्त्रकर्मणा शौर्यादिरूपेण निबद्धो यन्त्रितो यत् मोहात् युद्धं कर्तुं नेच्छसि? तत् अवशोऽपि करिष्यसि अतो मदाज्ञयैव कुर्वित्यर्थः।'),
('purushottama-sc:source:18.61','Puruṣottamajī','gita.18.61','sa','commentary','।।18.61।।नन्वीश्वराज्ञाव्यतिरेकेण प्रकृतिकर्मणोः कथं तथात्वं इत्यत आह -- ईश्वर इति। हे अर्जुन वृक्षजातीयनामत्वेन ज्ञानानर्ह ईश्वरो नियामकस्तत्त्वेन सर्वभूतानां हृद्देशे हृदयमध्ये तिष्ठति मायया सर्वभूतानि यन्त्रारूढानि शरीरारूढानि भ्रामयँस्तिष्ठति यथा दारुयन्त्रारूढानि कृत्रिमभूतानि सूत्रधारश्चालयति तथा मायया भ्रामयंस्तिष्ठतीति वाऽर्थः। अत ईश्वरप्रेरितानेव प्रकृतिः कर्म च साधकतया प्रेरयतीत्यर्थः।'),
('purushottama-sc:source:18.62','Puruṣottamajī','gita.18.62','sa','commentary','।।18.62।।मामज्ञात्वा मदाज्ञां चेन्न करोषि तदा हृदयस्थितेश्वरस्यैव शरणं गच्छेत्याह -- तमेवेति। हे भारत सत्कुलोत्पन्नत्वादहङ्काररहित तं पूर्वोक्तं हृदयस्थितमेव ईश्वरं सर्वभावेन सङ्कल्पविकल्पान् परित्यज्य सर्वात्मना शरणं गच्छ? ततस्तत्प्रसादात् परां शान्तिं शाश्वतं नित्यं स्थानं पूर्वश्लोकोक्तमक्षरात्मकं प्राप्स्यसि।'),
('purushottama-sc:source:18.63','Puruṣottamajī','gita.18.63','sa','commentary','।।18.63।।अथ सकलगीताशास्त्रार्थमुपसंहरन्नाह -- इतीति। इति अमुना प्रकारेण ते तव मया सर्वकर्त्रा सर्वात्मना गुह्यात् गोप्यात् गुह्यतरं गोप्यतरं मन्त्रबीजवत् सर्वशास्त्रज्ञानसारात्मकं ज्ञानमाख्यातं आ समन्तात् ससाधनं प्रसिद्धतयोक्तमित्यर्थः। एतत् मदुपदिष्टगीताशास्त्रार्थं अशेषेण पूर्वापरानुसन्धानेन विमृश्य पर्यालोच्य यथा कर्तुमिच्छसि उत्तमत्वेन तथा कुरु। एतद्विमर्शात् तदाज्ञाकरणे एव बुद्धिर्भविष्यतीत्याशयेनयथेच्छसि इत्युक्तमिति भावः।'),
('purushottama-sc:source:18.64','Puruṣottamajī','gita.18.64','sa','commentary','।।18.64।।विमृश्यकारित्वमीश्वरोक्तावसम्भावितमिति विचारेण शोचन्तमर्जुनं कृपया तद्द्वारा च लोकानुद्दिधीर्षुर्निश्चितार्थं स्वयमेवाह -- सर्वगुह्येति। सर्वगुह्येऽतिगुह्यं गोप्यं गुह्यतमं मे परमं फलरूपं वचो भूयः पूर्वमुक्तमपि तत्प्रकरणेषु इदानीमेकीकृत्य पुनर्वक्ष्यमाणं शृणु। एवं सारभूतमेकीकृत्याकथने हेतुमाह -- इष्टोऽसीति। मे मम दृढमत्यन्तम् अप्रियकरणेऽपि अन्यथाभावरहितः इष्टः प्रियोऽसि? ततः कारणात्ते हितं वक्ष्यामि कथयामि।'),
('purushottama-sc:source:18.65','Puruṣottamajī','gita.18.65','sa','commentary','।।18.65।।एवं प्रतिज्ञाय तत्स्वरूपमाह -- मन्मना इति। मन्मनाः मय्येव मनो यस्य तादृशो भव? मद्भक्तः मयि स्नेहयुक्तो भव? मद्याजी मत्पूजनशीलो भव? मां नमस्कुरु मयि सर्वाधिक्यज्ञानवान् भवेत्यर्थः। एवम्भूतः सन् सत्यं सत्यरूपं मामेव एष्यसि प्राप्स्यसि? नात्र सन्देहः कर्त्तव्यः यतो मे मम प्रियोऽसि अतस्ते तुभ्यं प्रतिजाने प्रतिज्ञां करोमि।'),
('purushottama-sc:source:18.66','Puruṣottamajī','gita.18.66','sa','commentary','।।18.66।।नन्वेतत्कथं सिद्ध्येत् इत्याशङ्क्याऽऽह -- सर्वधर्मानिति। सर्वधर्मान् चोदनालक्षणान् परित्यज्य कर्त्तव्योत्तमत्वलक्षणज्ञानाभावेन त्यक्त्वा मामेकं मुख्यं पुरुषोत्तमं शरणं व्रज इत्यर्थः।धर्मान् इति बहुवचनेनमामेकं इत्येकवचनेन च तत्रायाससाध्यत्वं साङ्गानुष्ठेयत्वम्? अत्र सुखसेव्यत्वं सर्वफलदानसामर्थ्यं च,ज्ञापितम्। सर्वधर्मपदेन लौकिकालौकिकधर्मत्यागयुक्तो भवेत्यसङ्कुचितवृत्त्या। विशेषेणास्यार्थस्तुश्रीमद्विठ्ठलेश्वरैरस्मत्प्रभुचरणैर्निरूपित इति नात्र प्रपञ्च्यते। एवं सर्वधर्मत्यागेन शरणागतौ पूर्वोक्तं सिद्ध्यतीत्यर्थः। ननु पूर्वजन्मसञ्चितपापप्रतिबन्धकतया कथं सर्वधर्मत्यागः शरणागतिर्वा सेत्स्यति इत्यत आह -- अहमिति। अहं त्वां पूर्वोक्तस्वेष्टत्वात् सर्वपापेभ्यः प्रतिबन्धकरूपेभ्यो मोक्षयिष्यामि मोचयिष्यामि? प्रतिबन्धकपापादिस्मरणेन मा शुचः शोकं माकार्षीः।'),
('purushottama-sc:source:18.67','Puruṣottamajī','gita.18.67','sa','commentary','।।18.67।।एवं सकलशास्त्रार्थगीतार्थतत्त्वमुपदिश्य लोकोद्धारार्थमेतदुपदेशनेन मार्गप्रवर्तनार्थमधिकारिणमाह -- इदं ते इति। इदं सर्वशास्त्ररहस्यं ते त्वया अतपस्काय स्वाचारहीनाय न वाच्यम्। न च अभक्ताय मद्भक्तिरहिताय कदाचन वाच्यम्।कदाचन इतिपदेनाभक्तसंसर्गिणे भक्तायाऽपि न वाच्यमिति ज्ञापितम्। न च पुनः अशुश्रूषवे श्रवणेच्छारहिताय? अनासक्तायेत्यर्थः। यद्वा मत्परिचर्याहीनाय च न वाच्यम्। यो मां पुरुषोत्तमं बाहिर्मुख्येण अभ्यसूयति दोषारोपपूर्वकं कौटिल्येन निन्दति तस्मै च न च वाच्यम्।'),
('purushottama-sc:source:18.68','Puruṣottamajī','gita.18.68','sa','commentary','।।18.68।।एवमेतद्दोषयुक्तेभ्यो न वाच्यं? एतद्दोषरहितेभ्यश्च सर्वथा वाच्यमित्येतदुपदेशनफलमाह -- य इदमिति। यः कश्चन दुर्लभः मद्भक्तिरसाविष्टं इमं पूर्वश्लोकोक्तं परमं सर्वोत्कृष्टं गुह्यं गोप्यं मद्भक्तेषु पूर्वोक्तदोषरहिततद्गुणसुसम्पन्नेषु अभिधास्यति वक्ष्यति श्रोता वक्ता चैतच्छ्रवणेन असंशयः सन्देहरहितः सन् परां सर्वोत्कृष्टां पूर्वोक्तां मयि भक्ितं कृत्वा मामेव एष्यति? प्राप्नोतीत्यर्थः।'),
('purushottama-sc:source:18.69','Puruṣottamajī','gita.18.69','sa','commentary','।।18.69।।ननु कथमेतत्कथनश्रवणमात्रेण त्वां प्राप्नोति इत्यत आह -- न चेति। तस्मादेतद्वक्तुः सकाशात् मनुष्येषु अधिकारिषु मे प्रियकृत्तमः प्रियकर्तृषु मध्ये अतिशयितो नच? नास्तीत्यर्थः। मद्भक्तानां मत्सङ्गार्थयत्नप्रर्दशकत्वादिति भावः। च पुनः तस्मात् श्रोतुः सकाशात् श्रुत्वा मदाज्ञप्तसेवादिकरणात् अन्यो भुवि प्रियतरो भविता नेत्यर्थः।'),
('purushottama-sc:source:18.70','Puruṣottamajī','gita.18.70','sa','commentary','।।18.70।।एवमुपदेष्टुः श्रोतुश्च फलमुक्त्वा पाठकर्तुः फलमाह -- अध्येष्यत इति। आवयोः श्रीकृष्णार्जुनयोः धर्म्यं धर्मयुक्तं धर्मोत्पादकं वा संवादं सोत्तरप्रत्युत्तरं गीतात्मकं सम्यक्प्रकारेण वदनात्मकं यश्च अध्येष्यते ध्यानं कृत्वा जपरूपेण पठिष्यति? तेनाध्ययनेन सर्वयज्ञश्रेष्ठेन ज्ञानयज्ञेन ज्ञानात्मकमद्यजनेन अहं तस्य इष्टः प्रियः स्यां? भवेयमित्यर्थः। इति एवम्प्रकारिका मे मम मतिः बुद्धिरित्यर्थः। स्वमतित्वकथनेनैतत्पाठस्याऽऽवश्यकत्वं करणे च स्वप्रसादावश्यकत्वं ज्ञापितमिति भावः।'),
('purushottama-sc:source:18.71','Puruṣottamajī','gita.18.71','sa','commentary','।।18.71।।एवंरूपज्ञानेनैकस्य पठतो योऽन्यः कश्चिच्छृणोति तस्यापि फलतीत्याह -- श्रद्धावानिति। यो नरः श्रद्धावान्एतच्छ्रवणेनाहं कृतार्थो भविष्यामि इत्यत्यादरयुक्तः शृणुयादप्यर्थानवबोधेनापि स शुभान् मोक्षप्रापकान् लोकान् प्राप्नुयात्। च पुनः अनसूयः किमिति दम्भार्थमुच्चैः पाषण्डी पठतीत्याद्यसूयारहितः सम्यक् गीतां पठतीत्याद्यनुमोदते मनसि सोऽपि मुक्तः संसारात् पुण्यकर्मणां लोकान् स्वर्गादीन् प्राप्नुयात्।'),
('purushottama-sc:source:18.72','Puruṣottamajī','gita.18.72','sa','commentary','।।18.72।।एवं संसारमुक्तिः शुभलोकप्राप्तिश्च मोहनाशो भवति? स च भगवन्मुखाच्छ्रवणेऽर्जुनस्यैव ततः पुनर्युद्धादिकरणात्तदा कथमन्यस्य भवेत् इति बहिर्मुखशङ्कामपनुदन् भगवानर्जुनं पृच्छति -- कश्चिदेतदिति। हे पार्थ श्रद्धयैतच्छ्रवणयोग्य कच्चिदिति प्रश्नार्थः। त्वया एकाग्रेण चेतसा प्रणिहितेन मनसा एतन्मयोक्तं श्रुतं तेन श्रवणेन हे धनञ्जय ते अज्ञानसम्मोहः अज्ञानेन मत्स्वरूपेङ्गिताज्ञानेन जनितो यः सम्मोहः आसुरमारणजपापोत्पत्तिरूपः सम्यक्प्रकारको मोहो भ्रमो नष्टः। ते तवेत्यर्थः।'),
('purushottama-sc:source:18.73','Puruṣottamajī','gita.18.73','sa','commentary','।।18.73।।एवं प्रश्ने नष्टमोहः सन् अर्जुन उत्तरं प्राह -- नष्टो मोह इति। अज्ञानकृतो मोहो नष्टः? त्वदुक्ितश्रवणेनेति शेषः। अधिकमपि जातं हे अच्युत सर्वत्र च्युतिरहित मया अहङ्काराज्ञानसहितेन त्वत्प्रसादात् स्मृतिः तत्स्वरूपात्मिका लब्धा प्राप्ता।प्रसादात् इति कथनेन साधनालभ्यतोक्ता। अहो दासस्य प्रभ्वाज्ञाकरणमेव धर्मः? न त्वन्योऽपि धर्माधर्मविचारः। एवं गतसन्देहः संस्तवाग्रे दासत्वेन स्थितोऽस्मि इदानीं,तव वचनं पूर्वोक्तं युद्धादिरूपं सर्वधर्मत्यागरूपं त्वद्भक्तेष्वेतदुपदेशरूपं च करिष्ये।'),
('purushottama-sc:source:18.74','Puruṣottamajī','gita.18.74','sa','commentary','।।18.74।।एवं धृतराष्ट्रपृष्टश्रीकृष्णार्जुनसंवादं सफलमशेषतः कथयित्वा भगवति सासूयत्वात् धृतराष्ट्रस्य फलाभावकथनार्थं स्वस्य च तदग्रे कथनावश्यकत्वाय स्वस्य श्रवणानन्दभवनकारणज्ञापनाय स्तुतकथानुसन्धानेन सञ्जय उवाच -- इतीति। इति अमुना प्रकारेण अहं त्वदीयत्वेन द्वेषसम्बन्धयुक्तोऽपि वासुदेवस्य मोक्षदातुः महात्मनो भगवद्भक्तस्य पार्थस्य च इमं मया पूर्वोक्तं संवादम् उत्तरप्रत्युत्तररूपं अद्भुतम्? अलौकिकं रोमहर्षणं रोमहर्षकरम् आनन्दोद्बोधकं अश्रौषं श्रुतवानस्मि।'),
('purushottama-sc:source:18.75','Puruṣottamajī','gita.18.75','sa','commentary','।।18.75।।ननु द्वेषभावसम्बन्धे सति कथं श्रुतं इत्यत आह -- व्यासप्रसादादिति। व्यासस्य भगवज्ज्ञानावतारस्य प्रसादात् चक्षुश्श्रोत्रादिकं व्यासेनालौकिकं दिव्यं दत्तं? तेन श्रुतवानस्मि। किं तदिति श्रुतं इत्यत आह। एतत् परिदृश्यमानं गुह्यं गोप्यं परं सर्वोत्कृष्टं योगं योगेश्वरात् कृष्णात् साक्षात् स्वयं कथयतःश्रुतवानस्मि।'),
('purushottama-sc:source:18.76','Puruṣottamajī','gita.18.76','sa','commentary','।।18.76।।किञ्च -- राजन्निति। हे राजन् इमं केशवार्जुनयोः संवादं अद्भुतं लौकिकोपपत्तिरहितं पुण्यजनकं संस्मृत्य संस्मृत्य सादरं संस्मृत्य सादरं संस्मृत्य मुहुर्मुहुः वारंवारं हृष्यामि हर्षं प्राप्नोमि।'),
('purushottama-sc:source:18.77','Puruṣottamajī','gita.18.77','sa','commentary','।।18.77।।किञ्च तच्चेति। तत् अत्यद्भुतं अलौकिकरूपं संस्मृत्य? च पुनः हरेः सर्वदुःखहर्तुः पुरुषोत्तमसम्बन्धिरूपं संस्मृत्य मे विस्मयो महान् जातः? कथं त्वदीया जेष्यन्तीति। मूलभूतस्वरूपदर्शनेन सर्वे मोक्षं प्राप्स्यन्तीति पुनः पुनः वारं वारमादरेण हृष्यामि। यद्वा -- हरेः अत्यद्भुतं पुरुषोत्तमत्वेनानुभवैकवेद्यं तत्संस्मृत्य स्मरणं कृत्वा पुनः संस्मृत्य ध्यानं कृत्वा मे महान् विस्मयः? यतःक्वाहं तुच्छो जीवः? क्व तद्दर्शनं इति त्वत्सम्बन्धेन दर्शनं जातमतः सम्बोधयति -- राजन्निति। किञ्च पुनः हृष्यामि आनन्दं प्राप्नोमि। भगवद्दर्शने हर्षस्तवाप्यनुभवसिद्ध इति तज्ज्ञत्वेन महत्सम्बोधयति -- राजन्निति।'),
('purushottama-sc:source:18.78','Puruṣottamajī','gita.18.78','sa','commentary','।।18.78।।एवं गीताश्रवणेन भगवद्दर्शनानन्दितचित्तेन स्वमतिनिश्चितार्थमनुवदति तथात्वज्ञानेन शरणागमनार्थम् -- यत्रेति। यत्र येषां पक्षे योगानां सर्वसाधनानामीश्वरो नियामकः तत्र श्रीः लक्ष्मीः? यत्र यस्मिन्नर्थे पार्थः पृथायाः क्षत्ित्रयायाःयदर्थे क्षत्ित्रयासुत इति वाक्यवक्त्र्याः पुत्रो महाशूरो भगवदीयश्च धनुर्धरः ससामग्रीकः तत्र विजयः शत्रूणां पराजयपूर्वकमुत्कर्षः? यत्रैव लक्ष्मीस्तत्रैव भूतिस्तदंशरूपा राज्यलक्ष्मीः ध्रुवा निश्चला? यत्र विजयस्तत्र नीतिर्नय इत्यर्थः। इत्येवंरूपा मे मतिः मद्बुद्धिनिश्चयः।अत्रायं भावः -- यत्र श्रीकृष्णार्जुनौ पक्षे भवतः तत्र श्यादिकं भवति? तत्र साक्षात्तावेव यत्र तत्र किं वाच्यमिति भावः। अतस्तवापि संरम्भादित्यागेन शरणगमनमेव सर्वार्थसाधकमिति भावः। स्वमतित्ववाचकस्येति प्रतिजानीमः।श्रीकृष्णानन्यभक्तस्य गीताश्रवणतः परा। दृढा भक्तिर्भवेद्गीतासारस्त्वेवं हि बुद्ध्यताम्।।1।।शास्त्रार्थरूपमज्ञात्वा कृतं न फलदं भवेत्। हरिर्भजनसिद्ध्यर्थं गीताशास्त्रमथाब्रवीत्।।2।।अर्जुनाय प्रसङ्गेन सर्वोद्धारप्रयत्नवान्। तस्माज्ज्ञात्वा हि गीतार्थं कृष्णः सेव्यो हि सर्वदा।।3।।अतस्तदर्थं गीतार्थो निगूढो विनिरूपितः। श्रीमदाचार्यपादाब्जभक्त्या लब्धो ह्यनन्यया।।4।।श्रीमदाचार्यपादेषु गीतार्थकुसुमाञ्जलिः। न्यस्तस्तेन प्रसीदन्तु ते सदा मयि किङ्करे।।5।।पुष्टिमार्गीयभक्तानां विहारार्थं सुनिर्मला। कृता श्रीकृष्णभावाब्धिगीतामृततरङ्गिणी।।6।।अनन्यैकैव भक्तिर्हि कार्या श्रीकृष्णतुष्टये। विद्याष्टादशकेनापि सर्वथैवोच्यते यतः।।7।।इत्येवाष्टादशाध्यायैर्गीताशास्त्रं हरिः स्वयम्। प्रकटीकृतवाँल्लोके दयालुर्देवकीसुतः।।8।।अत्र युक्तमयुक्तं वा जीवबुद्ध्या ह्यलेखि यत्। तत् क्षमन्तु सदाऽऽचार्याः स्वाङ्गीकृतिबलान्मयि।।9।।कृष्णो जलधरश्यामो बभौ राजीवलोचनः। श्यामाऽपि यस्य वामांसे विद्युल्लेखेव राजते।।10।।'),
('nilakantha-sc:source:1.1','Nīlakaṇṭha','gita.1.1','sa','commentary','।।1.1।।तत्र युद्धोद्यमं श्रुत्वौत्सुक्यादग्रिमं वृत्तान्तं बुभुत्सुर्धृतराष्ट्र उवाच धर्मक्षेत्र इति। तत्र वेदेतेषां कुरुक्षेत्रं देवयजनमास इति कर्मकाण्डप्रसिद्धं कुरुक्षेत्रमन्यत्अविमुक्तं वै कुरुक्षेत्रं देवानां देवयजनं सर्वेषां भूतानां ब्रह्मसदनम् इत्यविमुक्ताख्यं ब्रह्मप्राप्तिस्थानभूतं कुरुक्षेत्रमन्यत्। ब्रह्मसदनत्वं चास्य अत्र हि जन्तोः प्राणेषूत्क्रममाणेषु रुद्रस्तारकं ब्रह्म व्याचष्टे येनासावमृतीभूत्वा मोक्षी भवतीति वाक्यशेषेण व्युत्पादितम्। एतद्व्यावृत्त्यर्थं धर्मक्षेत्रे इति विशेषणम्। कुरुदेशान्तर्गतं हि कुरुक्षेत्रं धर्मक्षेत्रमेव नतु तद्ब्रह्मसदनम्। प्रवर्ग्यकाण्डे तस्य धर्मक्षेत्रत्वमात्रश्रवणात्। तत्र समवेता मिलिताः युयुत्सवो योद्धुमिच्छवः। पाण्डवानां पृथग्ग्रहणं तेषु ममत्वाभावसूचनार्थम्।'),
('nilakantha-sc:source:1.2','Nīlakaṇṭha','gita.1.2','sa','commentary','।।1.2।।व्यूढं व्यूहरचनया स्थितम्। आचार्यं द्रोणम्। राजा दुर्योधनः। राजाब्रवीदित्येव सिद्धे वचनपदेन संक्षिप्तबह्वर्थत्वादिगुणवत्त्वं वाक्यस्य सूच्यते।'),
('nilakantha-sc:source:1.3','Nīlakaṇṭha','gita.1.3','sa','commentary','।।1.3।।द्रुपदपुत्रेणेति पूर्ववैरसूचनेन क्रोधोद्दीपनार्थं विशेषणम्।'),
('nilakantha-sc:source:1.4','Nīlakaṇṭha','gita.1.4','sa','commentary','।।1.4।।महेष्वासा महान्त इष्वासाः धनूंषि येषां ते। युयुधानः सात्यकिः। द्रुपदश्च महारथ इत्येकः।'),
('nilakantha-sc:source:1.5','Nīlakaṇṭha','gita.1.5','sa','commentary','।।1.5।।धृष्टकेत्वादयः षट्।'),
('nilakantha-sc:source:1.6','Nīlakaṇṭha','gita.1.6','sa','commentary','।।1.6।।युधामन्यूत्तमौजसौ सौभद्रोऽभिमन्युः पञ्च द्रौपदेयाः प्रतिविन्ध्यादयश्चेत्यष्टौ। चकारात् पाण्डवा घटोत्कचादयश्चातिप्रसिद्धा ग्राह्याः। सर्वेऽपि महारथा एव। तल्लक्षणं तुएको दशसहस्राणि योधयेद्यस्तु धन्विनाम्। शस्त्रशास्त्रप्रवीणश्च स वै प्रोक्तो महारथः। अमितान्योधयेद्यस्तु संप्रोक्तोऽतिरथस्तु सः। रथस्त्वेकेन योद्धा स्यात्तन्न्यूनोऽर्धरथः स्मृतः। इति।'),
('nilakantha-sc:source:1.7','Nīlakaṇṭha','gita.1.7','sa','commentary','।।1.7।।विशिष्टाः श्रेष्ठाः। निबोध बुध्यस्व। भौवादिकस्य परस्मैपदिनो बुधेरिदं रूपम्। संज्ञार्थं अस्मत्पक्षेऽपि शूराः सन्तीति ज्ञापनार्थम्। परेषु प्राबल्यं दृष्ट्वा तवोत्साहभङ्गो माभूदित्यर्थः।'),
('nilakantha-sc:source:1.8','Nīlakaṇṭha','gita.1.8','sa','commentary','।।1.8।।विकर्णः स्वभ्राता। सौमदत्तिर्भूरिश्रवाः। जयद्रथपदस्थानेतथैव च इति क्वचित्पाठः।'),
('nilakantha-sc:source:1.9','Nīlakaṇṭha','gita.1.9','sa','commentary','।।1.9।।अन्ये शल्यकृतवर्मप्रभृतयः। शस्त्राणि विदारकाणि खङ्गादीनि प्रहरणानि केवलं प्रहारार्थानि गदादीनि नानाविधानि येषां ते नानाशस्त्रप्रहरणाः।'),
('nilakantha-sc:source:1.10','Nīlakaṇṭha','gita.1.10','sa','commentary','।।1.10।।पर्याप्तं परित आप्तं परिवेष्टितम्। पाण्डवसैन्यं हि सप्ताक्षौहिणीमितत्वादल्पं बहुनैकादशाक्षौहिणीमितेनास्मत्सैन्येन वेष्टयितुं शक्यं नतु तदीयेनास्मदीयमित्यर्थः। एवं च पर्याप्तमित्यस्य पारणीयमित्यर्थः।'),
('nilakantha-sc:source:1.11','Nīlakaṇṭha','gita.1.11','sa','commentary','।।1.11।।अयनेषु व्यूहरचनया स्थिते सैन्ये प्रवेशमार्गेषु स्वे स्वे स्थाने स्थिता यूयं मध्यस्थं भीष्ममेवाभिरक्षन्तु। अस्य सेनापतेश्चाञ्चल्ये सर्वापि सेना आकुलीभवेत्। तत्स्थैर्ये स्थिरा च भवेदतः स एव रक्ष्य इत्यर्थः।'),
('nilakantha-sc:source:1.12','Nīlakaṇṭha','gita.1.12','sa','commentary','।।1.12।।तस्य एवं वदतो दुर्योधनस्य संजयवाक्यमिदम्। सिंहनादमिति णमुलन्तम्। तेन विनद्येत्यस्यानुप्रयोगः कषादित्वात्समूलकाषं कषतिस्म दैत्यान् इत्यादिवत्। कुरुवृद्धो भीष्मः। प्राग्विराटनगरादौ दृष्टप्रभावान्पाण्डवान्दृष्ट्वा राज्ञो भयं मा भूदिति शङ्खं दध्मौ। हर्षं युद्धोत्साहं जनयन्। हेत्वर्थे शतृप्रत्ययः। हर्षजननार्थमित्यर्थः।'),
('nilakantha-sc:source:1.13','Nīlakaṇṭha','gita.1.13','sa','commentary','।।1.13।।अभ्यहन्यन्त अभिहताः। कर्मकर्तरि प्रयोगः।'),
('nilakantha-sc:source:1.14','Nīlakaṇṭha','gita.1.14','sa','commentary','।। 1.14अभ्यहन्यन्त अभिहताः। कर्मकर्तरि प्रयोगः।'),
('nilakantha-sc:source:1.15','Nīlakaṇṭha','gita.1.15','sa','commentary','।। 1.15अभ्यहन्यन्त अभिहताः। कर्मकर्तरि प्रयोगः।'),
('nilakantha-sc:source:1.16','Nīlakaṇṭha','gita.1.16','sa','commentary','।। 1.16अभ्यहन्यन्त अभिहताः। कर्मकर्तरि प्रयोगः।'),
('nilakantha-sc:source:1.17','Nīlakaṇṭha','gita.1.17','sa','commentary','।। 1.17अभ्यहन्यन्त अभिहताः। कर्मकर्तरि प्रयोगः।'),
('nilakantha-sc:source:1.18','Nīlakaṇṭha','gita.1.18','sa','commentary','।। 1.18अभ्यहन्यन्त अभिहताः। कर्मकर्तरि प्रयोगः।'),
('nilakantha-sc:source:1.19','Nīlakaṇṭha','gita.1.19','sa','commentary','।। 1.19अभ्यहन्यन्त अभिहताः। कर्मकर्तरि प्रयोगः।'),
('nilakantha-sc:source:1.20','Nīlakaṇṭha','gita.1.20','sa','commentary','।।1.20।।व्यवस्थितान् भयोद्विग्नतया वैषम्येणावस्थितान्। कपिध्वजपाण्डवपदाभ्यां भीषणध्वजत्वं शौर्यं च प्रदृश्यते।'),
('nilakantha-sc:source:1.21','Nīlakaṇṭha','gita.1.21','sa','commentary','।।1.21।।हृषीकेशं सर्वेषामिन्द्रियाणां प्रवर्तकत्वेन परचित्ताभिज्ञम्। वाक्यमेवाह न तु कञ्चिदर्थमिति द्योतनार्थं वाक्यपदम्। वाक्यमेवाह सेनयोरिति।'),
('nilakantha-sc:source:1.22','Nīlakaṇṭha','gita.1.22','sa','commentary','।।1.22।।रथस्थापनप्रयोजनमाह यावदिति। कैः सह मया योद्धव्यं मया सह वा कैर्योद्धव्यमित्युभयत्र सहशब्दसंबन्धः। के वा मां जेतुं यतन्ते मया वा के जेतव्या इत्यालोचनार्थमित्यर्थः।'),
('nilakantha-sc:source:1.23','Nīlakaṇṭha','gita.1.23','sa','commentary','।।1.23।।योत्स्यमानान् न तु शान्तिकामान्। यतो दुर्बुद्धेः प्रियं चिकीर्षन्ति तेन तेषामपि तत्तुल्यत्वं सूचितम्।'),
('nilakantha-sc:source:1.24','Nīlakaṇṭha','gita.1.24','sa','commentary','।।1.24।।रथोत्तमं स्थापयित्वा उवाचेति द्वयोः संबन्धः।'),
('nilakantha-sc:source:1.25','Nīlakaṇṭha','gita.1.25','sa','commentary','।।1.25।।महीक्षितां पृथिवीश्वराणाम्।'),
('nilakantha-sc:source:1.26','Nīlakaṇṭha','gita.1.26','sa','commentary','।।1.26।।पितृ़न् पितृव्यादीन् भूरिश्रवःप्रभृतीन्। पितामहान् भीष्मादीन्। मातुलान् शल्यादीन्। भ्रातृ़न् दुर्योधनादीन्। पुत्रान् लक्ष्मणादीन्। पौत्रान् लक्ष्मणादिपुत्रान्। सखीन् अश्वत्थामादीन्।'),
('nilakantha-sc:source:1.27','Nīlakaṇṭha','gita.1.27','sa','commentary','।।1.27।।सुहृदः कृतवर्मादीन्।'),
('nilakantha-sc:source:1.28','Nīlakaṇṭha','gita.1.28','sa','commentary','।।1.28।।कृपया स्नेहेन। स च स्वजनमिति विशेषणेन प्रदर्श्यते।'),
('nilakantha-sc:source:1.29','Nīlakaṇṭha','gita.1.29','sa','commentary','।।1.29।।सीदन्ति निश्चेष्टानि भवन्ति। रोमहर्षो रोमाञ्चः।'),
('nilakantha-sc:source:1.30','Nīlakaṇṭha','gita.1.30','sa','commentary','।। 1.30सीदन्ति निश्चेष्टानि भवन्ति। रोमहर्षो रोमाञ्चः।'),
('nilakantha-sc:source:1.31','Nīlakaṇṭha','gita.1.31','sa','commentary','।।1.31।।निमित्तानि लोकक्षयकराणि भूमिकम्पादीनि।'),
('nilakantha-sc:source:1.32','Nīlakaṇṭha','gita.1.32','sa','commentary','।। 1.32निमित्तानि लोकक्षयकराणि भूमिकम्पादीनि।'),
('nilakantha-sc:source:1.33','Nīlakaṇṭha','gita.1.33','sa','commentary','।। 1.33निमित्तानि लोकक्षयकराणि भूमिकम्पादीनि।'),
('nilakantha-sc:source:1.34','Nīlakaṇṭha','gita.1.34','sa','commentary','।।1.34।।स्याला इति स्यालशब्दो दन्त्यादिः।वि जामातुरुत वाघा स्यालात् इति मन्त्रवर्णात्।स्याल्लाजानावपतीति वा लाजा लाजतेः स्यं शूर्पं स्यतेः इति यास्कः।'),
('nilakantha-sc:source:1.35','Nīlakaṇṭha','gita.1.35','sa','commentary','।।1.35।।हन्तुं इच्छापि मम न भवति किमुत हन्तृत्वमित्यर्थः। महीकृते पृथिव्यर्थे।'),
('nilakantha-sc:source:1.36','Nīlakaṇṭha','gita.1.36','sa','commentary','।।1.36।।आततायिनःअग्निदो गरदश्चैव शस्त्रपाणिर्धनापहः। क्षेत्रदारहरश्चैव षडेते ह्याततायिनः। आततायिनमायान्तं हन्यादेवाविचारयन्। नाततायिवधे दोषो हन्तुर्भवति कश्चन। इति। यद्यप्येवं तथापि एतान्हत्वा अस्मान्पापमेव आश्रयेत्। आततायिवधो हि अर्थशास्त्रविहितः।न हिंस्यात्सर्वा भूतानि इति तु धर्मशास्त्रम्। तच्च पूर्वस्मात्प्रबलम्। यथोक्तं याज्ञवल्क्येनस्मृत्योर्विरोधे न्यायस्तु बलवान्व्यवहारतः। अर्थशास्त्रात्तु बलवद्धर्मशास्त्रमिति स्थितिः। इति। अस्मान्हत्वा एतान् आततायिनः पापमेवाश्रयेदित्यपरा योजना। तथा च एत एवास्मद्वधेन नश्यन्तु न तु वयमेतेषां वधेन नङ्क्ष्याम इति भावः।'),
('nilakantha-sc:source:1.37','Nīlakaṇṭha','gita.1.37','sa','commentary','।। 1.37आततायिनःअग्निदो गरदश्चैव शस्त्रपाणिर्धनापहः। क्षेत्रदारहरश्चैव षडेते ह्याततायिनः। आततायिनमायान्तं हन्यादेवाविचारयन्। नाततायिवधे दोषो हन्तुर्भवति कश्चन। इति। यद्यप्येवं तथापि एतान्हत्वा अस्मान्पापमेव आश्रयेत्। आततायिवधो हि अर्थशास्त्रविहितः।न हिंस्यात्सर्वा भूतानि इति तु धर्मशास्त्रम्। तच्च पूर्वस्मात्प्रबलम्। यथोक्तं याज्ञवल्क्येनस्मृत्योर्विरोधे न्यायस्तु बलवान्व्यवहारतः। अर्थशास्त्रात्तु बलवद्धर्मशास्त्रमिति स्थितिः। इति। अस्मान्हत्वा एतान् आततायिनः पापमेवाश्रयेदित्यपरा योजना। तथा च एत एवास्मद्वधेन नश्यन्तु न तु वयमेतेषां वधेन नङ्क्ष्याम इति भावः।'),
('nilakantha-sc:source:1.38','Nīlakaṇṭha','gita.1.38','sa','commentary','।।1.38।।ननुआहूतो न निवर्तेत द्यूतादपि रणादपि इतिविजितं क्षत्रियस्य इति च युद्धादनिवृत्तिर्हिंसया च वृत्तिः क्षत्रियस्येष्टा तत्कथं युद्धान्निवृत्तिमिच्छसीत्याशङ्क्याह कथमिति। सा हि लोभमूलिका स्मृतिः कुलक्षयदोषविधिना बाध्यते। यथाऔदुम्बरीं स्पृष्ट्वोद्गायेत् इति स्पर्शनविधिना विरुद्धा सतीऔदुम्बरी सर्वा वेष्टयितव्या इति सर्ववेष्टनस्मृतिर्बाध्यते लोभमूलकत्वात्तद्वत्। नहि विधिमात्राद्यत्किंचित्कर्तव्यम्। श्येनादीनामधर्मरूपाणामप्यवश्यानुष्ठेयत्वापत्तेः। तस्माद्यत्फलतो न दुष्यति तदेव विहितं धर्मरूपमनुष्ठेयम्। यथोक्तम्फलतोऽपि च यत्कर्म नानर्थेनानुबध्यते। केवलं प्रीतिहेतुत्वात्तद्धर्म इति कथ्यते। इति। श्येनादिवत्पापानुबन्धित्वात् युद्धं त्याज्यमेवेत्यर्थः।'),
('nilakantha-sc:source:1.39','Nīlakaṇṭha','gita.1.39','sa','commentary','।।1.39।।प्रणश्यन्ति अनुष्ठातृ़णां वृद्धानामभावात्। अवशिष्टं बालादिरूपं वंशं धर्मलोपादधर्मोऽभिभवति।'),
('nilakantha-sc:source:1.40','Nīlakaṇṭha','gita.1.40','sa','commentary','।।1.40।।दुष्टासु पुत्रार्थं वर्णान्तरमुपासीनासु।'),
('nilakantha-sc:source:1.41','Nīlakaṇṭha','gita.1.41','sa','commentary','।।1.41।।कथं तर्हि जामदग्न्येन रामेण क्षत्रियेषु हतेषु तत्स्त्रियः पुनःपुनर्ब्राह्मणेभ्यः पुत्रान् जनयामासुरित्युपाख्यायते कथं वा धृतराष्ट्रादीनामसंकरजत्वमित्याशङ्क्याह पतन्तीति। हि शब्दो वैदिकीं प्रसिद्धिं द्योतयति। सा हिन शेषो अग्ने अन्यजातमस्ति इति श्रुतिः। अन्यस्माज्जातं शेषोऽपत्यं नास्तीति तदर्थः।अन्योदर्यो मनसापि न मन्तव्यो ममायं पुत्रः इति यास्कवचनाच्च।ये यजामहे इति शास्त्रात् ये वयं स्मस्ते वयं यजामह इत्यर्थकाद्दृश्यमानस्य पित्रादेः संशयग्रस्तत्वादयं मम पितैवेति निश्चयस्य दुःसाध्यत्वात्। मन्त्रश्चयोऽहमस्मि स सन्यजे। ब्राह्मणेऽर्थवादश्चनचैतद्विद्मो ब्राह्मणाः स्मो वयमब्राह्मणा वा इति। तस्माद्बीजपतेरेव पिण्डादिप्राप्तिर्नतु क्षेत्रपतेरिति लुप्तपिण्डोदकक्रियत्वादवश्यं पितृ़णां पातो भवति। क्षेत्रजपुत्रस्मृतिस्तु इह लोके वंशस्थापनमात्रपरा नतु तेन क्षेत्रपतेः कश्चिदामुष्मिक उपकारोऽस्ति। उदाहृतश्रुतिविरोधात्। अयं च संकरोऽस्माभिः स्वयं कृतश्चेदवश्यमस्मान्बाधिष्यत एवेति भावः।'),
('nilakantha-sc:source:1.42','Nīlakaṇṭha','gita.1.42','sa','commentary','।।1.42।।एतदेव विवृणोति द्वाभ्याम् दोषैरिति।'),
('nilakantha-sc:source:1.43','Nīlakaṇṭha','gita.1.43','sa','commentary','।। 1.43एतदेव विवृणोति द्वाभ्याम् दोषैरिति।'),
('nilakantha-sc:source:1.44','Nīlakaṇṭha','gita.1.44','sa','commentary','।। 1.44एतदेव विवृणोति द्वाभ्याम् दोषैरिति।'),
('nilakantha-sc:source:1.45','Nīlakaṇṭha','gita.1.45','sa','commentary','।। 1.45एतदेव विवृणोति द्वाभ्याम् दोषैरिति।'),
('nilakantha-sc:source:1.46','Nīlakaṇṭha','gita.1.46','sa','commentary','।।1.46।।संख्ये संग्रामे।।।इति श्रीनैलकण्ठीये भगवद्गीतासु प्रथमोऽध्यायः।।1।।'),
('nilakantha-sc:source:1.47','Nīlakaṇṭha','gita.1.47','sa','commentary','।।1.47।।अर्जुन उवाच संजय उवाच स तु पार्थो महामनाः परमकारुणिको दीर्घबन्धुः परमधार्मिकः सभ्रातृको भवद्भिः अतिघोरैः मारणैः जतुगृहादिभिः असकृद् वञ्चितः अपि परमपुरुषसहायः अपि हनिष्यमाणान् भवदीयान् विलोक्य बन्धुस्नेहेन परमया च कृपया धर्माधर्मभयेन च अतिमात्रस्विन्नसर्वगात्रः सर्वथा अहं न योत्स्यामि इति उक्त्वा बन्धुविश्लेषजनितशोकसंविग्नमानसः सशरं चापं विसृज्य रथोपस्थे उपाविशत्।
INSERT INTO commentary_fts (unit_id,author,canonical_ref,language,content_type,content) VALUES
('nilakantha-sc:source:2.14','Nīlakaṇṭha','gita.2.14','sa','commentary','।।2.14।।ननु आत्मनो लिङ्गशरीरादन्यत्वेऽप्यहं दुःखीत्याद्यनुभवाद्दुःखादिधर्माश्रयत्वं दुर्वारम्। ततश्च भीष्मादिबन्धुवर्गनाशे सति दुःखसंबन्धो भवत्येवेत्याशङ्क्याह मात्रास्पर्शा इति। मीयन्ते विषया आभिस्ता मात्रा इन्द्रियवृत्तयः। यद्वा दश प्रज्ञामात्राः वागादयः दश भूतमात्राः नामादयः कौषीतकिप्रसिद्धा इन्द्रियविषयरूपा ग्राह्याः। तासां स्पर्शाः परस्परं विषयविषयिभावेन संबन्धा इति व्याख्येयम्। यद्वा मात्रा प्रमात्रा सह स्पर्शाः विषयेन्द्रियसंबन्धाः। स्पर्शशब्दस्य तद्वाचित्वंस्पर्शान्कृत्वा बहिर्बाह्यान् इत्यत्र दृष्टम्। तत्र स्पर्शपदेन तद्वतोर्विषयेन्द्रिययोरपि लाभः। तेन प्रमातुः प्रमाणद्वारा प्रमेयेण सह संबन्धाः सर्वे शीतोष्णादिवदागमापायिन उत्पत्तिविनाशशीला अतएवानित्याश्च तद्वदेव सुखदुःखदाश्च। अतस्तान् तितिक्षस्व सहस्व। हे कौन्तेय भारतेत्युत्तमवंश्यत्वेन धीरत्वमस्य सूचयति। प्रमातृत्वादिरनर्थो हि सुप्तिसमाधिग्रहावेशादिष्वभावाज्जाग्रत्स्वप्नादौ भावाच्च कादाचित्कतया आत्मनि प्रतीयमानोऽपि रज्जूरगादिवन्मिथ्याभूतः सन्न तद्धर्मत्वं भजते। यद्धि यत्राभेदेन कदाचिद्भाति तत्तत्राध्यस्तं रज्ज्वामिव सर्पः। प्रमात्रादिश्च प्रतीचि प्रत्यगभेदेन कदाचिद्भाति अतो मिथ्येति निश्चितम्। तेन प्रतीचि प्रमातृसंबन्ध एव नास्ति। सत्यमिथ्यावस्तुनोर्वास्तवसंबन्धायोगात्। प्रमातृधर्माणां दुःखादीनां तु प्रतीचि संबन्धो दूरापेत एव। कथं तर्ह्यात्मनि दुःखित्वप्रत्ययः। तत्तदुपाधितादात्म्याध्यासादिति ब्रूमः। अतएव जाग्रति दृष्टं दुःखं स्वप्ने नानुवर्तते स्वप्नदृष्टं वा जाग्रति न दृश्यते। तथा च श्रुतिःस यत्तत्र पश्यति पुण्यं च पापं चानन्वागतस्तेन भवत्यसङ्गो ह्ययं पुरुषः इति।कामः संकल्पो विचिकित्सा इत्यादिश्रुतिरेतत्सर्वं मन एवेति अभेदनिर्देशात्मकामादिसर्वविकारोपादानत्वं मनस एवाह। तस्मात्स्वप्न इवात्मनि दुःखित्वप्रतीतिर्भ्रान्तिरेवेतीष्टवियोगजनितां तां तितिक्षस्वेति भावः।'),
('nilakantha-sc:source:2.15','Nīlakaṇṭha','gita.2.15','sa','commentary','।।2.15।।तितिक्षाफलं प्रत्यक्षमेवेत्याह यं हीति। एते मात्रास्पर्शाः प्राग्व्याख्यातरीत्या त्रिविधा अपि यं जाग्रति स्वप्नेऽसंप्रज्ञातसमाधौ वा न व्यथयन्ति स्वास्थ्यान्न प्रच्यावयन्ति। पुरुषं पूर्षु अष्टासु वसतीति पुरुषस्तम्। पुरश्चकर्मेन्द्रियाणि खलु पञ्च तथा पराणि ज्ञानेन्द्रियाणि मन आदि चतुष्टयं च। प्राणादिपञ्चकमथो वियदादिकं च कामश्च कर्म च तमः पुनरष्टमी पूः। इति प्रसिद्धाः। यद्वा स्थूलसूक्ष्मोपाधिमध्ये एव इतरासामन्तर्भावादत्र पूरिति तम एव ग्राह्यम्। तेन कारणोपाधेरप्यात्मनो विविक्तत्वं दर्शितम्। पुरुषर्षभेति त्वमप्येतदनुभवितुं योग्योऽसि सर्वपुरुषश्रेष्ठत्वादिति सूचयति। उपाधित्रयत्यागादेव समे दुःखसुखे यस्य तम्। नहि समाधिस्थस्य सुखाय दुःखाय वा शीतोष्णस्पर्शौ भवत इति युक्तमस्य समदुःखसुखत्वम्। धीरं ध्यायिनं योगिनं न व्यथयन्ति। सोऽमृतत्वाय मोक्षाय कल्पते योग्यो भवति।'),
('nilakantha-sc:source:2.16','Nīlakaṇṭha','gita.2.16','sa','commentary','।।2.16।।ननु सुप्तिसमाध्यादौ त्यक्तोपाधेरात्मनः समदुःखसुखत्वेऽपि सोपाधिकदशायां तप्तायःपिण्डस्य दग्धृत्वमिव तस्य दुःखित्वं दुर्वारम्। उपाधिश्च मूलप्रकृतेर्व्यापिकाया मात्रारूप इति तत्सत्त्वे तु न निर्मूलोच्छेदमर्हत्यतः सोऽमृतत्वाय कल्पत इत्यनुपपन्नमित्याशङ्क्याह नासत इति। प्रमात्रादेरागमापायित्वेन कादाचित्कत्वात् रज्जूरगादिवत् असतः भावः सत्ता कालत्रयेऽपि नास्ति। अयमर्थः प्रमात्रादिर्मूलाज्ञानेन चिदात्मनि कल्पितः। मूलाज्ञानस्य चात्मज्ञानेन निवृत्तौ कारणाभावान्न पुनः प्रमात्राद्युद्भवोऽस्तीति निष्प्रत्यूहममृतत्वं ज्ञानात्सिध्यतीति। नन्वप्रतीतिमात्रात्प्रमात्रादेर्मिथ्यात्वोपगमे आत्मनोऽपि सुप्त्यादावप्रतीयमानत्वाविशेषान्मिथ्यात्वमस्तु। उभयोर्वा सत्यत्वमस्तु इत्याशङ्क्याह नाभावो विद्यते सत इति। सद्वस्तुनः अभावोऽसत्त्वं कदाचिदपि न विद्यते। सुषुप्त्यादावपि अनुभूतयोः सुखाज्ञानयोः सुखमहमस्वाप्सं न किञ्चिदवेदिषमिति उत्थाने परामर्शदर्शनात्। तदनुभवमन्तरेण तयोः परमार्शासंभवात्। अतः सतोऽसत्त्वं नास्ति। श्रुतिरपि सुप्तिकैवल्ययोः प्रमात्राद्यभावं दृशो नित्यत्वं चाह।यद्वै तन्न पश्यति पश्यन्वै तन्न पश्यति न हि द्रष्टुर्दृष्टेर्विपरिलोपो विद्यतेऽविनाशित्वान्नतु तद्वितीयमस्ति ततोऽन्यद्विभक्तं यत्पश्येत् इति। यदि प्रमात्रादिः सत्यस्तर्हि सतोऽर्थस्य सुषुप्त्यादावदर्शनं सान्निध्याभावाद्वा द्रष्टुर्दृग्लोपाद्वा वक्तव्यम्। नाद्यः। आत्मनि दृष्टनष्टस्वभावस्यान्यत्र सद्भावकल्पनायोगात्। नान्त्यः। उदाहृतया श्रुत्यैव तन्निषेधात्। तस्मादुभयोरपि सत्यत्वेन मिथ्यात्वेन वा साम्यं दुर्वचम्। ननु सत आकाशादेः क्वचिदपि देशे काले चाभावो यद्यपि नास्ति तथापि सत एव परमाणोर्देशान्तरेऽभावोऽस्ति प्रागसतोऽपि घटादेर्भावश्च दृष्टः तत्कथमुच्यतेनासतो विद्यते भावो नाभावो विद्यते सत इत्याशङ्क्य विद्वदनुभवेन निरस्यति उभयोरपीति। अन्तो याथात्म्यम्। यथा स्वप्ने नभःकुम्भरज्जूरगादयो नित्यत्वानित्यत्वसत्यत्वासत्यत्वादिधर्मोपेततया निश्चिता अपि प्रबोधेन बाध्यन्ते तद्वज्जाग्रद्दृष्टा अपि ते तत्त्वज्ञानेन बाध्यन्ते। ननु जाग्रद्वासनावशात् स्वप्नगतनभ आदौ नित्यत्वादिनिश्चयो भ्रम इति चेत् अनादिकालप्रवृत्तप्राग्भवीयसंस्कारवशात् जाग्रन्नभ आदावपि स भ्रम एवेति तुल्यम्। ननु स्वरूपसदेव रजतादिकं शुक्त्यादावध्यस्यते नत्वसत् शशशृङ्गादिकम्। गगनादिकं तु त्वद्रीत्या स्वरूपेण असदपि कथमात्मन्यध्यस्यत इति चेन्न। अध्यासे हि पूर्वानुभवमात्रमपेक्षते नत्वनुभूतस्य स्वरूपेण सत्त्वमपि। दर्पणप्रतिबिम्बिते गगनेऽपि नैल्याध्यासदर्शनात्। न च गगने नैल्यं स्वरूपेण सत्यमस्ति अथचान्यत्राध्यस्यते। तस्मात् भ्रमपरम्परायाः संभवात्। स्वप्नद्रष्टृभिरिवास्माभिरदृष्टमपि सदसतोर्याथात्म्यं प्रबुद्धैर्द्रष्टुं शक्यमेव। तथा च श्रुतयःनेह नानास्ति किंचनअस्तीत्येवोपलब्धव्यःअतोऽन्यदार्तम् इत्याद्याः अनात्मनोऽसत्त्वं आत्मनश्च सत्त्वं प्रतिपादयन्ति। एवं सतो ज्ञानेनासतो बाधात्कैवल्यं सिध्यतीति भावः।'),
('nilakantha-sc:source:2.17','Nīlakaṇṭha','gita.2.17','sa','commentary','।।2.17।।यस्याभावो नास्ति तस्य सतः सत्त्वे किं मानमित्याशङ्क्याह अविनाशीति। तच्छब्देन प्रकृतं सत् परामृश्यते। येन सता इदं सर्वं वियदादि ततं व्याप्तम्। घटः सन्पटः सन्निति सर्वस्य सदभेदानुभवात्। यथा घटो मृत् शरावो मृदिति घटादीनां मृदभेदानुभवान्मृदुपादानकत्वं तद्वत्सर्वस्यापि सदुपादानकत्वं बोध्यम्। ननु मृद्वत्सदपि किं विकारवद्भवतीत्याशङ्क्याह अविनाशीति। तत् सत् अविनाशि विद्धि। अयमर्थः पूर्वावस्थापरित्यागोऽत्र विनाशः। मृद्धि पिण्डाकारतां त्यक्त्वा घटीभवति अतः सा विनाशशीला। विकारधाराश्रयत्वात्। ब्रह्म तु न तथा किं तर्हि रज्जुवत्स्वयमविनश्यदेव कार्याकारं भवति। स्वकीये च सत्तास्फुरणे कार्येऽर्पयति। अतोऽविनाशि। तथा च श्रुतयःअजायमानो बहुधा विजायतेजात एव न जायते को न्वेनं जनयेत्पुनः। अजायमानः जन्माख्यं विकारमलभमानोऽपि विजायते वियदादिरूपेणाविर्भवति। तथा लोकदृष्ट्या जातो घटादिः परमार्थदृष्ट्या न जायते। परिणाम्युपादानस्याभावात्। मृदादेस्तु स्वाप्नमृदादिवत्तुच्छत्वात्। अत एनं घटादिं को नु जनयेन्न कोऽपि। कुतस्तर्हि भासत इति चेत् रज्जूरगादिवदिति दत्तोत्तरमेतत्। तथाप्राणा वै सत्यं तेषामेष सत्यम्तस्य भासा सर्वमिदं विभाति इति सतः सत्यत्वेन प्राणोपलक्षितस्य प्रपञ्चस्य सत्यत्वं सतो भानमेव प्रपञ्चस्य भानमिति। तथा च प्रपञ्चगते सत्तास्फूर्ति सतः सत्त्वे प्रमाणमित्यर्थः। श्रुतिश्चअन्नेन सोम्य शुङ्गेनापोमूलमन्विच्छ अद्भिः सोम्य शुङ्गेन तेजोमूलमन्विच्छ तेजसा सोम्य शुङ्गेन सन्मूलमन्विच्छ सन्मूलाः सोम्येमाः प्रजाः सदायतनाः सत्प्रतिष्ठाः इति सतो जगदुपादानत्वं कार्यलिङ्गेन द्रढयति। सतोऽविनाशित्वं च विनाशहेत्वभावादित्याह विनाशमिति। न व्येति नापक्षीयत इत्यव्ययम्। एतेन सर्वविकारशून्यस्य विनाशो नास्तीत्यर्थः। अपक्षयो हि जन्मादिविकारवत् एव भवतीति स एवात्र सर्वविकारोपलक्षणतया बोध्यः। न कश्चिदित्यनेन तदन्यस्य विनाशहेतोरभावो दर्शितः।द्वितीयाद्वै भयं भवति इति श्रुतेः।'),
('nilakantha-sc:source:2.18','Nīlakaṇṭha','gita.2.18','sa','commentary','।।2.18।।एवं सत आत्मनो नित्यत्वं असतो देहादेरनित्यत्वं चोक्तमुपसंहरन् एनं युद्धाभिमुखं करोति अन्तवन्त इति। यद्यपिनासतो विद्यते भावः इति असतां देहानां कालत्रयेऽपि सत्त्वं नास्तीति परमार्थदृष्ट्या उक्तं तथापि तां दृष्टिमप्रतिपद्यमानस्य नरकादिभयमनुरुध्यमानस्य व्यवहाराभिप्रायेण नित्यानित्यविभागमभिप्रेत्य देहानामन्तवत्त्वमुच्यत इति न दोषः नित्यत्वं कालापरिच्छेद्यत्वं तच्च व्यवहारे नभसोऽप्यस्तीत्यत उक्तं अनाशिन इति। नाशः अदर्शनं तद्वान् हि आकाशःनभ आत्मनि लीयते इति स्मृतेः। अयं तु न तथेत्यनाशी। सर्वदैव प्रकाशमान इत्यर्थः। एतदपि न घटादिवद्दृश्यत्वेनेत्याह अप्रमेयस्येति। तथा च श्रुतिरात्मनोऽप्रमेयत्वमाहएतदप्रमयं ध्रुवम् इति। अप्रमयमित्यस्याप्रमेयमित्यर्थः। एतच्चात्मनि प्रमाणाप्रसराज्ज्ञेयम्। तथा च श्रुतिःयेनेदं सर्वं विजानाति तं केन विजानीयाद्विज्ञातारमरे केन विजानीयात् इति। प्रसिद्धिस्त्वस्य प्रत्यगात्मत्वादेव।यत्साक्षादपरोक्षाद्ब्रह्म य आत्मा सर्वान्तरः इति श्रुतेः। उक्तं चप्रमाणमप्रमाणं च प्रमाभासस्तथैव च। यत्प्रसादात्प्रसिध्यन्ति तदसंभावना कुतः। इति। तस्माद्युध्यस्व भारत। भीष्मादिदेहानां मिथ्यात्वादनित्यत्वाच्च स्वयमेव नष्टप्रायतया हननान्निवृत्त्या त्वया स्वधर्मो न नाशनीय इति भावः।'),
('nilakantha-sc:source:2.19','Nīlakaṇṭha','gita.2.19','sa','commentary','।।2.19।।ननुनासतो विद्यते भावः इति न्यायेनासतो मात्रादेर्मिथ्यात्वेन निःस्वरूपत्वात्कर्तृत्वं न संभवति। अतः सत एव कर्तृत्वं बन्धमोक्षभाक्त्वं च वाच्यम्। अन्यथाऽन्तःकरणे बन्ध आत्मनश्च मोक्ष इति तयोर्वैयधिकरण्यं स्यात्। तथा येन सर्वमिदं ततमिति सतो देहाद्युपादानत्वं चोक्तम्। तथा च हननक्रियां प्रत्येकस्यैव कर्तृत्वं कर्मत्वं चापतति तच्च विरुद्धम्। स्वात्मनि स्वव्यापारायोगात्। नहि वह्निर्वह्निं दहतीति युक्तमित्याशङ्क्याह य एनमिति। यश्च तार्किकादिरेनमात्मानं हन्तारं हननक्रियायाः कर्तारं मन्यते यश्च चार्वाकादिरेनं हतं हननक्रियायाः कर्मीभूतं मन्यते तावुभावपि न जानीतः। आत्मतत्त्वमिति शेषः। यस्मान्नायं हन्ति न हन्यते। नहि यः कर्ता स आत्मा नापि देह आत्मा तयोः प्रागेवानात्मत्वावधारणात्। अयं भावः यथायःपिण्डे वह्निसंबन्धादेव दग्धृत्वं न तु स्वतः एवं मात्राद्युदयसमनियतं कर्तृत्वं मात्रादिधर्म एव नात्मनः। आत्मनि तु कर्तृत्वप्रतीतिर्मात्रादिसंबन्धादेव। अतो मात्रादिविशिष्टस्यैव बन्धो न केवलस्य। मोक्षश्च मात्रादिवियोग एवेति न बन्धमोक्षयोर्वैयधिकरण्यम्। न च मात्रादेर्निःस्वरूपत्वमस्ति। सत्त्वासत्त्वाभ्यामनिर्वचनीयस्य व्यवहारयोग्यस्य ब्रह्मज्ञानैकबाध्यस्य स्वप्नमायागन्धर्वनगरादितुल्यस्य तत्स्वरूपस्याभ्युपगमात्। तस्मान्न कर्तृत्वमात्मधर्मः। यथोक्तम्आत्मा कर्त्रादिरूपश्चेन्मा काङ्क्षीस्तर्हि मुक्तताम्। नहि स्वभावो भावानां व्यावर्तेतौष्ण्यवद्रवेः। इति। किञ्च कर्तृत्वं रागद्वेषादिविकारवत् एव संभवति तद्वांश्च दुःखीत्यात्मनोऽनुभूयमानं साक्षित्वं बाध्येत। यथोक्तम्नर्ते स्याद्विक्रियां दुःखी साक्षिता का विकारिणः। धीविक्रियासहस्राणां साक्ष्यतोऽहमविक्रियः। इति। न च सतो देहाद्युपादानत्वेन हननक्रियाकर्मत्वं संभवति। विवर्तवादाभ्युपगमात्। नह्यध्यस्तस्य धर्मैरधिष्ठाने विकारो दृश्यते। यथोक्तं भाष्येयत्र यदध्यस्तं सत्तत्कृतेन गुणेन दोषेण वाऽणुमात्रेणापि न संबध्यते इति। विवृतं चैतद्वृद्धैःनहि भूमिरूषरवती मृगतृट्जलवाहिनीं सरितमुद्वहति। मृगवारिपूरपरिपूरवती न नदी तथोषरभुवं स्पृशति। इति। एतेन कर्तृत्वकर्मत्वयोरनात्मधर्मत्वादनात्मनश्चानेकरूपत्वादेकत्रात्मनि तदुभयविरोधोद्भावनमपि निरस्तं वेदितव्यम्। एवं चार्वाकतार्किकाभिमतौ देहात्मकर्त्रात्मवादौ।हन्ता चेन्मन्यते हन्तुं हतश्चेन्मन्यते हतम्। उभौ तौ न विजानीतो नायं हन्ति च हन्यते। इति काठकोक्तेन मन्त्रेण पूर्वार्धे पाठभेदात्पठितेन परिहृतौ वेदितव्यौ।'),
('nilakantha-sc:source:2.20','Nīlakaṇṭha','gita.2.20','sa','commentary','।।2.20।।नायं हन्ति न हन्यत इत्युक्तं तत्र न हन्यत इत्येतदुपपादयति तत्रस्थेनैव द्वितीयेन मन्त्रेण न जायत इति। अयं आत्मा कदाचित् न जायते अभिनवो नोत्पद्यते। न वा म्रियते निरन्वयो न नश्यति। तार्किकाभिमतघटवत्। तत्र क्रमेण हेतुद्वयम् अजो नित्य इति। अजत्वान्न जायते। नित्यत्वाच्च न वा म्रियत इत्यर्थः। अस्तु तर्हि क्षणिकविज्ञानधारारूपः। तस्याविज्ञानवादिभिरजत्वनित्यत्वाभ्युपगमादित्याशङ्क्याह भूत्वा भविता वा न भूय इति। अयमित्यनुवर्तते। अयं भूत्वा भूयो भविता न। भूयोऽसकृत् भूत्वा भवितेति भवनक्रियाद्वयस्य क्त्वाप्रत्ययोक्तं समानकर्तृत्वं धारैक्याभिप्रायेण। भूत्वैव भविता न तु भूत्वा स्थित्वा विनश्यति। तार्किकाणां हि विज्ञानमुत्पत्तिस्थितिनाशक्षणव्यापित्वात्ित्रक्षणावस्थायि। विज्ञानवादिना तु पूर्वस्य नाशक्षण एवोत्तरस्योत्पत्तिक्षणः स एव तस्य स्थितिक्षणश्चेति क्षणिकत्वाद्विज्ञानानां भवनक्रियाद्वयस्याव्यवधानाद्भूत्वा भवितेत्युक्तम्। तादृशोऽप्ययं न यतः शाश्वतः शश्वदेकरूपः। योऽहं बाल्ये पितरावन्वभूवं सोऽहं स्थाविरे प्रणप्तृ़ननुभवामीति बाल्यस्थाविरयोरात्मैक्यप्रत्यभिज्ञानात्। न च सादृश्यात्प्रत्यभिज्ञानम्। सादृश्यग्रहीतुः स्थिरस्याभावात्। यद्वा जन्ममरणहीनोऽपि धर्मान्तरविशिष्टः पूर्वं भूत्वा पुनर्धर्मान्तरविशिष्टो भवति इत्यपि न। भूत्वैव भविता नत्वभूत्वेति योजना। अर्हता हि शरीरपरिमाणमात्मानमभ्युपगच्छन्तो नित्यस्यैवात्मनः क्रमेण व्युत्क्रमेण वा मशकमनुजमतंगजशरीरप्राप्तौ परिमाणभेदं मन्यमाना भूतस्यैवात्मनो विशेषणीभूतपरिमाणभवनादौपचारिकं भवनमभ्युपगच्छन्ति तदपि न। शाश्वतत्वादेव उपचयापचयवतो मध्यमपरिमाणस्य वस्तुनो नित्यत्वायोगात्। अनेनैव सुखदुःखादिधर्मान्तरोत्पत्त्यात्मनो भाक्तं भूत्वा भवनं प्रत्याख्येयम्। नहि दुःखादिधर्मिणः स्वनाशमन्तरेणात्यन्तिकदुःखोच्छेदः संभवति। घटादौ यावद्रूपनाशादर्शनात्। नन्वजत्वं नित्यत्वं शाश्वत्वं चाकाशेऽप्यस्ति अत आह पुराण इति। पुरा वियदादिसृष्टेः प्रागपि नव एव। एतेन अपक्षयादिधर्मराहित्यान्मुख्यमजत्वादिकं आत्मन एव वियदादेस्त्वमुख्यं तदिति दर्शितम्। अतएव शरीरे हन्यमाने न हन्यते। भाष्ये तु वाशब्दश्चार्थे। न जायते म्रियते चेत्यर्थः। तत्रोपपत्तिः अयं न भूत्वा अनुत्पद्य न भविता घटादिवदतो न जायते। अथवा नञः पूर्वान्वयित्वं न जायते न वा म्रियत इति। यतो भूत्वा अभविता घटवद्विनाशी न अतो न म्रियत इति। शाश्वतः पुराण इत्येताभ्यामुपचयापचयौ निषिध्येते इति न हन्यते न विपरिणम्यत इति च व्याख्यातम्। केचिदेवमाहुः। न जायते म्रियत इति प्रतिज्ञा। कदाचिदित्यादिना तस्या उपपादनम्। अज इत्यादिरुपसंहार इति।'),
('nilakantha-sc:source:2.21','Nīlakaṇṭha','gita.2.21','sa','commentary','।।2.21।।नायं हन्तीत्येतदुपपादयति वेदेति। विनष्टुं अदर्शनं गन्तुं शीलमस्येति विनाशि रज्जूरगतुल्यमुपाधित्रयं स्थूलसूक्ष्मकारणशरीराख्यं ततोऽन्यं अविनाशिनम्। अतएव नित्यं नाशहीनम्। तत्र हेतुः अजम्। जन्मवान् हि अनित्यः अयं तु अजत्वान्नित्यश्चेत्यर्थः। ननु विनाशिनः स्वकार्यापेक्षया नित्यत्वं च सांख्याभिमते प्रधाने तार्किकाभिमते नभसि चास्त्यत उक्तं अव्ययमिति। न व्येति पूर्वावस्थां त्यजतीत्यव्ययमपरिणामि। प्रधानं तुचलं गुणवृत्तम् इति न्यायेन गुणसाम्यावस्थायामपि परिणममाणमेव सर्वदास्तीति तेषामभ्युपगमात्। आकाशस्यापितस्माद्वा एतस्मादात्मन आकाशः संभूतः इति उत्पत्तिश्रवणादजत्वाभावादेव नाव्ययत्वम्। तादृशं आत्मानं यो वेद अपरोक्षीकरोति स पुमान् कथं केन प्रकारेण कमन्यं घातयति हननक्रियायां प्रवर्तयति। कं वा हन्ति। न केनचित्प्रकारेण कमपि घातयति न वा हन्तीत्यर्थः। द्वैताभावात्। तथाहि श्रुतिर्विद्यावस्थायां सर्वकारकव्यापारं निषेधति।यत्र त्वस्य सर्वमात्मैवाभूत्तत्केन कं पश्येत् इत्यादि। अविद्यावस्थायामेव च सर्वकारकव्यवहारं दर्शयति।यत्र हि द्वैतमिव भवति तदितर इतरं पश्यति इत्यादि। एतेन सर्वकारकोपमर्दिन्या विद्यायाः सर्वकारकसापेक्षैः कर्मभिः सह समुच्चयो निरस्तः। परस्परविरुद्धस्वभावत्वेन शीतोष्णयोरिव द्वयोरेककार्यकारित्वस्य रथाश्वन्यायेनासंभवादित्यन्यत्र विस्तरः। मादृशानां ज्ञानिनां व्युत्थानकाले अविद्यालेशानुवृत्त्या घातयितृत्वादेः प्रसक्तावपि विद्यया तस्य बाधितत्वादागामिकर्मणामश्लेषाच्च न दोषः। तथा च वक्ष्यतेहत्वापि स इमाँल्लोकान्न हन्ति न निबध्यते इति।'),
('nilakantha-sc:source:2.22','Nīlakaṇṭha','gita.2.22','sa','commentary','।।2.22।।ननुब्राह्मणो यजेतजातपुत्रः कृष्णकेशोऽग्नीनादधीत इति आत्मानं वयोवर्णादिविशेषणवन्तमेवाधिकृत्य कर्मविधयः प्रवर्तन्ते तेन नीलादुत्पलमिव देहादन्य आत्मावधारयितुं न शक्यत इत्याशङ्क्याह वासांसीति। दण्डी प्रैषानन्वाहेति दण्डस्य विशेषणत्वेऽपि न प्रैषानुवक्तृस्वरूपान्तर्गतत्वम् एवं ब्राह्मणत्वादेरपि न स्वर्गकामस्वरूपान्तर्गतत्वमिति वस्त्रदेवदत्तयोरिव जडाजडयोर्देहात्मनोरत्यन्तविलक्षणत्वमस्तीति वस्त्रनाशेन देवदत्तनाशं मन्वानस्येव तव देहनाशादात्मनाशं मन्वानस्यात्यन्तमौढ्यं स्पष्टमिति भावः। स्पष्टार्थश्च श्लोकः।'),
('nilakantha-sc:source:2.23','Nīlakaṇṭha','gita.2.23','sa','commentary','।।2.23।।कीदृशोऽसौ देहीत्यत आह नैनमिति। एनं शस्त्राणि न छिन्दन्ति न द्वेधा कुर्वन्ति। अस्थूलत्वात्। तर्हि पार्थिवपरमाणुवत्पाकजरूपाद्याश्रयो भविष्यतीत्याशङ्क्याह नैनं दहति पावक इति। अनणुत्वात्। आपश्चैनं न क्लेदयन्ति अस्पर्शत्वात्। स्पर्शवद्धि द्रव्यमद्भिरार्द्रीकर्तव्यं न त्वस्पर्शम्। न शोषयति मारुतः अस्नेहत्वात्। एतेनअदीर्घमस्थूलमनणुअशब्दमस्पर्शमरूपमव्ययं तथाऽरसं नित्यमगन्धवच्च यत् इति श्रुतिप्रसिद्धानामदीर्घत्वाशब्दत्वादीनामपि संग्रहो ज्ञेयः।'),
('nilakantha-sc:source:2.24','Nīlakaṇṭha','gita.2.24','sa','commentary','।।2.24।।कुतो हेतोरस्य शस्त्रादीनि छेदादीन्न कुर्वन्तीत्याशङ्क्य तस्य छेदाद्ययोग्यत्वादित्याह अच्छेद्योऽयमिति। अत्राच्छेद्यत्वादौ पूर्वोक्तान्येवास्थूलत्वादीनि कारणानि ज्ञेयानि। एवमच्छेद्यत्वादिना स्थूलादीनभावरूपान् गुणानुक्त्वा भावरूपानपि गुणानाह नित्य इति। सर्वैर्विशेषणैरखण्डैकरसस्यैव वस्तुनो लक्ष्यत्वात् नित्यत्वादिभिरुत्पाद्यत्वादिकं निराक्रियते। यतो नित्यः अतो घटवदनुत्पाद्यः। यतः सर्वगतः अतो ग्रामवदप्राप्यः। यतः स्थाणुः पूर्वरूपापरित्यागेन स्थिरस्वभावः अतः क्षीरादिवदविकार्यः। अचलः यथा दर्पणः स्वतः स्वाच्छयादप्रच्युतोऽपि मलरूपेणावरणेन स्वाच्छयात्प्रच्याव्यते एवं स्वयं स्थाणुरपि अन्यसंयोगाच्चाञ्चल्यमश्नुवीत। स च दोषापकर्षणलक्षणं संस्कारमपेक्षते। अयं तु अचलत्वान्न तथा एवं च उत्पत्त्याप्तिविकृतिसंस्कृतिरूपं चतुर्विधं क्रियाफलमात्मनि न संभवतीत्युक्तम्। तत्र हेतुः सनातन इति। सना इत्यव्ययं नैरन्तर्ये। तच्च देशतः कालतो वस्तुतश्च परिच्छेदराहित्यम्। परमते परमाणूनां कालतः परिच्छेदाभावेऽपि देशतः परिच्छेदोऽस्ति। आकाशस्य तदुभयाभावेऽपि वस्तुतः परिच्छेदोऽस्ति। सोऽपि त्रिविधः सजातीयविजातीयस्वगतभेदरूपः। यथावृक्षस्य स्वगतो भेदः पत्रपुष्पफलादितः। वृक्षान्तरात्सजातीयो विजातीयः शिलादितः। ततश्च सना नैरन्तर्येण त्रिविधपरिच्छेदराहित्येन भवति अस्तीति सनातनोऽखण्डैकरसो यस्मात्तस्मात् नोत्पत्त्याद्याश्रय इत्यर्थः।'),
('nilakantha-sc:source:2.25','Nīlakaṇṭha','gita.2.25','sa','commentary','।।2.25।।एवं ज्ञेयं वस्तूक्तं तच्च तत्राध्यस्तदेहत्रयनिरासेनापरोक्षीकर्तव्यमित्याह अव्यक्तोऽयमिति। व्यक्तं स्थूलशरीरं प्रत्यक्षगम्यं तदन्योयं प्रत्यगात्मा। तथा अचिन्त्योऽयं चिन्त्यं चिन्तायोग्यं रूपादि प्रकाशकार्येणानुमेयं चक्षुरादिसमुदायात्मकं लिङ्गशरीरं अप्रत्यक्षं ततोऽप्यन्योऽयम्। तथा अविकार्योऽयं विकारं स्थूलसूक्ष्मकार्यभावेनावस्थानमर्हतीति विकार्यं त्रिगुणात्मकं मूलाज्ञानं कारणशरीरं सुप्तोत्थितस्य न किंचिदवेदिषमिति परामर्शदर्शनादहं न जानामीत्यनुभवाच्च साक्ष्येकगम्यं ततोऽप्यन्योऽयम्। उच्यते व्यक्तादिनिषेधमुखेन नतु शृङ्गग्राहिकयाऽयमेवंविध इति विधिमुखेनोच्यते। यस्मादेवमयमुच्यते तस्मादेनं विदित्वा नानुशोचितुमर्हसि।तरति शोकमात्मवित् इति श्रुतेरात्मविद् भूत्वा बन्धुवियोगजं शोकं मा कार्षीरित्यर्थः। उक्तं चात्मनोऽवस्थात्रयातीतत्वम्स्वप्ननिद्रायुतावाद्यौ प्राज्ञस्त्वस्वप्ननिद्रया। न निद्रां नैव च स्वप्नं तुर्ये पश्यन्ति निश्चिताः। इति।'),
('nilakantha-sc:source:2.26','Nīlakaṇṭha','gita.2.26','sa','commentary','।।2.26।।एवं तत्त्वदृष्ट्या शोको नोचित इत्युक्तं इदानीं प्राकृतजनदृष्ट्यापि शोको नोचित इत्याह अथचेति। नित्यं नियमेन जातं नित्यजातमिति चार्वाकपक्षः। नित्यं सर्वदा जातमिति क्षणिकविज्ञानवादिपक्षः। नित्यश्चासौ अपूर्वदेहेन्द्रियसंबन्धाज्जातश्चेति तार्किकादिपक्षः। एवं नित्यं वा मन्यसे मृतमित्यपि योज्यम्। पक्षत्रयेऽपि शोको न युक्तः। महाबाहो इति युद्धार्थमुत्साहयति।'),
('nilakantha-sc:source:2.27','Nīlakaṇṭha','gita.2.27','sa','commentary','।।2.27।।शोचितुं नार्हसीत्युक्तं तत्र हेतुमाह जातस्येति। ध्रुवोऽपरिहार्यः मृत्युर्मरणम्। अपरिहार्ये अर्थे मरणाख्ये त्वदुद्योगं विनापि अवश्यंभाविनि विषये न त्वं शोचितुमर्हसि। वक्ष्यति चमयैवैते निहताः पूर्वमेव इति।'),
('nilakantha-sc:source:2.28','Nīlakaṇṭha','gita.2.28','sa','commentary','।।2.28।।अस्त्वात्मनोऽशोच्यत्वं तथापि इष्टदेहविनाशजः शोको भवत्येवेत्याशङ्क्य सकारणस्य देहादेर्मिथ्यात्वं साधयति अव्यक्तादीनीति। भूतानि वियदादीनि तद्विकारभूतानि जरायुजादीनि च। न व्यक्तमव्यक्तमज्ञानं आदिर्येषां तथाविधानि। व्यक्तः स्पष्टः मध्यः उत्पत्तिमारभ्य मरणात्प्रागवस्था येषाम्। अव्यक्ते एव निधनं लयो येषामिति। अयमर्थः रज्जूरगादिकारणमज्ञानं न रज्जुवत् उरगवद्वा व्यक्तमस्ति। परीक्ष्यमाणं च न दृष्टिपथमवतरति। अतस्तदव्यक्तम्। तत उत्पन्नः सर्पस्तत्रैव लीयते न रज्ज्वाम्। एवं आत्मनि कल्पितानां भूतानां आदिरन्तश्चाव्यक्तमेव। तेनआदावन्ते च यन्नास्ति वर्तमानेऽपि तत्तथा इति न्यायेन मध्ये भासमानान्यपि तानि रज्जुरगवत् असन्त्येव। एवंविधे तत्र तस्मिन्विषये का परिदेवना को वा विलापः। नहि मरुमरीचिकाह्रदो नष्ट इति कश्चित्तत्त्ववित् विलपति। अतएव भूतानां रज्जूरगादीनामिव प्रतीतिसमकालिकीं सृष्टिमभिप्रेत्य कौषीतकिब्राह्मणे स्वापप्रबोधयोर्जगल्लयोदयौ पठ्येते।स यदा स्वपिति तदैनं वाक्सर्वैर्नामभिः सहाप्येति चक्षुः सर्वै रूपैः सहाप्येति श्रोत्रं सर्वैः शब्दैः सहाप्येति मनः सर्वैर्ध्यानैः सहाप्येति स यदा प्रबुध्यतेऽथैतस्मादात्मनः सर्वे प्राणा यथायतनं विप्रतिष्ठन्ते प्राणेभ्यो देवा देवेभ्यो लोकाः इति। प्राणाश्चक्षुरादीन्द्रियाणि। देवास्तदनुग्राहकाः सूर्यादयः। लोकाः रूपादयः। नन्विहान्यत्र च आत्मैव सर्वभूतानां लयोदयस्थानमित्युच्यते नान्यत्। तत्कथमेषामव्यक्तं लयोदयस्थानमित्युच्यते। सत्यम्। अज्ञानाश्रयत्वाद्ब्रह्मणि तथात्वव्यपदेशो न वस्तुगत्या। नहि अपरिणामिनः कूटस्थस्य मृद्वत्कार्यप्रविलयोदयस्थानत्वं भवति। यथोक्तम्अस्य द्वैतेन्द्रजालस्य यदुपादानकारणम्। अज्ञानं तदुपाश्रित्य ब्रह्मकारणमुच्यते। इति।'),
('nilakantha-sc:source:2.29','Nīlakaṇṭha','gita.2.29','sa','commentary','।।2.29।।ननु वज्रपञ्जरतुल्यस्य सर्वप्रमाणसिद्धस्य वियदादिप्रपञ्चस्य कथं रज्जूरगादिवदज्ञानप्रभवत्वेनात्यन्ततुच्छत्वमुच्यते कथं वा कर्मज्ञानकाण्डापेक्षितमात्मनो यज्ञादिकर्तृत्वं श्रवणादिकर्तृत्वं चापह्नूयत इत्याशङ्क्याह आश्चर्यवदिति। कश्चित् ज्ञातात्मतत्त्व एनमतीतानन्तरश्लोकोक्तं भूतग्राममाश्चर्यवत् आश्चर्यमद्भुतं स्वप्नमायेन्द्रजालादिकं तेन तुल्यमाश्चर्यवत् तथाभूतं पश्यति। तथा कश्चिदेनं आश्चर्यवद्वदति सत्त्वेन असत्त्वेन वा निर्वक्तुमशक्यमपि अनिर्वचनीयेनैव लोकाप्रसिद्धेन रूपेणोपपादयति। तथाहि रज्जूरगवत्प्रपञ्चः संश्चेत्नेह नानास्ति किंचन इति श्रुत्या न बाध्येत असंश्चेन्न प्रतीयेत तस्मादनिर्वचनीयोऽयमिति। तदिदं सर्वव्यवहारास्पदस्यापि प्रपञ्चस्य मिथ्यात्वोपपादनमत्याश्चर्यमित्यर्थः। तथा एनं प्रपञ्चमन्य आश्चर्यवत् शृणोति।इमे लोका इमे देवा इमे वेदा इदं सर्वं यदयमात्मा इति प्रत्यक्षेणानात्मतया उपलभ्यमानस्यापि प्रपञ्चस्य यत् प्रत्यगभिन्नत्वेन श्रवणं तदत्यन्तमाश्चर्यम्। न हीयं श्रुतिःयजमानः प्रस्तरः इत्यादिवदुपचरितार्था। प्रपञ्चस्यात्मनः पृथक्त्वेआत्मनो वा अरे दर्शनेन श्रवणेन मत्या विज्ञानेनेदं सर्वं विदितं भवति इत्येकविज्ञानात्सर्वविज्ञानप्रतिज्ञोपरोधापत्तेः। न च प्रतिज्ञाप्यौपचारिकी। प्रदेशान्तरे श्रुतस्ययथा सौम्यैकेन मृत्पिण्डेन सर्वं मृन्मयं विज्ञातं स्यात् इति दृष्टान्तस्योपरोधापत्तेः। तस्मात्प्रतिज्ञादृष्टान्तनिगमनानामेकवाक्यत्वात् न प्रपञ्चस्यात्मान्यत्वम्। तच्च भेदग्राहिप्रत्यक्षविरोधादाश्चर्यमिव श्रृणोति। तथा कश्चिदेनं प्रपञ्चं प्रत्यगनन्यत्वेन श्रुत्वा अपिशब्दात् उक्त्वा स्वप्नादिदृष्टान्तैरुपपाद्य दृष्ट्वा ध्यानेन च साक्षात्कृत्वापि तत्त्वतो न वेद न जानाति। तथाहि प्राप्तापि प्रज्ञा तीव्रविक्षेपवतः परिहीयत इति वक्ष्यति। तस्मादात्मैक्यात्संभवत्येव प्रपञ्चस्य रज्जूरगादितुल्यत्वेन तुच्छत्वम्। यद्वा एनं आत्मानं कर्तृत्वभोक्तृत्वदुःखित्वानित्यत्वजडत्वसङ्गित्वपरिच्छिन्नत्वादिधर्मवत्तया प्रसिद्धमपि तत्त्वमसीत्यागमोत्थया ब्रह्माकारान्तःकरणवृत्त्या ब्रह्मविद्याख्यया अकर्तारमभोक्तारमानन्दघनं सत्यचिद्रूपमसङ्गमनन्तमपरोक्षीकरोतीति महदाश्चर्यम्। यत् पश्यति तदाश्चर्यवदिति क्रियाविशेषणं वा। आविद्यकमपि दर्शनमविद्यां स्वात्मानं च कतकरजोवन्निवर्तयतीति। यद्वा यः पश्यति स आश्चर्यवदिति कर्तृविशेषणम्। यत एक एव विद्वान् समाधिव्युत्थानयोः परस्परविरुद्धमात्मनो ब्रह्मभावं जीवभावं च यावदारब्धकर्मक्षयमनुभवतीति तथा वाङ्मनसातीतमप्यात्मानं यद्वाचा वदति तदप्याश्चर्यम्। अगृहीतसंगतिकेनापिशब्देन यथा सुप्तः प्रबोध्यते तद्वत्। यथोक्तं वार्तिकेअगृहीत्वैव संबन्धमभिधानाभिधेययोः। हित्वा निद्रां प्रबुध्यन्ते सुषुप्ते बोधिताः परैः। जाग्रद्वन्न यतः शब्दं सुषुप्ते वेत्ति कश्चन। ध्वस्तेऽतो ज्ञानतोऽज्ञाने ब्रह्मास्मीति भवेत्फलम्। अविद्याघातिनः शब्दाद्याहं ब्रह्मेति धीर्भवेत्। नश्यत्यविद्यया सार्धं हत्वा रोगमिवौषधम्। इति। तथा यः शृणोति सोऽपि आश्चर्यवत् अतिदुर्लभ इत्यर्थः।श्रवणायापि बहुभिर्यो न लभ्यः इति श्रुतेः।शृण्वन्तोऽपि बहवो यं न विदुः इति श्रुतिद्वितीयपादार्थं संगृह्णाति श्रुत्वाप्येनमिति। आश्चर्यो वक्ता कुशलोऽस्य लब्धा आश्चर्यो ज्ञाता कुशलेनानुशिष्टः इति उत्तरार्धस्तु श्लोकपूर्वार्धेन संगृहीत इति ज्ञेयम्। दुर्विज्ञेयोऽयमात्मा अतस्त्वं तज्ज्ञानार्थं यतस्वेति भावः।'),
('nilakantha-sc:source:2.30','Nīlakaṇṭha','gita.2.30','sa','commentary','।।2.30।।प्रकृतमर्थमुपसंहरति देहीति। सर्वाणि भूतानि कथमेते दीना अल्पबला बलवत्तरेण मया हन्तव्याः कथमेषां पुत्रादय एतैर्विना जीविष्यन्ति कथं वाहं भीष्मादिभिर्गुरुभिर्विना जीविष्यामीति शोचितुं नार्हसीत्यर्थः।'),
('nilakantha-sc:source:2.31','Nīlakaṇṭha','gita.2.31','sa','commentary','।।2.31।।अर्जुनस्य अनात्मनि देहे आत्मधीरूपो मोहो निवारितः। इदानीं स्वधर्मे युद्धे अधर्मधीरूपं मोहं निवारयति स्वधर्ममपीत्यादिना। युद्धं क्षत्रियस्य स्वो धर्मः तमवेक्ष्यापि विकम्पितुं चलितुं नार्हसि। हि यस्मात् धर्म्यात् धर्मादनपेताद्युद्धादन्यत् क्षत्रियस्य श्रेयः प्रशस्ततरं नास्ति।'),
('nilakantha-sc:source:2.32','Nīlakaṇṭha','gita.2.32','sa','commentary','।।2.32।।किञ्च यदृच्छया अप्रार्थितमप्युपपन्नमुपस्थितं स्वर्गद्वारं अपावृतमुद्धाटितं ये क्षत्रिया लभन्ते ते सुखिनो धन्या भवन्तीति संबन्धः।'),
('nilakantha-sc:source:2.33','Nīlakaṇṭha','gita.2.33','sa','commentary','।।2.33।।युद्धत्यागे इष्टनाशोऽनिष्टप्राप्तिश्च भवतीत्याह अथचेदिति।'),
('nilakantha-sc:source:2.34','Nīlakaṇṭha','gita.2.34','sa','commentary','।।2.34।।अव्ययां दीर्घकालम्।'),
('nilakantha-sc:source:2.35','Nīlakaṇṭha','gita.2.35','sa','commentary','।।2.35।।अकीर्तिमेवाह भयादिति। त्वं बहुमतो भूत्वा स्वत एव अतिश्लाघ्यवृत्तः सन् लाघवं लघुभावं कातर्याख्यं येषां पुरतो यास्यसि ते महारथास्त्वां भयाद्रणादुपरतं मंस्यन्त इति योजना।'),
('nilakantha-sc:source:2.36','Nīlakaṇṭha','gita.2.36','sa','commentary','।।2.36।।किञ्च अवाच्यवादान् वक्तुमयोग्यान् शब्दान्षण्ढतिलोऽर्जुन इत्यादीन्। सामर्थ्यं निन्दन्तः धिगस्य शौर्यं यो भीष्मादिभयात् पलायित इति। इदं वचनं मरणादप्यधिकं दुःखम्। इतोऽन्यद्दुःखतरमधिकं दुःखं किं। न किमपीत्यर्थः।'),
('nilakantha-sc:source:2.37','Nīlakaṇṭha','gita.2.37','sa','commentary','।।2.37।।यद्वा जयेम यदि वा नो जयेयुः इत्युक्तं तत्राह हतो वेति। रणे स्थितस्य स्वर्गो वा राज्यं वा सिद्धमस्तीति पक्षद्वयमपि हितावहमित्यर्थः।'),
('nilakantha-sc:source:2.38','Nīlakaṇṭha','gita.2.38','sa','commentary','।।2.38।।स्वधर्मस्य युद्धस्याकरणे धर्मकीर्त्योर्नाशः पापावाप्तिश्चअथ चेत् इति श्लोकेन भगवता यद्यप्युक्ता तथापि युद्धस्य अर्जुनाभिमते काम्यत्वपक्षेअहो बत महत्पापं कर्तुं व्यवसिता वयम्। यद्राज्यसुखलोभेन हन्तुं स्वजनमुद्यताः। इति तत्करणे पापप्रसक्तिरस्ति तां निवारयितुं सिद्ध्यसिद्ध्योः समत्वलक्षणं योगमाह सुखदुःखे इति। समे कृत्वा सुखदुःखयोस्तद्धेत्वोः राज्यलाभालाभयोस्तद्धेत्वोश्च जयाजययोः रागद्वेषावकृत्वेत्यर्थः। केवलं स्वधर्मोऽयमिति मत्वा युद्धाय युज्यस्व घटस्व। एवं कुर्वंस्त्वं पापं नावाप्स्यसि। यस्तु राज्यलोभेन सुहृद्वधं करोति तस्यास्त्येव पापमिति भावः। कथं तर्हि स्वधर्मत्वेनानुष्ठितेऽपि युद्धे हतो वा प्राप्स्यसि स्वर्गमित्यादिफलस्मरणमानुषङ्गिकमिति ब्रूमः। तथाचापस्तम्बःतद्यथाम्रे फलार्थं निर्मिते च्छाया गन्धावनूत्पद्येते एवं धर्मं चर्यमाणमर्था अनूत्पद्यन्ते नो चेदनूत्पद्यन्ते न धर्महानिर्भवति इत्याम्रनिदर्शनेन प्रतिपादयति।'),
('nilakantha-sc:source:2.39','Nīlakaṇṭha','gita.2.39','sa','commentary','।।2.39।।एवमर्जुनस्य पूर्वोक्तौ द्वावपि मोहावपनीतौ तत्रकं घातयन्ति हन्ति कम् इति कर्तृत्वकारयितृत्वयोरात्मन्यसंभव उक्तःततो युद्धाय युज्यस्व इति नियोगश्चोक्तः नह्यकर्तुराकाशवत्सर्वगतस्य नियोज्यत्वं संभवतीति परस्परव्याहतमेतदितीमामाशङ्कां अधिकारिभेदेन उभयं व्यवस्थापयन् परिहरति एषा ते इति। एषा ते तुभ्यं अभिहिता अशोच्यानन्वशोचस्त्वमित्यादिना स्वधर्ममपि चावेक्ष्येत्यतः प्राक्तनेन संदर्भेणोक्ता। सांख्ये सम्यक् ख्यायते प्रकथ्यते वस्तुतत्त्वमनयेति संख्या उपनिषत् तत्र विदिते सांख्ये औपनिषदे ब्रह्मणि विषये बुद्धिर्ज्ञानं संसारनिवर्तकम्। एषा ते सांख्ये बुद्धिरभिहितेति संबन्धः। योगेसिद्ध्यसिद्ध्योः समो भूत्वा समत्वं योग उच्यते इति वक्ष्यमाणलक्षणे विषये। तुशब्दः पूर्ववैलक्षण्यद्योतनार्थः। वक्ष्यति च ज्ञानकर्मनिष्ठयोर्विभिन्नाधिकारिकत्वंलोकेऽस्मिन् द्विविधा निष्ठा पुरा प्रोक्ता मयानघ। ज्ञानयोगेन सांख्यानां कर्मयोगेन योगिनाम्। इति। एतेन ज्ञानकर्मणोः समुच्चयशङ्काप्यपास्ता। इमांस्वधर्ममपि चावेक्ष्य इत्यादिनाऽनन्तरग्रन्थेनोक्तामपि विस्तरेणाभिधीयमानां शृणु। इमामेव बुद्धिं स्तौति सार्धेन बुद्ध्येत्यादिना। ननु कर्मबन्धप्रहाणमात्मज्ञानेनैव श्रूयतेतपसैवात्मपदं विदित्वा न लिप्यते कर्मणा पापकेन इति श्रुतेः। कर्मयोगस्तु कर्मबन्धं दृढीकरिष्यत्येवेति कथमुच्यते कर्मबन्धं प्रहास्यसीति चेत्। श्रुतिबलादिति ब्रूमः। तथाहिईशावास्यमिदं सर्वं यत्किंच जगत्यां जगत्। तेन त्यक्तेन भुञ्जीथा मा गृधः कस्यस्विद्धनम्। कुर्वन्नेवेह कर्माणि जिजीविषेच्छतं समाः। एवं त्वयि नान्यथेतोऽस्ति न कर्म लिप्यते नरे। इति श्रुतिरीश्वरेणेदं सर्वं स्तम्भितमस्तीति न कश्चित्किंचित्स्वेच्छया कर्तुं प्रभवति अतः सर्वत्र ममताहीनः सन् भोक्तृत्वकर्तृत्वाभिमानत्यागेनैव भोगान् भुङ्क्ष्व कर्माणि च कुरु एवं कुर्वति त्वयि कर्मलेपो नास्ति इतोऽन्यदुपायान्तरं च नास्तीति वदति। तस्मात् कनककार्ष्णायसादिवत्केनचिद्विशेषरूपेणोपेतं कर्मैव सजातीयोच्छेदनिमित्तं भविष्यतीति युक्तमुक्तं कर्मयोगेनापि कर्मबन्धं प्रहास्यसीति।'),
('nilakantha-sc:source:2.40','Nīlakaṇṭha','gita.2.40','sa','commentary','।।2.40।।एतदेवोपपादयति नेहेति। इह कर्मबन्धप्रहाणार्थे कर्मयोगेऽनुष्ठीयमाने। अभिक्रम्यते व्याप्यत इत्यभिक्रमः कर्मारम्भः कर्मैव वा तस्य नाशो नास्ति। अन्यत्तु फलं दत्त्वा नश्यति नत्विदम्। इष्टफलस्याजननात्। नन्वेतस्यापि काम्यान्तःपातितया नित्याकरणजनितः प्रत्यवाय उत्पद्येतैव। सकृदनुष्ठितस्य बन्धप्रहाणप्रत्यवायपरिहाराख्यफलद्वयहेतुत्वायोगादित्याशङ्क्याह प्रत्यवायो न विद्यत इति। तमेतं वेदानुवचनेन ब्राह्मणा विविदिषन्ति यज्ञेन दानेन तपसाऽनाशकेन इति श्रुत्या संयोगपृथक्त्वन्यायेनदध्नेन्द्रियकामस्य जुहुयात् इत्यनेन नित्यस्य दध्नो वीर्यार्थत्वमिव नित्यानामपि कर्मणां विविदिषार्थत्वं विनियोगबलात्सिध्यति। ततश्च काम्येनैव प्रयोगेण नित्यस्यापि सिद्धेर्न नित्याकरणनिमित्तो वा काम्यत्वात्सर्वाङ्गानुपसंहारनिमित्तो वा प्रत्यवायो विद्यते। नित्यानामेव विनियोगात्। नित्येषु च यथाशक्त्युपबन्धस्यानुज्ञानात्। वार्तिके तु काम्यानामप्यत्र विनियोगो दृष्टः। यथावेदानुवचनादीनामैकात्म्यज्ञानजन्मने। तमेतमिति वाक्येन नित्यानां वक्ष्यते विधिः। यद्वा विविदिषार्थत्वं काम्यानामपि कर्मणाम्। तमेतमिति वाक्येन संयोगस्य पृथक्त्वतः। इति। अस्मिन्पक्षे काम्यानामपि तुल्यफलत्वात् नित्यवद्यथाशक्त्युपबन्धो भविष्यतीति न सर्वाङ्गानुपसंहारजनितः प्रत्यवायो विद्यते। स्वल्पमपि अस्य योगधर्मस्यानुष्ठितं अनुपभुक्तबीजकल्पम्जन्मजन्मान्तराभ्यस्तं दानमध्ययनं तपः। तेनैवाभ्यासयोगेन तच्चैवाभ्यसते पुनः। इति स्मृतेरुत्तरोत्तरसंस्काराधानद्वारा स्वसजातीयवृद्धेर्निमित्तं सत्कामादिदोषक्षपणद्वारा महतो भयात्संसारात्त्रायते। तस्मात्सांख्यानधिकारिणा कर्मयोग एवानुष्ठेय इति भावः।'),
('nilakantha-sc:source:2.41','Nīlakaṇṭha','gita.2.41','sa','commentary','।।2.41।।नन्वेवं सांख्ययोगयोर्महाभयात्त्राणहेतुत्वं तुल्यं चेत्कोऽनयोर्विशेष इत्याशङ्क्य सांख्यानां पातशङ्का नास्ति योगिनां तु यावद्विदेहकैवल्यं पातशङ्कास्तीत्याह व्यवसायात्मिकेति। व्यवसायस्तत्त्वनिश्चयस्तदात्मिका तदाकारा बुद्धिरन्तःकरणवृत्तिःअहं ब्रह्मास्मि इति वाक्यजन्या ब्रह्माकारान्तःकरणवृत्तिर्ब्रह्मविद्याभिधाना समस्तवृत्त्यन्तरबाधेन सम्यगभ्युदिता एका एकैव।सकृद्विभातो ह्येष ब्रह्मलोकः इति श्रुतेः। ब्रह्मैव लोको ब्रह्मलोक इह ब्रह्मैव। नहि सकृज्ज्ञाते ब्रह्मणि ज्ञातव्यं कर्तव्यं वा किञ्चिदवशिष्यते कृतकृत्यत्वाद्ब्रह्मविदोऽतोऽस्य पातशङ्का नास्ति। अव्यवसायिनामज्ञानिनां तु बुद्धयोऽनन्ताः ताश्च प्रत्येकं बहुशाखा इति इदमेव मम श्रेय इति निश्चयस्य दुर्लभत्वात्कदाचिदश्रेयस्यपि श्रेयोबुद्धौ सत्यां पातशङ्कास्तीति महांस्तयोर्विशेषे इति भावः।'),
('nilakantha-sc:source:2.42','Nīlakaṇṭha','gita.2.42','sa','commentary','।।2.42।।उत्तरार्धमेव विवृणोति यामिमामित्यादिना। यां पुष्पितां पुष्पितद्रुमवद्दूरतो रमणीयां वाचम्अक्षय्यं ह वै चातुर्मास्ययाजिनः सुकृतं भवतिअपाम सोमममृता अभूम इत्येवंरूपां प्रवदन्ति। अविपश्चितः अव्यवसायिनो मूढाः। यतो वेदवादरताः वेदान्तर्गतेषु अर्थवादेषुयस्य पर्णमयी जुहूर्भवतिन पापँ् श्लोकँ् शृणोति इत्येवमादिषु रताः बद्धश्रद्धाः अतएव कर्मणोऽन्यत् आत्मज्ञानं तत्फलं मोक्षश्च नास्तीति वादिनो वदनशीलाः।');
INSERT INTO commentary_fts (unit_id,author,canonical_ref,language,content_type,content) VALUES
('nilakantha-sc:source:2.43','Nīlakaṇṭha','gita.2.43','sa','commentary','।।2.43।।तथा भोगश्च ऐश्वर्यं च तयोर्गतिः प्राप्तिस्तां प्रति तदर्थमित्यर्थः। कामात्मानः कामग्रस्तचित्ताः। अतएव स्वर्गपराः। कीदृशीं भोगैश्वर्यगतिम्। जन्मकर्मफलप्रदाम्। प्राप्तभोगैश्वर्यो हि पुरुषस्तद्वासनावासितः पुनर्भोगैश्वर्यप्राप्तये जन्म लभते तदर्थं कर्माणि च कुरुते फलं च ततो भोगादिकं प्राप्नोतीति चक्रमनिशमावर्तते। तेन निष्ठातश्च्युतो भवतीत्यर्थः। किञ्च क्रियाविशेषेण बहुलां यथा यथा वित्तव्ययायासाद्याधिक्यं तथा तथा भोगैश्वर्यप्राप्तेरप्याधिक्यमित्यर्थः। एतेनात्यन्तायाससाध्येष्वपि कर्मसु फललोभात्सज्जन्त इत्युक्तम्। भाष्ये भोगैश्वर्यगतिं प्रति साधनभूताः ये क्रियाविशेषा अग्निहोत्रादयः तद्बहुलां जन्मरूपं यत् कर्मफलं तत्प्रदां च वाचमेवेति व्याख्यातम्।'),
('nilakantha-sc:source:2.44','Nīlakaṇṭha','gita.2.44','sa','commentary','।।2.44।। भोगेति। तया पुष्पितया वाचा अपहृतचेतसां पुंसां बुद्धिः समाधौ समाध्यनुष्ठानकाले व्यवसायात्मिका व्यवसायो ज्ञानं तदात्मिका शुद्धचिन्मात्राकारा न विधीयते न भवति। कर्मकर्तरि लकारः। विरक्तस्य हि बुद्धिः समाधौ चिन्मात्राकारा भवति न तु भोगाद्यासक्तस्येति स्पष्टमेव। भाष्ये तु समाधौ अन्तःकरणे व्यवसायात्मिका बुद्धिर्न भवतीति व्याख्यातम्। यद्वा समाध्यनुष्ठानार्थमेव निश्चयात्मिका तेषां बुद्धिर्न भवतीति व्याख्येयम्।'),
('nilakantha-sc:source:2.45','Nīlakaṇṭha','gita.2.45','sa','commentary','।।2.45।।कस्य तर्हि समाधौ बुद्धिर्भवतीत्यत आह त्रैगुण्येति। त्रैगुण्यं गुणत्रयकार्यमूर्ध्वमध्याधोगतिरूपं संसरणं तदेव प्रकाश्यत्वेन विषयो येषां तादृशाः कर्मकाण्डपरा वेदाः। त्वं तु निस्त्रैगुण्यो भव। ऊर्ध्वगतावपि विरक्तो भवेत्यर्थः। वक्ष्यति च तत्तद्गुणप्रधानं गतित्रयंऊर्ध्वं गच्छन्ति सत्वस्था इति। दिव्येभ्योऽपि विषयेभ्यो विरक्तः समाधावधिक्रियत इति भावः। किं लक्षणोऽसौ निस्त्रैगुण्य इत्यत आह निर्द्वन्द्व इति। सुखदुःखे मानापमानौ शत्रुमित्रे शीतोष्णे इत्यादीनि द्वन्द्वानि सप्रतिपक्षपदार्थरूपाणि तेभ्यो निर्गतो निर्द्वन्द्वः। सर्वत्र समबुद्धिरित्यर्थः। ननु बाधमानमुष्णादिकं कथं शीतादिवत्क्षन्तुं शक्यमत आह नित्यसत्त्वस्थ इति। नित्यं सर्वदा सत्त्वं धैर्यं सत्वगुणो वा तदाश्रितो भूत्वा। धीरो हि सर्वं सोढुं शक्तः सात्विको वा प्रारब्धकर्मोपस्थापितमिदं दुःखमपरिहार्यं किमु तप्ततयेति जानन् सर्वं सोढुं शक्नोत्येव। नन्वत्यन्तदुःसहं क्षुधादिदुःखं कथं निस्त्रैगुण्येन सर्वथा प्रवृत्तिशून्येन सोढुं शक्यमत आह निर्योगक्षेम इति। अप्राप्तस्य प्राप्तिर्योगः। प्राप्तस्य संरक्षणं क्षेमः। एतद्वयमपि प्रारब्धकर्माधीनमिति ततोऽपि निर्गत इत्यर्थः। तत्र हेतुः यत आत्मवाञ्जितचित्तः। सहि सर्वास्वप्यापत्स्वनाकुलो नित्यतृप्ततया निरुद्यमश्च भवतीति त्वमप्येतादृशो निस्त्रैगुण्यो भवेत्यर्थः।'),
('nilakantha-sc:source:2.46','Nīlakaṇṭha','gita.2.46','sa','commentary','।।2.46।।नन्वात्मवत्त्वं चित्तशुद्धौ सत्यामेव भवति सा च सकलवेदोक्तकर्मानुष्ठानसाध्या अतो निस्त्रैगुण्यत्वं दुर्लभमित्याशङ्क्याह यावानिति। सर्वतः संप्लुतोदके महति उदपाने जलाशये पुरुषस्य यावान् अर्थो यावत्स्नानपानादिकं प्रयोजनं घटमात्रजलनिर्वर्त्यं भवति न कृत्स्नजलाशयव्ययनिर्वर्त्यं तावानेवार्थो विजानतो व्युत्पन्नचित्तस्य ब्राह्मणस्य ब्रह्मबुभूषोः सर्वेषु वेदेषु वेदैकदेशोपनिषच्छ्रवणमात्रनिर्वर्त्यो भवति न कृत्स्नवेदार्थानुष्ठानं स्वसिद्ध्यर्थमपेक्षते। एकेन जन्मना कृत्स्नवेदार्थानुष्ठानासंभवात्। ऐहिकेन जन्मान्तरीयेण वा जपादिना चित्तशुद्धौ सत्यामुपनिषच्छ्रवणान्निस्त्रैगुण्यता संभवतीति भावः। वृद्धास्तु सर्वतःसंप्लुतोदकस्थानीये आत्मज्ञाने पुरुषस्य तावानर्थः कृत्स्नोऽपि भवति यावाननेककूपरूपोदपानस्थानीयेषु सकलवेदोक्तकर्मस्वनुष्ठितेषु भवति ब्रह्मानन्दे क्षुद्रानन्दानामन्तर्भावात्। तथा च श्रुतिर्ज्ञाने सर्वकर्मफलान्तर्भावं दर्शयति।यथा कृतायविजितायाधरेयाः संयन्त्येवमेवैनं सर्वं तदभिसमेति यत्किंच प्रजाः साधु कुर्वन्ति यस्तद्वेद यत्स वेद इति। वक्ष्यति चसर्वं कर्माखिलं पार्थ ज्ञाने परिसमाप्यते इति। गङ्गातुल्यज्ञानोदयात्प्रागेव कूपोपमानि कर्माणि कर्तव्यानीति भाव इति व्याचख्युः। अस्मिन्पक्षे पूर्वार्धे अनेकस्मिन् यथातथाभवतीति पदचतुष्टयाध्याहारः यावान्तावान्पदयोरनुषङ्गश्च दार्ष्टान्तिके द्रष्टव्यः।'),
('nilakantha-sc:source:2.47','Nīlakaṇṭha','gita.2.47','sa','commentary','।।2.47।।ननु ममाप्यौपनिषदात्मज्ञानार्थिनः शम एवेष्टस्तत्कथं मां युध्यस्वेति प्रेरयसीत्याशङ्क्याह कर्मण्येवेति। कर्मण्येवाधिकारो न ज्ञाननिष्ठायाम्। मा फलेषु सङ्गोऽस्त्वित्यपकृष्यते। कर्मफलं स्वर्गपश्वादिहेतुः कर्मसु प्रवर्तकं यस्य तादृशो मा भूः। अकर्मणि कर्माकरणेऽपि तव सङ्गो मास्तु।'),
('nilakantha-sc:source:2.48','Nīlakaṇṭha','gita.2.48','sa','commentary','।।2.48।।एतदेव विवृणोति योगस्थ इति। योगस्थः सन् सङ्गं फलतृष्णां कर्तृत्वाभिमानं च त्यक्त्वा कर्माणि ज्ञानार्थं कुरु। हे धनंजय सिद्ध्यसिद्ध्योः कर्मफलस्य विविदिषादेः सिद्धावसिद्धौ वा समो हर्षविषादशून्यो भूत्वा कर्माणि कुर्विति संबन्धः। इदमेव सिद्ध्यसिद्ध्योः समत्वं योग इत्युच्यते।'),
('nilakantha-sc:source:2.49','Nīlakaṇṭha','gita.2.49','sa','commentary','।।2.49।।इदमेव बुद्धियोगं स्तौति दूरेणेति। कर्मफलकामेन क्रियमाणं बुद्धियोगात्पूर्वोक्तान्निष्कामात्कर्मणः दूरेण हि प्रसिद्धं अवरं अत्यन्तनिकृष्टं अतो बुद्धौ योगरूपायां तत्फलभूतायां सांख्यरूपायां वा तन्निमित्तं शरणं रक्षितारं आश्रयं वा ईश्वरमन्विच्छ प्रार्थयस्व। तत्प्रीत्यर्थं कर्माणि कुर्वित्यर्थः। यतः फलहेतवः फलमेव हेतुः प्रवर्तकं येषां तादृशाः फलतृष्णावन्तः कृपणा दीना भवन्ति।यो वा एतदक्षरं गार्ग्यविदित्वास्माल्लोकात्प्रैति स कृपणः इति श्रुतेः।'),
('nilakantha-sc:source:2.50','Nīlakaṇṭha','gita.2.50','sa','commentary','।।2.50।।किञ्च बुद्धीति। बुद्धियुक्तः समत्वबुद्धियुक्तः योगाय समत्वबुद्धियोगाय युज्यस्व घटस्व। योगः सिद्ध्यसिद्ध्योः समत्वबुद्धिः कर्मसु बन्धकेष्वपि कौशलं बन्धनिवर्तकत्वसंपादनम्। ननु बुद्धियुक्तः कर्मभिर्दुष्कृतं त्यजतुधर्मेण पापमपनुदति इति श्रुतेः सुकृतं तु सजातीयत्वात्तैर्दुष्परिहरमिति कथमुभे सुकृतदुष्कृते जहातीत्युच्यते सत्वशुद्धिज्ञानोत्पत्तिद्वारेति प्राञ्चः। अर्वाञ्चस्तु दुष्कृतत्यागमुक्तरीत्याभ्युपेत्य फलत्यागात्सुकृतत्यागोऽपि कर्मयोगिनो भवति। दुष्कृतफलवन्मोक्षप्रतिबन्धकतत्फलस्यानुत्पादात्। यत्तु आपस्तम्बोक्ताम्रवृक्षनिदर्शनेन नान्तरीयकं सुकृतफलमुक्तं न तत्फलत्वेनोपपद्यते नान्तरीयकत्वादेव। तस्मात्फलद्वारा मोक्षप्रतिबन्धके क्रियमाणे एव सुकृतदुष्कृते कर्मयोगी जहाति ज्ञानी तु संचिते अपि ते जहातीति तयोर्विशेषे इत्याहुः।'),
('nilakantha-sc:source:2.51','Nīlakaṇṭha','gita.2.51','sa','commentary','।।2.51।।एतदेवाह कर्मजमिति। बुद्धियुक्ताः समत्वबुद्धियुक्ताः। क्रियमाणकर्मजं फलं त्यक्त्वा मनीषिणो मनोनिग्रहसमर्था भूत्वा जन्मरूपेण बन्धेन मुक्ताः सन्तोऽनामयं निरुपद्रवं पदं मोक्षाख्यं गच्छन्ति।'),
('nilakantha-sc:source:2.52','Nīlakaṇṭha','gita.2.52','sa','commentary','।।2.52।।कदा मनीषिणो भवन्तीत्यत आह यदेति। ते तव मोहः इष्टानिष्टवियोगसंयोगजपरितापजन्यं वैचित्यं तदेव कलिलमिव कलिलं कालुष्यं बुद्धिगतं बुद्धिर्व्यतितरिष्यति व्यतिक्रमिष्यति बुद्धिः प्रसन्ना भविष्यति तदा श्रोतव्यस्य शास्त्रभागस्य श्रुतस्य च निर्वेदं वैराग्यं गन्तासि। अयं भावः मलिनायां बुद्धावसकृद्गृहीतस्यापि शास्त्रार्थस्याफुरणाच्छ्रोतव्यं श्रुतं च वृथैव तद्वच्छुद्धायामपि बुद्धौ सद्यः शास्त्रार्थस्फुरणात्तयोर्वैयर्थ्यमित्युभयथापि तत्र निर्वेद उचितः। प्रसन्ना च बुद्धिर्निग्रहीतुं योग्या भवतीति श्रवणादिकं त्यक्त्वा ध्याननिष्ठ एव भवेदिति।'),
('nilakantha-sc:source:2.53','Nīlakaṇṭha','gita.2.53','sa','commentary','।।2.53।।ननु बुद्धिप्रसादोऽपि केन लिङ्गेन ज्ञेय इत्यत आह श्रुतीति। श्रुतिभिर्नानाविधशास्त्रश्रवणैर्विप्रतिपन्ना आत्मा नित्योऽनित्यो वा नित्योऽपि कर्ताऽकर्ता वा अकर्ताप्येकोऽनेको वेत्येवमादिसंशयग्रस्ता सती यदा असंभावनाविपरीतभावनानिरासपूर्वकं श्रुतितात्पर्यविषयीभूते ब्रह्माद्वैते निश्चला पुनः कुतर्कैरनास्कन्दनीया निर्विचिकित्सा परोक्षनिश्चयवती भूत्वा समाधौ निर्विकल्पके प्रत्यगात्मनि अचला लयविक्षेपशून्या स्थास्यति स्थिरा भविष्यति तदा योगं विवेकप्रज्ञां प्राप्स्यसि। निश्चलसमाधिलाभ एव बुद्धिप्रसादलिङ्गमिति भावः।'),
('nilakantha-sc:source:2.54','Nīlakaṇṭha','gita.2.54','sa','commentary','।।2.54।।लब्धसमाधेः स्थितप्रज्ञापरनाम्नो लक्षणानि बुभुत्सुरर्जुन उवाच स्थितप्रज्ञस्येति। स्थिता प्रत्यगात्मनि प्रतिष्ठिता प्रज्ञा यस्य तस्य स्थितप्रज्ञस्य समाधिस्थस्य समाधौ स्थितस्य का भाषा भाषणं वचनं। कथमसौ परैर्भाष्यते इत्येकः प्रश्नः। स्थितधीः स्थितप्रज्ञः अर्थाद्व्युत्थितः सन् किं प्रभाषेत कथं वदति कथमास्ते कथं वा व्रजति विषयान्भुङ्क्ते इति प्रश्नत्रयम्।'),
('nilakantha-sc:source:2.55','Nīlakaṇṭha','gita.2.55','sa','commentary','।।2.55।।एतेषां क्रमेणोत्तराण्याह भगवान् प्रजहातीत्यादिना। अत्र यान्येव कृतार्थलक्षणानि तानि ज्ञानसाधनानीति मत्वा उपदिश्यन्ते स्थितप्रज्ञलक्षणानि तेषामकृतार्थेषु यत्नसाध्यत्वात् कृतार्थेषु स्वाभाविकत्वात्। यथोक्तम्उत्पन्नात्मप्रबोधस्य ह्यद्वेष्टृत्वादयो गुणाः। भवन्त्ययत्नतस्तस्य न तु साधकरूपिणः। इति। यदायं योगी सर्वान्स्थूलसूक्ष्मकारणशरीरभोग्यान् कामान्काम्यमानान्विषयान्प्रकर्षेण समूलं जहाति त्यजति। कीदृशान्कामान्। मनोगतान्मनस्येव संकल्पविकल्पात्मके स्थितान्नतु बहिः। यथोक्तमक्षपादाचार्यैःदोषनिमित्तं रूपादयो विषयाः संकल्पकृताः इति। तत्र स्थूलानां कामानां त्याग एकान्तसेवनमात्राद्भवतीति स स्थवीयानेव। विलीनकरणग्रामस्य समनस्कस्य जाग्रद्वासनामयाः स्वप्ने ये कामाः स्फुरन्ति तेषामपि त्यागो भगवद्ध्यानादिरूपसद्वासनाभ्यासबलेन भवति। येतूपसंहृतकरणस्य संप्रज्ञातसमाधिकाले दिव्याः कामाः संकल्पमात्रोपनता दहरविद्यादिषु प्रसिद्धास्तेषामपि त्यागोऽसंप्रज्ञातसमाध्यभ्यासबलेन भवति। एवं त्रिविधान्कामान्त्यक्त्वा आत्मन्येवाखण्डैकरसे आत्मना स्वेनैव स्वरूपानन्देन तुष्टो बाह्यविषयनिरपेक्षो यदा भवति तदायं स्थितप्रज्ञ इत्युच्यते।'),
('nilakantha-sc:source:2.56','Nīlakaṇṭha','gita.2.56','sa','commentary','।।2.56।।दुःखेषु शस्त्रपातादिषु दुःखसाधनेषु प्राप्तेष्वपि अनुद्विग्नमना अचञ्चलमनाः। वक्ष्यति चयस्मिन्स्थितो न दुःखेन गुरुणापि विचाल्यते इति। सुखेषु सुखसाधनेषु स्रक्चन्दनादिषु प्राप्तेष्वपि विगतस्पृहो निर्वृत्तिकत्वाद्भवति। अतएव वीताः रागभयक्रोधा यस्मात्स तथा। नहि तस्यामवस्थायां रागादयो दुःखादयो वा संभवन्ति। एवंविधः समाधिस्थः स्थितधीः स्थितप्रज्ञ उच्यते।'),
('nilakantha-sc:source:2.57','Nīlakaṇṭha','gita.2.57','sa','commentary','।।2.57।।स्थितधीः किं प्रभाषेतेत्यस्योत्तरमाह यः सर्वत्रेति। सर्वेषु धनदारदेहजीवनादिषु अभिस्नेहः। अभिस्नेहवान्हि धनदारादिषु विकलेषु सकलेषु वाऽहमेव विकलः सकलोऽस्मीति दैन्यदर्पोपेतः पूर्वापरानुसंधानरहितो जल्पति अयं तु न तथेति भावः। तथा शुभं प्राप्य नाभिनन्दति संतुष्टो भूत्वा शुभप्रापयितारं न प्रशंसति। तथा अशुभं प्राप्य न द्वेष्टि दुःखी भूत्वा अशुभप्रापयितारं न निन्दति यस्तस्य प्रज्ञा प्रतिष्ठिता।'),
('nilakantha-sc:source:2.58','Nīlakaṇṭha','gita.2.58','sa','commentary','।।2.58।।किमासीतेत्यस्योत्तरमाह यदेति। इन्द्रियार्थेभ्यः शब्दादिविषयेभ्यः प्रारब्धकर्मवशेन व्युत्थितोऽपि योगी द्वैतदर्शनादुद्विग्नः सन् निरोधसंस्कारप्राबल्यात्प्रीत्या समाधिमनुतिष्ठन्नेवास्ते इत्यर्थः। शेषं स्पष्टम्।'),
('nilakantha-sc:source:2.59','Nīlakaṇṭha','gita.2.59','sa','commentary','।।2.59।।ननु विषयेभ्य इन्द्रियाणां निवृत्तिश्चेत् स्थितप्रज्ञताहेतुस्तर्हि सुप्तिमूर्च्छालयग्रहावेशादावपि सास्तीति सर्वोऽपि स्थितप्रज्ञ एवेत्याशङ्क्याह विषया इति। सत्यं देहिनो देहाभिमानवतो मूढस्य सुप्त्यादौ निराहारस्य इन्द्रियैर्विषयाननाहरतोऽभुञ्जानस्य विषया विनिवर्तन्त एव तथापि रसवर्जं रसो रागस्तद्वर्जं निवर्तन्ते। तदापि सूक्ष्मरूपेण रागोऽस्ति रागमूलस्यात्माज्ञानस्यादाहान्नासौ स्थितप्रज्ञ इत्यर्थः। अस्यैव पुनः परं दृष्ट्वा आत्मानं साक्षात्कृत्य निराहारस्य शब्दादीनगृह्णतो रसोऽपि निवर्तते मूलाज्ञानदाहादित्यस्ति सुप्तादेः समाधिस्थस्य च महान्विशेष इति भावः। प्राञ्चस्तु रोगिणः काष्ठतपस्विनो वा मूढस्यापि विषयाननाहरतो रसवर्जं विषया विनिवर्तन्ते तस्यैव परं दृष्ट्वा स्थितस्य रसोऽपि निवर्तत इति व्याचख्युः।'),
('nilakantha-sc:source:2.60','Nīlakaṇṭha','gita.2.60','sa','commentary','।।2.60।।किंच सुप्तादेरिन्द्रियाणि श्रान्त्या स्वयमेव लीयन्ते समाहितेन तु तानि कूर्मेणाङ्गानीव स्वेच्छया संह्रियन्ते एतच्चात्यन्तायाससाध्यमित्याह यतत इति। विपश्चितः शास्त्राचार्योपदेशवतो यततोऽपि समाधिसिद्ध्यर्थं यतमानस्यापि पुरुषस्य इन्द्रियाणि कर्तृ़णि मनः प्रतीचि स्थिरीक्रियमाणं कर्मीभूतं हरन्ति विषयप्रवणं कुर्वन्ति। यतः प्रमाथीनि यथा बहवश्चोरा वने एकं पुरुषं प्रमथ्य तस्य वित्तं हरन्ति एवमिन्द्रियाणि यततो मनो हरन्ति। यतः प्रसभमतिशयेन प्रमथनशीलानि।'),
('nilakantha-sc:source:2.61','Nīlakaṇṭha','gita.2.61','sa','commentary','।।2.61।।यद्यप्येवं तथापि तानि नियन्तव्यान्येवान्यथास्थितप्रज्ञत्वस्यैवासिद्धेरित्याह तानीति। संयम्य वशीकृत्य युक्तः संनद्धो मत्परः अहमेव सर्वेषां प्रत्यगात्मा परः स्त्र्यादिभ्यो बाह्येभ्यो देहेन्द्रियादिभ्य आन्तरेभ्यश्च उत्कृष्टः प्रियतमो यस्य स मत्परः सन्नासीत। हि यस्मात् वशे आज्ञायाम्। शेषं स्पष्टम्।'),
('nilakantha-sc:source:2.62','Nīlakaṇṭha','gita.2.62','sa','commentary','।।2.62।।यदा पञ्चावतिष्ठन्ते ज्ञानानि मनसा सह। बुद्धिश्च न विचेष्टति तामाहुः परमां गतिम् इति श्रुतौ इन्द्रियमनोबुद्धीनां निग्रहे परमपदप्राप्तिरित्युक्तम्। तत्र उपसंहृतकरणस्य बाह्याञ्शब्दादीनगृह्णतो मनोमात्रेणावस्थितस्य योगिनो मनसोऽनिग्रहे किं स्यादित्याह ध्यायत इति द्वाभ्याम्। विषयाञ्शब्दादीन्ध्यायतश्चिन्तयतः पुंसः पुरुषस्य तेषु शब्दादिषु सङ्गः संबन्धो जायते। बाह्यार्थेभ्यो निगृहीतान्यपीन्द्रियाणि मनोदोषात्पुनर्बाह्यार्थान्गृह्णन्तीत्यर्थः। ततः सङ्गात्कामस्तस्मिन्विषयेऽभिलाषः संजायते। कामात्कुतश्चिद्धेतोः प्रतिहतादभिज्वलनात्मा क्रोधोऽभिजायते।'),
('nilakantha-sc:source:2.63','Nīlakaṇṭha','gita.2.63','sa','commentary','।।2.63।।ततः क्रोधात्संमोहः कार्याकार्यविवेकाभावो भवति। ततः स्मृतिविभ्रमः शास्त्रार्थानुसंधानस्य विभ्रंशरूपं चलनं भवति। स्मृतिभ्रंशाद् बुद्धिनाशः शास्त्रार्थस्य निश्चितस्यापि तिरोधानं भवति। तस्मिंश्च शास्त्रजे परोक्षज्ञानेऽपि नष्टे पुरुषो नश्यति पुरुषार्थायोग्यो भवति। यो हि तादृशः स नष्ट एवेति लोके वदन्ति।'),
('nilakantha-sc:source:2.64','Nīlakaṇṭha','gita.2.64','sa','commentary','।।2.64।।ननु विषयानध्यायतोऽपि योगिनो व्युत्थाने प्रमाणस्वाभाव्यादिन्द्रियाणां विषयेषु सङ्गो दुष्परिहरस्ततश्चोक्तरीत्या तस्यापि नाशप्रसक्तिरित्याशङ्क्याह रागद्वेषेति। विधेयात्मा किंकरीकृतमनास्तु आत्मवश्यैर्मनोधीनैरिन्द्रियैः स्वामिनश्चित्तस्य किंकरीकृतस्य कामक्रोधहीनत्वात्स्वयमपि रागद्वेषवियुक्तैः विषयान्पथि पतिततृणादीनीवानास्थया चरन्पश्यन्नपि पुमान् तत्र कामाद्यनुदयात्प्रसादं संकल्पविकल्पपङ्कलेपप्रक्षालनेन मनसः स्वाच्छ्यमधिगच्छति। मनसः स्वाच्छ्यमेव प्रत्यगात्मनः स्वाच्छ्यं तस्य तद्गुणसारत्वात्। अजितमनस्कमिव जितमनस्कं विषयसङ्गो न बाधतेऽतो मनोजयोऽवश्यं कर्तव्य इत्यर्थः।'),
('nilakantha-sc:source:2.65','Nīlakaṇṭha','gita.2.65','sa','commentary','।।2.65।।किंच चित्तस्य प्रसादे हि अस्य पुंसः सर्वदुःखानां काममूलकानां कामाभावाद्धानिः परिहारो जायते। कामानुदये हेतुमाह प्रसन्नेति। हि यस्मात्प्रसन्नचेतसः पुंसो बुद्धिर्ब्रह्मात्मैक्यनिश्चय आशु शीघ्रं पर्यवतिष्ठते सुदृढो भवति। तस्मिंश्च सति प्राप्याभावान्न कामोदय इत्यर्थः।'),
('nilakantha-sc:source:2.66','Nīlakaṇṭha','gita.2.66','sa','commentary','।।2.66।।समनस्कानामिन्द्रियाणामनिग्रहे दोष उक्तः बुद्धेरपर्यवस्थाने को दोष इत्यत आह नास्तीति। अयुक्तस्य श्रवणमननयोरनासक्तस्य बुद्धिर्ब्रह्मात्मैक्यनिश्चयो नास्ति। प्रमाणविषयासंभावनायाः प्रमेयविषयासंभावनायाश्चानिरासात्। तथा अयुक्तस्यासमाहितमनसो भावना ब्रह्माकारान्तःकरणवृत्तिप्रवाहो नास्ति। मनसश्चाञ्चल्येन बुद्धेरपि चाञ्चल्यात् अभावयतो ध्यानमकुर्वतः शान्तिः सर्वदुःखोपरमश्च नास्ति। चेतसोऽनवस्थित्वेन दुःखावश्यंभावात्। अशान्तस्यानुपरतसर्वदुःखस्य सुखं प्रत्यगद्वयानन्दात्मकं कुतो न कुतश्चित्। दुःखित्वादेव आद्यमयुक्तस्येति पदंयुजिर् योगे इत्यस्य रूपम्। द्वितीयंयुज समाधौ इत्यस्य। तस्माद्बुद्धेः पर्यवस्थानमावश्यकम्।'),
('nilakantha-sc:source:2.67','Nīlakaṇṭha','gita.2.67','sa','commentary','।।2.67।।तदभावे दोषमाह इन्द्रियाणां हीति। हि यस्मादिन्द्रियाणां चरतां स्वस्वविषये प्रवर्तमानानाम्। कर्मणि षष्ठी। यत् रागादिकलुषितं मनः तान्यनुलक्षीकृत्य विधीयते प्रवर्त्यते। कर्मकर्तरि लकारः। प्रवर्तत इत्यर्थः। तत् इन्द्रियानुसारि मनोऽस्य साधकस्य प्रज्ञामात्मतत्त्वविषयां बुद्धिं हरति। तस्या मनोनुसारित्वात्। दृष्टान्तः स्पष्टार्थः। अन्ये तु इन्द्रियाणां मध्ये यदिन्द्रियमनुलक्षीकृत्य मनः प्रवर्तते तदिन्द्रियमस्य साधकस्य मनसो वा प्रज्ञां हरतीति योजयन्ति। आत्मविषयां प्रज्ञां हृत्वा मनोविषयविषयां करोतीति भाष्यमप्यालोचनीयम्।'),
('nilakantha-sc:source:2.68','Nīlakaṇṭha','gita.2.68','sa','commentary','।।2.68।।यततो ह्यपीत्यत्रोपक्रान्तमर्थं बहुधोपपाद्योपसंहरति तस्मादिति। यस्मादिन्द्रियाधीनं मनो मनोनुगा च प्रज्ञा तस्मात् हे महाबाहो यस्य यतेरिन्द्रियाणि सर्वशः सर्वप्रकारेण स्वकारणेन मनसा सहितानीति यावत्। इन्द्रियार्थेभ्यः शब्दादिभ्यो निगृहीतानि भवन्ति तस्य प्रज्ञा प्रतिष्ठितेति विद्धि।'),
('nilakantha-sc:source:2.69','Nīlakaṇṭha','gita.2.69','sa','commentary','।।2.69।।यदा पञ्चावतिष्ठन्ते इत्युदाहृतश्रुतेःतामाहुः परमां गतिम् इत्येतं चतुर्थं पादं व्याचष्टे या निशेति। सर्वेषां भूतानामज्ञानां या निशेव निशा यस्यां मध्यंदिने उलूका इवानन्धा अप्यन्धा एव सर्वे प्राणिनो भवन्ति तस्यां तस्मिन्प्रत्यग्ज्योतिषि संयमी इन्द्रियमनोबुद्धीनां निग्रहणशीलो योगी जागर्ति इन्द्रियादीनां दृक्शक्तिलोपेऽप्यनुपरतदृक्शक्तिरेवास्ते। तथा च श्रुतिःनहि द्रष्टुर्दृष्टेर्विपरिलोपो विद्यतेऽविनाशित्वात् इति। यस्यामविद्याख्यायां निशायां क्रियाकारकादिद्वैतस्वप्नप्रवर्तिकायां सर्वाणि भूतानि जाग्रति निशीथे उलूका इव स्वस्वव्यापारे प्रवर्तन्ते सा अविद्या पश्यतो मुनेः आत्मदर्शनवतो योगिनः प्रारब्धकर्मणा विदेहकैवल्यप्रतिबन्धाल्लेशतोऽनुवर्तमाना व्युत्थानकाले व्यवहारतोऽस्य गाढान्धकारवती निशेव क्लेशकरी भवति। अतिसुकुमारा हि योगिनो बाह्यव्यवहारादुद्विजन्ते नरा इव गाढान्धकारे संचारात्। यथोक्तं योगभाष्येअक्षिमात्रकल्पो हि विद्वानत्यल्पदुःखलेशेनाप्युद्विजते इति। अत्र वार्तिकानिकारकव्यवहारे हि शुद्धं वस्तु न वीक्ष्यते। शुद्धे वस्तुनि सिद्धे च कारकव्यापृतिस्तथा। काकोलूकनिशेवायं संसारोऽज्ञात्मवेदिनोः। या निशा सर्वभूतानामित्यवोचत्स्वयं हरिः। इति।बुद्धतत्त्वस्य लोकोऽयं जडोन्मत्तपिशाचवत्। बुद्धतत्त्वोऽपि लोकस्य जडोन्मत्तपिशाचवत्। इति। तदेवं किमासीतेत्यस्योत्तरंयदा संहरते चायम् इत्यादिना एतदन्तेन ग्रन्थेन स्थितप्रज्ञः सदा समाधिमनुतिष्ठन्परमां गतिं प्राप्यास्त इत्युक्तम्।'),
('nilakantha-sc:source:2.70','Nīlakaṇṭha','gita.2.70','sa','commentary','।।2.70।।ननुप्रजहाति यदा कामान्इन्द्रियाणीन्द्रियार्थेभ्यो निगृहीतानि इत्यादिनाऽसकृद्विषयाणां प्रहाणं तेभ्यश्च इन्द्रियादीनां प्रत्याहरणमुक्तम्। तेन तेषामात्मनः पृथक्सत्त्वमस्तीति सिद्धम्। न चनेह नानास्ति किंचन इत्यादिश्रुत्या तेषां बाधान्न तदस्तीति वाच्यम्। इहेति प्रतीच्येव तन्निषेधात्। नहि इह भूतले घटो नास्तीत्युक्ते घटस्य स्वरूपं निषिध्यते किंतु तस्य भूतलसंबन्धमात्रम्। तस्मात्कामानां पृथक्सत्त्वमस्त्यतो नाद्वैतसिद्धिरित्याशङ्क्य सदृष्टान्तं परिहरति आपूर्यमाणमिति। प्रविशन्तीभिरद्भिरापूर्यमाणमपि अचलप्रतिष्ठम् अनुद्रिक्तम्। वृद्धिहीनत्वात्। एवं निर्गच्छन्तीभिरद्भिः रिच्यमानमप्यचलप्रतिष्ठमरिक्तं ह्रासहीनत्वादित्यपि बोध्यम्। एवंविधं समुद्रं यद्वत् आत्मप्रभवा आपः प्रविशन्ति तद्वत् यं पुरुषं कामैरापूर्यमाणं हीयमानं वा अचलप्रतिष्ठं निर्विकारं वृद्धिह्रासहीनत्वात् आत्मप्रभवाः सर्वे कामाः प्रविशन्ति स एव शान्तिं मोक्षं आत्यन्तिकं दुःखोपरमं प्राप्नोति न तु कामकामी विषयार्थी। अयं भावः कूटस्थादात्मनः सर्वस्योत्पत्तिस्तत्रैव च लय इति सर्वश्रुतिस्मृतिप्रसिद्धम्। तेन कामानां प्रहाणं तेभ्यश्चेन्द्रियाणां प्रत्याहरणं स्मर्यमाणं न तेषां परमार्थतः पृथक्सत्त्वं साधयति। बहुप्रमाणविरोधात् किंतु पामरप्रसिद्धं पृथक्सत्त्वमभिप्रेत्य प्रहाणादिकमुक्तं प्रविलापनं त्वेवमेव व्याख्येयम्। यथाअग्नये पथिकृतेऽष्टाकपालं निर्वपेत् इत्यादौ निर्वपतिना याग उच्यते नतु श्रौतार्थमात्रं तद्वदिहापि ज्ञेयम्।नेह नानास्ति इत्यपीह परिदृश्यमाने प्रपञ्चे आत्मातिरिक्तं नाना किमपि नास्तीत्येवंपरतया व्याख्येयम्। तथा चआत्मैवेदं सर्वंब्रह्मैवेदं सर्वंसर्वं खल्विंद ब्रह्म इत्यादयः श्रुतिवादाः संगच्छन्ते। आत्मनि कल्पितस्यास्य तत्रैव निषेधेनान्यत्र सत्त्वानुपपत्तेर्न कामानां पृथक्सत्त्वमस्तीति युक्त एव समुद्रदृष्टान्तः। यत्तु समुद्रात्पृथग्गङ्गायाः सत्त्वमस्तीति। तन्न। कार्ये कारणसत्तातिरिक्तसत्ताया अभावात्।वाचारम्भणं विकारो नामधेयम् इति कार्यस्य वागालम्बनमात्रत्वश्रवणादित्यन्यत्र विस्तरः।'),
('nilakantha-sc:source:2.71','Nīlakaṇṭha','gita.2.71','sa','commentary','।।2.71।।प्रासङ्गिकीमाशङ्कां परिहृत्य व्रजेत किमित्यस्य प्रश्नस्योत्तरमाह विहायेति। पूर्वोक्तांस्त्रिविधान्कामान्विहाय यः चरति विषयान्भुङ्क्ते निस्पृहश्च। यतो निर्ममः। ममतावान्हि इदं मम भूयादित्यन्यधनाद्यर्थं स्पृहां करोति न निर्ममोऽपि। कुतः यतो निरहंकारः। नह्यहंकारशून्यस्य सुप्त्यादौ ममता दृष्टा। तस्मादहंकारप्रविलयाच्छान्तिं मोक्षं प्राप्नोति। अत्र यः सर्वत्रानभिस्नेह इति सर्वत्र यच्छब्ददर्शनात्साधनविधिपर एवायं ग्रन्थः। अन्यथा स्थितप्रज्ञस्य प्रकृतत्वात्तदनुवादार्थो यच्छब्दोऽनर्थकः प्राप्नोति। लोकेऽपि हि परस्वभावकथने स एवं करोतीति तच्छब्द एव प्रयुज्यते न तु यच्छब्दः। विधौ तु य एवं करोति स इदं प्राप्नोतीति द्वयोरपि प्रयोगो दृश्यते। लक्षणकथनार्थत्वेऽपि तत्र तात्पर्याभावाद्विधावेव पर्यवस्यतीति दिक्।'),
('nilakantha-sc:source:2.72','Nīlakaṇṭha','gita.2.72','sa','commentary','।।2.72।।प्रतिपादितां कर्मयोगप्राप्यां सांख्ययोगनिष्ठां फलेन स्तुवन्नुपसंहरति एषेति। एषा स्थितप्रज्ञलक्षणप्रसङ्गात्कथिता ब्राह्मी। ब्रह्मशब्देनात्र ब्रह्मविदुच्यते।ब्रह्मविद्ब्रह्मैव भवति इति श्रुतेः। तस्येयं ब्राह्मी स्थितिर्निष्ठा एनां निष्ठां प्राप्य नरो न विमुह्यति पुनर्मोहं न प्राप्नोति। अस्यामन्तकालेऽपि स्थित्वेति सकृज्जातापीयं फलवती नतूपासनावच्चिराभ्याससापेक्षेत्युक्तम्। ब्रह्म ऋच्छति प्राप्नोति। किं लोकान्तरवद्गतिप्राप्यं ब्रह्म नेत्याह निर्वाणमिति। निर्गतं वानं गमनं यस्मिन्प्राप्ये ब्रह्मणि तन्निर्वाणम्। तथा च श्रुतिःन तस्य प्राणा उत्क्रामन्त्यत्रैव समवलीयन्ते ब्रह्मैव सन् ब्रह्माप्येति इति। गतिमन्तरेण प्राणरूपोपाधिप्रविलयमात्राद्धटाकाशस्य महाकाशत्वप्राप्तिवत् जीवस्य ब्रह्मप्राप्तिमाह। अन्तकालेऽपीत्यपिशब्दाद्यो ब्रह्मचर्यादारभ्यात्र तिष्ठति स ब्रह्मनिर्वाणं कैमुतिकन्यायेन प्राप्नोतीति गम्यते। अस्याध्यायस्यार्थः संगृहीतो मधूसूदनश्रीपादैःज्ञानं तत्साधनं कर्म सत्त्वशुद्धिश्च तत्फलम्। तत्फलं ज्ञाननिष्ठैवेत्यध्यायेऽस्मिन्प्रकीर्तितम्।'),
('nilakantha-sc:source:3.1','Nīlakaṇṭha','gita.3.1','sa','commentary','।।3.1।।पूर्वस्मिन्नध्यायेएषा तेऽभिहिता सांख्ये बुद्धिर्योगे त्विमां श्रृणु इति द्वे बुद्धी प्रदर्श्यव्यवसायात्मिका बुद्धिः इति श्लोकेन सांख्यनिष्ठावतां पातशङ्का नास्ति कर्मयोगनिष्ठावतां तु सास्तीत्युक्तायावानर्थ उदपाने इति सांख्यनिष्ठायां सर्वकर्मफलान्तर्भावश्रवणात्तामेव प्रशमात्मिकां स्वाशयानुकूलां मन्वानोऽर्जुन उवाच ज्यायसीति। हे जनार्दन कर्मणो निष्कामकर्मयोगापेक्षया बुद्धिः सांख्यनिष्ठालक्षणं ज्ञानं ज्यायसी प्रशस्ततरा चेत्ते तव मता तत्तर्हि मां भैक्ष्यवृत्त्यापि तुष्यन्तं घोरे बन्धुवधाख्ये कर्मणि किं कुतो हेतोर्नियोजयसि पुनः पुनर्युध्यस्वेति वदन्।'),
('nilakantha-sc:source:3.2','Nīlakaṇṭha','gita.3.2','sa','commentary','।।3.2।।ननु तव ज्ञाननिष्ठायामनधिकारात्मकर्मैव कुर्विति त्वां ब्रवीमीत्याशङ्क्याह व्यामिश्रेणेति। व्यामिश्रेणाविविक्तेन। इवशब्दो विविक्तेऽपि बुद्धिदोषादविविक्ततां गृह्णामीति सूचयति तेन वाक्येनत्रैगुण्यविषया वेदा निस्त्रैगुण्यो भवार्जुन इति क्वचिद्वेदनिष्ठां त्याजयसि।कर्मण्येवाधिकारस्ते इति तामेव च ग्राहयसि। तथानिर्द्वन्द्वो नित्यसत्वस्थो निर्योगक्षेम आत्मवान्भवेति निवृत्तिमार्गमुपदिशसि।धर्म्याद्धि युद्धाच्छ्रेयोऽन्यत्क्षत्रियस्य न विद्यते इति प्रवृत्तिमप्युपदिशसि। नह्येकेन मया युगपदुभयं स्थितिगतिवदनुष्ठातुं शक्यम्। अतो मे मम बुद्धिं मोहयसीव वस्तुतस्तु मम मोहं नाशयितुं प्रवृत्तोऽसीतीवशब्देनोच्यते। तत्तयोर्मध्ये यदेकं प्रधानं मद्योग्यं तन्निश्चित्य वद येनानुष्ठितेनाहं श्रेयः कल्याणमाप्नुयाम्।'),
('nilakantha-sc:source:3.3','Nīlakaṇṭha','gita.3.3','sa','commentary','।।3.3।।अत्रोत्तरं श्रीभगवानुवाच लोकेऽस्मिन्निति। पुरा पूर्वाध्याये मया निष्ठा एकैव प्रोक्ता परंतु सा द्विविधा द्विप्रकारा। एकस्या एव ब्रह्मनिष्ठायाः प्रकारद्वयमुक्तमधिकारिभेदेन न तु ब्रह्मप्राप्तये परस्परनिरपेक्षमार्गद्वयमुक्तमिति भावः। हेऽनघ विशुद्धान्तःकरण मद्वचनस्यार्थं सम्यगालोचयेत्यर्थः। तदेव प्रकारद्वयमाह ज्ञानयोगेनेति। सांख्यानां प्रकृतिपुरुषयोर्विविक्तत्वं जानतामात्मानात्मविवेकज्ञानवतां ज्ञानार्थं युज्यते इति ज्ञानयोगः ज्ञानोपायो वेदान्तश्रवणमनननिदिध्यासनात्मकस्तेन ज्ञानयोगेन ब्रह्मणि निष्ठां परिसमाप्तिं सांख्याः प्राप्नुवन्तीत्यर्थः। योगिनांसिद्ध्यसिद्ध्योः समो भूत्वा समत्वं योग उच्यते इत्युक्तलक्षणयोगवतां कर्मयोगेन संध्योपासनादिनिर्विकल्पकसमाध्यनुष्ठानमिह कर्मयोगपदार्थः तेन योगिनो ब्रह्मनिष्ठां प्राप्नुवन्तीत्यर्थः। अयं भावः इह जन्मनि जन्मान्तरे वा ईश्वरप्रीत्यर्थमनुष्ठितैः कर्मभिर्विशुद्धसत्वो विवेकवैराग्यशमादिषट्कोपेतो मुमुक्षुः प्रत्यक्प्रवणचित्तः श्रवणमननाभ्यामेव कृतकृत्यो भवति स चेच्छ्रवणादेः प्रागसमाहितचित्तस्तर्हि निदिध्यासनमस्यापेक्षितम् अतएवसहकार्यन्तरविधिः पक्षेण इति सूत्रकृता निदिध्यासनस्य पाक्षिकत्वमुक्तं सोऽयं सांख्यमार्गः। तथा सर्वाणि कर्माणि परमगुरावर्पयञ्श्रवणमननात्मकं विचारमन्तरेणैव केवलं श्रद्धामात्रात्प्रतीचो निर्विशेषब्रह्मरूपत्वं गुरुवाक्यतो निश्चित्यासंभावनादिदोषरहित आचार्यान्निर्गुणब्रह्मोपास्तिप्रकारमधिगम्य कर्मच्छिद्रेषु समाध्यभ्यासं कुर्वन्निष्कलं प्रत्यगात्मस्वरूपं साक्षात्करोति सोऽयं योगमार्गः तेन ऊहापोहकौशलं येषामस्ति ते सांख्याः येषां तन्नास्ति ते योगिन इति। अत इयं द्विप्रकारा निष्ठा न तु द्वे निष्ठे इति भ्रमितव्यम्। यथोक्तं वसिष्ठेनद्वौ क्रमौ चित्तनाशस्य योगो ज्ञानं च राघव। योगो वृत्तिनिरोधो हि ज्ञानं सम्यगवेक्षणम्। असाध्यः कस्यचिद्योगः कस्यचित्तत्त्वनिश्चयः। प्रकारौ द्वौ ततो देवो जगाद परमः शिवः। इति। चित्तादर्शनोपलक्षितस्य ब्रह्मसाक्षात्कारस्य द्वौ क्रमौ। चित्तादेर्मिथ्यात्वपक्षे ज्ञानमेव यथा रज्जूरगादिसम्यगवेक्षणेनैव नश्यति तद्वत् तस्य सत्यत्वपक्षे योग एव। यथा सत्य उरगो मन्त्रादिना निरुद्धप्रचारः स्वयमेव नश्यति तद्वच्चित्तमपि योगेन निरुद्ध्यमानं नश्यति। तस्य निरन्वयोच्छेदस्तु प्रारब्धकर्मान्ते पक्षद्वयेऽपि तुल्य इति।'),
('nilakantha-sc:source:3.4','Nīlakaṇṭha','gita.3.4','sa','commentary','।।3.4।।अनयोः प्रकारयोरङ्गाङ्गिभावमाह न कर्मणामिति। कर्मणां यज्ञादीनामनारम्भादननुष्ठानान्नैष्कर्म्यं ज्ञाननिष्ठां नाश्नुते न प्राप्नोति।विविदिषन्ति यज्ञेन इति श्रुत्या यज्ञादीनां विद्याङ्गत्वेन विधानात्। ननु सन्प्रत्ययप्राधान्यात्कर्मणां विविदिषाङ्गत्वमत्र गम्यते। तेन विविदिषायां यज्ञादिना सिद्धायाम्एतमेव प्रव्राजिनो लोकमिच्छन्तः प्रव्रजन्ति इति श्रुतेः प्रव्रज्यारूपमेव नैष्कर्म्यमिह ज्ञाननिष्ठासाधनं ग्राह्यम्। न ज्ञानं नैष्कर्म्यसिद्धिं परमामित्यादाविवात्र तद्ग्राहकस्य परमत्वविशेषणस्याभावात्। ननु कर्मयोगजनितचित्तशुद्ध्यभावे केवलात्संन्यासात्सिद्धिं समधिगच्छतीति योजनायां विप्रकृष्टयोर्ज्ञानकर्मणोः समुच्चयासंभवस्याभीष्टस्य सिद्धेः किमिति नैष्कर्म्यशब्देन निष्ठा गृह्यत इति चेत्सत्यम्। गुणैः कर्मकार्यत इति वाक्यशेषान्नैर्गुण्यहेतुकं मुख्यंज्ञानमेवेह नैष्कर्म्यपदार्थो नतु प्रव्रज्या। विविदिषन्ति यज्ञेनेत्यत्रापि जिगमिषत्यश्वेन जिघांसत्यसिनेत्यादाविव तृतीयान्तस्य धात्वर्थेनैवान्वयादश्वादीनां गमनादाविव यज्ञादीनां वेदन एवान्वयो ज्ञेयः। एतमेवेति श्रुतिस्तु विविदिषासंन्यासाभिप्रायेण प्रवृत्ता।एवं वैतमात्मानं विदित्वा ब्राह्मणाः पुत्रैषणायाश्च वित्तैषणयाश्च लोकैषणायाश्च व्युत्थायाथ भिक्षाचर्यं चरन्ति इति ज्ञानपरिपाकार्थस्य जीवन्मुक्तिसुखार्थस्य वा याज्ञवल्क्यादिभिरनुष्ठितस्य विद्वत्संन्यासस्यापि शास्त्रे दर्शनात्। असंन्यासिनो ज्ञानमेव नोत्पद्यत इति प्राचामाग्रहो विक्षेपककर्मत्यागरूपसंन्यासविषयो न तु काषायपरिधानमात्रविषयः। गार्गीव्याधवासिष्ठादीनामतथाविधानामपि ज्ञानोत्पत्त्यवगमादित्यास्तां तावत्। कर्मभिरशोधितचित्तस्य मन्दबुद्धेः रागद्वेषादिग्रस्तस्यात्मानात्मविवेकद्वारा चित्तरोधद्वारा वा नैष्कर्म्यप्राप्तिर्नस्तीति पूर्वार्धार्थः। ननुअभयं सर्वभूतेभ्यो दत्त्वा नैष्कर्म्यमाचरेत् इति केवलात्कर्मसंन्यासादपि नैष्कर्म्यसिद्धिः स्मर्यते तत्कथमुच्यते न कर्मणामनारम्भान्नैष्कर्म्यमस्तीति तत्राह नचेति। कर्मजचित्तशुद्ध्यभावे कृतादपि संन्यासान्न मोक्षसिद्धिः। उदाहृतस्मृतिस्तु चित्तशुद्धिपूर्वकसंन्यासाभिप्राया। नहि रागादिग्रस्तः सर्वभूतेभ्यः सर्वात्मानाऽभ्यं दातुमीष्टे अतो युक्तमुक्तं न च संन्यसनादेवेति।'),
('nilakantha-sc:source:3.5','Nīlakaṇṭha','gita.3.5','sa','commentary','।।3.5।।एतदेव प्रपञ्चयति नहीति। अवशः कर्मजशुद्ध्यभावादजितचित्तः कश्चिदपि जातु कदाचित्समाधिकालेऽपि क्षणमप्यकर्मकृत् कर्माणि दुर्मनोरथादीन्यकुर्वन् हि प्रसिद्धं न तिष्ठति। हि यस्मात्सर्वोऽपि लोकः प्रकृतिजैर्गुणैः सत्त्वरजस्तमोभिः स्वभावप्रभवैः रागद्वेषादिभिर्वा कर्म कायिकं वाचिकं मानसिकं वा कार्यतेऽवश्यं तत्र प्रवर्त्यते।'),
('nilakantha-sc:source:3.6','Nīlakaṇṭha','gita.3.6','sa','commentary','।।3.6।।ननु संन्यासपूर्वकं ध्यानेनैव चित्तशुद्धिमपि संपादयिष्यामि किं कर्मभिरित्याशङ्क्याह कर्मेन्द्रियाणीति। यो विमूढात्मा रागाद्याक्रान्तचित्तः कर्मेन्द्रियाणि वागादीनि संयम्य निगृह्य आस्ते एकान्ते ध्यानापदेशेनोपविशति स मिथ्याचारः। तस्य तदासननियमनादिकमाचरणं मिथ्या अलीकमेव निष्फलत्वात्। तत्र हेतुः इंद्रियार्थान्मनसा स्मरन्निति। यतः इन्द्रियार्थाञ्शब्दादीञ्श्रोत्रादिभिर्गृह्णाति मनसा च स्मरति अतो मिथ्याचारः स विषयांश्चिन्तयन्योगनिष्ठामात्मनो लोकेऽभिव्यनक्त्यतः कपटीत्यर्थः। तस्मात्कर्मव्यतिरिक्तश्चित्तशुद्ध्युपायो नास्तीति भावः।'),
('nilakantha-sc:source:3.7','Nīlakaṇṭha','gita.3.7','sa','commentary','।।3.7।।यस्तु पूर्वस्मान्मिथ्याचाराद्विलक्षणः पुरुषधौरेयः इन्द्रियाणि मनसा सह नियम्य रागद्वेषवियुक्तानि कृत्वा कर्मेन्द्रियैः कर्मयोगमारभते हे अर्जुन सः कर्मफले स्वर्गादावैहिके वा शब्दादौ असक्तोऽनासक्तोऽतो विशिष्यते। पूर्वस्मादधिको भवतीत्यर्थः।'),
('nilakantha-sc:source:3.8','Nīlakaṇṭha','gita.3.8','sa','commentary','।।3.8।।नियतमिति। यस्मादेवं तस्मात्त्वं नियतं संध्योपासनादिकर्मैव कुरु। यद्वा नियतं नियमेन त्वं कर्म नित्यकाम्यसाधारणं यत्पापनिवर्त्तकस्वभावं तत्तदेव कुरु। हि यस्मादकर्मणः सकलकर्मेन्द्रियनिग्रहेण तदकरणाच्चित्तजयशून्यात्कर्मैव ज्यायः प्रशस्ततरम्। अपि च ते तव क्षत्रियस्य अकर्मणः सत्यामपि चित्तशुद्धौ सर्वकर्मत्यागिनः शरीरयात्रा देहव्यवहारो न प्रसिध्येत्। भैक्ष्यचर्यायामनधिकारात्ब्राह्मणाः पुत्रैषणायाश्च वित्तैषणायाश्च लोकैषणायाश्च व्युत्थायाथ भिक्षाचर्यं चरन्ति इति संन्यासविधायके वाक्येराजा राजसूयेन स्वाराज्यकामो यजेत इत्यत्र राजपदवद्ब्राह्मणपदस्य विवक्षितस्वार्थत्वात्चत्वार आश्रमा ब्राह्मणस्य त्रयो राजन्यस्य द्वौ वैश्यस्य इति स्मृतेश्च। अन्यत्राप्युक्तं पारिव्राज्यं प्रकृत्यमुखजानामयं धर्मो वैष्णवं लिङ्गधारणम्। बाहुजातोरुजातानां नायं धर्मो विधीयते। इति।'),
('nilakantha-sc:source:3.9','Nīlakaṇṭha','gita.3.9','sa','commentary','।।3.9।।ननुकर्मणा बध्यते जन्तुः इति कर्मणां बन्धकत्वस्मृतेः कथं मुमुक्षुं मां तत्र नियोजयसीत्याशङ्क्याह यज्ञार्थादिति। यज्ञः परमेश्वराराधनंयज्ञ देवपूजायाम् इति धात्वर्थानुगमात्। तदर्थंयज्ञो वै विष्णुः इति श्रुतेर्विष्णुर्वा तदाराधनार्थं यत्कर्म ततोऽन्यत्र कर्मणि स्वर्गाद्यर्थे प्रवृत्तोऽयं लोकः कर्मबन्धनः कर्मणा बध्यते नत्वीश्वराराधनार्थेन। अतस्तदर्थं ईश्वराराधनार्थं कर्म वर्णाश्रमोचितं हे कौन्तेय मुक्तसङ्गः फलाभिलाषशून्यः सन् समाचर सम्यक्कुरु।'),
('nilakantha-sc:source:3.10','Nīlakaṇṭha','gita.3.10','sa','commentary','।।3.10।।एतदेवार्थवादेन द्रढयति सहेति। यज्ञैः सहेति सहयज्ञाः।वोपसर्जनस्य इति पक्षे सादेशाभावः। कर्माधिकृता इति यावत्। प्रजास्त्रैवर्णिकाः। अनेन यज्ञेन प्रसविष्यध्वं प्रसवो वृद्धिस्तां लभध्वम्। एष यज्ञो वो युष्माकमिष्टकामधुगिष्टार्थपूरकोऽस्तु।'),
('nilakantha-sc:source:3.11','Nīlakaṇṭha','gita.3.11','sa','commentary','।।3.11।।इष्टार्थपूरकत्वमेवाह देवानिति। भावयत तर्पयत। अनेन देवतापूजात्मकेन यज्ञेन ते वो युष्मान्भावयन्तु वृष्ट्यादिदानेन। परस्परं भावयन्तो देवाश्च यूयं च श्रेयः परं प्राप्स्यथ।'),
('nilakantha-sc:source:3.12','Nīlakaṇṭha','gita.3.12','sa','commentary','।।3.12।।किंच इष्टान्पुत्रपश्वादीन्वो युष्मभ्यम्। एभ्यो देवेभ्यस्तद्दत्तानेव व्रीहिपश्वाज्यादीनप्रदायादत्त्वा देवतोद्देशेन द्रव्यत्यागात्मकं यागं नित्यनैमित्तिकरूपं वैश्वदेवाग्निहोत्रजातेष्ट्यादिरूपमकृत्वेत्यर्थः। अदत्त्वा यो भुङ्क्ते स स्तेन एव।'),
('nilakantha-sc:source:3.13','Nīlakaṇṭha','gita.3.13','sa','commentary','।।3.13।।ये तु यज्ञशिष्टाशिनः वैश्वदेवाविशेषान्नभोजनशीलाः सन्तः ऋणापाकरणात् ते मुच्यन्ते सर्वकिल्बिषैः प्रमादकृतैर्विहिताकरणनिमित्तैः पञ्चसूनानिमित्तैर्वा। ये त्वात्मकारणात्स्वार्थमेव पचन्ति न तु पञ्चमहायज्ञार्थं ते पापाः स्वयं पापरूपा एव सन्तः पापमेव भुञ्जते। तथा च स्मृतिःकण्डनी पेषणी चुल्ली उदकुम्भी च मार्जनी। पञ्च सूना गृहस्थस्य ताभिः स्वर्गं न विन्दति। इतिपञ्चसूनाकृतं पापं पञ्चयज्ञैर्व्यपोहति इति च। श्रुतिश्चइदमेवास्य तत्साधारणमन्नं यदिदमद्यते स य एतदुपासते न स पाप्मनो व्यावर्तते मिश्रं ह्येतत् इति। मन्त्रवर्णोऽपिमोघमन्नं विन्दते अप्रचेताः सत्यं ब्रवीमि वध इत्स तस्य। नार्यमणं पुष्यति नो सखायं केवलाघो भवति केवलादी इति।'),
('nilakantha-sc:source:3.14','Nīlakaṇṭha','gita.3.14','sa','commentary','।।3.14।।जगच्चक्रप्रवृत्तिहेतुत्वादपि कर्म कर्तव्यमित्याह अन्नादिति। अन्नाद्रेतोरूपेण परिणताद्भूतानि प्राणिशरीराणि भवन्ति। अन्नं च पर्जन्यात्। एतत्प्रसिद्धमेव। यज्ञाद्भवति पर्जन्यःअग्नौ प्रास्ताहुतिः सम्यगादित्यमुपतिष्ठते। आदित्याज्जायते वृष्टिर्वृष्टेरन्नं ततः प्रजाः। इति स्मृतेः। यज्ञो देवताराधनजो धर्मः कर्मभ्यो यागहोमदानादिभ्यः समुद्भवतीति कर्मसमुद्भवः।');
INSERT INTO commentary_fts (unit_id,author,canonical_ref,language,content_type,content) VALUES
('nilakantha-sc:source:3.15','Nīlakaṇṭha','gita.3.15','sa','commentary','।।3.15।।कर्म ब्रह्मोद्भवं वेदोद्भवम् वेद एव धर्मे प्रमाणं नतु पाखण्डादिप्रणीतागमः ब्रह्म वेदोप्यक्षरसमुद्भवम्।अस्य महतो भूतस्य निःश्वसितमेतद्यदृग्वेदो यजुर्वेदः इत्यादिश्रुतेः साक्षात्परमेश्वरादेवोत्पन्नः अतो न तत्र भ्रमविप्रलम्भकत्वादिदोषाक्रान्तपाखण्डादिवाक्यवदप्रामाण्यशङ्कास्तीति भावः। यस्मादेवं तस्मात्सर्वस्मिन्देशे काले च वर्तमानं ब्रह्म वेदः। एतेन वेदस्य नित्यत्वं शब्दस्य विभुत्वं च दर्शितम्। नित्यं नियमेन यज्ञे प्रतिष्ठितं तात्पर्येण पर्यवसन्नम्।'),
('nilakantha-sc:source:3.16','Nīlakaṇṭha','gita.3.16','sa','commentary','।।3.16।।भवत्वेवं ततः किं फलितमित्यत आह एवमिति। भूतानामादौ वेदाधिगमस्ततः कर्मानुष्ठानं ततो देवानां तृप्तिस्ततो वृष्टिस्ततोऽन्नं ततो भूतानि तेषां वेदाधिगम इत्येवंरूपं चक्रमिव चक्रं निरन्तरमावर्तमानं जगद्यात्रानिर्वाहक नानुवर्तयति नानुतिष्ठति सोऽघायुः पापजीवनः इन्द्रियारामो न तु धर्माराम आत्मारामो वा मोघं व्यर्थं दंशमशकादिवज्जीवति। यस्त्वेतदनुवर्तयति स जगदुपकारको धन्य इति भावः। तथा च श्रुतिःअथो अयं वा आत्मा सर्वेषां भूतानां लोकः स यज्जुहोति यद्यजते तेन देवानां लोकोऽथ यदनुब्रूते तेन ऋषीणामथ यत्पितृभ्यो निपृणाति यत्प्रजामिच्छति तेन पितृ़णामथ यन्मनुष्यान्वासयते यदेभ्योऽशनं ददाति तेन मनुष्याणामथ यत्पशुभ्यस्तृणोदकं विन्दति तेन पशूनां यदस्य गृहेषु श्वापदो वयांस्यापिपीलिकाभ्य उपजीवन्ति तेन तेषां लोकः इति।'),
('nilakantha-sc:source:3.17','Nīlakaṇṭha','gita.3.17','sa','commentary','।।3.17।।एवमीश्वरेण वेदयज्ञपूर्वकं जगच्चक्रं प्रवर्तितमज्ञैरधिकृतैरनुवर्तितव्यमित्युक्तम्। अस्यानुवर्तने च महान्प्रत्यवाय उक्तः। स ब्रह्मविदमपि स्पृशेदिति संभावितामाशङ्कां परिहरति यस्त्विति। आत्मन्येव रतिः प्रीतिर्यस्य नतु स्त्र्यादौ स तथा। नन्वात्मनि प्रीतिः प्राणिमात्रस्यानौपाधिक्यस्ति प्रत्युत तदर्थत्वेनैव स्त्र्यादिष्वपिप्रीतिर्भवतीत्यत उक्तम् आत्मतृप्त इति। आत्मनैव परमानन्दरूपेण तृप्तो न मिष्टान्नादिना। ननु मन्दाग्निरपि स्त्र्यादौ न रमते नापि मिष्टान्नेन तृप्यत्यत उक्तं आत्मन्नेव च संतुष्ट इति। मन्दाग्निर्हि धातुवृद्धिं जाठरोद्दीपनं च कामयमान औषधाद्यर्थमितस्ततो धावति नत्वात्मन्येव तुष्यति विद्वांस्तु रतितृप्तितुष्टीरात्मनैवानुभवति न स्त्र्यन्नधनादिभिरिति तस्य कार्यं कर्तव्यं किमपि नास्ति। क्रियाप्राप्यस्य कस्यचिदप्यर्थस्याभावात्।'),
('nilakantha-sc:source:3.18','Nīlakaṇṭha','gita.3.18','sa','commentary','।।3.18।।एतदेवाह नैवेति। तस्यात्मरतेः कृतेन कर्मणार्थः प्रयोजनं नास्ति। स्वर्गादौ लिप्साभावात्। मोक्षस्य चाक्रियासाध्यत्वात्नास्त्यकृतः कृतेन इति श्रुतेः। अकृतो मोक्षः कृतेन कर्मणा नास्तीति श्रुत्यर्थः। अकृतेन विरुद्धकर्मणाप्यर्थो नरकादिरस्य नास्ति। अत्र कृताकृतशब्दौ मित्रामित्रपदवत्परस्परविरुद्धार्थवाचितया पुण्यपापवचनौ। ये तु अकृतेनेति भावे निष्ठा। नित्याकरणाद्गर्हितत्वरूपो वा प्रत्यवायप्राप्तिरूपो वा कश्चनार्थो विदुषो नास्तीति व्याचक्षते। तेषामप्यभावात् भावोत्पत्तेरनभ्युपगमान्नित्यानां काले यदन्यदविहितं क्रियते तत एव प्रत्यवायोत्पादो वक्तव्य इति घट्टकुट्यां प्रभातवृत्तान्त आपद्यते। अत्रोपपत्तिमाह न चेति। चो हेतौ। यस्मादात्मरतेः सर्वभूतेषु चेतनाचेतनेषूत्तममध्यमाधमेषु कश्चिदप्यर्थव्यपाश्रयः सुखभोगात्मकप्रयोजनाभिसंबन्धो नास्ति आत्मरतित्वादेव निष्कामत्वाद्विदुषः पुण्यपापफलसंबन्धो नास्तीत्यर्थः।'),
('nilakantha-sc:source:3.19','Nīlakaṇṭha','gita.3.19','sa','commentary','।।3.19।।यस्मान्निष्कामस्य कर्मलेपो नास्ति तस्मात्त्वमप्यसक्तः फलासक्तिशून्यः सततं सर्वदा कार्यमवश्यकर्तव्यं कर्म नित्यनैमित्तिकं समाचर। हि यस्मादसक्तः कर्माचरन् परं मोक्षं सत्त्वशुद्धिद्वारेणाप्नोति।'),
('nilakantha-sc:source:3.20','Nīlakaṇṭha','gita.3.20','sa','commentary','।।3.20 3.21।।अत्र शिष्टाचारं प्रमाणयति कर्मणेति। कर्मणैव सह संसिद्धिं श्रवणादिसाध्यां ज्ञाननिष्ठां गन्तुमास्थिताः प्रवृत्ता जनकादयस्त्वादृशाः क्षत्रियाः न तु संन्यासेन। ननु शुद्धचित्तस्य मम नास्ति कर्मापेक्षेत्याशङ्क्याह लोकेति। लोकस्य संग्रहः स्वधर्मे प्रवर्तनम्। ननु स्वप्रयोजनाभावेऽपि केवलं लोकसंग्रहार्थं चेत्कर्म कर्तव्यं तदा विदुषां ब्राह्मणानामपि संन्यासो न स्यात्। यतीनेव संन्यासधर्मान्ग्राहयितुं तेषां संन्यास इति चेत् अर्जुनेऽपि न तद्दंडवारितमस्ति। ननु क्षत्रियस्य संन्यासेऽधिकारो नास्तीति चेत् लिङ्गधारणेऽधिकाराभावेऽपि भरतऋषभादिवद्विक्षेपकर्मत्यागमात्रेऽधिकारात्। वार्तिकेसर्वाधिकारविच्छेदि ज्ञानं चेदभ्युपेयते। कुतोऽधिकारनियमो व्युत्थाने क्रियते बलात्। इति विद्वत्संन्यासे क्षत्रियादेरप्यधिकारस्य साधितत्वात्। अतो लोकसंग्रहो न मुख्यं कर्मप्रयोजनमिति चेत्सत्यम्।न मे पार्थास्ति कर्तव्यम् इति स्वदृष्टान्तेनाधिकारिकत्वादर्जुन एवैवं नियोज्यते न क्षत्रियमात्रमिति तुष्यतु भवान्।'),
('nilakantha-sc:source:3.21','Nīlakaṇṭha','gita.3.21','sa','commentary','।।3.20 3.21।।अत्र शिष्टाचारं प्रमाणयति कर्मणेति। कर्मणैव सह संसिद्धिं श्रवणादिसाध्यां ज्ञाननिष्ठां गन्तुमास्थिताः प्रवृत्ता जनकादयस्त्वादृशाः क्षत्रियाः न तु संन्यासेन। ननु शुद्धचित्तस्य मम नास्ति कर्मापेक्षेत्याशङ्क्याह लोकेति। लोकस्य संग्रहः स्वधर्मे प्रवर्तनम्। ननु स्वप्रयोजनाभावेऽपि केवलं लोकसंग्रहार्थं चेत्कर्म कर्तव्यं तदा विदुषां ब्राह्मणानामपि संन्यासो न स्यात्। यतीनेव संन्यासधर्मान्ग्राहयितुं तेषां संन्यास इति चेत् अर्जुनेऽपि न तद्दंडवारितमस्ति। ननु क्षत्रियस्य संन्यासेऽधिकारो नास्तीति चेत् लिङ्गधारणेऽधिकाराभावेऽपि भरतऋषभादिवद्विक्षेपकर्मत्यागमात्रेऽधिकारात्। वार्तिकेसर्वाधिकारविच्छेदि ज्ञानं चेदभ्युपेयते। कुतोऽधिकारनियमो व्युत्थाने क्रियते बलात्। इति विद्वत्संन्यासे क्षत्रियादेरप्यधिकारस्य साधितत्वात्। अतो लोकसंग्रहो न मुख्यं कर्मप्रयोजनमिति चेत्सत्यम्।न मे पार्थास्ति कर्तव्यम् इति स्वदृष्टान्तेनाधिकारिकत्वादर्जुन एवैवं नियोज्यते न क्षत्रियमात्रमिति तुष्यतु भवान्।'),
('nilakantha-sc:source:3.22','Nīlakaṇṭha','gita.3.22','sa','commentary','।।3.22।।कर्मणि वर्ते एव। अहं कर्म करोम्येवेत्यर्थः।'),
('nilakantha-sc:source:3.23','Nīlakaṇṭha','gita.3.23','sa','commentary','।।3.23।।यद्यहं कर्मणि न वर्तेयं तर्हि मनुष्याः ममैव वर्त्मानुवर्तन्ते अनुवर्तेरन्। कर्म न कुर्वीरन्नित्यर्थः। अतन्द्रितोऽनलसः। सर्वशः सर्वप्रकारैः।'),
('nilakantha-sc:source:3.24','Nīlakaṇṭha','gita.3.24','sa','commentary','।।3.24।।ततश्च किमित्यत आह उत्सीदेयुरिति। यद्यदाचरतीत्यादेरपरा योजना। न केवलं लोकसंग्रहंपश्यन् कर्तुमर्हसि अपितु श्रेष्ठाचारत्वादपीत्याह यद्यदिति। तथा च मम श्रेष्ठस्य यादृश आचारस्तादृश एव मदनुवर्तिना त्वयानुष्ठेयः न स्वातन्त्र्येणान्य इत्यर्थः। कीदृशस्तवाचारो यो मयानुवर्तनीय इत्याकाङ्क्षायां न मे पार्थेत्यादिभिस्त्रिभिः श्लोकैस्तत्प्रदर्शनमिति मधुसूदनश्रीपादाः।'),
('nilakantha-sc:source:3.25','Nīlakaṇṭha','gita.3.25','sa','commentary','।।3.25।।यदि मादृश एव त्वं कृतार्थोऽसि तथापि परानुग्रहार्थं कर्माणि कुर्वित्याह सक्ता इति। कर्मणि कर्मफले। कुर्वन्ति कर्माणीति शेषः। असक्त इति च्छेदः।'),
('nilakantha-sc:source:3.26','Nīlakaṇṭha','gita.3.26','sa','commentary','।।3.26।।विद्वान् अज्ञानां कर्मस्वासक्तानां बुद्धिभेदं बुद्धेश्चालनं न जनयेन्नोत्पादयेत् किंतु तान्सर्वाणि कर्माणि जोषयेत्सेवयेत्। कथम्। युक्त आदृतो भूत्वा समाचरन्।'),
('nilakantha-sc:source:3.27','Nīlakaṇṭha','gita.3.27','sa','commentary','।।3.27।।अविद्वान्कथं कर्मसु सज्जत इत्यत आह प्रकृतेरिति। प्रकृतेः पारमेश्वर्याः सत्वरजस्तमोगुणात्मिकायाःदेवात्मशक्तिं स्वगुणैर्निगूढाम् इति श्रुतिप्रसिद्धायाः शक्तेर्गुणैः कार्यकारणसंघातात्मकैः क्रियमाणानि कर्माणि अहंकारेण स्वस्मिन्नध्यस्तेन विमूढः तदीयान्कर्तृत्वादीनात्मधर्मत्वेन पश्यन् आत्मनश्चासङ्गानन्दसंविद्रूपतामपश्यन्नात्मा अहंकारेण विमूढश्चासावात्मा चेति विग्रहः। अहं कर्माणि करोमि कर्मणां कर्तेति मन्यते कर्त्रध्यासेन। कर्ताहमिति तृन्प्रत्ययस्तेननलोकाव्ययनिष्ठाखलर्थतृनाम् इति षष्ठीनिषेधः। अन्यथा तृच्प्रत्यये कर्मणां कर्ताहमिति षष्ठ्या भाव्यम्।'),
('nilakantha-sc:source:3.28','Nīlakaṇṭha','gita.3.28','sa','commentary','।।3.28।।एवं सक्तस्य कर्माचरणं प्रदर्श्यासक्तस्य तत्प्रदर्शयति तत्त्वविदिति। गुणकर्मविभागयोः गुणविभागस्य कर्मविभागस्य च तत्त्वविदिति भाष्यम्। नाहं गुणात्मक इति गुणेभ्य आत्मनो विभागः नाहं कर्मात्मक इति कर्मभ्यश्चात्मनो विभागः तयोर्गुणकर्मविभागयोस्तत्त्वं वेत्तीति श्रीधरः। मधुसूदनस्तु गुणाः देहेन्द्रियान्तःकरणान्यहंकारास्पदानि। कर्माणि च तेषां व्यापारभूतानि ममकारास्पदानि। गुणकर्मेति द्वन्द्वैकवद्भावः। विभज्यते सर्वेषां जडानां भासकत्वेन पृथग्भवतीति विभागः स्वप्रकाशज्ञानरूपोऽसङ्ग आत्मा। गुणकर्म च विभागश्चेति द्वन्द्वः। तयोर्जडाजडयोस्तत्त्वं यो वेत्ति सः गुणाः करणात्मकाः गुणेषु विषयेषु वर्तन्ते इति मत्वा न सज्जते। कर्तृत्वाभिनिवेशं न करोतीत्यर्थः। गुणविभागस्य कर्मविभागस्य च तत्त्वविदिति पक्षे गुणकर्मणोरित्येव सिद्धे विभागपदं व्यर्थमिति। यद्वा यस्तत्त्ववित् स गुणाः गुणेषु वर्तन्त इति मत्वा गुणविभागे कर्मविभागे च न सज्जते इति योजना। गुणानां सत्त्वरजस्तमसां विभागो बुद्ध्यहंकारज्ञानेन्द्रियकर्मेन्द्रियविषयरूपेण विभज्यावस्थानं तस्मिन्न सज्जते इदमहमिति न मन्यते। तथाहि शरीरे गौरेऽहं गौरोऽस्मि हस्ताभ्यामात्ते मयेदमात्तमिति चक्षुषा दृष्टे मयेदं दृष्टमित्यहंकारेणाभिमते ममेदमित्यभिमन्यते। बुद्धौ विक्रियमाणायामहं सुखीति च सर्वेषु बुद्ध्यादिषु विभज्य गृह्यमाणेष्वपि प्रत्येकं प्रत्यक्त्वमध्यस्याहमिदमिति ममेदं कर्मेति च मन्यते। एतेन कर्मविभागोऽप्यावश्यकत्वेन व्याख्यातः। अन्यथा चिदात्मन्येवादनादिकर्तृत्वं दुःखादिमत्त्वं चापतति। अयं च कर्मविभागः श्रुत्यापि दर्शितःअन्धो मणिमविन्दत्। तमनङ्गुलिरावयत्। अग्रीवः प्रत्यमुञ्चत्। तमजिह्वो असश्चत् इति। अन्धः स्वयं प्रकाशहीनोऽपि चक्षुरादिर्मणिं रूपादिकं विषयमविन्दत्प्रकाशयति। अनङ्गुलिः काष्ठलोष्ठादिवज्जडत्वात् स्वयं कर्म कर्तुमशक्तोऽपि पाण्यादिः आवयदासीव्यत् विषयमुपादत्ते। अग्रीवः छिन्नशिरस्कवन्निर्जीवोऽहंकारस्तं प्रत्यमुञ्चत् ग्रीवायां धारयति मयेदं लब्धमिति मन्यते। अजिह्वो धीधातुः जडत्वात्स्वयं स्वगतसुखदुःखयोः पट इव स्वगतरूपादेः प्रकाशनेऽसमर्थोऽप्यहं सुखी दुःखीति चानुभवति। तथाचात्मानात्मनोर्याथात्म्यज्ञो व्यावृत्तेष्वहंकारादिषु तत्कर्मसु चाभिमानादिषु कुसुमेषु सूत्रमिवानुवर्तमानमात्मानं तेभ्यः पृथग्भूतं जानन् गुणा धीचक्षुरादयो गुणेषु दुःखरूपादिषु वर्तन्ते न त्वात्मेति मत्वा न सज्जतेऽहमेव हस्तादिसंघातरूपो ममैवेदमादानादिकं कर्मेति न सक्तो भवतीत्यर्थः।'),
('nilakantha-sc:source:3.29','Nīlakaṇṭha','gita.3.29','sa','commentary','।।3.29।।एवं सक्तासक्तयोः कर्माणि विभज्य सक्तकर्मानुवादपूर्वकं न बुद्धिभेदं जनयेदज्ञानामित्युपक्रान्तमुपसंहरति प्रकृतेरिति। गुणैरहंकारादिभिः स्वस्मिन्नध्यस्तैः संमूढाः एकीभावेनाभेदाध्यासेन मूढास्तु प्रकृतेः प्रकृतिसंबन्धिषु गुणेषु देहादिषु कर्मसु गमनादिषु च सज्जन्ते अहमयं ब्राह्मणो ममैवेदं यज्ञादिकं कर्मेति सज्जन्ते सक्ता भवन्ति तान् मूढत्वात् अकृत्स्नविदः आत्मज्ञानहीनान्आत्मविद्धि कृत्स्नवित्।आत्मनो वा अरे दर्शनेन श्रवणेन मत्या विज्ञानेनेदं सर्वं विदितम् इति श्रुतेः। मन्दाञ्शास्त्रार्थग्रहणासमर्थान्। कृत्स्नविदात्मविन्न विचालयेत्कर्मनिष्ठातो न प्रच्यावयेत्। तेषामुभयभ्रष्टत्वापत्तेः प्रकृतेर्गुणैः संमूढाः गुणानां कर्मसु सज्जन्त इति प्राचां योजना।'),
('nilakantha-sc:source:3.30','Nīlakaṇṭha','gita.3.30','sa','commentary','।।3.30।।मयीति। त्वं तु अज्ञो मुमुक्षुश्च मयि सर्वान्तर्यामिणि सर्वाणि कर्माणि संन्यस्य समर्प्य अध्यात्मचेतसा आत्मानमधिकृत्य प्रवृत्तं शास्त्रमध्यात्मं तत्र प्रवणेन चेतसा। शाकपार्थिवादिवन्मध्यमपदलोपी समासः। आत्मानात्मविवेकवतेत्यर्थः। ईश्वरप्रेरितोऽहं करोमीत्यनया बुद्ध्या निराशीः फलमनिच्छन् निर्ममो लब्धे ममत्वाभिमानशून्यश्च भूत्वा युध्यस्व विगतज्वरो विशोकः सन्।'),
('nilakantha-sc:source:3.31','Nīlakaṇṭha','gita.3.31','sa','commentary','।।3.31।।ये म इति। येऽन्येऽपि त्वादृशाः मे मम मतमसक्त्या कर्मानुष्ठानं अनुतिष्ठन्त्यनुवर्तन्ते मानवाः श्रद्धावन्तः अनसूयन्तः अत्र दोषमपश्यन्तः तेऽपि स्वकर्मभिर्धर्माधर्माख्यैर्मुच्यन्ते।'),
('nilakantha-sc:source:3.32','Nīlakaṇṭha','gita.3.32','sa','commentary','।।3.32।।विपक्षे दोषमाह येत्विति। सर्वशब्द ईश्वरवाची।सर्वं समाप्नोषि ततोऽसि सर्वः इति निर्वचनात्। तस्य ज्ञाने विषये विशेषेण मूढान्पारोक्ष्येणापि ते ईश्वरमजानन्तो देहमात्रनिष्ठास्तान् नष्टान्स्वर्गापवर्गभ्रष्टान् अचेतसः विवेकशून्यान्।'),
('nilakantha-sc:source:3.33','Nīlakaṇṭha','gita.3.33','sa','commentary','।।3.33।।ननु ते चेत्तव मतं नानुतिष्ठन्ति तर्हि कथं तवान्तर्यामित्वमित्यत आह सदृशमिति। स्वस्याः प्रकृतेः स्वकीयस्य प्राग्भवीयधर्माधर्मसंस्कारस्य सदृशमनुरूपं ज्ञानवानपि चेष्टते किमु मूर्खः।पश्वादिभिश्चाविशेषात् इति न्यायात्। तस्मात्प्रकृतिं यान्त्यनुसरन्ति भूतानि प्राणिनस्तत्र मम वान्यस्य वा निग्रहः किं करिष्यति न किमपि। अहमपि पूर्वकर्मापेक्षयैव तान्प्रवर्तयामीति भावः।'),
('nilakantha-sc:source:3.34','Nīlakaṇṭha','gita.3.34','sa','commentary','।।3.34।।एवं तर्हि पुरुषस्य स्वातन्त्र्याभावाद्विधिनिषेधशास्त्रं व्यर्थमित्याशङ्क्याह इन्द्रियस्येति। इन्द्रियस्येन्द्रियस्येति द्विर्वचनं वीप्सायाम्। प्रतीन्द्रियं स्वे स्वेऽर्थे शब्दादौ वचनादौ च विषये रागद्वेषौ अनुकूले रागः प्रतिकूले द्वेषश्च व्यवस्थितौ नित्यसंबद्धौ तत्र तयोर्वशं नागच्छेदिति शास्त्रस्याभ्यनुज्ञा। पुरुषस्य च तदनुष्ठाने स्वातन्त्र्यमस्ति। हि यतः तौ रागद्वेषावेवास्य प्राणिनः परिपन्थिनौ विरोधिनौ दृष्टद्वारेण प्रवर्तकत्वात्। न तु प्रकृत्यनुसारी ईश्वरोऽस्य परिपन्थी। तस्य वैषम्यादिदोषापत्तेः। अयं भावः यथा ह्यस्तनेन स्वाज्ञोल्लङ्घनजेनापराधेन कुपितो राजाऽपराधिनं हि निगडादौ निग्रहीतुं स्वीयान्भटान्प्रवर्तयति स एवाद्यतनेन दानमानेन प्रसादित एनं तेषामेव भटानामाधिपत्ये नियुङ्क्ते। एवं पूर्वकर्मानुसारी ईश्वरो रागादिद्वारा पुरुषं बाधमानोऽपि विधिप्रतिषेधशास्त्रानुसारिणा तेनैव भक्ति ध्यानप्रणिधानेनावर्जितः एनं रागादिजये नियुङ्क्ते तस्माद्विधिप्रतिषेधशास्त्रस्य नानर्थक्यम्। पुरुषस्य स्वातन्त्र्यसत्त्वात्। नापीश्वरे वैषम्यादिकम्। प्राणिकर्मायत्तत्वादिति।'),
('nilakantha-sc:source:3.35','Nīlakaṇṭha','gita.3.35','sa','commentary','।।3.35।।यस्मादेवं तस्माच्छ्रेयान्प्रशस्यतरः स्वधर्मः स्वस्य वर्णाश्रमानुरूप्येण ईश्वरेण विहितत्वात्। विगुणो हिंसादिमिश्रोऽपि किंचिदङ्गहीनोऽपि परधर्माद्धिंसादिदोषरहितपरधर्मापेक्षया स्वनुष्ठितात्सर्वाङ्गोपसंहारेण सम्यगनुष्ठितादपि स एव श्रेयान्। स्वधर्मे युद्धादौ निधनं मरणमपि श्रेयः। विहितत्वात्। परस्य धर्मो भैक्षचर्यादिर्भयावहः। क्षत्रियस्य तव निषिद्धत्वात्। तस्मात्स्वतन्त्रेण त्वया स्वधर्म एवानुष्ठेय इति भावः।'),
('nilakantha-sc:source:3.36','Nīlakaṇṭha','gita.3.36','sa','commentary','।।3.36।।ईश्वरो धर्माधर्मौ रागद्वेषौ वा पुरुषस्य प्रवर्तकौ भवत इत्यात्मनोऽस्वातन्त्र्यं मन्वानोऽर्जुन उवाच अथ केनेति। केन ईश्वरादीनामन्यतमेनान्येन वा प्रयुक्तः प्रवर्तितः सन् अयं पुरुषः पापमनिष्टं चरति करोति। अनिच्छन्नित्यनेन रागद्वेषयोः प्रवर्तकत्वं निरस्तम्। सति हि रागे इच्छा भवति। अत इच्छाया अभावाद्रागाभावः। रागस्याप्रवर्तकत्वे तन्मूलभूतसंस्कारहेत्वोर्धर्माधर्मयोरप्रवर्तकत्वं ततश्च तत्सापेक्षस्य ईश्वरस्यापीति सर्वेषामाक्षेपः। तस्मान्मुख्यं प्रवर्तकं यत्तद्वाच्यमित्यर्थः। बलादिव नियोजितः विष्टिगृहीत इवेत्यर्थः।'),
('nilakantha-sc:source:3.37','Nīlakaṇṭha','gita.3.37','sa','commentary','।।3.37।।अत्रोत्तरंकाममय एवायं पुरुष इत्यादिश्रुतिसिद्धं भगवानुवाच काम एष इति। एष प्रसिद्धः कामःसोऽकामयत जाया मे स्यादथ प्रजायेयाथ वित्तं मे स्यादथ कर्म कुर्वीयेति श्रुतेरिदं मे भूयादिदं मे भूयात् इति तीव्राभिलाषहेतुभूतश्चेतसोऽनवस्थितत्वापादको वृत्तिविशेषः। स च चेतोरूप एव।कामः संकल्पः इत्युपक्रम्यएतत्सर्वं मनः इत्युपसंहारात् स एष कामः केनचिन्निमित्तेन प्रतिहतः क्रोधरूपेण परिणमतेऽतः क्रोधोऽभिज्वलनात्माप्येष एव तमेनमिह शरीरेऽन्तःस्थितं वैरिणं विद्धि। कुतो वैरी। यतः रजोगुणसमुद्भवः रजो रञ्जनात्मकः प्राकृतो गुणः तस्य गुणौ कार्यभूतौ तृष्णासङ्गौ तावेवोद्भवो यस्य सः। रजःकार्यत्वात् दुःखैकफलोऽयमतो वैरी। यद्वा रजोगुणस्य लोभप्रवृत्त्यादिलक्षणस्य समुद्भवो यस्मात्। ननु विषयाभिलाषात्मकः कामो विषयार्पणेन शाम्यति। विषयस्य दौर्लभ्यनिश्चये स्वत एव वा निवर्तते अन्ध इव रूपदर्शनाभिलाषादित्याशङ्क्याह महाशनो महापाप्मेति। महद्दातुमपारणीयमशनमस्य स तथा। यथोक्तंन जातु कामः कामानामुपभोगेन शाम्यति। हविषा कृष्णवर्त्मेव भूय एवाभिवर्धते इति।यत्पृथिव्यां व्रीहियवं हिरण्यं पशवः स्त्रियः। नालमेकस्य तत्सर्वमिति मत्वा शमं व्रजेत् इति। तथा महापाप्मात्युग्रः। स हि सहस्रशः प्रबोधितोऽपि न निवर्तते तद्वदयमपि दुश्चिकित्स्यः। महाशनत्वान्नायं वैरी दानसाध्यः। नापि सामभेदसाध्यः। अत्युग्रत्वात्। अतो हन्तव्य एवेति।'),
('nilakantha-sc:source:3.38','Nīlakaṇṭha','gita.3.38','sa','commentary','।।3.38।।अस्य वैरित्वमेव विवृणोति धूमेनेत्यादिना। उल्बेन गर्भवेष्टनेन जरायुणा। तेन कामेन इदं वक्ष्यमाणं ज्ञानमावृतम्। आवरणीयस्य त्रैविध्यात्तदनुगुणं दृष्टान्तत्रयं ज्ञेयम्।'),
('nilakantha-sc:source:3.39','Nīlakaṇṭha','gita.3.39','sa','commentary','।।3.39।।आवृतमिति। ज्ञानमन्तःकरणसत्त्वम्ह्रीर्धीर्भीरित्येतत्सर्वं मन एव इति श्रुतेः। एतेन कामेन रजोगुणात्मकेनावृतम्। ज्ञानिनोऽन्तःकरणविशिष्टस्य प्रमातुः नित्यवैरिणा कामरूपेण दुष्पूरेण पूरयितुमयोग्येन। अयं हि पूर्यमाणोऽनर्थानेव प्रसवेत्। अनलेन अथापि पूर्यते चेत् अनलः नास्त्यलं पर्याप्तिर्यस्य स तथा तेनानलेन। न ह्यनलः काष्ठैस्तर्पयितुं शक्यः किंतु वर्धत एव तद्वदयमपीत्यर्थः। अयं भावः अन्तःकरणसत्वं हि वह्निवत्प्रकाशात्मकं तत्सहजेन कामेन वह्निरिव धूमेनावृतं चेत्प्रमातारमनर्थे पातयति। अन्यथा तदेव स्वभावशुद्धत्वाद्विवेकवैराग्योपगं भूत्वा तमुद्धरेत्। अतोऽयं कामो ज्ञानिनो नित्यवैरीति।'),
('nilakantha-sc:source:3.40','Nīlakaṇṭha','gita.3.40','sa','commentary','।।3.40।।किंच इन्द्रियाणीति। अयमर्थः इन्द्रियमनोबुद्धयो हि कामेनाधिष्ठिता बाह्यार्थप्रवणा भवन्ति। तैश्च तथाभूतैरयं कामो ज्ञानं चिदाकाशरूपमादर्शतलप्रख्यम्। यत्र योगिनो व्यवहितं विप्रकृष्टमतीतमनागतं वा पश्यन्ति। यथोक्तमाचार्यैःविश्वं दर्पणदृश्यमाननगरीतुल्यं निजान्तर्गतम्। पश्यन्त्यात्मनि इति निजान्तर्गतं शरीरान्तर्गतं आत्मनि हार्दाकाशाख्ये ब्रह्मणि तत् मलेनादर्शमिवावृत्य देहिनं देहाभिमानिनं विशेषेण मोहयति। विशब्दाद्देहाभिमानशून्यं योगिनमपि व्युत्थानावस्थायां किंचिन्मोहयतीति गम्यत इति। अक्षरयोजना स्पष्टा।'),
('nilakantha-sc:source:3.41','Nīlakaṇṭha','gita.3.41','sa','commentary','।।3.41।।तस्मादिति। यस्मादिन्द्रियाण्यस्याधिष्ठानं सामान्तस्येव गिरिदुर्गादिकं तस्मात्तान्येव नियम्य वशीकृत्य एनं कामं हि निश्चयेन प्रजहि प्रकर्षेण नाशय। गिरिदुर्गादीन्स्वायत्तीकृत्येव तत्स्थं सामन्तं घ्नन्ति राजानस्तद्वत्। हन्तव्यत्वे हेतुः पाप्मानमत्युग्रम्। तत्रापि हेतुः ज्ञानविज्ञाननाशनमिति। ज्ञानस्य शास्त्राचार्योपदेशजस्य परोक्षस्य विज्ञानस्य निदिध्यासनपरिपाकजस्यापरोक्षस्य च नाशनम्।'),
('nilakantha-sc:source:3.42','Nīlakaṇṭha','gita.3.42','sa','commentary','।।3.42।।न केवलं बाह्येन्द्रियजयनैव कृतार्थत्वं किंतु मनोबुद्ध्योरपि जयः कर्तव्यः कामस्य समूलोच्छेदाय। त्रिप्राकारदुर्गस्थस्य सामन्तस्येवाभ्यन्तरप्राकारद्वयजयेन। अतो मनोबुद्ध्योर्जयार्थं योगं दर्शयति इन्द्रियाणीति। अत्र परत्वं सूक्ष्मत्वेन कारणत्वेन वा बोध्यम्। इन्द्रियाणि चक्षुरादीनि पराणि स्वविषयेभ्यः पृथिव्यादिस्वाश्रयसहितेभ्यो गन्धादिभ्यो वित्तपुत्रशरीरेभ्यश्च तेषां तत्कारणत्वात्। तथा च कौषीतकिनः समामनन्ति ब्राह्मणेप्राणेभ्यो देवा देवेभ्यो लोकाः इति। व्युच्चरन्तीत्यनुषज्ज्यते। प्राणेभ्य इन्द्रियेभ्यो देवास्तदधिष्ठात्र्यो देवता उत्पद्यन्ते देवेभ्यश्च लोका भूतभौतिका उत्पद्यन्त इति श्रुत्यर्थः।इन्द्रियेभ्यः परं मनःमनसा ह्येव पश्यति मनसा शृणोति इति श्रुतेरिन्द्रियाणां मनोविकारत्वात्। तेन बाह्यार्थेभ्य इन्द्रियाण्याकृष्य मनसि प्रविलापनीयानीति दर्शितम्। केवलं परत्वमात्रप्रतिपादने प्रयोजनाभावात्मनसस्तु परा बुद्धिःतस्माद्वाएतस्मान्मनोमयात् अन्योन्तर आत्मा विज्ञानमयः इति श्रुतेः। मनसः प्रविलापनं तत्कारणे बुद्धौ कर्तव्यमित्यर्थः। समष्टिबुद्धेरप्यत्रैवान्तर्भावः।यो बुद्धेः परतस्तु सः। यस्तु। तु शब्दो भास्यवर्गाद्बुद्ध्यादेर्भासकस्य ज्ञानस्य वैलक्षण्यं गमयति। यो बुद्धेरपि परतः स ज्ञानपदाभिधेयः कामेन उल्बेन गर्भ इव आवृत इति व्यवहितेन संबन्धः। तथा च श्रुतिःयच्छेद्वाङ्मनसी प्राज्ञस्तद्यच्छेज्ज्ञानमात्मनि। ज्ञानमात्मनि महति तद्यच्छेच्छान्त आत्मनि इति। एतदुक्तं भवति वागादिबाह्येन्द्रियव्यापारमुत्सृज्य मनोमात्रेणावतिष्ठेत। मनोऽपि विषयविकल्पाभिमुखं ज्ञानात्मशब्दोदितायां बुद्धौ धारयेत्। तामपि महत्यात्मनि समष्टिबुद्धौ धारयेत्। ततं तं महान्तमात्मानं शान्ते निष्कले परस्मिञ्जयोतिषि प्रत्यगात्मनि धारयेदिति।'),
('nilakantha-sc:source:3.43','Nīlakaṇṭha','gita.3.43','sa','commentary','।।3.43।।योगफलमाह एवमिति। आत्मानं मनः हार्दाकाशेऽपि तत्स्थान्नित्यान्कामान्कामयानम्। श्रूयते हि दहरविद्यायां हार्दाकाशं प्रकृत्ययच्चास्येहास्ति यच्च नास्ति सर्वं तदत्र गत्वा विन्दते इति तत्रत्यानां कामानां सत्त्वम्। तेषां च सत्यत्वंत इमे सत्याः कामाः इति श्रुतेः। आत्मानं मनः आत्मना मनसैव बुद्ध्यैव वा संस्तभ्य निर्वृत्तिकं कृत्वा बुद्धेः परं परमात्मानं बुद्ध्वा समूलघातं कामरूपं शत्रुं शातयितारं जहि नाशय। हे महाबाहो इति संबोधयंस्तन्नाशे तव सामर्थ्यमस्तीति दर्शयति। अयमर्थः यावत्काममूलस्याज्ञानस्योच्छेद आत्मतत्त्वज्ञानेन क्रियते तावत्पर्यन्तं कामस्य निर्मूलोच्छेदो न भवतीति बुद्धेः परं बुद्ध्वा कामो नाशनीयः। तस्मिंश्च नष्टे संसारानर्थोच्छेदो भवतीति। दुरासदं परबोधं विना दुःखेनापि नाशयितुमशक्यम्।उपायः कर्मनिष्ठात्र प्राधान्येनोपसंहृता। उपेया ज्ञाननिष्ठा तु तद्गुणत्वेन कीर्तिता।'),
('nilakantha-sc:source:4.1','Nīlakaṇṭha','gita.4.1','sa','commentary','।।4.1।।अध्यायद्वयोक्तेऽर्थेप्रामाण्यशङ्का माभूदिति विद्यावंशसंप्रदायमात्मनश्च भ्रमविप्रलम्भकत्वादिनिरासायेश्वरत्वं सर्वज्ञत्वं च दर्शयति इममित्यादिना। इमं सांख्ययोगं कर्मयोगरूपोपायसहितं ससंन्यासमिति भाष्यं। इमं संध्योपासनादिनिर्विकल्पकसमाध्यनुष्ठानान्तं कर्मयोगं ज्ञाननिष्ठोपसर्जनं पारिव्राज्यानधिकारिणां राज्ञामेव योग्यं विवस्वते सूर्याय मण्डलाभिमानिने सर्वेषां क्षत्रियाणामादिभूतायाहमादित्यान्तर्यमीय एषोऽन्तरादित्ये हिरण्मयः पुरुषो दृश्यते हिरण्यश्मश्रुर्हिरण्यकेश आप्रणखात्सर्व एव सुवर्णस्तस्य यथा कप्यासं पुण्डरीकमेवमक्षिणी तस्योदिति नाम इत्यादिश्रुतिप्रसिद्धः प्रोक्तवान् पुरा। अव्ययमविच्छिन्नसंप्रदायम्। तेनानादित्वमपि। मनवे स्वपुत्राय विवस्वान्प्राह। इक्ष्वाकवे मनुः स्वपुत्रायाब्रवीत्।'),
('nilakantha-sc:source:4.2','Nīlakaṇṭha','gita.4.2','sa','commentary','।।4.2।।एवमिति। एवं परंपराप्राप्तमिक्ष्वाकोर्निमिनाभागादिक्रमेण राजर्षयो जनकाजातशत्रुकैकेयप्रभृतयो राजानः ऋषयश्च सनकवसिष्ठाद्याः सूक्ष्मार्थदर्शिनस्ते राजान एव ऋषय इति वा अविदुर्ज्ञातवन्तः।सिजभ्यस्तविदिभ्यश्च इति लङो झेर्जुस्। नष्टोऽदर्शनं गतः।'),
('nilakantha-sc:source:4.3','Nīlakaṇṭha','gita.4.3','sa','commentary','।।4.3।।स इति। अद्य संप्रदायविच्छेदे सति। भक्तः शरणागतः सखा प्रीतिविषयः रहस्यं गोप्यमभक्तादिभ्यो न देयम्। अन्यथा निर्वीर्या विद्या भवेदित्यर्थः। तथा च मन्त्रवर्णःविद्या ह वै ब्राह्मणमाजगाम गोपाय मा शेवधिष्टेऽहमस्मि। असूयकायानृजवे अप्रयताय न मा ब्रूया वीर्यवती तथा स्याम् इति।'),
('nilakantha-sc:source:4.4','Nīlakaṇṭha','gita.4.4','sa','commentary','।।4.4।।भगवद्देहस्य वसुदेवादुत्पत्तिं मन्वानोऽर्जुन उवाच अपरमिति। अपरमर्वाक्कालिकं परं बहुकालिकं विजानीयाम्। यद्यपि शब्दादयमर्थो ज्ञातस्तथापि विरुद्धस्य वाक्यस्याबोधकत्वात्कथमेतद्विजानीयामित्युक्तम्। पदयोजना स्पष्टा।'),
('nilakantha-sc:source:4.5','Nīlakaṇṭha','gita.4.5','sa','commentary','।।4.5।।स्वदेहस्याजत्वं साधयितुं स्वस्य सर्वज्ञत्वं तावदाह बहूनीति। स्पष्टार्थः श्लोकः।'),
('nilakantha-sc:source:4.6','Nīlakaṇṭha','gita.4.6','sa','commentary','।।4.6।।किं तर्हि योगिनां सर्वज्ञत्वप्रसिद्धेस्त्वं जातिस्मरो जीवोऽसीत्याशङ्क्याह अज इति। देहान्निष्कृष्टस्याजत्वाव्ययत्वेनत्वेवाहं जातु नासं इत्यत्र साधिते इह तु देहविशिष्टस्यैव ते उच्येते। ईश्वरोऽपीत्यनेन देहान्निष्कृष्टस्यास्मदादेरपीश्वरत्वंतत्त्वमसिअहं ब्रह्मास्मि इत्यादिश्रुतिप्रसिद्धमतो देहविशिष्टस्यैवाजत्वनित्यत्वे दृढीक्रियेतेऽन्यथानीश्वरत्वप्रसङ्गात्। नह्यादित्यान्तर्यामिणः परमेश्वरस्य हिरण्यश्मश्रुत्वादिविशिष्टो देहो जन्मव्ययवानिति वक्तुं शक्यम्। अकर्मजत्वात्। कर्मफलस्य हि परा काष्ठा हैरण्यगर्भशरीरप्राप्तिः। न चपुरुषो ह वै नारायणोऽकामयत अत्यतिष्ठेयं सर्वाणि भूतानि अहमेवेदं सर्वं स्यामिति स एतं पुरुषमेधं पञ्चरात्रं यज्ञक्रतुमपश्यत् इत्यादिना शतपथे नारायणाख्यस्य परमात्मनःसहस्रशीर्षा पुरुषः सहस्राक्षः सहस्रपात्। स भूमिं विश्वतो वृत्वात्यतिष्ठद्दशाङ्गुलम् इतिपादोऽस्य सर्वा भूतानि त्रिपादस्यामृतं दिवि इति च पुरुषसूक्तप्रतिपाद्यस्य सर्वाणि भूतान्यतिक्रम्य स्थितस्येश्रस्यापि शरीरं पञ्चरात्राख्यकर्मविशेषफलमिति श्रूयत इति वाच्यम्। तत्र नारायणशब्देन हिरण्यगर्भस्यैव विवक्षितत्वात्। नहि परमेश्वरस्य पूर्णकामस्य सर्वानतिक्रम्य स्थितस्य पुनरत्यतिष्ठेयं सर्वाणि भूतानीति कामना भवति। ननु परमेश्वरेऽपि कामना दृष्टासोऽकामयत बहु स्यां प्रजायेयेति इतिचेच्छ्लाघनीयप्रज्ञो देवानांप्रियः यतआप्तकामस्य का स्पृहा इति श्रुतेःलोकवत्तु लीलाकैवल्यम् इति न्यायाच्च निस्पृहस्य लीलयैव ब्रह्माण्डकोटीः सृजतो भगवतो राजगोपालस्य कर्मकिंकरेण कर्मणा सार्वात्म्यं प्रार्थयता साम्यमापादयति। तस्मान्न कर्मफलं भगवतः शरीरम्। अतएव न भौतिकम्। विराट्सूत्रात्मातिरिक्तस्य भौतिकस्याभावात्। तस्माद्युक्तमजोऽपि सन्निति। ननु तर्हि भगवच्छरीरस्य किमुपादानम्। अविद्येतिचेन्न। परमेश्वरे तदभावात्। जीवाविद्याचेन्न। शुक्तिरजतादेरिव तुच्छत्वापत्तेः। चिन्मात्रं चेन्न। चितः साकारत्वायोगात्। तथात्वे वा तस्यातीन्द्रियत्वापत्तिः। तस्मात्किमालम्बो भगवद्देहो देवकीगर्भप्रववेशजननबाल्यकौमारपौगण्डयौवनादिप्रतीतिविषय इति चेच्छृणु। प्रकृतिं स्वामधिष्ठाय संभवाम्यात्ममाययेति। अयमर्थः जीवात्मनो ह्यनात्मभूतां प्रकृतिं तेजोबन्नात्मिकां पञ्चभूतात्मिकां वाधिष्ठायसंभवन्ति जन्मादींल्लभन्ते अहं तु स्वां प्रत्यगनन्यां प्रकृतिं प्रत्यक्चैतन्यमेवेत्यर्थः। तदेवाधिष्ठाय नतूपादानान्तरम्। आत्ममायया स्वीयमायया संभवामि। यथा कश्चिन्मायावी स्वयं स्वस्थानादप्रच्युतस्वभावोऽप्यदृश्यो भूत्वा स्थूलसूक्ष्मभूतान्यनुपादायैव केवलया मायया द्वितीयं मायाविनं स्वसदृशमेव सूत्रमार्गेण गगनमारोहन्तं सृजति एवमहं कूटस्थचिन्मात्रोऽग्राह्यः स्वमायया चिन्मयमात्मनः शरीरं सृजामि तस्य बाल्याद्यवस्थाश्च सूत्रारोहणवद्दर्शयामि। एतावांस्तु विशेषः लौकिकमायावी मायामुपसंहरन् द्वितीयं मायाविनमप्युपसंहरति अहं तु तामनुपसंहरन् स्वविग्रहमपि नोपसंहरामीति। एवं हि सति हिरण्यश्मश्रुत्वादिलक्षणविग्रहयोगिनश्चैतन्यस्यअन्तस्तद्धर्मोपदेशात् इत्यादिन्यायसिद्धं वियदाद्युपादानत्वलक्षणं सर्वेश्वरत्वं युज्यते नान्यथेति। तस्मात्सिद्धं परमेश्वरस्य मायामयं शरीरं नित्यमिति एकेनैव देहेन विवस्वन्तमुपदिश्य त्वामप्युपदिशामीति। अन्यत्रापिनित्यैव सा जगन्मूर्तिः इति सावधारणं प्रतिज्ञायतेदेवानां कार्यसिद्ध्यर्थमाविर्भवति सा यदा। उत्पन्नेति तदा लोके सा नित्याप्यभिधीयते इति। नित्याया अप्याविर्भावापेक्षया सूर्यस्येव बाल्यादिकमुत्पत्त्याद्युपगम्यते। भाष्ये तु स्वां प्रकृतिं वैष्णवीं त्रिगुणात्मिकां मायामधिष्ठाय वशीकृत्य आत्ममायया संभवामि देहवान् जात इवात्मनो मायया न परमार्थतो लोकवदिति व्याख्यातम्।'),
('nilakantha-sc:source:4.7','Nīlakaṇṭha','gita.4.7','sa','commentary','।।4.7।।कदा संभवसीत्यपेक्षायमाह यदेति। ग्लानिर्ह्रासः। अभ्युत्थानं वृद्धिः।'),
('nilakantha-sc:source:4.8','Nīlakaṇṭha','gita.4.8','sa','commentary','।।4.8।।किमर्थमात्मानं मायया सृजसीत्यत आह परित्राणायेति। दुष्कृतां दुष्टं कर्म कुर्वतां पापिनाम्। संभवाम्याविर्भवामि।'),
('nilakantha-sc:source:4.9','Nīlakaṇṭha','gita.4.9','sa','commentary','।।4.9।।जन्म मायामयम् कर्म साधुत्राणम् दिव्यमप्राकृतं यो वेत्ति स त्यक्त्वा देहं पुनर्जन्म न प्राप्नोति किंतु मामेति मामेव प्राप्नोति। एतेन भगवतो जन्मानि कर्माणि च भगवत्प्राप्तिकामेन गेयानीति दर्शितम्।'),
('nilakantha-sc:source:4.10','Nīlakaṇṭha','gita.4.10','sa','commentary','।।4.10।।एतस्यापि भगवत्प्राप्तेर्द्वारमाह वीतेति। रागो विषयेषु प्रीतिः भयं स्वोच्छेदाशङ्का क्रोधः स्वपरपीडाहेतुरभिज्वलनं ते त्रयो वीता येभ्यस्ते वीतरागभयक्रोधाः। अतएव मन्मयाः मदेकप्रधानाः। किं जारिणी यथा जारमपि भर्तारं चाश्रिता योगक्षेमार्थं तद्वन्नेत्याह। मामुपाश्रिताः ज्ञानतपसा ज्ञानमयं तप आलोचनं मम जन्मकर्मणोः स्वरूपस्य च निरन्तरं चिन्तनंयस्य ज्ञानमयं तपः इति श्रुतिप्रसिद्धं ज्ञानतपस्तेन पूताः सन्तो मद्भावं मत्तादात्म्यं प्राप्ता इत्यर्थः।'),
('nilakantha-sc:source:4.11','Nīlakaṇṭha','gita.4.11','sa','commentary','।।4.11।।ननु साध्वसाध्वोस्त्राणविनाशौ कुर्वतस्तव वैषम्यनैर्घृण्ये स्तोऽतः किं तवास्मदादितुल्यस्य जन्मकर्मस्वरूपाणां चिन्तनेनेत्याशङ्क्याह ये यथेति। ये मनुष्याः मां सर्वशरीरस्थं यथा येन प्रकारेण शत्रुत्वेन मित्रत्वेन वा प्रपद्यन्ते प्राप्नुवन्ति तांस्तेनैव प्रकारेणाहमपि भजाम्यनुसरामि। ये तु मम वर्त्म भक्तिध्यानप्रणिधानात्मकमनुवर्तन्ते तान्ममात्मभूतांस्तथैव सर्वशः सर्वैः प्रकारैरनुवर्तेऽहमिति योजना। ततश्च मद्बिम्बभूते प्राणिजाते यथा यः प्रीतिं द्वेषं वा करोति तस्मिन्प्रतिबिम्बभूतेऽहमपि तथैव प्रीतिं द्वेषं च करोमि। बिम्बपूजापरिभवौ प्रतिबिम्बे एव संक्रामतोऽतो न मम वैषम्यनैर्घृण्ये स्तः। तस्मात् श्रेयोर्थिना सर्वस्य कल्याणायैव यतितव्यमिति भावः। भाष्ये तु ये यथा येन प्रकारेण येन प्रयोजनेन आर्ता जिज्ञासवोऽर्थार्थिनो ज्ञानिनो वा प्रतिपद्यन्ते तांस्तथैव पीडापरिहारेण ज्ञानदानेन अर्थदानेन मोक्षदानेन वाऽनुगृह्णामि। सर्वथा ते ममैव वर्त्मानुवर्तन्त इति अन्यदेवताभक्ता इति चैतद्व्याचक्षते।'),
('nilakantha-sc:source:4.12','Nīlakaṇṭha','gita.4.12','sa','commentary','।।4.12।।काङ्क्षन्त इति। हि यस्मात् मानुषे लोके कर्मसिद्धिः काम्यकर्मफलं पुत्रपश्वादिकं क्षिप्रं भवति न तु निष्कामकर्मजा चित्तशुद्धिः। अतो ये कर्मणां सिद्धिं फलं इहैव क्षिप्रं काङ्क्षन्तः काङ्क्षमाणा देवता इन्द्रादीन्यजन्ते तेऽपि ममैव वर्त्मानुवर्तन्त इति पूर्वेणान्वयः। वक्ष्यति चयेप्यन्यदेवताभक्ताः इत्यादि।'),
('nilakantha-sc:source:4.13','Nīlakaṇṭha','gita.4.13','sa','commentary','।।4.13।।अन्यदेवताभक्ता अपि कस्मात्पुनः कारणात्तवैव वर्त्मानुवर्तन्ते नान्यस्येत्यत आह चातुर्वर्ण्यमिति।चतुर्णां वर्णानां हितं चातुर्वर्ण्यम्। गुणाश्च कर्माणि चेति गुणकर्म। द्वन्द्वैकवद्भावः। कर्माण्यग्निहोत्रादीनि। गुणाश्च द्रव्यदेवतादिरूपाः। विभागशः साधारणासाधारणविभागेन। तथाहि दानजपादिकं सर्वसाधारणम्। अग्निहोत्रादिकं त्रैवर्णिकस्यैव न शूद्रस्य। राजसूयादिकं राज्ञ एव नेतरेषामिति विभागो दृश्यते। यतश्चातुर्वर्ण्यं गुणकर्म मया सृष्टं ततोऽन्यदेवतानामपि मदुत्थत्वात्पुत्रप्रीत्या पितुरिव तत्प्रीत्या ममैव तृप्तिरस्तीत्यर्थः। यद्वा गुणविभागशः कर्मविभागश इति योज्यम्। तथाहि सत्त्वप्रधाना ब्राह्मणास्तेषां कर्म शमदमादिकम् सत्त्वोपसर्जनरजःप्रधानाः क्षत्रियास्तेषां कर्म शौर्यादि तम उपसर्जनरजःप्रधाना वैश्यास्तेषां कर्म कृष्यादि रज उपसर्जनतमःप्रधानाः शूद्रास्तेषां कर्म शुश्रूषैवेति गुणकर्मविभागो दृश्यते तदा चातुर्वर्ण्यमिति स्वार्थे ष्यञ्। चत्वारो वर्णाः गुणकर्मविभागशो मया सृष्टा इत्यर्थः। अन्यदेवताभक्ता अपि मदुक्तकर्मकारित्वान्मद्भक्ता एवेति भावः। ननु यद्येवं त्वं स्वसन्ततितर्पणेन स्वाज्ञाकरणेन प्रीयसे तदर्थं च त्वया चातुर्वर्ण्यं सृष्टं तर्हि महान्संसारीं त्वमसीत्याशङ्क्याह तस्येति। कर्तारं मायायोगात् वस्तुतोऽकर्तारम्। अतएवाव्ययमविकारिणम्।'),
('nilakantha-sc:source:4.14','Nīlakaṇṭha','gita.4.14','sa','commentary','।।4.14।।ननु कर्तुरपि कथमकर्तृत्वमत आह न मामिति। कर्मलेपोऽपि कुतो नास्तीत्यत आह न मे इति। यः कर्तृत्वाभिमानी स लिप्यते यस्तु फलेच्छुः स एवात्मनः कर्तृत्वं मनुत इति फलेच्छाभावादकर्ता अकर्तृत्वाच्च न लिप्यतेऽथं इति मां योऽभिजानाति स कर्मफलस्पृहात्यागात्कर्मभिर्न बध्यते।'),
('nilakantha-sc:source:4.15','Nīlakaṇṭha','gita.4.15','sa','commentary','।।4.15।।एतदेव शिष्टाचारप्रदर्शनपूर्वकं ग्राहयति एवं ज्ञात्वेति। पूर्वतरं वेदोक्तत्वान्नत्वधुना केनचित्कल्पितमित्यर्थः। पूर्वतरं प्रथमतरं कृतं अत्यावश्यकत्वादिति वार्थः।'),
('nilakantha-sc:source:4.16','Nīlakaṇṭha','gita.4.16','sa','commentary','।।4.16।।आवश्यकत्वेऽपि न कर्मणो गतानुगतिकतयानुष्ठानं कर्तव्यं किंतुज्ञात्वा कर्माणि कुर्वीत इतिवचनात्कर्माश्रितं किंचिद्विशेषं ज्ञापयितुमुपोद्धातयति किं कर्मेति। यतः कर्माकर्मणी कवीनामपि दुर्निरूपे तत्तस्मात्ते तुभ्यं कर्म अकर्म चाकारप्रश्लेषेण ग्राह्यम्। ते उभे प्रवक्ष्यामि यत् द्वयं ज्ञात्वाऽशुभात्संसारान्मोक्ष्यसे।'),
('nilakantha-sc:source:4.17','Nīlakaṇṭha','gita.4.17','sa','commentary','।।4.17।।एतज्ज्ञानमावश्यकमित्याह कर्मण इति। तत्त्वं बोधव्यमस्तीति स्थलत्रयेऽपि तत्त्वमस्तीति पदद्वयाध्याहारः। कर्मणः शास्त्रविहितस्य। विकर्मणः प्रतिषिद्धस्य। अकर्मणस्तूष्णींभावस्य। गहना कर्मण इत्यत्र कर्मण इति त्रितयोपलक्षणम्। कर्मविकर्माकर्मणां गतिर्याथात्म्यं तत्त्वं गहनम्।');
INSERT INTO commentary_fts (unit_id,author,canonical_ref,language,content_type,content) VALUES
('nilakantha-sc:source:4.18','Nīlakaṇṭha','gita.4.18','sa','commentary','।।4.18।।यत्कर्मादेस्तत्त्वं वक्ष्यामीति प्रतिज्ञातं तदाह कर्मणीति। कर्मणि कर्माकर्मविकर्मात्मके देहेन्द्रियादिव्यापारे अविद्यया प्रत्यगात्मन्यारोपिते सति तत्राकर्म कर्माभावं नौस्थे तीरतरौ चलने आरोपिते सति तत्त्वबुद्ध्या तत्र चलनाभावमिव यः पश्येत् तथाचलं गुणवृत्तम् इति न्यायेन त्रिगुणात्मकेषु देहेन्द्रियादिषु नित्यकर्मवत्सु यश्चन्द्रतारकादौ गत्यभावमिव तूष्णींभूतोऽहमस्मि न किंचित्करोमीत्यध्यस्ते अकर्मणि कर्माभावे कर्म तन्निग्रहाख्यप्रयत्नरूपं यः पश्यति स मनुष्येषु बुद्धिमान् तत्त्वदर्शी। आत्मनि भ्रान्तिजनितव्यापारस्य अनात्मनि च तादृशनिर्व्यापारत्वस्य बाधात्। स एव च युक्तो योगी कृत्स्नकर्मकृच्च। कर्मयोगफलस्य तत्त्वज्ञानस्य प्राप्तत्वादिति स्तुतिमात्रम्। आत्मनोऽकर्तृत्वं संघातस्यैव कर्तृत्वमिति भावयता कर्माणि कर्तव्यानीत्यर्थः। यद्यप्येतद्बहुधा प्रपञ्चितंअव्यक्तोऽयम् इत्यादौ तथापि तत्त्वस्य दुर्ज्ञेयत्वात्पुनःपुनरुच्यत इति प्राञ्चः। यत्तु कर्मणि नित्ये परमेश्वरार्थेऽनुष्ठीयमाने बन्धहेतुत्वाभावादकर्मेदमिति यः पश्येत्तथाऽकर्मणि नित्यकर्माकरणे प्रत्यवायहेतुत्वेन कर्मेदमिति च यः पश्येत्स बुद्धिमानिति तदसंगतमेव। नित्यकर्मण्यकर्मेदमिति ज्ञानस्याशुभमोक्षहेतुत्वाभावान्मिथ्याज्ञानत्वेन तस्यैवाशुभत्वाच्च। न चैतादृशां मिथ्याज्ञानं बोद्धव्यं तत्त्वं नाप्येतादृशज्ञाने बुद्धिमत्त्वादिस्तुत्युपपत्तिरिति दिक्। ये तु कर्मणि ज्ञानकर्मणि दृश्ये जडे सद्रूपेण स्फुरणरूपेण वानुस्यूतं सर्वभ्रमाधिष्ठानं अकर्म अवेद्यं स्वप्रकाशचैतन्यं परमार्थदृष्ट्या यः पश्येत् तथा अकर्मणि स्वप्रकाशे दृग्वस्तुनि कल्पितं कर्म दृश्यं मायामयं न परमार्थं सदिति यः पश्यति स बुद्धिमानिति परमार्थदर्शितत्वाद्वास्तवैरेव गुणैः स्तूयत इत्यपि व्याचख्युस्तदप्यसंगतमेव। कर्म कुरु कर्म प्रवक्ष्यामीत्यनुष्ठेयकर्मप्रस्तावे तत्त्वज्ञानानवसरात्। नापिकर्तुरीप्सिततमं कर्म इति पारिभाषिक्या कर्मसंज्ञया दृश्यस्य कर्मशब्दार्थत्वं ग्रहीतुं शक्यम्। तस्या घुटिभादिसंज्ञानामिवागमार्थनिर्णयानर्हत्वादिति संक्षेपः। वस्तुतस्तुकर्मणो हीति श्लोके कर्मविकर्माकर्मणां गतिशब्दितं पर्यवसानं गहनत्वाद्बोद्धव्यमित्युपक्षिप्तं तद्व्याख्यानं कर्मण्यकर्म यः पश्येत्स मनुष्येषु बुद्धिमानिति। तथाहि। कर्मणि कर्माकर्मविकर्मरूपे अकर्म तद्वैपरीत्यं शास्त्रतो दृश्यत। यथा क्रतुः कर्मणि श्रद्धाहीनस्य कृतोऽप्यकृत एव भवतीत्यकर्मणि पर्यवस्यति। दाम्भिकस्य तु विकर्मणि पर्यवस्यति। यथोक्तंअश्रद्धया हुतं दत्तं तपस्तप्तं कृतं च यत्। असदित्युच्यते पार्थ न च तत्प्रेत्य नो इह इतिचत्वारि कर्माण्यभयंकराणि भयं प्रयच्छन्त्ययथा कृतानि। मानाग्निहोत्रमुत मानमौनं मानेनाधीतमुत मानयज्ञः। इति च। एवमौदासीन्यमकर्मापि शक्तस्यार्तपरित्राणाभावाद्विकर्मणि पर्यवस्यति। दीक्षितस्य भगवद्ध्यानाद्यसक्तस्य वा स्वकाले पञ्चयज्ञाद्यकरणंदीक्षितो न ददाति इत्यादिवचनात्सर्वधर्मान्परित्यज्य इत्यादिवचनाच्च कर्मण्येव पर्यवस्यति। नित्यकर्मकाले प्रत्यवायहेतोरन्यस्याविहितस्याकरणात्। एवं विकर्मापि हिंसाअग्नीषोमीयं पशुमालभेत इति वचनाद्यज्ञे कर्मैव भवति सैव वृथा नष्टे पशौ न कर्म। विध्यर्थानिष्पत्तेः। नापि विकर्म कामकारेणाकृतत्वात्। किंतु परिशेषात्कृताप्यकृतैवेत्यकर्मणि पर्यवस्यति। एवं स्तेनप्रमोचनं तत्सयूथ्यानां कर्मापि राज्ञो विकर्म।स्तेनः प्रमुक्तो राजनि पापं मार्ष्टि इति वचनात् तदेव यतीनामुपेक्षणीयत्वादकर्म। एवं हिंसाफलके सत्यादौ दानफलकेऽनृतादौ च विकर्मत्वकर्मत्वे बोध्ये। तस्मात्कर्माकर्मविकर्माख्ये कर्मणि अकर्म तद्वैपरीत्यं यः पश्येत् स कार्याकार्यविभागज्ञो बोद्धव्यानामेषां प्रबोधात् बुद्धिमानित्युच्यते। तथा किं कर्मेति श्लोके यत्र कवीनामपि मोहोऽस्ति ययोश्च ज्ञानमशुभमोक्षहेतुस्ते कर्माकर्मणी प्रवक्ष्यामीत्युपक्षिप्तं तद्व्याख्या न कर्मणि च कर्म यः पश्येत्स युक्त इति। चकारो दर्शनद्वयसमुच्चयार्थः। तेन यो बुद्धिमान्युक्तश्च स एव कृत्स्नकर्मकृत् नत्वेकैक इत्यपि ज्ञेयम्। तथाहि अकर्मणि स्पन्दशून्ये कूटस्थे वस्तुनि कर्म सस्पन्दं बाह्यं वियदादि आभ्यन्तरं प्रमात्रादिकं चाधाराधेयभावेन वा उपादानोपादेयभावेन वा अधिष्ठानाध्यस्तभावेन वा पश्यन्तः शास्त्रविदः कर्माणि कुर्वन्ति। तत्राद्यः सांख्येऽसङ्गे मयि संघातकर्म एव सन्कर्त्रादिरविवेकात्स्फटिके लौहित्यमिव भातीति मन्यते। द्वितीयस्तु कनककुण्डलवद्ब्रह्मोद्भवं सर्वं ब्रह्मैवेति कर्म तत्साधनादिकमहं च ब्रह्मैवेति भावयन्करोति। एतौ युक्तावप्यतिबुद्धिमानप्ययुक्तः करोति तस्य सर्वमसदेव भवति नत्वशुभमोक्षाय।यो वा एतदक्षरं गार्ग्यविदित्वास्मिन्लोके यजति ददाति तपस्तप्यतेऽपि बहूनि वर्षसहस्राण्यन्तवदेवास्य तद्भवति इति श्रुतेः। यस्तु युक्तोऽपि निर्बुद्धित्वादकार्यमपि करोति स प्रत्यवैति। पापाश्लेषनिमित्तस्यापरोक्षज्ञानस्याभावात्। अनयोश्चाविद्याविद्याशब्दतयोः कर्मपरोक्षज्ञानयोः समुच्चयः श्रूयतेविद्यां चाविद्यां च इति मन्त्रे। यद्वा द्विविधं कर्मणि कर्मदर्शनं परोक्षमपरोक्षं च। तत्राद्यवान् ज्ञानकर्मसमुच्चयानुष्ठाता बुद्धिमानुच्यते। अपरोक्षमपि द्विविधम्। उपास्यसाक्षात्काररूपं तत्त्वसाक्षात्काररूपं च। तत्राद्यमपि व्याकृताव्याकृतरूपोपास्यभेदेन द्विविधम्। तत्रापि व्याकृतं सूत्रं कार्यम्। तद्दर्शी विगतदेहाहंकारत्वाद्योगशास्त्रे विदेह उच्यते। अव्याकृतं कारणं तद्दर्शी प्रकृतिलय उच्यते। अनयोरुपासनयोः संभवासंभवसंज्ञयोः समुच्चयो विधीयतेअन्यदेवाहुः संभवात् इत्यादिना। सोयं युक्त इत्युच्यते। अस्याप्यग्रे कर्तव्यमवशिष्टमस्तीति नायमपि कृत्स्नकर्मकृत् किंतु यस्य कर्मबाधेनाकर्मदर्शनं मुख्यमस्ति स एव कृतकृत्यत्वान्मुख्यः कृत्स्नकर्मकृदिति। एतेष्वाद्यो मनुष्येषु देहाभिमानिष्वेव बुद्धिमानित्यक्रान्तदर्शित्वादकविरेव। मध्यमौ क्रान्तदर्शिनावपि तत्त्वविषये मूढत्वात्कवयोऽप्यत्र मोहिता इत्युक्तौ। एतयोर्व्यवधानेनाशुभान्मुक्तिः। उत्तमस्तु जीवन्नेवाशुभान्मुक्त इति श्लोकार्थः प्रतिभाति।व्याख्यातुरपि मे नास्ति भाष्यकारेण तुल्यता। गुहावद्योतिनोऽप्यस्ति किं दीपस्यार्कतुल्यता। यद्वा कर्माकर्मणी वक्तव्यत्वेन बोद्धव्यत्वेन चोपक्षिप्यात्र तयोर्लक्षणप्रदर्शनमुचितम्। अतो यदकर्मणा विशेषितं तदेव कर्म नान्यदिति कर्मलक्षणम्। यच्च कर्मणा विशेषितं तदेवाकर्मेत्यकर्मलक्षणमिति व्याख्येयम्। अक्षरार्थस्तु कर्म यज्ञादिकं ससाधनम्। तत्राकर्म स्पन्दशून्यं कूटस्थं ब्रह्म यः पश्येत् कर्मतदङ्गेषु ब्रह्मदृष्टिमध्यस्येत्अहं क्रतुरहं यज्ञः स्वधाहमहमौषधम्। मन्त्रोऽहमहमेवाज्यमहमग्निरहं हुतम् इत्युक्तप्रकारेण। अन्यथा यत्कृतं तद्वृथा चेष्टारूपमेवातो गहना कर्मणो गतिः। किं तदकर्म यत्कर्मण्यध्यस्यत इत्याकाङ्क्षायां यत्रैतत्कर्म पुण्यपापात्मकं दृश्यतेपुण्यो वै पुण्येन कर्मणा भवति पापः पापेन इति तत्फलं च सुखदुःखादिकं अहं सुखी अहं दुःखीति स प्रत्यक्चेतनोऽकर्म तत्रैवेदं कर्म अस्पन्दे स्पन्दात्मकमसर्पे सर्प इवाध्यस्तमिति यः पश्येदिति। अयं भावः यथा रज्ज्वामध्यस्तं सर्पं पश्यन्नायं सर्पो रज्जुरियमिति वाक्यात्तस्य रज्जुत्वं विक्षेपप्राबल्यादप्रतिपद्यमानो नरः सर्पमिमं रज्जुदृष्ट्योपास्स्वेति नियोज्यते सचोपासनादाढ्ये सर्पं विस्मृत्य रज्जुतत्त्वमेव विन्दति। यस्तु वाक्यादेव रज्जुतत्त्वं विन्दति न तस्य प्रत्ययावृत्तिलक्षणया उपास्त्या प्रयोजनमस्ति। एवमकर्मण्यध्यस्तं कर्त्रादितत्त्वमसीतिवाक्याद्बाधितत्वाऽकर्मप्रतिपत्तिर्भवति शुद्धसत्वस्य। अन्यस्य तु कर्त्रादीनेवाकर्मदृष्ट्याउपासीनस्य भावनादार्ढ्यात्कर्त्रादिरूपतिरोधानेनाकर्मतत्त्वप्रतिपत्तिरिति। यद्वा कर्मणीवाकर्मण्यपि विकर्मसहितेऽकर्मदृष्टिर्माभूदित्याशङ्क्याह कर्मणीति। विहिताकरणे प्रतिषिद्धाचरणे च कर्मदृष्टिरेव भवेत्। अकर्मतो बिभ्यत्कर्म ब्रह्मदृष्ट्या कुर्यान्न त्वकर्मापि तादृशदृष्ट्या कुर्यादित्यर्थः।'),
('nilakantha-sc:source:4.19','Nīlakaṇṭha','gita.4.19','sa','commentary','।।4.19।।अविदुषां कर्मण्यकर्मभावनां द्रढयितुं विदुषां कर्मदर्शनं स्तौति यस्य सर्वे समारम्भा इत्यादिभिः षड्भिः। यस्य विदुषः सर्वे समारभ्यन्त इति समारम्भाः कर्माणि। कामेन फलेच्छया संकल्पेनाहमिदं करोमीत्यभिमानेन च वर्जिताः तं ज्ञानाग्निना कर्मादावकर्मादिदर्शनेन दग्धान्यङ्कुरीभावाच्च्यावितानि कर्माणि शुभाशुभानि येन तं पण्डितं बुधा आहुः।'),
('nilakantha-sc:source:4.20','Nīlakaṇṭha','gita.4.20','sa','commentary','।।4.20।।ननु प्रायश्चित्तेनेव ज्ञानाग्निना पूर्वकर्मदाहेऽपि क्रियमाणं तत्फलाय भवेदित्यत आह त्यक्त्वेति। आत्मलाभेन नित्यतृप्तत्वात्फलासङ्गं त्यक्त्वा निराश्रयत्वात्। अहंकाराद्याश्रयेण हि कर्म क्रियते। निराश्रयो निरहंकारो यस्मात् ततः कर्मसङ्गमहंकरोमीत्यभिमानं च त्यक्त्वा कर्मणि लौकिके वैदिके वा अभितः सर्वाङ्गोपसंहारेण प्रवृत्तोऽपि स नैव किंचित्करोति। अतोऽस्य क्रियमाणमपि कर्म न फलाय प्रभवतीत्यर्थः।'),
('nilakantha-sc:source:4.21','Nīlakaṇṭha','gita.4.21','sa','commentary','।।4.21।।नन्वेतस्माद्गौणात्कर्मकरणादकरणं मुख्यमेव तद्वरमित्याशङ्क्य गृहस्थस्य तत्प्रत्यवायावहमिति व्यतिरेकमुखेनाह निराशीरिति। यो निष्परिग्रहः स्त्र्यादिपरिग्रहरहितः संन्यासी स चेन्निराशीः योगैश्वर्यमप्यनिच्छन् यतं चित्तं बुद्धिरात्मा च देहेन्द्रियसंघातो येन स यतचित्तात्मा। समाधिकाले निरुद्धबाह्याभ्यन्तरवृत्तरित्यर्थः। स व्युत्थानकाले शारीरं शरीरस्थितिमात्रप्रयोजनं भिक्षाटनादि। तदपि केवलं कर्तृत्वाभिमानशून्यं पराध्यारोपितकर्तृत्वेन कुर्वन्नपि किल्बिषंयावज्जीवमग्निहोत्रं जुहुयात् इति यावज्जीवाधिकारचोदिताग्निहोत्राद्यकरणजं प्रत्यवायं नाप्नोति। विधितस्तेषां त्यागात्। यस्तु सपरिग्रहः स निराशीरपि यतचित्तात्मापि केवलमपि शारीरं कर्म कुर्वन् विहिताकरणात्किल्बिषं प्राप्नोत्येवेत्यर्थः।'),
('nilakantha-sc:source:4.22','Nīlakaṇṭha','gita.4.22','sa','commentary','।।4.22।।ननु सपरिग्रहः कुटुम्बभरणव्यग्रतया कथं वित्तव्ययायाससाध्यान्यग्निहोत्रादीन्यनुतिष्ठेदित्याशङ्क्याह यदृच्छेति। यदृच्छया अप्रार्थितोपनतो लाभो यदृच्छालाभस्तेन संतुष्टः। तथाहि ऋतामृताभ्यां जीवनं ब्राह्मणस्य विधाय व्याख्यातंऋतमुञ्छशिलं प्रोक्तममृतं स्यादयाचितम् इति। द्वन्द्वातीतो बहुलाभेऽलाभे वा सुखदुःखाद्यतीतः। विमत्सरः परस्य लाभं दृष्ट्वा संतापहीनः। समो यदृच्छालाभेनैवेष्टिपशुचातुर्मास्यादेर्नित्यकर्मणः सिद्धावसिद्धौ वा समो निर्विकार एवंभूत इष्ट्यादीनि कृत्वापि तत्फलेन स्वर्गादिना न निबध्यते। अपिशब्दात्तज्जेन प्रत्यवायेन न निबध्यते। बन्धहेतोः कर्मणस्तत्त्वज्ञानेनैव दाहात्। तथा च स्मृतिःन्यायागतधनस्तत्त्वज्ञाननिष्ठोऽतिथिप्रियः। श्राद्धकृत्सत्यवादी च गृहस्थोऽपि विमुच्यते। इति। भाष्ये त्वयं श्लोकः संन्यासिपरत्वेनैव व्याख्यातः।'),
('nilakantha-sc:source:4.23','Nīlakaṇṭha','gita.4.23','sa','commentary','।।4.23।।त्यक्त्वा कर्मफलासङ्गम् इत्यादिना श्लोकत्रयेण विद्वान्कर्माणि कुर्वन्नपि न करोति अतो न लिप्यते लेपाभावाच्च न बध्यत इत्युक्तं तत्किं कर्मणां फलदानशक्तिप्रतिबन्धो वा ज्ञानेन क्रियते उत निरन्वयोच्छेद एवेत्याशङ्क्याद्ये मुक्तस्यापि पुनः संसारप्रसक्तिं पश्यन् द्वितीयमभ्युपगच्छति गतसङ्गस्येति। यतो विद्वान् गतसङ्गः कर्तृत्वाभिमानशून्योऽतो न करोतीत्युक्तम्। यतो मुक्तः फलकामनामुक्तः अतो न लिप्यत इत्युक्तम्। यतो यज्ञायैव यज्ञेश्वरप्रीत्यर्थमेवाचरति न फलान्तरार्थम् प्राप्याभावात्। अतस्तामेवोत्पाद्य कृतार्थैः कर्मभिर्न बध्यत इत्युक्तम्। यतोऽयं ज्ञाने सम्यग्दर्शनेऽवस्थितचेताः प्रतिष्ठितप्रज्ञः अत ईश्वरप्रीतिफलस्य ज्ञाननिष्ठाप्राप्तिरूपस्यापि प्रागेव लाभात् अस्य गतसङ्गस्य मुक्तस्य यज्ञाय कर्माचरतो ज्ञानावस्थितस्य सर्वं कर्म क्रियमाणादिकं सर्वप्रकारेण निष्प्रयोजनं सत्समग्रं अग्रेण फलेन वासनया वा सह समग्रं प्रकर्षेण निरन्वयं विलीयते नश्यत्यतो न कदाचिदपि प्रादुर्भवति। अयं च क्रियमाणकर्मप्रलयो विद्वद्दृष्ट्यैव। स्वाभाविकस्य तेषां फलजननसामर्थ्यस्य वह्न्यौष्ण्यवदप्रत्याख्येयत्वात्। अतएव ज्ञानेन पूर्वकर्मणां दाह उत्तरेषामश्लेषश्च श्रूयते नतूत्तरेषामपि दाहः।तद्यथैषीकतूलमग्नौ प्रोतं प्रदूयेतैवं हास्य सर्वे पाप्मानः प्रदूयन्ते इति।तं विदित्वा न कर्मणा लिप्यते पापकेन इति च।तस्य पुत्रा दायमुपयन्ति सुहृदः साधुकृत्यां द्विषन्तः पापकृत्याम् इति।विदुषो धनस्येव कर्मणामप्यन्यत्र गमनदर्शनान्न तेषां वस्तुवृत्त्या प्रलयोऽस्तीति ध्येयम्।'),
('nilakantha-sc:source:4.24','Nīlakaṇṭha','gita.4.24','sa','commentary','।।4.24।।कुतो विदुषां कर्माणि प्रविलीयन्त इत्याशङ्क्याह ब्रह्मार्पणमिति। यतस्ते विद्वांसः सविकल्पसमाधौ सर्वं जगत्प्रत्यक्चितिशक्तिनिर्मितं पश्यन्ति। तथा च श्रुतिःकिं कारणम् इत्युपक्रम्य कालः स्वभाव इति कालादीनि लोकदृष्ट्यानेकानि कारणान्युपक्षिप्य कारणं निर्णीयते ध्यानयोगानुगता अपश्यन्देवात्मशक्तिं स्वगुणैर्निगूढाम् इति समाधिना दर्शयति। तथा च समाधिना सर्वस्य ब्रह्मणि कल्पितत्वं पश्यतां तेषां यदर्पणमर्पणसाधनं मन्त्रजुह्वादि तत् ब्रह्मैव। एवशब्दः सर्वत्रानुषञ्जनीयः। यदर्पणीयं हविस्तदपि ब्रह्मैव। यत् हुतं हवनक्रिया हुतं तर्पितं देवब्राह्मणादि वा तदपि ब्रह्मैव। यदग्नौ हुतं तदपि ब्रह्मण्येव हुतम्। अत्र ब्रह्मणीति पदमध्याहर्तव्यम्। यद्यजमानेन हुतं तद्ब्रह्मणैव हुतम्। यत्तेन कर्मणा गन्तव्यं प्राप्तव्यं फलं तदपि ब्रह्मैव। किं बहुना यत्किंचित्तस्य कर्म शयनासनादिकं तत्सर्वं ब्रह्मैव। तत्र कारणं समाधिना समाधिजेनात्मसाक्षात्कारेण। यतः सर्वमस्य ब्रह्मात्मकं ब्रह्म च प्रत्यगनन्यत अतः प्रदेयस्य फलस्याभावात् कर्माणि प्रविलीन्यन्ते दाह्याभावाद्दहन इवेति भावः। यत्तु कर्मणि तदङ्गेषु च नामादिष्विव ब्रह्मदृष्टिरत्र विधीयत इति व्याख्यानं तदुपक्रमादिविरोधाद्ब्रह्मविद्यायाः प्रकृतत्वाच्चासंगतमिति भाष्ये एव निरस्तम्। या हि ब्रह्मविदां कर्माङ्गेषु तात्विकी ब्रह्मदृष्टिः कीर्तिता सा स्थितप्रज्ञलक्षणवदब्रह्मविदामनुष्ठानायैव फलतो भवतीति न तत्र तस्यास्तात्पर्यं वर्णनीयमिति दिक्।'),
('nilakantha-sc:source:4.25','Nīlakaṇṭha','gita.4.25','sa','commentary','।।4.25।।एवं सम्यग्दर्शनस्य यज्ञत्वं संपाद्य तत्स्तुत्यर्थं यज्ञान्तराण्युपक्षिपति दैवमेवेत्यादिना। दैवं देवताप्रधानमेव दर्शपूर्णमासादियज्ञं नान्यं एके योगिनः कर्मयोगिनः पर्युपासते अपरे तु ब्रह्मैव सत्यज्ञानानन्तानन्दात्मकमखण्डैकरसं वस्तु तदेव ज्ञातं सत्सर्वकर्मदग्धृत्वादग्निरिवाग्निर्ब्राह्माग्निस्तत्र यज्ञं जीवम्। यज्ञशब्दस्यात्मनामसु पाठात्। सोपाधिं यज्ञेनैवात्मनैव निरुपाधिकेन रूपेण जुह्वति घटाकाशमिव महाकाशे उपाधिप्रहाणेन प्रविलापयन्ति सोऽयं ज्ञानयज्ञो मुख्यः।'),
('nilakantha-sc:source:4.26','Nīlakaṇṭha','gita.4.26','sa','commentary','।।4.26।।यज्ञान्तरमाह श्रोत्रादीनीति। तत्र कंचिद्बाह्यमाभ्यन्तरं वा विशेषमुपादाय तत्र चेतसो नियमनं क्रियते। ते च संयमा अनेकविषयत्वादनेके पृथक्फलाश्च। तथा च योगसूत्रकृता प्रोक्तम्भुवनज्ञानं सूर्ये संयमाच्चन्द्रे ताराव्यूहज्ञानं कण्ठकूपे क्षुत्पिपासानिवृत्ति रित्यादि। त एवाग्नय इन्द्रियेन्धनसंहारहेतुत्वात् तेषु संयमाग्निषु श्रोत्रादीनि जुह्वति प्रक्षिपन्ति। तत्र श्रोत्रमनाहते ध्वनौ संनियम्य हंसोपनिषदुक्तरीत्या घण्टानादादीन्दशनादाननुभवन्ति। नहि तत्र सन्नियते चेतसि शब्दान्तरग्रहणं तदा भवति सोऽयं श्रोत्रस्य संयमाग्नौ होमो बोध्यः। एवमन्यत्रापि तद्वारा च निष्कलं तत्त्वं प्रतिपद्यन्ते। तथान्ये विषयेभ्यः प्रत्याहृतकरणाः धारणाध्यानसमाध्यात्मकं मनसः संयमं एकत्र मूलाधाराद्यन्यतमचक्रे कर्तुमशक्ताः समनस्केन्द्रियेषु विषयवियोगाद्दग्धेन्धनानलवत्स्वयं विलीनेषु येषां समाधिबुद्धिस्तैरिन्द्रियेषु विषया एवोपसंहृता न त्विन्द्रियादीनि मन आदिषु पूर्वोक्तरीत्या उपसंहृतानि। तानेतानिन्द्रियचिन्तकान्प्रकृत्योक्तं वायवीयेदशमन्वन्तराणीह तिष्ठन्तीन्द्रियचिन्तकाः इति।'),
('nilakantha-sc:source:4.27','Nīlakaṇṭha','gita.4.27','sa','commentary','।।4.27।।इतो विशिष्टं योगान्तरमाह सर्वाणीति। इन्द्रियाणां कर्माणि शब्दादिग्रहणानि प्राणकर्माण्याकुञ्चनप्रसारणश्वासप्रश्वासादीनि। अपरे यगिनः आत्मनि बुद्धौ संयमः स एव योगोऽग्निश्च तस्मिन् ज्ञानेन देहेन्द्रियप्राणमनोव्यतिरिक्तात्मज्ञानेन दीपिते प्रकाशिते जुह्वति प्रविलापयन्ति। इन्द्रिययोगिनां हि सुप्ताविव प्राणोऽनुपसंहृत एवास्ते। तत्सहचरस्य मनसोऽनुपसंहारात्। बुद्धियोगिनां तु मनसोऽप्युपसंहारात्तदायत्तस्य प्राणस्याप्युसंहारो भवतीति विशेषः। एतेषामपि बुद्धौ बोद्धव्याभावात्पूर्ववल्लीनायां समाधिबुद्धिरस्ति नत्वेतैर्बुद्धेरन्यत्वेन नात्मा ज्ञातो नापि तस्मिन्बुद्धिरुपसंहृता। अतएवैतान्प्रकृत्योक्तं वायवीयेबौद्धा दशसहस्राणि तिष्ठन्ति विगतज्वराः इति। बौद्धा बुद्धौ लीनाः दशसहस्राणि मन्वन्तराणीत्यनुषङ्गात्।'),
('nilakantha-sc:source:4.28','Nīlakaṇṭha','gita.4.28','sa','commentary','।।4.28।।एवं यज्ञपञ्चकं श्लोकत्रयेणोक्तम्। अथैकेनैव श्लोकेन पञ्चयज्ञानाह द्रव्येति। द्रव्यसाध्याः वापीकूपारामाः तीर्थे बहिर्वेदिकादानं श्रौतयज्ञानां प्रागेव ग्रहणात् त एव यज्ञा येषां ते द्रव्ययज्ञाः। तथा तपःकृच्छ्रचान्द्रायणमासोपवासादि तदेव यज्ञस्थानीयं येषां ते तपोयज्ञाः। तथा योगयज्ञाः सङ्गफलत्यागपूर्वकं संध्योपासनादिनिर्विकल्पसमाध्यन्तानां कर्मणामनुष्ठानं तृतीयाध्यायोक्तं योगः स एव यज्ञो येषां ते योगयज्ञाः। यद्वा यमनियमासनप्राणायामप्रत्याहारधारणाध्यानसमाधिरूपोऽष्टाङ्गोपेतोयोगश्चित्तवृत्तिनिरोधः इति सूत्रितो योग एव यज्ञो येषां त इति। तथा स्वाध्याययज्ञाः नित्यं वेदाध्ययनरतास्ते स्वाध्याययज्ञाः। ज्ञानं स्वाध्यायार्थस्य पूर्वोत्तरमीमांसाविचारः स एव यज्ञो येषाम्। स्वाध्याययज्ञा ज्ञानयज्ञाश्चेति स्वाध्यायज्ञानयज्ञा इति समासः। यतयो यतनशीलाः संशितव्रताः सम्यक् शितं तीक्ष्णं व्रतमहिंसादिकं येषां ते इति सर्वेषां विशेषणम्।'),
('nilakantha-sc:source:4.29','Nīlakaṇṭha','gita.4.29','sa','commentary','।।4.29।।एकादशं यज्ञमाह अपान इति। अपरे अपानेऽपानवृत्तौ जुह्वति प्रक्षिपन्ति प्राणं प्राणवृत्तिम्। पूरकाख्यं प्राणायामं कुर्वन्तीत्यर्थः। तथा प्राणे च अपानं प्रक्षिपन्ति। रेचकाख्यं प्राणायामं कुर्वन्तीत्यर्थः। प्राणापानगती रुद्ध्वा मुखनासिकाभ्यां वायोर्निर्गमनं प्राणस्य गतिः तद्विपर्ययेणाधोगमनमपानस्य गतिः ये प्राणापानगति एते निरुध्य प्राणायामपरायणाः प्राणायामतत्पराः कुम्भकाख्यं प्राणायामं कुर्वन्तीत्यर्थः।'),
('nilakantha-sc:source:4.30','Nīlakaṇṭha','gita.4.30','sa','commentary','।।4.30।।द्वादशं यज्ञमाह अपरे इति। नियतो निगृहीत आहारो विषयभोगो यैस्ते नियताहाराः वैराग्यादिमन्तः प्राणान्। अत्र समनस्कानीन्द्रियाणि प्राणशब्देन गृह्यन्ते। तान्प्राणेषु मनश्चित्ताहंकारेष्वन्तःकरणवृत्तिभेदेषु। बुद्धेः प्राग्गृहीतत्वादग्रहणम्। जुह्वति प्रविलापयन्ति। इन्द्रियाणि संकल्पात्मके मनसि संहृत्य मनोऽपि स्मरणात्मके चित्ते संहृत्य तदप्यहंकारे संहरन्ति। स चाभिमानरूपोऽहंकारोऽभिमन्तव्याभावात्स्वयमेव दग्धेन्धनानलवद्विलीयते। तत्र येषां समाधिबुद्धिरस्ति ते आभिमानिका बुद्धियोगिभ्यः पूर्वोक्तेभ्यो निकृष्टाः। अतएव एतान्प्रकृत्योक्तं वायवीयेसहस्रं त्वाभिमानिकाः इति। सहस्रं मन्वन्तराणीत्यनुषङ्गः। भौतिकस्तु योगोऽत्र नोक्तः। यदनुष्ठातृ़न्प्रकृत्य तत्रैवोक्तंभौतिकास्तु शतं पूर्णम् इति। अत्रापि शतं मन्वन्तराणात्यनुषञ्जनीयम्। सर्वेऽप्येते यज्ञविदो यज्ञलब्धारो यज्ञेन क्षपितं कल्मषं येषां ते तथाविधा भवन्ति सर्वे यज्ञाः कल्मषक्षयायैव भवन्ति न पुनः साक्षान्मोक्षायेत्यर्थः।'),
('nilakantha-sc:source:4.31','Nīlakaṇṭha','gita.4.31','sa','commentary','।।4.31।।सर्वेषामेतेषां मध्येऽन्यतममप्यनुष्ठातुमशक्तं प्रति प्राह यज्ञेति। यज्ञाः पञ्चमहायज्ञास्तेभ्यः शिष्टमवशिष्टमन्नममृताख्यं ये भुञ्जते तेऽपि चित्तशुद्धिद्वारा सनातनं ब्रह्म यान्ति प्राप्नुवन्ति। अयज्ञस्य पूर्वोक्तेषु द्वादशस्वन्यतमो वा नित्याः पञ्च वा यस्य यज्ञा न सन्ति सोऽयज्ञस्तस्यायमपि लोको नास्ति अन्यः परलोक आत्मलोको वा कुतो भवेत्। न कुतश्चिदित्यर्थः।'),
('nilakantha-sc:source:4.32','Nīlakaṇṭha','gita.4.32','sa','commentary','।।4.32।।एवमिति। ब्रह्मणो वेदस्य मुखे द्वारे। वेदद्वारेणैव वितता विस्तारिताः। गुरुभिरुपदिष्टा इत्यर्थः। कर्मजान्कायिकवाचिकमानसिककर्मजान्नतु नैष्कर्म्यरूपान्। एवं ज्ञात्वास्मादशुभान्मोक्ष्यसे। तत्त्वज्ञानोत्पत्तिद्वारेणेत्यर्थः।'),
('nilakantha-sc:source:4.33','Nīlakaṇṭha','gita.4.33','sa','commentary','।।4.33।।यदर्थमेते यज्ञा उपन्यस्तास्तं ज्ञानयज्ञं स्तौति श्रेयानिति। द्रव्यं बाह्यमाभ्यन्तरं च देहेन्द्रियादितत्साध्याद्द्रव्यमयाद्यज्ञात् ज्ञानयज्ञो निःशेषवाङ्मनःकायप्रवृत्त्युपरमात्मकः श्रेयान्प्रशस्तरः। ईयसुन्प्रत्ययेन तेषामपि प्रशस्तत्वं द्योत्यते तत्र हेतुः सर्वमिति। कर्म कर्मफलं सर्वमखिलं सर्वाङ्गोपसंहारयुक्तं ज्ञाने परिसमाप्यतेऽन्तर्भवति।यथा कृताय विजितायाधरेयाः संयन्त्येवमेवैनं सर्वं तदभिसमेति यत्किंच प्रजाः साधु कुर्वन्ति यस्तद्वेद यत्स वेद इति।'),
('nilakantha-sc:source:4.34','Nīlakaṇṭha','gita.4.34','sa','commentary','।।4.34।।तद्विद्धीति। ज्ञानिनः ग्रन्थज्ञाः। तत्त्वदर्शिनोऽनुभववन्तः। ज्ञानं ब्रह्म स्पष्टार्थः श्लोकः।'),
('nilakantha-sc:source:4.35','Nīlakaṇṭha','gita.4.35','sa','commentary','।।4.35।।यज्ज्ञात्वेति। यत् चिन्मात्रस्वरूपं ब्रह्म ज्ञात्वा एवमिदानीमिव पुनर्मोहं न यास्यसि। अथो अपि च येन ज्ञानेन भूतानि ब्रह्मादिस्तम्बपर्यन्तान्यात्मनि मयि त्वंपदलक्ष्यार्थादनन्यभूते परमेश्वरे द्रक्ष्यसि।नान्योऽतोऽस्ति द्रष्टा इति प्रतीचोऽन्यस्य द्रष्टुर्निषेधात्। भाष्ये तु साक्षादात्मनि मत्स्थानीमानीति द्रक्ष्यसि। अथो अपि मयि वासुदेवे परमेश्वरे च इमानीति क्षेत्रज्ञेश्वरैकत्वं सर्वोपनिषत्प्रसिद्धं द्रक्ष्यसीत्यर्थ इति।'),
('nilakantha-sc:source:4.36','Nīlakaṇṭha','gita.4.36','sa','commentary','।।4.36।।अपि चेदिति। वृजिनं वृजिनार्णवम्। धर्मोपीह मुमुक्षोः पापमित्युच्यते।'),
('nilakantha-sc:source:4.37','Nīlakaṇṭha','gita.4.37','sa','commentary','।।4.37।।यथेति। एधांसि काष्ठानि। कर्माणि प्रारब्धादन्यानि।'),
('nilakantha-sc:source:4.38','Nīlakaṇṭha','gita.4.38','sa','commentary','।।4.38।।नहीति। योगेन निष्कामकर्मानुष्ठानेन समाधियोगेन वा संसिद्धः संस्कृतो योग्यतामापन्नः। कालेनेति चिरप्रयत्नसाध्यत्वं ज्ञानस्योच्यते।'),
('nilakantha-sc:source:4.39','Nīlakaṇṭha','gita.4.39','sa','commentary','।।4.39।।श्रद्धावान् ज्ञानं लभते। श्रद्धावानपि मन्दप्रयत्नो माभूदत आह तत्पर इति। तत्परोऽप्यजितेन्द्रियो माभूदत आह संयतेन्द्रिय इति। परां शान्तिं विदेहकैवल्यम्। अचिरेण प्रारब्धकर्मसमाप्तौ सत्याम्।'),
('nilakantha-sc:source:4.40','Nīlakaṇṭha','gita.4.40','sa','commentary','।।4.40।।अज्ञ इति। अज्ञः सुखेन चिकित्सितुं शक्यः। अश्रद्दधानो यत्नेन। संशयात्मा त्वसाध्य एव। यतो मित्रादिष्वपि संशयं कुर्वतोऽस्यायं लोकोऽपि नास्ति नापि परः। वेदवाक्येऽपि संशयात्। अतएव सर्वदा संशयाकुलत्वात्सुखमपि तस्य नास्ति। तस्मात्संशयो न कर्तव्यः।'),
('nilakantha-sc:source:4.41','Nīlakaṇṭha','gita.4.41','sa','commentary','।।4.41।।किंच योगेति। योगेन कर्मण्यकर्मदर्शनात्मकेन संन्यस्तानि फलतः स्वरूपतो वा त्यक्तानि कर्माणि येन तं योगसंन्यस्तकर्माणम्। ज्ञानेन सम्यग्दर्शनेन सम्यक् छिन्नाः संशयाः आत्मा देहेऽन्यो वा अन्योऽपि विभुरविभुर्वा विभुरपि कर्ताऽकर्ता वा अकर्ताप्येकोऽनेको वा एकोऽपि सगुणो निर्गुणो वेत्येवमादयो यस्य स ज्ञानसंछिन्नसंशयस्तं आत्मवन्तं शमदमादिपरं कर्माणि कृतानि न निबध्नन्ति हे धनंजय।'),
('nilakantha-sc:source:4.42','Nīlakaṇṭha','gita.4.42','sa','commentary','।।4.42।।तस्मादिति। हृत्स्थं बुद्धिस्थम्। ज्ञानासिना ज्ञानखङ्गेन। योगं सम्यग्दर्शनोपायम्। निष्कामकर्म आतिष्ठ कुरु। उत्तिष्ठ। युद्धायेति शेषः।'),
('nilakantha-sc:source:5.1','Nīlakaṇṭha','gita.5.1','sa','commentary','।।5.1।।तृतीयेऽध्यायेलोकेऽस्मिन्द्विविधा निष्ठा इति विभिन्नाधिकारिकं निष्ठाद्वयं प्रस्तुत्यन कर्मणामनारम्भान्नैष्कर्म्यं पुरुषोऽश्नुते इत्यादिना कर्मनिष्ठाया ज्ञाननिष्ठाङ्गत्वेन भूयसा निर्बन्धेनानुष्ठेयत्वमुक्तम्कर्मण्येवाधिकारस्ते इत्यादिना। चतुर्थे तूत्पन्नसम्यग्दर्शनैः कृतमपि कर्माकृतमेव भवति ज्ञानेन कर्तृत्वादिबाधात्। अतस्तैर्वृथाचेष्टावत्कर्म वा कर्तव्यं संन्यासो वा कर्तव्य इत्यनास्थया प्रोक्तम्। अथेदानीं पञ्चमषष्ठयोरज्ञानिना ज्ञानार्थिना वैराग्योत्पत्तेः प्राक्कर्मैवानुष्ठेयम्। संपन्ने तु वैराग्ये दृष्टविक्षेपनिवृत्त्यर्थं कर्मसंन्यासं कृत्वा ज्ञानोत्पत्त्यर्थं योगोऽनुष्ठेय इत्युच्यते। तत्र चतुर्थेत्यक्तसर्वपरिग्रहः इति संन्यासोयोगमातिष्ठ इति कर्मयोगश्चैकं मां प्रति विहितः। न चैतयोः स्थितिगतिवद्युगपदेकेन मयानुष्ठानं कर्तुं शक्यते परस्परविरुद्धत्वादिति मन्वानोऽर्जुन उवाच संन्यासमिति। हे कृष्ण पापकर्षण मे मह्यं ज्ञानार्थिने संन्यासं कर्मयोगं चेति द्वयं परस्परविरुद्धं कथं शंससि कथयसि। पुनरित्यनेन प्रागपि त्वया वेदकर्त्रा इदं द्वयं विहितमस्तीति गम्यते। तथाच श्रुतिस्मृति भवतःएतमेव प्रव्राजिनो लोकमिच्छन्तः प्रव्रजन्तिसंसारमेवं निःसारं दृष्ट्वा सारदिदृक्षया। प्रव्रजन्त्यकृतोद्वाहाः परं वैराग्यमास्थिताः। इति च। तथातमेतं वेदानुवचनेन ब्राह्मणा विविदिषन्ति यज्ञेन दानेन तपसाऽनाशकेन इतिमहायज्ञैश्च यज्ञैश्च ब्राह्मीयं क्रियते तनुः इति च। ब्राह्मी ब्रह्मदर्शनयोग्या। अत एतयोः श्रुतिविहितत्वेन प्रशस्यतयोर्मध्ये एकं श्रेयः प्रशस्तरं यत्तन्मे सुनिश्चितं ब्रूहीति प्रश्नः।'),
('nilakantha-sc:source:5.2','Nīlakaṇṭha','gita.5.2','sa','commentary','।।5.2।।अस्योत्तरं भगवानुवाच संन्यास इति। निःश्रेयसकरौ ज्ञानोत्पत्तिहेतुतया। तथापि कर्मसंन्यासादविरक्तकृतात्कर्मयोग एव विशिष्यते। चित्तशुद्धिद्वारा वैराग्यादिहेतुत्वात्।'),
('nilakantha-sc:source:5.3','Nīlakaṇṭha','gita.5.3','sa','commentary','।।5.3।।ननु प्रत्यक्षः कर्मयोगिनां विक्षेपः संन्यासिनां तु स नास्तीति कथमुच्यते कर्मयोगो विशिष्यत इत्याशङ्क्याह ज्ञेय इति। यो रागद्वेषरहितः स कर्मसु स्वरूपतस्त्यक्तेष्वत्यक्तेषु वा नित्यं संन्यास्येव। एतेन साधनभूतयोः सांख्ययोगयोः रागद्वेषराहित्यकृतं साम्यमुक्तम्। फलभूतयोस्तु सर्वविकल्पराहित्यरूपसाम्यमनन्तरश्लोकाभ्यामुच्यते। तथापि चित्तस्वाभाव्यात्कदा चित्संन्यासिनो रागोदये पाताशङ्कास्ति नेतरस्येति स एव श्रेयानिति भावः। यद्यप्येवं तथापि हि प्रसिद्धं निर्द्वन्द्वो द्वन्द्वं सत्यानृतयोरात्मानात्मनोर्मिथुनं परस्पराध्यासस्तद्रहितः सांख्यो रागाद्युदयहेतोरज्ञानस्यात्यन्तोच्छेदात्। सुखं कर्मकरणायासंविनापि बन्धात्संसारात्केवलज्ञानेनैव मुच्यते न कर्माण्यपेक्षते। यद्वा निर्द्वन्द्वोद्वन्द्वं वै मिथुनं तस्माद्वन्द्वान्मिथुनं प्रजायते इति श्रुतेर्द्वन्द्वं स्त्रीपुंसयोर्मिथुनं तद्रहितः स्त्र्यादित्यागी संन्यासी अनायासेन मुच्यते। रागादिजयस्योभयत्र तुल्यत्वात्। अत्रच कुटुम्बभरणवैयग्र्याभावात्सुखं मुच्यत इत्यर्थः।'),
('nilakantha-sc:source:5.4','Nīlakaṇṭha','gita.5.4','sa','commentary','।।5.4।।नन्वेकत्र पाताशङ्का एकत्र कर्मश्रमस्तदनयोः पथोः कतरः श्रेयानित्याशङ्क्य द्वयोरपि फलतः साम्यमित्याह सांख्ययोगाविति। सांख्यंसमित्येकीभावे इति यास्कः। एकीभावेनात्मानन्यत्वेन ख्यायते प्रकाश्यते वस्तुस्वरूपमनयेति संख्या स्थूलसूक्ष्मकारणप्रपञ्चस्य निर्विकल्पे प्रत्यगात्मनि प्रविलापनेनोदिता चेतोवृत्तिस्तत्साधनभूतो यः सांख्यः संन्यासः सच दारादिबुद्ध्यन्तानां पदार्थानामात्मन्येकीभावेन न्यसनं त्यागः प्रविलापनं तथा योगोऽप्यग्निहोत्रसंध्योपासनादिनिर्विकल्पसमाध्यन्तमनुष्ठानं तत्र मुख्यस्य योगस्य लक्षणंयोगश्चित्तवृत्तिनिरोधः इति। वृत्तयश्चप्रमाणविपर्ययविकल्पनिद्रास्मृतयः इति पञ्च। तत्र प्रत्यक्षानुमानागमाः प्रमाणानि तेषु प्रत्यक्षमिन्द्रियं तज्जा वृत्तिः शुक्त्यादिविषयं याथार्थ्येन ज्ञानम्। विपर्ययस्तु तत्रैव रजतादिविषयं भ्रान्तिरूपं ज्ञानम्। संशयोऽपि इयं शुक्तिर्वा रजतं वेत्यनिर्धारितान्यतरकोटिकं ज्ञानम्। स च विपर्यय एवान्तर्भवति। विकल्पस्तु शब्दज्ञानानुपाती वस्तुशून्यः यथा पुरुषस्य चैतन्यं वन्ध्यापुत्र इति। नहि पुरुषचैतन्यतत्संबन्धानां पृथक्त्वमस्ति किंतु चैतन्यमेव हि शब्दत्रयेणोच्यते। नापि वन्ध्यासुतस्य स्वरूपमस्त्यथापि शब्देनाभिलप्यते। सोऽयं विकल्पः शब्दज्ञानानुपाती वस्तुशून्यः एकस्मिन्ननेकबुद्धिरसति स सद्बुद्धिरिति। निद्रास्मृति लोकप्रसिद्धे। एतासां निरोधेऽपि निर्विकल्पः प्रत्यगात्मैवावशिष्यते। तावेतौ फलभूतौ सांख्ययोगौ। साधनभूतौ तावेव संन्यासकर्मयोगाख्यौ। तत्रान्त्ययोः साम्यंज्ञेयः स नित्यसंन्यासी इत्यनेन सूचितम्। आद्ययोस्त्वैक्यमत्रोच्यते। आस्थितोऽनुतिष्ठन्। फलं निर्विकल्पात्मनावस्थितिरूपम्।'),
('nilakantha-sc:source:5.5','Nīlakaṇṭha','gita.5.5','sa','commentary','।।5.5।।योगैर्योगिभिः। अर्शआद्यच्प्रत्ययान्तोऽयं योगशब्दः। स्थानं मोक्षाख्यम्। एकमभिन्नम्। स्पष्टा योजना श्लोकद्वयस्य।'),
('nilakantha-sc:source:5.6','Nīlakaṇṭha','gita.5.6','sa','commentary','।।5.6।।नन्वेवं निर्विकल्पस्थानप्राप्तये द्वौ भागावुक्तौ स्यातां तच्चनान्यः पन्था विद्यतेऽयनाय इति श्रुतिविरुद्धमित्याशङ्क्याह संन्यासस्त्विति। संन्यासो नैष्कर्म्यम्। अयोगतो योगिंविना अवाप्तुं दुःखं हे महाबाहो। अयमर्थः निर्विकल्पकसमाधिरपि तत्त्वमसीत्येतद्वाक्यार्थप्रतिपत्त्युपायभूत एव न स्वतः पुरुषार्थ इति द्वितीयमार्गस्याभावान्नोदाहृतश्रुतिविरोधः।शान्तो दान्त उपरतस्तितिक्षुः समाहितो भूत्वात्मन्येवात्मानं पश्यति इति श्रुत्यैव शमादिवत्समाधेरप्यात्मदर्शनार्थत्वस्य दर्शितत्वात्। तथा च समाहितपदं वार्तिककारैर्व्याख्यातम्।स्वातन्त्र्यं येषु कर्तुः स्यात्करणाकरणंप्रति। तान्येव तु निषिद्धानि कर्माणीह शमादिभिः। शमादिश्रुत्याअस्वातन्त्र्यं तु येषु स्यात्करणाकरणंप्रति। समाहितोक्याथेदानीं तन्निरोधो विधीयते। अस्वातन्त्र्यं गुरूपदेशापेक्षत्वम्। येषु मानमेयव्यवहारनिरोधेषु।पिण्डीकृत्येन्द्रियग्रामं बुद्धावारोप्य निश्चलम्। विषयांस्तत्स्मृतीस्त्यक्त्वा तिष्ठेच्चिदनुरोधतः। एषोऽभ्युपायः सर्वत्र वेदान्तेषु प्रतिष्ठितः। तत्त्वमस्यादिवाक्यार्थज्ञानोत्पत्त्यर्थमादरात्। इति। एवं व्यतिरेकमुक्त्वान्वयमाह योगयुक्त इति। मुनिः संन्यासी नचिरेण शीघ्रमेव ब्रह्माधिगच्छति वाक्यश्रवणमात्रेण नतु केवलसंन्यासी। यथोक्तंन च संन्यसनादेव सिद्धिं समधिगच्छति। इति।'),
('nilakantha-sc:source:5.7','Nīlakaṇṭha','gita.5.7','sa','commentary','।।5.7।।योगेति। योगेन निर्विकल्पसमाधिना युक्तो योगयुक्तः। अत एव विशुद्धात्मा वृत्तिसारूप्यदोषेण हीनः आत्मा प्रत्यक्चेतनो यस्य। निर्विकल्पावस्थायां केवल एव चेतनोऽस्ति नान्यदेत्युक्तं तदा द्रष्टुः स्वरूपेऽवस्थानं वृत्तिसारूप्यमितरत्रेति तदा वृत्त्यभावे इतरत्र वृत्तिकाले इति सौत्रपदद्वयार्थः। अत्र हेतुः। यतोऽयं विजितात्मा विजितचित्तो जितेन्द्रियश्च। एवं शुद्धस्त्वंपदार्थ उक्तस्तस्य तत्पदार्थाभेदमाह सर्वभूतात्मेति। सर्वेषां भूतानां ब्रह्मादिस्तम्बपर्यन्तानां वियदादीनां च चेतनाचेतनानामात्मभूतः उपादानत्वेन स्वरूपभूतः कनकमिव कुण्डलादीनां स्वरूपभूतम्। कारणानन्यत्वात्कार्यस्य। सर्वभूतात्मभूत आत्मा प्रत्यक्चेतनो यस्य स सर्वभूतात्मभूतात्मा। यत्तु सर्वेषां भूतानामात्मभूत आत्मा यस्येति भाष्यं सर्वभूतात्मेत्येतावतैवार्थलाभादात्मभूत इत्यधिकमिति दूषितम्। स्वयं च सर्वभूत आत्मभूतश्चात्मा यस्येति विग्रहो दर्शितः तत्र संकोचे कारणाभावात्सर्वपदेनैव चिज्जडयोर्ग्रहे परस्याप्यात्मभूतेत्यधिकमेव। सर्वभूतश्चेतनाचेतनप्रपञ्चभूत आत्मा यस्येति तत्रापीष्टार्थलाभात् सर्वं च आत्मानश्च तद्भूत आत्मा यस्येति विगृह्य सर्वात्मभूतात्मेत्येतावतैव सिद्धे प्रथमभूतपदस्य वैयर्थ्यं च भाष्यमते ब्रह्मादीनां प्रत्यग्भूत आत्मा यस्येति श्रुत्यैव जीवेशाभेद उच्यते। परस्य तूपादानत्वलिङ्गेन जडसाधारण्येन जीवस्य ब्रह्माभेदोऽवगम्यत इति विद्वद्भिरविनयः क्षन्तव्यः। यतोऽयं सर्वेषां प्रत्यगात्मा अतोऽहमिव सोऽपि कुर्वन्नपि न लिप्यते असङ्गात्मज्ञानात्कर्त्रादेर्बाधितत्वाच्च। व्युत्थाने तत्प्रतीतावप्युत्खातदंष्ट्रोरगवदबाधकत्वाच्चेत्यर्थः।'),
('nilakantha-sc:source:5.8','Nīlakaṇṭha','gita.5.8','sa','commentary','।।5.8 5.9।।न लिप्यत इत्येतदुपपादयति नैवेति द्वाभ्याम्। तत्त्ववित् अहं नैव किंचित्करोमीति मन्येत मन्यते। तत्र हेतुः। इन्द्रियाणि उपलक्षणमिदं प्राणादेरपि। इन्द्रियादय इन्द्रियार्थेषु स्वेषु विषयेषु वर्तन्ते इति धारयन्निश्चिन्वन्नत्वहं विषयेषु वर्ते इति मन्यते। धारयन्निति हेतौ शतृप्रत्ययः। अत्र दर्शनादयः पञ्चज्ञानेन्द्रियाणां व्यापाराः। गमनविसर्गप्रलपनग्रहणानि कर्मेन्द्रियाणाम्। तानिच आनन्दस्योपलक्षणानि। श्वसन्निति प्राणस्य स्वपन्निति बुद्धेः उन्मेषणनिमेषणे कूर्माख्यप्राणस्येति विभागः। क्रमस्त्वविवक्षितः। एतानि कुर्वन्नप्यभिमानाभावान्न लिप्यत इत्यर्थः।'),
('nilakantha-sc:source:5.9','Nīlakaṇṭha','gita.5.9','sa','commentary','।।5.8 5.9।।न लिप्यत इत्येतदुपपादयति नैवेति द्वाभ्याम्। तत्त्ववित् अहं नैव किंचित्करोमीति मन्येत मन्यते। तत्र हेतुः। इन्द्रियाणि उपलक्षणमिदं प्राणादेरपि। इन्द्रियादय इन्द्रियार्थेषु स्वेषु विषयेषु वर्तन्ते इति धारयन्निश्चिन्वन्नत्वहं विषयेषु वर्ते इति मन्यते। धारयन्निति हेतौ शतृप्रत्ययः। अत्र दर्शनादयः पञ्चज्ञानेन्द्रियाणां व्यापाराः। गमनविसर्गप्रलपनग्रहणानि कर्मेन्द्रियाणाम्। तानिच आनन्दस्योपलक्षणानि। श्वसन्निति प्राणस्य स्वपन्निति बुद्धेः उन्मेषणनिमेषणे कूर्माख्यप्राणस्येति विभागः। क्रमस्त्वविवक्षितः। एतानि कुर्वन्नप्यभिमानाभावान्नलिप्यत इत्यर्थः।'),
('nilakantha-sc:source:5.10','Nīlakaṇṭha','gita.5.10','sa','commentary','।।5.10।।ब्रह्मणीति। यतो विद्वानसङ्गत्वात्कुर्वन्नपि न लिप्यते तस्मादविद्वानपि ब्रह्मणि सर्वान्तर्यामिणि कर्माण्याधाय अयमेव कारयिता नत्वहं कर्तेति समर्प्य यः कर्माणि करोति सः पापेन न लिप्यतेऽम्भसा पद्मपत्रमिव।'),
('nilakantha-sc:source:5.11','Nīlakaṇṭha','gita.5.11','sa','commentary','।।5.11।।कायेनेति। केवलैरिति विपरिणामेन सर्वत्र संबन्धनीयम्। केवलेन कायेन अहमयं ब्राह्मणो युवेत्यात्माध्यासशून्येन। एवमन्यत्रापि सङ्गं त्यक्त्वा देहादिभ्यो विविक्तेऽपि आत्मनि तार्किकादिवदहं करोमीत्यभिनिवेशं त्यक्त्वा योगिनः कर्म कुर्वन्ति। आत्मशुद्धये चित्तशुद्ध्यर्थम्। तस्मात्तवापि तत्रैवाधिकारोऽस्तीति तदेव त्वं कुरु।'),
('nilakantha-sc:source:5.12','Nīlakaṇṭha','gita.5.12','sa','commentary','।।5.12।।किंच युक्त इति। युक्तो ब्रह्मण्याधाय कर्माणीत्यादिनोक्तलक्षणः कर्मणां फलं त्यक्त्वा ईश्वरे समर्प्य शान्तिं कैवल्यं नैष्ठिकीं सत्वशुद्ध्यादिक्रमप्राप्तब्रह्मनिष्ठाफलभूतां प्राप्नोति। अयुक्तस्तद्विपरीतः कामकारेण स्वैरवृत्त्या फले सक्तः सन् नितरां बध्यते।');
INSERT INTO commentary_fts (unit_id,author,canonical_ref,language,content_type,content) VALUES
('nilakantha-sc:source:5.13','Nīlakaṇṭha','gita.5.13','sa','commentary','।।5.13।।एवमविद्वान्फलासक्त्यनासक्तिवशात्कर्मभिर्बध्यते न बध्यते चेत्युक्तम् विद्वांस्तु तद्विपरीत इत्याह सर्वकर्माणीति। वशी जितचित्तः समाधिस्थो योगी नवद्वारे नवैव पञ्चज्ञानेन्द्रियाणि षष्ठः प्राणस्तेनैव तत्प्रवर्त्यानां कर्मेन्द्रियाणां संग्रहः। बुद्ध्यहंकारचित्तानीति नव। एतानि द्वाराणीव पुरपतेर्जीवस्य भोगार्थं विषयप्रवेशस्थानानि यस्मिन्नवद्वारे शरीराख्ये पुरे विचित्रवासनाकल्पितानन्तविषयवति अनेकैः कर्मसचिवैरधिष्ठिते सुखदुःखादिनानापण्यवति मनसा सर्वद्वारोद्धाटनकुञ्चिकया सह सर्वाणि कर्माणि पुरपतिरिव राजकार्याणि संन्यस्य सुखं निर्विकल्पसंविन्मात्ररूपेणास्ते। कर्माणि क्षेत्रस्यैव धर्मो नत्वात्मन इति क्षेत्रे त्यक्तुं शक्यान्येव। तथाच श्रुतिःशरीरे पाप्मनो हित्वा इति।यत्र सुहार्दः सुकृतो मदन्ते विहाय रोगं तन्वा्ँस्वायाम् इति च। देही सन् देहाभिमानकाले। व्युत्थानेऽपीत्यर्थः। तदापि नैव कुर्वन्नास्ते नापि कारयन्नास्ते राजेवामात्येषु निहितभारः। समाधौ क्षेत्रेण सहात्मनः संबन्धाभावदर्शनात्। यद्वा नवद्वाराणि चक्षुःश्रोत्रनासाबिलद्वन्द्वानि षट् सप्तमं मुखं अधस्तने द्वे इति। अस्मिन्पक्षे इन्द्रियाणि परिचारका बुद्धिरमात्योऽहंकारो युवराज इत्यादिकमूह्यम्। विदुषः कर्मसंबन्ध एव नास्ति दूरे तत्फलासक्त्यनासक्ती इति भावः।'),
('nilakantha-sc:source:5.14','Nīlakaṇṭha','gita.5.14','sa','commentary','।।5.14।।नन्वेवं भृत्यवत्कर्तृत्वं स्वामिवत्कारयितृत्वं वास्य मास्तु। अयस्कान्तवदविकारस्यैव सतः कर्त्रादिधर्मकाहंकारादिप्रवर्तकत्वमस्त्वित्याशङ्क्याह न कर्तृत्वमिति। कर्तृत्वमहंकारस्य कर्माणीन्द्रियाणां वचनादानादीनि श्रवणदर्शनादीनि च। लोकस्य लोक्यते प्रकाश्यत इति लोको जडवर्गः प्रभुश्चिदात्मा सूर्य इवास्मदादीनां प्रकाशकोऽपि न कर्मादौ प्रवर्तकस्तद्वदस्य कर्मफलसंयोगं वा न सृजति किंतु यो यादृक् यस्य स्वभावः स तथा प्रवर्तते। यथा सूर्येऽभ्युदिते कमलानां विकसनं कुमुदानामुन्मुद्रणं चेति तद्वदेवमात्मनि प्रकाशमाने घटादयो न चेष्टन्ते मनुष्यादयस्तु चेष्टन्ते। नत्वात्मा कस्यचित्प्रवर्तको निवर्तको वा। लोहायस्कान्तयोरिव सत्यानृतयोरात्मानात्मनोः संबन्धाभावादिति भावः।'),
('nilakantha-sc:source:5.15','Nīlakaṇṭha','gita.5.15','sa','commentary','।।5.15।।ननुएष ह्येव साधु कर्म कारयति तं यमेभ्यो लोकेभ्य उन्निनीषते एष ह्येवासाधु कर्म कारयति तं यमधो निनीषते इति श्रुत्या परमेश्वरे कारयितृत्वं बोध्यते। तत्कथमुच्यतेस्वभावस्तु प्रवर्तते इति तत्राह नादत्त इति। कस्यचित्कर्तुः पापमयं नादत्ते नापि सुकृतम्। कारयितृत्वाभावात्। यतो विभुर्व्यापकः। निष्क्रिय इति यावत्। सक्रियो ह्यन्यं प्रवर्तयति तदीयं पापं पुण्यं वा लभते। अयं तु न तथा किंतु सूर्यवत् प्रकाशत एव नतु स्वप्रकाश्यानां कर्त्रादीनां कर्मणा संबध्यते इति भावः। कारयितृत्वमप्यस्य सत्तामात्रेण सूर्यवत्। यथा घटः प्रकाशते सविता प्रकाशयतीति नोदाहृतश्रुतिविरोधः। कथं तर्हि ईश्वराराधनार्थं कर्माणि कुर्वन्ति तदकरणाच्च बिभ्यतीत्याशङ्क्याह अज्ञानेनेति। यथा हि महाराजस्य सार्वभौमस्याहं सर्वेश्वरो निर्वृतोऽस्मीति ज्ञानं अज्ञानेन सौषुप्तेनावृतं चेत्स तत्र विविधानि परचक्रादीनि महान्ति संकटशतानि पश्यति अहो अहं दीनोऽस्मिदुःख्यस्मीति च मुह्यति तद्वदेते जन्तवः स्वस्याहं ब्रह्मास्मीति प्रमाणेन ब्रह्मभावमजानन्त ईश्वरादात्मानं पृथङ्मन्यमाना ईशात्मनोः सेव्यसेवकभावं च पश्यन्तो मुह्यन्ति। तथाच श्रुतिःअथ योऽन्यां देवतामुपास्तेऽन्योऽसावन्योऽहमिति न स वेद यथा पशुरेव स देवानाम् इति। एष ह्येवेति श्रुतिरपि भ्रान्तजनव्यवहारविषयैवेति भावः।'),
('nilakantha-sc:source:5.16','Nīlakaṇṭha','gita.5.16','sa','commentary','।।5.16।।तदात्मन आवरकमज्ञानं येषां ज्ञानेन ब्रह्मास्मीति प्रमाणजेन नाशितं तेषां तज्ज्ञानं कर्तु आदित्यवदादित्यो यथा कृत्स्नं दृश्यं प्रकाशयति तद्वत्परं परमार्थवस्तु प्रकाशयति। अज्ञानजानर्थनिवृत्त्यर्थं ज्ञानमेष्टव्यमिति भावः।'),
('nilakantha-sc:source:5.17','Nīlakaṇṭha','gita.5.17','sa','commentary','।।5.17।।तद्बुद्धय इति। यत् परं ब्रह्म प्रशान्तं तत्रैव बुद्धिरस्ति ब्रह्मेति निश्चयो येषामापाततः श्रुत्यर्थविदां ते तद्बुद्धयः तदेव आत्मा प्रत्यक्तत्त्वं येषां श्रवणमननात्मकविचारेण प्रमाणप्रमेयगतासंभावनाविहीनानां ते तदात्मानः तत्रैव निष्ठा विजातीयवृत्त्यनन्तरितसजातीयवृत्तिप्रवाहो येषां देहादावनात्मन्यात्मधीरूपविपरीतभावनारहितानां ते तन्निष्ठाः तदेव परमयनमज्ञानरूपोपाधिनिरासेन प्राप्यं येषामखण्डानन्दमग्नानां ते तत्परायणाः अपुनरावृत्तिं मोक्षं गच्छन्ति। यतो ज्ञानेन निर्धूतं कल्मषं मूलाज्ञानं संसारबीजभूतं येषां ते ज्ञाननिर्धूतकल्मषाः।'),
('nilakantha-sc:source:5.18','Nīlakaṇṭha','gita.5.18','sa','commentary','।।5.18।।एतेषां जगति दृष्टिमाह विद्येति। उत्तमब्राह्मणे चण्डालादौ वा समं ब्रह्मैव सद्रूपेण स्फुरणरूपेण च भासमानं द्रष्टुं शीलं येषां ते समदर्शिनः। यथोक्तम्अस्ति भाति प्रियं रूपं नाम चेत्यंशपञ्चकम्। आद्यं त्रयं ब्रह्मरूपं जगद्रूपं ततो द्वयम्। इति। चराचरं जगद्ब्रह्मदृष्ट्यैव पश्यन्तीत्यर्थः।'),
('nilakantha-sc:source:5.19','Nīlakaṇṭha','gita.5.19','sa','commentary','।।5.19।।ननुसमासमाभ्यां विषमसमे पूजातः इति तुल्यश्रुतशीलाय ब्राह्मणद्वयाय विषमां पूजां प्रयुक्तवतः तथा अतुल्यश्रुतशीलाय ब्राह्मणद्वयाय समां पूजां प्रयुक्तवतश्चाभोज्यान्नत्वं गौतमेन स्मर्यते तत्कथं ब्राह्मणचण्डालयोः समदर्शित्वं युक्तमित्याशङ्क्याह इहैवेति। येषां मनः सर्वभूतेषु साम्ये ब्रह्मभावे स्थितं निश्चलं तैरिहैव जीवद्भिरेव सर्गो जन्म जितो वशीकृतः। हि यस्मान्निर्दोषं समं सर्वत्राविषमं ब्रह्मास्ति यथा हिरण्मययोर्देवतातत्पीठयोः स्वर्णदृक्साम्यं पश्यति पूजकस्तु आकारदृक्तारतम्यं पश्यति तद्वत्। पूजास्मृतिर्भ्रान्तिकृततारतम्यविषया। साम्यदृष्टिस्तु तत्त्वविषयेति भावः। यस्मादेवं ते साम्यं पश्यन्ति तस्माद्ब्रह्मण्यखण्डैकरसे ते द्रष्टारः स्थिता एकीभावेन समाप्तिं गताः।'),
('nilakantha-sc:source:5.20','Nīlakaṇṭha','gita.5.20','sa','commentary','।।5.20।।न प्रहृष्येदिति। यस्मान्निर्दोषं समं ब्रह्म तस्मात् प्रियं पुत्रादिं प्राप्य न प्रहृष्येत्। अप्रियं शत्रुं दुःखदं प्राप्य नोद्विजेत्। बुद्धस्थितिरबुद्धेनानुष्ठेयति ज्ञापयितुमुभयत्र लिङ्प्रयोगः। स्थिरबुद्धिः प्रत्यगद्वैते श्रुतियुक्तिभ्यां स्थिरीकृतप्रज्ञः। असंमूढो ध्यानजसाक्षात्कारेण निर्गतमोहः। अतएव ब्रह्मविद्ब्रह्मभावस्य लब्धा। ब्रह्मभावं गत इत्यर्थः। ब्रह्मण्येव प्रत्यगद्वये व्युत्थानावस्थायामपि स्थितः। सर्वं ब्रह्मेत्येव पश्यन्नित्यर्थः।'),
('nilakantha-sc:source:5.21','Nīlakaṇṭha','gita.5.21','sa','commentary','।।5.21।।नन्वननुभूतात्मसुखेप्सया प्रसिद्धं बाह्यं सुखं त्यक्तुमशक्यमतो न प्रहृष्येदित्यसंगतमत आह बाह्येति। बहिर्भवाः बाह्याः स्पर्शा विषयेन्द्रियसंबन्धास्तेषु असक्तात्माऽनासक्तचित्तः सन्नात्मनि प्रत्यगद्वयानन्दे सुषुप्तिकाले स्थित्वा यत्सुखं विन्दति लभते स तदेव सुखम्। विधेयापेक्षं पुंस्त्वम्। कस्तत्सुखम्। यो ब्रह्मयोगे ब्रह्मणि योगः समाधिस्तत्र युक्तो योजित आत्मा बुद्धिर्येन स ब्रह्मयोगयुक्तात्मा। ब्रह्मविदित्यर्थः।ब्रह्मविद्ब्रह्मैव भवति इति श्रुतेः। ब्रह्मयोगयुक्तात्मा तदेव सुखं विन्दतीति वक्तव्ये ब्रह्मविदेव तत्सुखमिति तस्य सुखाभिन्नत्वविवक्षयेदमुक्तम्। ननूभयत्रैकमेव सुखं चेत्कः सुप्तसमाधिस्थयोर्विशेष इत्याशङ्क्याह सुखमिति। अक्षय्यं सुखं मोक्षस्तमश्नुते व्याप्नोति द्वैतादर्शनस्य तुल्यत्वादुभयत्रैकमेव सुखं तत्रापि योगी मूलाविद्याया नष्टत्वादक्षय्यं सुखमश्नुते न सुप्तः। अविद्यानुच्छेदात्। तथा च मोक्षसुखस्य मुख्यस्याप्यनुभूतत्वात्तदर्थं बाह्यं सुखं सुत्यजमित्यर्थः।'),
('nilakantha-sc:source:5.22','Nīlakaṇṭha','gita.5.22','sa','commentary','।।5.22।।ननु सुषुप्तितुल्यस्य मोक्षसुखस्यार्थे कः प्राप्तमेव बाह्यं दिव्यस्त्र्यन्नपानगीतवाद्यादिसुखं त्यजेदित्याशङ्क्य बाह्यसुखमनित्यत्वान्निन्दति ये हीति। संस्पर्शजा विषयसंबन्धजाः। दुःखयोनित्वे हेतुः आद्यन्तवन्त इति। जाते पुत्रे यत्सुखं तत्तस्मिन्नष्टे नश्यति दुःखं च महत्प्रयच्छतीति तेषु भोगेषु बुधः परिपाकदर्शी न रमते।'),
('nilakantha-sc:source:5.23','Nīlakaṇṭha','gita.5.23','sa','commentary','।।5.23।।कः पुनर्मुख्यः सुखीत्याह शक्नोतीति। इहैव जीवत्येव देहे प्राक्शरीरविमोक्षणाद्यावद्देहपातं मया कामक्रोधौ जिताविति विस्रम्भो न कर्तव्य इत्यर्थः। श्रुते दृष्टेऽनुमिते वा विषये यो गर्धस्तृष्णारूपोऽतृप्तिश्च स कामः क्रोधस्तादृशे एव विषये द्वेषस्तौ कामक्रोधावुद्भवो यस्य वेगस्य स रोमाञ्चहृष्टनेत्रवक्त्रलिङ्गोऽन्तःकरणप्रक्षोभरूपः कामोद्भवो वेगः। गात्रप्रकम्पप्रस्वेदसंदष्टौष्ठपुटरक्तनेत्रादिलिङ्गः क्रोधोद्भवो वेगस्तं कामक्रोधोद्भवं वेगं सोढुं यः शक्नोति स एव युक्तो योगी मुख्यः सुखी च नान्यः।'),
('nilakantha-sc:source:5.24','Nīlakaṇṭha','gita.5.24','sa','commentary','।।5.24।।कोऽसौ योगी यो मुख्यः सुखीत्युक्तं तत्राह य इति। सुखं विषयसङ्गजा प्रीतिः आरामः प्रीतिहेतुः स्त्र्यादिभिः सह क्रीडा ज्योतिः क्रीडोपकरणानां प्रकाशः तदेतत्त्र्यं यस्यान्तरेव सोऽन्तःसुखोऽन्तरारामोऽन्तर्ज्योतिश्च न त्विन्द्रियद्वारकमिति एवशब्दार्थः। य एवंभूतः स योगी किमतो यद्येवं ब्रह्मनिर्वाणं गत्यप्राप्यपरमानन्दं ब्रह्म इहैवाधिगच्छति। यतो ब्रह्मभूतो जीवन्नेव ब्रह्मदर्शने ब्रह्मभावं गतः।'),
('nilakantha-sc:source:5.25','Nīlakaṇṭha','gita.5.25','sa','commentary','।।5.25।।लभन्त इति। ऋषयः सम्यग्दर्शिनः। छिन्नद्वैधाश्छिन्नसंशयाः। यतात्मानो जितचित्ताः।'),
('nilakantha-sc:source:5.26','Nīlakaṇṭha','gita.5.26','sa','commentary','।।5.26।।किञ्च कामेति। अभितो जीवतां मृतानां च विदितात्मनां ज्ञातात्मतत्त्वानाम्।'),
('nilakantha-sc:source:5.27','Nīlakaṇṭha','gita.5.27','sa','commentary','।।5.27।।एवं सम्यग्दर्शननिष्ठानां सद्योमुक्तिरुक्ता कर्मयोगश्च सङ्गफलत्यागेन ईश्वरप्रीत्यर्थमनुष्ठितः सत्त्वशुद्धिज्ञानप्राप्तिद्वारेण मोक्षाय भवतीत्यप्युक्तं अथेदानीं सम्यग्दर्शनस्यान्तरङ्गसाधनं ध्यानयोगं विस्तरेण वक्ष्यामीति तत्सूत्रभूतांस्त्रीन्श्लोकानुपदिशति स्पर्शानिति। अत्रोत्तरार्धेन प्राणायाम उक्तः स्पर्शान्कृत्वा बहिर्बाह्यानिति प्रत्याहर उक्तः भ्रुवोरन्तरे चक्षुः कृत्वेति धारणोक्ता विगतेच्छाभयक्रोध इति साधनभूताः फलभूताश्च द्विविधा यमा नियमाश्चोक्ताः यतेन्द्रिय इति वितर्काख्यः संप्रज्ञातः यतमान इति विचाराख्यः यतबुद्धिरित्यानन्दास्मिताख्यौ मोक्षपरायण इत्यसंप्रज्ञात उक्तः शेषेण योगफलमिति विभागः। पाठक्रममनुरुध्यार्थक्रमेणाक्षरार्थः स्पष्टीक्रियते। तत्र विगतेच्छो विगतभयो विगतक्रोध इति संबन्धः। यो हि इच्छावान्स इष्टसिद्ध्यर्थं हिंसानृतस्तेयस्त्रीपरिग्रहानिच्छेत्। अतो विगतेच्छपदेन तद्विपर्ययान्अहिंसासत्यास्तेयब्रह्मचर्यापरिग्रहा यमाः इति सूत्रोक्तान्यमाँल्लक्षयति। तथा भयं स्वोच्छेदशङ्का तया ह्युद्विग्नो नशौचसंतोषतपःस्वाध्यायेश्वरप्रणिधानानि नियमाः इति सूत्रोक्तान्नियमान्स्वीकर्तुमिच्छेदतो विगतभय इत्यनेन तेषां ग्रहणम्। तथा क्रोधाक्रान्तो मैत्र्यादीन्भावयितुमशक्तश्चित्तप्रसाधनं कर्तुं न शक्नोति। तच्चमैत्रीकरुणामुदितोपेक्षाणां सुखदुःखपुण्यापुण्यविषयाणां भावनातश्चित्तप्रसाधनं इति सूत्रितम्। तत्र विगतक्रोधः शान्तप्रकृतित्वात्सुखितेषु मैत्रीं परस्येष्टे न ममैवेष्टमिदं जातमिति भावयेत्। तथा दुःखितेषु करुणां पुण्यवत्सु मुदितां पापवत्सूपेक्षां च भावयेत्। नचैतेन प्रसाधनेन विना चित्तादर्शस्य नैर्मल्यं भवति एवं साधनावस्थायां यमनियमचित्तप्रसाधनानां सिद्ध्यर्थं विगतेच्छाभयक्रोधत्वमीप्सितम्। एवं फलावस्थायामपि तदीप्सितम्। तथाहि संप्रज्ञातसमाधिफलभूतायां मधुमत्यां योगभूमौ स्थितं योगिनं प्रति दिव्याः कामा उपतिष्ठन्ते तत्रापि विगतेच्छत्वमिष्टम्। तथाहिस्थान्युपनिमन्त्रणे सङ्गस्मयाकरणं पुनरनिष्टप्रसङ्गात् इति सूत्रम्। स्थानिनो देवास्तैरुपनिमन्त्रणे इहास्यतां इमे रम्यावसथाः इमा रम्या रमाः इमानि जरामरणहराणि रसायनानि इमे वयं किंकराः स्वपुण्यार्जितमिदं स्थानं त्वया भुज्यतामिति प्रार्थनायां क्रियमाणायां सङ्गो लिप्सा तत्र न कर्तव्या नापि तल्लाभेनात्मनो महाभागत्वं देवप्रार्थ्यत्वं मत्वा गर्वोऽपि कर्तव्यस्तयोः सङ्गस्मययोर्भ्रंशहेतुत्वादिति सूत्रार्थः। तथा भयमपि द्विविधं योगान्तरायजं वितर्कजं च। तत्राद्यंव्याधिस्त्यानसंशयप्रमादालस्याविरतिभ्रान्तिदर्शनालब्धभूमिकत्वानवस्थितत्वानि चित्तविक्षेपास्तेऽन्तरायाःदुःखदौर्मनस्याङ्गमेजयत्वश्वासप्रश्वासाविक्षेपसहभुवः इति सूत्राभ्यामुक्तं। स्त्यानं अकर्मण्यता अविरतिरवैराग्यं अङ्गमेजयत्वं कंपवायुः वितर्काहिंसादयस्तज्जं च भयं आद्यस्य निवारणं ईश्वरप्रणिधानेन। तथा च सूत्रिंतततः प्रत्यक्चेतनाधिगमोऽन्तरायाभावश्च इति। तत ईश्वरप्रणिधानात् द्वितीयस्य प्रतिपक्षभावनेन। तथाच सूत्रितम्वितर्कबाधने प्रतिपक्षभावनम् इति।वितर्का हिंसादयः कृतकारितानुमोदितालोभक्रोधमोहमूला मृदुमध्याधिमात्रा दुःखाज्ञानानन्तफला इति प्रतिपक्षभावनम् इति च। आदिपदादनृतस्तेयादयः। हिंसादयः प्रत्येकं कृतकारितानुमोदितभेदेन त्रिविधाः। तेऽपि प्रत्येकं लोभादिमूलकत्वेन त्रिविधाः। तेऽपि मृदुमध्यमाधिमात्रभेदेन प्रत्येकं त्रिविधाः। ते च मूलभूता वितर्कास्त्रयश्चत्वारः पञ्च अधिका वा त्रिस्त्रिगुणिता एकाशीतिरष्टोत्तरशतं पञ्चत्रिंशदधिकं शतमधिका वा भवन्ति। शाखाप्रशाखाभेदेनानन्ताश्च। दुःखरूपमज्ञानरूपं चानन्तफलं येषां ते दुःखाज्ञानानन्तफला इत्यनया प्रतिपक्षभावनया ते निवर्तनीया इति। एवं यमनियमचित्तप्रसाधनप्रतिपक्षभावनैर्निरन्तरायं मृदूकृतचित्तो योगी विविक्ते देशेआसीनः संभवात् इति न्यायेन स्थिरसुखमासनमध्यासीत। तत्र देशासने श्रूयेतेसमे शुचौ शर्करवह्निवालुकाविवर्जिते शब्दजलाश्रयादिभिः। मनोनुकूले नतु चक्षुपीडने गुहानिवाताश्रयणे प्रयोजयेत्। त्रिरुन्नतं स्थाप्य समं शरीरं हृदीन्द्रियाणि मनसा संनिरुध्य। ब्रह्मोडुपेन प्रतरेत विद्वान्स्रोतांसि सर्वाणि भयावहानि। इति। चक्षुरित्यत्र विसर्गलोपश्छान्दसः। त्रिरुन्नतं कटिवक्षःकन्धराप्रदेशेषून्नतम्। ततो जितासनः प्राणायाममभ्यसेत्। तेन हि मन्दगतौ प्राणे सति तदनुसारि मनोऽपि चाञ्चल्यं त्यजति। नोचेद्वायुविक्षेपेण विक्षिप्यते। तत्र प्राणजयप्रमाणम्प्राणान्प्रपीड्येह सयुक्तचेष्टः क्षीणे प्राणे नासिकयोच्छ्वसीत इति श्रुत्युक्तमेव संगृह्णाति। प्राणापानौ समौ कृत्वा नासाभ्यन्तरचारिणौ इति। प्राणापानौ समौ तुल्यावूर्ध्वाधोगतिविच्छेदेन नासाभ्यन्तरचारिणौ कुम्भकेन कृत्वा ततो बाह्यान्बहिर्भवान्स्पर्शान्विषयसंबन्धानिन्द्रियद्वारा नित्यमन्तर्बुद्धौ क्रियमाणान् योगीन्द्रियाणां प्रत्याहरणेन तान्बहिरेव कुर्यात्। ततो विषयेभ्यो व्यावृत्तेषु करणेषु स्वप्नकाले इवान्तर्मनोमात्रेणावतिष्ठत इत्यर्थः। इमं प्रत्याहारं कर्तुमशक्तस्याविरक्तस्य का गतिरित्यत आह चक्षुश्चैवान्तरेभ्रुवोरिति। चशब्दो वार्थे। चक्षुरेव वा भ्रुवोरन्तरे कुर्यात्। खेचरीं मुद्रामभ्यस्येदित्यर्थः। सा चोक्ता योगसारेलम्बिकोर्ध्वस्थिते गर्ते जिह्वां व्यावृत्य धारयेत्। दृढासनश्चिरं तिष्ठेन्मुद्रैषा खेचरी मता। भ्रूमध्यदृष्टिरप्येषा महादेवेन कीर्तिता इति। य एवं सर्वोऽपि बाह्ये विषये सूर्यादौ संयमो यथोक्तं प्रत्याहारमनुष्ठातुमशक्तान्प्रत्येवोपदिश्यत इति ज्ञेयम्।'),
('nilakantha-sc:source:5.28','Nīlakaṇṭha','gita.5.28','sa','commentary','।।5.28।।यतेन्द्रियेति। यस्मिन्कस्मिंश्चित्स्थूले विषये सूर्ये तद्रश्मिषु वा विष्णुप्रतिमायां वाऽनाहतध्वनौ वान्यत्र वा चक्षुराद्यन्यतमद्वारा मनो धारयेत्। तच्च मनस्तद्विषयाकारतां प्राप्तं तत्रैव स्थिराभ्यासेन विश्रान्तं स्वदेहमपि न पश्यति सेयं महाविदेहा नाम धारणा। अस्यां सिद्धायामिन्द्रियगणः स्वंस्वं विषयं न तु गृह्णाति। सोऽयं बहिर्विषयप्रत्याहारः पूर्वोक्तस्त्वान्तर इति भेदः। अतएव तयोस्तुल्यफलत्वं सूत्रितम्ततः क्षीयते प्रकाशावरणम् इति। ततः अभ्यन्तरप्रत्याहारत् तथा बहिरकल्पिता वृत्तिर्महाविदेहा तत्संयमात्प्रकाशावरणक्षय इति। यदा चित्तं देहमविस्मृत्यैव हठेन पुरःस्थितमूर्त्याद्याकारं क्रियते तदा सा चित्तस्य मूर्त्याकारतारूपा वृत्तिः कल्पिता। यदा तु निरवशेषेण देहं विस्मृत्य चेतः केवलं ध्येयाकारमात्रं भवति सदा सा महाविदेहा नाम धारणा। तस्या अपि फलं तदेव। तत्संयमात्तस्यां चेतसो निग्रहात्प्रकाशावरणक्षयो भवति सोयं बाह्यविषयः समाधिः। वितर्काख्यो द्विविधः सवितर्कनिर्वितर्कभेदात्। तत्राद्यस्य लक्षणं सूत्रितंशब्दार्थज्ञानविकल्पैः संकीर्णा सवितर्का इति। सवितर्का नाम समापत्तिः समाधिरित्यर्थः। यदा विष्णुप्रतिमादौ पूर्वापरानुसंधानेन शब्दार्थोल्लेखेन च भावना प्रवर्तते तदा सवितर्का समापत्तिः। अस्मिन्नेवालम्बने पूर्वापराननुसंधानेन शब्दार्थोल्लेखनमन्तरेण भावना प्रवर्तते तदा निर्वितर्का नाम समापत्तिः। तथा च सूत्रंस्मृतिपरिशुद्धौ स्वरूपशून्ये वार्थमात्रनिर्भासा निर्वितर्का। स्मृतेः शब्दार्थस्मरणस्य परिशुद्धौ वर्जने सति भावयितुः स्वरूपेण शून्या तदाहमिदं भावयामीत्येवमाकारा वृत्तिरपि भावयितुर्नास्तीवेति भाति। यतोऽर्थमात्रनिर्भासा ध्येयार्थमात्रमस्यां भासते नत्वन्यदिति सूत्रार्थः। अस्यां सिद्धायां योगी जितेन्द्रिय इत्युच्यते। जितमना इति आभ्यन्तरप्रत्याहारपूर्वकं यदा मनःकल्पिते सूक्ष्मे विषये पूर्ववच्छब्दार्थोल्लेखपूर्वकं तद्वर्जं च मनसो भावना प्रवर्तते तदा ते उभे समापत्ती सविचारनिर्विचाराख्ये भवतः। तथा च सूत्रंएतयैव सविचारा निर्विचारा च सूक्ष्मविषया व्याख्याता इति। अत्र सूक्ष्मविषयेति ग्रहणात्पूर्वस्यां स्थूलविषयत्वं गम्यते। एतयैव द्विविधवितर्कसमापत्त्यैव निर्विचारसमापत्तौ दृढायां योगी जितमना इत्युच्यते। यदा पुनश्चेतसो मूर्त्याकारतां परित्यज्य सत्त्वोद्रेकात्समष्टिमनोमयविषया अहमेवेदं सर्वोऽस्मीत्येवमाकारा भावनाप्रवर्तते सोऽयं सानन्दः समाधिः। यदा तु तामपि भावनां परित्यज्य विषयवेदनमन्तरेणास्मीत्येतावन्मात्राकारा भावना प्रवर्तते साऽस्मिता। अस्मिताहंकारयोर्भेदस्तु क्रमेण विषयवैमुख्यतदाभिमुख्यमात्रकृतः। यथैक एव पूर्वाभिमुखः पश्चिमाभिमुखश्चेति तद्वत्। अस्यामवस्थायां योगी बुद्धितो विविक्तस्य त्वंपदार्थस्य साक्षात्काराज्जितबुद्धिरित्युच्यते। तदेतदुक्तं यतेन्द्रियमनोबुद्धिरिति। एतान्येव प्रसाधनानि गुणपर्वाण्युच्यन्ते। तथा च सूत्रम्विशेषाविशेषलिङ्गमात्रालिङ्गानि गुणपर्वाणि इति। तत्र विशेषाः स्थूलभूतानि एकादशेन्द्रियाणि च। अविशेषाः पञ्चतन्मात्राणि अहंकारश्च। लिङ्गमात्रं महत्तत्वम्। अलिङ्गं प्रधानम्। तत्र विशेषादविशेषं प्रविविक्षितो योगिनो दैनंदिनलयाभ्यासात्समनस्कानीन्द्रियाणि लीयन्ते स लयः। बहिर्मुखान्येव वा भवन्ति स विक्षेपः। एवमविशेषेभ्यो लिङ्गमात्रं विविक्षतोऽपि लयविक्षेपौ स्तः। लिङ्गमात्रात्परं पुरुषं प्रविविक्षतोऽपि तौ स्तः। तावेतौ लयविक्षेपौ हेयौ श्रूयेतेलयविक्षेपरिहतं मनः कृत्वा सुनिश्चलम्। यदा यात्युन्मनीभावं तदा तत्परमं पदम्। इति। एतेषु त्रिषु लीनेष्वाद्यः सुप्त एव। द्वितीयो विगलितदेहाहंकारत्वाद्विदेहसंज्ञः। तृतीयः प्रकृतिलय इति। एतयोः समाधिर्गौणः। अतएव सूत्रितम्भवप्रत्ययो विदेहप्रकृतिलयानाम् इति। भवप्रत्ययो जन्मान्तरहेतुरेषां समाधिर्भवति। यद्वा जन्मान्तरे एतेषां जन्मनैव समाधिसिद्धिः पक्षिणामाकाशगमनसिद्धिवद्भवतीति सूत्रार्थः। सर्वथापि तेषां सद्योमुक्तिर्नास्तीति सिद्धम्। यदातु अस्मितामात्रस्यापि निर्विकल्पे चिन्मात्रे लयो भवति तदायं विद्वान्कैवल्यं धर्ममेव समाध्याख्यमनुभवति। यमधिकृत्य श्रूयतेक्षणमेकं क्रतुशतस्य चतुःसप्तत्या यत्फलं तदवाप्नोति इति। अयमेव मोक्षाख्यः परमयनं प्राप्यं स्थानं यस्य स मुनिर्मोक्षपरायण इत्युच्यते। यतोऽस्यामेवावस्थायां योगी जीवन्मुक्त इत्युच्यते। विगतेच्छाभयक्रोध इति पादः प्रागेव व्याख्यातः। य एवंभूतः स सदा मुक्तः बन्धप्रतीतिकालेऽपि स मुक्त एवास्ति। अज्ञानमात्रव्यवधानान्मुक्तेः। एतेनाहंकारादेर्बन्धस्य कालत्रयेऽप्यसत्त्वोक्त्या मिथ्यात्वं दर्शितम्।'),
('nilakantha-sc:source:5.29','Nīlakaṇṭha','gita.5.29','sa','commentary','।।5.29।।एवं समाहितचित्तेन किं विज्ञेयमित्युच्यते भोक्तारमिति। सोपाधिकेन रूपेण यज्ञानां तपसां च कर्तृरूपेण देवतारूपेण च भोक्तारम्। तथा सर्वेषां भूतानां हिरण्यगर्भादीनामपि महान्तं व्यापकमीश्वरमीशितारमन्तर्यामिणम्। सुहृदं सर्वभूतानां प्राणिनां प्रत्युपकारनिरपेक्षतयोपकारिणं सर्वप्रत्ययसाक्षिणं नारायणं मां प्रत्यगभेदेन ज्ञात्वा साक्षात्कृत्य तद्भावं प्राप्य शान्तिमनुपाध्यवस्थां निरुपाख्यां कैवल्यसंज्ञां ऋच्छति प्राप्नोति। एवं च सोपाधिब्रह्मभावप्राप्तिपूर्वकैव निरुपाधिप्राप्तिरिति गम्यते। यथोक्तं वार्तिकसारेसोपाधिर्निरुपाधिश्च द्वेधा ब्रह्मविदुच्यते। सोपाधिकः स्यात्सर्वात्मा निरुपाख्योऽनुपाधिकः। जक्षन्क्रीडन्रतिं प्राप्त इति सोपाधिकस्य तु। छान्दोग्ये सर्वकामाप्तिः सार्वात्म्यात्स्पष्टमीरिता। अहमन्नं तथान्नादः श्लोककार्यप्यहो अहम्। इति तत्त्वविदः सामगाने सर्वात्मता श्रुता। अत्रापि चक्रदृष्टान्तात्सोपाधिस्तत्त्वविच्छ्रुतः। अपूर्वानपराद्युक्त्या श्रोष्यते निरुपाधिकः। इति।'),
('nilakantha-sc:source:6.1','Nīlakaṇṭha','gita.6.1','sa','commentary','।।6.1।।पूर्वाध्यायान्ते सूत्रितं ध्यानयोगं विवरीतुमिच्छंस्तत्राधिकारहेतुत्वात्कर्मयोगं तावत्स्तौति द्वाभ्याम् अनाश्रित इति। यः कर्मणां फलमनाश्रितोऽनपेक्षमाणः कार्यमवश्यकर्तव्यं नित्यं कर्म करोति स एव फलसंकल्पत्यागात्संन्यासी च योगी च भवति न तु निरग्निर्यो विधितः श्रौतस्मार्तकर्मत्यागी स एव संन्यासी नापि अक्रियस्त्यक्तवाङ्मनःकायक्रिय एव वा योगीति।'),
('nilakantha-sc:source:6.2','Nīlakaṇṭha','gita.6.2','sa','commentary','।।6.2।।केन साम्येनायं संन्यासी योगी चेति स्तूयते अत आह यमिति। यो हि त्यक्तसर्वसंकल्पः स संन्यासी तादृशश्च ध्यानयोगी अतो न तयोर्भेदः।निःसंकल्पस्तटस्थस्तिष्ठेदेतन्मोक्षलक्षणम् इति मैत्रायणीयोपनिषच्छ्रुतस्य मोक्षलक्षणस्य निःसंकल्पत्वस्योभयत्रापि तुल्यत्वात्। अतोऽयमपि कर्मयोगी फलसंकल्पत्यागान्निःसंकल्पत्वसाम्यात्संन्यासी योगी च भवतीति स्तूयत इत्यर्थः। योगाधिकारसिद्धये निष्कामकर्माण्यनुष्ठेयानीति श्लोकद्वयतात्पर्यार्थः।'),
('nilakantha-sc:source:6.3','Nīlakaṇṭha','gita.6.3','sa','commentary','।।6.3।।तत्र कर्मानुष्ठानस्यावधिमाह आरुरुक्षोरिति। यावद्धि योगं यमनियमाद्यष्टाङ्गोपेतमत्यौत्कण्ठ्यादारोढुमिच्छति तावत्कर्माण्यनुतिष्ठेत्। तस्यारुरुक्षोर्मुनेरारुरुक्षाकारणं तीव्रवैराग्योत्पादनद्वारा कर्म भवति। तस्यैव योगारूढस्य योगाङ्गानुष्ठाने प्रवृत्तस्य विक्षेपासहस्य योगारोहे कर्मणां शमः संन्यासः कारणमुच्यते। नहि कर्मसु व्यापृतोऽनन्यचित्ततया योगमनुष्ठातुमीष्टे।'),
('nilakantha-sc:source:6.4','Nīlakaṇṭha','gita.6.4','sa','commentary','।।6.4।।ननु योगपदेन मुख्यया वृत्त्या निर्बीजः समाधिरुच्यते तमारूढस्य कर्मणां त्यागः स्वतःसिद्धत्वादविधेय इत्याशङ्क्य प्रकृते योगारूढपदस्यार्थमाह यदाहीति। इन्द्रियार्थेषु शब्दादिषु रमणीयेषु कर्मसु च तत्प्राप्तिसाधनेषु तद्दर्शनमनु न सज्जते वैराग्यदाढर्यात्सक्तो न भवति। नापि मनसा इदं मे भूयादेतदर्थमहमिदं कर्म कुर्यामिति संकल्पयति। तादृशश्च सर्वसंकल्पसंन्यासी यदा भवति तदा योगारूढ इत्युच्यते। यथा तीव्रबुभुक्षयोपेतोऽन्यत्र नीरागो व्यासङ्गान्तरं त्यक्त्वा भोजनारूढ एव भवति तथा तीव्रारुरुक्षावान् सर्वत्र वीतरागस्त्यक्तसर्वकर्मा योगारूढ एव भवति। तावत्कर्माणि कर्तव्यानि ततः परं त्याज्यानीत्यर्थः।'),
('nilakantha-sc:source:6.5','Nīlakaṇṭha','gita.6.5','sa','commentary','।।6.5।।उद्धरेदिति। एवं क्रमेण कर्मद्वारा चित्तशुद्धिं संपाद्य योगारूढोऽभ्यासवैराग्यबलेनात्मानमुद्धरेत्। हि यस्मादात्मैवात्मनो बन्धुर्न पुत्रादय उद्धर्तुं क्षमाः। आत्मैव रिपुरात्मनः नत्वन्ये शत्रवः संसारे मज्जयितुमेनं क्षमा इत्यर्थः।'),
('nilakantha-sc:source:6.6','Nīlakaṇṭha','gita.6.6','sa','commentary','।।6.6।।आत्मना मनः आत्मना मनसा अनात्मनः अजितचेतसः आत्मा मन एव शत्रुः।'),
('nilakantha-sc:source:6.7','Nīlakaṇṭha','gita.6.7','sa','commentary','।।6.7।।मनसो जये फलमाह जितात्मन इति। शीतोष्णादिषु प्राप्तेषु जितात्मनो निर्विकारचित्तस्य आत्मा चित्तं परमुत्कर्षेण समाहितः समाधिं प्राप्तो भवति। अतः समाधिसिद्ध्यर्थं मनो जेतव्यमेवेत्यर्थः।'),
('nilakantha-sc:source:6.8','Nīlakaṇṭha','gita.6.8','sa','commentary','।।6.8।।समाधिसिद्धेरपि किं फलमत आह ज्ञानेति। ज्ञानं शास्त्रोपदेशजा बुद्धिः। विज्ञानं शास्त्रार्थध्यानजः प्रमारूपोऽनुभवस्ताभ्यां तृप्तः संजातालंप्रत्यय आत्मा चित्तं यस्य स ज्ञानविज्ञानतृप्तात्मा। यतस्तृप्तात्माऽतः कूटस्थोऽप्रकम्प्यः संसारतापानास्कन्दितो भवतीति समाधिफलम्। अस्य लोकप्रसिद्धं लक्षणमाह विजितेन्द्रिय इति। समलोष्टाश्मकाञ्चन इति एवंविधो योगी स युक्तः प्राप्तयोग इत्युच्यते विद्वद्भिः।'),
('nilakantha-sc:source:6.9','Nīlakaṇṭha','gita.6.9','sa','commentary','।।6.9।।समत्वमेव स्तौति सुहृदिति। सुहृत् प्रत्युपकारमनपेक्ष्योपकर्ता मित्रं स्नेहवान् अरिः शत्रुः उदासीन उभयत्र पक्षपातशून्यः मध्यस्थः उभयहितैषी द्वेष्य आत्मनोऽप्रियः बन्धुः संबन्धी तेषु साधुषु पुण्यकृत्सु पापेषु पापाचारेषु कस्य किं कर्मेत्यनालोचयन् तेषु सर्वेषु यः समबुद्धिः स विशिष्यते।'),
('nilakantha-sc:source:6.10','Nīlakaṇṭha','gita.6.10','sa','commentary','।।6.10।।योगीति। योगी योगाभ्यासपरः रहसि एकान्ते स्थितः सन् आत्मानं बुद्धिं युञ्जीत समादध्यात्। सततमिति नैरन्तर्यमुक्तम्। निराशीर्योगसिद्धेरन्यदप्रार्थयानः तेदकनिष्ठ इति यावत्। तेन सत्कार उक्तः। एकाकीअसहायः संन्यासीत्यर्थः। यतौ स्थिरीकृतौ चित्तं मनः आत्मा सेन्द्रियं शरीरं येन स यतचित्तात्मा। तथा अपरिग्रह एकाकित्वेऽपि कन्थापुस्तकादिबहुपरिग्रहशून्यः।'),
('nilakantha-sc:source:6.11','Nīlakaṇṭha','gita.6.11','sa','commentary','।।6.11।।योगं युञ्जीतेत्युक्तं तत्कथमित्याकाङ्क्षायां तदङ्गान्यासनादीन्याह शुचौ देशे इत्यादिना। शुचौ स्वभावतः संस्कारतो वा पुण्ये देशे स्थाने प्रतिष्ठाप्य सुस्थितं कृत्वा स्थिरं निश्चलं आस्तेऽस्मिन्नित्यासनं स्थण्डिलं निश्चलमित्यनेन मृन्मयमेव स्थण्डिलं नतु काष्ठमयं पीठम्। आत्मन इति परासनव्यावृत्त्यर्थम्। नात्युच्छ्रितं नात्युच्चं नातिनीचम्। चैलाजिनकुशाः उत्तरे उपर्युपरि यस्य तच्चैलाजिनकुशोत्तरम्। अजिनादुपरि चैलं कुशेभ्य उपरि अजिनं स्थण्डिलस्योपरि कुशा इत्यर्थः।'),
('nilakantha-sc:source:6.12','Nīlakaṇṭha','gita.6.12','sa','commentary','।।6.12।।प्रतिष्ठाप्य किं कुर्यादिति तत्राह तत्रेति। तत्रासने पद्मस्वस्तिकाद्यन्यतमेनासनेनोपविश्य यता निगृहीताः चित्तस्य क्रियाः विषयाणां स्मरणानि इन्द्रियक्रियास्तेषां ग्रहणं येनासौ यतचित्तेन्द्रियक्रियः। अतएव मनः बाह्याभ्यन्तरविषयानुपरक्ततया एकं ध्येयमेव प्रत्यक्तत्वं अग्रे यस्य स्फुरति नान्यत् तदेकाग्रं वृत्त्यन्तरानन्तरितब्रह्मैकाकारवृत्तिप्रवाहि कृत्वा आत्मविशुद्धये चित्तशुद्ध्यर्थं योगं वृत्तिप्रवाहस्यापि निरोधं युञ्ज्यादनुतिष्ठेत्। चित्तस्य स्थैर्यतापादनेन।'),
('nilakantha-sc:source:6.13','Nīlakaṇṭha','gita.6.13','sa','commentary','।।6.13।।आसन उपविश्येत्युक्तं तत्कथमित्यत आह सममिति। कायः शरीरमध्यं शिरः ग्रीवा च कायशिरोग्रीवं समं मूलाधारमारभ्य मूर्धान्तं अवक्रमचलं निष्कम्पं धारयन्स्थिरो भूत्वा। संप्रेक्ष्य नासिकाग्रं स्वमिति नासिकाग्रावेक्षणं न विधीयते किंतु निमीलने लयभयं उन्मीलने विक्षेपभयम्। अतो दिशोऽपि स्त्र्यादिविक्षेपकविषयदर्शनभयादनवलोकयन्नर्धोन्मीलितनेत्र आसीतेत्युत्तरेणान्वयः।'),
('nilakantha-sc:source:6.14','Nīlakaṇṭha','gita.6.14','sa','commentary','।।6.14।।एवमासने उपविष्टेन यत्कर्तव्यं तदाह प्रशान्तात्मेति। योगयुक्तो योगी ब्रह्मचारिव्रते भैक्षचर्यायां स्थितः संन्यासीत्यर्थः। मच्चितो मयि परमे चित्तं यस्य स एवंभूतो मय्येव मनः संयम्य मत्पर आसीत स प्रशान्तात्मा भूत्वा विगतभीर्भवतीति योजना। भवति हि कश्चिदात्मनोऽन्यमीश्वरं मत्वा तच्चित्तस्तमेवाराध्यत्वेनाभिगतः तत्रैव च मनसः संयमं करोति न तु स तत्परस्तमेव परमपुरुषार्थतया प्राप्यत्वेन मन्यते किंतु तत्प्रीत्यान्यदेव फलं कामयते अयं तु मच्चित्तो मय्येव मनः संयम्य मत्परो मामेव सर्वान्तरं प्रत्यगद्वयं कामयत इति। यतो मत्परोऽतएव प्रशान्तात्मा प्रकर्षेण बाह्याभ्यन्तरविषयत्यागेन समाधिसुखास्वादत्यागेन च शान्त उपरतः आत्मा चित्तं यस्य सोऽस्मितामात्रावशेषो विगतभीर्भवति। इयमेवावस्था सत्त्वपुरुषान्यथाख्यातिरिति ब्रह्मसाक्षात्कार इति च विकल्प्यते। सर्वथा तस्यां सिद्धायां पुरुषः परमपुरुषार्थभाग्भवति।'),
('nilakantha-sc:source:6.15','Nīlakaṇṭha','gita.6.15','sa','commentary','।।6.15।।अस्याः फलमाह युञ्जन्निति। एवमनेन प्रकारेण सदा निरन्तरं दीर्घकालं च आत्मानं मनो युञ्जन्समादधानो योगी नियतं ख्यातिफलादपि निगृहीतं मानसं येन स नियतमानसः शान्तिं परमवैराग्यबलात्ख्यातिमपि निरुध्य निर्विकल्पं पदं निर्वाणं मोक्षस्तदेव परमा निष्ठा यस्याः शान्तेस्तां मत्संस्थां मय्येव संस्था एकीभावेनावस्थानं समाप्तिर्वा यस्यास्तामधिगच्छति प्राप्नोति। ख्यातिफलं च सूत्रकृता दर्शितंप्रसंख्यानेऽप्यकुसीदस्य सर्वथा विवेकख्यातेर्धर्ममेघः समाधिः इतितत्परं पुरुषख्यातेर्गुणवैतृष्ण्यम् इतिसत्त्वपुरुषान्यताख्यातिमात्रात्सर्वज्ञातृत्वं सर्वभावाधिष्ठातृत्वं च इति सूत्रत्रयेण। प्रसंख्याने ध्याने। अकुसीदस्य वणिज इव फलानिच्छोः सर्वथा विवेकख्यातिरेव भवति तस्याश्च फलं धर्ममेघः समाधिः स च प्रागेव व्याख्यातः। तत् वैराग्यं परं परसंज्ञं पुरुषख्यातेः फलं। तस्य लक्षणं गुणेषु दिव्यादिव्यविषयेषु वैतृष्ण्यम्। एतस्यैव हि नान्तरीयकं फलं कैवल्यमिति योगा वदन्ति। तृतीयसूत्रोक्तं फलं सार्वज्ञ्यादिकं तु अभिप्रेत्य श्रूयतेकस्मिन्नु भगवो विज्ञाते सर्वमिदं विज्ञातं भवतीति सर्वस्य वशी सर्वस्येशानः सर्वस्याधिपतिः इत्यादिकम्।'),
('nilakantha-sc:source:6.16','Nīlakaṇṭha','gita.6.16','sa','commentary','।।6.16।।एवं योगाभ्यासनिष्ठस्याहारादिनियममाह द्वाभ्याम् नात्यश्नत इति। एकान्तमतिशयेन। अतिजाग्रत इत्यत्राप्यतिशब्दो योज्यः।'),
('nilakantha-sc:source:6.17','Nīlakaṇṭha','gita.6.17','sa','commentary','।।6.17।।युक्ताः परिमिता आहारादयो यस्य स तथा।'),
('nilakantha-sc:source:6.18','Nīlakaṇṭha','gita.6.18','sa','commentary','।।6.18।।निर्वाणपरमां शान्तिं प्राप्तस्य लक्षणान्याह यदेत्यादिभिः षड्भिः। विनियतं विशेषेण एकाग्रताभूमेरपि निरुद्धमात्मनि प्रत्यगात्मन्येवावतिष्ठते नत्वस्मितादिरूपेणोद्रिच्यते तदा योगी सर्वेभ्यो जाग्रत्स्वप्नसबीजसमाधिषूपस्थितेभ्यः। ल्यब्लोपे पञ्चमी। सार्वात्म्यप्राप्त्यैव तान् प्राप्य तेषु निःस्पृहो भवति तदा युक्तो निर्विकल्पक इत्युच्यते।'),
('nilakantha-sc:source:6.19','Nīlakaṇṭha','gita.6.19','sa','commentary','।।6.19।।एकाग्रतावस्थायांयोगिचित्तस्योपमामाह यथेति। नेङ्गते न चलति तद्वत्। यतं च तच्चित्तं च यतचित्तं तस्य। एकाग्रतां प्राप्तं चित्तं निवातप्रदीपवन्न चलतीत्यर्थः। आत्मनो योगं समाधिं युञ्जतोऽनुतिष्ठतः।'),
('nilakantha-sc:source:6.20','Nīlakaṇṭha','gita.6.20','sa','commentary','।।6.20।।यत्रेति। एवं चित्तमेकाग्रीभूतं सत् योगसेवया निरुद्धं यत्र यस्यामवस्थायामुपरमते विलीनं भवति यत्र वा आत्मना चित्तेनात्मानं निर्विकल्पं पश्यन्नात्मनि तुष्यति न बाह्यार्थे तुष्टिं भजते।'),
('nilakantha-sc:source:6.21','Nīlakaṇṭha','gita.6.21','sa','commentary','।।6.21।।किं च सुखमिति। आत्यन्तिकमनन्तं यत्सुखं तत्केवलं बुद्धिग्राह्यं सौषुप्तसुखवद्यतोऽतीन्द्रियमिन्द्रियागोचरं यत्र सुखे स्थितोऽयं न वेत्ति वेद्याभावान्न किंचिदनुभवति नापि तत्त्वतश्चलति। बुद्धितादातम्याध्यासकाले चलतीवेति भाति परंतु तत्त्वतो न चलति। तथा च श्रुतिःध्यायतीव लेलायतीव इतीवशब्दं प्रयुञ्जाना ध्यानादेरतात्त्विकत्वं दर्शयति। बुद्धौ ध्यायन्त्यां ध्यायतीवेति लेलायन्त्यां लेलायतीवेति श्रुत्यर्थः। यद्वा तत्सुखं यत्रायं न चैव वेत्ति किमपि नैवानुभवति। यत्रेत्यादि भिन्नं वाक्यम्।'),
('nilakantha-sc:source:6.22','Nīlakaṇṭha','gita.6.22','sa','commentary','।।6.22।।दुःखेन शस्त्रपातादिलक्षणेन। गुरुणा महता।'),
('nilakantha-sc:source:6.23','Nīlakaṇṭha','gita.6.23','sa','commentary','।।6.23।।तमिति। यत्रोपरमते चित्तमित्यादिनोक्तलक्षणं तं दुःखसंयोगस्याप्यन्तःकरणसंबन्धस्य वियोगमेव सन्तं विरुद्धलक्षणया योगसंज्ञितं विद्यात्। योगफलमुपसंहृत्य पुनर्निश्चयानिर्वेदयोः साधनत्वविधानपूर्वकं तमेव शतकृत्वोऽपि पथ्यं वदितव्यमिति न्यायेन विधत्ते स इत्यादिना। स योगो निश्चयेनाध्यवसायेनानिर्विण्णं निर्वेदरहितं चेतो यस्य तेन योक्तव्योऽभ्यसनीयः। यद्वाशान्तो दान्त उपरतस्तितिक्षुः समाहितो भूत्वात्मन्येवात्मानं पश्येत् इति श्रुतिविहितं श्रुत्यन्तरदृष्टं श्रद्धावित्तपदोपेतं शमादिषट्कमत्र क्रमतो विधीयते। तत्र निश्चयेनेति गुरुवेदवाक्यादौ फलावश्यंभावनिश्चयलक्षणा श्रद्धात्र निश्चयपदेन गृह्यते। तथा निर्विण्णचेतसेति वैराग्येण द्वन्द्वसहिष्णुत्वलक्षणा तितिक्षा विधीयते इति ज्ञेयम्।'),
('nilakantha-sc:source:6.24','Nīlakaṇṭha','gita.6.24','sa','commentary','।।6.24।।अथ शमदमोपरमसमाधानानि क्रमेण श्लोकद्वयेन विधत्ते संकल्पेति। संकल्प इदं मे भूयादिति चेतोवृत्तिस्तत उद्भवो येषां तान्कामान्काम्यमानान्विषयानशेषतो वासनोच्छेदपूर्वकं संकल्पनिरोधेन त्यक्त्वा। एतेनान्तरिन्द्रियनिग्रहलक्षणः शम उक्तः। बाह्येन्द्रियनिग्रहलक्षणं दममाह मनसैवेति। विषयदोषदर्शिना मनसैव सर्वतः सर्वप्रकारेण श्रोत्रादिकमिन्द्रियग्रामं समन्ततः सर्वेभ्यो विषयेभ्यो विनियम्योपरमेदित्युत्तरेणान्वयः।'),
('nilakantha-sc:source:6.25','Nīlakaṇṭha','gita.6.25','sa','commentary','।।6.25।।शनैः शनैरिति। भूमिकाजयक्रमेण दिव्यादिव्यविषयेभ्य उपरमेद्वव्यावृत्तो भवेत्। कथम्। धृतिगृहीतया बुद्ध्येति। धृतिःधृत्या यया धारयते मनःप्राणेन्द्रियक्रियाः। योगेनाव्यभिचारिण्या धृतिः सा पार्थ सात्विकी इत्युक्तलक्षणा तया गृहीतया वशीकृतया बुद्ध्योपरमेत्। तथा एवमुपरतं मनः आत्मनि स्वरूपे संस्था स्थितिर्यस्य न तु दृश्ये द्रष्टरि वा तत्तथा आत्मैकाकारमेकाग्रमित्यर्थः। द्रष्टृदृश्योपरक्तं चित्तं सर्वार्थंसर्वार्थतैकार्थतयोः क्षयोदयौ चित्तस्यैकाग्रतापरिणामः इति सूत्रितमैकाग्र्यं प्रापयेत्। सूत्रार्थस्तु अहमिदं पश्यामीत्यनुभवे हि द्रष्टा दृश्यं दर्शनं च भासते। तत्र दर्शनभानमप्रत्याख्येयमतो द्रष्टरि दृश्ये चोपरक्तं चित्तं सवार्थमिति। न तु दर्शनोपरक्ततापि सर्वार्थतायां गणिता। तदभावे चित्तस्य नाशापत्तेः। द्रष्टृदृश्योपरागाभावे तु एकार्थं तदुच्यते यथा स्वप्ने। तत्र हि दृश्यं नास्तीति पामराणामपि प्रसिद्धम्। द्रष्टापि नास्ति। तदा इन्द्रियाणामभावात्।आत्मेन्द्रियमनोयुक्तं भोक्ता इतिश्रुत्यैव भोक्तृत्वस्येन्द्रियसंनियोगशिष्टत्वात्। किंतु द्रष्टृदृश्यवासनावासितं चित्रपटसदृशमेकं मन एवास्ति। तच्च स्वयंज्योतिषा पुरुषेण भास्यमानं जाग्रद्वत्स्वप्नेऽपि द्रष्टृदृश्योपरागं प्रकाशयति। तद्वासनावासितत्वात्। एवं सति यदा सर्वार्थतायाः क्षय एकार्थताया उदयश्च तदा चित्तस्यैकाग्रतारूपः परिणामो भवतीति। तदेवमात्मसंस्थं मनः कृत्वेति संप्रज्ञातसमाधिरुक्तः। तत्रापि पूर्वाभ्यासवशाच्चित्तस्य द्रष्टृदृश्योपरागो वासनामयो भातीति तन्निवारणेनासंप्रज्ञातसमाधिमाह न किंचिदपि चिन्तयेदिति। ध्यातृध्यानध्येयविभागमपि न स्मरेत्किंतु अखण्डैकरससंविदात्मना सुषुप्तवत्तिष्ठेदित्यर्थः।'),
('nilakantha-sc:source:6.26','Nīlakaṇṭha','gita.6.26','sa','commentary','।।6.26।।शनैः शनैरित्येतं श्लोकं व्याचष्टे यतो यत इति त्रिभिः। यतो यतो हेतोर्यं यं विषयं ग्रहीतुं मनो निश्चरति बहिर्गच्छति ततस्ततस्तत्रतत्र दोषदर्शनेन ततस्ततो विषयादेतन्मनो नियम्य प्रत्याहृत्य आत्मनि स्वरूपे एव वशं नयेत्पर्यवस्थापयेत्। एतेन पूर्वार्धं व्याख्यातम्।');
INSERT INTO commentary_fts (unit_id,author,canonical_ref,language,content_type,content) VALUES
('nilakantha-sc:source:6.27','Nīlakaṇṭha','gita.6.27','sa','commentary','।।6.27।।एवमात्मवशे मनसि किं स्यादित्याशङ्क्याह प्रशान्तेति। हि यस्मादेनं प्रशान्तमनसं प्रकर्षेणोपरतचेतसं योगिनमेकाग्रताभूमावुत्तमं सुखं संप्रज्ञातसमाधिफलभूतमुपैति। भौतिकानां बाह्यानां मानोरथिकानामान्तराणां च विषयाणां त्यागात् शान्तरजसं प्रक्षीणमोहादिक्लेशं ब्रह्मभूतं सद्वस्तुरूपं अकल्मषं धर्माधर्मवर्जितम्। यथोक्तं योगभाष्येयस्त्वेकाग्रे चेतसि सद्भूतमर्थं प्रद्योतयति कर्मबन्धनानि श्लथयति निरोधमभिमुखीकरोति क्षिणोति च क्लेशान् स संप्रज्ञातो योग इत्याख्यायते इति। एतेनात्मसंस्थं मनः कृत्वेति व्याख्यातम्।'),
('nilakantha-sc:source:6.28','Nīlakaṇṭha','gita.6.28','sa','commentary','।।6.28।।अस्य फलमाह युञ्जन्निति। एवमनेन प्रकारेण योगी आत्मानं मनो युंजन्समादधानः विगतकल्मषो निरस्ताविद्यादिक्लेशः सुखेनानायासेन ब्रह्मसंस्पर्शं निर्विशेषं ब्रह्मणैक्यं त्रिविधोपाधिप्रविलयादश्नुते प्राप्नोति। कीदृशं ब्रह्मसंस्पर्शम्। अत्यन्तं अन्तो द्रष्टृदृश्यभावेन परिच्छेदस्तमतिक्रान्तं निर्विशेषं सुखं परमानन्दैकरूपम्। एतेन न किंचिदपि चिन्तयेदिति चतुर्थपादो व्याख्यातः।'),
('nilakantha-sc:source:6.29','Nīlakaṇṭha','gita.6.29','sa','commentary','।।6.29।।द्विविधस्यापि योगस्य फलमाह सर्वेति।सोपाधिर्निरुपाधिश्च द्वेधा ब्रह्मविदुच्यते। सोपाधिकः स्यात्सर्वात्मा निरुपाख्योऽनुपाधिकः। इति वार्तिकोक्तरीत्या संप्रज्ञाते आत्मनः सार्वात्म्यमनुभवन्योगी सर्वेषु भूतेषूपादानतया स्थितमात्मानमीक्षते पश्यति। तथा असंप्रज्ञाते सर्वाणि भूतानि ब्रह्मादिस्तम्बपर्यन्तान्यात्मन्येकतां गतानि रज्ज्वामिवाध्यस्तसर्पदण्डधारादीनि तद्वत्पश्यति। योगयुक्तात्मा योगेन समाहितचित्तः। अस्यैव व्युत्थानावस्थामाह सर्वत्रेति। सर्वेषु ब्रह्मादिस्थावरान्तेषु विषमेषु भूतेषु समं निर्विशेषं ब्रह्मात्मैकत्वविषयं दर्शनं यस्य स सर्वत्र समदर्शनः। तथा च श्रुतयःयस्तु सर्वाणि भूतान्यात्मन्येवानुपश्यति। सर्वभूतेषु चात्मानं ततो न विजुगुप्सते।सर्वस्यात्मा भवति।ब्रह्म दाशा ब्रह्म दासा ब्रह्मेमे कितवा उत।इदं सर्वं यदयमात्मा इत्यादय एतमर्थं प्रतिपादयन्ति। यत्तु यो योगयुक्तात्मा यो वा सर्वत्र समदर्शनः स आत्मानमीक्षत इति योगिसमदर्शिनावात्मेक्षणाधिकारिणावुक्तौ। यथाहि चित्तवृत्तिनिरोधः साक्षिसाक्षात्कारहेतुस्तथा जडविवेकेन सर्वानुस्यूतचैतन्यपृथक्करणमपि नावश्यं योग एवापेक्षित इति। तन्न।समाहितो भूत्वात्मन्येवात्मानं पश्यतिततस्तु तं पश्यति निष्कलं ध्यायमानः इत्यादिश्रुतिभिः समाधिध्यानापरपर्याययोगस्यैवात्मदर्शनहेतुत्वप्रतिपादनात्।तत्कारणं सांख्ययोगाभिपन्नं विद्यामेतां योगविधिं च कृत्स्नम् इति लिङ्गाच्च ज्ञानयोगयोः समुच्चयावगमात्। न च श्रौतं यौक्तिकविवेकमात्राज्जडाजडयोर्देहात्मनोः पृथक्करणं संभवति। सोपाधिकस्य भ्रमस्योपाधिनिवृत्तिमन्तरेण निवृत्त्यसंभवात्। आदर्शाद्यनिवृत्तावपि प्रतिबिम्बादिभ्रमनिवृत्त्यापतेः। अतएवाधिष्ठानज्ञानदार्ढ्ये सति तत्र कल्पितस्य चित्तस्य तद्दृश्यस्य चादर्शनमनायासेनैवोपपद्यत इति निरस्तम्। योगं विनाधिष्ठानज्ञानस्यैवासंभवात्। यदाह दक्षःस्वसंवेद्यं हि तद्ब्रह्मकुमारी स्त्रीसुखं यथा। अयोगी नैव जानाति जात्यन्धो हि यथा घटम्। इति। यत्तूक्तं भगवत्पूज्यपादैःब्रह्मविदः कुत्रापि योगापेक्षां न व्युत्पादयांबभूवुः इति तत्अथातो ब्रह्मजिज्ञासा इत्यत्राथशब्दसूचितमुमुक्षुविशेषणीभूतसाधनचतुष्टयान्तर्गतं शमाद्युपेयसमाधिमदृष्ट्वोक्तमिति न दोषः। द्वौ क्रमाविति वसिष्ठवाक्यतात्पर्यं तु परस्परनिरपेक्षमार्गद्वयोपगमेनान्यः पन्था इति श्रुतिबाधापत्त्याप्रतिपत्तिक्रमभेदमात्रपरतया प्रागेव वर्णितमिति दिक्। किं च योगप्रकारेण योगानपेक्षमार्गान्तरप्रतिपादनमसंगतम्। न च तत्सूचकोऽत्र कश्चिच्छब्दो वर्तते। संभवति वा उक्तयुक्तेरतो यो वा समदर्शन इति वापदाध्याहारोऽप्यसंगत इति दिक्।'),
('nilakantha-sc:source:6.30','Nīlakaṇṭha','gita.6.30','sa','commentary','।।6.30।।अस्यात्मैकत्वदर्शनस्यापि फलमाह यो मामिति। सर्वत्रास्मच्छब्दः प्रत्यगात्मपरः। यो योगी आत्मानं सर्वत्र पश्यति सर्वं चात्मनि पश्यति तस्य योगिनो ज्ञात आत्मा न प्रणश्यति अदर्शनं न गच्छति। ज्ञात आत्मा न पुनस्तिरोभवति। सकृन्नष्टस्य मूलाज्ञानस्य बीजाभावेन पुनरुदयासंभवादित्यर्थः। ननु कार्यकारणसंघाताभिमानिना शुक्तिरूप्यवद्ब्रह्मण्यध्यस्तेन तदभिमानत्यागपूर्वकं ज्ञातं स्वाधिष्ठानभूतं ब्रह्म मा तिरोधायि बुद्धेस्तत्त्वपक्षपातित्वात् ब्रह्मदृष्ट्या तु मुक्तजीवस्य निरन्वयोच्छेदो भवतीत्याशङ्क्याह स च मे न प्रणश्यतीति। स च विद्वान्मे मम न प्रणश्यति न तिरोभवति मदभिन्नत्वात्। भवेदेतदेवं यदि जीवो मय्यध्यस्तो वा मम विकारो वा भवेत्तदा निरन्वयोच्छेदं प्राप्नुयात्। अहमेव तु सः।तत्त्वमसिअहं ब्रह्मास्मिअयमात्मा ब्रह्म इत्यादिशास्त्रात्। तस्माद्युक्तमुक्तं स च मे न प्रणश्यतीति।'),
('nilakantha-sc:source:6.31','Nīlakaṇṭha','gita.6.31','sa','commentary','।।6.31।।यस्मात्सर्वात्मैकत्वदर्शी अहमेव अतो नास्य मोक्षः प्रतिबध्यत इत्याह सर्वभूतेति। सर्वोपादानतया सर्वेषु भूतेषु सत्तारूपेण स्फुरणरूपेण च स्थितं मां परमात्मानं एकत्वं जीवब्रह्मणोरैक्यमास्थितः सन् भजति निर्विकल्पेन समाधिना सेवते स योगी व्युत्थानदशायां प्रारब्धकर्मवशाद्बाधितानुवृत्त्या देहमारूढः सर्वथा सर्वप्रकारेण याज्ञवल्क्यादिवत्कर्मत्यागेन वा वसिष्ठजनकादिवद्विहितकर्मणा वा दत्तात्रेयादिवन्निषिद्धकर्मणा वा वर्तमानोऽपि व्यवहरन्नपि मय्येव वर्तते न मत्तश्च्युतो भवति। यतो देवेभ्योऽपि नास्य भयमिति श्रूयतेतस्य ह न देवाश्च नाभूत्या ईशत आत्मा ह्येषां स भवति इति च। नेत्यव्ययमप्यर्थे। देवा अपि तस्य ब्रह्मविदः अभूत्यै अनैश्चर्याय न ईशते न समर्था भवन्ति। यतोऽयमेषामात्मा इति श्रुत्यर्थः। स न पुनः संसारी पूर्ववद्भवतीत्यर्थः।'),
('nilakantha-sc:source:6.32','Nīlakaṇṭha','gita.6.32','sa','commentary','।।6.32।।यद्यपि निषिद्धकर्मणाप्यात्मविन्न बध्यते तथापि शीलवानेव योगी श्रेष्ठ इत्याह आत्मौपम्येनेति। यथा स्वस्य सुखमिष्टं दुःखमनिष्टं तद्वत्परस्यापीति बुद्ध्या योऽन्यस्मै दुःखं न प्रयच्छति सोऽहिंसकः परमयोगी मत इत्यर्थः।'),
('nilakantha-sc:source:6.33','Nīlakaṇṭha','gita.6.33','sa','commentary','।।6.33।।साम्ययोगमशक्यं मन्वान उपायान्तरबुभुत्सयार्जुन उवाच योऽयमिति। योयं योगस्त्वया साम्येन प्रोक्तोऽहिंसाप्राधान्येन संन्यासपूर्वकतया वर्णितः हे मधुसूदन तस्य योगस्य सर्ववृत्तिनिरोधरूपस्य स्थिरां स्थितिं न पश्यामि। मनसश्चञ्चलत्वादिति शेषः।'),
('nilakantha-sc:source:6.34','Nīlakaṇṭha','gita.6.34','sa','commentary','।।6.34।।एतदेवोपपादयति चञ्चलं हीति। प्रमाथि बहुदस्युवदेकस्य प्रमथनशीलम्।'),
('nilakantha-sc:source:6.35','Nīlakaṇṭha','gita.6.35','sa','commentary','।।6.35।।मनसो दुर्ग्रहत्वमभ्युपेत्य भगवानुवाच। यद्यप्येवं तथाप्यभ्यासवैराग्याभ्यां समुच्चिताभ्यां दुर्निग्रहमपि मनो निगृह्यते। तत्राभ्यासो नाम कस्यांचिच्चित्तभूमौ समानप्रत्ययावृत्तिः। वैराग्यं तु दृष्टादृष्टेष्टभोगेषु ससाधनेषु दोषदर्शनेन वैतृष्ण्यम्। तत्र यथा कैदारिकः केदारेषु कुल्याजलं संचारयन्नेकस्य द्वारं पिधायारपरस्योद्धाटयति तद्वद्वैराग्येण विषयस्रोतः खिलीक्रियते अभ्यासेन कल्याणस्रोत उद्घाट्यत इति द्वयोरप्यावश्यकत्वम्। तथा च सूत्रम् अभ्यासवैराग्याभ्यां तन्निरोधः इति।'),
('nilakantha-sc:source:6.36','Nīlakaṇṭha','gita.6.36','sa','commentary','।।6.36।।असंयतात्मनाऽजितचित्तेन। वश्यात्मना जितचित्तेन। उपायतोऽभ्यासवैराग्यरूपात्।'),
('nilakantha-sc:source:6.37','Nīlakaṇṭha','gita.6.37','sa','commentary','।।6.37।।मनसो दुर्निग्रहत्वाद्योगसिद्धौ विघ्नं पश्यन्नर्जुन उवाच हे कृष्ण योगात्कर्मयोगाच्चलितमानसस्त्यक्तकर्मा संन्यासीत्यर्थः। श्रद्धया उपेतो योगमार्गं प्रविष्टोऽपि अयतिः आयुषोल्पत्वाद्वा वैराग्यदौर्बल्याद्वाल्पप्रयत्नः। अलवणा यवागूरितिवदत्राल्पार्थे नञ्। स कदाचित् योगसंसिद्धिं योगफलं सम्यग्दर्शनमप्राप्य मृतश्चेत् कां गतिं गच्छति।'),
('nilakantha-sc:source:6.38','Nīlakaṇṭha','gita.6.38','sa','commentary','।।6.38।।कच्चिदिति। कच्चिन्नोभयविभ्रष्टः कर्ममार्गाद्योगमार्गाच्च विभ्रष्टः छिन्नाभ्रमिव पूर्वमपरं वा मेघसंघमप्राप्य मध्ये एव नश्यति तद्वत्। अप्रतिष्ठो निराश्रयः। हे महाबाहो विमूढो ब्रह्मणः पथि ब्रह्मप्राप्तिमार्गे।'),
('nilakantha-sc:source:6.39','Nīlakaṇṭha','gita.6.39','sa','commentary','।।6.39।।एतत् एतम्। स्पष्टमन्यत्।'),
('nilakantha-sc:source:6.40','Nīlakaṇṭha','gita.6.40','sa','commentary','।।6.40।।अत्रोत्तरं भगवानुवाच पार्थेति। हे तातेति वात्सल्यात्संबोधयति। तस्येह विनाशो नीचयोनिप्राप्तिः अमुत्रविनाशो नरकप्राप्तिस्तदुभयमपि न जायते। हि यतः कल्याणकृच्छुभकृत् दुर्गतिं नैव प्राप्नोति।'),
('nilakantha-sc:source:6.41','Nīlakaṇṭha','gita.6.41','sa','commentary','।।6.41।।इहामुत्र च तस्य महत्त्वमेवास्तीत्याह प्राप्येति। उषित्वा वासं कृत्वा। शाश्वतीः समाः नित्यान्वत्सरान्योगभ्रष्टो रागी चेदल्पकालाभ्यस्तयोगश्चेत् श्रीमतां गेहे जायते। तत्रापि श्रीमानधो गच्छतीत्याशङ्क्य शुचीनामित्युक्तम्। शुचयो हि सत्कार्येष्वेव श्रियमुपयुञ्जानाः पूर्वापेक्षया महत्तरं स्थानमासादयन्तीत्यर्थः।'),
('nilakantha-sc:source:6.42','Nīlakaṇṭha','gita.6.42','sa','commentary','।।6.42।।स योगी विरक्तश्चिराभ्यस्तयोगो वा चेत्तस्य गतिमाह अथवेति।'),
('nilakantha-sc:source:6.43','Nīlakaṇṭha','gita.6.43','sa','commentary','।।6.43।।तत्र द्विविधेऽपि जन्मनि पौर्वदेहिकं पूर्वदेहप्राप्तं बुद्धिसंयोगम्। यावती च योगभूमिः पूर्वजन्मनि जिता तत्र च यावान्बुद्धिलाभो जातस्तावन्तं बुद्धिसंयोगं पूर्वाभ्यासादल्पेनैवाभ्यासेन लभते। तस्मादपि भूयस्यां बह्व्यां संसिद्धौ ऊर्ध्वभूमिलाभार्थमित्यर्थः। यतते यत्नं करोति।'),
('nilakantha-sc:source:6.44','Nīlakaṇṭha','gita.6.44','sa','commentary','।।6.44।।कुतो यतते शिक्षितोऽपीत्यत आह पूर्वेति। अवशोऽपि प्रह्नादादिवत्पित्रादिभिरन्यथा नीयमानोऽपि तेनैव पूर्वाभ्यासेन बलवता ह्रियते योगप्रवणः क्रियते। यतो योगस्य जिज्ञासुर्ज्ञानमात्रमिच्छन्यो भवति सोऽपि शब्दब्रह्म कर्मकाण्डं वेदमप्यतिक्रम्य वर्तते किं पुनः पित्राद्याज्ञाम्। इत्थं पूर्वाभ्यासबलं यन्महान्तमपि पित्रादियत्नं वृथा करोतीत्यर्थः।'),
('nilakantha-sc:source:6.45','Nīlakaṇṭha','gita.6.45','sa','commentary','।।6.45।।एवं योगभ्रष्टगतिमुक्त्वा यो विषयैर्ह्रियमाणोऽपि प्रयत्नेन योगमेवाभ्यसितुं प्रवर्तते तस्य गतिमाह प्रयत्नादिति। प्रयत्नात्प्रकृष्टाद्धठाद्वायुनिरोधाद्विरूपात्खेचर्यादिमुद्राविशेषाभ्यासाद्यो यतमानः संशुद्धकिल्बिषो निष्पापो भवति। यदाह मनुःप्राणायामैर्दहेदेनः इति। हठयोगानां सर्वेषां पापनिवृत्त्युपयोगित्वं न तत्त्वसाक्षात्कारे साक्षात्साधनत्वमित्यर्थः। अतएव सः अनेकैर्जन्मनि संसिद्धः प्राप्तयोगो भूत्वा ततः परां गतिं मोक्षं याति। एतेनचक्षुश्चैवान्तरे भ्रुवोः इति पञ्चमान्ते यत्सूत्रितं तद्व्याख्यातम्।'),
('nilakantha-sc:source:6.46','Nīlakaṇṭha','gita.6.46','sa','commentary','।।6.46।।एवं योगिनं स्तौति तपस्विभ्य इति। तपस्विनोऽत्र कृच्छ्रचान्द्रायणमासोपवासादिकर्तारः। ज्ञानिनश्च शास्त्रीयपाण्डित्यवन्तः। कर्मिणोऽग्निहोत्राद्यनुष्ठातारः। तेभ्यः सर्वेभ्यो योगी यतोऽधिको मतस्तस्माद्योगी भवार्जुन।'),
('nilakantha-sc:source:6.47','Nīlakaṇṭha','gita.6.47','sa','commentary','।।6.47।।समाप्तः कर्मप्रधानस्त्वंपदार्थविवेकः। अतःपरमुपासनाप्राधान्येन तत्पदार्थं निरूपयितुकामस्तदुपासनां महाफलत्वेन स्तौति योगिनामिति। दैवमेवापरे यज्ञमित्यादिना चतुर्थाध्यायप्रोक्ता द्वादशयोगास्तद्वतां योगिनां सर्वेषां मध्ये यो मद्गतेन मयि वासुदेवे समर्पितेनान्तरात्मना चित्तेन श्रद्धावान्सन् मां भजते स मे मम युक्ततमोऽतिशयेन युक्तः श्लाघ्यो मतोऽभिप्रेतः। तस्मान्मद्भक्तो भवेति भावः।'),
('nilakantha-sc:source:7.1','Nīlakaṇṭha','gita.7.1','sa','commentary','।।7.1।।पूर्वाध्यायान्ते यो मां भजते स मे युक्ततमो मत इत्युक्तम् तत्र कीदृशं पूर्वोक्तनिष्कामकर्मयोगापेक्षया विलक्षणं तव भजनं केन वा गुणेन पूर्वयोगापेक्षया तस्य युक्ततमत्वमित्येतामर्जुनस्याशङ्कां स्वयमेव परिहरन् भगवानुवाच मयीति। कश्चिद्राजाश्रयो धनमानासक्तमना भवति। अयं तु मदाश्रयेण मामेव परमपुरुषार्थभूतं प्राप्तुमिच्छन्नित्यर्थः। ईदृशो योगं युञ्जन्समाधिमनुतिष्ठन् त्वंपदार्थविवेककाले यद्यपि सार्वज्ञ्यमस्तिसर्वभूतस्थमात्मानम् इत्यादिवचनात्तथापि स्वस्मादन्य ईश्वरोऽस्ति नवेति पातञ्जलकापिलयोस्तार्किकमीमांसकयोर्वा सेश्वरानीश्वरयोर्मतभेदात्संशयः कारणाज्ञानाच्चासमग्रं तत्सार्वज्ञ्यमिति मत्वा आह असंशयं समग्रमिति। मां तत्पदार्थमीश्वरं यथा ज्ञास्यसि तत् तं प्रकारं शृणु। अत्र वक्ष्यमाणरीत्या सर्वं ब्रह्म वासुदेवात्मकमिति भजने वैलक्षण्यं कारणज्ञातृत्वमस्य योगिनः पूर्वयोग्यपेक्षयाधिक्यमिति भावः।'),
('nilakantha-sc:source:7.2','Nīlakaṇṭha','gita.7.2','sa','commentary','।।7.2।।एतदेवाह ज्ञानमिति। ज्ञानं शुद्धप्रज्ञानघनं ब्रह्मसत्यं ज्ञानमनन्तं ब्रह्मविज्ञानमानन्दं ब्रह्म इति श्रुतेः। ते तुभ्यमहं वक्ष्यामि। अशेषतः साधनकलापसहितम्। किं वचनमात्रजेन परोक्षज्ञानेन शब्दस्य स्वविषये परोक्षज्ञानजनकत्वनियमादित्याशङ्क्याह सविज्ञानमनुभवसहितम्। दशमस्त्वमसीत्यादौ शब्दादप्यपरोक्षज्ञानोत्पत्तिदर्शनात्कस्मिन्नु भगवो विज्ञाते सर्वमिदं विज्ञातम् इत्येकविज्ञानात्सर्वविज्ञानप्रतिज्ञां श्रौतीमेव वर्णयति यज्ज्ञात्वेति। जगत्कारणाधिष्ठानस्य ज्ञानरूपस्य ब्रह्मणो ज्ञाने संशयोच्छेदात्सर्वस्यात्ममात्रत्वेन ज्ञातव्यानवशेषो युक्त इत्यर्थः।'),
('nilakantha-sc:source:7.3','Nīlakaṇṭha','gita.7.3','sa','commentary','।।7.3।।एतदेव ज्ञानं दौर्लभ्यप्रदर्शनेन स्तौति मनुष्याणामिति। यततां यतमानानाम्।'),
('nilakantha-sc:source:7.4','Nīlakaṇṭha','gita.7.4','sa','commentary','।।7.4।।एवमेकविज्ञानात्सर्वविज्ञानं प्रतिज्ञाय तदुपपत्तये सर्वस्य जडाजडप्रपञ्चस्य ज्ञानात्मकब्रह्मप्रभवत्वमाह त्रिभिः भूमिरिति। अत्र भूम्यादिपदैस्तत्तत्कारणान्येव गृह्यन्ते प्रकृतिरित्यधिकारात् स्थूलभूम्यादेश्च विकृतिमात्रत्वात्। तथा च भूमिरिति गन्धतन्मात्रं आप इति रसतन्मात्रं अनल इति रूपतन्मात्रं वायुरिति स्पर्शतन्मात्रं खमिति शब्दतन्मात्रं मन इति तत्कारणमहंकारः बुद्धिरिति समष्टिबुद्धिर्महत्तत्त्वं अहंकरोत्यनयेत्यहंकारो मूलप्रकृतिः। करणे घञो दुर्लभत्वेऽप्यगत्या बाहुलकात्तद्बोध्यम्। इयं मे मत्तोऽभिन्नाऽपृथक्सिद्धा शुक्तिशकलादिव रजतं अष्टधा अष्टप्रकारा प्रकृतिर्जडप्रपञ्चोपादानभूता। यद्वा नात्राव्यक्तमहदहंकारपञ्चतन्मात्राण्येवाष्टौ सांख्याभिमता एव प्रकृतयो ग्राह्या इति नियमोऽस्ति।मनसा ह्येव पश्यति मनसा शृणोति इति मनस इन्द्रियान्तरप्रकृतित्वश्रवणेन सन्तु नवापि प्रकृतयः। तथा चैवं योज्यम्। इयं मे मदभिन्ना प्रकृतिरव्याकृताख्या भूम्यादिभेदेनाष्टधेति मूलप्रकृतेरत्र भूम्यादिभिः सह पाठाज्जन्यत्वमवगम्यते न सांख्यानामिवाजन्यत्वम्।तस्मादव्यक्तमुत्पन्नं त्रिगुणं द्विजसत्तम इतिअव्यक्तं पुरुषे ब्रह्मन्निष्कले प्रविलीयते इति च तस्या अपि प्रभवप्रलययोः स्मरणात्।'),
('nilakantha-sc:source:7.5','Nīlakaṇṭha','gita.7.5','sa','commentary','।।7.5।।एवं क्षेत्रात्मिकां प्रकृतिमुक्त्वा क्षेत्रज्ञात्मिकां तामाह अपरेयमिति। इयं प्रागुक्ता सा अपरा अश्रेष्ठा जडत्वात्। इतस्तु विलक्षणामन्यां परां चेतनत्वेन मदनन्यत्वादुत्कृष्टां मे मत्संबन्धिनीं प्रकृतिं जीवभूतां प्राणधारणनिमित्तभूतां क्षेत्रज्ञाख्यां विद्धि जानीहि। हे महाबाहो यया प्रकृत्या अन्तःप्रविष्टया इदं जगत्स्थावरजंगमशरीरात्मकं धार्यते।'),
('nilakantha-sc:source:7.6','Nīlakaṇṭha','gita.7.6','sa','commentary','।।7.6।।एतदिति। एते परापरे क्षेत्रक्षेत्रज्ञरूपे प्रकृती योनिरुत्पत्तिलयस्थानं येषां भूतानां तानि एतद्योनीनि भूतानि चतुर्विधानि इत्येतदुपधारय सम्यग्जानीहि। किं पातञ्जलानामिव एते प्रकृती ईश्वरादन्ये इत्याशङ्क्याह अहमिति। कृत्स्नस्य स्वस्वप्रकृतिसहितस्य जगतो जडाजडरूपस्य प्रभवः प्रभवत्यस्मादिति प्रभव उत्पत्तिकारणं तथा प्रलीयतेऽस्मिन्निति प्रलयो लयस्थानं च। अतस्ते उभे अपि प्रकृती मत्तो नातिरिच्येते।'),
('nilakantha-sc:source:7.7','Nīlakaṇṭha','gita.7.7','sa','commentary','।।7.7।।एवमेकविज्ञानात्सर्वविज्ञानं प्रकृतमात्मनो जगदुपादानत्वेनोपपाद्य तत एवात्मनो निर्विकारत्वहाने प्राप्ते आह मत्त इति। कारणान्मृदादेः परं पृथग्भूतं घटादि व्यवहारे तयोर्भेदानुभवात्। परतरं तु गवाश्वादिमृदनुपादानकत्वात्। एवं ब्रह्मणः परतरं तदनुपादानकं किञ्चिदपि नास्ति। हे धनंजय एवं प्रपञ्चे ब्रह्माव्यतिरेकं प्रदर्श्य ब्रह्मणि प्रपञ्चव्यतिरेकं सदृष्टान्तमाह मयीति। मयि सद्रूपेण स्फुरणरूपेण च सूत्रवत्सर्वत्रानुस्यूते यदिदं सर्वं मणिगणवत्परस्परव्यावृत्तं तत्प्रोतं तेन व्यावृत्तेभ्योऽनुवृत्तं भिन्नमिति न्यायेन प्रपञ्चातीतोऽहमतो न मम विकारित्वमित्यर्थः।'),
('nilakantha-sc:source:7.8','Nīlakaṇṭha','gita.7.8','sa','commentary','।।7.8।।नन्वेवं प्रपञ्चपरमात्मनोर्मणिसूत्रवदुपादानोपादेयभावोऽपि न स्यात्। नहि उपादानं चाननुवृत्तं चेति घटते मृद्धटादावदर्शनादित्याशङ्क्य स्वप्नमायेन्द्रजालरज्जूरगतुल्यत्वं प्रपञ्चस्योपपाद्योभयमप्यविरुद्धमित्युपदिष्टं चेदयमकस्मादुद्विग्नो भविष्यतीति मत्वा दृष्टान्तान्तरैरेवानुवृत्तिं व्यावृत्तिं चिज्जडयोर्दर्शयति रस इति। यथा रसोऽप्सु एकमप्यप्परमाणुमपरित्यज्यानुस्यूतो दृश्यतेऽतो रसरूपे मयि आपः प्रोताः एवं प्रभायां चन्द्रादयः प्रोताः प्रणवे सर्वे वेदाः प्रोताःतद्यथा शङ्कुना सर्वाणि पर्णानि संतृण्णान्येवमोंकारेण सर्वा वाक् संतृण्णा इति वाङ्मात्रे प्रणवानुस्यूतिश्रवणात्। संतृण्णानि संग्रथितानि। एवमाकाशे शब्दः सारभूतस्तस्मिन्मयि खं प्रोतम्। सर्वपुरुषेषु सारं पौरुषं शौर्यर्धैर्यादिरूपं तत्र पुरुषाः प्रोताः। एवमग्रेऽपि द्रष्टव्यम्।'),
('nilakantha-sc:source:7.9','Nīlakaṇṭha','gita.7.9','sa','commentary','।।7.9।।पुण्य इति। रसादिष्वपि द्रष्टव्यम्। अपुण्यस्य सर्वस्याविद्यामात्रविलसितत्वात्। विभावसौ वह्नौ तेजः दहनशक्तिः। जीवन्त्यनेनेति जीवनमन्नं विराजम्। तत्र हि सर्वाणि भूतानि प्रोतानि। अन्ये तु जीवनं आयुरिति व्याचक्षते तपश्चेति। तपो धर्मस्तद्रूपे मयि तपस्विनः प्रोताः।'),
('nilakantha-sc:source:7.10','Nīlakaṇṭha','gita.7.10','sa','commentary','।।7.10।।बीजं कारणम्। सर्वभूतानां पिण्डब्रह्माण्डात्मकानां बीजे मयि पिण्डादिकं प्रोतम्। कनके कुण्डलादिवत्। सनातनं नित्यं बीजान्तरादनुत्पन्नम्। बुद्धिरूपे मयि बुद्धिमन्तः प्रोताः। तेजः प्रागल्भ्यं तद्रूपे मयि प्रगल्भाः प्रोताः।'),
('nilakantha-sc:source:7.11','Nīlakaṇṭha','gita.7.11','sa','commentary','।।7.11।।बलरूपे मयि बलवन्तः प्रोताः। कामरागविवर्जितं कामस्तृष्णा रागो रञ्जना। तौ हि आविद्यकौ। अतो निरवद्यस्य बलं तद्वर्जितम्। एवं धर्माविरुद्धकामरूपे मयि ईदृशाः कामवन्तः प्रोताः।'),
('nilakantha-sc:source:7.12','Nīlakaṇṭha','gita.7.12','sa','commentary','।।7.12।।सात्विकाः धर्मज्ञानवैराग्यैश्वर्यादयः राजसाः लोभप्रवृत्त्यादयः तामसाः निद्रालस्यादयः तान्सर्वान्मत्त एव रसतन्मात्रादिरूपात्सूत्रात्मनो निर्गता इति विद्धि। नन्वेवं तव सर्वजगदात्मनो विकारित्वापत्त्या कौटस्थ्यहानिरित्याशङ्क्याह नत्वहं तेषु ते मयीति। येष्वबादयः प्रोतास्तेषु सूत्रावयवभूतेषु रसादिष्वनृतजडरूपेष्वबाधितात्मचिन्मात्ररूपो घटशरावोदञ्चनादाविव मृत् नास्मि। अनृतस्यास्य सत्तास्फुरणे एव स्वकीये प्रयच्छामि नत्वनृतात्मा भवामीत्यर्थः। ते तु मय्येवाध्यस्ता मदनन्याः यथा रज्ज्वामध्यस्ताः सर्पादयो रज्ज्वनन्याः।तदनन्यत्वमारम्भणशब्दादिभ्यः इतिन्यायात्। अनन्यत्वं व्यतिरेकेणाभावः। नखल्वनन्यत्वमित्यभेदं ब्रूमः किंतु भेदं निषेधामः। कुतः आरम्भणशब्दात्वाचारम्भणं विकारो नामधेयम् इतिविकारस्य वागालम्बनत्वेन स्वप्नमायेन्द्रजालिकविषयसाम्यश्रुतेः। नह्यात्मनो विचित्रप्रपञ्चात्मत्वे ते मयीत्यंशाविरोधेऽपि नत्वहं तेष्वित्यंशे विरोधपरिहारो युज्यते। कार्यस्य कारणात्मकत्वावश्यंभावात्। तस्माद्विवर्तवादाश्रयेणैव ब्रह्मणो जगदुपादानत्वकूटस्थत्वे निर्वहत इति साधूक्तं नत्वहं तेषु ते मयीति।'),
('nilakantha-sc:source:7.13','Nīlakaṇṭha','gita.7.13','sa','commentary','।।7.13।।कथं तर्हि स्थूलसूक्ष्मप्रपञ्चबाधेन जना आत्मानं नावगच्छन्तीत्याशङ्क्याह त्रिभिरिति। एभिः पूर्वोक्तैस्त्रिभिस्त्रिविधैर्भावैः प्रकाशप्रवृत्तिनियमाद्यैर्गुणमयैः सत्वरजस्तमोगुणविकारैः इदं चराचरं प्राणिजातं जगच्छब्दवाच्यं मोहितं सत् एभ्यो गुणेभ्यः परं मां न जानाति। यथा रज्ज्वां सर्पभ्रमेण व्याकुलः सर्पात्परां रज्जुं न जानाति तद्वत्। परत्वे हेतुः अव्ययम्। एते भावाः परिणामित्वाद्व्ययवन्तः अहं तु तद्विपरीतः साक्षीत्यव्ययः।'),
('nilakantha-sc:source:7.14','Nīlakaṇṭha','gita.7.14','sa','commentary','।।7.14।।देवस्य जीवरूपेण लीलया क्रोडतो मम संबन्धिनीयं दैवी हि प्रसिद्धा पिण्डब्रह्माण्डरूपेण वितता एषा मम चिन्मात्रस्य माया मामहं न जानामीति साक्षिप्रत्यक्षत्वेनापलापानर्हा अनृतस्य प्रपञ्चस्येन्द्रजालादेरिवप्रकाशिका गुणमयी सत्वरजस्तमोगुणमयी दुरत्यया दुरतिक्रमा। ये मामेव सर्वभूतस्थं भगवन्तं वासुदेवं प्रपद्यन्ते विषयीकुर्वन्ति त एवैतां मायां तरन्ति। अधिष्ठानज्ञानेनैव समूलस्य भ्रमस्योच्छेदो भवति नतु ज्ञानान्तरेण वा वृत्तिनिरोधेन वेत्यर्थः। अयमर्थः जीवेश्वरविभागशून्ये शुद्धचिन्मात्रे कल्पितो मायादर्पणश्चित्प्रतिबिम्बरूपं जीवं वशीकृत्य बिम्बचैतन्यमनुरुध्य प्रचलति। अयस्कान्तमनुरुध्येव लोहशलाका। इदमेव ईश्वराधीनत्वं मायायाः। ईश्वरस्य च मायाद्वारा सर्वस्रष्टृत्वमपि। तथा च श्रुतिःतस्मान्मायी सृजते विश्वमेतत्तस्मिंश्चान्यो मायया सन्निरुद्धः इति। तथाचैकैव माया जीवेश्वरयोरुपाधिर्दर्पण इव बिम्बप्रतिबिम्बयोर्बिम्बप्रतिबिम्बभावानाक्रान्तमुभयानुस्यूतं शुद्धचिन्मात्रमन्यत्तृतीयं मुक्तप्राप्यम्। जीवेश्वरौ च उपाधिपक्षपातदशायामल्पज्ञत्वसर्वज्ञत्वशास्यत्वशासितृत्वादिभावं भजेते। तावेव तदभावे उपाधिप्रचारदर्शिनौ उदासीनबोधरूपतया जीवसाक्षीश्वरसाक्षीतिशब्दाभ्यां व्यवह्रियेते। एवं च जीव ईश्वराराधनावाप्तप्रत्यक्तत्वज्ञानेन मायायां नष्टायां तत्कार्यस्यापि नाशेन साक्ष्याभावात्साक्षित्वमपि परित्यज्य बिम्बप्रतिबिम्बानुस्यूतं शुद्धं तृतीयं चैतन्यं प्राप्नोतीति तदिदमुक्तं दैवी मायेति। मम मायेति चैकस्या एव जीवेश्वरसंबन्धित्वं जीवस्येश्वरभजनेन मायातरणमिति च।'),
('nilakantha-sc:source:7.15','Nīlakaṇṭha','gita.7.15','sa','commentary','।।7.15।।कुतस्तर्हि सर्वे त्वां प्रपद्य मायां न तरन्तीत्याशङ्क्याह न मामिति। यतो दुष्कृतिनोऽतश्चित्तशुद्ध्यभावान्मूढाः आत्मानात्मविवेकहीनाः। अतएव नराधमा मां न प्रपद्यन्ते। कुतो दुष्कृतिनः। यतो माययाऽपहृतं तिरस्कृतं ज्ञानमखण्डसंविद्रूपं ब्रह्म येषां ते अपहृतज्ञानाः। एतेन मायाया आवरणशक्तिरुक्ता। किंच आसुरमसुराणां विरोचनादीनां भावं चित्ताभिप्रायंआत्मैवेह महय्यः इत्यादिना श्रुतं देहेन्द्रियसंघात एव सम्यक्संतर्पणीय इत्येवंविधमाश्रिताः। एतेन मायाया विक्षेपशक्तिरुक्ता। तदेवं मायया स्वरूपानन्दमावृत्य देहात्मभ्रमे जनिते सति तदभिमानाद्देहादिपुष्ट्यर्थं दुष्कृतं कुर्वन्ति तेन च मूढाः सन्तो नराधमा मां न प्रपद्यन्ते। सर्वानर्थमूलं मायैवेत्यर्थः।'),
('nilakantha-sc:source:7.16','Nīlakaṇṭha','gita.7.16','sa','commentary','।।7.16।।येतु सत्यपि देहाद्यध्यासे मत्तो बिभ्यति मत्प्रीत्यर्थं सुकृतमेवाचरन्ति तेऽपि चतुर्विधा न केवलं सर्वे मदेककामा इत्याशयेनाह चतुर्विधा इति। आर्तः पीडितः पीडापरिहारार्थी। जिज्ञासुः स्वाज्ञाननाशार्थी। अर्थार्थी धनाद्यर्थी। ज्ञानी चेति चतुर्विधा मां भजन्ते।'),
('nilakantha-sc:source:7.17','Nīlakaṇṭha','gita.7.17','sa','commentary','।।7.17।।किं सर्वेऽपि समा एते सुकृतिन इति साधारण्येन विशेषणादत आह तेषामिति। तेषां मध्ये ज्ञानी विशिष्यते। यतो नित्ययुक्तः। आर्तादयो हि कामिनः कामपूर्तौ न मद्भजने युक्ता भवन्ति अयंतु नित्ययुक्त एकभक्तिश्चैकभावेन भजनं करोति। तथाहि आर्ता रोगिणः सूर्यं भजन्ते जिज्ञासवः सरस्वतीं अर्थार्थिनः कुबेरादीनिति तेषां तत्तत्कामार्थित्वेनानेकभक्तित्वं दृश्यते। तस्य नित्ययुक्तत्वे एकभक्तित्वे च हेतुः हि यतः ज्ञानिनोऽहमत्यर्थं प्रियः आत्मत्वादेव। आत्मा च प्रियः निरुपाधिप्रेमगोचरत्वात्तदेतत्प्रेयः पुत्रात्प्रेयो वित्तात्प्रेयोऽन्यस्मात्सर्वस्मादान्तरो यदयमात्मा इति श्रुतेश्च। सच ज्ञानी मम प्रियो भक्तानां दुर्लभत्वादिति भावः।'),
('nilakantha-sc:source:7.18','Nīlakaṇṭha','gita.7.18','sa','commentary','।।7.18।।उदारा इति। सर्वेऽप्येते उदारा उत्कृष्टा एव। ज्ञानी तु ममात्मैवेति मम मतं निश्चितम्। हि यतः स युक्तात्मा अहमेव भगवान्वासुदेव इत्यभेदेन मयि समाहितचित्तो मामेवानुत्तमां श्रेष्ठां गतिमास्थितो नतु मत्तोऽन्यदारोग्यादिकं कामयमानो मद्भक्तिं करोति। किंतर्हि मत्प्राप्त्यर्थमेव मां भजत इत्यर्थः।'),
('nilakantha-sc:source:7.19','Nīlakaṇṭha','gita.7.19','sa','commentary','।।7.19।।किंच वासुदेवः सर्वमिति ज्ञानवान् यो बहूनां जन्मनामन्ते चरमजन्मनि मां प्रपद्यते सम्यग्दर्शनेनापरोक्षीकरोति स महात्मा ब्रह्मभूतः सुदुर्लभ इति योजना।'),
('nilakantha-sc:source:7.20','Nīlakaṇṭha','gita.7.20','sa','commentary','।।7.20।।अन्ये तु तैस्तैः कामैः पुत्रपश्वादिविषयैर्हृतज्ञानाः हृतं दूरीकृतं ज्ञानं विवेको येषां ते। अन्यदेवताः अहमेतस्या आराधनेनेदं फलमवाप्नवानीति भेदबुद्ध्या प्रपद्यन्ते इन्द्रादीन् तं तं नियमं चतुर्दश्युपवासादिकमास्थाय स्वया प्रकृत्या वक्ष्यमाणविधया दैव्या आसुर्या वा नियता निगृहीताः।'),
('nilakantha-sc:source:7.21','Nīlakaṇṭha','gita.7.21','sa','commentary','।।7.21।।किंच यो यो भक्तः सात्विको राजसस्तामसो वा यां यां तनुं तादृशीमेव देवादिरूपां यक्षरक्षोरूपां भूतप्रेतरूपां वा मूर्तिं श्रद्धया तादृश्यैवार्चितुमिच्छति तस्य तस्य भक्तस्य तामेव श्रद्धां सात्त्विकीं राजसीं तामसीं वाहं सर्वेश्वरोऽचलां विदधामि।'),
('nilakantha-sc:source:7.22','Nīlakaṇṭha','gita.7.22','sa','commentary','।।7.22।।ततश्च स तया श्रद्धया युक्तः सन् तस्या मूर्तेराराधनं ससाधनं वशीकरणमीहते इच्छति। ततश्च कामान्विषयांल्लभते। मयैव विहितानाज्ञापितान्। हितानीप्सितान्। एतेन सर्वासां देवतानां स्वाज्ञावशवर्तित्वं दर्शितम्।'),
('nilakantha-sc:source:7.23','Nīlakaṇṭha','gita.7.23','sa','commentary','।।7.23।।अल्पमेधसांअथ यत्रान्यत्पश्यत्यन्यच्छृणोत्यन्यन्मनुतेऽन्यद्विजानाति तदल्पम् इति श्रुतेः द्वैतमल्पं तत्रैव मेधा येषां ते। बाह्यार्थाभिलाषिणामित्यर्थः। तेषां तत्फलमन्तवत् सर्वस्य बाह्यार्थस्यान्तवत्त्वादेव। तुशब्दोऽभेदेनेश्वरभक्तेभ्यो विभेदार्थः। यतो देवयजो देवान्यजन्ते इति देवयजस्ते देवानन्तयुक्तानेव यान्ति। एवं यक्षरक्षोभक्ता यक्षादीनेव यान्ति। भूतप्रेतभक्ताश्च भूतादीनेवेत्यपि द्रष्टव्यम्। मद्भक्तास्तु मामेवानन्तं यान्ति। अतस्तेऽनन्तफलभाज इत्यर्थः।'),
('nilakantha-sc:source:7.24','Nīlakaṇṭha','gita.7.24','sa','commentary','।।7.24।।एवं तर्हि कुतस्त्वामेव सर्वे न प्रतिपद्यन्त इत्याशङ्क्याज्ञानादित्याह अव्यक्तमिति। अव्यक्तं सर्वोपाधिशून्यत्वेनास्पष्टमपि वासुदेवशरीरेण व्यक्तिमापन्नमस्मदादिवच्छरीराभिमानिनं मामबुद्धयो मन्यन्ते। यतो मम परं भावं परत्वमुत्कृष्टत्वमजानन्तः। उत्कृष्टत्वमेव विशिनष्टि। अव्ययं न व्येतीत्यव्ययमविनाशिनम्। अनुत्तमं यस्मादन्यदुत्कृष्टं च नास्ति। निरतिशयमखण्डैश्वर्यरूपमित्यर्थः।'),
('nilakantha-sc:source:7.25','Nīlakaṇṭha','gita.7.25','sa','commentary','।।7.25।।कुतस्त्वद्विषयमज्ञानं लोकस्येत्यत आह नाहमिति। हे योग योगिन्। अर्शआद्यच्प्रत्ययान्तोऽयं योगशब्दः। अहं तत्पदार्थः सर्वस्य योगिनस्त्वंपदार्थमात्राभिज्ञस्य न प्रकाशोऽस्मि। तत्र हेतुः मायासमावृत इति। भाष्ये तु योगो युक्तिर्गुणानां घटनं सैव योगमाया चित्तसमाधिर्वा योगो भगवतस्तत्कृता मायेति। भगवत्संकल्पवशवर्तिनी मायेत्यर्थः। उत्तरार्धः स्पष्टार्थः।'),
('nilakantha-sc:source:7.26','Nīlakaṇṭha','gita.7.26','sa','commentary','।।7.26।।ननु त्वदभिन्नं लोकं त्वन्माया मोहयति चेत्त्वां कुतो न मोहयतीत्यत आह वेदाहमिति। सत्यम्। सत्यपि लोकस्य मम चाभेदे औपाधिकभेदस्य सत्त्वादुपाधिधर्माभिमानित्वाल्लोको मूढः तदभावाच्चाहं सर्वज्ञ इति विशेषः। अक्षरार्थः स्पष्टः।'),
('nilakantha-sc:source:7.27','Nīlakaṇṭha','gita.7.27','sa','commentary','।।7.27।।केन पुनर्निमित्तेनातीतादीनि भूतानि न जानन्तीत्याशङ्क्याह इच्छेति। इच्छा रागः द्वेषस्ताभ्यां समुत्थितो द्वन्द्वमोहः शोभनाशोभनसत्यासत्यनित्यानित्यात्मानात्मसु विपर्ययः अशोभने शोभनबुद्धिः शोभने वा अशोभनबुद्धिरित्येवंरूपस्तेन। हे भारत भरतान्वय सर्वभूतानि सर्गे सृष्टिविषये मोहमविवेकं यान्ति हे परंतप। अयं भावः यो हि सृष्टेरुपादानं स्वरूपं च तत्त्वतो जानाति स ब्रह्मवित् सर्वज्ञत्वादतीतादीञ्जानाति सृष्टौ च सर्वेषां मोहोऽस्ति अशोभने स्त्र्यादौ शोभनाध्यासात् असत्ये प्रपञ्चे सत्यत्वाध्यासात् सत्ये चात्मनोऽसङ्गत्वेऽसत्यत्वाध्यासात् अनित्ये स्वर्गादौ नित्यत्वाध्यासात् अनात्मनि देहादावात्माध्यासात्। अतो विपर्ययेण सृष्टिज्ञानं प्रतिबद्धं तेन च सार्वज्ञ्यं न जायतेऽस्मदादीनामिति।'),
('nilakantha-sc:source:7.28','Nīlakaṇṭha','gita.7.28','sa','commentary','।।7.28।।केषां तर्हि सार्वज्ञ्यं भवतीत्याशङ्क्याह येषां त्विति द्वाभ्याम्। येषां पुनर्जनानां पुण्यकर्मणां पापं अन्तगतं अन्तं नाशं प्राप्तं।द्वितीया श्रिता इति समासः। ते द्वन्द्वमोह उक्तलक्षणस्तेन निर्मुक्ताः सन्तः प्रथमं दृढव्रताः शमदमादिदार्ढ्य भाजो भूत्वा मां भजन्ते।'),
('nilakantha-sc:source:7.29','Nīlakaṇṭha','gita.7.29','sa','commentary','।।7.29।।ततश्च जरामरणयोः प्रवाहादात्मनो मोक्षाय मामाश्रित्य मयि समाहितचेतसो भूत्वा ये यतन्ति यतन्ते ज्ञानलाभाय वेदान्तश्रवणादौ ते तत् सर्ववेदान्तप्रसिद्धं कृत्स्नं ब्रह्म विदुः। विराडाद्युपासका ह्यकृत्स्नब्रह्मविदः।सूत्रकारणयोर्निष्कलस्य चाज्ञानात् श्रीगोपालबालोपासकास्तु तत्पदलक्ष्यकृत्स्नब्रह्मविदोऽतस्तेऽध्यात्मादिकं कात्स्न्र्येन जानन्ति। सर्वविदो भवन्तीत्यर्थः। अनेनयज्ज्ञात्वा नेह भूयोऽन्यज्ज्ञातव्यमवशिष्यते इत्येकविज्ञानात्सर्वविज्ञानप्रतिज्ञा या पूर्वं कृता तस्या उपसंहारो दर्शितः। अध्यात्मं आत्मनि शरीरे स्थितं प्रत्यगात्मविषयं वस्तु शुद्धं त्वंपदार्थमित्यर्थः। कर्म च तत्त्वंपदार्थज्ञानयोः साधनं श्रवणादिकं सर्वं विदुः।'),
('nilakantha-sc:source:7.30','Nīlakaṇṭha','gita.7.30','sa','commentary','।।7.30।।एवं तत्पदार्थविवेकं सद्योमुक्तिहेतुं समाप्य तत्प्राप्त्युपायभूतान्युपासनानि क्रममुक्तिफलानि विस्तरेण वक्तुकामः संक्षेपेण सूत्रयति साधिभूतेति। अधिभूतं च अधिदैवं च ताभ्यां सहितं साधिभूताधिदैवम्। तथाऽधियज्ञेन सहितं साधियज्ञं च मां ये विदुरुपासते ते युक्तचेतसः। यतो नित्यं समाहितचित्तास्ततो मां प्रयाणकालेऽपि सर्वजनव्यामोहके विदुरेव। भावनादार्ढ्यान्मरणकालेऽपि तस्य ज्ञानस्य प्रमोषो न भवत्यतो भगवति नैरन्तर्येण दृढा भावना कर्तव्येति भावः। अधिभूतादिपदार्थं तु भगवानेव व्याख्यास्यतीति नोक्तवन्तो वयम्।'),
('nilakantha-sc:source:8.1','Nīlakaṇṭha','gita.8.1','sa','commentary','।।8.1।।पूर्वस्मिन्नध्याये मायोपहितं ब्रह्म जगत्कारणमुक्तंतच्चोत्तमानामनुपाधिब्रह्मप्रतिपत्तावुपलक्षणं मध्यमानामुपास्यं चेति मत्वा प्रतिपत्तव्यं ब्रह्म तद्विषय एकः उपासनाविषयाश्च षट् एवं सप्त प्रश्नविषयास्ते ब्रह्म तद्विदुरित्यध्यायान्ते सार्धश्लोकेन भगवता सूत्रितास्तद्वृत्तिरूपोऽयमध्याय आरभ्यते। तत्र सूत्रितानां ब्रह्मादिशब्दानामर्थं बुभुत्सुरर्जुन उवाच। किं तत्कृत्स्नं ब्रह्मेति प्रथमः प्रश्नः। शेषः स्पष्टार्थः श्लोकः।'),
('nilakantha-sc:source:8.2','Nīlakaṇṭha','gita.8.2','sa','commentary','।।8.2।।अधियज्ञः कथं कोऽत्र। क इति स्वरूपप्रश्नः। कथं ज्ञेय इति पदापकर्षेण तत्तदुपासनाप्रकारप्रश्नश्चेति द्वयं मिलित्वा एकएव प्रश्नः। शेषं स्पष्टम्।'),
('nilakantha-sc:source:8.3','Nīlakaṇṭha','gita.8.3','sa','commentary','।।8.3।।क्रमेणैषां प्रश्नानामुत्तरमाह -- अक्षरमित्यादिभिस्त्रिभिः। तत्र किं तद्ब्रह्मेत्यस्योत्तरमक्षरं परमं ब्रह्मेति। यत्परमक्षरं तद्ब्रह्मेति योजना। अक्षरशब्दस्य वर्णेषु रूढत्वात्ओमित्येतदक्षरम् इत्यादिश्रुतौओमित्येकाक्षरं ब्रह्म इति स्मृतौ च दर्शनेनात्रापि प्रणवस्याक्षरशब्देन ग्रहणे प्रसक्ते परममिति विशेषणं प्रणवस्य परब्रह्मत्वासंभवात्। अतश्चएतद्वै तदक्षरं गार्गि ब्राह्मणा अभिवदन्त्यस्थूलमनण्वह्रस्वमदीर्घम् इति श्रुतिप्रसिद्धमखण्डैकरसं वस्तु अक्षरशब्दितं तद्ब्रह्मेति प्राञ्चः। यद्वा अक्षरशब्देन जीवःकूटस्थोऽक्षर उच्यते। उत्तमः पुरुषस्त्वन्यः इति गीतासुक्षरं प्रधानममृताक्षरं हरः क्षरात्मानावीशते देव एकः इति श्रुतौ च कूटस्थपदेनामृतपदेन च विशेषितस्याक्षरपदस्य जीववाचित्वदर्शनात्। अमृतोक्षरमित्यपेक्षिते उत्वाभावश्छान्दसः। तथाचाक्षरं जीवाख्यं परमं ब्रह्म। परममिति विशेषणेन सोपाधिकस्य पूर्वाध्यायोक्तस्य व्यावृत्तिः। नहि जीवस्य सोपाधिकस्य ब्रह्मभावः संभवति। व्यावर्तकोपाधौ मायादर्पणे जाग्रति तयोरभेदायोगात्।किं तद्ब्रह्म इति प्रश्ने परममिति विशेषणाभावेऽपिते ब्रह्म तद्विदुः कृत्स्नम् इति प्रश्नोत्थापके सूत्रे परमत्ववाचिना कृत्स्नपदेन ब्रह्मणो विशेषितत्वादुत्तरेऽपि ब्रह्मण एव परममिति विशेषं युज्यत एव। प्रश्नेऽपि तच्छब्देन कृत्स्नत्वस्यैव ग्रहात्। ततश्च किं तत्कृत्स्नं प्रश्ने यदक्षरं जीवाख्यं तदेवापेतोपाधिसंबन्धं सत् कृत्स्नं ब्रह्मेति तत्त्वमसीति महावाक्यार्थः प्रतीचो ब्रह्मभावः प्रतिपादितो भवतीति ह्यद्यम्। तथा स्वोऽनागन्तुको भावः स्वरूपं स्वभावः शुद्धस्त्वंपदार्थः सोऽध्यात्ममुच्यते। भाष्ये तु तस्यैव परस्य ब्रह्मणः प्रतिदेहं प्रत्यगात्मभावः स्वो भावः स्वभावोऽध्यात्ममुच्यते अध्यात्मशब्देनाभिधीयत इति। विसर्गो देवतोद्देशेन द्रव्यत्यागात्मको यागः स कर्मसंज्ञितः। तमेव विशिनष्टि -- भूतेति। भूतानां भावः सात्विकादिः स्वभावः उद्भवश्च तयोः करणात् भूतभावोद्भवकरः। तथाहिबुद्धिः कर्मानुसारिणी इति कर्मानुसारित्वं भावस्य स्मर्यते। तथा उद्भवोऽपि कर्मत एव स्मर्यते।अग्नौ प्रास्ताहुतिः सम्यगादित्यमुपतिष्ठते। आदित्याज्जायते वृष्टिर्वृष्टेरन्नं ततः प्रजाः इति।'),
('nilakantha-sc:source:8.4','Nīlakaṇṭha','gita.8.4','sa','commentary','।।8.4।।क्षरो भावो जनिमद्वस्तु कर्मफलभूतं तत्साधनभूतं च तदधिभूतमित्युच्यते। अधिदैवतं पुरुषः सर्वासु पूर्षु वसतीति सर्वकरणानुग्राहकः सकलदेवतात्मा हिरण्यगर्भः। अधियज्ञो यज्ञाभिमानी विष्णुरन्तर्यामी सोऽहमेव देह्यस्मि। अत्रास्मिन्देहे देहभृतां वर।');
INSERT INTO commentary_fts (unit_id,author,canonical_ref,language,content_type,content) VALUES
('nilakantha-sc:source:8.5','Nīlakaṇṭha','gita.8.5','sa','commentary','।।8.5।।अत्र षट्प्रश्नोत्तरेषु प्रथमे जीवस्य ब्रह्मभाव उक्तः। तं जानतां प्रयाणमेव नास्ति।न तस्य प्राणा उत्क्रामन्त्यत्रैव समवलीयन्ते ब्रह्मैव सन्ब्रह्माप्येति इति श्रुतेः। द्वितीये शुद्धस्त्वंपदार्थ उक्तस्तज्ज्ञानस्यापि वस्तुतत्त्वविषयत्वान्न तत्र भावनापेक्षास्तीति न भावनाफलभूतकाले तत्प्रत्ययोऽपेक्षते। तृतीयचतुर्थयोस्तु कर्मतत्साधनभूतं च जन्यं वस्तूक्तम्। तत्रापि न भावनापेक्षास्ति। अन्तकाले प्रबलेनैव कर्मणा चित्तस्यावरोधात्तत्साधनफलभूतस्यैव स्मरणावश्यंभावेन तत्र भावनाया वैयर्थ्यात् परिशेषादन्त्ययोरेव कार्यकारणब्रह्मणोः सोपाधिकनिरुपाधिकयोरन्यतरस्य भावना सुदृढा चेदन्तकाले तत्प्रत्ययोऽवश्यंभावीति तयोरन्यतरं रूपं परमात्मानं स्मरन् यः कलेवरं मुक्त्वार्चिरादिमार्गेण प्रयाति स ब्रह्मलोकप्राप्तिद्वारा क्रमेण मद्भावं मोक्षं यातीत्याह -- अन्तकाले चेति। स्पष्टा योजना। नास्त्यत्र संशय इति। सोपाधिकब्रह्मोपास्तिं प्रकृत्यशतं चैका च हृदयस्य नाड्यस्तासां मूर्धानमभिनिःसृतैका। तयोर्ध्वमायन्नमृतत्वमेति विष्वगन्या उत्क्रमणे भवन्ति इति तदुपासकस्य गतिपूर्वकस्यामृतत्वस्य श्रवणात्। यस्तु शुद्धत्वंपदार्थरूपमध्यात्मवस्तुमात्रं वेद असौ ब्रह्मात्मैक्यज्ञानाभावात्न तस्य प्राणा उत्क्रामन्ति इत्येतद्वाक्यविषयो न भवति किंतु शतं चैकाचेत्येतस्यैव,विषयः। ननु तस्यानुपासकत्वात्कथमेतदिति चेन्न।नहि कल्याणकृत्कश्चिद्दुर्गतिं तात गच्छति इति न्यायेन तस्योभयभ्रष्टत्वासंभवात्। कठवल्लीषु निष्कलप्रत्यगात्मविदं केवलयोगिनं प्रकृत्य शतं चैकाचेत्याम्नानाच्च।वेदान्तविज्ञानसुनिश्चितार्थाः संन्यासयोगाद्यतयः शुद्धसत्वाः। ते ब्रह्मलोके तु परान्तकाले परामृतात्परिमुच्यन्ति सर्वे इति श्रुतेर्निश्चतार्थानां शोधितत्वंपदार्थानामेव क्रममुक्तिरवगम्यते। नचात्र सुनिश्चितार्था इत्यनेन ब्रह्मात्मैक्यनिश्चयवन्तो ग्रहीतुं शक्याः। तेषां गत्यभावस्य प्रोक्तत्वात्। नाप्युपासकाः असंभवात्। उपासना हि नाम अतस्मिंस्तद्बुद्धिः। यथा शालग्रामे विष्णुबुद्धिरेवं सूत्रविराडन्तर्यामिष्वात्मबुद्धिरिति न तद्वन्तः सुनिश्चितार्था इति वक्तुं शक्यम्। तस्मादध्यात्मविदां ब्रह्मात्मैक्यानवगमादनुपासकत्वेनान्त्यप्रत्ययाभावेऽप्यर्चिरादिगतिप्राप्तिरस्तीति सर्वमनवद्यम्।'),
('nilakantha-sc:source:8.6','Nīlakaṇṭha','gita.8.6','sa','commentary','।।8.6।।न केवलं कार्यकारणब्रह्मणोरेव भावनान्त्यप्रत्ययवशात्तद्भावप्राप्तिहेतुरपि तु कीटस्य जीवत एव भावनाबलाद्भाव्यवस्तुभावप्राप्तिर्दृश्यते। नन्दिकेश्वरस्य च स्मर्यतेस हि महादेवं भावयंस्तत्सारूप्यं देहान्तरं विनैव प्राप्तः इति। योगशास्त्रेऽपि प्रसिद्धम्। तत्र किमु वक्तव्यमन्तप्रत्ययवशाद्देहान्तरे भाव्यभावप्राप्तिरस्तीति मत्वा तमेवार्थमन्यत्रापि दर्शयति -- यं यमिति। तद्भावभावितः भाव्याकारवासनया रञ्जित इत्यर्थः।'),
('nilakantha-sc:source:8.7','Nīlakaṇṭha','gita.8.7','sa','commentary','।।8.7।।यस्मादेवं तस्मात्सर्वेषु कालेषु मामनुस्मर अन्तकाले मत्स्मृत्या मद्भावप्राप्त्यर्थं। युध्यचेति चकारात्कर्मोपास्त्योः समुच्चयोऽवगम्यते। ज्ञानकर्मसमुच्चयकर्तरीव तदुभयानुष्ठातर्येकस्मिन्नेवाधिकारिणि कर्तृत्वाकर्तृत्वप्रत्ययकृतविरोधाभावात्। मयि अर्पिते मदेकनिष्ठतां नीते मनोबुद्धी येन स मय्यर्पितमनोबुद्धिस्त्वं असंशयं मामेवैष्यसि प्राप्स्यसि। अन्तकाले स्मरणेनेति शेषः।'),
('nilakantha-sc:source:8.8','Nīlakaṇṭha','gita.8.8','sa','commentary','।।8.8।।एतदेव श्लोकत्रयेण विवृणोति -- अभ्यासेति। अभ्यासयोगयुक्तेनतत्र स्थितौ यत्नोऽभ्यासः इति सूत्रितोभ्यासः तत्र ध्येये वस्तुनि चित्तस्य स्थिरीकरणार्थो यतः। सच विजातीयप्रत्ययानन्तरितसजातीयप्रत्ययप्रवाहीकरणरूपः सोऽत्राभ्यासः। तत्र भाव्यो विषयः सिद्धः विष्णुप्रतिमादिर्विराडादिर्वा। असिद्धस्तु मानसप्रतिमादिः। तत्रासिद्धे मनसः प्रतिमाकारतासंपादने तत्र स्थैर्यसंपादने चेति विषयभेदाद्विगुणो यत्नः कर्तव्यो भवति। सिद्धे तु चित्तस्थिरीकरणार्थ एक एव यत्नः। तत्र यथा स्वतः स्वच्छः स्फटिको जपाकुसुमोपरागाल्लोहितः स्फटिक इति तत्र लौहित्याध्यासः तत्प्राबल्यात्तत्रैव स्फटिकधीप्रमोषे पद्मरागत्वाध्यासः पद्मरागेऽपि चन्द्रिकायामिन्द्रनीलत्वाध्यासस्तत्रैव तदानीमेव किंचिद्दूरस्थे निहीनोपलत्वाध्यास इत्युत्तरोत्तराध्यासक्रमेण शुद्ध एक एव स्फटिकः पञ्चविधो भवति। एवं स्वतःशुद्धं चैतन्यं मायोपरागात्तदेवेश्वरः मायाप्राबल्ये तस्यैवेश्वरत्वांशप्रमोषे तत्रैव सूत्रात्माध्यासः सूत्रेऽप्यज्ञानदार्ढ्याद्विराडध्यासः ततएव विराडेकदेशेषु शरीरादिषु आत्मत्वभ्रमः तत्र यथा घटान्तर्गतः प्रदीपो घटमात्रं भासयति घटच्छिद्राद्बहिर्गतः किंचित्स्वप्रभया संसृष्टं विषयमवभासयति सर्वात्मना घटाद्बहिर्गतस्तु कृत्स्नं भवनोदरवर्ति पदार्थजातं प्रकाशयति तद्वद्देहान्तर्गता चितिर्देहमात्रं भासयति देहच्छिद्राच्चक्षुरादेर्बहिर्गता सती तत्संनिकृष्टं कंचिद्विषंय रूपादिकमवभासयति सर्वात्मना गुरूक्तयुक्त्या देहकृतपरिच्छेदाभिमाने त्यक्ते त्वपरिच्छिन्ना सती कृत्स्नं विराडात्मानमवभासयति। यथोक्तं बाह्यग्रन्थेष्वपिमणिहुतवहतारासोमसूर्यादयोऽपि क्षितिविषयमिहाल्पं बाह्यमुद्योतयन्ति। सहजलयसमुत्थं द्योतयेज्ज्योतिरन्तस्त्रिभुवनमपि सूक्ष्मस्थूलभेदक्रमेण। इति। सहजलयसमुत्थं सहजः स्वाभाविको देहकृतपरिच्छेदाभिमानस्तस्य लयमात्रादेव उत्थितं क्रमेण संकल्पक्रमेण सदीक्षणमात्राभिनिर्वृत्तत्वात्सर्वस्य प्राक्संकल्पादसत्त्वात्। तथा च श्रुतिःस यदि पितृलोककामो भवति संकल्पादेवास्य पितरः समुत्तिष्ठन्ति इति।दोषनिमित्तं रूपादयो विषयाः संकल्पकृताः इत्यक्षपादसूत्राच्च। दोषा रागादयः। तदेवं प्रकाशमाने विराजिअहमेवेदं सर्वोऽस्मीति मन्यते सोऽस्य परमो लोकः इति शास्त्रप्रामाण्यादुपासकेन गृहीतोऽहंग्रहो यद्यपि वस्तुतत्त्वापेक्षया भ्रान्तिरूपस्तथापि स्वाभाविकाद्देहाहंग्रहात्सत्यरूपः यथा स्फटिके हीनोपलत्वग्रहापेक्षया इन्द्रनीलत्वग्रहस्तद्वत्। यथाच स्फटिके प्रणिधीयमानं चक्षुरुत्तरोत्तरपाटवविवृद्धान्विद्रनीलत्वं बाधित्वा पद्मरागत्वं तद्बाधेन लोहितस्फटिकत्वं तद्बाधेन शुद्धत्वं चावगच्छति एवं गुरूक्तयुक्त्या प्रत्यगात्मनि प्रणिधीयमानं मनोऽस्य बाह्यं बाह्यं रूपमपोह्य आन्तरे आन्तरे अवतिष्ठते। चरमं विशुद्धं रूपं प्राप्य तु स्वयमेव विलीयते। यथोक्तंयेन त्यजसि तत्त्यज इति। येन,मनसा त्यजसि विराडादिभावं तदपि मनस्त्यजेत्यर्थः। तदेवं व्यवहारापेक्षया सिद्धेषु विराट्सूत्रान्तर्यामिषु मनसः स्थिरीकरणार्थो यत्नोऽभ्यासस्तत्फलभूतो योगः समाधिर्ध्येयवस्तुन्येव चेतसः स्थैर्यं तेन गुणेन युक्तं यच्चेतस्तेन। नान्यगामिना अनन्यगामिना। नैकधेतिवत्समासः। तेन चेतसा परमं सर्वोत्कृष्टं पुरुषं निरस्ताशेषदोषम्।यत्सर्वेषां पुरस्तात्सर्वान्पाप्मन औषत्तस्मात्पुरुषः इति निर्वचनात्। दिव्यं द्योतमानमनुचिन्तयन्नहमेव भगवान्सर्वात्मा वासुदेव इति सततमाचार्योपदेशमनुध्यायन् तमेव नदीसमुद्रन्यायेन याति हे पार्थ। तथा च श्रुतिःयथा नद्यः स्यन्दमानाः समुद्रेऽस्तं गच्छन्ति नामरूपे विहाय। तथा विद्वान्पुण्यपापे विधूय परात्परं पुरुषमुपैति दिव्यम् इति। परात्सूत्रात् परमन्तर्यामिणम्।'),
('nilakantha-sc:source:8.9','Nīlakaṇṭha','gita.8.9','sa','commentary','।।8.9।।तदेवमुपासनायाः स्वरूपमुक्त्वोपासस्य स्वरूपमाह -- कविमिति। कविं क्रान्तदर्शिनं सर्वज्ञम्। पुराणं चिरन्तनं। अनुशासितारं जगतोन्तर्यामिणम्। अणोः सूक्ष्मादप्याकाशादेरणीयांसं सूक्ष्मतरं योऽनुस्मरेदनुचिन्तयेत्। सर्वस्य कर्मफलस्य धातारं विभागेन प्रदातारम्। अचिन्त्यरूपं नास्य रूपं विद्यमानमपि केनचिच्चिन्तयितुं शक्यम्। आदित्यवर्णं आदित्यस्येव नित्यप्रकाशरूपो वर्णो दीप्यमानता यस्य तं आदित्यवर्णम्। सर्वजगदवभासकमित्यर्थः। तमसः देहेन्द्रियादावनात्मनि आत्माभिमानरूपाऽविद्यातः परस्तात्पराचीनम्। सति देहाभिमाने न प्रकाशते योगयुक्त्या त्यक्ते तु तस्मिन् स्वयमेव प्रकाशत इत्यर्थः।'),
('nilakantha-sc:source:8.10','Nīlakaṇṭha','gita.8.10','sa','commentary','।।8.10।।उपासनायाः फलमाह -- प्रयाणेति। प्रयाणकाले मनसाऽचलेन वृत्त्यन्तरवर्जितेन भक्त्या भगवति वासुदेवे आराध्यत्वबुद्ध्या युक्तो योगबलेन योगो मनःप्राणेन्द्रियक्रियानिरोधो हृदयपुण्डरीके तेषां वशीकरणमित्यर्थः। तस्यैव बलेन च युक्तो भूमिकाजयक्रमेण प्रागेव मूलाधारादिब्रह्मरन्ध्रान्तस्थानेषु आरोहावरोहक्रमेण संचारितपवनोऽन्तकाले भ्रुवोर्मध्ये आज्ञाचक्रे प्राणमावेश्य सुषुम्नया नाड्या मूलाधारादुत्थापनपूर्वकं सम्यक् निवेश्य स्थापयित्वा। स्थापनप्रयोजनं तु अन्यविस्मरणपूर्वकं दिव्यपुरुषचिन्तनम्। तच्च भ्रूमध्यादुपर्युन्नीयमाने वायौ मनो मूर्च्छामापद्यत इति तस्यामवस्थायां न भवतीत्यन्त्यप्रत्ययस्तत्रैव संपाद्यस्ततोऽर्चिरादिमार्गपर्वणा अमानवस्य पुरुषस्य स्थानविशेषप्रापकस्य प्राप्यस्थानस्य च तस्मिन्नेव स्मरणं कर्तव्यम्। तद्वासनावासितं मनो भ्रूमध्याद्योगिना ऊर्ध्वया नाड्या उत्क्षिप्ते प्राणे मुक्तेषुवद्ब्रह्माण्डखर्परं भित्त्वा प्रचलिते सति लब्धवृत्तिकं भूत्वा पूर्वसंस्कारप्राबल्याद्योगमाहात्म्याच्च दिव्योपाध्युपेतमर्चिरादिपर्वदेवताभिरभिपूज्यमानमुत्तरोत्तरं स्थानं प्रत्यतिवाह्यमानममानवेन च पुरुषेण संगच्छमानं तेन च यथाभिलषितं स्थानं प्रापितमात्मानं पश्यति। तदिदमुक्तं भ्रुवोर्मध्ये सम्यक् प्राणमावेश्येति। स एवं कृत्वा योगी कविं पुराणमित्युक्तलक्षणं परं पुरुषं हिरण्यगर्भाख्यं सर्वस्य भूतजातस्य जनयितारं नारायणादिशब्दप्रतिपाद्यमुपैति समीपे प्राप्नोति। तल्लोकं प्राप्नोतीत्यर्थः। नहि पौराणिकानामिव वैदिकानां मते ब्रह्मविष्णुरुद्रलोकानामुपर्युपरि कल्पनास्ति किंतर्हि सर्वे हिरण्यगर्भलोकाख्ये सत्यलोके एवान्तर्भवन्ति।पराहि सोपासनकर्मोर्जितिर्हिरण्यगर्भप्राप्यता इति बृहदारण्यके तद्भाष्यादौ च स्पष्टम्।'),
('nilakantha-sc:source:8.11','Nīlakaṇṭha','gita.8.11','sa','commentary','।।8.11।।भ्रुवोर्मध्ये प्राणमावेश्येत्युक्तं तत्किं कृत्वा कर्तव्यं तत्कृत्वा च किं कर्तव्यमित्येतद्वयं वदिष्यंस्तत्र प्रतीकत्वेन चिन्त्यं प्रणवं तावद्वाच्यवाचकयोरभेदविवक्षया स्तौति -- यदक्षरं प्रणवाख्यं वाचकं वेदविदो वेदादौ वदन्ति। यद्वा यदक्षरं ब्रह्म तद्वाच्यंएतद्वै तदक्षरं गार्गि ब्राह्मणा अभिवदन्त्यस्थूलमनण्वह्रस्वमदीर्घम् इत्येवंलक्षणं वा वेदविद उपनिषद्विदो वदन्ति यच्च यतयो विशन्ति ब्रह्मप्रतीकत्वेन शरणीकुर्वन्ति पक्षे सम्यग्दर्शने सति सरित्सागरन्यायेन यत्प्रविशन्ति यतयः। यत् अक्षरमिच्छन्तो ब्रह्मचर्यं चरन्तीति पक्षद्वयेऽपि समानम्। तत्ते पदं वर्णत्रयात्मकं पदनीयं वा स्थानं विष्णोः परमं पदं संग्रहेण प्रवक्ष्ये। अयं च वाच्यवाचकयोरभेदः श्रुतिच्छायया गम्यते।अन्यत्र धर्मादन्यत्राधर्मात् इति सर्वधर्मातीतं ब्रह्म प्रकृत्यसर्वे वेदा यत्पदमामनन्ति तपांसि सर्वाणि च यद्वदन्ति। यदिच्छन्तो ब्रह्मचर्यं चरन्ति तत्ते पदं संग्रहेण ब्रवीम्योमित्येतत्। इत्योंकारेणोपसंहारात्। तत्फलं च प्रतीकभावात्। ओंकारं प्रतीकत्वेन प्रकल्प्य तद्वारा शुद्धं शबलं वा ब्रह्म प्रतिपत्तव्यम्। तथा च श्रुत्यन्तरेएतद्वै सत्यकाम परं चापरं च ब्रह्म यदोंकारः इत्युपक्रम्यतस्मादेवंविद्वानेतेनैवायतनेनैकतरमन्वेति इति दृष्टम्। आयतनं शालग्रामवत्प्रतीकं तेन।'),
('nilakantha-sc:source:8.12','Nīlakaṇṭha','gita.8.12','sa','commentary','।।8.12।।भ्रुवोर्मध्ये कथं प्राणमावेशयेदित्यत आह -- सर्वेति। सर्वाणि शब्दादिविषयग्रहणद्वाराणीन्द्रियाणि संयम्य निगृह्य तथा हृदि मनोऽपि निरुध्य तेषां कञ्चुकभूतं प्राणं मूर्धन्यनाड्या सुषुम्नाख्यया मूर्ध्नि भ्रुवोर्मध्ये आधाय कथं योगधारणां योगशास्त्रोक्तां धारणां मनसो देशविशेषनिबन्धिनीं आस्थितः अनुतिष्ठन्सन्।'),
('nilakantha-sc:source:8.13','Nīlakaṇṭha','gita.8.13','sa','commentary','।।8.13।।मूर्ध्नि प्राणमाधाय किं कुर्यादत आह -- ओंकाररूपं एकाक्षरं एकं च तदक्षरं च वर्णो ब्रह्म च तद्व्याहरनुच्चरन् मां च ब्रह्मभूतमनुस्मरन् यो हि देवदत्तं स्मृत्वा तन्नाम व्याहरति तस्मै देवदत्तोऽभिमुखो भवत्येवं ब्रह्मणो नामोच्चारणेन संनिहिततरं व्यापकं ब्रह्म साधकस्य संनिधीयते। संनिहिते च ब्रह्मणि यो देहं त्यजन् म्रियमाणः प्रयाति ऊर्ध्वनाड्या उत्क्रामति स परमां गतिं संनिकृष्टब्रह्मरूपां याति। ब्रह्मैव प्रकृत्य श्रूयतेएषास्य परमा गतिरेषास्य परमा संपदेषोऽस्य परम आनन्दः इति। तामेव गतिं शुद्धं ब्रह्मैव प्राप्नोति ब्रह्मलोकप्राप्तिद्वारा।'),
('nilakantha-sc:source:8.14','Nīlakaṇṭha','gita.8.14','sa','commentary','।।8.14।।इयं मतिरतीव दुर्लभेति मामंस्था इत्याह -- अनन्येति। नास्ति अन्यत्र चेतो यस्यासौ अनन्यचेता इत्यनेन स्मरणे आदर उच्यते। सततमिति नैरन्तर्यम्। यो मां स्मरति नित्यश इति दीर्घकालत्वम्। यावज्जीवं स्मरतीत्यर्थः। तस्याहं सुलभः पार्थ नित्ययुक्तस्य नित्ये योगिनामावश्यके युक्ताहारविहारादौ यमनियमादौ च युक्तस्यावहितस्य योगिनः। योगमनुतिष्ठतः।'),
('nilakantha-sc:source:8.15','Nīlakaṇṭha','gita.8.15','sa','commentary','।।8.15।।त्वल्लाभेऽपि किं स्यादत आह -- मामिति। मामुपेत्य पुनर्द्वितीयवारं जन्म नाप्नुवन्ति। यज्जन्म दुःखानामालयभूतं मूढदृष्ट्या किंचित्सुखालयत्वेऽप्यशाश्वतं नश्वरम्। तुच्छमित्यर्थः। के नाप्नुवन्ति। महात्मानो योगेन जितचित्ताः। अतएव परमां संसिद्धिं मोक्षं गताः। अगता अपि प्रत्यासन्नत्वाद्गता एव। तथा ब्रह्मलोकगतान्प्रकृत्य स्मर्यतेब्रह्मणा सह ते सर्वे संप्राप्ते प्रतिसंचरे। परस्यान्ते कृतात्मानः प्रविशन्ति परं पदम् इति। प्रतिसंचरे ब्राह्मे प्रलये। परस्य चतुर्मुखस्य अन्ते नाशे।'),
('nilakantha-sc:source:8.16','Nīlakaṇṭha','gita.8.16','sa','commentary','।।8.16।।त्वदलाभेऽपि किं स्यादत आह -- आब्रह्मेति। आब्रह्मभुवनाद्ब्रह्मलोकमभिव्याप्य। ब्रह्मलोकेन सहैवेत्यर्थः। लोकाः पुनरावर्तिनः पुनरावृत्तिस्वभावाः। हे अर्जुन शेषं स्पष्टम्। अत्रेयं व्यवस्था। ये क्रममुक्तिफलाभिर्दहरादिविद्याभिर्ब्रह्मलोकं गतास्ते तत्रैव ज्ञानं प्राप्य ब्रह्मणा सह मुच्यन्ते। येतु पञ्चाग्निविद्याभिर्ब्रह्मलोकं गतास्तेऽनुपासितपरमेश्वराः पुनरावर्तन्त इति।'),
('nilakantha-sc:source:8.17','Nīlakaṇṭha','gita.8.17','sa','commentary','।।8.17।।आवृत्तिभाजां कालपरिच्छेदमाह -- सहस्रेति। युगशब्दोऽत्र चतुर्युगपर्यायः।चतुर्युगसहस्रं तु ब्रह्मणो दिनमुच्यते इति पुराणान्तरदर्शनात् सहस्रं चतुर्युगानि पर्यन्तोऽवसानं यस्य। चतुर्युगसहस्रं ब्रह्मणो दिनं रात्रिरपि तावतीत्याह -- रात्रिमिति। अत्रापि चतुर्युगसहस्राणां अन्तो भवति तां चतुर्युगसहस्रान्ताम्। ते प्रसिद्धा अहोरात्रविदो जना विदुः।'),
('nilakantha-sc:source:8.18','Nīlakaṇṭha','gita.8.18','sa','commentary','।।8.18।।किं ब्रह्मणोऽह्नि जायते किंवा रात्रावित्यत आह -- अव्यक्तादिति। अत्र दैनंदिनसृष्टिप्रलययोः प्रकृतत्वादव्यक्तशब्देन नाव्याकृतं वियदादिकारणमिह ग्राह्यम्। तदा आकाशादीनां सत्त्वात्। किं तर्हि प्रजापतेः स्वापावस्थैवेहाव्यक्तशब्दार्थः। अयं भावः -- प्रजापतेः स्वापकाले तत्कल्पितः स्थावरजगंमप्रपञ्चः सर्वोऽपि तदीयेऽज्ञानेऽव्याकृताख्ये लीयते रात्र्यागमे। तथा दिवसागमे पुनस्तत एव यथापूर्वमाविर्भवति। एवं दृष्टिसृष्टिन्यायेनास्मत्कल्पितोऽप्ययं वियदादिप्रपञ्चोऽस्मत्सुषुप्तौ लीयते अस्मत्प्रबोधे यथापूर्वं प्रादुर्भवतीति।'),
('nilakantha-sc:source:8.19','Nīlakaṇṭha','gita.8.19','sa','commentary','।।8.19।।कृतहानाकृताभ्यागमदोषापमुक्तये बन्धमोक्षशास्त्रप्रवृत्तिसाफल्याय च अविद्यादिवशादवशोऽयं भूतग्रामः पुनःपुनर्भूत्वा पुनः पुनः प्रलीयत इत्याह वैराग्योत्पादनार्थम् -- भूतग्राम इति। अहरागमे भूत्वा भूत्वा रात्र्यागमे प्रलीयत इति योजना। स एव भूत्वा प्रलीयते नान्योऽभिनवो भवतीत्यर्थः। कुतः यतोऽवशः अविद्याकामकर्माधीनस्तस्मात्सर्वानर्थबीजभूताया अविद्याया विद्यया उच्छेदे जन्ममरणप्रवाहविच्छेदायावश्यं यतितव्यमित्यर्थः।'),
('nilakantha-sc:source:8.20','Nīlakaṇṭha','gita.8.20','sa','commentary','।।8.20।।एवं ब्रह्मभुवनान्तानामावृत्तिं व्याख्याय यत्प्राप्तानामावृत्तिर्नास्ति तदक्षरं परमं ब्रह्मेत्युपक्रान्तं वस्तु लक्षयति -- परस्तस्मादिति त्रिभिः। पर इति। तस्मादव्यक्ताद्भूतग्रामबीजभूतादविद्यालक्षणादनृतात् अन्योऽत्यन्तविलक्षणो भावः सत्ता। तुशब्दात्पराभिमतं सत्तासामान्यं वारयति। तस्य सामान्यादिभ्यो व्यावृत्तत्वात्। अस्य च सर्वानुगतत्वात्। सनातनो नित्यैकरूपः। उपाधिमान् हि उपाधिविक्रियया नित्यं विक्रियत इव भाति। अयं त्वनुपाधित्वान्नित्यैकरूप एव यः स भावः सर्वेषु भूतेषु वियदादिषु नश्यत्सु न विनश्यति केवलसत्तारूपत्वात्। एतेन तस्य कालत्रयाबाध्यत्वं नित्यत्वं चोक्तम्।'),
('nilakantha-sc:source:8.21','Nīlakaṇṭha','gita.8.21','sa','commentary','।।8.21।।अव्यक्तो न व्यज्यत इति दृश्यत्वं निरस्तम्। अक्षरोऽश्नुते व्याप्नोतीति त्रिविधपरिच्छेदशून्यत्वमुक्तम्। तं भावं परमां गतिम्। ब्रह्मलोकान्ता गतिरपरमा। कार्यत्वात्। इयं तु परमा। कार्यकराणातीतत्वात्। आहुःएषास्य परमा गतिः इत्यादयः श्रुतयः। यं भावं प्राप्य न निवर्तन्ते पुनः संसारे न पतन्ति तदिति विधेयापेक्षं क्लीबत्वम्। स एव मम विष्णोः परममुपाध्यस्पृष्टं धाम प्रकाशःतद्विष्णोः परमं पदम् इति श्रुतिप्रसिद्धं निष्कलं ब्रह्म।'),
('nilakantha-sc:source:8.22','Nīlakaṇṭha','gita.8.22','sa','commentary','।।8.22।।एवं ज्ञेयं प्रत्यगभिन्नं ब्रह्मोक्त्वा जगत्कारणमुपासनीयमितोऽन्यदित्याह -- पुरुष इति। तुशब्दः पूर्ववैलक्षण्यद्योतनार्थः। हे पार्थ योयं भक्त्या आराधनेन। उपासनेनेतियावत्। कीदृश्या। अनन्यया नास्त्यन्यो यस्यां सा तया उपास्योपासकभेदमन्तरेणाहंग्रहरूपयेत्यर्थः। तया भक्त्या यो लभ्यः स परः पूर्वोक्तादव्यावृत्ताननुगतादक्षरादन्यः कारणात्मेति यावत्। लभ्यत्वादेवास्यान्यत्वमपि। नह्यात्मा च लभ्यश्चेति युज्यते। अस्य कारणत्वमेवाह -- यस्येति। यस्य पुरुषस्यान्तःस्थानि बीजे द्रुम इव सर्वाणि वियदादीनि स्थावरजंगमानि च येन च इदं सर्वं ततं व्याप्तमुपादानत्वात् स भक्त्या लभ्यत इति योजना।'),
('nilakantha-sc:source:8.23','Nīlakaṇṭha','gita.8.23','sa','commentary','।।8.23।।पूर्वोक्तानामोंकारद्वारा सगुणब्रह्मविदां क्रममुक्तिभाजां ब्रह्मप्रतिपत्तये उत्तरो मार्गो वक्तव्य इत्यत आह -- यत्रेति। आवृत्तिमार्गोपन्यासोऽनावृत्तिमार्गस्तुत्यर्थः। योगिन इति। योगिनः कर्मिणश्चोच्यन्ते तेषां यथायोगं मार्गद्वयविभागः। शेषं स्पष्टम्।'),
('nilakantha-sc:source:8.24','Nīlakaṇṭha','gita.8.24','sa','commentary','।।8.24।।तत्रोपासकानां देवयानं पन्थानमाह -- अग्निरिति। अग्निर्ज्योतिरित्यर्चिरभिमानिनी देवता लक्ष्यते। एवमहरित्यहरभिमानिनी। एवं शुक्लपक्षस्य षष्ठमाससंमितोत्तरायणस्य चाभिमानिन्यौ देवते एव। एतच्चान्यासामप्युपलक्षणम्। तत्र प्रयाता उत्क्रान्ता ब्रह्मकार्यं ब्रह्मतद्वारा परं च गच्छन्ति। ब्रह्मविदो ब्रह्मोपासका जनाः।'),
('nilakantha-sc:source:8.25','Nīlakaṇṭha','gita.8.25','sa','commentary','।।8.25।।एतेन च धूमो रात्रिरित्येषोऽपि धूमादिमार्गः कर्मिणामपक्वयोगिनां चोचित आवृत्तिफलश्च व्याख्यातः।'),
('nilakantha-sc:source:8.26','Nīlakaṇṭha','gita.8.26','sa','commentary','।।8.26।।उक्तौ मार्गावुपसंहरति -- शुक्लेति। शुक्ला ज्ञानहेतुत्वादर्चिरादिगतिः तदभावात्कृष्णा धूमादिगतिः। एकया शुक्लया। अन्यया कृष्णया।'),
('nilakantha-sc:source:8.27','Nīlakaṇṭha','gita.8.27','sa','commentary','।।8.27।।एते सृती मार्गौ आवृत्त्यनावृत्तिफले जानन् योगी न मुह्यति। योगभ्रष्टोऽयतिरल्पप्रयत्नश्च योगी न भवति कश्चन कोऽपि। यस्मादेवं तस्मात्सर्वेष्वित्यादि स्पष्टम्।'),
('nilakantha-sc:source:8.28','Nīlakaṇṭha','gita.8.28','sa','commentary','।।8.28।।पुनः श्रद्धाभिवृद्धये योगं स्तौति -- वेदेष्विति। वेदेषु सम्यगधीतेषु यज्ञेषु तपःसु च सम्यगनुष्ठितेषु दानेषु च सम्यग्दत्तेषु यत्पुण्यं तत्फलं चेति पुण्यफलं सर्वेषु समुच्चितेषु यत्प्रदिष्टं शास्त्रेषु तत्सर्वं योगी अत्येत्यतिक्रामति कार्यब्रह्मलोकं प्राप्नोतीत्यर्थः। किंकृत्वा इदं पूर्वोक्तमुपासनं विदित्वा ज्ञात्वानुष्ठाय च। ततश्च किमित्यत आह -- यत्स्थानं निर्विशेषं ब्रह्मोपैति प्राप्नोति च क्रमेणेत्यर्थः। आद्यं न तु केनचिन्निर्भितम्।,तदनेनाध्यायेन ध्येयस्तत्पदार्थो व्याख्यातः। अग्रिमेऽध्याये ज्ञेयं ब्रह्म व्याख्यास्यति।'),
('nilakantha-sc:source:9.1','Nīlakaṇṭha','gita.9.1','sa','commentary','।।9.1।।पूर्वाध्याये किंतद्ब्रह्मेत्यादिसप्तप्रश्न्यां अक्षरं ब्रह्म परममित्यादिना संक्षिप्य व्याख्यातायां तज्ज्ञानस्य पृथक्प्रयोजनाकाङ्क्षायां कर्मविद आधिभौतिकं धूमादिमार्गप्राप्यं स्थानमिति निरूपणेन प्राप्यप्रापकादिविभागो दर्शितः। तेन कर्माधिभूते व्याख्याते। तथा सूत्रान्तर्यामिणोरुपासकस्यार्चिरादिमार्गेण क्रममुक्तिस्थानप्राप्तिरित्युक्तं तेनाधिदैवाधियज्ञौ व्याख्यातौ। ओमित्येकाक्षरमित्यादिना अन्तकाले कथं ज्ञेयोऽसीत्यस्योत्तरं व्याख्यातम्। तदेवं ध्येयब्रह्मविद्या साङ्गा निरूपिता? परिशिष्टमाद्यं ज्ञेयब्रह्मविषयं प्रश्नद्वयं किं तद्ब्रह्म किमध्यात्ममिति तद्विवरणाय नवमोऽध्याय आरभ्यते। न केवलमर्चिरादिगतिप्राप्या कालान्तर एव मुक्तिरस्ति किंत्विहैव सद्योमुक्तिरस्तीति विशेषं वक्तुं श्रीभगवानुवाच -- इदं तु ते इति। इदं वक्ष्यमाणं तु पूर्वस्माद्ध्येयाद्विलक्षणं ज्ञेयं ते तुभ्यं गुह्यतममतिगोप्यं प्रवक्ष्यामि। अनसूयवे असूया गुणेषु दोषाविष्करणं तद्रहिताय। ज्ञानं ज्ञप्तिमात्रस्वरूपं ब्रह्म। विज्ञानेनानुभवेन सहितं नतु केवलं पारोक्ष्येण। यज्ज्ञानं ज्ञात्वा साक्षात्कृत्य अशुभात्संसारान्मोक्ष्यसे। अत्र यत्सप्तमादौज्ञानं तेऽहं सविज्ञानमिदं वक्ष्याम्यशेषतः इति प्रतिज्ञातं? यस्य च विज्ञानाय शाखाचन्द्रन्यायेनोपलक्षणीभूतं जगत्कारणं ब्रह्म तत्रैव निरूपितम्? यद्विज्ञानेऽधिकारसंपत्त्यर्थं तस्यैव सगुणस्योपासनमुक्तं तदिह सर्वशेषीभूतं ब्रह्म वक्तव्यमिति तथैव प्रतिजानीते वचनमात्रेणैवात्रापरोक्षं ज्ञानं जायत इति। तच्च तत्रैव व्युत्पादितं न विस्मर्तव्यम्।'),
('nilakantha-sc:source:9.2','Nīlakaṇṭha','gita.9.2','sa','commentary','।।9.2।।एतदेव स्तौति -- राजविद्येति। विद्यानां राजा इति राजविद्या अध्यात्मविद्या। गुह्यानां राजा इति राजगुह्यम्।राजदन्तादिषु परम् इत्युपसर्जनस्य परनिपातः। पवित्रं पावनम्। उत्तमं पूर्वापरदुरितनाशाश्लेषहेतुत्वात्प्रायश्चित्ताद्यपेक्षया श्रेष्ठम्। प्रत्यक्षावगमं प्रत्यक्षं नित्यापरोक्षं यत्प्रत्यगात्मवस्तु तदेव याथात्म्येनावगम्यतेऽनेनेति प्रत्यक्षावगमं? प्रत्यक्षेण सुखादिवद्गमो यस्येति वा। अस्मिन्पक्षे विज्ञानसहितमिति विशेषणस्य श्लोकान्तरस्थत्वान्न तेन पौनरुक्त्यदोषः। तर्हि अपूर्वत्वाभावान्निष्फलं स्यादत आह। धर्म्यं धर्मादनपेतम्। तथाहि क्षणमपि प्रत्यगात्माकारवृत्तौ सत्यां श्रूयतेक्षणमेकं क्रतुशतस्य चतुःसप्तत्या यत्फलं तद्वाप्नोति इति। तर्हि दुःसाध्यं स्यान्नेत्याह -- सुसुखं कर्तुमिति। कर्तुं संपादयितुमाविष्कर्तुं सुसुखमनायाससाध्यम्। अज्ञानापनयमात्रसिद्धत्वात्। तर्हि आशुविनाशिफलं चेत्। अव्ययं? वस्तुमात्रविषयत्वात्। अनन्तफलं नतु कर्मफलवन्नश्यति।'),
('nilakantha-sc:source:9.3','Nīlakaṇṭha','gita.9.3','sa','commentary','।।9.3।।तर्हि कुतएतज्ज्ञानं सर्वे न संपादयन्तीत्याह -- अश्रद्दधाना इति। स्पष्टार्थः श्लोकः।'),
('nilakantha-sc:source:9.4','Nīlakaṇṭha','gita.9.4','sa','commentary','।।9.4।।एवं स्तुत्यादिमुखीकृत्य यद्वक्तव्यं तदाह -- मयेति। मया इदं सर्वं जगत् ततं व्याप्तं उपादानत्वात् कनकेनेव कुण्डलादीनि। ननु प्रागेवैतदुक्तंअहं सर्वस्य जगतः प्रभवः प्रलयस्तथा इति। तथा चराजविद्या इत्यादिस्तुतिरस्थाने एव कृता स्यात्। वक्तव्यविशेषाभावादितिचेत्। अत्र ब्रूमः। यथायतो वा इमानि भूतानि जायन्ते। येन जातानि जीवन्ति। यत्प्रयन्त्यभिसंविशन्ति। तद्विजिज्ञासस्व। तद्ब्रह्मेति इति ज्ञेयस्य ब्रह्मणो लक्षणं जगज्जन्मादिहेतुत्वमुक्त्वा तस्यानुगमं अन्नादिशब्दशब्दितेषु विराडादिषु दर्शयतिअन्नाद्ध्येव खल्विमानि भूतानि जायन्ते प्राणाद्ध्येव इत्यादिना। तस्य निर्णयवाक्यं तुआनन्दाद्ध्येव खल्विमानि भूतानि जायन्ते इतिसैषा भार्गवी वारुणी विद्या इति तत्रैव विद्यायाः पर्यवसानाभिधानात्? एवमिहापि सप्तमेभूमिरापोऽनलो वायुः इत्यादिना सर्वभूतात्मकस्य विराजो जगज्जन्मादिहेतुत्वं प्रदर्श्य पश्चात्अहं सर्वस्य जगतः प्रभवः प्रलयस्तथा इत्यनेन मायाशबलेऽपि तत्प्रदर्श्य इदानीं शुद्धे प्रत्यगात्मन्येव तद्दर्शयति स्थूलारुन्धतीन्यायेन प्रतिपत्तिसौकर्यार्थमिति गम्यते। राजविद्येत्यादिना स्तुतत्वात्। यथा कश्चिद्दुर्लक्ष्यां सूक्ष्मामरुन्धतीं दिदर्शयिषुस्तत्समीपस्थां स्थूलां तारामरुन्धतीति ग्राहयति? प्रतिपद्यते चानेनैव क्रमेण प्रतिपत्ता? एवमिहापि कार्यकारणप्रतिपत्तिद्वारा अकार्यकारणस्य शुद्धस्य प्रतिपत्तिर्युक्ता। अतएव भगवान्भाष्यकारो मया ततमिदं सर्वमित्यत्र मया मम यः परो भावस्तेन ततं व्याप्तमिति व्याचख्यौ। नत्वहं सर्वस्य जगतः प्रभव इत्यत्र मम यः परो भावः स सर्वस्य जगतः प्रभव इति। सच भागवतः कारणात्मनः परो भावः परमानन्द एव तेनैव चेदं ततम्। आनन्दाद्ध्येवेत्युदाहृतश्रुतेस्तस्यैव जगदुपादानत्वेन तदीयसत्तास्फूर्तिभ्यां जगतो व्याप्तत्वात्।,अतएवाव्यक्तमूर्तिनेति विशेषणम्। मायाशबलं हि कारणं बुद्धिग्राह्यत्वात्करणगोचरः? शुद्धं हि बुद्धेः परत्वाकरणागोचर इति। किंभूताकारेणानन्दः परिणमत इत्यत आह -- मत्स्थानीति। मयि प्रत्यगानन्दे रज्ज्वां स्रक्सर्पदण्डधारादय इव सर्वभूतानि स्थितानि अतो मत्स्थानीत्युपचारादुच्यन्ते। अधिष्ठानाध्यस्तयोर्वास्तवसंबन्धायोगात्। एतदेवाह -- न चेति। नचाहं परमानन्दस्तेषु भूतेष्ववस्थितोऽस्मि घटादाविव मृत्। अपरिणामित्वादेव।'),
('nilakantha-sc:source:9.5','Nīlakaṇṭha','gita.9.5','sa','commentary','।।9.5।।एवमभ्युपगतमानन्दस्य जगद्विवर्ताधिष्ठानत्वं तदप्यपवदति -- न च मत्स्थानीति। अयंभावः -- अस्य द्वैतेन्द्रजालस्य यदुपादानकारणम्। अज्ञानं तदुपाश्रित्य ब्रह्मकारणमुच्यते इति वार्तिकोक्तेरज्ञानमेव जगत्कारणं तच्च तुच्छम्। अहं चासङ्गः। ततश्च तुच्छतरेण तत्कार्येण भूतसंघेन न ममासङ्गस्याधाराधेयभावसंबन्धोऽनिर्वचनीयोऽप्यस्ति। आवृतं हि रज्ज्वादिकमनिर्वचनीयेन सर्पादिना संबध्यते। अहं तु सर्वदानावृतः साक्षिरूपत्वात्तत्संबन्धशून्य इति न च मत्स्थानि भूतानीत्युक्तमिति। ननु साक्षिणस्तव ब्रह्मणो युवा सुखी चेति प्रतीत्येव भूतसंबन्धानुभवात्कथं न च मत्स्थानीत्युक्तिरित्याशङ्क्याह -- पश्य मे योगमैश्वरमिति। मे मम भूतैः सह योगं युक्तिघटनां पश्य। ऐश्वरं ईश्वरेण मायाविना निर्मितं गगने गन्धर्वनगरमिव। अतएव मम कारणशरीरस्यात्मा प्रत्यगानन्दे भूतभृदपि भूतस्थो न। चकारोऽप्यर्थे भिन्नक्रमश्च। खमिव गन्धर्वनगरभृदपि तत्स्थं न। तस्य तदाकारेण परिणामासंभवात्। एवंरूपोऽपि परानन्दरूपो ममात्मा स भूतभावनः भूतानां वृद्धिकरः।एतस्यैवानन्दस्यान्यानि भूतानि मात्रामुपजीवन्ति। को ह्येवान्यात्कः प्राण्याद्यदेष आकाश आनन्दो न स्यात् इत्यादिश्रुतिभ्यः। आकाशेऽव्याकृताख्ये स्वाधिष्ठानभूत आनन्दोऽनुस्यूतो न स्यात्तर्हि प्राणापानक्रियां कश्चिदपि न कुर्यात् कारणगतं जाड्यं कार्येऽपि स्यात्। आकाशे आनन्दानुबन्धे तु कारणस्य चेतनत्वात्कार्यमपि चेतनावत्स्यादिति श्रुत्यर्थः। बृहदारण्यकेऽपियदूर्ध्वं गार्गि दिवो यदवाक् पृथिव्या यदन्तरा द्यावापृथिवी इमे यद्भूतं च भवच्च भविष्यच्चेत्याचक्षत आकाश एव तदोतं च प्रोतं च इति मायाविनि सर्वस्योतप्रोतत्वमुक्त्वाकस्मिन्नु खल्वाकाश ओतश्च प्रोतश्च इत्यस्योत्तरम्एतस्मिन्खल्वक्षरे गार्गि आकाश ओतश्च प्रोतश्च इत्यस्थूलादिलक्षणस्याक्षरस्याकाशाधारत्वमुक्तम्। तस्माद्युक्तमुक्तमाकाशशरीरेण भगवता कारणोपाधिनिष्कृष्टचिन्मात्राभिप्रायेण ममात्मा भूतभावन इति।'),
('nilakantha-sc:source:9.6','Nīlakaṇṭha','gita.9.6','sa','commentary','।।9.6।।श्लोकद्वयोक्तेऽर्थे दृष्टान्तमाह -- यथेति। यथा लोके आकाशे स्थितो नित्यं सदा वायुः सर्वत्रगः परिमाणतश्च महान्? तथा सर्वाणि भूतानि सर्वगते मयि असंश्लेषेणैव स्थितानीत्येवमुपधारयेति प्राञ्चः। किंतद्ब्रह्मेति प्रश्नस्योत्तरमुक्तं अक्षरं परमं ब्रह्मेति। अक्षरसंज्ञं शुद्धस्त्वंपदार्थएव निरुपाधिकं ब्रह्मेत्युक्तम्। तत्र निरुपाधिकं ब्रह्म श्लोकद्वयेन व्याख्यातम्। इदानीं तस्याक्षराख्येन जीवेनाभेदं सदृष्टान्तमाह -- यथेति। वायुः सूत्रात्मावायुर्वै गोतम तत्सूत्रम् इतिश्रुतेः। सर्वत्रगतिसमष्टिलिङ्गत्वात्तस्य सर्वगतत्वम्। महानिति बाह्यवायुव्यावृत्त्यर्थम्। स यथा आकाशस्थितः अव्याकृताकाशे स्वकारणे स्थितः। नित्यमिति कालत्रयेऽपि तस्याकाशसंबन्ध उक्तः। सर्वाणि भूतान्युपाधिनिष्कृष्टत्वंपदार्थरूपी चेतनवर्गः। बहुत्वं लोकाभिप्रायेण। यथा कार्यं सर्वमुत्पत्तेः प्राक् नाशादूर्ध्वं मध्ये च स्वकारण एवाभेदेन तिष्ठति? एवं सर्वोऽपि जीववर्ग उपाध्युत्पत्तेः प्राक् तन्नाशादूर्ध्वं मध्ये वा घटाकाशो महाकाशादिव परस्माद्ब्रह्मणः कालत्रयेऽपि नातिरिच्यत इत्यर्थः। एतेन जीवब्रह्माभेदकथनेनस्वभावोऽध्यात्ममुच्यते इति यत्प्रागुक्तं ब्रह्मैव जीव इति तद्विवृतम्।'),
('nilakantha-sc:source:9.7','Nīlakaṇṭha','gita.9.7','sa','commentary','।।9.7।।नन्वेवमुपाधिरहितस्यैव ब्रह्मणि लयश्चेदुपाधेः का गतिरित्याशङ्क्याह -- सर्वेति। सर्वाणि भूतानि स्थावरजंगमशरीराणि मामिकां मम मायाविनः प्रकृतिं त्रिगुणात्मिकामपरां सूक्ष्मभूम्याद्यात्मिकां यान्ति प्रविशन्ति। कदा यान्ति कल्पक्षये। पुनश्च तान्येव भूतानि प्रकृतौ सुप्ताविव संस्कारात्मना स्थितानि एकतां गतानि कल्पादौ विसृजामि विविधरूपेण सृजाम्यहं कारणात्मा मायावी।'),
('nilakantha-sc:source:9.8','Nīlakaṇṭha','gita.9.8','sa','commentary','।।9.8।।एतदेवाह -- प्रकृतिमिति। एवमविद्यालक्षणां स्वां प्रकृतिमवष्टभ्य आश्रित्य तां विना केवलस्य स्रष्टृत्वासंभवात्। इमं भूतग्रामं पुनःपुनर्विविधं सृजामि। किंभूतम्। प्रकृतेर्वशात्स्वभाववशात्। अवशं रागद्वेषाद्यधीनम्।'),
('nilakantha-sc:source:9.9','Nīlakaṇṭha','gita.9.9','sa','commentary','।।9.9 -- 9.10।।ननु विषमां सृष्टिं कुर्वतस्तव वैषम्यनैर्घृण्ये स्यातामत आह -- न चेति। तानि विषमसृष्टिरूपाणि कर्मामि मां न निबध्नन्ति। तत्र हेतुः उदासीनवदासीनमिति। यथा पर्जन्यो बीजविशेषेषु रागं केषुचिद्द्वेषं चाकृत्वा उदासीनः सन् वर्षति एवमीश्वरोऽपि पुण्यवत्सु रागं पापिषु द्वेषं चाकुर्वञ्जगत्सृजति। तत्तदसाधारणकर्मबीजवशात्ते ते विभिन्नं फलं प्राप्नुवन्तीति नेश्वरवैषम्यादीत्यर्थः। ननु विसृजामि। उदासीनवदासीनमिति परस्परविरुद्धमुच्यत इत्याशङ्क्याह -- मयेति। मया कूटस्थेन अध्यक्षेण अयस्कान्तकल्पेन प्रवर्तकेन प्रकृतिश्चराचरं जगत् सूयते उत्पादयति। अनेनाध्यक्षत्वेनैव हेतुना हे कौन्तेय? जगद्विपरिवर्तते जन्माद्यवस्थासु भ्रमति। अयस्कान्तवदहमुदासीनश्च सृष्टिप्रवर्तकश्च भवामीति भावः। तथा च मन्त्रवर्णःएको देवः सर्वभूतेषु गूढः सर्वव्यापी सर्वभूतान्तरात्मा। कर्माध्यक्षः सर्वभूताधिवासः साक्षी चेता केवलो निर्गुणश्च इति एकस्यैव देवस्य सर्वाध्यक्षत्वं साक्षित्वं च प्रतिपादयति।'),
('nilakantha-sc:source:9.10','Nīlakaṇṭha','gita.9.10','sa','commentary','।।9.9 -- 9.10।।ननु विषमां सृष्टिं कुर्वतस्तव वैषम्यनैर्घृण्ये स्यातामत आह -- न चेति। तानि विषमसृष्टिरूपाणि कर्मामि मां न निबध्नन्ति। तत्र हेतुः उदासीनवदासीनमिति। यथा पर्जन्यो बीजविशेषेषु रागं केषुचिद्द्वेषं चाकृत्वा उदासीनः सन् वर्षति एवमीश्वरोऽपि पुण्यवत्सु रागं पापिषु द्वेषं चाकुर्वञ्जगत्सृजति। तत्तदसाधारणकर्मबीजवशात्ते ते विभिन्नं फलं प्राप्नुवन्तीति नेश्वरवैषम्यादीत्यर्थः। ननु विसृजामि। उदासीनवदासीनमिति परस्परविरुद्धमुच्यत इत्याशङ्क्याह -- मयेति। मया कूटस्थेन अध्यक्षेण अयस्कान्तकल्पेन प्रवर्तकेन प्रकृतिश्चराचरं जगत् सूयते उत्पादयति। अनेनाध्यक्षत्वेनैव हेतुना हे कौन्तेय? जगद्विपरिवर्तते जन्माद्यवस्थासु भ्रमति। अयस्कान्तवदहमुदासीनश्च सृष्टिप्रवर्तकश्च भवामीति भावः। तथा च मन्त्रवर्णःएको देवः सर्वभूतेषु गूढः सर्वव्यापी सर्वभूतान्तरात्मा। कर्माध्यक्षः सर्वभूताधिवासः साक्षी चेता केवलो निर्गुणश्च इति एकस्यैव देवस्य सर्वाध्यक्षत्वं साक्षित्वं च प्रतिपादयति।'),
('nilakantha-sc:source:9.11','Nīlakaṇṭha','gita.9.11','sa','commentary','।।9.11।।एवंभूतं मां सन्तं मूढाः अवजानन्ति। यतो मानुषीं तनुमाश्रितं मनुष्यदेहेन व्यवहरन्तम्। मम परं प्रकृष्टं भावं तत्त्वमजानन्तः भूतानां महेश्वरं मामवजानन्तीति संबन्धः।'),
('nilakantha-sc:source:9.12','Nīlakaṇṭha','gita.9.12','sa','commentary','।।9.12।।मदवज्ञानाच्च ते मोघाशाः वृथैव आशा आशिषो येषां ते मोघाशाः। तथा मोघकर्माणो निष्फलोद्योगाः। मोघज्ञानाः निष्फलज्ञानाः। यतो विचेतसो निर्विवेकाः। यतो राक्षसीमासुरीं च रजस्तमःप्रधानां मोहिनीं मोहकरीं प्रकृतिं श्रिताः। छिन्धि भिन्धि पिब खाद परस्वमपहरेत्येवंवादशीलाः क्रूरकर्माणो भवन्तीत्यर्थः।'),
('nilakantha-sc:source:9.13','Nīlakaṇṭha','gita.9.13','sa','commentary','।।9.13।।तथा ये महात्मानोऽक्षुद्रचित्ताः। तु पूर्वेभ्योऽत्यन्तं विलक्षणाः मां भजन्ति। यतो दैवीं प्रकृतिं सत्वप्रधानामाश्रिताः। अनन्यमनसः एकाग्रचेतसः। किं गतानुगतिकतया दम्भेन वा भजन्ति। न। किं तर्हि मां भूतादि सर्वभूतकारणमव्ययं ज्ञात्वा मत्वा भजन्ति।'),
('nilakantha-sc:source:9.14','Nīlakaṇṭha','gita.9.14','sa','commentary','।।9.14।।भजनस्वरूपमाह -- सततमिति। यतन्तः इन्द्रियोपसंहारशमदमादिषु प्रयतमानाः दृढान्यहिंसादीनि व्रतानि येषां ते दृढव्रताः नमस्यन्तश्च मां हृदयेशं प्रतिमादिरूपं वा भक्त्या। नित्ययुक्ताः नित्यमवहिताः सन्त उपासते।'),
('nilakantha-sc:source:9.15','Nīlakaṇṭha','gita.9.15','sa','commentary','।।9.15।।ज्ञानयज्ञेन निर्विकल्पसमाधिना पातञ्जलाः। एकत्वेन अहमेव भगवान्वासुदेव इत्यभेदेनौपनिषदाः। पृथक्त्वेन अयमीश्वरो ममस्वामीति बुद्ध्या प्राकृताः। अन्ये पुनर्बहुधा बहुप्रकारं विश्वतोमुखं सर्वैर्द्वारैर्यत्किंचिद्दृष्टं तद्भगवत्स्वरूपमेव? यच्छ्रुतं तत्तन्नामैव? यद्दत्तं भुक्तं वा तत्तदर्पितमेवेत्येवं विश्वतोमुखं यथा स्यात्तथा मामुपासते।'),
('nilakantha-sc:source:9.16','Nīlakaṇṭha','gita.9.16','sa','commentary','।।9.16।।इदमेवोपासनं विवृणोति -- अहमिति। क्रतुः संकल्पो देवताध्यानरूपः। यज्ञः श्रौतः स्मार्तश्च देवतोद्देशेन द्रव्यत्यागः। स्वधा पितृ़णामन्नम्। औषधं मनुष्याणामन्नम्। मन्त्रो येन दीयते सः। आज्यं हविः। अग्निः। हुतं प्रक्षेपक्रिया। इदं सर्वं यस्मादहमेवातस्तेषां विश्वतोमुखमुपासनं युक्ततरमित्यर्थः।'),
('nilakantha-sc:source:9.17','Nīlakaṇṭha','gita.9.17','sa','commentary','।।9.17।।धाता कर्मफलानां विकर्ता। वेद्यं वेदितव्यं ब्रह्म। पवित्रं पावनं तप आदिकम्।'),
('nilakantha-sc:source:9.18','Nīlakaṇṭha','gita.9.18','sa','commentary','।।9.18।।गतिर्मुक्तिप्राप्यं स्थानम्। भर्ता कर्मफलदानेन पोषकः। प्रभुः अन्तर्यामी। साक्षी कृताकृतावेक्षकः। निवसन्त्यस्मिन्निति निवास आश्रयो यजमानादिः। शरणं रक्षकः। सुहृदुपकारमनपेक्ष्योपकर्ता। प्रभव उत्पत्तिस्थानम्। प्रलयो लयस्थानम्। स्थानं स्थितिस्थानम्। निधानं कर्मफलसमर्पणस्थानम्। कालान्तरे फलप्रसवार्थं बीजं प्ररोहकारणं प्ररोहधर्मिणाम्। अव्ययं यावत्संसारभावित्वात्।'),
('nilakantha-sc:source:9.19','Nīlakaṇṭha','gita.9.19','sa','commentary','।।9.19।।अहं तपामि आदित्यो भूत्वा। अहं वर्षं वृष्टिस्तां निगृह्णामि अष्टसु मासेषु कैश्चिद्रश्मिभिः। उत्सृजामि च चतुर्षुमासेषु कैश्चिदिति। अमृतं जीवनं मृत्युर्मरणम्। अमृतं देवान्नं वा। सत् साधु? असत् असाधु। एतत्सर्वमहमेव। अतस्तेषां विश्वतोमुखं मम भजनं कुर्वतां सर्वरूपेणाहमनुग्रहं करोमीति भावः।'),
('nilakantha-sc:source:9.20','Nīlakaṇṭha','gita.9.20','sa','commentary','।।9.20।।ये पुनरुक्तेषु प्रकारेष्वन्यतमेनापि मां न भजन्ते ते केवलकर्मठाः कां गतिं प्राप्नुवन्तीति शृणु -- त्रैविद्या इति। तिस्रः ऋग्यजुःसामरूपाः विद्या येषां ते त्रिविद्याः त एव त्रैविद्याः सोमपाः सोमपायिनो याज्ञिकाः यज्ञैर्मामिष्ट्वा स्वर्गतिं फलं प्रार्थयन्ते। दिव्यानप्राकृतान्संकल्पमात्रोपनतान्दुःखासंभिन्नान्।');
INSERT INTO commentary_fts (unit_id,author,canonical_ref,language,content_type,content) VALUES
('nilakantha-sc:source:9.21','Nīlakaṇṭha','gita.9.21','sa','commentary','।।9.21।।त्रयी वेदत्रयी तस्यामुक्तं धर्मं त्रयीधर्मं काम्ययज्ञं कामकामाः विषयकामुकाः गतागतं यातायातं सातत्येन लभन्ते। तथाच श्रुतिःप्लवा ह्येते अदृढा यज्ञरूपा अष्टादशोक्तमवरं येषु कर्म। एतच्छ्रेयो येऽभिनन्दन्ति मूढा जरामृत्युं ते पुनरेवापि यान्ति इति। अष्टादशेति षोडशर्त्विजः यजमानः पत्नी चेति द्वौ।'),
('nilakantha-sc:source:9.22','Nīlakaṇṭha','gita.9.22','sa','commentary','।।9.22।।एवं कर्मिणामावृत्तिं फलं चोक्त्वा भक्तानामपि मद्भजनेनैव सर्वसिद्धिरित्याह -- अनन्या इति। नास्ति अन्य उपास्यो येषाम्। अहमेव भगवान्वासुदेव इत्यभेदेन चिन्तयन्त इत्यर्थः। ये जनाः पर्युपासते परितः साकल्येन कात्स्न्र्येनाद्वैतदृष्ट्येत्यर्थः। उपासते तेषां नित्याभियुक्तानां सतताभियोगिनां। योगः अप्राप्तस्यान्नादेर्योगभूमिकाया वा प्रापणं। क्षेमः तस्यैव प्राप्तस्य संरक्षणं। तद्वयमहमेव वहामि निर्वहामि। तैरन्नाद्यर्थं वा योगभूमिषूर्ध्वोर्ध्वभूमिलाभार्थं वा चिन्ता न कर्तव्येत्यर्थः। अनन्यचेतसां तेषां मदभिन्नत्वात्सर्वं सेत्स्यतीत्यर्थः। तथा चोक्तंज्ञानी त्वात्मैव मे मतम् इति।'),
('nilakantha-sc:source:9.23','Nīlakaṇṭha','gita.9.23','sa','commentary','।।9.23।।अविधिपूर्वकं विधिरभेदबुद्धिस्तद्राहित्यादविधिपूर्वकत्वं तदीयभजनस्य।'),
('nilakantha-sc:source:9.24','Nīlakaṇṭha','gita.9.24','sa','commentary','।।9.24।।हि यतः सर्वयज्ञानामहमेव सर्वदेवतारूपेण भोक्ता प्रभुः फलदाता च। एवं सति ते मां प्रत्यगभिन्नं तत्त्वेन याथातथ्येन न जानन्ति अतश्च्यवन्ति ज्ञाननिष्ठामलब्ध्वा संसारगर्ते पतन्ति।'),
('nilakantha-sc:source:9.25','Nīlakaṇṭha','gita.9.25','sa','commentary','।।9.25।।सर्वे भक्ता यथाभजनं प्राप्नुवन्ति स्वाराध्यसांनिध्यमित्याह -- यान्तीति। भूतार्थमिज्या येषां ते भूतेज्याः।'),
('nilakantha-sc:source:9.26','Nīlakaṇṭha','gita.9.26','sa','commentary','।।9.26।।मद्भक्तिरतिसुकरा देवतान्तरभक्तिस्तु बहुवित्तव्ययायाससाध्येत्याशयेनाह -- पत्रमिति। भक्तिरेव केवलं ममापेक्षिता नान्यदिति भावः। भक्त्युपहृतं भक्त्या समर्पितम्।'),
('nilakantha-sc:source:9.27','Nīlakaṇṭha','gita.9.27','sa','commentary','।।9.27।।अतः सर्वं मदर्पणं कुर्वित्याह -- यदिति। यत्करोषि गमनादिकं तद्भगवत एव प्रदक्षिणादिकं करोमीति मत्प्रीत्यर्थमेव तदर्पणं कुर्विति। एवं वचनादिष्वपि नामकीर्तनादिदृष्ट्या ऊह्यम्।'),
('nilakantha-sc:source:9.28','Nīlakaṇṭha','gita.9.28','sa','commentary','।।9.28।।एवं कुर्वतः फलमाह -- शुभाशुभेति। शुभाशुभफलैरिष्टानिष्टफलैः कर्मरूपैर्बन्धनैरेवं कुर्वन् त्वं मोक्ष्यसे भगवदर्पणबुद्ध्या यत्किञ्चित्कर्म कुर्वतः कर्मलेपो नास्तीत्यर्थः। अयमेवोक्तलक्षणः कर्मफलसंन्यासरूपो,मार्गस्तत्र युक्तात्मा समाहितचित्तः सन् विमुक्तः कर्मबन्धनैर्विमुक्तः सन् मां सर्वेषां प्रत्यगात्मानमुपैष्यसि।'),
('nilakantha-sc:source:9.29','Nīlakaṇṭha','gita.9.29','sa','commentary','।।9.29।।यतो भक्तानेवानुगृह्णाति नेतरानित्यतो रागद्वेषवान्भगवानित्यत आह -- समोऽहमिति। यथाग्निः रागादिशून्योऽपि समीपस्थानामेव शीतं नाशयति न दूरस्थानां तद्वत्सर्वत्र समोऽप्यहं शरणागतानामेव बन्धं नाशयामि नान्येषामित्यर्थः। अतो मम न रागद्वेषाविति भावः। मयि ते तेषु चाप्यहम्। भक्ता अनन्यशरणतया मय्येव वर्तन्ते अहमपि तेष्वेव वर्ते। अभक्तचित्तानां रागाद्याक्रान्तत्वेन तत्र मम विशेषतोऽभिव्यक्तिर्नास्तीति भावः।'),
('nilakantha-sc:source:9.30','Nīlakaṇṭha','gita.9.30','sa','commentary','।।9.30।।भक्तेर्माहात्म्यमाह -- अपिचेदिति। अत्यन्तपापिष्ठोऽपि मां यद्यनन्यचेताः सन् भजते तथापि स साधुरेव मन्तव्यः। हि यतः स सम्यग्व्यवसितः सम्यग्वृत्तः।'),
('nilakantha-sc:source:9.31','Nīlakaṇṭha','gita.9.31','sa','commentary','।।9.31।।सम्यग्व्यवसितत्वादेव क्षिप्रं धर्मात्मा भवति। शान्तिं च शश्वन्निगच्छति प्राप्नोति। हे कौन्तेय? त्वमेव मदाज्ञया प्रतिजानीहि प्रतिज्ञां कुरु मे मम भगवतो हरेर्भक्तो न नश्यतीति।'),
('nilakantha-sc:source:9.32','Nīlakaṇṭha','gita.9.32','sa','commentary','।।9.32।।किं च हे पार्थ? हि प्रसिद्धं मां व्यपाश्रित्य आश्रित्य येऽत्यन्तं पापयोनयः स्त्र्यादयस्तेऽपि परां गतिं यान्ति।'),
('nilakantha-sc:source:9.33','Nīlakaṇṭha','gita.9.33','sa','commentary','।।9.33।।ब्राह्मणादयः पुनः पुण्याः मदाश्रयेण परां गतिं यान्तीत्यत्र किं चित्रम्। अतस्त्वमिमं मर्त्यलोकं अनित्यं नश्वरं असुखं सुखलेशहीनं प्राप्य मां परमात्मानं भजस्व। लोकान्तरे भजनं न भविष्यतीत्यर्थः। तथा च श्रुतिःइह चेदवेदीदथ सत्यमस्ति न चेदिहावेदीन्महती विनष्टिः इति।'),
('nilakantha-sc:source:9.34','Nīlakaṇṭha','gita.9.34','sa','commentary','।।9.34।।भजनप्रकारं दर्शयति -- मन्मना इति। मय्येव मनो यस्य न पुत्रादौ स मन्मनाः। ममैव भक्तो न राजादेर्धनाद्यर्थं स मद्भक्तः। मद्याजी मदर्थमेव यजते न स्वर्गाद्यर्थं स मद्याजी तादृशो भव। मामेव नमस्कुरु शरणं व्रज नत्वन्यान्। एवमनेन प्रकारेण युक्त्वा योगं कृत्वा मामेवात्मानं सर्वान्तरं एष्यसि प्राप्स्यसि। अभेदेन घटाकाश इव महाकाशम्। यतो मत्परायणः अहमेव सर्वोपाधिशून्यश्चिदात्मा परं सर्वोत्कृष्टमयनं प्राप्यं यस्य स मत्परायणः। तथा च श्रूयतेयथा नद्यः स्यन्दमानाः समुद्रेऽस्तं गच्छन्ति नामरूपे विहाय। तथा विद्वान्नामरूपाद्विमुक्तः परात्परं पुरुषमुपैति दिव्यम् इति।'),
('nilakantha-sc:source:10.1','Nīlakaṇṭha','gita.10.1','sa','commentary','।।10.1।।सप्तमे त्वंपदवाच्योऽर्थो निरूपितः? तदुपासनाच्च क्रममुक्तिरित्यष्टमे प्रोक्तं? नवमे तत्पदलक्ष्यार्थ उक्तस्तत्प्राप्तये च विश्वतोमुखं सर्वत्र भगवद्भावभावनात्मकं भगवद्भजनमुक्तम्? तद्रागद्वेषकलुषितमनसामशक्यमिति मन्वानो भगवांस्तत्सिद्धये स्वविभूतीः केषुचिदेव पदार्थेषु भगवद्बुद्धिविधानार्थास्तावद्दर्शयति दशमे। तत्फलभूतं विश्वतोमुखस्योपासनं तेन च विश्वरूपदर्शनमेकादशे। द्वादशे पुनस्तत्पदलक्ष्यस्याव्यक्तस्योपासनं तदुपासकलक्षणानि चोक्त्वा उपासनाकाण्डं तत्पदार्थशोधनार्थं समापयिष्यति तत्र वात्सल्यात्स्वयमेव श्रीभगवानुवाच -- भूय एवेति। हे महाबाहो? भूयः प्रागुक्तमपि पुनर्मे परमं निरतिशयवस्तुनः प्रकाशकं वचः शृणु। प्रीयमाणाय अमृतपानादिवन्मद्वचनात्प्रीतिमनुभवते वक्ष्यामि। हितकाम्यया तव हितेच्छया।'),
('nilakantha-sc:source:10.2','Nīlakaṇṭha','gita.10.2','sa','commentary','।।10.2।।दुर्ज्ञेयत्वाच्च मत्स्वरूपस्याहं त्वां ब्रवीमीत्याह -- न मे इति। प्रभवं प्रकृष्टं भवमैश्वर्यं वियदादिसृष्टिसामर्थ्यं न विदुः। तत्र हेतुराह अहमिति। अयं भावः -- देहोत्पत्त्यनन्तरं हि देवादीनां बुद्ध्यादिलाभो न चार्वाचीनैर्बुद्ध्यादिभिः स्वोत्पत्तिप्राक्कालीनोऽर्थः परिच्छेत्तुं शक्यत इति। पदार्थः स्पष्टः।'),
('nilakantha-sc:source:10.3','Nīlakaṇṭha','gita.10.3','sa','commentary','।।10.3।।कस्तर्हि त्वां वेत्तीत्यत आह -- य इति। योऽसंमूढः स मां वेत्ति। स एव सर्वपापैः प्रमुच्यत इति संबन्धः। जडाजडयोर्बुद्ध्यात्मनोरेकीभावेनान्योन्याध्यासलक्षणेन मूढः संमूढस्तद्विपरीतोऽसंमूढस्तत्त्वज्ञानेन बाधिताध्यासः स एवात्मवित्त्वादितरस्य जनिमनुभवन् मां प्रत्यगात्मानं लोकमहेश्वरमनादिं आदिः कारणं तच्छून्यमतएवाजमजातं वेत्ति स सर्वैः कृतैः क्रियमाणैर्वा पापैः प्रमुच्यते मर्त्येषु मध्ये।'),
('nilakantha-sc:source:10.4','Nīlakaṇṭha','gita.10.4','sa','commentary','।।10.4।।मम महेश्वरत्वादेव मत्तो बुद्ध्यादयो भवन्तीत्याह -- बुद्धिरिति। बुद्धिरन्तःकरणस्य सूक्ष्मार्थावबोधने सामर्थ्यम्? ज्ञानमात्मानात्मादिपदार्थावबोधः। असंमोहः प्रत्युत्पन्नेषु बोद्धव्येष्वव्याकुलतया विवेकपूर्विका प्रतिपत्तिः। क्षमा आकृष्टस्य ताडितस्य वाऽविकृतचित्तता। सत्यं प्रमाणेनावगतस्यार्थस्य यथार्थत्वेन भाषणम्। दमो बाह्येन्द्रियनियमः। शमो मनोनिग्रहः। सुखमाह्लादः। दुःखं तापः। भव उत्पत्तिः। भावः सत्ता अभावस्तद्विपर्ययः। भयं त्रासः। अभयमेव च तद्विपरीतम्।'),
('nilakantha-sc:source:10.5','Nīlakaṇṭha','gita.10.5','sa','commentary','।।10.5।।अहिंसा प्राणिनामपीडा। समता मित्रामित्रादौ समचित्तता। तुष्टिः संतोषो लब्धे पर्याप्तबुद्धिः। तप इन्द्रियसंयमपूर्वकं शरीरपीडनम्। दानं यथाशक्ति संविभागः। यशो धर्मनिमित्ता कीर्तिः। अयशोऽधर्मनिमित्ता अकीर्तिः। एते बुद्ध्यादयो विंशतिर्भावा मत्त एव प्राणिनां भवन्ति। पृथग्विधाः प्रत्येकं नानाप्रकाराः। तत उत्तमगुणलाभायाहमेव त्वया शरणीकरणीय इति भावः।'),
('nilakantha-sc:source:10.6','Nīlakaṇṭha','gita.10.6','sa','commentary','।।10.6।।एतदेव शिष्टाचारप्रदर्शनेन द्रढयति -- महर्षय इति। सप्त भृग्वाद्याश्चत्वारः सनकादयश्च पूर्वे प्रसिद्धा महर्षय इति संबन्धः। तथा मनवश्चतुदर्श प्रसिद्धाः। ते सर्वे मानसा हिरण्यगर्भरूपस्य मम मनस एवोद्भूता अयोनिजा जाता उत्पन्नाः। इमाः प्रजाश्चतुर्विधा अयं लोकश्च तदाधारभूतः तदुभयं येषां यत्संबन्धि संततिर्येषां संततिरित्यर्थः। यद्ववा येषामिति षष्ठी पञ्चम्यर्थे। येभ्य इमाः प्रजा अयं लोकश्च जाता इत्यर्थः। तेऽपि मद्भावा मय्येव भावो मनो येषां ते। प्रसिद्धमहिमानोऽप्येते यतो मामेवोपासतेऽतस्त्वमपि मामुपास्वेति भावः।'),
('nilakantha-sc:source:10.7','Nīlakaṇṭha','gita.10.7','sa','commentary','।।10.7।।उपास्तावधिकारिणमाह -- एतामिति। एतां वक्ष्यमाणां विभूतिं योगं च विश्वतोमुखे भगवति मनःसमाधानं यस्तत्त्वतो वेत्ति सम्यगनुष्ठातुं ज्ञातुं च समर्थो भवति सोऽविकम्पेनाचलेन निर्विकल्पकेन षष्ठाध्यायोक्तेन योगेन मद्विषयेण समाधिना युज्यते ततश्च कृतकृत्यो भवति। नात्र संशय इति प्रवृत्त्यतिशयार्थमुच्यते। भगवद्वचसि संशयासंभवात्।'),
('nilakantha-sc:source:10.8','Nīlakaṇṭha','gita.10.8','sa','commentary','।।10.8।।उपासनास्वरूपमाह द्वाभ्याम् -- अहमिति। बुधा मां प्रत्यगात्मानमिति मत्वा भजन्ते। इति कथम्। अहमेव सर्वस्य जगतः प्रभव उत्पत्तिः। मत्तो मदनुग्रहं प्राप्यैव सर्वं बुद्ध्यादिकं स्वस्वकार्याय प्रवर्तते। अहमेव,जगतः कर्तान्तर्यामी चेत्यहंग्रहेणात्मानमुपासीतेति भावः। भावसमन्विताः भावनायुक्ताः एतच्चोत्तरार्थम्।'),
('nilakantha-sc:source:10.9','Nīlakaṇṭha','gita.10.9','sa','commentary','।।10.9।।एवं ध्याने भावनाप्रकारमुक्त्वा व्युत्थाने तमाह -- मच्चित्ता इति। अहमेव चित्ते येषां ते मच्चित्ताः। तथाहमेव गतो विद्यमानो येषु ते मद्गतास्तथाविधाः प्राणा इन्द्रियाणि येषां ते मद्गतप्राणाः। चित्तेनेन्द्रियैर्वा यद्गृह्यते तत्सर्वं प्रत्यगात्मा वासुदेव इति भावयन्त इत्यर्थः। इममेवार्थं परस्परं बोधयन्तः श्रुतियुक्तिप्रदर्शनेन समानानां समुदायं ज्ञापयन्तः। कथयन्तश्च शिष्यान्प्रति। तुष्यन्ति तेनैव ज्ञानेन न तु मिष्टान्नादिना। रमन्ति च तत्रैव नतु स्त्र्यादावित्यर्थः।'),
('nilakantha-sc:source:10.10','Nīlakaṇṭha','gita.10.10','sa','commentary','।।10.10।।उपासनायाः फलमाह -- तेषामिति। सततयुक्तानां नित्योत्साहवताम्। प्रीतिः प्रेमा तत्पूर्वकं भजतां सेवमानानां तेभ्यो ददामि तं बुद्धियोगं ज्ञानरूपं योगं समाधिम्। ज्ञाननिष्ठामित्यर्थः। तां ददामि येन यया निष्ठया ते मामुपयान्ति समुद्रमिव नद्योऽभेदेन प्रविशन्ति।'),
('nilakantha-sc:source:10.11','Nīlakaṇṭha','gita.10.11','sa','commentary','।।10.11।।किं च तेषां भक्तानामुपर्यनुकम्पार्थं न स्वप्रयोजनसिद्ध्यर्थं राजवत्। बुद्धियोगप्रदानेनाज्ञानजमविवेकादुत्थितं मिथ्याप्रत्ययलक्षणं मोहान्धकारं तमोनामकं सर्वानर्थनिदानमूलाज्ञाननाशेन नाशयामि। आत्मभावस्थ आत्मनो भावोऽन्तःकरणगृहं तत्स्थः। ज्ञानरूपेण दीपेन। भास्वता प्रबलेन। अयं भावः -- तत्त्वमसीति वाक्यजा ब्रह्माकारान्तःकरणवृत्तिः स्वोत्पत्तये श्रवणमननध्यानानि शमादीनि कर्माणि चापेक्षते। यथा दीपः स्वोत्पत्तये तैलवर्त्यग्न्यादीन्। उत्पन्ना तु तमोनाशेन स्वविषयप्रकाशनार्थं प्रत्ययावृत्तिलक्षणं प्रसंख्यानं च कर्मभिरुपकारं वा नापेक्षते। नहि ज्ञाते घटे तदाकारप्रत्ययावृत्तिर्वा कर्मापेक्षा वा तज्ज्ञानदार्ढ्यायापेक्षते। प्रमाणव्याप्तिमात्रसापेक्षत्वात् ज्ञानस्य। तस्माद्ये उत्पन्नज्ञानानामपि प्रसंख्यानापेक्षां कर्मभिरुपकारापेक्षां च वदन्ति ते बलादेव मोक्षस्य कृतकतामनित्यतां च प्रार्थयन्त इति दिक्।'),
('nilakantha-sc:source:10.12','Nīlakaṇṭha','gita.10.12','sa','commentary','।।10.12 -- 10.13।।एवं एतां विभूतिं योगं चेत्यादिना विभूतिज्ञानस्य फलोदर्कं श्रुत्वा तत्प्राप्त्युत्सुकः प्रथमं स्तुत्या भगवन्तमावर्जयन्नर्जुन उवाच -- परमिति। परं ब्रह्म नत्वपरमुपास्यम्।तदेव ब्रह्म त्वं विद्धि नेदं यदिदमुपासते इति श्रुतेः। परं धाम ज्योतिः नत्वपरं वृत्तिरूपं ज्ञानम्। एतस्यह्रीर्धीर्भीरित्येतत्सर्वं मन एव इति श्रुतेर्वृत्तिरूपत्वात्। परमं पवित्रं न तु तीर्थादिवदपरमं भवान्। तत्र मानमाह -- पुरुषमिति सार्धेन। पुरुषं देहान्तरस्थम्। शाश्वतं नित्यं। दिव्यं दिवि हार्दाकाशे आविर्भूतम्। आदिदेवं सूत्रात्मनोऽप्याद्यम्। अतएव अजं विभुं व्यापकम्। त्वां ऋषय आहुरिति संबन्धः।'),
('nilakantha-sc:source:10.13','Nīlakaṇṭha','gita.10.13','sa','commentary','।।10.12 -- 10.13।।एवं एतां विभूतिं योगं चेत्यादिना विभूतिज्ञानस्य फलोदर्कं श्रुत्वा तत्प्राप्त्युत्सुकः प्रथमं स्तुत्या भगवन्तमावर्जयन्नर्जुन उवाच -- परमिति। परं ब्रह्म नत्वपरमुपास्यम्।तदेव ब्रह्म त्वं विद्धि नेदं यदिदमुपासते इति श्रुतेः। परं धाम ज्योतिः नत्वपरं वृत्तिरूपं ज्ञानम्। एतस्यह्रीर्धीर्भीरित्येतत्सर्वं मन एव इति श्रुतेर्वृत्तिरूपत्वात्। परमं पवित्रं न तु तीर्थादिवदपरमं भवान्। तत्र मानमाह -- पुरुषमिति सार्धेन। पुरुषं देहान्तरस्थम्। शाश्वतं नित्यं। दिव्यं दिवि हार्दाकाशे आविर्भूतम्। आदिदेवं सूत्रात्मनोऽप्याद्यम्। अतएव अजं विभुं व्यापकम्। त्वां ऋषय आहुरिति संबन्धः।'),
('nilakantha-sc:source:10.14','Nīlakaṇṭha','gita.10.14','sa','commentary','।।10.14।।व्यक्तिं प्रभवम्।'),
('nilakantha-sc:source:10.15','Nīlakaṇṭha','gita.10.15','sa','commentary','।।10.15।।हे भूतभावन भूतानां भावक।'),
('nilakantha-sc:source:10.16','Nīlakaṇṭha','gita.10.16','sa','commentary','।।10.16।।एवं स्तुत्वात्मनो बुभुत्सितमाह -- वक्तुमिति।'),
('nilakantha-sc:source:10.17','Nīlakaṇṭha','gita.10.17','sa','commentary','।।10.17।।योग ऐश्वर्यं तद्वन् हे योगिन्? त्वां कथं चर्मचक्षुषा विद्यां न कथमपीति विश्वरूपदर्शनस्य दौर्लभ्यं मन्वानः कतिपयेष्वेव स्थानेषु भगवन्तं चिन्तयिष्यामि विश्वरूपदर्शनेऽधिकारसिद्ध्यर्थमित्याशयेनाह -- केष्विति।'),
('nilakantha-sc:source:10.18','Nīlakaṇṭha','gita.10.18','sa','commentary','।।10.18।।योगं वैश्वरूप्यम्। विभूतिं ध्यानालम्बनम्। अमृतं अमृतस्य मोक्षस्य साधनम्।'),
('nilakantha-sc:source:10.19','Nīlakaṇṭha','gita.10.19','sa','commentary','।।10.19।।अत्रोत्तरं श्रीभगवानुवाच -- हन्तेति। हन्त इदानीम्। हन्तेत्यनुमतौ वा। दिव्याः पुराणान्तरेष्वपि श्रेष्ठत्वेन प्रसिद्धाः या आत्मविभूतयस्ताः कथयामीति योजना। प्राधान्यत इति। योगोपकारित्वेन विभूतय इह प्राधान्येन? योगस्तु संक्षेपेणैवोच्यते। तस्याग्रे वक्ष्यमाणत्वादिति भावः। अन्यथा योगं विभूतिं च कथयेति पुष्टे विभूतिमात्रकथनेनानवहितचित्तत्वं भगवतः स्यात्। नास्त्यन्तो विस्तरस्य मे विभूतिनामिति विपरिणामेनानुषञ्जनीयम्।'),
('nilakantha-sc:source:10.20','Nīlakaṇṭha','gita.10.20','sa','commentary','।।10.20।।संक्षेपेण योगमाह -- अहमिति। हे गुडाकेश हे जितनिद्र घनकेशेति वा। अहं वासुदेव आत्मा अततीत्यात्मा व्यापकः। अतएव सर्वेषां भूतानामाशयः एकीभावस्थानं जलानामिव कासारो जलाशयस्तद्वदहं सर्वभूताशयः। स्थितः अचलः।खर्परे शरि वा विसर्गलोपो वक्तव्यः इति वार्तिकेन पक्षे विसर्गलोपः। भाष्ये तु सर्वेषां भूतानामाशयेऽन्तर्हृदि स्थित इति व्याख्यातम्। सर्वभूताशयत्वादेवाहं आदिर्जन्मकारणम्। मध्यं स्थितिकारणम्। भूतानामन्तः लयस्थानम्। सर्वमिदं ब्रह्माण्डं मय्येवास्तीति भावः।'),
('nilakantha-sc:source:10.21','Nīlakaṇṭha','gita.10.21','sa','commentary','।।10.21।।योगमुक्त्वा विभूतीराह -- आदित्यानामित्यादिना यावदध्यायसमाप्ति। आदित्यानां द्वादशानां मध्ये विष्णुनामादित्योऽहं? वामनावतारो वा। ज्योतिषामग्न्यादीनां मध्ये रविः अंशुमान् अत्यन्तं प्रतपनशीलो निदाघमध्याह्ने तीव्रातपवान्रविरहमेवेत्यर्थः। मरुतां सप्तसप्तकानां मध्ये मरीचिरहम्। नक्षत्राणां ताराणाम्। अत्र प्रायेण निर्धारणे षष्ठी। भूतानामस्मि चेतनेत्यादौ संबन्धेऽपि। शशी चन्द्रमाः।'),
('nilakantha-sc:source:10.22','Nīlakaṇṭha','gita.10.22','sa','commentary','।।10.22।।सामवेदो गानेन रमणीयत्वात्। वासवो देवराजत्वात्। मन इन्द्रियान्तरप्रवर्तकत्वात्। चेतना धीवृत्तिः। चिदभिव्यक्तिहेतुत्वात्। एते वेदादीनां मध्ये श्रेष्ठाः।'),
('nilakantha-sc:source:10.23','Nīlakaṇṭha','gita.10.23','sa','commentary','।।10.23।।रुद्राणामेकादशानां? वसूनामष्टानां? शिखराणि रत्नविशेषास्तद्वतां मध्ये मेरुरहम्।'),
('nilakantha-sc:source:10.24','Nīlakaṇṭha','gita.10.24','sa','commentary','।।10.24।।पुरोधसां पुरोहितानां बृहस्पतिं देवराजपुरोहितत्वात्। सेनानीनां सेनापतीनां स्कन्दः कार्तिकेयः। सरसां जलाशयानाम्।'),
('nilakantha-sc:source:10.25','Nīlakaṇṭha','gita.10.25','sa','commentary','।।10.25 -- 10.26।।एकमक्षरमोंकाराख्यम्। जपयज्ञो हिंसाशून्यत्वात्। स्थावराणां स्थितिमताम्।'),
('nilakantha-sc:source:10.26','Nīlakaṇṭha','gita.10.26','sa','commentary','।।10.25 -- 10.26।।एकमक्षरमोंकाराख्यम्। जपयज्ञो हिंसाशून्यत्वात्। स्थावराणां स्थितिमताम्।'),
('nilakantha-sc:source:10.27','Nīlakaṇṭha','gita.10.27','sa','commentary','।।10.27।।अमृतोद्भवममृतमथनावसरे उद्भवो यस्य तम्।'),
('nilakantha-sc:source:10.28','Nīlakaṇṭha','gita.10.28','sa','commentary','।।10.28।।प्रजनोऽपत्यजनयिता कंदर्पः कामो न तु वृथामैथुनरूपः।'),
('nilakantha-sc:source:10.29','Nīlakaṇṭha','gita.10.29','sa','commentary','।।10.29।।नागानां सर्पावान्तरभेदानाम्। यादसां जलचराणाम्। संयमतां नियमनकर्तृ़णाम्।'),
('nilakantha-sc:source:10.30','Nīlakaṇṭha','gita.10.30','sa','commentary','।।10.30।।कलयतां गणनं कुर्वताम्।'),
('nilakantha-sc:source:10.31','Nīlakaṇṭha','gita.10.31','sa','commentary','।।10.31।।पवतां पावयितृ़णां वेगवतां वा। रामो दाशरथिः। रामादीनां परमेश्वराणामपि विभूतिमध्ये गणनं ध्यानार्थम्। झषाणां मत्स्यादीनां मकरो जातिभेदः। स्रोतसां नदीनाम्।'),
('nilakantha-sc:source:10.32','Nīlakaṇṭha','gita.10.32','sa','commentary','।।10.32।।सर्गाणां भौतिकानां भूतानामादिरन्त इति प्रागेवोक्तत्वात्। विद्यानां चतुर्दशसंख्यानां मध्ये अध्यात्मविद्या बन्धच्छेदहेतुत्वात्। प्रवदतां प्रवक्तृद्वारेण वदनभेदा एव वादजल्पवितण्डा इह गृह्यन्ते। तेषां मध्ये वादस्तत्त्वनिर्णयार्थत्वादहम्।'),
('nilakantha-sc:source:10.33','Nīlakaṇṭha','gita.10.33','sa','commentary','।।10.33।।अक्षराणां मध्ये अकारः।अकारो वै सर्वा वाक् इति श्रुतेः। सामासिकस्य समाससमुदायस्य मध्येऽहं द्वन्द्वोऽस्मि। उभयपदार्थप्रधानत्वादिति प्राञ्चः। समं एकत्रासनं समासो विदुषां वा गुरुशिष्याणां वा मन्त्रार्थकथनार्थं वा एकत्रावस्थानं तत्र विदितमर्थजातं सामासिकम्। चातुरर्थिकष्ठक्ठस्येकः इतीकादेशः।यस्येति च इत्यलोपः। तस्य मध्ये द्वन्द्वो रहस्योऽर्थोऽहम्।द्वन्द्वं रहस्य -- इति सूत्रे द्वन्द्वशब्दस्य रहस्यवाचित्वं शाब्दिकप्रसिद्धम्। अक्षयः क्षयहीनः कालः क्षणादिः परो वा ईश्वरः कालस्यापि कालोऽस्मि। धाता कर्मफलप्रदः। विश्वतोमुखः। सर्वप्राणितृप्त्यातृप्यामीत्यर्थः।'),
('nilakantha-sc:source:10.34','Nīlakaṇṭha','gita.10.34','sa','commentary','।।10.34।।सर्वहरः प्रलयकालिको मृत्युरस्मि। भविष्यतां भाविकल्याणानामुद्भव ऐश्वर्योत्कर्षोऽहम्। कीर्त्यादिसप्तकमप्यहं यासां संश्रयमात्रेण मनुष्येषु कृतार्थताबुद्धिर्भवति।'),
('nilakantha-sc:source:10.35','Nīlakaṇṭha','gita.10.35','sa','commentary','।।10.35।।बृहत्सामत्वामिद्धि हवामहे इत्यस्यामृचि गीयमानं साम पृष्ठ्यस्तोत्रे विनियुक्तमिन्द्रदेवत्यं तत् साम्नां मध्येऽहमस्मि। छन्दसां मध्ये गायत्री द्विजत्वसंपादनात्सोमाहरणाच्च श्रेष्ठाहमस्मि। कुसुमाकरो वसन्तः।'),
('nilakantha-sc:source:10.36','Nīlakaṇṭha','gita.10.36','sa','commentary','।।10.36।।व्यवसायो निश्चय उद्यमो वा।'),
('nilakantha-sc:source:10.37','Nīlakaṇṭha','gita.10.37','sa','commentary','।।10.37।।वृष्णीनां यादवानाम्। उशना शुक्रः।'),
('nilakantha-sc:source:10.38','Nīlakaṇṭha','gita.10.38','sa','commentary','।।10.38।।दमयतां राजादीनां दमनसाधनं दण्डोऽहमस्मि। जिगीषतां जेतुमिच्छतां जयसाधनं नीतिरस्मि। मौनं वाचोनिग्रहः।'),
('nilakantha-sc:source:10.39','Nīlakaṇṭha','gita.10.39','sa','commentary','।।10.39।।सर्वभूतानां बीजमित्यनेन सर्वभूतानि मद्विभूतिरिति दर्शितम्? तदेवोपपादयति -- न तदस्तीति। मया विना भूतां किमपि नास्ति। उपादेयस्योपादानमन्तरेण स्थित्यसंभवात्।'),
('nilakantha-sc:source:10.40','Nīlakaṇṭha','gita.10.40','sa','commentary','।।10.40।।नान्तोऽस्तीति। उद्देशत एकदेशेन विभूतेर्विस्तरो विस्तारो मया प्रोक्तः।'),
('nilakantha-sc:source:10.41','Nīlakaṇṭha','gita.10.41','sa','commentary','।।10.41।।सर्वभूतानां बीजमहमित्युक्त्या स्वस्य सार्वात्म्योक्तेः सर्वं स्वविभूतिरित्युक्तमेव तथापि तद्ग्रहणाशक्तं प्रति प्राह -- यद्यदिति। यद्यत्सत्त्वं प्राणि विभूतिमदैश्वर्ययुक्तम्। श्रीर्लक्ष्मीः शोभा वा तद्युक्तम्। ऊर्जितं बलाद्यतिशययुक्तम्। तत्तत्सर्वं मम तेजसश्चिच्छक्तेरंशसंभवमंशात्संभूतं त्वमवगच्छ जानीहि। लोके यदतिरमणीयं तद्भगवतो रूपमिति ध्यायेदित्यर्थः।'),
('nilakantha-sc:source:10.42','Nīlakaṇṭha','gita.10.42','sa','commentary','।।10.42।।उत्तमाधिकारिणमुद्दिश्याह -- अथवेति। मूढान्प्रत्येतदुक्तं? त्वं तु एतावदेव विद्धि। एकांशेन एकदेशेनाहमिदं विष्टभ्य व्याप्य स्थितोऽस्मि।पादोऽस्य विश्वा भूतानि इति श्रुतेः। तस्मात्परिच्छिन्नं दर्शनं त्यक्त्वा सर्वत्र ब्रह्मबुद्धिमेव कुर्वित्याशयः।'),
('nilakantha-sc:source:11.1','Nīlakaṇṭha','gita.11.1','sa','commentary','।।11.1।।पूर्वस्मिन्नध्याये योगो विभूतिश्च व्याख्येयत्वेन प्रतिज्ञातौएतां विभूतिं योगं च मम यो वेत्ति इति।आत्मनो योगं विभूतिं च जनार्दन। भूयः कथय इतीतरेण च श्रोतव्यत्वेन प्रार्थितौ। तत्रअहमात्मा गुडाकेश सर्वभूताशयस्थितः इति संक्षेपेण योगो भगवता सर्वभूताधारत्वलक्षण उक्तः प्राग्विभूतिकथनात्। तदन्ते चविष्टभ्याहमिदं कृत्स्नमेकांशेन स्थितो जगत् इति कुसूलेन धान्यमिव मयेदं जगद्विष्टब्धमित्युक्त्या स एव स्मारितस्तदेव भगवतः सर्वभूताधारत्वं साक्षात्कर्तुकामोऽर्जुन उवाच -- मदनुग्रहायेति। मयि अनुग्रहोऽनुकम्पा तदर्थं मदनुग्रहाय। परमं सद्यः शोकमोहनिवर्तकत्वेनोत्कृष्टं गुह्यं गोप्यं अध्यात्मसंज्ञितमात्मानात्मविवेकार्थं शास्त्रमध्यात्मं तत्संज्ञितं यत्त्वया वचःअशोच्यानन्वशोचः इत्यादिना षष्ठाध्यायपर्यन्तं त्वंपदार्थशुद्धिप्रधानंनायं हन्ति न हन्यते इत्यात्मनोऽकर्तृत्वाभोक्तृत्वप्रतिपादकं तेन मम मोहोऽविवेकोऽयं विशेषेण गतो नष्टः। अत्र प्रथमे पादेऽक्षराधिक्यमार्षम्।'),
('nilakantha-sc:source:11.2','Nīlakaṇṭha','gita.11.2','sa','commentary','।।11.2।।भवेति। तथा सप्तमाध्यायमारभ्य दशमपर्यन्तं त्वया भूतानां भवाप्ययावप्युक्तौअहं सर्वस्य प्रभवो मत्तः सर्वं प्रवर्तते इति तावपि मया विस्तरशरस्त्वत्तः श्रुतौ। हे कमलपत्राक्ष? अव्ययं माहात्म्यमपिन च मां तानि कर्माणि लिम्पन्ति इति विषमसृष्टिकर्तुरपि वैषम्यनैर्घृण्यदोषो नास्ति जगत्कर्तुरपि विकारगन्धो नास्ति इत्येवमादिरूपतत्पदार्थशुद्धिप्रधानं श्रुतमित्यनुषङ्गः।'),
('nilakantha-sc:source:11.3','Nīlakaṇṭha','gita.11.3','sa','commentary','।।11.3।।एवमिति। यच्च त्वंविष्टभ्याहमिदं कृत्स्नमेकांशेन स्थितो जगत् इति आत्मानं जगदाधारमात्थ तदपि इत्थमेव न ममात्रासंभावनास्ति। हे परमेश्वर? ते तव रूपं ऐश्वरमीश्वरस्येदं विश्वात्मकं मायामयमित्यर्थः। हे पुरुषोत्तम क्षराक्षरातीत? विश्वरूपं मायामयं? वास्तवं तु रूपं मायातीतमित्यैश्वरमिति पुरुषोत्तमेति च पदाभ्यां लभ्यते। तथाच वक्ष्यतिमाया ह्येषा मया सृष्टा यन्मां पश्यसि नारद। सर्वभूतगुणैर्युक्तं नैवं मां ज्ञातुमर्हसि इति। उक्तं च शुद्धं रूपमभिप्रेत्यअव्यक्तोऽयमिन्त्योऽयम् इति।'),
('nilakantha-sc:source:11.4','Nīlakaṇṭha','gita.11.4','sa','commentary','।।11.4।।मन्यस इति। हे योगेश्वर योगानां योगिनामीश्वर? तद्रूपं यदि मया द्रष्टुं शक्यमिति मन्यसे यदि मयि तद्दर्शनाधिकारं पश्यसि ततस्तर्हि मे मह्यमव्ययं मायामयमात्मानं दर्शय। मायामयत्वादेवास्याव्ययत्वम्। मायायां हि सर्वं सर्वात्मकं सर्वदास्तीति प्रसिद्धम्। यथोक्तं वसिष्ठेनवर्तमानमतीतं च भविष्यत्स्थूलमण्वपि। तथा दूरमदूरं च निमेषः कल्प इत्यपि। चिदात्मनि स्थितान्येव पश्य मायाविजृम्भितम् इति। नहि मरुमरीचिसरसी क्रमशः शुष्यति। अतो मायामयत्वादेवास्यैश्वरस्य रूपस्याप्यव्ययत्वम्।'),
('nilakantha-sc:source:11.5','Nīlakaṇṭha','gita.11.5','sa','commentary','।।11.5।।एवं प्रार्थितः सन् भगवानुवाच -- पश्येति। शतश इत्यादिनानन्तानीत्युक्तम्। नानावर्णानि नानाकृतीनि च।'),
('nilakantha-sc:source:11.6','Nīlakaṇṭha','gita.11.6','sa','commentary','।।11.6।।दिव्यानि तावदाह -- पश्यादित्यानिति। अदृष्टपूर्वाण्याश्चर्याणि अद्भुतानि चतुर्मुखपञ्चमुखषण्मुखादीनि।'),
('nilakantha-sc:source:11.7','Nīlakaṇṭha','gita.11.7','sa','commentary','।।11.7।।हे गुडाकेश जितनिद्र? इह मम देहे एकस्थं एकस्मिन्नेवावयवे नखाग्रमात्रे स्थितं कृत्स्नं वर्तमानं जगत्पश्य। यच्चान्यत् अतीतमनागतं विप्रकृष्टं व्यवहितं स्थूलं सूक्ष्मं वा तत्सर्वमिह पश्य।'),
('nilakantha-sc:source:11.8','Nīlakaṇṭha','gita.11.8','sa','commentary','।।11.8।।यत्तूक्तंमन्यसे यदि तच्छक्यं मया द्रष्टुम् इति तत्राह -- नत्विति। शक्यसे शक्नोषि। पदविकरणव्यत्यय आर्षः। अनेन प्राकृतेन। दिव्यमप्राकृतम्। ऐश्वरं ईश्वरसंबन्धिनं योगं विश्वाश्रयत्वलक्षणं सामर्थ्यम्।'),
('nilakantha-sc:source:11.9','Nīlakaṇṭha','gita.11.9','sa','commentary','।।11.9।।एवमुक्त्वा भगवानर्जुनाय दिव्यं रूपं दर्शितवान्? सच दृष्ट्वा विस्मयाविष्टो भगवन्तं,विज्ञापितवानितीमं वृत्तान्तमेवमुक्त्वेत्यादिषड्भिः श्लोकैर्धृतराष्ट्रं प्रति संजय उवाच -- एवमुक्त्वेत्यादि। ततः दिव्यचक्षुःप्रदानानन्तरम्। राजन् हे धृतराष्ट्र? महांश्चासौ योगेश्वरश्चेति विग्रहः। महतो योगस्य वा ईश्वरः। परमं दिव्यं रूपं ऐश्वरं मायाविसंबन्धि नतु मायातीतं दर्शयामास।'),
('nilakantha-sc:source:11.10','Nīlakaṇṭha','gita.11.10','sa','commentary','।।11.10।।तदेव रूपं विशिनष्टि द्वाभ्याम् -- अनेकेत्यादिना। अनेकान्यनन्तानि वक्त्राणि नयनानि च यस्मिंस्तदनेकवक्त्रनयनम्। अनेकान्यद्भुतानि दर्शनानि यस्मिंस्तदनेकाद्भुतदर्शनम्। अनेकानि दिव्यान्याभरणानि यस्मिन्। दिव्यान्यनेकानि चोद्यतान्यायुधानि चक्रादीनि यस्मिन्।'),
('nilakantha-sc:source:11.11','Nīlakaṇṭha','gita.11.11','sa','commentary','।।11.11।।विश्वतोमुखमिति पूर्वोक्तस्यएकत्वेन पृथक्त्वेन बहुधा विश्वतोमुखम् इत्यस्यायं परामर्शः। अनन्तं सर्वतः परिच्छेदरहितम्।'),
('nilakantha-sc:source:11.12','Nīlakaṇṭha','gita.11.12','sa','commentary','।।11.12।।दिवि अन्तरिक्षे। भाः दीप्तिः। भासः दीप्तेः। अभूतोपमेयम्। निरुपमतामेव तस्य दीप्तेर्दर्शयतिउभौ यदि व्योम्नि पृथक्प्रवाहौ इत्यादिवत्।'),
('nilakantha-sc:source:11.13','Nīlakaṇṭha','gita.11.13','sa','commentary','।।11.13।।इहैकस्थं जगत्कृत्स्नं पश्येति यत्प्राक् भगवतोक्तं तदप्यपश्यदित्याह -- तत्रेति। अनेकधा प्रविभक्तमित्येतद्वर्षासूत्थिततिंतिणीबीजे सूक्ष्मरूपेण तरुर्दृश्यते तद्वन्माभूदिति दर्शयितुं सावकाशं अनेकधा विभागयुक्तं विविक्तमपश्यत्। एकस्थमेकावयवस्थम्। अयमर्थः -- यदा भगवतश्चतुर्भुजं रूपं चिन्त्यते तत्र च चेतसि लब्धपदे सति क्रमशस्तदीयावयवांस्त्यक्त्वा मुखे स्मिते वा पदनखे वा चित्तं ध्रियते। तत्रापि लब्धपदे तस्मिंस्तदपि त्यक्त्वा विश्वरूपमारोहति। दिव्यं चक्षुरपि एवं सूक्ष्मतामापादितं मन एव।मनोऽस्य दैवं चक्षुः स एतेन दैवेन चक्षुषा मनसैतान्कामान्पश्यन्रमते इति श्रुतेः। कामान्विषयान् एतान्हार्दाकाशाख्यसगुणब्रह्मगतानिति श्रुतिपदयोरर्थः। यथोक्तं श्रीभागवतेतत्र लब्धपदं चित्तमाकृष्यैकत्र धारयेत्। नान्यानि चिन्तयेद्भूयः सुस्मितं भावयेन्मुखम्। तत्र लब्धपदं चित्तमाकृष्य व्योम्नि धारयेत्। तच्च त्यक्त्वा मदारोहो न किञ्चिदपि चिन्तयेत् इति। तत्र मूर्तौ एकत्र अङ्गे। व्योम्नि कारणे। मदारोहो निर्विकल्पे ब्रह्मण्यारूढः। तदिदमुक्तं देवदेवस्य शरीरे कृत्स्नं जगदेकस्थं पाण्डवोऽपश्यदिति।'),
('nilakantha-sc:source:11.14','Nīlakaṇṭha','gita.11.14','sa','commentary','।।11.14।।हृष्टरोमा रोमाञ्चितगात्रः।'),
('nilakantha-sc:source:11.15','Nīlakaṇṭha','gita.11.15','sa','commentary','।।11.15।।देवानादित्यादीन्। भूतविशेषाश्चतुर्विधा जरायुजादयस्तेषां संघान्समूहान्। ब्रह्माणं चतुर्मुखम्। ईशमीशितारम्। कमलासनस्थमित्यनेन दूरदर्शनमुक्तम्। उरगान्पातालस्थाननन्तादीन्। दिव्यान्कैलासादौ स्थितान्वासुकिप्रमुखान्। एतेन व्यवहितदर्शनमुक्तम्।'),
('nilakantha-sc:source:11.16','Nīlakaṇṭha','gita.11.16','sa','commentary','।।11.16।।अनेके अनन्ता बाहव उदराणि वक्त्राणि नेत्राणि च यस्मिंस्तदनेकबाहूदरवक्त्रनेत्रम्। सर्वतश्चतुर्दिक्षूपर्यधश्चानन्तमपरिच्छिन्नं रूपमस्य तम्। अनन्तत्वमेवाह -- नान्तमिति। दीर्घरज्ज्वा इव तवाद्यन्तौ दैशिकौ न स्त इत्यर्थः।'),
('nilakantha-sc:source:11.17','Nīlakaṇṭha','gita.11.17','sa','commentary','।।11.17।।किरीटगदाचक्रधारिणम्। दीप्तिमत्त्वादेव दुर्निरीक्ष्यं द्रष्टुमशक्यम्। समन्तात्सर्वतो ये दीप्ता अनला अर्काश्च तद्वद्द्युतिर्यस्य तं? समन्ताद्दीप्तानर्लाकद्युतिमित्येकं पदम्। अतएवाप्रमेयं द्रष्टुमशक्यपरिच्छेदम्।'),
('nilakantha-sc:source:11.18','Nīlakaṇṭha','gita.11.18','sa','commentary','।।11.18।।एवं तव योगैश्वर्यदर्शनात्त्वामेवमवैमीति वदन्नप्रमेयत्वमेव विवृणोति -- त्वमिति। परममक्षरमस्थूलादिलक्षणम्।अक्षरं ब्रह्म परमम् इत्यत्र प्रागुक्तं निष्कलं ब्रह्म तदेव त्वमसि। एतेन सगुणरूपस्य निर्गुणज्ञापकत्वमुक्तम्। शाखाग्रस्येव चन्द्रज्ञापकत्वम्। अतएव वेदितव्यं वेदान्तप्रमाणेन ज्ञातुं योग्यं नतूपासनीयम्। सगुणं ब्रह्मापि त्वमेवेत्याह -- त्वमस्येति। निधानं लयस्थानम्। एतेन कारणत्वमुक्तम्। अव्ययः अमृतः देवत्वात्। शाश्वतस्य वैदिकस्य धर्मस्य गोप्तेत्यनेन कार्यब्रह्मभूतहिरण्यगर्भरूपत्वमुक्तम्।,सनातनश्चिरन्तनोऽनादिपुरुषो जीवात्मा सोऽपि त्वमेव मे मम मतः। एवं विश्वरूपदर्शने जीवब्रह्मणोरैक्यं शाखया चन्द्र इवाधिगम्यत इत्युक्तम्।'),
('nilakantha-sc:source:11.19','Nīlakaṇṭha','gita.11.19','sa','commentary','।।11.19।।एतदेवाह -- अनादीति। देशतः कालतश्चादिमध्यान्तहीनत्वादनादिमध्यान्तम्। दीप्तो हुताशो वक्त्रे यस्येति भास्वरदन्तत्वं व्यज्यते। स्वतेजसा चैतन्यज्योतिषा इदं विश्वं विश्वरूपं तपन्तं प्रकाशयन्तम्। अनादित्वादिसर्वविशेषणविशिष्टं विश्वं तपिकर्मीभूतं तापयन्तं त्वां परज्योतीरूपं पश्यामि जानामि। चित्रपटस्थानीयं विश्वरूपं सकलकारकात्मकधीवासनोपेतं येन ज्योतिषा प्रकाशते तदेव त्वमसीति जानामीति भावः।'),
('nilakantha-sc:source:11.20','Nīlakaṇṭha','gita.11.20','sa','commentary','।।11.20।।एवं स्वयंकृतविश्वरूपदर्शनेन कृतकृत्यो भूत्वा तदुपसंहारमिच्छन्स्तौति -- द्यावापृथिव्योरिति। हे महात्मन्? हि प्रत्यक्षं त्वयैकेनेदं द्यावापृथिव्योरन्तरं मध्यं सर्वाः दिशश्च व्याप्ताः। अतस्तवेदमद्भुतमुग्रं रूपं दृष्ट्वा लोकत्रयं प्रकर्षेण व्यथितम्। अतः परमिदमुपसंहरेत्यभिप्रायः।'),
('nilakantha-sc:source:11.21','Nīlakaṇṭha','gita.11.21','sa','commentary','।।11.21।।व्यथामेवाह -- अमीति। हि यतः अमी त्वा त्वां असुरसङ्घा असुरांशा दुर्योधनादयस्त्वां पतङ्गाः पावकमिवादृष्टप्रेरिता विशन्ति मरणायेत्यर्थः। केचिद्भीताः प्राञ्जलयो बद्धाञ्जलयो गृणन्ति स्तुवन्ति।'),
('nilakantha-sc:source:11.22','Nīlakaṇṭha','gita.11.22','sa','commentary','।।11.22।।किं च ये त्वदनुगृहीता रुद्रादयस्तेऽपि विस्मिताः सन्तः सर्वे त्वां वीक्षन्त इत्याह -- रुद्रादित्या इति। साध्याः विश्वे च देवगणविशेषौ रुद्रादित्यवज्ज्ञेयौ। उष्मपाः पितरः। गन्धर्वाणां यक्षाणामसुराणां सिद्धानां जातिभेदानां सङ्घाः समूहाः। शेषं स्पष्टम्।'),
('nilakantha-sc:source:11.23','Nīlakaṇṭha','gita.11.23','sa','commentary','।।11.23।।पुनर्लोकानामात्मनश्च व्यथामाह -- रूपमिति। महत् आदिमध्यान्तहीनम्। हे महाबाहो? ते तव करालं महारूपं दृष्ट्वा लोका व्यथितास्तथाहं च व्यथित इति योजना।'),
('nilakantha-sc:source:11.24','Nīlakaṇṭha','gita.11.24','sa','commentary','।।11.24।।करालत्वप्रपञ्चनेन स्वव्यथामेवाह -- नभ इति। नभःस्पृशं व्योमव्यापिनम्। दीप्तमग्निवज्जाज्वल्यमानम्। व्यात्ताननं विस्तारितमुखम्। दीप्तविशालनेत्रं रक्तनेत्रमित्यर्थः। हि प्रत्यक्षं त्वा त्वां दृष्ट्वा प्रव्यथितान्तरात्मा प्रकर्षेण व्यथितचित्तो धृतिं धैर्यं न विन्दामि न लभे शमं च शान्तिं स्वास्थ्यं च न लभे हे विष्णो व्यापक? भयानकं त्वदाक्रान्तं देशं त्यक्त्वान्यत्र गन्तुमशक्यं तव व्यापकत्वादिति भावः।'),
('nilakantha-sc:source:11.25','Nīlakaṇṭha','gita.11.25','sa','commentary','।।11.25।।कालानलः प्रलयाग्निस्तत्तुल्यानि। प्रसीद प्रसन्नः सुखदो भवेत्यर्थः।'),
('nilakantha-sc:source:11.26','Nīlakaṇṭha','gita.11.26','sa','commentary','।।11.26।।अमी त्वां विशन्तीत्यग्रिमश्लोकादपकृष्यते।'),
('nilakantha-sc:source:11.27','Nīlakaṇṭha','gita.11.27','sa','commentary','।।11.27।।ते भीष्मादयः। उत्तमाङ्गैः शिरोभिः। अयं भावः -- धृतराष्ट्रस्य पुत्राः पापिष्ठाः भवन्तमेव त्रैलोक्यशरीरं विशन्ति। पापानुरूपं तस्य पायुस्थानस्थितान्नरकानेव गच्छन्तीति तत्र त्वां विशन्तीत्येवोक्तम्। भीष्मादयस्तु भक्ता यतोऽग्निर्ब्राह्मणा वेदाश्च प्रसूतास्तद्भगवतो मुखं प्रविशन्तीति वैषम्यगतिसूचनार्थं त्वां धृतराष्ट्रस्य पुत्रा विशन्ति भीष्मादयस्ते वक्त्राणि विशन्तीति विभागदर्शनं युक्तमिति।'),
('nilakantha-sc:source:11.28','Nīlakaṇṭha','gita.11.28','sa','commentary','।।11.28।।इदमेव सदृष्टान्तमाह -- यथेति। तव वक्त्राणि विशन्तीति संबन्धः। अभिविज्वलन्ति सर्वतः जाज्वल्यमानानि।'),
('nilakantha-sc:source:11.29','Nīlakaṇṭha','gita.11.29','sa','commentary','।।11.29।।बुद्धिपूर्वकमेव ते त्वद्वक्त्राणि प्रविशन्तीति सदृष्टान्तमाह -- यथा प्रदीप्तमिति।'),
('nilakantha-sc:source:11.30','Nīlakaṇṭha','gita.11.30','sa','commentary','।।11.30।।ये च पतन्तस्तांस्त्वं करुणावानपि न वारयसि प्रत्युत ग्रसितुमिच्छस्येवेत्याह -- लेलिह्यसे,भूयोभूयोऽतिशयेन वा आस्वादयसि। कीदृशस्त्वम्। समन्ताज्ज्वलद्भिर्वदनैर्लोकान्समग्रान्ग्रसमानः। एवं निर्घृणस्यापि तव तेजो न हीयते प्रत्युत वर्धत एवेत्याह -- तेजोभिरिति। हे विष्णो व्यापनशील? समग्रं जगत्तेजोभिरापूर्य तव उग्राः स्प्रष्टुमशक्या भासो दीप्तयः प्रतपन्तीति योजना। पदार्थः स्पष्टः।'),
('nilakantha-sc:source:11.31','Nīlakaṇṭha','gita.11.31','sa','commentary','।।11.31।।एवं दीप्त्याकुलीभूतोऽर्जुनो भगवानयमिति विस्मृत्याह -- आख्याहीति। एवमुग्ररूपः क्रूरकर्मा भवान् कोऽसीत्याख्याहि अमुकोऽस्मीति कथय। प्रसीद शान्तो भव। त्वामहं विज्ञातुमिच्छामि। यतस्तव प्रवृत्तिं चेष्टां न जानामि।'),
('nilakantha-sc:source:11.32','Nīlakaṇṭha','gita.11.32','sa','commentary','।।11.32।।एवमर्जुनेन प्रार्थितो भगवानुवाच -- काल इति। इहास्मिन्संग्रामे लोकान्समाहर्तुं भक्षितुं प्रवृत्तः प्रवृद्धो महान् लोकक्षयकृत् कालो नाम परमेश्वरोऽस्मि। यस्मादेवं तस्मात् ऋतेऽपि त्वा त्वां विनापि सर्वे न भविष्यन्ति मरिष्यन्ति। के ते सर्वे। ये प्रत्यनीकेषु शत्रुसैन्येषु योधाः शूरा भीष्मादयोऽवस्थितास्ते।'),
('nilakantha-sc:source:11.33','Nīlakaṇṭha','gita.11.33','sa','commentary','।।11.33।।तस्मादिति। यस्मात्त्वां विनाप्येते मरिष्यन्ति तस्मात्त्वमुत्तिष्ठ युद्धाय। शेषं स्पष्टम्।'),
('nilakantha-sc:source:11.34','Nīlakaṇṭha','gita.11.34','sa','commentary','।।11.34।।मा व्यथिष्ठाः एते महान्तः कथं हन्तुं शक्या इत्याकुलीभावं मागा इत्यर्थः। जेतासि जेष्यसि सपत्नाञ्शत्रून्।'),
('nilakantha-sc:source:11.35','Nīlakaṇṭha','gita.11.35','sa','commentary','।।11.35।।भगवतैवमुक्ते सति पश्चात्किंवृत्तमित्यपेक्षायां संजय उवाच। अत्र कृताञ्जलित्वादिना चिह्नेन भगवद्वाक्योल्लङ्घनं किरीटी न करिष्यतीति सूच्यते। सगद्गदं भयहर्षाद्यावेशेन गद्गदेन कण्ठकम्पनेन सह वर्तत इति सगद्गदं यथा भवति तथा आह उक्तवान्। भीतभीतोऽत्यन्तं भीतः सन्नाहेति संबन्धः। अत्राहेति पदच्छेदे पुनरर्जुन उवाचेति पुनरुक्तं स्यात्। अतः प्रणम्य अर्जुन उवाचेत्येव संबन्धो नतु प्रणम्य आहेति। का तर्हि आहेति क्रियाया गतिः। नेयं क्रिया किंतु अहेति प्रसिद्ध्यर्थमव्ययमित्यदोषः।'),
('nilakantha-sc:source:11.36','Nīlakaṇṭha','gita.11.36','sa','commentary','।।11.36।।एकादशभिः श्लोकैरर्जुन उवाच -- स्थाने इति। हे हृषीकेश सर्वेन्द्रियप्रवर्तक अन्तर्यामिन्? तव प्रकीर्त्या नामसंकीर्तनेन जगत्प्रहृष्यति यत्तत् स्थाने युक्तम्। स्थाने इत्यव्ययं युक्तमित्यर्थे। यत्तव प्रकीर्त्या जगदनुरज्यते तदपि स्थाने युक्तम्। यत्तव प्रकीर्त्या रक्षांसि भीतानि सन्ति दिशो द्रवन्ति पलायन्ते तदपि स्थाने युक्तम्। यच्च त्वां सर्वे सिद्धसङ्घाः कपिलादीनां समुदायाः नमस्यन्ति तदपि स्थाने। अयं श्लोको रक्षोघ्नमन्त्रत्वेन मन्त्रशास्त्रे प्रसिद्धः। स च नारायणाष्टाक्षरसुदर्शनास्त्रमन्त्राभ्यां संपुटितो ज्ञेय इति रहस्यम्।'),
('nilakantha-sc:source:11.37','Nīlakaṇṭha','gita.11.37','sa','commentary','।।11.37।।कुतो मां सिद्धसङ्घा नमस्यन्ति यतस्तेप्यहमिव ब्रह्माण्डशतानि स्रष्टुमर्हन्तीत्यत आह -- कस्मादिति। हे महात्मन् कस्माद्धेतोस्ते त्वां न नमेरन्नपितु नमेरन्नेव। तत्र हेतुः गरीयसे। तेऽपि गुरवस्त्वमपि गुरुस्तथापि त्वमतिशयितो गुरुरसीत्यर्थः। कुतो ममैवातिशयस्तेषां मम च समानेऽपि सत्यसंकल्पत्वादौ सत्यतश्चाह। ब्रह्मणो हिरण्यगर्भस्याप्यादिकर्त्रे पितामहाय पञ्चमहाभूतसृष्टिद्वारा ब्रह्माणं सृजत इत्यर्थः।जगद्व्यापारवर्जं प्रकरणादसन्निहितत्वाच्च इतिन्यायेन नित्यसिद्धेश्वरस्य तवाज्ञया ते सर्वेऽप्यैश्वर्यभाजो भवन्ति नतु त्वत्समास्ते। अतएव हे अनन्त हे देवानां ईश जगन्निवास जगतामालयभूत? त्वं अक्षरं शुद्धं ब्रह्म। कीदृशमक्षरम्। यत् सदसत्तत्परं सच्च असच्च सदसती ताभ्यां परं च सदसत्तत्परम् कार्यं कारणं तदुभयातीतं चेति त्रिविधमित्यर्थः।'),
('nilakantha-sc:source:11.38','Nīlakaṇṭha','gita.11.38','sa','commentary','।।11.38।।पुनरपि स्तौति -- त्वमिति। आदिदेवो जगतः स्रष्टृत्वात्। पुरुषः सर्वशरीरशायी। पुराणः शरीरनाशादिनाप्यविनश्यन्। विश्वस्यास्य त्वं परं निधानं निधीयतेऽस्मिन्निति लयस्थानम्। सांख्यानां जडां प्रकृतिं वारयति। वेत्ता ज्ञाता। वेद्यं तद्दृश्यं च त्वमेव। परं वेत्तृवेद्याभ्यामन्यत् धाम चैतन्यम्। त्वया विश्वं ततं व्याप्तं स्वसत्तास्फूर्तिभ्याम्। हे अनन्तरूप त्रिविधपरिच्छेदशून्यस्वरूप।');
INSERT INTO commentary_fts (unit_id,author,canonical_ref,language,content_type,content) VALUES
('nilakantha-sc:source:11.39','Nīlakaṇṭha','gita.11.39','sa','commentary','।।11.39।।सर्वदेवतात्मत्वेन स्तौति -- वायुरिति। प्रजापतिर्दक्षादिश्चतुर्मुखो वा। प्रपितामहश्चतुर्मुखपिता।'),
('nilakantha-sc:source:11.40','Nīlakaṇṭha','gita.11.40','sa','commentary','।।11.40।।हे अनन्तवीर्य? यतः सर्वं समाप्नोषि एकीभावेनासमन्ताद्व्याप्नोषि ततो हेतोः सर्व इति तव नाम। पुरस्तात्कर्मणामादौ। पृष्ठतस्तेषां समाप्तौ। सर्वतो मध्येऽपि ते नमोऽस्तु।'),
('nilakantha-sc:source:11.41','Nīlakaṇṭha','gita.11.41','sa','commentary','।।11.41।।एवं स्तुत्वा स्वापराधान्क्षमापयते -- सखेतीति। अयं मम सखा इति मत्वा प्रसभं स्वोत्कर्षाविष्करणपूर्वकं यत् मयोक्तं हे कृष्ण हे यादव हे सखे इति। इतिशब्देन संधिरार्षः। कुत उक्तम्। तव इदमेवंविधं महिमानं माहात्म्यमजानता कदाचित्प्रमादाच्चित्तविक्षेपात्कदाचित्प्रणयेन स्नेहेन च।'),
('nilakantha-sc:source:11.42','Nīlakaṇṭha','gita.11.42','sa','commentary','।।11.42।।तथा यच्च अवहासार्थं विहारादिष्वसत्कृतोऽसि परिभूतोऽसि। एको वा सखीनां वियोगकाले वा तत्समक्षं सखिजनसमक्षं वाऽसत्कृतोऽसि तत्क्षामये क्षमापये। यतस्त्वमप्रमेयोऽचिन्त्यस्वभावः करुणापरः। यतः शत्रुभ्योऽपि शिशुपालादिभ्य उत्तमां गतिं दत्तवानसीत्यर्थः।'),
('nilakantha-sc:source:11.43','Nīlakaṇṭha','gita.11.43','sa','commentary','।।11.43।।अप्रमेयत्वमेवाह -- पितासीति। यतस्त्वमस्माकं पितासि अतोऽस्माभिः शिशुभिः कृता अपराधास्त्वया क्षन्तव्या एवेति भावः।'),
('nilakantha-sc:source:11.44','Nīlakaṇṭha','gita.11.44','sa','commentary','।।11.44।।एतदेवाह -- तस्मादिति। यस्मात्त्वं पिता गुरुश्च तस्मात्कायं शरीरं प्रणिधाय भूमौ कृत्वा दण्डवत्प्रणम्य त्वां प्रसादये। ईड्यं स्तुत्यम्। स्पष्टमन्यत्।'),
('nilakantha-sc:source:11.45','Nīlakaṇṭha','gita.11.45','sa','commentary','।।11.45।।एवं स्तुत्वा स्वेष्टं प्रार्थयते -- अदृष्टपूर्वमिति। हे देव? कदाचिदपि पूर्वं न दृष्टं तादृशमदृष्टपूर्वं तव रूपं दृष्ट्वा हृषित उत्फुल्लोऽस्मि। तथा विकरालरूपदर्शनजेन भयेन च मे मम मनः प्रव्यथितम्। अतस्तदेव धारणाविषयभूतं रूपं मे मह्यं दर्शय।'),
('nilakantha-sc:source:11.46','Nīlakaṇṭha','gita.11.46','sa','commentary','।।11.46।।तदेव रुपमाह -- किरीटिनमिति। एतेनार्जुनस्य चक्रगदाकिरीटोपेतं चतुर्भुजं भगवतो रूपं धारणाविषय इति दर्शितम्। हे सहस्रबाहो हे विश्वमूर्ते सहस्रबाहुत्वादिकमुपसंहृत्य तेनैव रूपेण भव प्रकटो भव।'),
('nilakantha-sc:source:11.47','Nīlakaṇṭha','gita.11.47','sa','commentary','।।11.47।।एवमर्जुनेन प्रार्थितस्तं स्तुवन्भगवानुवाच -- मयेति त्रिभिः। हे अर्जुन? प्रसन्नेन मया तव तुभ्यमिदं परं रूपं दर्शितम्। आत्मयोगात्स्वसामर्थ्यात्। करुणया नतु तद्दर्शनेऽधिकारोऽस्ति। तथाच प्रागुक्तम् कर्मण्येवाधिकारस्ते इति। तेजोमयं चिद्रूपं दिव्यं विश्वं विश्वात्मकं आद्यमनादि अनन्तं च यत् रूपं त्वदन्येन कदाचिदपि न पूर्वं दृष्टं दृष्टपूर्वम्।'),
('nilakantha-sc:source:11.48','Nīlakaṇṭha','gita.11.48','sa','commentary','।।11.48।।योगैकगम्यमेतत्कर्मिणां दुष्प्रापमित्याह -- न वेदेति। वेदानां यज्ञानां चाध्ययनैरधिगमैः नच दानैर्नच क्रियाभिः स्मृत्युक्ताभिरापूर्तादिभिर्वापीकूपारामादिभिस्तपोभिः कृच्छ्रचान्द्रयणाद्यैः। उग्रैर्मासोपवासाद्यैः। नृलोके एवंरूपोऽहं द्रष्टुं न शक्यः। रोरुत्वाभाव आर्षः। त्वदन्येन कुरुप्रवीर।'),
('nilakantha-sc:source:11.49','Nīlakaṇṭha','gita.11.49','sa','commentary','।।11.49।।इदमतिदुर्लभदर्शनं रूपं दृष्ट्वापि चेद् व्यथसे तर्ह्युपसंहरामीदमित्याशयेनाह -- मा ते इति। ममेदं ईदृक् घोरं रूपं दृष्ट्वा ते तव व्यथा माभूदिति शेषः। विमूढभावो मोहश्च ते माभूत्। व्यपेतभीर्निर्भयः प्रीतमनाश्च पुनस्त्वं भूत्वा तदेव यत्त्वया द्रष्टुं प्रार्थितं मे ममेदं रूपं प्रपश्य।'),
('nilakantha-sc:source:11.50','Nīlakaṇṭha','gita.11.50','sa','commentary','।।11.50।।संजय उवाच -- इतीति। वासुदेवोऽर्जुनं प्रति इति पूर्वोक्तरीत्योक्त्वा यथा पूर्वमासीत्तथा स्वकं मानुषं रूपं भूयः पुनर्दर्शयामास। यदर्जुनेन प्रार्थितं चतुर्भुजं धारणाविषयं रूपं तदपि तिरोदधे इत्यर्थः। तथा महात्मा व्यापकोऽपि सन् सौम्यवपुरनुग्रदेहो भूत्वा भीतमेनमाश्वासयामास च।'),
('nilakantha-sc:source:11.51','Nīlakaṇṭha','gita.11.51','sa','commentary','।।11.51।।ततो निर्भयः सन्नर्जुन उवाच -- दृष्ट्वेति। सचेता अव्याकुलः। प्रकृतिं गतः स्वास्थ्यं प्राप्तः। संवृत्तो जातोऽस्मि।'),
('nilakantha-sc:source:11.52','Nīlakaṇṭha','gita.11.52','sa','commentary','।।11.52।।अस्य विश्वरूपदर्शनस्य दौर्लभ्यं दर्शयन् श्रीभगवानुवाच सुदुर्दर्शमिति। दर्शनकाङ्क्षिणः दर्शनं काङ्क्षन्ते एव न तु लभन्ते।'),
('nilakantha-sc:source:11.53','Nīlakaṇṭha','gita.11.53','sa','commentary','।।11.53। नाहमिति। न वेदयज्ञाध्ययनैरित्यनेनोक्त एवार्थः पुनरुच्यते विश्वरूपदर्शनस्यातिदौर्लभ्यसूचनाय। स्पष्टार्थश्च श्लोकः।'),
('nilakantha-sc:source:11.54','Nīlakaṇṭha','gita.11.54','sa','commentary','।।11.54।।कथं तर्हि द्रष्टुं शक्यस्त्वमत आह -- भक्त्येति। भक्त्या आराधनेन। अनन्ययाव्यभिचरितया। अखण्डयेत्यर्थः। अहमेवंविधो ज्ञातुं शक्यस्त्वंपदार्थशोधकशास्त्रतः। द्रष्टुं शक्यो ध्यानतः। तत्त्वेन याथात्म्येन प्रवेष्टुं शक्यस्तत्त्वमसिवाक्यार्थजज्ञानतः। हे परमज्ञानशत्रुं तापयतीति परंतप।'),
('nilakantha-sc:source:11.55','Nīlakaṇṭha','gita.11.55','sa','commentary','।।11.55।।शास्त्रसर्वस्वं संगृह्णाति -- मत्कर्मकृदिति। मदर्थमेव कर्माणि करोतीति मत्कर्मकृत्। अहमेव परमो निष्कलः प्राप्यो यस्येति स मत्परमः। एतेन कृत्स्नः कर्मयोगो ध्यानयोगश्च त्वंपदार्थशोधक उक्तः। मम भक्त आराधनकृदित्युपासनाकाण्डार्थसंग्रहः। सङ्गवर्जित इत्यनेन एकान्तभगवद्ध्याननिष्ठ इत्युक्तम्। निर्वैर इति विश्वं भगवदात्मना पश्येदित्युक्तम्। अन्यथा भेदबुद्धिमतो निर्वैरत्वासंभवात्। एवंभूतो यः स मां तत्पदलक्ष्यार्थभूतमखण्डानन्दैकघनमेति प्राप्नोति प्रत्यगभेदेन। हे पाण्डव विशुद्धवंशज। त्वमेवैतज्ज्ञातुं शक्नोषीति भावः।'),
('nilakantha-sc:source:12.1','Nīlakaṇṭha','gita.12.1','sa','commentary','।।12.1।।सप्तममारभ्यैतावता ग्रन्थेन तत्पदवाच्यार्थो निरूपितः। इदानीं तत्पदार्थशोधनमुपासनाकाण्डं च समापयिष्यन्निहार्थतः प्राधान्येन तत्पदलक्ष्यमर्थं तद्विदां लक्षणानि च प्रदर्श्यन्ते। शब्दतस्तु लौकिकबुद्ध्यनुसारेण तत्पदवाच्यस्यैवोपासनादिकं प्रपञ्च्यते। तत्र पूर्वाध्यायान्तेमत्कर्मकृन्मत्परमः इत्यादिना स्वभजनमुक्तम्। तत्र मच्छब्दार्थः किं सगुणमुत निर्गुणं ब्रह्म। उभयत्राप्यस्मच्छब्दस्य पूर्वं प्रयोगदर्शनात्संदिहानः पृच्छति -- एवमिति। एवमित्यव्यवहितं मत्कर्मकृदित्यादिनोक्तं प्रकारं परामृशति। अनेन प्रकारेण ये सततयुक्ता नित्यं समाहितचित्ता भक्ताः सगुणवेदिनस्त्वां पर्युपासते? ये चाप्यक्षरमस्थूलादिलक्षणमव्यक्तं बुद्ध्याद्यगोचरमुपासते तेषां मध्ये योगवित्तमाः के कतरे इत्यर्थः।'),
('nilakantha-sc:source:12.2','Nīlakaṇṭha','gita.12.2','sa','commentary','।।12.2।।निर्गुणस्य दुष्प्रापत्वोक्त्यैव श्रेष्ठत्वं सूचयन् सगुणप्राशस्त्यं च शब्दतो दर्शयन् श्रीभगवानुवाच -- मयीति। मयि सगुणे ब्रह्मणि मन आवेश्य प्रवेश्य ये नित्ययुक्ताः सदोद्युक्ता मां परमेश्वरमुपासते चिन्तयन्ति श्रद्धया आस्तिक्यबुद्ध्या परया सात्विक्या अवश्यं परमात्मायमाराधितोऽस्मांस्तारयिष्यतीत्येवं निश्चयरूपया श्रद्धया उपेतास्ते मे ममज्ञानी त्वात्मैव मे मतम् इति ज्ञानिनमात्मत्वेनैव पश्यतो मूर्खेष्वपि कारुण्यात्पक्षपातवतः सर्वज्ञस्य युक्ततमा मताः।'),
('nilakantha-sc:source:12.3','Nīlakaṇṭha','gita.12.3','sa','commentary','Sri Neelkanth did not comment on this sloka'),
('nilakantha-sc:source:12.4','Nīlakaṇṭha','gita.12.4','sa','commentary','।।12.4।।एवंविधमक्षरं कथमुपासनीयमित्यत आह -- संनियम्येति। सर्वत्र काले सर्वदा। एतेन ध्यानस्य,नैरन्तर्यमुक्तम्। इन्द्रियग्रामं समनस्कानीन्द्रियाणि संनियम्य एकीभावेनात्मनि वशे कृत्वा। स्वकारणे प्रविलाप्येत्यर्थः। समा चाञ्चल्यहीना बुद्धिर्येषां ते समबुद्धयो ये भवन्ति तेऽपि मामेव निर्विकल्पं परं ब्रह्म परां काष्ठां प्राप्नुवन्ति। श्रुतिश्चयदा पञ्चावतिष्ठन्ते ज्ञानानि मनसा सह। बुद्धिश्च न विचेष्टति तामाहुः परमां गतिम्। इति। सर्वभूतहिते रता इत्यनेन सर्वभूताभयदानेन संन्यासोऽपि ध्यानाङ्गमिति विधीयते।'),
('nilakantha-sc:source:12.5','Nīlakaṇṭha','gita.12.5','sa','commentary','।।12.5।।अस्या गतेर्दुष्प्रापत्वमाह -- क्लेश इति। यद्यपि सगुणविदामधिकः क्लेशोऽस्त्येव तथापि ते सालम्बना ध्यायन्ति सोपानारोहक्रमेण परां काष्ठां प्रविशन्ति। येषां तु निरालम्बं ध्यानमाकाशयुद्धसमं तेषां निर्विषये चेतःस्थिरीकरणेऽधिकतरः क्लेशोऽस्ति। तत्र क्रमिकध्यानप्रयोगः शुद्धे चिन्मात्रे विश्वरूपं माययाध्यस्तम्। तत्र च केवलमातिवाहिकं कृत्स्नं जडमाधिभौतिकमध्यस्तम्। यथोक्तं वसिष्ठेनआतिवाहिक एवायं त्वादृशैश्चित्तदेहकः। आधिभौतिकया बुद्ध्या गृहीतश्चिरभावनात्।। इति। अतिक्रम्य पाषाणादीन्वहति इष्टदेशं नयत्यभिमानिनमित्यतिवाहि सर्वत्राप्रतिहतगतिकं भूतसूक्ष्मं तेन निर्वत्त आतिवाहिकोऽयं कृत्स्नः प्रपञ्चो यतश्चित्तदेहकः चित्तमेव देहः स्वरूपमस्येति स्वप्नतुल्य एव सन् चिरभावनात् वज्रपञ्जरवत्काठिन्येनोपेत आधिभौतिकया स्थूलभूतप्रभवया बुद्ध्या गृहीत इति श्लोकार्थः। एवं च यथा तीव्राभिनिवेशेन निरीक्ष्यमाणो रज्जूरगः स्वयं शाम्यति तदधिष्ठानभूता रज्जुश्चाविर्भवति तथा वस्तुतश्चिद्रूपायामपि माधवादिमूर्तौ जाड्यमध्यस्तं तामेवाभिनिवेशेन चिरकालं चर्मचक्षुषैव पश्यतस्तस्या मूर्तेर्जाड्यं तिरोधीयते चैतन्यमाविर्भवति। अतएव बाणादयः स्वाराध्यैः सार्धं स्वामिभृत्यन्यायेन व्यवहरन्तीति सर्वत्रोपाख्यायते। एवमचेतनाया मूर्तेरपि तत्त्वं विश्वरूपमेवेति मूर्तिमेवात्यादरेण पश्यंस्तस्यास्तत्त्वं विश्वरूपमवगच्छति यदपश्यदर्जुनो वासुदेवदेहे एतदेव वितर्कजं प्रत्यक्षं प्रकृत्योक्तं भगवता योगभाष्यकारेण बादरायणेनतत्परं प्रत्यक्षं तच्च श्रुतानुमानयोर्बीजम् इति। स्थूलालम्बनः समाधिर्वितर्कः। विश्वरूपस्याप्यस्मितामात्रेऽध्यासात्तस्यावलोकनेऽस्मितामात्रमवशिष्यते। अस्मिताया अपि शुद्धायां चितावध्यस्तत्वात्तस्यामपि समाहिते मनसि सहैव मनसाऽस्मिता तिरोधीयते शुद्धा चितिरेवावशिष्यते इति। एवं व्यक्तासक्ताः सोपानारोहक्रमेण परां काष्ठां प्रतिपद्यन्ते। ये तु अव्यक्तासक्ताः पक्षिवदकस्मादूर्ध्वं पदमारुरुक्षन्ति ते लयेन विक्षेपेण च भृशं बाध्यन्ते। लयमेव च कदाचित्समाधित्वेनाभ्युपगच्छन्तीति तेषां पराभवसंभावनाप्यस्तीत्यत उक्तं क्लेशोऽधिकतरस्तेषामव्यक्तासक्तचेतसामिति। हि यस्मादव्यक्ता निरालंबना गतिः पदप्राप्तिर्देहवद्भिर्देहाभिमानिभिर्दुःखं यथास्यात्तथा अवाप्यते न तु सा सुखप्राप्येति भावः।'),
('nilakantha-sc:source:12.6','Nīlakaṇṭha','gita.12.6','sa','commentary','।।12.6।।ननु अव्यक्तासक्तचेतसां क्लेशाधिक्येऽपि क्लेशान्ते सद्यः कैवल्यसिद्धिरस्तीति किं विलम्बसाध्येन व्यक्तभावनेनेत्याशङ्क्याह -- ये त्विति द्वाभ्याम्। सर्वाणि नित्यनैमित्तिकस्वाभाविकादीनि संन्यस्य समर्प्य मत्परा अहमेव परः सर्वकर्मभिः प्राप्यो येषां ते मत्पराः मद्ध्यानपरा वा। अनन्येन भेदशून्येन अहमेव भगवान्वासुदेव इति परमेश्वरेऽहंग्रहलक्षणेन योगेन चेतःसमाधानेन मां ध्यायन्त उपासते तत्रैव ध्याने स्थैर्यं लभन्ते।'),
('nilakantha-sc:source:12.7','Nīlakaṇṭha','gita.12.7','sa','commentary','।।12.7।।तेषां ध्यायिनां नचिराच्छीघ्रमेवाहं समुद्धर्ता समुद्धरणकर्ता। यतस्ते मयि सगुणे विश्वरूपे आवेशितचेतसो भवन्ति अतो व्यक्तासक्ता अपि शीघ्रमेव परं पदमारोढुमर्हा इति नाव्यक्तेऽत्यन्ताभिनिवेष्टव्यमिति भावः।'),
('nilakantha-sc:source:12.8','Nīlakaṇṭha','gita.12.8','sa','commentary','।।12.8।।यस्मादेवं तस्मान्मय्येव विश्वरूपे ईश्वरे मनः संकल्पविकल्पात्मकमाधत्स्व स्थापय। मय्येवाध्यवसायं कुर्वतीं बुद्धिं निवेशय तत्फलं च। निवसिष्यसि निवत्स्यसि निश्चयेन मदात्मना मयि वासं करिष्यसि। अतः शरीरपातादूर्ध्वं। न संशयः कर्तव्यः।'),
('nilakantha-sc:source:12.9','Nīlakaṇṭha','gita.12.9','sa','commentary','।।12.9।।विश्वरूपधारणायामशक्तं प्रति प्राह -- अथेति। मयि विश्वेश्वरे अथ यदि चित्तं समाधातुं निवेशितुमचलं धारयितुं न शक्नोषि ततस्तर्ह्यभ्यासयोगेन चित्तस्यैकस्मिन्नाभ्यन्तरे बाह्ये वा प्रतिमादावालम्बने सर्वतः समाहृत्य पुनःपुनःस्थापनमभ्यासस्तत्पूर्वको योगः समाधानलक्षणस्तेनाभ्यासयोगेन मां विश्वरूपमाप्तुं प्राप्तुमिच्छ प्रार्थयस्व हे धनंजय।'),
('nilakantha-sc:source:12.10','Nīlakaṇṭha','gita.12.10','sa','commentary','।।12.10।।अभ्यासेऽपीति। अभ्यासे पूर्वश्लोकोक्ते। मत्कर्मश्रवणं कीर्तनं विष्णोः स्मरणं पादसेवनम्। अर्चनं वन्दनं दास्यं सख्यमात्मनिवेदनम् इति नवविधभजनात्मकं भगवत्प्रीत्यर्थं कर्म मत्कर्मशब्दितं तदेव परममावश्यकं यस्य तादृशो भव। कर्माणि श्रवणादीनि। सिद्धिं सत्वशुद्धिम्।'),
('nilakantha-sc:source:12.11','Nīlakaṇṭha','gita.12.11','sa','commentary','।।12.11।।मद्योगं श्रवणादौ निष्ठाम्। तर्हि पूर्वोक्तं श्रौतस्मार्तसर्वकर्मफलत्यागं कुर्वित्यर्थः। यतात्मवान् यतश्च नियमादिमांश्च आत्मवान् जितचित्तश्चेति यतात्मवान्।'),
('nilakantha-sc:source:12.12','Nīlakaṇṭha','gita.12.12','sa','commentary','।।12.12।।इममेव त्यागं सर्वपुरुषार्थमूलत्वात्स्तौति -- श्रेयो हीति। अभ्यासान्निदिध्यासनाज्ज्ञानं श्रवणमननजं परोक्षं श्रेयः। ज्ञानादपि ध्यानं विष्णोः श्रवणकीर्तनादि विशिष्यते। ततोऽपि कर्मफलत्यागः श्रेयान्। यस्मादनन्तरमव्यवधानेन शान्तिर्मोक्षोऽस्ति चित्तशुद्ध्याद्युत्पादनद्वारेण। अत्र बाह्यं साधनं सुकरत्वात्पूर्वपूर्वापेक्षया प्रशस्तमित्युच्यते तत्रैव प्रवृत्त्यतिशयाय। यद्वा श्रवणाद्यभ्यासात्तज्जं ज्ञानं तत्त्वनिश्चयात्मकं श्रेयः। ततोऽपि ज्ञातस्यार्थस्य साक्षात्कारार्थं ध्यानं श्रेयः। ततोऽपि कर्मफलत्यागः। योगी हि सर्वकर्मत्यागीप्रजहाति यदा कामान् इति प्रोक्तः। अयमपि कर्मफलत्यागेन कामाञ्जहात्येवेति तेन सम इति स्तूयते।'),
('nilakantha-sc:source:12.13','Nīlakaṇṭha','gita.12.13','sa','commentary','।।12.13।।परमप्रकृतस्याक्षरस्योपासकं स्तौति तद्गुणकथने हि साधकानां तेषु गुणेष्वादरो भविष्यतीति बुद्ध्याह -- अद्वेष्टेति। अद्वेष्टा चेदुदासीनः स्यान्नेत्याह। मैत्रः मित्रमेव मैत्रो नतूदासीनः कदाचिदपि। नन्वन्यस्मिन् शत्रौ सति कथं मैत्रत्वं स्यात्तत्राह -- करुण इति। दुःखदातारमपि करुणया न बाधितुमीष्टे अपितु त्रातुमेवेच्छति। एतेन सर्वभूताभयप्रदः संन्यासी उक्तः। अतएव तस्य निर्मम इति विशेषणं युज्यते। मुख्यमक्षरविदो लक्षणं निरहंकार इति। अहंकारो हि सर्वानर्थनिदानं स एव निर्गतो यस्मात्स निरहंकारः। अतएव समे दुःखसुखे यस्य।तत्र को मोहः कः शोक एकत्वमनुपश्यतः इति श्रुतेः। क्षमी क्षमावान्परिभवप्राप्तावपि स्वस्थचित्तः। अन्योऽपि मुमुक्षुरेतान्धर्माननुतिष्ठेदित्यर्थः।'),
('nilakantha-sc:source:12.14','Nīlakaṇṭha','gita.12.14','sa','commentary','।।12.14।।संतुष्टो यदृच्छालाभेनैव संजातालंप्रत्ययः। सततं सर्वदा। योगी श्रवणादौ समाहितचित्तः। यतात्मा संयतशरीरेन्द्रियादिसंघातः। दृढः स्थिर आत्मतत्त्वविषये निश्चयो यस्य स दृढनिश्चयोऽसंभावनाशून्यो दृढश्रद्धावान्। मयि निर्गुणे ब्रह्मण्यर्पिते निहिते प्रविलापिते वा मनः संकल्पादिरूपं बुद्धिरध्यवसायस्ते उभे येन स मय्यर्पितमनोबुद्धिः। एतादृशो यो मे मम भक्तः स मे मम प्रियः आत्मत्वादेव स परमप्रेमास्पदम्ज्ञानी त्वात्मैव मे मतम् इत्युक्तम्। एतेन पूर्वश्लोकोक्ताया निरहंकारतायाः साधनान्युक्तानि।'),
('nilakantha-sc:source:12.15','Nīlakaṇṭha','gita.12.15','sa','commentary','।।12.15।।स च निरहंकारो द्विविधः। समाधिस्थो व्युत्थितश्च। तयोर्लक्षणं क्रमेणाह द्वाभ्याम् -- यस्मादिति। यस्मात्समाधिस्थत्वेन काष्ठसमाल्लोको नोद्विजते न त्रस्यति। लोकादपि यो निर्मनस्कत्वान्नोद्विजते। अतएव हर्ष इष्टलाभे सति मनस उत्फुल्लता। अमर्षोऽसहिष्णुता। भयमात्मोच्छेदशङ्का। उद्वेगस्तत्कृतैव व्याकुलता। एतैर्निर्मनस्कत्वादेव स्वयमेव मुक्तस्त्यक्तः। नत्वेतान्स्वयं त्यक्तुं यतते साधकवत्। ईदृशो यो मद्भक्तः स च मे प्रियः।'),
('nilakantha-sc:source:12.16','Nīlakaṇṭha','gita.12.16','sa','commentary','।।12.16।।अस्यैव व्युत्थानावस्थामाह -- अनपेक्ष इति। सुखप्राप्तौ दुःखहाने वा तत्साधने वा लिप्साशून्योऽनपेक्षः। शुचिः बाह्याभ्यन्तरशौचवान् पुण्यापुण्याभ्यामलिप्तो वा। दक्षः भगवद्भजनादावनलसः। उदासीनो मानापमानादौ समवृत्तिः। अतएव गता व्यथा चेतःपीडा यस्य स गतव्यथः। सर्वारम्भपरित्यागी संन्यासित्वादेव। यो मद्भक्तः स मे प्रियः।'),
('nilakantha-sc:source:12.17','Nīlakaṇṭha','gita.12.17','sa','commentary','।।12.17।।एतमेव श्लोकं व्याचष्टे त्रिभिः श्लोकैः -- यो नेति। इष्टलाभे सति न हृष्यति। अनिष्टप्राप्तौ न द्वेष्टि। इष्टवियोगे सति न शोचति। इष्टसंयोगमनिष्टपरिहारं वा न काङ्क्षति। अनपेक्षत्वात्। शुभं कल्याणं पुण्यं अशुभममङ्गलं पापं च ते उभे परित्युक्तं शीलमस्य स शुभाशुभपरित्यागी। एतेन शुचित्वं व्याख्यातम्।,भक्तिमान्भक्तौ सततोद्युक्त इति दक्ष इत्यर्थः।'),
('nilakantha-sc:source:12.18','Nīlakaṇṭha','gita.12.18','sa','commentary','Sri Neelkanth did not comment on this sloka'),
('nilakantha-sc:source:12.19','Nīlakaṇṭha','gita.12.19','sa','commentary','।।12.19।।सर्वारम्भपरित्यागीत्येतद्व्याचष्टे -- तुल्येति। शिष्टेषु विगीतो न स्यामिति वा लोकेषु प्रख्यातः स्यामिति वा इदं मे भूयादिति वा कामयमानः किंचिदारभते नत्वयम्। तुल्यनिन्दास्तुतित्वात्संतुष्टत्वाच्च। मौनी संन्यासी। अतएवानिकेतो गृहशून्यः कुटीमपि वासार्थं नारभते। यतः स्थिरमतिः स्थितप्रज्ञो भक्तिमान्योगी मे मम प्रियो नरः पुरुषः।'),
('nilakantha-sc:source:12.20','Nīlakaṇṭha','gita.12.20','sa','commentary','।।12.20।।मुक्तलक्षणान्येव मुमुक्षोः साधनत्वेन विधत्ते -- ये त्विति। ये मुमुक्षवः तु पूर्वोक्तमुक्तापेक्षया विलक्षणाः। इदं अद्वेष्टा सर्वभूतानाम् इत्यादिना ग्रन्थेन प्रतिपादितं धर्मजातं तदेवामृतस्य मोक्षस्य साधनत्वादमृतं धर्मामृतम्। यथोक्तमुक्तानतिक्रमेण पर्युपासते साकल्येनानुतिष्ठन्ति। श्रद्दधानाः श्रद्धायुक्ताः मत्परमाः अहमेव भगवान्वासुदेवोऽक्षराख्यः सर्वविशेषरहितः परमानन्दरूपः परमः पार्यन्तिकः प्राप्यो येषां ते मत्परमाः भक्ताः शान्तिदान्त्यादिमन्तो मद्भजनशीलास्तेऽतीव मे मम प्रियाः। ज्ञानी तु भगवत आत्मैव। परिशेषादतीव प्रियत्वं भक्तेष्वेव पर्यवसन्नम्। यो मुक्तानां स्वाभाविको धर्मः स मुमुक्षुणा यत्नतोऽनुष्ठेय इत्यर्थः। यथोक्तं वार्तिकेउत्पन्नात्मप्रबोधस्य ह्यद्वेष्टृत्वादयो गुणाः। अयत्नतो भवन्त्येव न तु साधनरूपिणः। इति। समाप्त उपासनाप्रधानस्तत्पदार्थविवेकः। अतःपरं वाक्यार्थविचारो जीवब्रह्माभेदप्रतिपादको भविष्यति। ,'),
('nilakantha-sc:source:13.2','Nīlakaṇṭha','gita.13.1','sa','commentary','।।13.2।।ननु अव्यक्तोऽयमचिन्त्योऽयमविकार्योऽयमुच्यते। नित्यः सर्वगतः स्थाणुरचलोऽयं सनातनः इति द्वितीये त्वंपदार्थस्वरूपमुक्तम्। तथा द्वादशे ये त्वक्षरमनिर्देश्यमव्यक्तं पर्युपासते। सर्वत्रगमचिन्त्यं च कूटस्थमचलं ध्रुवम् इति तत्पदार्थस्वरूपमुक्तम्। न च तयोर्भेदः संभवति। लक्षणैक्यात्। लक्षणं हि तयोरव्यक्तत्वमचिन्त्यत्वमचलत्वं सर्वगतत्वं चेत्यादि समानम्। न च द्वयोः सर्वगतत्वं संभवति। अन्योन्यव्यावृत्तत्वेनासर्वगतत्वापत्तेः। न च लक्षणभेदाभावेऽपि तत्तदात्मगतविशेषाः सन्ति ये मुक्तात्मनां जीवेशयोश्चान्योन्यं भेदमावहन्ति स्वात्मानं च स्वाश्रयात्स्वयमेव व्यावर्तयन्तीति वाच्यम्। विशेषाणां सत्त्वे प्रमाणाभावात्। ननु मा सन्तु विशेषाः बन्धमोक्षादिव्यवस्थान्यथानुपपत्त्या तु निर्विशेषेष्वपि पुरुषेषु भेदः सिध्यति। यथोक्तं सांख्यवृद्धैःजन्ममरणकरणानां प्रतिनियमादयुगपत्प्रवृत्तेश्च पुरुषबहुत्वं सिद्धं त्रैगुण्यविपर्ययाच्चैव इति। जन्मादिव्यवस्थातो युगपत्प्रवृत्त्यदर्शनात् सात्विकराजसादिभेदाच्च न पुरुषैक्यमित्यर्थ इति चेन्न। व्यापकानेकात्मवादे भोगसांकर्यप्रसङ्गात्। नह्येकत्रान्तःकरणे सुखादिरूपेण परिणते तत्प्रतिसंवेदी एक एव चेतन इति नियन्तुं शक्यम्। सर्वेषां सान्निध्याविशेषेण प्रतिसंवेदनापत्तेरवर्जनीयत्वात्। श्रोत्रस्यैकस्यापि कर्णशष्कुलीरूपोपाधिभेदादिवान्तःकरणरूपोपाधिभेदादेकस्याप्यात्मनः शब्दग्रहव्यवस्थावज्जन्मादिव्यवस्थापि सेत्स्यतीति न पुरुषबहुत्वं वक्तव्यम्। ततश्च जीवेशयोर्लक्षणैक्यादभेदे सिद्धे किमुत्तरग्रन्थेन तत्प्रतिपादनार्थेनेति चेत्सत्यम्।यत्र त्वस्य सर्वमात्मैवाभूत्तत्केन कं पश्येत् इति श्रुतेर्विद्यावस्थायां भेदाभावेऽपि अविद्यावस्थायांअन्तःप्रविष्टः शास्ता जनानाम्एष ह्येव साधु कर्म कारयति तं यमेभ्यो लोकेभ्य उन्निनीषते इतिव्यवहारदशायां शास्यशासितृभावेन कर्तृकारयितृभावेन च प्रसक्तस्य जीवेश्वरयोर्भेदस्य निरासार्थत्वादुत्तरग्रन्थस्यारम्भ उपपद्यते। तत्रानुपदोक्तेन तत्पदार्थेन सहास्याभेदं वक्तुं योग्यतायै भास्यभासकभावेन क्षेत्रात्क्षेत्रज्ञस्य कुम्भाद्भास्वत इव विवेकं दर्शयति -- इदमिति। इदमनात्मत्वेन भास्यं घटाद्यहंकारान्तं शरीरं विशरणधर्मि हे कौन्तेय? क्षेत्रं क्षिणोत्यात्मानमविद्यया त्रायते च विद्ययेति क्षेत्रं कर्मबीजप्ररोहस्थानं क्षेत्रशब्देनोच्यते। एतद्यो वेत्ति भासयति तं चिदात्मानं क्षेत्रज्ञ इत्यन्वर्थसंज्ञं प्राहुः। के प्राहुः। तद्विदः क्षेत्रक्षेत्रज्ञविदः। एतेन गच्छामि पश्यामि भुञ्जे इत्यनुभवाद्देहेन्द्रियाहंकाराः प्रतीतितो भासककोटिनिविष्टा इव भान्ति तथापि तेषां तत्त्वतो भास्यत्वलक्षणोऽनात्मभावः सिद्धः।'),
('nilakantha-sc:source:13.3','Nīlakaṇṭha','gita.13.2','sa','commentary','।।13.3।।तमेवंलक्षणमुपाधितो निष्कृष्टं क्षेत्रज्ञं चात्क्षेत्रमपि मां परमेश्वरमेवोभयरूपेण सन्तं विद्धि।तत्त्वमस्यहं ब्रह्मास्मि ब्रह्मैवेदं सर्वं सर्वं खल्विदं ब्रह्म इति शास्त्रात्। यस्मादुभयात्माहं तस्मात्क्षेत्रक्षेत्रज्ञयोर्यज्ज्ञानं क्षेत्रस्य बाध्यत्वेन क्षेत्रज्ञस्य सर्वबाधावधिभूतत्वेन च यज्ज्ञानमापरोक्ष्येण तत्त्वनिश्चयस्तदेव ज्ञानं मम मद्विषयं सम्यग्ज्ञानं एतयोरेव ज्ञानं ब्रह्मज्ञानमिति मतं निश्चितं ब्रह्मविद्भिःनेह नानास्ति किंचन इति क्षेत्रस्य बाधात्नान्योतोऽस्ति द्रष्टा इति क्षेत्रज्ञादन्यस्य द्रष्टुर्निषेधाच्च। यद्यपि सर्वस्य ब्रह्माभिन्नत्वाद्यत्किञ्चिदपि ज्ञानं तत्सर्वं ब्रह्मविषयमेव भवति। तथापि रज्जुं सर्पात्मना पश्यतो न तु रज्जुविषयं सर्पविषयं वा सम्यग्ज्ञानमस्ति। नापि तस्य ज्ञानस्य रज्जुव्यतिरेकेण विषयान्तरं वास्तवमस्ति। किंतु यदा सर्पबाधेन रज्जुतत्त्वमधिगच्छति तदैव सर्पं मिथ्यायमिति सम्यग्जानाति रज्जुं च। तद्वदिहाप्युभयविदेव सम्यग्ज्ञानीत्यर्थः। नह्यन्यतरस्य तत्त्वे ज्ञाते कृतकृत्यतास्ति। न हि सांख्यो निर्विशेषात्मविदपि प्रपञ्चमबाधमानः शून्यवादी वा प्रपञ्चं तुच्छत्वेन पश्यन्नधिष्ठानं ब्रह्म नास्तीति ब्रुवाणः कृतकृत्यो भवतीति वक्तुं युक्तम्। अतो द्वयोरपि तत्त्वं बोध्यमेव।'),
('nilakantha-sc:source:13.4','Nīlakaṇṭha','gita.13.3','sa','commentary','।।13.4।।क्षेत्रक्षेत्रज्ञपदे विवरीतुमारभते -- तदिति। यच्चेदं क्षेत्रं निर्दिष्टं तत् यादृक् यादृशं स्वकीयैर्धर्मैरस्ति। यद्विकारि ये च तस्य विकाराः यतश्च यत् यस्माद्विकाराद्यज्जायत इति प्राञ्चः। तत्पूर्वोक्तं क्षेत्रं यच्च यत्स्वरूपं यादृक् यत्प्रकारकं यद्विकारि ये च तस्य विकाराः यतश्च क्षेत्रावयवाद्यज्जायते तत् शृणु। तथा स च क्षेत्रज्ञः यो यत्स्वरूपः यत्प्रभावश्च तदपि मत्तः शृणु।'),
('nilakantha-sc:source:13.5','Nīlakaṇṭha','gita.13.4','sa','commentary','।।13.5।।वक्ष्यमाणेऽर्थे प्रमाणमाह -- ऋषिभिरिति। ऋषिभिर्वसिष्ठाद्यैर्बहुधा गीतं योगवासिष्ठादौ प्रतिपादितम्। छन्दोभिर्वेदैर्मन्त्रैर्वा पृथक् प्रतिशाखमनेकप्रकारं गीतम्। ब्रह्मसूत्रपदैः ब्रह्मणः सूचकानि पदानि समुच्चित्य वाक्यभावमापन्नानि तैर्ब्रह्मसूचकैर्ब्राह्मणवाक्यैः। तत्त्वमसीत्याद्यैरित्यर्थः। हेतुमद्धिःअन्नेन सोम्य शुङ्गेनापोमूलमन्विच्छ अद्भिः सोम्य शुङ्गेन तेजोमूलमन्विच्छ तेजसा सोम्य शुङ्गेन सन्मूलमन्विच्छ सन्मूलाः,सोम्येमाः प्रजाः इत्यादिना कार्यलिङ्गान्यनुमानानि ब्रह्माधिगमाय प्रदर्शयन्तो हेतवस्तद्वद्भिः। विनिश्चितैरसकृदभ्यासेन सकलशङ्कापङ्कक्षालनेन निश्चितार्थैः क्षेत्रक्षेत्रज्ञयोः स्वरूपमेतैः सर्वैर्यद्गीतं तच्छृण्विति पूर्वेण संबन्धः।'),
('nilakantha-sc:source:13.6','Nīlakaṇṭha','gita.13.5','sa','commentary','।।13.6।।तच्च यच्च यादृक् च यद्विकारि चेत्येतद्व्याचष्टे -- महाभूतानीति। चकारो भिन्नक्रमो बुद्धिश्चेति बुद्धिपदादुपरि द्रष्टव्यः। यत्क्षेत्रं शरीराख्यमुक्तं तदव्यक्तमेव।शरीरं रथमेव तु इति श्रुतौ अव्यक्तपदेन पञ्चतन्मात्रा उच्यन्ते। अहंकारो तत्प्रकारमाह -- महाभूतान्यहंकारो बुद्धिश्चेति सप्तप्रकारैरङ्कुरितम्। महाभूतशब्देन पञ्चतन्मात्रा उच्यन्ते। अहंकारो बुद्धिरिति महत्तत्त्वमुच्यते। स्वप्ने हि एतान्येव करणानि भासन्ते तत्प्रकारक एव भूतगण इति तावत्प्रकारकमेव क्षेत्रमित्युक्तम्। यद्विकारीत्यस्योत्तरमाह -- इन्द्रियाणीति। इन्द्रियाणि दशैकं चेत्येकादश। पञ्च ज्ञानेन्द्रियाणि श्रोत्रत्वक्चक्षुरसनघ्राणानि पञ्च कर्मेन्द्रियाणि वाक्पाणिपादपायूपस्थाख्यानि मनश्चेत्येकादश। इन्द्रियाणां गोचरा विषयाः स्थूला वियदादयः पञ्च अयं षोडशको विकार एव। एतान्येव सांख्यैश्चतुर्विंशतितत्त्वानि गण्यन्ते। एतावांस्त्वस्माकं विशेषः। तैः स्वतन्त्रा सत्या च प्रकृतिरुच्यते अस्माभिर्मायारूपा मिथ्या ईश्वराधीना चोच्यत इति। तथा च श्रुतिःमायां तु प्रकृतिं विद्यान्मायिनं तु महेश्वरम् इति। तस्मात्सांख्यप्रक्रियात्र भगवताश्रितेति न भ्रमितव्यम्।'),
('nilakantha-sc:source:13.7','Nīlakaṇṭha','gita.13.6','sa','commentary','।।13.7।।यतश्च विकाराद्यज्जायत इत्युक्तं तदाह -- इच्छेति। इच्छा सुखे तत्साधने वा स्पृहारूपा चित्तवृत्तिरिदं मे भूयादिति सा काम इति राग इति चोच्यते। द्वेषो दुःखे तत्साधने चेदं मे माभूदिति स्पृहाविरोधिनी चेतोवृत्तिः। सुखदुःखे प्रसिद्धे। संघातःआत्मेन्द्रियमनोयुक्तं भोक्तेत्याहुर्मनीषिणः इति श्रुतेरिन्द्रियमनश्चिदात्मनामेकलोलीभावरूपो भोक्ता। चेतना या पूर्वोक्ता बुद्धिः सैव शुद्धा सत्त्वमयत्वाद्विमलादर्शवच्चित्प्रतिबिम्बग्राहिणी तप्तायःपिण्डे वह्नित्वमिव स्वयमचेतनापि चेतनात्वं प्राप्ता यया व्याप्तः स्थूलपिण्डोऽपि चेतन एव प्रतीयते सेयं चेतना मनःसंज्ञिता सैव इच्छादिरूपा परिणमते। तथा च श्रुतिःकामः संकल्पो विचिकित्सा श्रद्धाऽश्रद्धा धृतिरधृतिर्ह्रीर्धीर्भीरित्येतत्सर्वं मन एव इति कामादीनां मनोवृत्तित्वमाह। एतत्क्षेत्रमव्यक्ताख्यं विकारं विकारेण महदादिना तद्विकारेण चेच्छादिना सहितमुदाहृतमुक्तम्। नन्विच्छादयोऽहंप्रत्ययविषयस्यात्मनो धर्मा इति काणादा वदन्ति। सत्यमेव वदन्ति ते परंतु सोऽस्माकं मुख्य आत्मैव न भवति? तस्य शुद्धायां चित्यभेदेनाध्यस्तत्वादिति प्रागेवोक्तम्। अतः क्षेत्रान्तर्गतस्याहमर्थस्य दृश्यस्य तादृशा एव दृश्या इच्छादयो धर्माः सन्तु न नः किञ्चिच्छिन्नम्। आत्मनोऽसङ्गत्वमहंकारस्यानृतत्वं चानुभवसिद्धं श्रुती अप्यनुवदतःअसङ्गो ह्ययं पुरुषः इतिअमृतेन हि प्रत्यूढाः इति।'),
('nilakantha-sc:source:13.8','Nīlakaṇṭha','gita.13.7','sa','commentary','।।13.8।।इदानीं ज्ञानसाधनानि विधत्ते -- अमानित्वमिति। अमानित्वादयोऽपि चेतोवृत्तिविशेषा दृश्यत्वाच्च तत्क्षेत्रविकारा एव सन्तः सत्त्वगुणकार्यत्वात् ज्ञानस्य साधनभूता अप्युपचाराज्ज्ञानपदवाच्या भवन्ति।एतज्ज्ञानमिति प्रोक्तम् इत्युपसंहारात्। तत्र विद्यमानैरविद्यमानैर्वा गुणैरात्मनः श्लाघित्वं मानित्वम्। लाभपूजाख्यात्यर्थं स्वधर्मस्य प्रकटीकरणं दम्भित्वम्। कायवाङ्मनोभिः प्राणिनां पीडनं हिंसा। तेषां वर्जनममानित्वमदम्भित्वमहिंसा च। परेणापकृतेऽपि चित्तस्य निर्विकारत्वं क्षान्तिः। आर्जवमकौटिल्यम्। आचार्योपासनं स्पष्टम्। शौचं मृज्जलाभ्यां बाह्यं भावशुद्धिरान्तरम्। स्थैर्यं मोक्षसाधने प्रवृत्तस्य विघ्नसद्भावेऽपि तदगणनम्। आत्मविनिग्रहो देहेन्द्रियादिप्रचारसंकोचः।'),
('nilakantha-sc:source:13.9','Nīlakaṇṭha','gita.13.8','sa','commentary','।।13.9।।इन्द्रियार्थेषु दृष्टेषु आनुश्रविकेषु वा शब्दादिषु वैराग्यं रागाभावः। अनहंकारो दर्पराहित्यम्। अयोगव्यवच्छेदार्थ एवकारः। समुच्चयार्थश्चकारः। जन्मादिषु जायमानं दुःखं परस्य व्यथादोषाश्च दैन्यादयस्तेषामनुदर्शनम्।'),
('nilakantha-sc:source:13.10','Nīlakaṇṭha','gita.13.9','sa','commentary','।।13.10।।असक्तिरिति। सक्तिः पुत्रादौ ममतामात्रम्। अभिष्वङ्गस्तेन सह तादात्म्याभिमानोऽयमेवाहमिति च। पुत्रादेः सुखेऽहमेव सुखी तस्य दुःखेऽहमेव दुःखीति सङ्गाभिष्वङ्गौ तद्वर्जनमित्यर्थः। समचित्तत्वं हर्षविषादराहित्यम्। कुत्र इष्टानिष्टोपपत्तिषु इष्टप्राप्तौ हर्षाभावोऽनिष्टप्राप्तौ विषादाभावः।'),
('nilakantha-sc:source:13.11','Nīlakaṇṭha','gita.13.10','sa','commentary','।।13.11।।मयीतिश्लोकः स्पष्टार्थः।'),
('nilakantha-sc:source:13.12','Nīlakaṇṭha','gita.13.11','sa','commentary','।।13.12।।अध्यात्मशास्त्रजे ज्ञाने निष्ठावहमध्यात्मज्ञाननित्यत्वम्। तत्त्वज्ञानस्यार्थः प्रयोजनमविद्यानिवृत्तिरानन्दावाप्तिश्च तयोर्दर्शनम्। एतदमानित्वादितत्त्वज्ञानार्थदर्शनान्तं विंशकं ज्ञानं ज्ञानसाधनमिति प्रोक्तं वेदेषु। अज्ञानं ज्ञानविरोधि इतोऽन्यथा यत्तत् मानित्वादिकमित्यर्थः। तस्मात्तत्परित्यागेनामानित्वादिकमेवोपादेयमिति भावः।'),
('nilakantha-sc:source:13.13','Nīlakaṇṭha','gita.13.12','sa','commentary','।।13.13।।एवं क्षेत्रं व्याख्याय स च यो यत्प्रभावश्चेत्युक्तं क्षेत्रज्ञस्वरूपं तस्य मायिकं प्रभावं व्याचष्टे -- ज्ञेयमिति। एतैर्ज्ञानसाधनैर्यज्ज्ञेयं तत्प्रवक्ष्यामि। यज्ज्ञेयं ज्ञात्वा अमृतं मोक्षमश्नुते प्राप्नोति। तस्य स्वरूपं तावदाह -- अनादिमदिति। आदिमत् अव्यक्तम्तस्मादव्यक्तमुत्पन्नम् इति तदुत्पत्तिस्मरणात्। तदन्यदनादिमत्। अनादीत्येतावत्युक्ते प्रवाहनित्यत्वमव्यक्तादीनामप्यस्तीति तेषामप्यनादितायां प्राप्तायां तत्प्रतिषेधार्थमनादिमदित्युक्तम्। यद्वा आदिमच्च ततः परं चादिमत्परे कार्यकारणे ताभ्यामन्यदनादिमत्परमिति। अतएव परं निर्विशेषं नत्वपरं सविशेषम्। ब्रह्म त्रिविधपरिच्छेदशून्यम्। न सत् प्रधानपरमाण्वादिवत्सदिति नोच्यते। नाप्यसत् शून्यवदसदपि नोच्यते। तथा च श्रुतिःनासदासीन्नो सदासीत्तदानीं नासीद्रजो नो व्योमा परो यत् इति। असच्छब्दितस्य शून्यस्य सच्छब्दितस्य प्रधानस्य रजःशब्दितानां परमाणूनां परव्योमशब्दितस्य अस्मदभिमतस्याव्यक्तस्यापि सृष्टेः प्राक् निषेधं दर्शयति।'),
('nilakantha-sc:source:13.14','Nīlakaṇṭha','gita.13.13','sa','commentary','।।13.14।।एवं स च य इत्येतत्क्षेत्रज्ञस्वरूपमपास्तसमस्तविशेषमुपपाद्य यत्प्रभाव इति प्रतिज्ञातं तस्य प्रभाव वैश्वरूप्यलक्षणमुपपादयति -- सर्वत इति। सर्वतः सर्वासु दिक्षु अन्तर्बहिश्च पाणयः पादाश्चास्य सन्तीति सर्वतःपाणिपादम्। एवं सर्वतः अक्षीणि शिरांसि मुखानि च यस्य तत्सर्वतोऽक्षिशिरोमुखम्। सर्वतःश्रुतिमत् श्रवणवत्। लोके सर्वं आवृत्य व्याप्य तिष्ठति। यथा स्वप्नदृक् तैजसो वासनामयेनैव पाणिपादादिना स्वाप्नं प्रपञ्चमनुभवति। तस्य च जाग्रत्काले उपाधिभूतं पिण्डगतमेव पाणिपादादिकं तदेव स्थूलप्रपञ्चानुभवसंस्काराधानद्वारा वासनामयस्य प्रपञ्चस्य कारणम्। वासनामयश्च स्थूलप्रपञ्चस्य कारणमिति बीजाङ्कुरन्यायेनानयोरन्योन्यस्मिन्नन्योन्यसद्भावोऽन्योन्यकारणत्वं चास्तीति। एवं सकलप्राणिधीवासनोपरक्ताज्ञानोपाधिकं चैतन्यं सकलप्राणिधीवासनामयं समष्टिसूक्ष्मप्रपञ्चमवभासयति। अस्य चोपाधिभूतं ब्रह्माण्डगतसकलप्राणिपादादिकमेव। एवं च पूर्ववत्स्थूलसूक्ष्मयोरपि समष्टिप्रपञ्चयोरन्योन्यं बीजाङ्कुरन्यायेन कार्यकारणभावमन्योन्यस्यान्योन्यस्मिन्सद्भावं चाभिप्रेत्योक्तं भगवता भाष्यकारेण सकलप्राणिकरणोपाधिद्वारेण ज्ञेयब्रह्मणोऽस्तित्वं प्रतिपाद्यत इति। कार्यद्वारा करणास्तित्वसिद्धौ च कारणाभावोऽप्यपोद्यतेअनादिमत्परं ब्रह्म न सत्तन्नासदुच्यते इति। ननुप्रक्षालनाद्धि पङ्कस्य दूरादस्पर्शनं वरम् इति न्यायेन व्यर्थस्तर्हि कारणोपन्यास इति चेन्न। तं विना शुद्धाधिगमायोगात्। शाखाचन्द्रन्यायेन हि सगुणं निर्गुणस्य वस्तुनो ज्ञापकम्। यथोक्तं भाष्ये उपाधिकृतमिथ्यारूपमप्यस्तित्वाधिगमाय ज्ञेयधर्मवत्परिकल्प्योच्यते सर्वतःपाणिपादमित्यादि। तथाहि संप्रदायविदां वचनम्अध्यारोपापवादाभ्यां निष्प्रपञ्चं प्रपञ्च्यते इति।'),
('nilakantha-sc:source:13.15','Nīlakaṇṭha','gita.13.14','sa','commentary','।।13.15।।ननु यूपाहवनीयादिवदलौकिकमपि ब्रह्म कार्यकारणप्रपञ्चविशिष्टं चित्रमेव सर्वतःपाणिपादं तदित्यादिना शास्त्रेण कार्यशेषतया समर्थ्यते। न च वाच्यं उपासनापरं शास्त्रं न ब्रह्मणो वैचित्र्यं प्रतिपादयितुमीष्टे इति। देवताधिकरणन्यायेन देवताविग्रहादिवत्तद्वैचित्र्यस्याप्यवान्तरतात्पर्यविषयतयासिद्धेः। न च देवताविग्रहादेर्व्यावहारिकमेव सत्त्वं न पारमार्थिकं ब्रह्मज्ञानेन तस्य बाधादिति वाच्यम्। सत्ताद्वैविध्यस्याप्रसिद्धेः। तस्मात्सर्वतःपाणिपादत्वादिकं ब्रह्मणो वास्तवमेवेति नापवादमर्हतीत्याशङ्क्याह -- सर्वेन्द्रियेति। सर्वाणि आन्तराणि बाह्यानि च इन्द्रियाणि मनोबुद्ध्यहंकारचित्ताख्यानि श्रोत्रादीनि चेति ग्राहकमात्रसंगृहीतम्। गुणाश्च विषयाः तेन ग्राह्यमात्रं गृह्यते। समस्तग्राह्यग्राहकवदाभासते न तु ग्राह्यग्राहकस्वरूपं विचित्रम्। यथा जलसूर्योऽधस्थ इव कम्पत इवाभासते न तु वस्तुतोऽधस्थः कम्पते वा तद्वत् आत्मनो ग्राह्यग्राहकाकारत्वं मिथ्येत्यर्थः। कुत एतत्। यतः सर्वेन्द्रियविवर्जितं इन्द्रियेति गुणानामप्युपलक्षणम्। नहि ब्रह्मणि किञ्चित् ग्राह्यं रूपादि ग्राहकं वा मन आदि वर्तते।अशब्दमस्पर्शमरूपमव्ययंअप्राणो ह्यमनाः शुभ्रःयत्तदद्रेश्यमग्राह्यमचक्षुःश्रोत्रं तदपाणिपादम् इत्यादिशास्त्रात्। तस्मान्न प्रपञ्चविशिष्टं विचित्रं ब्रह्म। कथं तर्हि सर्वं ब्रह्मेति शास्त्रमित्याशङ्क्याह -- असक्तं सर्वभृच्चैवेति। अत्र सर्वभृदिति सर्वाधारत्वोक्त्या,सर्वस्मात्पृथग्भूतमित्युक्तम्। सर्वस्य ब्रह्मणा सहाधाराधेयभावोऽपि किं घटरूपयोरिव समवायसंबन्धेन? कुण्डबदरयोरिव संयोगसंबन्धेन वेत्याशङ्क्य संबन्धं विनैव सर्वभृत्त्वं ब्रह्मणा इत्याह -- असक्तमिति। ननु व्याहतमेतत् असक्तमिति सर्वभृदिति चेति। नैष दोषः। नह्यूषरभूमिर्मरीचिकोदकेन संसक्ता अथ च तदाधारभूतापि भवति तद्वदेतद्भविष्यति। नन्वेवं प्रपञ्चस्य मिथ्यात्वमापततीति। तथा च कर्मोपास्तिविधय उपरुध्येरन्। न। ब्रह्मात्मैकत्वज्ञानेन यावद्द्वैतं न बाध्यते तावत्िक्रयाकारकादिसर्वव्यवहारस्य सत्यत्वोपगमात्प्राणा वै सत्यं तेषामेष सत्यम् इति श्रुत्यापि प्राणोपलक्षितस्य कृत्स्नस्य प्रपञ्चस्य व्यावहारिकं सत्यत्वमुक्त्वा ततोऽप्यधिकं परमार्थसत्यं ब्रह्म दर्शितम्। सत्यत्वं चाबाध्यत्वं तत्किंचित्कालं प्राणानामस्ति ब्रह्मणस्तु सार्वत्रिकमिति यथा भूपतीनां भूपतिरित्युक्ते ऐश्वर्याल्पत्वभूयस्त्वकृतो भेदः स्पष्ट एवमिहापि द्रष्टव्यम्। तस्माद्ब्रह्मणः सविशेषत्वं निष्कलात्मबोधात्प्रागेव नतूर्ध्वमित्यवश्यं तत्त्वज्ञानेन बाधितुं शक्यमित्यनुपाधिकं ब्रह्म न केनचित्कार्यशेषतां नेतुं शक्यम्। तदधिगमे क्रियाकारकादिद्वैतोपमर्दादुपास्योपासकोपासनाभेदस्य बाधितत्वात्। तस्माद्युक्तमुक्तमुपाधिकृतं रूपं मिथ्येति। किं च निर्गुणं गुणभोक्तृ च। ग्राह्यग्राहकसंबन्धशून्यमपि ग्राहकेषु बुद्ध्यादिषु ग्राह्यसंबन्धात्सुखाद्याकारेण परिणतेषु सत्सु केवलं तत्प्रकाशकत्वमात्रेण गुणभोक्तृत्वमप्यस्य चिदाभासरूपस्योपपद्यते। यथा प्रतिबिम्बरूपे रवावुपाधिकृतं चलनादिकम्। तथा च श्रुतिःध्यायतीव लेलायतीवेति। बुद्धौ ध्यायन्त्यां तत्र प्रविष्टश्चिदाभासो ध्यायतीव विषयान्। बुद्धौ लेलायन्त्यां विषयप्रदेशं गच्छन्त्यां सोऽपि लेलायतीव न तु स्वतो ध्यायति लेलायति वेति प्रतिपादयति। एतेनअपाणिपादो जवनो ग्रहीता पश्यत्यचक्षुः स शृणोत्यकर्णः इत्यपि ब्रह्मण उपाधिगुणानुगुण्यभजनशक्तिमत्त्वेनैव व्याख्येयम्। अयमपादोऽपि पादे जववति जववान् भवतीति। अन्धो मणिमविन्ददित्यादिकं वचनजातं चात्रानुसंधेयम्। तस्माद्युक्तमुक्तं निर्गुणं गुणभोक्तृ चेति। भाष्ये तु निर्गुणं सत्त्वादिगुणरहितमपि तेषां गुणानां सुखदुःखमोहात्मकत्वेन परिणतानां भोक्तृ च उपलब्धृ चेति व्याख्यातम्।');
INSERT INTO commentary_fts (unit_id,author,canonical_ref,language,content_type,content) VALUES
('nilakantha-sc:source:13.16','Nīlakaṇṭha','gita.13.15','sa','commentary','।।13.16।।नन्वसक्तमसंबद्धं चेत्कथमुपलब्धं स्यादित्याशङ्क्याह -- बहिरिति। भूतानां प्राणिनामेकादशेन्द्रियाणि स्थूलभूतानि च केवलविकारत्वेन व्यवहितत्वात् बहिरित्युच्यन्ते। महदहंकारपञ्चतन्मात्राव्यक्तानि प्रकृतिरूपत्वेन संनिहितत्वादन्तरित्युच्यन्ते। चराचरमिति। उभयनिकृष्टाश्चराचरोपाध्युपलक्षिता अवधिभूताः पुरुषाश्चरमचरं चेत्यनेनोच्यन्ते। तत्र चराचरं ज्ञेयमिति सामानाधिकरण्यात्पुरुषाणां ज्ञेयब्रह्मभाव उक्तः। बहिरन्तश्च ज्ञेयमिति षोडशसु विकारेष्वष्टासु प्रकृतिषु च ज्ञेयस्य संबन्ध उक्तः। स च संबन्धो यादृशो यक्षस्तादृशो बलिरितिन्यायेनाध्यस्तप्रकृतिविकृतिनिरूपितत्वेनाध्यस्त एव। एवं च पुरुषस्योपलब्धिमात्रशरीरस्य गुणैः सहाध्यासिकसंबन्धसत्त्वात् गुणोपलब्धृत्वं युज्यते। यथा प्रकाशमात्रस्वरूपस्य रवेः प्रकाश्यसंबन्धापेक्षं प्रकाशयितृत्वं तद्वदित्यर्थः। ननु नित्यापरोक्षः पुरुषप्रकृतिविकारसंबद्धश्च तर्हि कुतो न सर्वैर्गृह्यत इत्याशङ्क्याह। सूक्ष्मत्वात् दुर्लक्ष्यत्वात्तज्ज्ञेयं। अविज्ञेयं दुर्विज्ञेयम्। यथा जपाकुसुमोपहितस्य स्फटिकस्य शौक्ल्यं सन्निहितमपि रूपान्तरविक्षेपेण तिरोहितं सन्न गृह्यते एवं नित्यापरोक्षमप्यसङ्गं ब्रह्मोपाध्युपधानाद्विविक्ततया न ग्रहीतुं शक्यं किंत्वौपाधिकधर्मोपेतमेव गृह्यते मूढैः। विद्वद्भिस्तूपाधिप्रविलापनेन सुग्रहमित्याशयः। एतदेवाह -- दूरस्थं चान्तिके च तदिति। यथा मूढो जलसूर्यं बिम्बसूर्याद्दूरस्थं मन्यते विद्वांस्तु उपाधिप्रतिहतनयनरश्मीनामुपर्युत्प्लुत्य गतानां बिम्बग्राहित्वं स्पष्टम्। बिम्बस्याधस्थत्वग्रहणं तु पूर्वप्रवृत्ताधोमुखवृत्तिसंस्कारापेक्षमिति जानन् बिम्बदेशे एव प्रतिबिम्बं पश्यति। बिम्बे एव जलस्थत्वमध्यस्य तेन तु जले प्रतिबिम्ब इति। उपाधौ धर्म्यध्यासकल्पनातो विषयस्योपाधिसंसर्गमात्राध्यासकल्पने लाघवात्। एवं बिम्बभूतं ब्रह्म प्रतिबिम्बभूताज्जीवान्मूढानां विप्रकृष्टं विदुषां त्वत्यन्तं संनिकृष्टमिति।'),
('nilakantha-sc:source:13.17','Nīlakaṇṭha','gita.13.16','sa','commentary','।।13.17।।एतदेवोपपादयत्यर्धेन -- अविभक्तं चेति।एक एव तु भूतात्मा भूते भूते व्यवस्थितः। एकधा बहुधा चैव दृश्यते जलचन्द्रवत् इति श्रुतेर्भूतेषु कार्यकारणसंघातापन्नेषु जलपात्रेषु चन्द्रस्येव ब्रह्मणः प्रतिबिम्बा जीवास्ते चोक्तरीत्या बिम्बादनन्या इति तद्रूपेण भूतेष्वविभक्तं च विभागमप्राप्तमपि ज्ञेयवस्तु मूढदृष्ट्या विभक्तमिव दूरदेशस्थमिव चाद्विभिन्नमिव च स्थितम्। एवं तर्हि चन्द्रादुदपात्राणामिव भूतानां पृथक्सत्त्वापत्तिरित्याशङ्क्याह -- भूतभर्तृचेति। अधिष्ठानत्वेन सर्वाणि भूतानि धारयतीति न ततस्तेषां पृथक्सत्तास्ति रज्जुत इव तदध्यस्तानां सर्पदण्डधारादीनामित्यर्थः। एतदेवाह -- ग्रसिष्णु प्रभविष्णु च। यथा रज्जुस्त्वज्ञानदशायां सर्पादीन् ग्रसति अज्ञानदशायां च तानेव प्रसूते तद्वत् ज्ञातं ब्रह्म सर्वभूतानि ग्रसिष्णु ग्रसनशीलमज्ञातं च सर्वभूतानां प्रभविष्णु उत्पादनशीलम्।'),
('nilakantha-sc:source:13.18','Nīlakaṇṭha','gita.13.17','sa','commentary','।।13.18।।एवं ज्ञेयस्य तटस्थलक्षणमुक्त्वा स्वरूपलक्षणमाह -- ज्योतिषामिति। ज्योतिषां बाह्यानामादित्यादीनामान्तराणां च बुद्ध्यादीनामितरावभासकानामपि तज्ज्ञेयं ब्रह्म ज्योतिरवभासकं। चैतन्यज्योतिषो जडज्योतिरवभासकत्वोपपत्तेः। तथा च श्रुतयःयेन सूर्यस्तपति तेजसेद्धःतस्य भासा सर्वमिदं विभाति इत्याद्याः। वक्ष्यति चयदादित्यगतं तेजः इत्यादि। तमसोऽज्ञानात् भूतग्रासप्रसवहेतोः परं दूरस्थं तदुच्यते। ननु यथा चान्द्रस्य ज्योतिषोऽवभासकं तत्सजातीयं सौरं ज्योतिरिति ज्योतिःशास्त्रे प्रसिद्धम्। एवं सौरादिज्योतिषामप्यवभासकं किंचित्तत्सजातीयं ज्योतिरलौकिकं स्यादित्याशङ्क्याह -- ज्ञानमिति। केवलज्ञप्तिमात्रशरीरं यज्ज्योतिर्नतु भौतिकं तदेव ज्ञेयं वस्तु आवृतत्वाज्ज्ञानेन प्राप्तुमिष्टतमम्। कुतस्तर्हि तज्ज्ञानमत आह -- ज्ञानगम्यमिति। यतस्तज्ज्ञानेनामानित्वादिना ज्ञानसाधनेन गम्यं प्राप्यम्। किं तर्हि ग्रामान्तरवद्देशव्यवहितं वा बाल्ययौवनाद्यवस्थान्तरवत्कालव्यवहितं वा तत्प्राप्यमस्तीत्यत आह -- हृदि सर्वस्य विष्ठितमिति। स्वात्मभूतमेव तदन्तर्दृष्टीनां सम्यक्प्रकाशत इत्यर्थः।'),
('nilakantha-sc:source:13.19','Nīlakaṇṭha','gita.13.18','sa','commentary','।।13.19।।उक्तमर्थजातमुपसंहरति -- इतीति। क्षेत्रं महाभूतादिधृत्यन्तम्। ज्ञानं ज्ञानसाधनममानित्वादि तत्त्वज्ञानार्थदर्शनान्तम्। ज्ञेयमनादिमत्परमित्यादि धिष्ठितमित्यन्तम्। श्रुतिभ्यः स्मृतिभ्यश्च समासतः संक्षेपत उक्तम्। मद्भक्त एतत्त्रयं विज्ञाय मद्भावाय ब्रह्मभावायोपपद्यते युक्तो भवति। भक्त्यैव प्राप्यं ब्रह्म यत्प्राप्य ब्रह्मैव भवति। तथा च श्रुतिःयस्य देवे परा भक्तिर्यथा देवे तथा गुरौ। तस्यैते कथिता ह्यर्थाः प्रकाशन्ते महात्मनः इति।ब्रह्म वेद ब्रह्मैव भवति इति च।'),
('nilakantha-sc:source:13.20','Nīlakaṇṭha','gita.13.19','sa','commentary','।।13.20।।एवं क्षेत्रं शरीराख्यमव्यक्तमुक्तं तत्प्रकाराश्च महदाद्यास्त्रयोविंशतिस्तद्विकारा इच्छादयो ज्ञानाज्ञानशब्दिता अमानित्वमानित्वादयः पुरुषश्च उक्तः। इदानीं क्षेत्रक्षेत्रज्ञयोर्मध्ये यस्माद्यज्जायते तच्च क्षेत्रज्ञस्य प्रभावश्चेति द्वयं वक्तव्यं तत्राद्यं विवृणोति त्रिभिः -- प्रकृतिमिति। सप्तमाध्यायेऽष्टधा या प्रकृतिरपरा उक्ता सात्र प्रकृतिः। या तु जीवभूता परा प्रकृतिरुक्ता सात्र पुरुषशब्देनोच्यते। एतौ हि संपृक्तौ संसारं जनयतः। वियोगश्च तयोर्मोक्षः। तत्र तावुभावप्यनादी विद्धि। तयोरादिमत्त्वे संसारस्याकस्मिकत्वापातात् कृतहानाकृताभ्यागमप्रसङ्गश्चेत्यन्यत्र विस्तरः। विकारान् इच्छादीन् गुणान् बुद्धीन्द्रियादींश्च प्रकृतिसंभवान् विद्धि।'),
('nilakantha-sc:source:13.21','Nīlakaṇṭha','gita.13.20','sa','commentary','।।13.21।।उभयोरपि संसारं प्रति कारणत्वे द्वारमाह -- कार्येति। कार्यं शरीरं तदारम्भकाणि भूतानि विषयाश्च। कारणं त्रयोदशेन्द्रियाणि तदाश्रिताश्च सुखदुःखमोहात्मका गुणाश्च। करणेतिपाठेऽपि स एवार्थः। एतयोः कार्यकारणयोः कर्तृत्वे निमित्ते सति कर्तृत्वेनेत्यर्थः। हेतुः संसारस्य कारणं प्रकृतिर्भवति। तथा पुरुषः सुखदुःखानां भोक्तृत्वेन संसारस्य हेतुरिति। यदि हि कार्यकारणसुखदुःखस्वरूपहेतुफलात्मना प्रकृतिर्न परिणमेत तदा पुरुषः किमुपलभेत। अनुपलब्ध्वा वा कथं संसारी स्यात्। अनुपलब्धृका वा प्रकृतिः कुत्रोपयुज्येत। तस्मादुपलभ्योपलब्धृसंयोगः संसारकारणमिति यथाभाष्यं व्याख्यातम्। यद्वा पुरुषस्य कार्यत्वे कारणत्वे कर्तृत्वे च प्रकृतिरेव पुरुषतादात्म्यं प्राप्ता हेतुर्भवति। वह्नितादात्म्यं प्राप्तं लोहं वह्नेश्चतुष्कोणत्वादाविव हेतुर्भवति? तथा प्रकृतेः सुखदुःखभोक्तृत्वे स्वच्छायाप्रदानेन पुरुषः कारणम् वह्निरिव लोहस्य स्वच्छायाप्रदानेन दग्धृत्वे। तथाहि कार्यत्वादयः प्राकृतदेहेन्द्रियबुद्धिधर्माः सन्तश्चिदात्मन्यारोप्यन्ते गौरोऽहममुष्यपुत्रोऽहं काणोऽहं खञ्जोऽहं करोम्यहमकार्षमहमिति। तथा चिच्छायापन्ना बुद्धिश्चेतयाम्यहं सुखदुःखादीनुपलभे इति मन्यते। सोऽयं प्रकृतिपुरुषयोरन्योन्यधर्माध्यासः संसारस्य कारणमित्युपपादितं भवति। सांख्याभिमतं पुरुषस्य भोक्तृत्वमपि निरस्तं भवति। अन्यथा प्रकृतिः कर्त्री पुरुषो भोक्तेति कर्तृत्वभोक्तृत्वयोर्वैयधिकरण्यमापद्येत। न च भोक्तुः पुरुषस्य निर्विकारत्वमपि वक्तुं शक्यमित्यन्यत्र विस्तरः। द्वन्द्वान्ते श्रूयमाणं पदं प्रत्येकमभिसंबध्यत इति त्वप्रत्ययस्य पूर्वाभ्यामपि संबन्धे कार्यत्वं कारणत्वं कर्तृत्वं चेति विग्रहः द्वन्द्वैकवद्भावश्चप्रातिपदिकार्थलिङ्गपरिमाणवचनभावे प्रथमा इत्यादिवत्।'),
('nilakantha-sc:source:13.22','Nīlakaṇṭha','gita.13.21','sa','commentary','।।13.22।।ननु यथा बौद्धं कर्तृत्वं पुंस्यारोप्यते एवं पौंस्नं भोक्तृत्वं बुद्धावस्त्वित्येतं भ्रमं वारयति -- पुरुष इति। हि प्रसिद्धम्। प्रकृतिस्थः देहेन्द्रियमनःसंघातमध्यारूढस्तत्तादात्म्यं गत इत्यर्थः। प्रकृतिजान् सुखदुःखमोहात्मकान् गुणान् भुङ्क्ते उपलभते। यदा तु सुप्तिसमाधिमूर्च्छादौ प्रकृतिस्थत्वं नास्ति तदा न,सुखादीनुपलभते तेनोपाधिगतान्येव सुखादीनि तदभावेन प्रतीयन्त इति सिद्धम्। श्रुतिरपिआत्मेन्द्रियमनोयुक्तं भोक्तेत्याहुर्मनीषिणः इतीन्द्रियमनोयोगादेवात्मनि भोक्तृत्वं दर्शयन्ति शुद्धस्य केवलस्य भोक्तृत्वं नास्तीति दर्शयति। कुतस्तर्ह्यभोक्तुरप्यस्य प्राकृतो बन्ध इति तत्राह -- कारणमिति। अस्य पुरुषस्य सदसद्योनिजन्मसु तत्र सद्योनिजन्मानो देवाः? असद्योनिजन्मभाजस्तिर्यञ्चः स्थावराश्च। सदसद्योनिजन्मानो मनुष्याः। एतेषु त्रिष्वपि जन्मसु प्राप्येषु अस्य पुंसो गुणसङ्गः सुखादिष्वभिष्वङ्गः कारणं हेतुः। तथा हि सात्विका देवा भवन्ति राजसा मनुष्यास्तामसाश्च पशवस्तेषां तत्तद्योनिप्राप्तौ तद्गुणप्राधान्यमेव कारणम्। वक्ष्यति चऊर्ध्वं गच्छन्ति सत्वस्थाः इत्यादि। यद्वा प्रकृतिस्थो विद्वानविद्वान्वा गुणान्भुङ्क्ते।पश्वादिभिश्चाविशेषात् इति न्यायात्। तत्किं विद्वानिवाविद्वानपि कुतो न मुच्यते अविद्वानिव विद्वान्वा कुतो न बध्यत इत्याशङ्क्याह -- कारणमिति। गुणेषु देहेन्द्रियविषयेषु सङ्गः अहमिदं ममेदमित्यभिनिवेशः स एव जन्मकारणम्। विदुषां तु तदभावान्न जन्म। समानेऽपि देहसंबन्धे यदा यक्षो देहाभिमानं धत्ते तदा स एव देहपीडया पीड्यते न तु देहपतिर्जीवः। यदा त्वयं देहाभिमानं धत्ते तदा नेतर इति प्रसिद्धम्। सङ्गस्य बन्धकत्वं न तु सांनिध्यमात्रं बन्धकम्। अतो विद्वदविदुषोः समानेऽपि देहसंबन्धे सङ्गतदभावकृतो महान् विशेष इति भावः।'),
('nilakantha-sc:source:13.23','Nīlakaṇṭha','gita.13.22','sa','commentary','।।13.23।।स च यो यत्प्रभावश्चेति क्षेत्रज्ञतत्प्रभावौ व्याख्येयत्वेन प्रतिज्ञातौ तत्र क्षेत्रज्ञः प्रागेव वर्णितः तस्येदानीं प्रभावमाह -- उपद्रष्टेति। तत्र पूर्वं गुणसङ्गो जन्मकारणमित्युक्तम्। तत्र सङ्गश्चतुर्विधः पुरुषापलापेन गुणमात्रप्राधान्येन वा तमन्तर्भाव्य गुणप्राधान्येन वा? गुणानां समप्राधान्येन वा? अप्राधान्येन वेति। तत्राद्ये देहेन्द्रियमन आदिरूपं गुणसंघातमेव आत्मत्वेन पश्यन् भोक्ता भवति यथा चार्वाकादिः। द्वितीये गुणानां प्राधान्यादात्मनि वास्तवकर्तृत्वाद्यभिमानेन कर्मफलानां भर्ता संचेता भवति यथा तार्किकादिः। तृतीये गुणानां समप्राधान्येन गुणगतमपि भोक्तृत्वमसंगेऽप्यात्मनि वस्त्रे भल्लातकाङ्कवदनुमन्यते यथा सांख्यः। चतुर्थे सर्वथापि गुणधर्माणामात्मनि संक्रममपश्यन्नुदासीनबोधरूपत्वेन गुणप्रचारदर्शी उपद्रष्टा भवति यथास्माकं साक्षी। एतेषु चतुर्ष्वपि गुणसंगिषूपद्रष्टोत्तमः। अनुमन्ता मध्यमः। भर्ता अधमः। भोक्ता अधमाधमः। स एव गुणान्वशीकृत्य यदा क्रीडति तदा महेश्वर इत्युच्यते। यः सर्गस्थित्यन्तकर्ता प्रभुर्जगदन्तर्यामी स एव गुणानपहाय स्थितः परमात्मेति चाप्युक्तो भवति। यद्यप्युपद्रष्टापि गुणानपहाय तत्साक्षित्वेन स्थितो भवति तथापि तस्यैव संघातोपहितस्य संघातान्तरप्रचारदर्शित्वाभावादयं सकलसंघातप्रचारदर्शीति सर्वोत्कृष्टत्वात्परमोऽयमात्मा। तमेनं वक्ष्यतिउत्तमः पुरुषस्त्वन्यः परमात्मेत्युदाहृतः। यो लोकत्रयमाविश्य बिभर्त्यव्यय ईश्वरः इति। एतावपि गुणसङ्गिनौ। एवमेक एव देहेऽस्मिन्विद्यमानः परो गुणातीतः स्वात्मनि गुणान्प्रविलाप्य स्थितोऽखण्डैकरस आत्मा गुणसङ्गेन षड्विधो भवति। अयमेवास्य प्रभावः। तत्र अनुमन्तृभर्तृभोक्तृभिस्त्रिभिः रूपैरयं बध्यते। उपद्रष्टृमहेश्वरपरमात्मरूपैस्तु नित्यमुक्त एकएवेति ज्ञेयम्। अत्र भाष्यार्थोऽप्यनुसंधेयो विस्तरभयात्तु न प्रदर्शितः।'),
('nilakantha-sc:source:13.24','Nīlakaṇṭha','gita.13.23','sa','commentary','।।13.24।।एवं यथोक्तलक्षणात्मज्ञाने फलमाह -- य एवमिति। गुणैः स्वविकारैः सर्वथा विहितेन निषिद्धेन वा कर्मणा वर्तमानोऽपि न स भूयोऽभिजायते पुनर्जन्म न लभते मुक्तो भवतीत्यर्थः।'),
('nilakantha-sc:source:13.25','Nīlakaṇṭha','gita.13.24','sa','commentary','।।13.25।।एवंविधात्मदर्शनेऽधिकारिभेदेनोपायविकल्पानाह -- ध्यानेनेति। अत्र ये आत्मानं विविदिषन्ति ते निष्कामकर्मणा परमेश्वरमाराधयन्ति ते कर्मयोगिनः। तत एवोत्पन्नविविदिषा वेदान्तश्रवणे प्रवर्तन्ते। ततः प्रमाणगतासंभावनानिवृत्तौ सत्यां तस्यैवार्थस्य मनने प्रवर्तन्ते प्रमेयगतासंभावनानिवृत्त्यर्थं ते सांख्याः। ततः प्रमाणप्रमेयगतासंभावनाया निवृत्त्यनन्तरं अनात्मनि देहादावात्मबुद्धिरूपाया विपरीतभावनाया निवृत्त्यर्थं निदिध्यासनं विजातीयप्रत्ययतिरस्कारपूर्वकसजातीयप्रत्ययप्रवाहीकरणलक्षणं कर्तुं प्रवर्तन्ते। ततस्तत्परिपाके आत्मनि बुद्धिवृत्तौ आत्मानं परमेश्वरं पश्यन्ति ते ध्यायिनः। तत्र ये कर्मसांख्ययोर्निष्णातास्ते ध्यानेनात्मनि देहे आत्मानं परमेश्वरं आत्मना बुद्ध्या पश्यन्ति। अन्ये त्वकृतकर्माणः सांख्येन योगेन विचारात्मकेन योगेन ध्यानद्वारा पश्यन्ति। अन्ये पुनः कर्मयोगेनैव पूर्वोक्तलक्षणेन सांख्या ध्यानद्वारा पश्यन्तीति साधनत्रयस्य समुच्चयो न तु विकल्पः।'),
('nilakantha-sc:source:13.26','Nīlakaṇṭha','gita.13.25','sa','commentary','।।13.26।।पक्षान्तरमाह -- अन्येत्विति। अन्ये ऊहापोहकौशलहीनाः। तुशब्देन पूर्वोक्तेभ्यो विलक्षणाः एवं पूर्वोक्तप्रकारमजानन्तोऽन्येभ्य आचार्येभ्यः श्रुत्वा आत्मनो निर्विशेषब्रह्मचैतन्यरूपत्वं तदुपासनामार्गं चाधिगत्य उपासते यथोक्तप्रकारेण ध्यायन्ति तेऽपि च मृत्युं संसारं तरन्त्येव। अपिशब्दात्पूर्वश्लोकोक्तास्तरन्तीत्यत्र,किमाश्चर्यमिति गम्यते। एवशब्दात्तेषां मुख्यक्रमाभावेऽपि तरणे संशयो नास्ति। यतस्ते श्रुतिपरायणाः श्रुतिः श्रवणं तदेव परं अयनं मोक्षसाधनं येषां ते तथा। ध्याने प्रवृत्त्यतिशयान्न तेषां चित्तशुद्ध्यर्थं कर्मापेक्षा। वेदोक्ततत्त्वे दृढनिश्चयाच्चासंभावनानिवृत्त्यर्थं श्रवणमननापेक्षेति भावः। अयं च ब्रह्मसाक्षात्कारः संवादिभ्रमरूप इति केचित्। प्रमारूप इत्यन्ये। तथाहि यथा कश्चिन्मणिप्रभां मणिबुद्ध्या पश्यन् भ्रान्त एव तथापि तद्ग्रहणकाले मणिं लभतेऽतः स संवादिभ्रमः। एवं त्वंपदार्थं तत्पदार्थमणिप्रभाभूतं तत्पदार्थबुद्ध्या भावयन् व्यवहारतो भ्रान्त एव तथापि तत्साक्षात्कारकाले तदनन्यस्य तत्पदार्थस्य साक्षात्कारोऽपि संवादिभ्रमन्यायेन जायत इति। तथा च वसिष्ठःअसत्ये सत्यता साधो शाश्वती परिदृश्यते। शून्येन ध्यानयोगेन शाश्वतं प्राप्यते पदम् इति। व्यवहारतो निर्विशेषस्वरूपत्वेनासत्ये आत्मनि तत्र निर्विशेषत्वभावनं शून्यो निर्विषयोऽयं ध्यानयोगो योषित्यग्निध्यानवत् तथापि तेन शाश्वती सत्यता प्राप्यते दृश्यत इति वसिष्ठवाक्यार्थः। कल्पद्रुमाचार्यास्तुवेदान्तवाक्यजध्यानभावनाजाऽपरोक्षधीः। मूलप्रमाणदार्ढ्येन भ्रमत्वं प्रतिपद्यते इति प्राहुः।'),
('nilakantha-sc:source:13.27','Nīlakaṇṭha','gita.13.26','sa','commentary','।।13.27।।पूर्वं कार्यकारणकर्तृत्वे इत्यत्र चिदचितोः पुंप्रकृत्योरन्योन्यधर्माध्यास उक्तस्तस्यैव गुणसङ्गरूपस्य कारणं गुणसङ्गोऽस्येति नानाजन्महेतुत्वं चोक्तं तद्विशदयति -- यावदिति। सत्त्वं जीवरूपम्। गुणसङ्गोऽत्र रूपाद्यासक्तिर्न किंतु क्षेत्रक्षेत्रज्ञयोः संयोगोऽन्योन्यस्मिन्नन्योन्यात्मकताध्यासलक्षणो बोध्यः। शेषं स्पष्टम्।'),
('nilakantha-sc:source:13.28','Nīlakaṇṭha','gita.13.27','sa','commentary','।।13.28।।तन्नाशोपायमाह -- सममिति। सममपरिणामिनं कूटस्थं नित्यं सर्वेषु भूतेषु देहाद्याकारेण परिणतेषु तिष्ठन्तम्। एतेन देह एव तदधिगमस्थानमित्युक्तम्। परमेश्वरमन्तर्यामिणं सर्गस्थित्यन्तकर्तारम्। अतएवान्तर्मुखदृष्ट्या विनश्यत्सु तेषु भूतेषु रज्जूरगादिवत्कल्पितत्वाददर्शनं गच्छत्सु विभुत्वादात्मत्वान्नित्यदृग्रूपत्वाच्चाविनश्यन्तं सर्वास्वप्यवस्थास्वदर्शनमगच्छन्तं यः पश्यति स एव पश्यति अन्येऽन्धा इत्यर्थः।'),
('nilakantha-sc:source:13.29','Nīlakaṇṭha','gita.13.28','sa','commentary','।।13.29।।दर्शनफलमाह -- सममिति। स्वदेहे इव सर्वत्र देहमात्रे समवस्थितं सम्यगवस्थितमीश्वरं समं समतया पश्यन् हि यतः स सर्वाभेददर्शी आत्मना देहादिना आत्मानं ईश्वरं न हिनस्ति नानायोनिसंकटेषु पातनेन न पीडयति किंतु ततः परां गतिं मोक्षं याति। यद्वा ऐकात्म्यदर्शित्वात्स्वात्मानमिवान्यमपि न हिनस्ति। सर्वत्र दयालुर्भवतीति भावः। ततश्च परां गतिं याति।'),
('nilakantha-sc:source:13.30','Nīlakaṇṭha','gita.13.29','sa','commentary','।।13.30।।ननु विषमस्वभावानि भूतानि कः समबुद्ध्या पश्यत्यग्निमिव शीतबुद्ध्येत्याशङ्क्याह -- प्रकृत्यैवेति। सर्वशः सर्वप्रकारेण कर्माणि वाङ्मनःकायैरारब्धानि प्रकृत्यैव क्रियमाणानीति यः पश्यति तथा आत्मानं चाकर्तारं यः पश्यति पूर्वोक्तरीत्या स एव सर्वत्र समं पश्यतीति पूर्वेणान्वयः।'),
('nilakantha-sc:source:13.31','Nīlakaṇṭha','gita.13.30','sa','commentary','।।13.31।।ननु कथं प्रकृतेरेव कर्तृत्वं नत्वात्मन इत्याशङ्क्याह -- यदेति। भूतानां वियदादीनां जरायुजादीनां च पृथग्भावं नानाभावेनावस्थानं परिदृश्यमानमिदं यदा एकस्थं एकस्मिन्नात्मनि स्थितं रज्ज्वां सर्पादिवत्? कनके वा कुण्डलादिवत् विलीनं शास्त्राचार्योपदेशमनुपश्यति। तत् एवैकस्मात् विस्तारं च भूतपृथग्भावस्य व्युत्थानावस्थामनु स्वप्नादिवत् पश्यति तदा ब्रह्म संपद्यते ब्रह्मैव भवति। अयं भावः। कर्तृत्वं हि क्रियावत्त्वं क्रिया च परिस्पन्दः स च परिच्छन्नस्य पृथग्भूतस्य प्राकृतस्य बुद्ध्यादेरेव संभवति न तु व्यापकस्य सर्वभूतपृथग्भावग्रसिष्णोरात्मन इति।'),
('nilakantha-sc:source:13.32','Nīlakaṇṭha','gita.13.31','sa','commentary','।।13.32।।नन्वात्मनो विभुत्वेन रूपेण कर्तृत्वं मास्वीकारि देहाद्यवच्छिन्नेन तु रूपेण तद्वक्तव्यमन्यथानुभवविरोधादित्याशङ्क्याह -- अनादित्वादिति। अयं सर्वेषां प्राणिनां नित्यापरोक्षः परमो देहादिभ्योऽपरमेभ्य आत्मभ्योऽन्यः कोशपञ्चकातीत आत्मा परमात्मा। अव्ययः न व्येति परिच्छिद्यते देशतः कालतो वस्तुतश्चेत्यव्ययः। अव्ययत्वे हेतुः -- अनादित्वादिति। यद्धि आदिमदाकाशादि तद्व्येति न त्वयं व्येति अनादित्वात्। नन्वनादिभावस्यानन्त्यनियमेनात्मनः कालतः परिच्छेदो मास्तु। तथा देशतः परिच्छिन्नस्य नाशावश्यंभावादनादित्वायोगाच्च देशतोऽपि परिच्छेदो ब्रह्मणो मास्तु। ननु परमाणुवद्भविष्यतीतिचेन्न। दशदिगवच्छेद्यप्रदेशभेदवतो द्रव्यस्य निरवयवत्वरूपाणुत्वासिद्धेः। नहि परमाणोः पूर्वदिगवच्छिन्नो भागः पश्चिमया व्यवच्छेत्तुं शक्यते अनुभवविरोधात्। देशतः परिच्छेदाभावादेव सजातीयविजातीयवस्तुसद्भावकृतः,परिच्छेदोऽपि मास्तु तथापि विचित्रशक्तियुक्तस्याभिनवप्रपञ्चरचनापटीयसः परस्य सर्वेश्वरत्वसर्वज्ञत्वादिगुणयुक्तस्य स्वगतभेदोऽवश्यंभावी। स्वशक्तिमायावच्छिन्नेन रूपेण जगत्कर्तृत्वं देहावच्छेदेनाग्रिहोत्रादिकर्तृत्वं चावश्यं वक्तव्यमित्याशङ्क्याह -- निर्गुणत्वादिति। यो हि गुणवानाकाशादिः सं संयोगं विभागं वोपाधिं प्राप्य स्वगुणं शब्दमाविष्करोति न तु स्वस्मिन्नसन्तं स्पर्शं केनचिदप्युपाधिना दर्शयितुमीष्टे। एवं आत्मा सर्वगुणहीनः सत्यप्यवच्छेदलाभे कर्तृत्वादिकं गुणमाविष्कर्तुं न समर्थ इति। फलितमाह -- शरीरस्थोऽपीति। स्पष्टार्थमेतत्।'),
('nilakantha-sc:source:13.33','Nīlakaṇṭha','gita.13.32','sa','commentary','।।13.33।।निर्गुणत्वान्न करोतीति सिद्धम्। असङ्गत्वान्नोपलिप्यत इत्याह -- यथेति। यथा आकाशो धूमादिना न लिप्यते सौक्ष्म्यादसङ्गस्वभावत्वात्। एवमात्मा पुण्यपापादिना नोपलिप्यत इत्यर्थः।'),
('nilakantha-sc:source:13.34','Nīlakaṇṭha','gita.13.33','sa','commentary','।।13.34।।न करोति न लिप्यत इति द्वयमपि दृष्टान्तान्तरेण प्रतिपादयति -- यथेति। यथा सूर्यः स्वसत्तामात्रेण विश्वं प्रकाशयति नतु व्यापाराविष्टतया कुविन्द इव पटम्। यथा चैष प्रकाश्यधर्मैर्दुर्गन्धादिभिर्न लिप्यते एवमयं क्षेत्री क्षेत्रज्ञः सूर्यवदेक एव सन्ननेकधा भूतं क्षेत्रं महाभूतानीत्यादिना चतुर्विंशतितत्त्वात्मकमिच्छाद्वेषादिविकारयुक्तमुक्तं तत्स्वसत्तामात्रेण प्रकाशयति हे भारत? न तु व्यापारविष्टतया तत्संपादयति। तद्धर्मैर्वा पुण्यपापादिभिर्न लिप्यते। सूर्यदृष्टान्तेनैकत्वमकर्तृत्वप्रयुक्तमलेपत्वं च दर्शितम्। तथा च श्रुतयःयथा ह्ययं ज्योतिरात्मा विवस्वानपो भिन्ना बहुरूपोऽनुगच्छन्। उपाधिना क्रियते भेदरूपो देवः क्षेत्रेष्वेवमजोऽयमात्मासूर्यो यथा सर्वलोकस्य चक्षुर्न लिप्यते चाक्षुषैर्बाह्यदोषैः। एकस्तथा सर्वभूतान्तरात्मा न लिप्यते लोकदुःखेन बाह्यः इति।'),
('nilakantha-sc:source:13.35','Nīlakaṇṭha','gita.13.34','sa','commentary','।।13.35।।अध्यायार्थं कृत्स्नमुपसंहरति -- क्षेत्रेति। क्षेत्रक्षेत्रज्ञयोः पूर्वोक्तयोरेवमुक्तरीत्या अन्तरं भेदं जडत्वाजडत्वकर्तृत्वाकर्तृत्वविकारित्वाविकारित्वकृतं वैलक्षण्यं ज्ञानचक्षुःशास्त्राचार्योपदेशात्मप्रत्ययजनितेन ज्ञानचक्षुषा ये विदुस्ते परं मोक्षं यान्ति प्राप्नुवन्ति। किं सांख्यानामिवास्माकमपि गुणपुरुषान्तरज्ञानादेव कैवल्यमुच्यत इत्याशङ्क्याह -- भूतप्रकृतिमोक्षमिति। भूतानां वियदादीनां प्रकृतिरुपादानं त्रिगुणात्मिका अविद्या तस्या विद्यया मोक्षं निरन्वयोच्छेदं च ये विदुस्त एव परं यान्ति न तु क्षेत्रक्षेत्रज्ञयोरन्तरमात्रविद इत्यर्थः। यद्येका सत्या विभ्वी च प्रकृतिस्तर्हि विभूनामलिप्तदृशां बहूनां पुरुषाणां मुक्तानामपि तद्दर्शनमपरिहार्यम्। तथा च तेषामपि बन्धप्रसक्तिः। यदि तु मिथ्या तर्हि यस्यैवात्मसाक्षात्कारो जातस्तद्दृष्ट्या सर्वथैव रज्जूरगवद्बाधिता कालत्रयेऽपि नास्ति इतरेषां त्वनादिरनन्तास्त्येवेति वक्तुं शक्यम्। तस्मान्न प्रकृतिपुरुषान्तरज्ञानमात्रात्कैवल्यं किंतु प्रकृतिबाधेन पुरुषज्ञानात् सर्पबाधेन रज्जुदर्शनाद्भयनिवृत्तिवद्बन्धनिवृत्तिरिति सिद्धम्।'),
('nilakantha-sc:source:14.1','Nīlakaṇṭha','gita.14.1','sa','commentary','।।14.1।।पूर्वाध्यायान्ते भूतप्रकृतिमोक्षं च ये विदुस्ते परं यान्तीत्युक्तं तत्र का वा भूतप्रकृतिः किमाश्रयेण तस्या भूतजकत्वं कथं वा बन्धकत्वं कथं च ततो मोक्षः किंच मुक्तानां लक्षणमित्येतदर्थजातं विवरीतुं चतुर्दशोऽध्याय आरभ्यते। तत्र रुच्युत्पादनार्थं परं ज्ञानं स्तुवन् श्रीभगवानुवाच -- परमिति। परं सर्वोत्कृष्टं ब्रह्मविषयत्वात् ज्ञानं भूयः पुनः असकृदुक्तमपि प्रवक्ष्यामि। किं तत्स्वरूपं आह। ज्ञानानाममानित्वादीनां यज्ञादीनां ज्ञानसाधनानां मध्ये यदुत्तमं मोक्षफलत्वादन्तरङ्गं तदेव तत्। अहं घटं जानामीत्यत्राहमर्थस्य घटाकारवृत्तेर्घटस्य च ज्ञानमस्तीति विषयभेदात् ज्ञानत्रयमस्ति। तत्राद्यद्वयं नान्तरीयकं? यच्च उत्तमं चरमं घटप्रकाशफलरूपं ज्ञानं तदेव परं ब्रह्मेत्यर्थः। यथोक्तं वार्तिककारैःपरागर्थप्रमेयेषु या फलत्वेन संमता। संवित्सैवेह ज्ञेयोऽर्थो वेदान्तोक्तिप्रमाणतः इति। यत् ज्ञानं ज्ञात्वा वेदान्तवाक्यजन्यया धीवृत्त्या अपरोक्षीकृत्य परां सिद्धिं मोक्षमितः संसारात्संसारं विहाय गताः प्राप्ताः।'),
('nilakantha-sc:source:14.2','Nīlakaṇṭha','gita.14.2','sa','commentary','।।14.2।।इदं ज्ञानं विषयविषयिरूपविकल्पविनिर्मुक्तं उपाश्रित्य मम ईश्वरस्य साधर्म्यं सर्वात्मत्वं सर्वनियन्तृत्वं सर्वभावाधिष्ठातृत्वमित्यादिधर्मसाम्यं साधर्म्यमागताः। तथा च श्रुतयःय एवं वेदाहं ब्रह्मास्मीति स इदं सर्वं भवति।सर्वस्य वशी सर्वस्येशानः सर्वस्याधिपतिःस न साधुना कर्मणा भूयान्नो एवासाधुना कनीयान् इति ज्ञानफलं ईश्वरसाधर्म्यप्राप्तिमाहुः। किंच भुशुण्डीप्रभृतयो ज्ञानबलादेव सर्गेऽपि न जायन्ते? प्रलयकाले च तत्तद्भूतभावं गच्छन्तो न प्रलयाग्न्यादिभिर्व्यथन्ते व्यथां प्राप्नुवन्ति। इदं श्लोकद्वयं भाष्ये वक्ष्यमाणज्ञानस्तुत्यर्थत्वेनैव व्याख्यातम्। तज्ज्ञानमुपाश्रित्य ज्ञानसाधनमनुष्ठायेति पदार्थः। शेषं स्पष्टम्।'),
('nilakantha-sc:source:14.3','Nīlakaṇṭha','gita.14.3','sa','commentary','।।14.3।।अथेदानीं का वा भूतप्रकृतिः किमाश्रयेण तस्या भूतजनकत्वं तदाह -- ममेति। मम शुद्धचिन्मात्रस्य योनिः प्रवेशस्थानम्। महद्ब्रह्म महत्तत्त्वस्य प्रथमकार्यस्य ब्रह्म बृंहकं कारणमव्यक्ताव्याकृतापरपर्यायं त्रिगुणात्मकमायाख्यं तस्मिन् गर्भं स्वप्रतिबिम्बरूपं दधाम्यर्पयामि अहं चिदात्मा। ततो मत्प्रतिबिम्बगर्भिता या माया ततः सर्वेषां भूतानां भवनधर्माणां महदादीनां हिरण्यगर्भादीनां च संभव उत्पत्तिर्भवति हे भारत। एतेन चित्प्रतिबिम्बसापेक्षत्वोपपादनेन प्रकृतेः सांख्याभिमतं स्वातन्त्र्यं निरस्तम्।'),
('nilakantha-sc:source:14.4','Nīlakaṇṭha','gita.14.4','sa','commentary','।।14.4।।किंच सर्वेषु भूतेषु योनिषु उपादानभूतेषु पृथिव्यामोषधय इव या मूर्तयः शरीराणि सुरनरतिर्यक्स्थावरात्मकानि चतुर्विधानि संभवन्ति तासां मूर्तीनां ब्रह्ममहत्पूर्वोक्तं महतो ब्रह्म ब्रह्ममहत्। राजदन्तादित्वादुपसर्जनस्य परनिपातः। मायैव योनिरित्यर्थः। अहं तु तासां बीजप्रदः पिता तास्वपि स्वप्रतिबिम्बस्यार्पयिता। यथा पुरुषो भार्यायामनुशयिसंपृक्तं रेतो निषिञ्चति ततो भार्यातः पिण्डोत्पत्तिः रेतोंशतस्तत्र चैतन्योत्पत्तिरिति चैतन्यविशिष्टस्य पिण्डस्य पिताऽहं माता च मायेत्यर्थः।'),
('nilakantha-sc:source:14.5','Nīlakaṇṭha','gita.14.5','sa','commentary','।।14.5।।एवं ईश्वराश्रयेण प्रकृतिर्भूतानि सृजतीत्युक्तम्? इदानीं सा कथंभूता निबध्नातीति तदुच्यते -- सत्त्वमिति। प्रकृतिः सत्त्वरजस्तमसां साम्यावस्था। ततः सकाशात्परस्पराङ्गाङ्गिभावेन वैषम्येण उद्रिच्यमानाः प्रकृतिसंभवा इत्युच्यन्ते न तु प्रकृतितो वैशेषिकाणामिव द्रव्याद्गुणा अन्ये एते हे महाबाहो? देहे अव्ययमविकारिणमपि देहिनं स्थूणायां वत्समिव रशनाभूता गुणा निबध्नन्ति।'),
('nilakantha-sc:source:14.6','Nīlakaṇṭha','gita.14.6','sa','commentary','।।14.6।।तत्र कः केन सङ्गेन बध्नातीत्युच्यते -- तत्रेति। तत्र तेषु गुणेषु सत्त्वं निर्मलत्वाद्दुःखमोहाख्यमलराहित्यात् प्रकाशकं आलोकवत्सर्वार्थावद्योतकम्। यतोऽनामयं रजस्तमोभ्यामनभिभूतम्। तत्सुखसङ्गेन ज्ञानसङ्गेन च नरं अविद्यया तिरोहितस्वरूपज्ञानानन्दं अहं सुखी अहं ज्ञानीत्यभिमानेन अन्तःकरणवृत्तिधर्मयोः सुखज्ञानयोरात्मनि आरोपेण बध्नाति। हे अनघ अव्यसनिन्।'),
('nilakantha-sc:source:14.7','Nīlakaṇṭha','gita.14.7','sa','commentary','।।14.7।।रजोगुणो रागो रञ्जना तदात्मकं विद्धि। तृष्णा प्राप्यमाणेष्वप्यर्थेष्वतृप्तिः। सङ्गः प्राप्ते विषये मनसः प्रीतिलक्षणः संश्लेषस्तयोः समुद्भवं निदानभूतं तद्रजो हे कौन्तेय? कर्मसङ्गेन दृष्टादृष्टार्थेषु कर्मसु सङ्गस्तत्परता तेन निबध्नाति देहिनं देहाभिमानिनम्।'),
('nilakantha-sc:source:14.8','Nīlakaṇṭha','gita.14.8','sa','commentary','।।14.8।।तमोगुणस्तु पूर्वाभ्यां विलक्षणः। अज्ञानं मायाया आवरणशक्तिस्तत उद्भूतं अज्ञानजं विद्धि। अतः सर्वेषां देहिनां मोहनं भ्रान्तिहेतुः। प्रमादोऽनवहितत्वं स च सत्त्वकार्यप्रकाशविरोधी। आलस्यं जडता तच्च रजःकार्यप्रवृत्तिविरोधि। उभयकार्यनिरोधिनी तमोगुणालम्बना वृत्तिर्निद्रा ताभिस्तत्तमो नितरां बध्नाति। हे भारत? देहिनमित्यनुवर्तते।'),
('nilakantha-sc:source:14.9','Nīlakaṇṭha','gita.14.9','sa','commentary','।।14.9।।सत्त्वमुत्कृष्टं सत् सुखे दुःखकारणमभिभूय संजयति संश्लेषं जनयति। एवमुत्तरत्रापि। ज्ञानं प्रकाश आवृत्त्य प्रमादे अवश्यकर्तव्यस्याकरणे।'),
('nilakantha-sc:source:14.10','Nīlakaṇṭha','gita.14.10','sa','commentary','।।14.10।।सत्त्वादयः कदा स्वस्वकार्ये प्रभवन्तीत्याशङ्क्येतरेतरयोरभिभवे सतीत्याह -- रज इति। रजस्तमसी अभिभूय सत्त्वं भवति वर्धते। एवं रजोपि सत्वतमसी अभिभूय भवति। तथा तमोऽपि सत्त्वरजसी अभिभूय भवतीत्यर्थः।'),
('nilakantha-sc:source:14.11','Nīlakaṇṭha','gita.14.11','sa','commentary','।।14.11।।तत्तद्गुणोद्भवलिङ्गान्याह त्रिभिः -- सर्वेति। अस्मिन्देहे यदा सर्वेषु द्वारेषु बाह्याभ्यन्तरविषयोपलब्धिसाधनेषु बाह्याभ्यन्तरकरणेषु। प्रकाशः स्वस्वविषयावरणविरोधी परिणामविशेषो जायते तेनच ज्ञानं शब्दादिविषयस्य याथात्म्येन प्रकाशो यदा जायते तदा सत्त्वं विवृद्धमिति विद्याज्जानीयात्। उत अपि सुखादिलिङ्गेनापि जानीयादित्यर्थः।'),
('nilakantha-sc:source:14.12','Nīlakaṇṭha','gita.14.12','sa','commentary','।।14.12।।लोभः प्राप्ताधिके गर्धः। प्रवृत्तिः अग्निहोत्रादौ। आरम्भो गृहादेः। कर्मणां अशमः सतामसतां वा कार्याणामनुपरमः। स्पृहा दृष्टे परधनादावुपादित्सा। रजसि विवृद्धे सति एतानि लिङ्गानि जायन्ते हे भरतर्षभ।'),
('nilakantha-sc:source:14.13','Nīlakaṇṭha','gita.14.13','sa','commentary','।।14.13।।सत्यपि बोधके गुर्वादौ अप्रकाशः सत्त्वकार्यप्रकाशानुदयः। अप्रवृत्तिः सत्यपि प्रवृत्तिनिमित्ते रजःकार्यप्रवृत्त्यनुदयः। प्रमादः कार्याकार्यविवेकराहित्यम्। मोहो निद्रालस्यादिरूपः।'),
('nilakantha-sc:source:14.14','Nīlakaṇṭha','gita.14.14','sa','commentary','।।14.14।।प्रलयं मरणम्। उत्तमविदां हिरण्यगर्भाद्युपासकानां देवानां वा लोकान्। अमलान्निर्दुःखान्।'),
('nilakantha-sc:source:14.15','Nīlakaṇṭha','gita.14.15','sa','commentary','।।14.15।।कर्मसङ्गिषु श्रौतस्मार्तकर्मानुष्ठातृषु मनुष्येषु। मूढयोनिषु तिर्यक्स्थावरचाण्डालादिषु।'),
('nilakantha-sc:source:14.16','Nīlakaṇṭha','gita.14.16','sa','commentary','।।14.16।।सुकृतस्य सात्त्विकस्य कर्मणः फलं निर्मलं दुःखाज्ञानमलशून्यं सात्त्विकं ज्ञानवैराग्यादिकम्। रजसो राजसस्य कर्मणः फलं दुःखम्। तमसस्तामसस्य कर्मणः फलं अज्ञानम्। सात्विकादिकर्मलक्षणं चनियतं सङ्गरहितम् इत्यादिनाऽष्टादशे वक्ष्यति।'),
('nilakantha-sc:source:14.17','Nīlakaṇṭha','gita.14.17','sa','commentary','।।14.17।।एतादृशफलवैचित्र्ये पूर्वोक्तमेव हेतुमाह -- सत्त्वादिति।'),
('nilakantha-sc:source:14.18','Nīlakaṇṭha','gita.14.18','sa','commentary','।।14.18।।यतः सत्त्वादिभ्यो ज्ञानादीनि जायन्तेऽतः सत्त्वादिवृद्धिकाले प्रलयं गच्छन्तः। क्रमेणोत्तममध्यमाधमासु योनिषु जायन्त इत्याह -- ऊर्ध्वमिति। ऊर्ध्वं देवभावे। मध्ये मानुषभावे। अधः नरकतिर्यक्स्थावरभावे। जघन्यं निन्द्यं यद्गुणवृत्तं निद्रालस्यप्रमादादि तत्स्थास्तामसाः।'),
('nilakantha-sc:source:14.19','Nīlakaṇṭha','gita.14.19','sa','commentary','।।14.19।।कथं प्रकृतिः पुरुषं बध्नातीत्यस्योत्तरमुक्तम्। कथं वा ततोऽस्य मुक्तिरित्यस्योत्तरमाह -- नान्यमिति। गुणेभ्यः कार्यकारणविषयाकारपरिणतेभ्योऽन्यं दृशिमात्रं आत्मानं द्रष्टा जीवः कर्तारं नानुपश्यति विवेकमनु न पश्यति। किंतु गुणा एव कर्तार इत्येव पश्यति न त्वहं कर्तेति। तथा गुणेभ्यः परं गुणव्यापारसाक्षिभूतं मां यदि वेत्ति तदा स वेदिता मद्भावं ब्रह्मभावं गच्छति। अन्यथा तु गुणभावं गतो भवति।'),
('nilakantha-sc:source:14.20','Nīlakaṇṭha','gita.14.20','sa','commentary','।।14.20।।कथं त्वद्भावं गच्छतीति तत्राह -- गुणानिति। एतान्गुणान् महदादित्रयोविंशतिविकारात्मना,परिणतान् देहसमुद्भवान् स्थूलदेहस्य समुद्भवो येभ्यस्तानतीत्य जीवन्नेवातिक्रम्य निर्विकल्पकसमाध्यभ्यासेन बाधित्वाऽमृतं मोक्षमश्नुते प्राप्नोति। एतेनानन्दावाप्तिर्गुणात्ययप्रयोजनमुक्तम्। यतो मुक्तो जन्ममृत्युजरादुःखैर्विमुक्तः सन्निति त्वनर्थनिवृत्तिरुक्ता।'),
('nilakantha-sc:source:14.21','Nīlakaṇṭha','gita.14.21','sa','commentary','।।14.21।।प्रकृतितो मुक्तिप्रकारे उक्तेऽथ मुक्तलक्षणानि पृच्छन्नर्जुन उवाच -- कैरिति। कैर्लिङ्गैश्चिह्नैस्त्रीन्गुणानेतान्व्याख्यातानतीतो भवति पुमान् हे प्रभो? स च किमाचारः कोऽस्याचारः कथं केन च प्रकारेणैतांस्त्रीन्गुणानतिक्रम्य वर्तते।'),
('nilakantha-sc:source:14.22','Nīlakaṇṭha','gita.14.22','sa','commentary','।।14.22।।तत्राद्यस्योत्तरमाह -- प्रकाशमिति। प्रकाशप्रवृत्तिमोहाः सत्त्वरजस्तमसां कार्याणि। व्युत्थानावस्थायां तानि सम्यक् प्रवृत्तानि। सामान्ये नपुंसकम्। तान्संप्रवृत्तान्न द्वेष्टि। नापि समाध्यवस्थायां तानि निवृत्तानि सन्ति काङ्क्षति। सोऽयं नित्यसमाधिस्थो ब्रह्मविद्वरिष्ठः यं प्रकृत्य श्रीभागवते स्मर्यतेदेहं च नश्वरमवस्थितमुत्थितं वा सिद्धो न पश्यति इति। अत्र वासिष्ठे सप्तयोगभूमय उक्ताःज्ञानभूमिः शुभेच्छाख्या प्रथमा समुदाहृता। विचारणा द्वितीया तु तृतीया तनुमानसा। सत्त्वापत्तिश्चतुर्थी स्यात्ततोऽसंसक्तिनामिका। पदार्थाभावनी षष्ठी सप्तमी तुर्यगा स्मृता इति। तत्र यथोक्ता साधनसंपत् मुमुक्षान्ता प्रथमा। श्रवणमननाख्यविचारात्मिका द्वितीया। निदिध्यासनरूपा तृतीया। एताः साधनभूमयः। सत्त्वापत्तिर्ब्रह्मसाक्षात्काररूपा चतुर्थी फलभूता। यस्यां योगी कृतार्थोऽपि जीवन्मुक्तिसुखं पुष्कलं नानुभवति। परास्तिस्रो जीवन्मुक्तेरवान्तरभेदाः। तत्रापि पञ्चम्यां भूमौ स्वयं स्थितः स्वयमेव व्युत्तिष्ठति। षष्ठयां परप्रयत्नेन सप्तम्यां तु न स्वतः परतो वा व्युत्तिष्ठति। सोऽयं नित्यसमाधिस्थः प्रकाशमित्यनेन श्लोकेनोक्तः।'),
('nilakantha-sc:source:14.23','Nīlakaṇṭha','gita.14.23','sa','commentary','।।14.23।।अथ षष्ठ्यां पदार्थाभावन्यां गतो ब्रह्मविद्वरीयानुच्यते -- उदासीनवदिति। योऽयं समाधावुदासीन इवास्ते व्युत्थाने किमपि प्रयोजनमपश्यन्। इदं मम कर्तव्यमस्तीति वासनाशून्यत्वात्। य आस्ते एव न तु परप्रयत्नमन्तरेण कदाचिदपि गुणैर्विचाल्यते। परेण व्युत्थापितोऽपि गुणान्पश्यन् गुणा वर्तन्त इत्येव ज्ञात्वा योऽवतिष्ठति स्तब्ध एव वर्तते न तु गुणकृतैरिष्टानिष्टस्पर्शैरिङ्गते चलति। अयमर्थः -- यथा कश्चिद्भुञ्जानो रसनामौढ्यात्स्वयं शाकादिरसं न विन्दति। परेण ज्ञापितोऽपि कञ्चिद्रसविशेषमुपलभ्यापि तत्रोदासीन एवास्ते। झटित्येव विशेषदर्शनस्य तिरोधानान्न तत्कृतं सुखं दुःखं वा पश्यति तद्वदयं ज्ञेयः।'),
('nilakantha-sc:source:14.24','Nīlakaṇṭha','gita.14.24','sa','commentary','।।14.24।।अथ पञ्चम्यां भूमावसंसक्तिनामिकायां स्थितो ब्रह्मविद्वर उच्यते -- समेति। समाधौ समे दुःखसुखे यस्य स समदुःखसुखः। स्वस्थः स्वेनैव स्वेच्छयैव तिष्ठतीति स्वस्थः। यदा तु न समाधाविच्छा तदा स्वयमेव व्युत्तिष्ठतीति भावः। सोऽपि व्युत्थानावस्थायां समलोष्टाश्मकाञ्चनो विरक्त इत्यर्थः। तुल्यप्रियाप्रियः तुल्यनिन्दात्मसंस्तुतिश्च। प्रियाप्रिययोर्निन्दास्तुत्योश्च प्राप्तौ तुल्यो हर्षविषादशून्यः। अत्र हेतुर्धीर इति। यथा कश्चिच्छूरस्तीव्रप्रहारवेदनार्तोऽपि न व्यामुह्यति धैर्याद्वेदनां चानुभवति तद्वदयं हर्षविषादानुभवन्नपि धैर्यान्न चलति। पूर्वस्य तु जातायामपि वेदनायां हर्षाद्युदय एव नास्ति। तत्पूर्वस्य तु वेदनैव नास्तीति भेदः। एतेन श्लोकत्रयेण सर्वेषां जीवन्मुक्तानां समाधौ लिङ्गानि तत्संवेद्यान्याचाराश्च परसंवेद्यानि लिङ्गान्युक्तानि।'),
('nilakantha-sc:source:14.25','Nīlakaṇṭha','gita.14.25','sa','commentary','।।14.25।।अथ चतुर्थ्यां भूमौ सत्त्वापत्तिसंज्ञायां स्थितस्य योगिनः समाधिसुखाभावेन स्वसंवेद्यलिङ्गाभावात्तत्त्वनिश्चयेन द्वैतस्य बाधाल्लिङ्गमाचारश्च परसंवेद्य एव तदाह -- मानेति। यथाहि परीक्षकः कूटकार्षापणस्य लाभे विनाशे वा हर्षविषादशून्यो न च तल्लाभार्थं यत्नमारभते? मूढस्तु ताभ्यां बाध्यते तल्लाभार्थं यत्नं चारभते? एवं विद्वान् द्वैतं मरुमरीचिकाह्रदसमानं पश्यन् तत्र मानापमानयोर्वा मित्रारिपक्षयोर्वा तुल्य एव नत्वन्यतरलाभाय परिहाराय वा यत्नमारभते अतो गुणातीत इत्युच्यते। सर्वत्र पदार्थः स्पष्टः।'),
('nilakantha-sc:source:14.26','Nīlakaṇṭha','gita.14.26','sa','commentary','।।14.26।।अथ कथं त्रीन्गुणानतिवर्तत इत्यस्योत्तरं विवक्षन् साधनभूतासु तिसृषु भूमिषु तृतीयां तनुमानसामाह -- मां चेति। यश्च साधको मां प्रत्यगात्मानम्। चकारस्त्वर्थे पूर्वभूमिस्थापेक्षयास्य वैलक्षण्यं द्योतयति। अव्यभिचारेण वृत्त्यन्तरानन्तरितेन भक्तियोगेन मयि भगवति तैलधारावदविच्छिन्नवृत्तिप्रवाहिमनःप्रणिधानरूपेण,योगेन सेवते ध्यायति स एवं सूक्ष्मीकृतचित्त एतान् गुणान् समतीत्य ध्यानपरिपाकान्ते सत्त्वमपि बाधित्वा ब्रह्मभूयाय ब्रह्मभावाय कल्पते योग्यो भवति।भुवो भावे इति भवतेर्भावे क्यप्।');
INSERT INTO commentary_fts (unit_id,author,canonical_ref,language,content_type,content) VALUES
('nilakantha-sc:source:14.27','Nīlakaṇṭha','gita.14.27','sa','commentary','।।14.27।।विषयप्रदर्शनद्वारा विचारणाख्यां द्वितीयां भूमिमाह -- ब्रह्मणो हीति। ब्रह्मणो वेदस्य प्रतिष्ठा तात्पर्येण पर्यवसानस्थानमहमेव। अमृतस्य कर्मब्रह्मोभयदर्शनद्वाराऽमृतसाधनस्य। अव्ययस्य अनादित्वादनन्तत्वाच्चापौरुषेयत्वेनाप्रामाण्यशङ्काकलङ्कशून्यस्य। स्वतःप्रमाणभूतस्येत्यर्थः। एतेनोपक्रमोपसंहारादिपर्यालोचनया वेदाविरुद्धतर्कोपकरणया कृत्स्नस्य वेदस्य तात्पर्यं मद्दर्शनकामेन निर्णेतव्यमिति विचारणाख्या द्वितीया भूमिरुक्ता। हेतुफलोपदर्शनमुखेन शुभेच्छाख्यां प्रथमां भूमिमाह -- शाश्वतस्येति। काम्यधर्मवत्फलदानेन नाशाभावात् भगवत्यर्पितो नित्यो धर्मः शाश्वतः। विविदिषादिपारम्पर्येण मोक्षाख्यशाश्वतफलहेतुत्वात्। शाश्वतस्य च धर्मस्य प्रतिष्ठा परमं प्राप्यं फलमहमेव। तथा ऐकान्तिकं विषयसङ्गजन्यसुखव्यभिचारि स्वरूपभूतं मोक्षसुखं तस्यापि प्रतिष्ठा पराकाष्ठा अहमेव। एवं निष्कामधर्मेण विशुद्धचित्तस्यैकान्तिकसुखेच्छा भवति सेयं शुभेच्छाख्या प्रथमा भूमिः। अत्र परां परां भूमिमारोढुमशक्तस्य पूर्वा पूर्वा भूमिरुपदिश्यते। यथा ध्यानेनात्मनि पश्यन्तीत्यत्र निदिध्यासनाशक्तस्य सांख्यनामा विचारस्तत्राप्यशक्तस्य कर्मयोग उपदिश्यते तद्वत्।'),
('nilakantha-sc:source:15.1','Nīlakaṇṭha','gita.15.1','sa','commentary','।।15.1।।पूर्वाध्यायान्ते सुखस्यैकान्तिकस्य प्रतिष्ठा पराकाष्ठाहमित्युक्तं तत्र किं लक्षणं तत्सुखं केन वा आवृतं केन वा साधनेनास्यावरणभङ्गः केन वाधिकारिणा तत्प्राप्यमित्यादिवर्णयितुं पञ्चदशोऽध्यायः आरभ्यते -- ऊर्ध्वमूलमिति।आनन्दाद्ध्येव खल्विमानि भूतानि जायन्ते इति श्रुतिप्रसिद्धं मानुषानन्दमारभ्योत्तरोत्तरशतगुणविवृद्धानन्दसोपानपङ्क्तेरुपरिस्थितं परमानन्दाद्वयं वस्तु ऊर्ध्वं तदेव मूलं मूलकारणमस्य संसाराश्वत्थस्य तमूर्ध्वमूलम्। अधःशाखं ऊर्ध्वादधोऽधः सोपानस्थानीयाः शाखा इव शाखाः अव्यक्तमहदहंकारपञ्चतन्मात्राषोडशविकारहिरण्यगर्भविराट्प्रजापतिसुरगन्धर्वासुरनरतिर्यक्स्थावररूपा यस्य सोऽधःशाखस्तम्। न श्वोऽपि स्थातुं योग्यमनृतत्वादश्वत्थं संसारवृक्षम्। तथाप्यव्ययं मूढानामनाद्यनन्तं प्राहुर्वेदाः।ऊर्ध्वमूलोऽवाक्शाख एषोऽश्वत्थः सनातनः इत्यादयः। छन्दांसि वेदास्तदुपलक्षिता यज्ञादयस्त एव पर्णानि पर्णसंघातवच्छोभाहेतवो यस्य तरोस्तमश्वत्थं यो वेद मिथ्यात्वेन स एव वेदवित् विदितवेद्य इत्यर्थः। अत्राश्वत्थरूपकेण संसारो वर्ण्यते।'),
('nilakantha-sc:source:15.2','Nīlakaṇṭha','gita.15.2','sa','commentary','।।15.2।।अधश्च मानुषेभ्यस्तिर्यक्स्थावरादयोऽवीच्यन्ताः। ऊर्ध्वं च मानुषेभ्य एवोपरि च गन्धर्वयक्षादिहिरण्यगर्भपर्यन्तं प्रसृताः प्रसरं प्राप्तास्तस्य शाखाः गुणैः सत्वादिभिः प्रकर्षेण वृद्धाः गुणप्रवृद्धाः। विषया एव रञ्जकतया कोमलपल्लवरूपाणि प्रवालानि यासां ताः। संसारवृक्षस्योपरिमूलं ब्रह्म उक्तम्। अधश्च इह मनुष्यलोके च तस्य मूलानि वासनारूपाणि अवान्तरमूलानि अनुसन्ततानि प्रवाहनित्यानि। यतः कर्मानुबन्धीनि कर्मैव धर्माधर्माख्यं अनुबन्धः पश्चाद्भावि येषां तानि कर्मानुबन्धीनि वासनाभ्यः कर्माणि कर्मभ्यो वासना इत्यनवरतसंतानोऽयं वृक्ष इत्यर्थः।'),
('nilakantha-sc:source:15.3','Nīlakaṇṭha','gita.15.3','sa','commentary','।।15.3।।ननु श्वोऽपि स्थातुमनर्हश्चाव्ययश्चेत्युक्ते प्रतिक्षणविनाशिविज्ञानसंतानरूपो वा व्रीह्यादिवत्प्रवाहनित्यो वायं संसारस्तर्हि दुरुच्छेद्यो वासनानां कर्मणां च बीजाङ्कुरवदन्योन्यजन्महेतुत्वस्यावर्जनीयत्वादित्याशङ्क्य सत्त्वासत्त्वाभ्यामनिर्वचनीयोऽयमित्येवं पक्षमाश्रित्य परिहरति -- न रूपमिति। रज्जूरगस्येवास्य रूपं सम्यग्दृशा वीक्ष्यमाणं सन्नोपलभ्यते। इह जीवत्येव देहे। यथा पूर्वमज्ञानदशायां तथा नोपलभ्यते ज्ञानदशायाम्। तेनास्य मृषात्वमनुभवैकवेद्यमित्युक्तम्। एतेनानुपलभ्यरूपत्ववचनेन स्वप्रकाशानां विज्ञानानां रूपवतां बीजादीनां च सादृश्यस्य व्यावृत्तिः। तर्हि शशविषाणवत्तुच्छ एवायं स्यादित्यत आह -- नान्तो न चादिरिति। उपादानस्य मूलाज्ञानस्याद्यन्तशून्यत्वादयमप्याद्यन्तशून्य इत्यर्थः। तर्हि आत्मवदपरिहार्यः स्यादित्याशङ्क्याह -- न च संप्रतिष्ठा। अस्य प्रतिष्ठाख्यं लयस्थानं वृक्षस्य भूमिरिव नास्ति। न चायं ब्रह्मणो विकारो येन तत्रैव लीयेत। न चेष्टापत्तिः ब्रह्मणः कौटस्थ्यभङ्गापत्तेः। किं तर्हि तुच्छमज्ञानमस्योपादानं तस्मिंश्च ज्ञानेन विनष्टे समूलस्यास्योच्छेदो भवति। अज्ञानस्य च तुच्छत्वंतुच्छ्येनाभ्वपिहितं यदासीत् इत्यादिश्रुत्या। तत्कार्यस्य रज्जूरगादेः प्रलये तदनुपलम्भस्यानुभवेन च सिद्धम्। तस्मादस्य प्रतिष्ठा नोपलभ्यत इति युक्तमेवोक्तम्। तमेनमश्वत्थं वासनानां दार्ढ्यात् सुविरूढमूलं दृढतरमूलमपि असङ्गशस्त्रेण सङ्गोदेहादितादात्म्यबुद्धिस्तद्वर्जनमसङ्गः स एव शस्त्रं तेन दृढेन परिपक्वेन छित्त्वा। ततः पदं तत्परिमार्गितव्यमित्युत्तरेणान्वयः। यद्यपि स्थूलसूक्ष्मयोः संसारयोरसङ्गः सुषुप्तौ स्वयमेव जायते तेन तन्मूलवासनाभिरप्यात्मनोऽसङ्गोऽनुमीयते तथापि वासनामूलस्याज्ञानस्य ज्ञानेनानुच्छेदान्नासङ्गधीर्दृढा भवति तस्मान्निर्विकल्पसमाध्यभ्यासेन कारणशरीरस्याप्यसङ्गः साध्यः। तेन चासङ्गशस्त्रेणास्य छेदो मूलोच्छेदो लवणोदकवद्रज्जूरगवद्वा प्रविलापनरूपः कर्तव्यः। न तु सांख्यानामिव स्वरूपेण सतः परिवर्जनमात्रम्।'),
('nilakantha-sc:source:15.4','Nīlakaṇṭha','gita.15.4','sa','commentary','।।15.4।।तमिममश्वत्थं छित्त्वा किं कर्तव्यमत आह -- तत इति। न केवलं निर्विकल्पसमाधिना तदसंङ्गमात्रेण कृतार्थता किं तर्हि ततोऽसङ्गान्तरं तत् श्रुतिप्रसिद्धं पदनीयं ब्रह्म परिमार्गितव्यं श्रुतियुक्तिबलेनाहमेव ब्रह्मास्मीति ज्ञातव्यम्। यस्मिन्पदे निर्विकल्पे गताः प्राप्ताः सन्तो न निवर्तन्ति न पुनर्निवर्तन्ते। तमेव प्रत्यगानन्दमाद्यं पुरुषं पुरि शरीरे शयानमहमपि प्रपद्ये शरणागतोऽस्मीति भावयेत्। भगवत एव वा इदं वचनं लोकशिक्षार्थं वर्त एव च कर्मणीतिवत्। कोऽसौ पुरुषः यतः पुराणी आद्या प्रवृत्तिःसोऽकामयत बहु स्यां प्रजायेय इत्येवंरूपा प्रसृता अस्मास्वपि प्रवृत्ता। यतो वयमपि इदानीं कामयामहे,धनादिना वयं भूयांसः स्याम प्रजया प्रजायेमहीति चेति। येनेयं प्रवृत्तिर्दर्शिता तत्प्रणामेनैव सा निवर्तिष्यत इत्यर्थः।'),
('nilakantha-sc:source:15.5','Nīlakaṇṭha','gita.15.5','sa','commentary','।।15.5।।एवमैकान्तिकस्य सुखस्याच्छादकं संसाराश्वत्थं तच्छेदकमसङ्गशस्त्रं चोक्त्वा तस्य सुखस्य प्राप्तावधिकारिणं तस्य स्वरूपं चाह द्वाभ्याम् -- निर्मानेति। मानो दर्पः। मोहो विपर्ययस्तद्रहिताः निर्मानमोहाः। जितः सङ्गः कर्ताहमित्यभिमानः दोषो रागादिश्च यैस्ते जितसङ्गदोषाः। अध्यात्मं आत्मनि नित्याः निष्ठावन्तः आत्मध्यानपरा इति यावत्। विनिवृत्तकामाः त्यक्तसर्वपरिग्रहाः। द्वन्द्वैः सुखदुःखेत्युपलक्षणं शीतोष्णादीनामपि। तैर्विमुक्तास्तितिक्षावन्त इत्यर्थः। अमूढाः विद्ययाऽविद्यानाशं कृतवन्तः। तत्पदं अव्ययं अपुनरावृत्ति गच्छन्ति।'),
('nilakantha-sc:source:15.6','Nīlakaṇṭha','gita.15.6','sa','commentary','।।15.6।।ननु यदि तदूर्ध्वं पदं गच्छन्ति तर्हि ततः पातोऽप्यवश्यंभावीपतनान्ताः समुच्छ्रयाः इति न्यायात्। ततश्च यस्मिन् गता न निवर्तन्तीत्यनुपपन्नमित्याशङ्क्य तस्य पदस्य स्वरूपमाह -- न तदिति। तत्पदं सूर्यो न भासयति। रूपादिहीनत्वेन चक्षुरयोग्यत्वात्। एतेन सर्वेषां बाह्येन्द्रियाणां निवृत्तिः। यद्धि रूपव़च्चक्षुर्योग्यं तत्सूर्येण चक्षुरनुग्राहकेण भास्यं इदं तु न तथेत्यर्थः। न शशाङ्कश्चन्द्रोऽपि भासयति। यन्मनोग्राह्यं वस्तु तच्चन्द्रेण मनोनुग्राहकेण भास्यं इदं तु न तथा।यन्मनसा न मनुते इति श्रुत्याऽस्य मनोग्राह्यत्वनिषेधात्। नापि पावकः भासयति। यद्धि वाचा ग्राह्यं तत्तदनुग्राहकेण पावकेन भास्यं इदं तु न तथा।यद्वाचानभ्युदितम् इति श्रुत्यास्य वाग्गोचरत्वनिषेधात्।न चक्षुषा गृह्यते नापि वाचा इत्यादि श्रुत्यन्तरं च। यतश्चक्षुर्मनोवाचामगम्यं तेन स्थूलसूक्ष्मकारणप्रपञ्चातीतं प्रत्यगद्वयम्नान्तःप्रज्ञं न बहिःप्रज्ञंअस्थूलमनणु इत्यादिश्रुतिभिः सर्वविशेषरहितं यत्प्रतिपादितं तत् मम परमं धाम वृत्तिरूपज्ञानादपरमादन्यज्योतिश्चिन्मात्रम्। ममेति संबन्धो राहोः शिर इतिवदुपचारात्। मदभिन्नज्योतिः स्वयंप्रकाशमित्यर्थः। अतएव यद्गत्वा प्राप्य ज्ञात्वेत्यर्थः। न निवर्तन्ते निवृत्तिकारणस्य मूलाज्ञानस्याभाव्त। एवं व्याख्याने हियदा ह्येवैष एतस्मिन्नदृश्येनात्म्येऽनिरुक्तेऽनिलयनेऽभयं प्रतिष्ठां विन्दते अथ सोऽभयं गतो भवति इति श्रुत्यर्थानुगमो दृश्यते। अदृश्ये इति दृगयोग्यत्वेन सूर्यभास्यत्वं पर्युदस्यते। अनात्म्ये आत्मनो मनसो योग्यं आत्म्यं तदन्यत्र अनात्म्ये इति मनसोऽप्ययोग्यत्वेन चन्द्रभास्यत्वं निरस्यते। अनिलयने निलीयतेऽस्मिन्सर्वं स्थूलसूक्ष्ममिति निलयनं कारणं तद्भिन्ने। अतएवानिरुक्ते निर्वचनायोग्ये। वाचामगोचर इत्यर्थः। तेन पावकाप्रकाश्ये इति सिद्धम्। ये तु सूर्याद्यप्रकाश्यमर्चिरादिमार्गगम्यं सत्यलोकादप्युपरितनमप्राकृतं वैष्णवं पदं नित्यं देशान्तरेऽस्ति तद्गत्वा पुनर्न निवर्तन्त इति व्याचक्षते तेषांन रूपमस्येह तथोपलभ्यत इति दृश्यस्य तुच्छत्वादेव तादृशस्यापि तुच्छत्वमपरिहार्यम् दृश्यत्वाविशेषात्। तस्माद्यथोक्त एव श्लोकार्थः।'),
('nilakantha-sc:source:15.7','Nīlakaṇṭha','gita.15.7','sa','commentary','।।15.7।।ननु यदि सूर्याद्यभास्यज्योतीरूपस्त्वंक्षेत्रज्ञं चापि मां विद्धि इति स्वस्यैव क्षेत्रज्ञत्वं ब्रूषे तर्हि क्षेत्रज्ञस्य सतस्तव घटादिप्रकाशे किमिति सूर्याद्यपेक्षा दृश्यते। नहि स्वयं ज्योतीरूपः स्वविषयावभासने ज्योतिरन्तरमपेक्षते दीपादिष्वदर्शनादित्याशङ्क्याह त्रिभिः -- ममैवेति। यद्यस्मादीश्वरो जगत्स्रष्टा शरीरं अवाप्नोतिस एष इह प्रविष्ट आनखाग्रेभ्यःतत्सृष्ट्वा तदेवानुप्राविशत् इत्यादिश्रुतिभ्य ईश्वर एव शरीरधारी तथा यद्यस्माद्धेतोः। अपिशब्दोऽवधारणार्थे। चः समुच्चयार्थे।कस्मिन्नहमुत्क्रान्त उत्क्रान्तो भविष्यामि कस्मिन्वा प्रतिष्ठिते प्रतिष्ठास्यामीति स प्राणमसृजत इति श्रुतेः। प्राणधारणेनोपाधिना ईश्वर एव च उत्क्रामति। ततो हेतुद्वयाज्जीवलोके संसारे यो जीवभूतः प्राणी स सनातनः सर्वदैकरूपोऽहमेवेति वक्तव्येयथाग्नेः क्षुद्रा विस्फुलिङ्गा व्युच्चरन्त्येवमेवैतस्मादात्मनः सर्व एव आत्मानो व्युच्चरन्ति इति वह्निविस्फुलिङ्गन्यायेन स ममैवांश इत्यंशांशिभावोक्तिः। यद्यपि वह्नौ भेदः परिमाणं च स्वगतं न दृश्यते तथापि तूपाधिगतमेव तदुभयं तत्राप्युपचर्यते अयमग्निरस्मादग्नेर्भिन्नः अयमस्य स्फुलिङ्गः अयमस्मादल्प इति।एवमस्थूलमनण्वह्रस्वमदीर्घम् इति श्रुतेश्चतुर्विधपरिमाणशून्ये ब्रह्मणि ममैवांश इत्यंशांशिभावेन भेदोऽल्पत्वमहत्त्वे चोपचारादौपाधिके ध्येये। तथा च श्रुतिःबुद्धेर्गुणेनात्मगुणेन चैव ह्याराग्रमात्रो ह्यवरोऽपि दृष्टः इतिसमः प्लुषिणा समो मशकेन समो नागेन सम एभिस्त्रिभिर्लोकैः इति च। तथा च विस्फुलिङ्गो वह्निरेव न तु वन्ह्यंशः? एवं जीवोऽपि ब्रह्मैव न तु ब्रह्मांशःब्रह्मदाशा ब्रह्मदासा ब्रह्मेमे कितवा उत इति दाशादिष्वपि पिण्डेषु गोत्वस्येव कात्स्न्र्येन एकैकस्मिन् ब्रह्मभावपरिसमाप्तिदर्शनात्। निरंशेंऽशांशिकल्पनाया अयोग्यत्वाच्च स एवं जीवभूत ईश्वरो ममैवांश इवांशो,रूपभेदो मनः षष्ठं येषु तानि मनसा सह षडिन्द्रियाणि प्रकृतिस्थानि इन्द्रियाणां प्रकृतिः स्वभावो विषयप्रावण्यं तत्र स्थितानि। कर्षति सुप्तिप्रलयसमकालेषु संकोचयति।'),
('nilakantha-sc:source:15.8','Nīlakaṇṭha','gita.15.8','sa','commentary','।।15.8।।तथैतान्येव आशयात् स्वलयस्थानात् गृहीत्वा संयाति विषयदेशं प्रतिगच्छति प्रबोधसर्गव्युत्थानकालेषु। तत्र दृष्टान्तः। वायुर्गन्धानिवाशयात्। गन्धाशयात्पुष्पात्।'),
('nilakantha-sc:source:15.9','Nīlakaṇṭha','gita.15.9','sa','commentary','।।15.9।।कानि तानि मनःषष्ठानि। तानि गृहीत्वा गत्वा चायं किं करोतीत्यत आह -- श्रोत्रमिति। अधिष्ठाय व्यापारवन्ति कृत्वा विषयान् शब्दादीनुपसेवते प्रकाशयति। यथा दीपः स्वस्य वृत्तिलाभाय तैलवर्त्याद्यपेक्षमाणोऽपि स्वविषयावभासने स्वयमेव प्रभुः एवं जीवोऽपि घटाकारत्वलाभाय मनःषष्ठानीन्द्रियाणि सूर्यादींश्चापेक्षते तथापि घटावभासं स्वयमेव करोति नेतराणि इन्द्रियसूर्यादीनि स्वभास्यत्वात्तैलवर्त्यादिवदित्याशयः।'),
('nilakantha-sc:source:15.10','Nīlakaṇṭha','gita.15.10','sa','commentary','।।15.10।।तमेवंभूतं मनःषष्ठानीन्द्रियाणि प्राणं चाधिष्ठाय तेषामुत्क्रमणेनोत्क्रामन्तं तेषां स्थित्या स्थितं तेषां भोगेन भुञ्जानं तेषां सत्वरजस्तमोगुणयुक्तत्वेन गुणान्वितं घटसूर्यमिव घटाकाशमिव वा घटगमनादिना गमनादिमन्तं स्वतस्तूत्क्रमणादिशून्यमपि विमूढास्तात्त्विकरूपं नानुपश्यन्ति ज्ञानचक्षुषस्तु पश्यन्ति। उपाधेरेवोत्क्रमणादिकं न तूपहितस्यात्मन इति जानन्त्येवेत्यर्थः।'),
('nilakantha-sc:source:15.11','Nīlakaṇṭha','gita.15.11','sa','commentary','।।15.11।।यतन्तो यत्नशीला योगिनश्च एनं आत्मनि बुद्धाववस्थितं विभुमुत्क्रान्त्यादिहीनमसङ्गं पश्यन्ति। यतन्तोऽपि अकृतात्मानः ये यज्ञादिभिरशोधितचित्ताः एनं न पश्यन्ति। यतः अचेतसोऽनिर्जितचित्ताः। पाषाणतुल्या इत्यर्थः।'),
('nilakantha-sc:source:15.12','Nīlakaṇṭha','gita.15.12','sa','commentary','।।15.12।।कथं तर्हि सूर्यादीनामपि भासकत्वं लोके दृश्यते तदपि मदावेशादेवेत्याह -- यदादित्येति। अत्राप्यादित्यादिपदैः करणाधिष्ठात्र्यो देवतास्तदधिष्ठेयानि करणानि च तन्त्रेणैव गृह्यन्ते। यदादित्यादिषु बाह्यकरणाधिष्ठातृषु तत्तदधिष्ठेयेषु बाह्यकरणेषु च गतं विद्यमानं तेजो विषयप्रकाशनसामर्थ्यं सर्वं जगद्भासयते तत्तेजो मामकं मदीयं विद्धि।येन सूर्यस्तपति तेजसेद्धःयेन चक्षूंषि पश्यन्ति त्यादिश्रुतिभ्यः। एवं मनश्चन्द्रमसोर्यदान्तरप्रपञ्चप्रकाशनसामर्थ्यं तदपि मामकमेव तथा यद्वागग्न्योरव्याकृतादिविषयप्रकाशनसामर्थ्यं तदपि मामकमेवेत्यर्थः। अक्षरयोजना स्पष्टा।'),
('nilakantha-sc:source:15.13','Nīlakaṇṭha','gita.15.13','sa','commentary','।।15.13।।न केवलमादित्यादिगतप्रकाशनसामर्थ्यं मामकमपि तु पृथिव्यादिगतं भूतधारणव्यापनसामर्थ्यमपि मदीयमेवेत्याह -- गामिति। गां पृथिवीमाविश्य तां पृथिवीं दृढां कृत्वा भूतान्यहमेव धारयामि ओजसा बलेन। अन्यथा पृथिवी सिकतामुष्टिवद्विशीर्येत। तथा च मन्त्रवर्णःयेन द्यौरुग्रा पृथिवी च दृढा इति।स दाधार पृथिवीं इति। च तथाहमेव सोमो रसात्मको जलात्मकःरसो जलं रसो हर्षः इत्यनेकार्थमञ्जरी। जलमयो भूत्वा सर्वा ओषधीः पुष्णामि च रसवतीः पुष्टाश्च करोमि। सोमो हि स्वात्मरसानुप्रवेशेन सर्वा ओषधीः पुष्णातीति प्रसिद्धम्।'),
('nilakantha-sc:source:15.14','Nīlakaṇṭha','gita.15.14','sa','commentary','।।15.14।।अहं वैश्वानरसंज्ञ उदरस्थोऽग्निर्भूत्वा प्राणिनां सर्वेषां देहमाश्रितः सन् प्राणापानाभ्यां वायुभ्यां समायुक्तः समुद्दीपितश्चतुर्विधमन्नमदनीयं भक्ष्यं दन्तव्यापारापेक्षमपूपादि। भोज्यं तदनपेक्षं पायसादि। लेह्यं गुडशर्करादि। चोष्यं निश्चोष्य त्यज्यमानमिक्षुदण्डादि। एतेन सर्वत्र सर्वा शक्तिर्या दृश्यते सा मदीयैवेति भावः। तदेवं भोक्ता वैश्वानरोऽग्निर्भोज्यमन्नं सोमस्तदेवमुभयमग्नीषोमौ सर्वमिति पश्यतोऽन्नदोषलेपो न भवतीत्यपि द्रष्टव्यम्।'),
('nilakantha-sc:source:15.15','Nīlakaṇṭha','gita.15.15','sa','commentary','।।15.15।।किंच सर्वस्य प्राणिजातस्याहं हृदि संनिविष्ट आत्मेत्यर्थः। अतो मत्त आत्मनस्तेषां स्मृतिर्ज्ञानं च पुण्यवताम्। पापिनां तु तयोरपोहनं विस्मरणमज्ञानं च भवति। तथा च सर्वैर्वेदैः कर्मोपास्तिज्ञानकाण्डात्मकैरहमेव,परमात्मा वेद्यो वेदान्तकृत् वेदान्तोक्तविद्यासंप्रदायकृत् वेदविद्वेदार्थविच्चाहमेव। एतेन वेदान्तविद्वेदविच्च स्वविभूतिरित्युक्तं भवति।'),
('nilakantha-sc:source:15.16','Nīlakaṇṭha','gita.15.16','sa','commentary','।।15.16।।सर्वशास्त्रहृदयं संगृह्णाति -- द्वाविमाविति। लोके प्रसिद्धौ इमौ द्वावेव पुरुषौ। क्षरो विनाशी स च सर्वाणि भूतानि प्राणवन्ति कर्मक्षये सुप्तिप्रलयकैवल्यादावुपाधिनाशमनु विनाशशीलो जीवो ब्रह्मप्रतिबिम्बभूतो जलार्कोपमः।प्रज्ञानघन एवैतेभ्यो भूतेभ्यः समुत्थाय तान्येवानुविनश्यति इति श्रुतेः। कूटस्थो निर्विकारो मायोपाधिरक्षरः। तदुपाधेरकर्मत्वेन नाशासंभवात्। उपाधिदोषेणावशीकृतत्वाच्चासौ न क्षरति स्वरूपान्न च्यवत इत्यक्षरः।'),
('nilakantha-sc:source:15.17','Nīlakaṇṭha','gita.15.17','sa','commentary','।।15.17।।एताभ्यां कार्यकारणोपाधिभ्यामन्यो निरुपाधिरुत्तमः पुरुषः योऽसौ परमात्मेत्युदाहृतः शास्त्रे। योऽसौ मायया ईश्वरो भूत्वा लोकत्रयमुत्तममध्यमाधमशरीररूपमाविश्य प्रविश्य धारयति शरीरत्रयम्। अथापि अव्ययः सर्वज्ञत्वेन ईश्वरधर्मेण अल्पज्ञत्वेन जीवधर्मेण वा न व्येति वर्धते क्षीयते वेत्यर्थः।'),
('nilakantha-sc:source:15.18','Nīlakaṇṭha','gita.15.18','sa','commentary','।।15.18।।यस्मादिति। क्षरं उपाधिं अक्षरं च उपाधिं अतीतोऽतिक्रम्य स्थितोऽहमतोऽक्षरादपि चेति चशब्दात् क्षरादपि उत्तम उत्कृष्टतमः। जडात्क्षररूपादुपाधेरुत्कृष्टस्तदुपहितो जीवश्चेतनत्वात्? ततोऽप्युत्कृष्टतरो मायोपाधिः स्वतन्त्रत्वात्? ततोऽप्युत्कृष्टतमोऽनुपाधिरनागन्तुकरूपत्वात्? अक्षरार्थः स्पष्टः।'),
('nilakantha-sc:source:15.19','Nīlakaṇṭha','gita.15.19','sa','commentary','।।15.19।।एतद्विज्ञानफलमपि भक्तिरेवेत्याह -- यो मामिति। असंमूढः मम पुरुषोत्तमत्वे संशयविपर्यासादिहीनः स एव सर्ववित्। यतो मां पुरुषोत्तमं जानाति तत्फलं च मां सर्वभावेन सर्वात्मना सर्वैः प्रकारैर्भजति।'),
('nilakantha-sc:source:15.20','Nīlakaṇṭha','gita.15.20','sa','commentary','।।15.20।।अस्मिन्नध्याये भगवत्तत्त्वज्ञानस्य मोक्षफलत्वमुक्त्वाऽथेदानीं तत्स्तौति -- इतीति। इति एतद्गुह्यतमम् अत्यन्तरहस्यं शास्त्रम्। यद्यपि इयमष्टादशाध्यायी कृत्स्ना शास्त्रं तथाप्यस्मिन्नध्याये कृत्स्नस्य शास्त्रार्थस्य प्रदर्शनादयमपि शास्त्रम्। अत्र हि कार्यकारणविभागः संसारवृक्षस्यानित्यत्वं भगवतो विभूतयःयस्तं वेद स वेदवित्?वेदैश्च सर्वैरहमेव वेद्यः इत्यादिना सर्वः शास्त्रार्थो दर्शितोऽस्ति। इदं मया उक्तं हे अनघ निर्व्यसन? एतत् रहस्यं बुद्ध्वा बुद्धिमान् ज्ञानी स्यादात्मविद्भवेत्। तावता कृतकृत्यः। सर्वं हि कृत्यं परमात्मावगतिपर्यन्तं तत्रैव कृत्स्नपुरुषार्थसमाप्तेः। चात्प्राप्तप्रापणीयश्च स्यात् भवति नातःपरं कर्तव्यमवशिष्यते इत्यर्थः।'),
('nilakantha-sc:source:16.1','Nīlakaṇṭha','gita.16.1','sa','commentary','।।16.1।।नवमाध्याये राक्षसी आसुरी दैवी चेति तिस्रः संपद उक्तास्तासु राक्षसीमासुर्यामेवान्तर्भाव्य द्वे एव संपदावत्र व्युत्पाद्येतेद्वया ह प्राजापत्या देवाश्चासुराश्च इति श्रुतावभयसत्त्वशुद्ध्यादिधीवृत्तयो देवाः दम्भदर्पादिधीवृत्तयोऽसुरा इति द्वैराश्यस्यैव दर्शनात्। पूर्वाध्यायान्ते इदमुक्तं मयानघेत्यर्जुनं संबोधयताऽनघत्वं दैवसंपत्तिमत्त्वं तद्विपर्ययस्त्वासुरीसंपदिति दर्शयितुं श्रीभगवानुवाच -- अभयमिति। अभयं स्वोच्छेदबुद्ध्यभावः। सत्त्वसंशुद्धिः चित्तनैर्मल्यम्। ज्ञानं श्रवणादिजन्यं? योगो ज्ञातेऽर्थे चित्तप्रणिधानं तयोर्व्यवस्थितिः। निर्दिष्टैषा मुख्या दैवीसंपत्। दानं यथाशक्ति संविभागोऽन्नादीनाम्। दमो बाह्येन्द्रियनियमः। यज्ञः श्रौतस्मार्तादिः। स्वाध्यायो वेदाध्ययनम्। तपो वक्ष्यमाणलक्षणं शारीरादित्रिविधम्। आर्जवं ऋजुत्वं सर्वदा।'),
('nilakantha-sc:source:16.2','Nīlakaṇṭha','gita.16.2','sa','commentary','।।16.2।।किञ्च अहिंसा प्राणिपीडावर्जनम्। सत्यमप्रियानृतवर्जनं यथाभूतार्थभाषणम्। अक्रोधः परैराक्रुष्टस्याभिहतस्य वा प्राप्तस्य क्रोधस्योपशमनम्। त्यागः सर्वकर्मसंन्यासः पूर्वं दानस्योक्तत्वात्। शान्तिरन्तःकरणस्योपरमः। अपैशुनं परदोषप्रकाशनं पैशुनं तद्वर्जनम्। दया दुःखितेषु भूतेषु कृपा। अलोलुप्त्वमिन्द्रियाणां विषयसंनिधावप्यविक्रिया। मार्दवं मृदुता। ह्रीर्लज्जा। अचापलं असति प्रयोजने वाक्पाणिपादादीनामव्यापारयितृत्वम्।'),
('nilakantha-sc:source:16.3','Nīlakaṇṭha','gita.16.3','sa','commentary','।।16.3।।किञ्च तेजः प्रागल्भ्यं न तूग्रता। क्षमा आक्रुष्टस्य ताडितस्य वान्तर्विक्रियानुत्पत्तिः। उत्पन्नाया विक्रियायाः प्रशमनमक्रोध इत्युक्तम्। धृतिर्देहेन्द्रियेष्ववसादं प्राप्तेषु तस्य प्रतिषेधकोऽन्तःकरणवृत्तिविशेषो येनोत्तम्भितानि देहादीनि नावसीदन्ति। शौचं द्विविधं मृज्जलाभ्यां बाह्यम्? आन्तरं मनोबुद्ध्योर्नैर्मल्यं मायारागादिकालुष्याभावः। अद्रोहः परजिघांसाया अभावः। नातिमानिता अत्यन्तं मानराहित्यम्। एतानि अभयादीनि दैवीं सत्त्वप्रधानां संपदं अभिलक्ष्य जातस्य स्वभावतो भवन्ति हे भारत।'),
('nilakantha-sc:source:16.4','Nīlakaṇṭha','gita.16.4','sa','commentary','।।16.4।।अथेदानीं रजस्तमोमयी आसुरीसंपदुच्यते -- दम्भ इति। दम्भो धर्मध्वजित्वम्। दर्पः धनाभिजननिमित्त उत्सेकः। अभिमान आत्मनि पूज्यताबुद्धिः। क्रोधः प्रसिद्धः। पारुष्यं निष्ठुरभाषणम्। अज्ञानं अविवेकजनितो मिथ्याप्रत्ययः। एते आसुरीं संपदमभिलक्ष्य जातस्य भवन्ति हे पार्थ।'),
('nilakantha-sc:source:16.5','Nīlakaṇṭha','gita.16.5','sa','commentary','।।16.5।।अनयोः संपदोः कार्यमाह -- दैवीति। दैवी पूर्वोक्ता। अर्जुनस्य शङ्का किमहमासुर्यां संपदि जातोऽस्मीति तामपनुदति माशुच इति।'),
('nilakantha-sc:source:16.6','Nīlakaṇṭha','gita.16.6','sa','commentary','।।16.6।।द्वौ द्विसंख्यौ भूतसर्गौ भूतानां स्वभावौ मे मद्वचनाच्छृणु।'),
('nilakantha-sc:source:16.7','Nīlakaṇṭha','gita.16.7','sa','commentary','।।16.7।।प्रवृत्तिं विधिवाक्यं निवृत्तिं निषेधवाक्यं न विदुः। धर्माधर्मयोरिष्टानिष्टहेतुत्वज्ञानरहिता इत्यर्थः।'),
('nilakantha-sc:source:16.8','Nīlakaṇṭha','gita.16.8','sa','commentary','।।16.8।।असत्यं सत्यवर्जितं जगत्प्राणिजातम्। तथाऽप्रतिष्ठं धर्माधर्माख्या प्रतिष्ठा आश्रयस्तच्छून्यम्। अनीश्वरं अनियन्तृकं आहुः। अपरस्परसंभूतंअपरस्पराः क्रियासातत्ये इति सुट्। बीजाङ्कुरवत्परस्परकारणीभूतानां धर्माधर्मतद्वासनानां यत्सातत्यं तस्मात्संभूतं। किमन्यल्लोकेऽस्ति न किञ्चिदपि धर्माद्यपेक्षया उत्पद्यते? किंतु सर्वं कामहैतुकं स्त्रीपुंसयोर्मिथुनीभावः कामस्तदुत्थमेव। स्वभावादेव जन्तुर्जायते न त्वदृष्टादित्यर्थः।'),
('nilakantha-sc:source:16.9','Nīlakaṇṭha','gita.16.9','sa','commentary','।।16.9।।एतान्मनुपदोक्तां लोकायतिकानामभिप्रेतां दृष्टिमवष्टभ्य तामाश्रित्य नष्टात्मानः कामादिवशेन नष्टधैर्याः। यतोऽल्पे क्षुद्रे दृष्टसुखे एव बुद्धिर्येषां तेऽल्पबुद्धयः। अहिताः हिंस्राः।'),
('nilakantha-sc:source:16.10','Nīlakaṇṭha','gita.16.10','sa','commentary','।।16.10।।असद्ग्राहान् वश्याकर्षणनिध्यञ्जनकायसिद्ध्यादिसाधनेषु असत्सु असमीचीनेषु ग्राहा निर्बन्धा अत्यन्ताभिनिवेशास्तान् गृहीत्वा अशुचीनि मद्यमांसादिसापेक्षाणि व्रतानि नियमविशेषा येषां ते तथाभूताः सन्तः कुमार्गप्रवर्तनेन प्रवर्तन्ते जगतः क्षयायेति संबन्धः।'),
('nilakantha-sc:source:16.11','Nīlakaṇṭha','gita.16.11','sa','commentary','।।16.11।।चिन्तां योगक्षेमविषयाम्। प्रलयान्तां मरणावधिम्। एतावत् देह एवात्मा कामभोग एव पुरुषार्थ इतोऽन्यन्नास्ति इति निश्चिताः निश्चयवन्तः। तथा च बार्हस्पत्यं सूत्रंचैतन्यविशिष्टः कामः पुरुषः। काम एवैकः पुरुषार्थः इति च।'),
('nilakantha-sc:source:16.12','Nīlakaṇṭha','gita.16.12','sa','commentary','।।16.12।।अन्यायेन परवञ्चनादिना अर्थसंचयान् धनराशीन् ईहन्ते लिप्सन्ते।'),
('nilakantha-sc:source:16.13','Nīlakaṇṭha','gita.16.13','sa','commentary','।।16.13।।आशापाशान्विवृणोति -- इदमद्येति।'),
('nilakantha-sc:source:16.14','Nīlakaṇṭha','gita.16.14','sa','commentary','।।16.14।।क्रोधपरायणत्वं कामपरायणत्वं च पूर्वोत्तराभ्यामर्थाभ्यामाह -- असाविति। ईश्वरः समर्थः सर्वेषां निग्रहे। सिद्धः लब्धाखिलभोगसाधनः। बलवान् विषयोपभोगे समर्थः। अतएव सुखी।'),
('nilakantha-sc:source:16.15','Nīlakaṇṭha','gita.16.15','sa','commentary','।।16.15।।आढ्यो धनी। अभिजनवान् कुलीनः अज्ञानेन अविवेकेन मोहिताः विविधं भ्रमं प्रापिताः।'),
('nilakantha-sc:source:16.16','Nīlakaṇṭha','gita.16.16','sa','commentary','।।16.16।।अनेकं नास्ति एकं चिन्तनीयं यस्य तदनेकं बहुषु विषयेषु पूर्वोक्तेषु लग्नं चित्तं येषां ते अनेकचित्तास्ते च ते विभ्रान्ताश्च किमिदमादौ साधनीयमिदमादौ साधनीयमिति विशेषेण भ्रान्त्याकुला अनेकचित्तविभ्रान्ताः। मोहः असत्स्वपि सद्बुद्धिस्तदेव जालं तेन सम्यगावृताः। प्रसक्ताः प्रकर्षेण लग्नाः। अशुचौ विण्मूत्रादिमये।'),
('nilakantha-sc:source:16.17','Nīlakaṇṭha','gita.16.17','sa','commentary','।।16.17।।आत्मनैवात्मानं महान्तं मन्यन्ते ते आत्मसंभाविताः। स्तब्धाः अप्रणताः। धननिमित्तो मानो गर्वो मद उन्मत्तता ताभ्यामन्विताः धनमानमदान्विताः। नामयज्ञैर्नाममात्रैर्यज्ञैः। दम्भेन धर्मध्वजितया अविधिपूर्वकं यथोक्तधनज्ञानस्वयमृत्विक्पत्न्यादिशुद्धिरहितं यजन्ते।'),
('nilakantha-sc:source:16.18','Nīlakaṇṭha','gita.16.18','sa','commentary','।।16.18।।अहंकारोऽहमेव सर्वश्रेष्ठ इति बुद्धिः। बलं शारीरं धनाभिजननिमित्तं च। दर्पं परावज्ञाम्। कामं क्रोधं च संश्रिताः। मां सर्वदेहेषु प्रविष्टम्। आत्मदेहे स्वदेहशोषणेनकर्षयन्तः शरीरस्थं भूतग्राममचेतसः। मां चैवान्तःशरीरस्थं तान्विद्ध्यासुरनिश्चयान् इति वक्ष्यमाणदिशा परदेहे च हिंसादिना प्रद्विषन्तः। अभ्यसूयकाः सर्वत्र गुणेषु वेदोक्तेषु शमादिषु अशक्तत्वादिलक्षणं दोषमारोपयन्तः।'),
('nilakantha-sc:source:16.19','Nīlakaṇṭha','gita.16.19','sa','commentary','।।16.19।।तेषां फलमाह -- तानिति। सर्वभूतसमोऽप्यहं तान् वेदोक्तशासनातिगान् भूतद्रोहकर्तृ़न्। अहमन्तरात्मा न तु तटस्थो येन मम वैषम्यं स्यात्। पूर्वसंस्कारात्ते तथैव पापं कुर्वन्ति तदनुरूपं फलं च प्राप्नुवन्तीत्यर्थः।'),
('nilakantha-sc:source:16.20','Nīlakaṇṭha','gita.16.20','sa','commentary','।।16.20।।आसुरयोनिप्राप्तेरपि फलमाह -- आसुरीमिति। अधमां नारकीम्। तिर्यक्स्थावरादिरूपां वा।'),
('nilakantha-sc:source:16.21','Nīlakaṇṭha','gita.16.21','sa','commentary','।।16.21।।संक्षेपमासुर्याः संपत्तेराह -- त्रिविधमिति।'),
('nilakantha-sc:source:16.22','Nīlakaṇṭha','gita.16.22','sa','commentary','।।16.22।।कामादित्रयत्यागे किं स्यादत आह -- एतैरिति। तमोद्वारैः तमसो नरकस्य दुःखमोहात्मकस्य द्वारभूतैर्विमुक्तः सन्। आत्मनः श्रेयः कल्याणं भगवदाराधनादिकमाचरति। ततः परां गतिं मोक्षं याति तस्मात्कामादित्रयं त्यजेदिति।'),
('nilakantha-sc:source:16.23','Nīlakaṇṭha','gita.16.23','sa','commentary','।।16.23।।न केवलं काष्ठतपस्विवत्कामादित्यागमात्रेणोच्छास्त्रवर्ती सिध्यतीत्याह -- य इति। शास्त्रविधिं शास्त्रेण इष्टसाधनतयाऽनिष्टसाधनतया च ज्ञापितंब्राह्मणो यजेत?न सुरां पिबेत् इत्यादिना विहितं निषिद्धं च उत्सृज्य विहितमकरणेन निषिद्धमाचरणेन च उत्सृज्य यो वर्तते कामकारत इच्छया स सिद्धिं चित्तशुद्धिं,सुखं वैराग्यादिजनितां तृप्तिं परां गतिं मोक्षं च नावाप्नोति।'),
('nilakantha-sc:source:16.24','Nīlakaṇṭha','gita.16.24','sa','commentary','।।16.24।।यस्माच्छास्त्रातिगः शुद्ध्यादिकं त्रयं नाप्नोति तस्मात्ते तव शुद्ध्यादिकामस्य शास्त्रमेव प्रमाणं किं कार्यं किं न कार्यमित्यस्यां व्यवस्थायाम्। एवं ज्ञात्वा शास्त्रं इदं कर्तव्यमिदं न कर्तव्यमिति शासनं वेदाज्ञारूपं? विधानं च तदुल्लङ्घने प्रतिसमाधानम्। अग्निहोत्राद्यकरणेऽयं दोषस्तत्परिहारार्थमिदं कृच्छ्रादिकं प्रायश्चित्तम्। ब्रह्महत्यादिकरणेऽयं दोषस्तत्परिहारार्थमिदमश्वमेधादि अन्यद्वा प्रायश्चित्तम्। शास्त्रं च विधानं च ताभ्यामुक्तं कर्म इह मनुष्यलोके कर्तुमर्हसि। लोकान्तरे कर्मस्वनधिकारं दर्शयितुमिहेत्युक्तम् तदेवं शास्त्रानुवर्तिन एव चित्तशुद्ध्यादिकं नान्यस्येति सिद्धम्।'),
('nilakantha-sc:source:17.1','Nīlakaṇṭha','gita.17.1','sa','commentary','।।17.1।।तस्माच्छास्त्रं प्रमाणं ते इति प्रश्नबीजमुपलभ्यार्जुन उवाच -- य इति। ये पुरुषाः शास्त्रविधिम्। शास्त्रपदेनात्र श्रुतिसदाचारकुलाचारा गृह्यन्ते। सर्वेषां तेषां धर्मे प्रमाणत्वात्। तत्र योऽधिगतो विधिर्विधेयं तदुत्सृज्य सर्वात्मना परित्यज्य यजन्ते पूजयन्ति तातकूपादीन्। मत्पित्रा कृतोऽयं कूपो गङ्गाशतादप्यधिकोऽत्रैव स्नानपानावगाहनपरिचर्याप्रदक्षिणप्रक्रणरूपादेतत्सेवनादहमिष्टं फलमवश्यं प्राप्स्यामीति तत्र दृढतरया श्रद्धयान्विताः सन्तस्तेषां निष्ठा इयं का कीदृशी किं सत्त्वं सात्त्विकी वा पित्र्ये कूपे श्रद्धाधिक्यदर्शनात्। किं रजः राजसी वा तेषां निष्ठा शास्त्रातिक्रमेण कामकाररूपत्वात्। आहो इति प्रश्ने। किं तमः तामसी वा सा निष्ठा रङ्गे रजतधीरिवाशास्त्रीयाया अल्पे महत्त्वबुद्धेर्विपर्यासरूपाया दर्शनात्। यदपि तु भाष्ये वृद्धव्यवहारदर्शनादेव श्रद्दधानतया देवादीन्यजन्त इत्युक्तं? तत्राप्यविगीत एव वृद्धव्यवहारो ग्राह्यः। अविगीतेऽस्मिंस्तामसत्वादिशङ्काया अयोगात्।'),
('nilakantha-sc:source:17.2','Nīlakaṇṭha','gita.17.2','sa','commentary','।।17.2।।एवं सामान्यतः पृष्टे सामान्यमेवोत्तरं श्रीभगवानुवाच -- त्रिविधेति। स्वभावः प्राग्भवीयौ धर्माधर्मौ ततो जाता स्वभावजा। यदि प्राग्भवे सात्त्विको देवतापूजादिधर्मोऽनेनानुष्ठितस्तर्हि तस्य शुद्धसात्त्विक्येव श्रद्धा भवति। यदि राजसो यक्षादिपूजारूपस्तर्हि राजस्येव। यदि तामसो भूतप्रेतादिपूजारूपस्तर्हि तामसी श्रद्धा भवति। एवं त्रिविधा श्रद्धा देहिनां देहाभिमानवतां भवति तां मया व्याख्यास्यमानां शृणु।'),
('nilakantha-sc:source:17.3','Nīlakaṇṭha','gita.17.3','sa','commentary','।।17.3।।ननुश्रद्धावित्तो भूत्वात्मन्येवात्मानं पश्येत् इति श्रद्धाया आत्मदर्शने साधनेष्वन्तरङ्गत्वमुच्यते कथं तस्या राजसत्वं तामसत्वं चोच्यत इत्यत आह -- सत्त्वेति। प्राक्कर्मसंस्कारोपतं यादृशं बुद्धिसत्त्वं सात्त्विकं राजसं तामसं वा तदनुरूपैव सात्त्विक्यादिरूपा देवतादिपूजा सुफलावश्यंभावनिश्चयात्मिका श्रद्धापि भवति। तथायं पुरुषोऽपि श्रद्धामयः श्रद्धाप्रधानो यो यच्छ्रद्धो यो यया श्रद्धयोपेतः स एव स इति सात्त्विक्या श्रद्धयोपेतः सात्त्विक एव राजस्या राजसस्तामस्या तामस इति। एवं सति यदि तातकूपभक्तः पूर्वपुण्यवशात्तातं देववन्मन्यते तर्हि तं सात्त्विकं पुण्डरीकमिव देवा अनुगृह्णन्ति नित्यकर्मत्यागनिमित्तमपि दोषमस्यापनुदन्ति। यदि त्वेनं मन्त्रादिना सिद्धं पूर्ववासनावशाद्यक्षादिरूपं मन्यते तदा तं राजसं राजसा यक्षा एवानुगृह्णन्ति। नास्य कामकारवतो नित्यकर्मत्यागजं दोषमपनेतुमर्हन्ति। नहि देवतापराधी यक्षैस्त्रातुं शक्यते। यदि त्वयं प्रेतः पिता मत्कुटुम्बं माबाधिष्टेति सर्वं धर्मं त्यक्त्वा एनमस्य प्रियं कूपं पूजयामीति मन्यते तदां तं पितरि प्रेतत्वबुद्धियोगाद्विपर्यस्तं तामसं प्रेता एवानुगृह्णन्ति क्षुद्रभोगैर्देवाश्च नरके पातयन्ति।'),
('nilakantha-sc:source:17.4','Nīlakaṇṭha','gita.17.4','sa','commentary','।।17.4।।कुत एतदेवं कल्प्यते यस्मात्सात्त्विकादयो देवादीनेव यजन्ते इत्याह -- यजन्त इति। यजन्ते पूजयन्ति।'),
('nilakantha-sc:source:17.5','Nīlakaṇṭha','gita.17.5','sa','commentary','।।17.5।।सात्त्विकानां दौर्लभ्यमभिप्रेत्याह -- अशास्त्रेति। शास्त्रं वेदादि तद्विरोधिना कौलिकाद्यागमेन विहितं घोरं स्वमांसहोमेन ब्राह्मणलोहितादिना वा देवतासंतर्पणाद्यात्मकं ये जनास्तपस्तप्यन्ते तानासुरनिश्चयान्विद्धीति द्वयोः संबन्धः। दम्भो धर्मध्वजित्वम्? अहंकारः स्वस्मिन्पूज्यताबुद्धिः ताभ्यां संयुक्ताः। कामरागो विषयाभिलाषः? बलं साहसेनापि विषयसाधने उत्साहस्ताभ्यामन्विताः।'),
('nilakantha-sc:source:17.6','Nīlakaṇṭha','gita.17.6','sa','commentary','।।17.6।।कर्शयन्तः कृशं कुर्वन्तः। भूतग्रामं करणसमूहम्। अचेतसो मूढाः। मां चान्तःशरीरस्थं भोक्तृरूपेण शरीरान्तःस्थं मां परमेश्वरं वा भोग्यस्य शरीरस्य कृशीकरणेन मदाज्ञालङ्घनेन वा कृशीकुर्वन्तः तान्विद्ध्यासुरनिश्चयान्।'),
('nilakantha-sc:source:17.7','Nīlakaṇṭha','gita.17.7','sa','commentary','।।17.7।।अत्र सात्त्विकानां श्रद्धाराध्याहारयज्ञतपोदानानां परिग्रहार्थं राजसतामसानां वर्जनार्थं च तेषां प्रत्येकं त्रैविध्यं विधीयते। तत्रापि श्रद्धात्रैविध्यं आराध्यत्रैविध्यं च प्रागेवोक्तम्। आहारादीनां त्रैविध्यं प्रतिज्ञापूर्वकमाह -- आहारस्त्विति। आह्रियत इत्याहारोऽन्नं। अतः परं प्रायेण पदार्थः स्पष्टस्तथापि क्वचित्क्वचित्किंचित्किंचिद्व्याख्यायते।'),
('nilakantha-sc:source:17.8','Nīlakaṇṭha','gita.17.8','sa','commentary','।।17.8।।आयुर्जीवनम्। सत्त्वमुत्साहः। बलं शक्तिः। आरोग्यं रोगराहित्यम्। सुखं चित्तप्रसादः। प्रीतिरभिरुचिः। एतेषां विवर्धनाः वृद्धिकराः ते आयुःसत्त्वबलारोग्यसुखप्रीतिविवर्धनाः? रस्याः रसोपेताः? स्निग्धाः? स्नेहवन्तः? स्थिराः देहे रसांशेन चिरकालस्थायिनः? हृद्याः दृष्टमात्रा एव हृदयप्रियाः? आहाराः घृतक्षीरसितादयः सात्त्विकप्रियाः।'),
('nilakantha-sc:source:17.9','Nīlakaṇṭha','gita.17.9','sa','commentary','।।17.9।।कट्विति। अतिशब्दः सर्वत्र संबध्यते। अतिकटु निम्बादि? अत्यम्लातिलवणात्युष्णाः प्रसिद्धाः? अतितीक्ष्णो मरीचादि? अतिरूक्षः स्नेहशून्यः कङ्गुकोद्रवादिः? अतिविदाही राजिकादिः? दुःखं तात्कालिकी पीडा? शोकः पश्चाद्भाविदौर्मनस्यम्? आमयो धातुवैषम्यापादनेन रोगस्तत्प्रदाः।'),
('nilakantha-sc:source:17.10','Nīlakaṇṭha','gita.17.10','sa','commentary','।।17.10।।यातयामं प्रहरात्प्राक्कृतं शीतलतां गतमित्यर्थः। यातयामं अर्धपक्वं निर्वीर्यस्य गतरसेनैवोक्तत्वादिति भाष्यम्। गतरसं रसविमुक्तम्? पूति दुर्गन्धि? पर्युषितं पक्वं सद्रात्र्यन्तरितम्? उच्छिष्टं भुक्तावशिष्टम्? अमेध्यं यज्ञानर्हम्? भोजनं अन्नं तामसप्रियम्।'),
('nilakantha-sc:source:17.11','Nīlakaṇṭha','gita.17.11','sa','commentary','।।17.11।।यज्ञत्रैविध्यमाह -- अफलेति। विधिदृष्टः आवश्यकतया विहितः। यष्टव्यमेव न तु यज्ञाद्दृष्टमदृष्टं वा फलं प्राप्तव्यमिति मनः समाधाय समाहितं कृत्वा यो यज्ञ इज्यते स सात्त्विकः।'),
('nilakantha-sc:source:17.12','Nīlakaṇṭha','gita.17.12','sa','commentary','।।17.12।।राजसं यज्ञमाह -- अभिसंधायेति। विधिहीनं शास्त्रोक्तविधिहीनम्। असृष्टं न दत्तमन्नं यस्मिन् तं असृष्टान्नम्।'),
('nilakantha-sc:source:17.13','Nīlakaṇṭha','gita.17.13','sa','commentary','।।17.13।।विधिहीनं शास्त्रोक्तविधिहीनम्। असृष्टं न दत्तमन्नं यस्मिन् तं असृष्टान्नम्।'),
('nilakantha-sc:source:17.14','Nīlakaṇṭha','gita.17.14','sa','commentary','।।17.14।।देवाः विष्ण्वाद्याः? द्विजा ब्राह्मणाः? गुरवो मातृपित्राचार्यादयः? प्राज्ञाः ब्रह्मनिष्ठाः? तेषां पूजनम्। आर्जवमकौटिल्यम्।'),
('nilakantha-sc:source:17.15','Nīlakaṇṭha','gita.17.15','sa','commentary','।।17.15।।प्रियं च तत् हितं च प्रियहितम्। श्रवणकाले परिणामे च सुखदमित्यर्थः।'),
('nilakantha-sc:source:17.16','Nīlakaṇṭha','gita.17.16','sa','commentary','।।17.16।।मनःप्रसादः रागद्वेषादिराहित्यम्। सौम्यत्वं परहितैषित्वम्। मौनं वाक्संयमः। आत्मविनिग्रहो मनोनिरोधः। भावशुद्धिः परैर्व्यवहारकाले मायाराहित्यम्? इति एवंप्रकारं अन्यद्दयादिकं एतन्मानसं तप उच्यते।'),
('nilakantha-sc:source:17.17','Nīlakaṇṭha','gita.17.17','sa','commentary','।।17.17।।त्रिविधं कायिकवाचिकमानसभेदेन। युक्तैरवहितैः।'),
('nilakantha-sc:source:17.18','Nīlakaṇṭha','gita.17.18','sa','commentary','।।17.18।।सत्कारः लोके साधुरयमिति वाक्पूजा। मानोऽभ्युत्थानाभिवादनादिकायिकी पूजा। पूजा लाभादि। एतदर्थं दम्भेन च यत्तपः क्रियते तद्राजसन्। चलं विनाशि। अध्रुवमनिश्चितफलम्।'),
('nilakantha-sc:source:17.19','Nīlakaṇṭha','gita.17.19','sa','commentary','।।17.19।।मूढग्राहेणाविवेककृतेन दुराग्रहेण। आत्मनः शरीरस्य उत्सादनार्थं विनाशार्थम्।'),
('nilakantha-sc:source:17.20','Nīlakaṇṭha','gita.17.20','sa','commentary','।।17.20।।दातव्यमेवेति बुद्ध्या यद्दानं प्रदेयद्रव्यं दीयते न तु फलमुद्दिश्य दीयते। कस्मै अनुपकारिणे प्रत्युपकारासमर्थाय। देशे कुरुक्षेत्रादौ काले संक्रान्त्यादौ यद्दीयते तत्सात्त्विकमिति संबन्धः। यच्च पात्रे दानं समर्पणं तदपि सात्त्विकमिति योजना। अत्र आद्यो दानशब्दः कर्मणि व्युत्पन्नः प्रदेयद्रव्यवाची कर्मभूतः। तत्संयोगात्संप्रदाने चतुर्थ्यपेक्षा। द्वितीयस्तु भावव्युत्पन्नस्त्यागमात्रवाची। तेन तत्र पात्रभूते पुंसि न चतुर्थ्यपेक्षाकर्मणा यमभिप्रैति स संप्रदानम् इति हि पारिभाषिक्याः संप्रदानसंज्ञाया अत्र कर्मविभक्त्यभावेनाप्रवृत्तेः तेन पात्रे इति चतुर्थ्यर्थे सप्तमीति वा? पातृशब्दस्य चतुर्थीयमिति वा कल्पनं व्यर्थमेव। दानशब्दस्यावृत्त्या च देशकालानुपकारित्वविशिष्टे दानमित्येका कोटिः। पात्रे दानमित्यपरा। उभयसमुच्चये तु महान्गुण इति भावः।'),
('nilakantha-sc:source:17.21','Nīlakaṇṭha','gita.17.21','sa','commentary','।।17.21।।परिक्लिष्टं कथमेतावद्द्रव्यव्ययः कर्तव्य इत्याकुलतायुक्तं यथा स्यात्तथा दीयत इति क्रियाविशेषणम्।'),
('nilakantha-sc:source:17.22','Nīlakaṇṭha','gita.17.22','sa','commentary','।।17.22।।असत्कृतं प्रियभाषणपादप्रक्षालनादिपूजासत्कारस्तद्रहितम्। अवज्ञातं पात्रपरिभवयुक्तम्। दानं प्रदेयं हिरण्यादि।');
INSERT INTO commentary_fts (unit_id,author,canonical_ref,language,content_type,content) VALUES
('nilakantha-sc:source:17.23','Nīlakaṇṭha','gita.17.23','sa','commentary','।।17.23।।अदृष्टार्थानां यज्ञदानतपःप्रभृतीनां वैकल्यशङ्कायां साद्गुण्यसिद्ध्यर्थं प्रायश्चित्तमुपदिश्यते -- तत्सदिति। ओमिति तदिति सदिति च त्रिविधस्त्रिप्रकारोऽयं ब्रह्मणो निर्देशो नाम्नां पाठः। यथा सहस्रनाम्नां पाठे सहस्रं नामानि एवमस्मिन्नपि नामपाठे त्रीण्येव नामानीत्यर्थः।ओमिति ब्रह्म इति तैत्तिरीयके?तदिति वा एतस्य महतो भूतस्य नाम भवति इत्यैतरेयके?सदेव सोम्येदमग्र आसीत् इति छान्दोग्ये च एतेषां शब्दानां ब्रह्मनामत्वप्रसिद्धेः। तेन नामत्रयेण ब्राह्मणादयो विहिताः। पुरा सर्गादौ ब्राह्मणाः एतन्नामत्रयोच्चारणसामर्थ्येनैव विधात्रा विप्रादयो विहिताः। प्रकाशिता इत्यर्थः।'),
('nilakantha-sc:source:17.24','Nīlakaṇṭha','gita.17.24','sa','commentary','।।17.24।।यस्मादेतन्नामत्रयपूर्वकं एतेषां विधानं सर्गादौ दृष्टं तस्मात्ित्रष्वेतेषु नामसु ओमित्येकमेव नाम उदाहृत्य ब्रह्मवादिनां वैदिकानां विधानोक्ताः वेदोक्ताः यज्ञादयः क्रियाः सततं प्रवर्तन्ते। तथा च श्रुतिःमिति ब्रह्मा प्रसौति मिति शास्त्राणि शंसन्ति मित्यध्वर्युः प्रतिगरं प्रतिगृणाति मिति सामानि गायन्ति इति यज्ञे सर्वेषामृत्विजां क्रिया कारपूर्विक इत्येतद्दर्शयति।'),
('nilakantha-sc:source:17.25','Nīlakaṇṭha','gita.17.25','sa','commentary','।।17.25।।मिति नाम्नः काम्याकाम्यकर्मसाधारण्येन यज्ञादौ विनियोगमुक्त्वा तदिति नाम्नो निष्कामेषु मुमुक्षुकर्मसु विनियोगं दर्शयति -- तदिति। मोक्षकाङ्क्षिभिः फलमनभिसंधाय विविधाः यज्ञतपःक्रियाः दानक्रियाश्च क्रियन्ते इति योजना। ननु फलं चेन्नाभिसंधीयते तर्हि किमभिसंधाय क्रियन्त इत्याकाङ्क्षायामाह -- तदिति। क्रियन्ते इति। सर्वाः क्रियास्तदिति ब्रह्मेति क्रियन्ते। यथा ब्रह्मवादिभिःब्रह्मार्पणं ब्रह्म हविर्ब्रह्माग्नौ ब्रह्मणा हुतम्। ब्रह्मैव तेन गन्तव्यं ब्रह्मकर्मसमाधिना इत्युक्तदिशा सर्वाः ससाधनफलाः क्रियाः ब्रह्मैवेदं सर्वमितिबुद्ध्या क्रियन्ते तथा मुमुक्षुभिरपीत्यर्थः। यदेव हि मुक्तानां स्वाभाविकं शीलं तदेव मुमुक्षूणां शास्त्रेण विधीयत इति प्रसिद्धेः। फलमनभिसंधायेति सान्निध्यात्तदितीत्यत्रापि सामर्थ्यादभिसंधायेति लभ्यते। तेन फलमनभिसंधाय तदित्यभिसंधाय क्रियाः प्रवर्तन्त इत्यन्वयोऽपि सुलभ एव। तदिति ब्रह्माभिधानमुच्चार्येति भाष्येऽपि उदाहृत्येति पूर्वश्लोकोक्तक्रियानुवृत्त्या योजनमस्मदुक्ताभिप्रायेणैव व्याख्येयम् उच्चारणस्यापि ब्रह्मानुसंधानार्थत्वादिति दिक्।'),
('nilakantha-sc:source:17.26','Nīlakaṇṭha','gita.17.26','sa','commentary','।।17.26।।तच्छब्दयोर्विनियोगमुक्त्वा सच्छब्दस्य विनियोगमाह द्वाभ्याम् -- सद्भावे इति। सद्भावे अस्तित्वे साधुभावे समीचीनत्वे सच्छब्दः सदिदं कर्मेति प्रशस्ते कर्मणि सत्सत्त्वं वेदोक्तत्वादस्त्येवेति सच्छब्दः प्रयुज्यते आस्तिकैः।'),
('nilakantha-sc:source:17.27','Nīlakaṇṭha','gita.17.27','sa','commentary','।।17.27।।किंच यज्ञादौ स्थितिर्निष्ठा सदिति समीचीनेति उच्यते। तदर्थः सच्छब्दार्थो ब्रह्म तदीयं तदर्थं कृतं तदर्थीयं परमेश्वरप्राप्त्यर्थं कृतं कर्म सदित्येव समीचीनमित्येवाभिधीयते लोके। तदेवं असात्त्विकं विगुणं वा यज्ञादिकं श्रद्धापूर्वकं ब्रह्मणोऽभिधानत्रयोच्चारणेन सात्त्विकं सद्गुणं च संपादितं भवति।'),
('nilakantha-sc:source:17.28','Nīlakaṇṭha','gita.17.28','sa','commentary','।।17.28।।सर्वत्र श्रद्धैव साद्गुण्यहेतुरिति व्यतिरेकमुखेनाह -- अश्रद्धयेति। हुतं होमः। दत्तं दानम्। तपस्तप्तमनुष्ठितम् कृतमश्रद्धया विहितं भगवन्नामस्मरणमपि यच्चान्यत्तत्सर्वमसत् अभावभूतमित्युच्यते। पार्थ? अतएव तत् प्रेत्य मृत्वा परलोके नोपयुज्यते। इहास्मिन् लोके वा नो नैवोपयुज्यते। तस्मात् श्रद्धैव सात्त्विकी मातेव सुखकामैः शरणीकरणीयेति भावः।'),
('nilakantha-sc:source:18.1','Nīlakaṇṭha','gita.18.1','sa','commentary','।।18.1।।अस्यामष्टादशाध्याय्यां प्रथमे उपोद्धातितानां द्वितीये सूत्रितानां शेषैर्व्युत्पादितानामर्थानां कात्स्न्र्येनोपसंहारार्थोऽयमन्तिमोऽध्याय आरभ्यते। तत्र पूर्वाध्यायान्तेऽश्रद्धया कृतं सर्वं व्यर्थमित्युक्तम्। तत्र फलावश्यंभावनिश्चयः श्रद्धा सा च फलवतां कर्मणामेवाङ्गं न तु कर्मविरहरूपस्य संन्यासस्य भावरूपफलवर्जितस्य। अभावाद्भावोत्पत्तेरयोगात्। तस्माच्छ्रद्धासापेक्षकर्मापेक्षया श्रद्धानपेक्षः संन्यासः श्रेयान्। नचास्यैवंरूपस्य श्रद्धात्रैविध्यप्रयुक्तं सात्त्विकादिभेदेन त्रैविध्यं संभवति। येन फले तारतम्यं स्यात्। तत्फलस्य दृष्टविक्षेपनिवृत्तिरूपस्य सर्वत्र तुल्यत्वात्। स च संन्यासो यदि कर्मत्याग एव तर्हि सिद्धं नः समीहितम्। यदि तु तौ भिन्नौ तर्हि तयोर्वैलक्षण्यं विचार्यमित्याशयेनार्जुन उवाच -- संन्यासस्येति। हे महाबाहो हे हृषीकेश हे केशिनिषूदनेति बहुकृत्वः संबोधयन् जिज्ञासितेऽर्थेत्यादरं दर्शयति। संन्यासस्य तत्त्वं याथात्म्यं त्यागात्पृथग्भूतं वेदितुमिच्छामि। त्यागस्य याथात्म्यं संन्यासात्पृथग्भूतं वेदितुमिच्छामीति चकारेणानुवर्त्यते।'),
('nilakantha-sc:source:18.2','Nīlakaṇṭha','gita.18.2','sa','commentary','Sanskrit Commentary By Sri Neelkanth।।18.2।।अत्रोत्तरं श्रीभगवानुवाच -- काम्यानामिति। काम्यानां रागतः प्राप्तानां पुत्रकामेष्ट्यादीनां न तु फलस्य कामनाविषयत्वात् सर्वस्य कर्मणः फलवत्त्वनियमात् सर्वं कर्म काम्यमेवेति नित्यादीनामपि मुमुक्षोस्त्यागः स्यादिति सिद्धं नः समीहितमित्याशङ्क्याह -- सर्वेति। सर्वेषां नित्यनैमित्तिककाम्यानां कर्मणां फलत्यागमेव त्यागं विचक्षणाः प्राहुर्न स्वरूपतस्त्यागं प्राहुः। अतो न त्वदिष्टः संन्यासः सिद्ध्यतीत्यर्थः। अयमाशयः -- यद्यपि संन्यासत्यागशब्दौ निवृत्तिमेव ब्रूतः तथापि सा वैराग्याद्वा कायक्लेशभयाद्वा मौढ्याद्वा भवतीति तत्कारणानां सात्त्विकादिभेदेन भिन्नत्वात्तस्या अपि सात्त्विकराजसतामसभेदेन त्रैविध्यं त्रिविधश्रद्धाप्रधानत्वं च दुर्वारम्। न चाविरक्तोऽश्रद्दधानश्च त्यक्तकर्मापि दृष्टविक्षेपहीनो दृश्यते। यथोक्तं वार्तिकाचार्यैःप्रमादिनो बहिश्चित्ताः पिशुनाः कलहोत्सुकाः। संन्यासिनोऽपि दृश्यन्ते दैवसंदूषिताशयाः। इति। तस्मादविरक्तकृतसंन्यासापेक्षया निष्कामकर्माचरणमेव श्रेय इत्याशयेन भगवता काम्यकर्मत्यागः संन्यासत्वेन नित्यादिकर्मणां फलानभिसंधानं च त्यागत्वेन स्तूयत इति। तस्मादश्रद्धया कृतः संन्यासोऽप्यसन्नेवेति संन्यासाद्ब्रह्मणः स्थानमिति स्मृतं स्वफलं दातुं न समर्थ इति युक्तमुक्तं भगवता अश्रद्धया कृतं सर्वं व्यर्थमिति। यत्तु नित्यानामेव विविदिषायोगात्काम्यानां स्वरूपतोऽपि त्यागः पूर्वार्धस्यार्थः। सर्वेषां कर्मणां फलतस्त्याग इत्युत्तरार्धार्थ इति व्याख्यानं पक्षद्वयप्रदर्शनपरं तदग्रिमेण श्लोकेन पौनरुक्त्यमावहतीत्युपेक्षितम्।'),
('nilakantha-sc:source:18.3','Nīlakaṇṭha','gita.18.3','sa','commentary','।।18.3।।इदमेव पक्षद्वयमाह -- त्याज्यमिति। एके मुख्याः मनीषिणो मनोनिग्रहसमर्थाः परमात्मनि उत्पन्नविविदिषाणां पुरुषाणां दोषवत् रागादयो यथा त्याज्यास्तद्वत् कर्म त्याज्यमिति प्राहुः। अपरे तु विविदिषार्थिना यज्ञादिकं न त्याज्यमिति वा प्राहुरित्यनुवर्तते। तथा च द्विविधाः श्रुतय उपलभ्यन्तेन कर्मणा न प्रजया धनेन त्यागेनैके अमृतत्वमानशुःकुर्वन्नेवेह कर्माणि जिजीविषेच्छतं समाः इत्याद्याः। अविद्वद्विषयमेवैतत्पक्षद्वयम्। विदुषां तु कर्मसु प्रवृत्तिकारणस्याज्ञानस्य नष्टत्वात्स्वतःसिद्ध एव त्याग इति न तान्प्रति कर्मविधिर्वा तत्त्यागविधिर्वा प्रवर्तते। यथोक्तंन कर्माणि त्यजेद्योगी कर्मभिस्त्यज्यते ह्यसौ इति।'),
('nilakantha-sc:source:18.4','Nīlakaṇṭha','gita.18.4','sa','commentary','।।18.4।।निश्चयमिति। तत्र कर्मणां त्यागात्त्यागविषये विप्रतिपत्तौ सत्यां प्रथमोपात्ते त्यागे विषये मे मद्वचनान्निश्चयं श्रृणु। हि यस्मात् हे पुरुषव्याघ्र? त्यागः त्रिविधः सात्त्विकराजसतामसभेदेन त्रिप्रकारः परिकीर्तितः शास्त्रे। दृढवैराग्यपूर्वकः कर्मसंन्यासः सात्त्विकः? आयासभयात्तत्त्यागो राजसः? मौढ्यात्तत्त्यागस्तामस इति? तस्माद्गहनत्वात्त्यागो निश्चयेन विचारणीय इत्यर्थः।'),
('nilakantha-sc:source:18.5','Nīlakaṇṭha','gita.18.5','sa','commentary','।।18.5।।सूचीकटाहन्यायेन त्यागस्वरूपकथनात्प्राक् परमतमत्यागपक्षं उपन्यस्यति -- यज्ञेति। यज्ञादिकं कर्म न त्याज्यं किंतु कार्यमेव विष्टिगृहीततेनेव पुंसा अवश्यमनुष्ठेयमेव तत्। अकरणे प्रत्यवायश्रवणात्। चकारो हेत्वर्थः। यस्माद्यज्ञो दानं तपश्चैव मनीषिणां निष्कामानां दम्भादिरहितानां पावनानि चित्तशोधकानि। तथा च श्रुतिःत्रयो धर्मस्कन्धा यज्ञोऽध्ययनं दानमिति प्रथमस्तप एव द्वितीयो ब्रह्मचर्याचार्यकुलवासी तृतीयः सर्व एते पुण्यलोका भवन्ति इति यज्ञादीनां गृहस्थधर्माणां तपसो वनस्थधर्मस्याचार्यकुलवासस्य ब्रह्मचारिधर्मस्य च पावनत्वं दर्शयति। अत्रापि यज्ञदानशब्देन गृहस्थधर्मा ज्ञेयाः? तप इति वानप्रस्थधर्माः? परिशेषात्कर्मेति ब्रह्मचारिधर्माश्च ज्ञेयाः।'),
('nilakantha-sc:source:18.6','Nīlakaṇṭha','gita.18.6','sa','commentary','।।18.6।।एवमत्यागपक्षमुक्त्वा औत्सुक्यात्प्रथमं स्वाभिमतं त्यागात्यागसमुच्चयपक्षं दर्शयति -- एतानीति। तुशब्दः पूर्वोपन्यस्तात्पक्षाद्वैलक्षण्यं दर्शयति। अपिशब्द एवशब्दार्थः। एतान्येव कर्माणि यज्ञदानतपांसि संङ्गं त्यक्त्वा अहमेतेषां कर्ता मयावश्यमेतानि कर्तव्यानीत्यभिमानं वयोवर्णाद्यध्यासनिमित्तं त्यक्त्वा एतैः कृतैरहं स्वर्गं वा चित्तशुद्धिं वा ज्ञानं वा प्राप्स्यामीति फलानि च त्यक्त्वा? चकारादेषामकरणे मम प्रत्यवायो भविष्यतीत्येतमप्यभिसन्धिं त्यक्त्वा ब्रह्मनिष्ठेनेवासङ्गस्वभावेन पुरुषेण कर्तव्यानीति एवं प्रकारं मे मम मतम् उत्तमं पूर्वमताच्छ्रेष्ठम्। तत्र हि कर्तृत्वाभिमानरूपेण सङ्गेन प्रत्यवायोत्पादभयाच्च कर्मानुष्ठानं विहितम्। अत्र तु तदभावादसङ्गत्वाद्यंशेन कर्मणां त्यागः स्वरूपेणात्याग इति भेदः।'),
('nilakantha-sc:source:18.7','Nīlakaṇṭha','gita.18.7','sa','commentary','।।18.7।।प्राक् प्रतिज्ञातं त्यागत्रैविध्यमाह -- नियतस्येति। तुशब्दः पूर्वोक्तपक्षद्वयवैलक्षण्यार्थः। यस्मादधिकृतस्य मुमुक्षोर्नियतस्यावश्यानुष्ठेयस्य कर्मणः संन्यासः स्वरूपेण त्यागो नोपपद्यते न युज्यते। अज्ञस्य शुद्ध्यपेक्षत्वात्। एवं सति यो मोहादज्ञानात्तस्य नियतस्य कर्मणः परित्यागः स तामसः परिकीर्तितः। आवश्यकं च त्यज्यते चेति विप्रतिषेधात्।'),
('nilakantha-sc:source:18.8','Nīlakaṇṭha','gita.18.8','sa','commentary','।।18.8।।एवं तामसं त्यागमुक्त्वा राजसं त्यागमाह -- दुःखमिति। यः दुःखरूपमेवेदं कर्मेति मत्वा कालक्लेशभयात् यत्त्यजेत् स पुमान् तस्मादेव हेतोः राजसं रजोगुणनिर्वृत्तं त्यागं कृत्वा त्यागफलं चित्तशुद्धिद्वारा मोक्षं नैव लभेत् लभेत।'),
('nilakantha-sc:source:18.9','Nīlakaṇṭha','gita.18.9','sa','commentary','।।18.9।।एवं द्वाभ्यां श्लोकाभ्यां तामसराजसौ मुख्यावेव त्यागावुक्तौ। तामसराजसयोरमुख्यत्यागयोरसंभवस्य भगवतैव मोहात्तस्य परित्याग इति कायक्लेशभयाः त्यजेदिति च सूचनात्। नह्येवं संभवति। मूढश्च करोति चेति विप्रतिषेधात्। यदि करोति नैव मूढः? यदि मूढस्तर्हि नैव करोति। एवं यदि कायक्लेशाद्बिभेति नैव करोति? यदि करोति नैव कायक्लेशाद्बिभेति तस्मात्करोति च कायक्लेशाद्बिभेति चेति विप्रतिषिद्धम्। अतस्तामसराजसयोरमुख्यत्यागयोरसंभवात्तौ नैवोक्तौ। सात्त्विकस्त्वमुख्यत्यागः संभवति। यथा स्फटिके जपाकुसुमाश्रिते लौहित्यं विवेकिनां प्रतीतित एवास्ति न वस्तुत एवमात्मनि ईश्वराधीने विवेकिनां कर्तृत्वं प्रतीतित एवास्ति न वस्तुत इति वक्तुं शक्यम्। एवंच कर्तृत्वाभिनिवेशशून्यः पुमान् प्रतीतितः करोत्येव न वस्तुत इति संभवत्यमुख्योऽपि सात्त्विकस्त्याग इति तमेव मुख्यत्यागेऽधिकारहेतुं प्रथममाह -- कार्यमिति। कार्यं कर्तव्यमित्येव यत्कर्म नियतं नित्यं क्रियते हे अर्जुन? सङ्गं फलं च त्यक्त्वैवेत्यवधारणं प्रागुक्तस्यात्यागपक्षस्य व्यावृत्त्यर्थम्। स एवंभूतस्त्यागः सात्त्विको मतः वेदे दृष्टः। तथा च श्रुतिःईशावास्यमिदं सर्वं यत्किञ्च जगत्यां जगत्। तेन त्यक्तेन भुञ्जीथा मा गृधः कस्यस्विद्धनम् इति। ईशा ईशेन परमेश्वरेण सर्वकार्यकरणकर्त्रात्मप्रवर्तकेन इदं जगत्स्थावरजंगमं जगत्यां ब्रह्माण्डे स्थितं वास्यमाच्छादितं व्याप्तम्। येन हेतुना सर्वं तदधीनं तेन कारणेन त्यक्तेन त्यागेन कर्तृत्वभोक्तृत्वाभिमानवर्जनेन भुञ्जीथाः विषयान्भुङ्क्ष। मा गृधः गर्धं मा कार्षीः। कस्यस्विद्धनं न कस्यापि तत्र स्वामित्वमस्तीति वृथैव तत्र गर्ध इत्यर्थः। एवं कर्माण्यपि यज्ञादीनि कर्तृत्वाभिमानं त्यक्त्वा कुर्वतस्तव कर्मलेपो न भविष्यति। एतद्व्यतिरेकेण तव उपायान्तरं च नास्तीत्यग्रिममन्त्रेण प्रदर्श्यतेकुर्वन्नेवेह कर्माणि जिजीविषेच्छतं समाः। एवं त्वयि नान्यथेतोऽस्ति न कर्म लिप्यते नरे इति। इदमेव मुख्यं स्वमतं भगवता प्रदर्शितम्। एतान्यपि तु कर्माणीति श्लोके। ननु नित्यानां फलमेव नास्ति किं त्यक्तव्यमिति चेत्। इतएव भगवद्वचनात्तेषामपि फलमस्तीति जानीहि। निष्फलस्य वेदेनानुष्ठापनासंभवात्। तथाचापस्तम्बःतद्यथाम्रे फलार्थं निमित्ते छायागन्धावनूत्पद्येते एवं धर्मं चर्यमाणमर्था अनूत्पद्यन्ते इति आनुषङ्गिकं फलं नित्यानां दर्शयति। अकरणे प्रत्यवायस्मृत्यापि तेषां प्रत्यवायपरिहारः फलमिति प्रदर्श्यते।धर्मेण पापमपनुदति इत्यादिना च नित्येष्वपि कर्मसु फलं दृश्यते तदेव वक्तव्यमिति न कोऽपि दोषः।'),
('nilakantha-sc:source:18.10','Nīlakaṇṭha','gita.18.10','sa','commentary','।।18.10।।एवं मुख्यं सात्त्विकत्यागमुक्त्वाऽमुख्यं तमाह -- न द्वेष्टीति। सत्त्वेन सम्यगाविष्टो व्याप्तस्त्यागी मुख्यः सात्त्विकस्त्यागी संन्यासीत्यर्थः। अकुशलमसुखप्रदं कर्म त्रिषवणस्नानचतुर्गुणशौचभिक्षाटनादिप्रयासरूपं,न द्वेष्टि। कुशले मिष्टान्नभिक्षादौ नानुषज्जते न सङ्गं काकवत्प्रीतिं करोति। यद्वा कर्मकुशले सवादिकर्मकुशले शिष्यादौ न सज्जते तत्राकुशलं वा तं न द्वेष्टि। एतेन रागद्वेषशून्यत्वमस्य दर्शितम्। तदपि कुत इत्यपेक्षायामाह -- मेधावीति। ऊहापोहकुशलतया नित्यानित्यवस्तुविवेचनादौ प्रज्ञावान्। अतएव छिन्नसंशयः किं कर्माण्येव मुक्तिसाधनानि उत संन्यास एवेति विचिकित्सारहितः। एवं च त्यागीत्यनेन यज्ञो दानं तपः कर्म न त्याज्यमित्युक्तादत्यागाद्व्यावृत्तिः। मेधावीत्यनेन मोहात्तस्य परित्याग इत्युक्तात्तामसत्यागाद्व्यावृत्तिः। पूर्वार्धेन रागद्वेषाभावप्रतिपादनेन कायक्लेशभयात्त्यजेदित्युक्ताद्राजसत्यागाद्व्यावृत्तिः। छिन्नसंशय इत्यनेन कार्यमित्येव यत्कर्मेत्युक्तादमुख्यसात्त्विकत्यागाद्व्यावृत्तिः। नह्यसौ कर्मणां तुच्छत्वं संन्यासस्य महाभाग्यत्वं च तत्त्वतो वेद। वेद चेत्क्षणमपि कर्मसु न तिष्ठेत्। नहि दाहोपशमार्थी निकटस्थं जाह्नवीमहाह्रदं जानन्ग्रीष्मोष्मप्रतप्तपाथसि पल्वले क्षणमपि रमेत। संशयच्छेदेऽपि हेतुः सत्त्वसमाविष्ट इति। यतः सत्त्वेनैव कर्त्रा सम्यगाविष्टो यं नत्वयं सत्त्वमाश्रित इति महान्विशेषः। एवं च पूर्वश्लोकोक्तस्य सात्त्विकत्यागरूपस्य कर्मयोगस्य फलभूतोऽयं मुख्यः संन्यासो विविदिषूणामनुष्ठेयोयदहरेव विरजेत्तदहरेव प्रव्रजेत्?एतमेव प्रव्राजिनो लोकमिच्छन्तः प्रव्रजन्ति इति श्रुतिप्रसिद्धः। भाष्ये तु ननु कर्मपरित्यागस्त्रिविधः संन्यास इति च प्रकृतस्तत्र तामसो राजसश्चोक्तस्त्यागः कथमिह सङ्गफलत्यागस्तृतीयत्वेनोच्यते। यथा त्रयो ब्राह्मणा आगतास्तत्र षडङ्गविदौ द्वौ क्षत्रियस्तृतीय इति तद्वत्। नैष दोषः। त्यागसामान्येन स्तुत्यर्थत्वात्। अस्ति कर्मसंन्यासस्य फलाभिसन्धित्यागस्य च त्यागत्वं सामान्यम्। तत्र राजसतामसत्वेन कर्मत्यागनिन्दया कर्मफलाभिसन्धित्यागः सात्त्विकत्वेन स्तूयते स त्यागः सात्त्विको मत इति ग्रन्थेन त्यागत्रैविध्यं समाधायैवं सङ्गफलत्यागपूर्वकं नित्यकर्मानुष्ठानेन विशुद्धान्तःकरणस्यात्मज्ञानाभिमुखस्य तन्निष्ठाक्रमकथनार्थोऽयं श्लोक इत्युक्तम्। तथैव श्लोकं व्याख्याय पूर्वोक्तस्य कर्मयोगस्य प्रयोजनमनेन श्लोकेनोक्तमित्युपसंहृतम्। अन्ये तु फलाभिसंधिविशिष्टस्य कर्मणस्त्यागस्त्रिविधः। विशेषणाभावाद्विशेष्याभावादुभयाभावाच्च। आद्योऽत्रैव विधित्सितः? द्वितीयस्तु तामसराजसभेदेन द्विविधोऽप्यत्रैव निन्दितः। तृतीयस्तु कर्मानधिकारिणा विविदिषुणा विदुषा च कर्तुं योग्यो द्विविधः। तत्रान्त्यः स्थितप्रज्ञलक्षणादौ प्राग्व्याख्यातः। आद्यस्तु नैष्कर्म्यसिद्धिं परमामित्यत्र वक्ष्यते। तत्र भाष्ये तिस्रस्त्यागविधाः प्रतिज्ञाय द्वे यथावत्प्रदर्श्य तृतीयापि केनचित्सामान्येन प्रतिपादिता। अत्रतु एकस्यां द्वयोरन्तर्भावं कृत्वा द्वे एव विधे उपपाद्य तृतीया प्रदेशान्तरे प्रक्षिप्तेति प्रकृते प्रतिज्ञाया अनिर्वाह इति विशेषः।'),
('nilakantha-sc:source:18.11','Nīlakaṇṭha','gita.18.11','sa','commentary','।।18.11।।अमुख्यमेव सात्त्विकं त्यागमनूद्य तत्प्रयोजनमाह द्वाभ्याम् -- नहीति। देहभृता देहाभिमानिना हि यस्मादशेषतः कर्माणि त्यक्तुं न शक्यं अशक्यम्। प्राणयात्रालोपप्रसङ्गात्। तस्मादधिकृतः सन् यः कर्मफलत्यागशीलः। तुशब्द एवार्थे। स एव त्यागीत्युच्यते। यस्त्वशेषतः कर्माणि त्यक्तुं शक्नोति परमार्थदर्शी स मुख्यस्त्यागीत्यर्थः।'),
('nilakantha-sc:source:18.12','Nīlakaṇṭha','gita.18.12','sa','commentary','।।18.12।।एवंभूतस्य त्यागस्य फलमाह -- अनिष्टमिति। अनिष्टं नरकतिर्यगादिरूपम्? इष्टं देवतादिरूपम्? मिश्रं मानुषभाव इति कर्मणः कर्मजातीयस्य फलं त्रिविधं प्रेत्य मरणानन्तरमत्यागिनां पूर्वोक्तमुख्यसंन्यासहीनानां भवति मुख्यसंन्यासिनां तु क्वचित्तद्भवति। तेषां कर्तृत्वाभिमानाभावात्। अन्ये तु गौणसंन्यासिनामेवायं कर्मालेप इत्याहुः। तथा च व्याख्यातंकार्यमित्येव यत्कर्म इत्यत्र। अन्यथा संन्यासिनां गौणसंन्यासिनां च विशेषो न स्यात्। न चैवं मुख्यसंन्यासिनां गौणसंन्यासिनां चाविशेषापत्तिरिति वाच्यम्। उभयेषामुत्तरकर्माश्लेषसाम्येऽपि पूर्वकर्मदाहादाहकृतस्य विशेषस्य सत्त्वात्। गौणसंन्यासिनां जन्मान्तरादिकमपि पूर्वकर्मभिरेव भविष्यति आपस्तम्बोक्ताम्रनिदर्शनेन योगभ्रष्टगतिवन्नान्तरीयकं वा न तु तस्य प्रधानं फलं स्वर्गादिभवितुमर्हत्यनुद्दिष्टत्वादिति।'),
('nilakantha-sc:source:18.13','Nīlakaṇṭha','gita.18.13','sa','commentary','।।18.13।।नन्वात्मनः कर्मालेपनिमित्तं यदकर्तृत्वानुसंधानं तत्किं योषिदग्निदृष्ट्यादिवदाहार्यमुत वास्तवमेव सदविद्याध्यस्तकर्तृत्वेनावृतमिति शास्त्रदृष्ट्या कर्तृत्वतिरोधानेनाकर्तृत्वमेव भाव्यत इत्याशङ्क्याग्नित्वेन दृष्टायां योषिति दग्धृत्वादर्शनेनेव कल्पितेनाकर्तृत्वेन वास्तवस्य कर्मालेपस्यासंभवादाद्यं निरस्य द्वितीयमुपपादयिष्यन् पीठिकामारचयति -- पञ्चेति। हे महाबाहो? सर्वकर्मणां सिद्धये इमानि वक्ष्यमाणानि पञ्च कारणानि निर्वर्तकानि मे मद्वचनान्निबोध बुध्यस्व। स्ववचने विश्वासोत्पादनार्थं कारणानां समूलत्वमाह सांख्ये कृतान्ते प्रोक्तानीति।,सम्यग्विविच्य ख्यायन्ते प्रकटीक्रियन्ते तत्त्वान्यात्मानात्मपदार्थरूपाणि यस्मिंस्तत्सांख्यं वेदान्तशास्त्रम्। तदेव विशिनष्टि। कृतान्ते कृतस्य कर्मणोऽन्तः परिसमाप्तिर्यस्मिन्।सर्वं कर्माखिलं पार्थ ज्ञाने परिसमाप्यते इत्यात्मज्ञाने सति सर्वकर्मणां समाप्तिदर्शनात् तस्मिन्सांख्ये कृतान्ते प्रोक्तानि।'),
('nilakantha-sc:source:18.14','Nīlakaṇṭha','gita.18.14','sa','commentary','।।18.14।।तान्येव पञ्च गणयति -- अधिष्ठानमिति। अधिष्ठानमिच्छाद्वेषसुखदुःखज्ञानादीनामभिव्यक्तेराश्रयो देहः तस्यानात्मत्वं चार्वाकव्यतिरिक्तसमस्तवादिसिद्धम्। तथा कर्ता बुद्धिविशिष्टश्चिदाभासः प्रमाता नामाहंप्रत्ययविषयोऽहंकारस्तथेत्यनेन तद्वदेवानात्मत्वेन ज्ञेय इत्युक्तम्। देहस्यैव सृष्टौ प्रलये च तस्याप्युत्पत्तिविनाशयोर्दर्शनात्। एतच्च विशेषणनाशाद्विशिष्टनाशं विशेषणोत्पत्त्या च विशिष्टोत्पत्तिमभिप्रेत्य श्रूयतेविज्ञानघन एवैतेभ्यो भूतेभ्यः समुत्थाय तान्येवानु विनश्यति इति।यथाग्नेः क्षुद्रा विस्फुलिङ्गा व्युच्चरन्त्येवमेतस्मादात्मनः सर्व एत आत्मानो व्युच्चरन्ति इति च। विशिष्टस्य चानतिरेकादर्शनादनात्मत्वं सिद्धम्। करणं च शब्दाद्युपलब्धिसाधनं पृथग्विधं द्वादशविधं पञ्च कर्मेन्द्रियाणि पञ्च ज्ञानेन्द्रियाणि मनो बुद्धिश्च। तथा विविधाश्च पृथक् चेष्टा वायवीयाः प्राणनादिरूपाः। दैवं पुण्यपापरूपं तत्तत्करणानुग्राहकसूर्यादिदेवतारूपम् पञ्चमं पञ्चानां पूरणम्।'),
('nilakantha-sc:source:18.15','Nīlakaṇṭha','gita.18.15','sa','commentary','।।18.15।।शरीरेति। न्याय्यं धर्म्यं शास्त्रीयम्। विपरीतमन्याय्यमधर्म्यमशास्त्रीयम्। ननु शरीरादिभिस्त्रिभिरारभ्यते पञ्चैते तस्य हेतव इति च विप्रतिषिद्धमुच्यते। नैष दोषः। अत्रापि शरीरपदेनाधिष्ठानस्य नरपदेन कर्तुर्वाङ्मन इति करणस्यारभत इति चेष्टानां न्याय्यमिति धर्माधर्मरूपस्य दैवस्य च संग्रहात्। सर्वेषु कर्मसु पञ्चानां समानेऽप्युपयोगे विधिप्रतिषेधलक्षणं त्रिविधमेव कर्म शास्त्रे प्रसिद्धमिति। इदं शारीरं कर्मेदं मानसमिदं वाचिकमिति व्यपदेशो देहादीनां प्राधान्यापेक्ष इति न कश्चिद्विरोधः।'),
('nilakantha-sc:source:18.16','Nīlakaṇṭha','gita.18.16','sa','commentary','।।18.16।।एतत्प्रतिपादनफलं कर्तृत्वस्यारोपितत्वसिद्धिरकर्तृत्वस्य स्वाभाविकत्वसिद्धिश्चेति द्वाभ्यां श्लोकाभ्यां दर्शयति -- तत्रेति। तत्र तस्मिन्कर्मणि। एवमुक्तरीत्या पञ्चभिर्निर्वर्त्ये सति। केवलं त्वकर्तारमप्यात्मानं चेतनम्साक्षी चेता केवलो निर्गुणश्च इति श्रुतेः अधिष्ठानादिपञ्चकप्रचारदर्शिनमुदासीनमपि यः कर्तारं कर्तृत्वाश्रयं पश्यति स दुर्मतिः पापाभिभूतमतिर्न पश्यति। अन्ध एव सः। अदर्शने हेतुः अकृतबुद्धित्वादिति। शास्त्राचार्योपदेशशमदमादिसंस्कृता बुद्धिर्यस्य स कृतबुद्धिस्तद्विपरीतोऽकृतबुद्धिस्तस्य भावस्तत्त्वं तस्मात्। यथा स्वमुखस्योदपात्रसंसर्गिकत्वं पश्यता जलचाञ्चल्यमपि तत्रारोप्यत एवमात्मनो बुद्धिसंसृष्टत्वं पश्यता बुद्धिधर्मः कर्तृत्वादिरप्यात्मन्यारोप्यत इति भावः।'),
('nilakantha-sc:source:18.17','Nīlakaṇṭha','gita.18.17','sa','commentary','।।18.17।।द्वितीयं प्रयोजनमाह -- यस्येति। यस्य प्रमातुर्भावः प्रत्ययमात्रस्वरूप आत्मा नाहंकृतः अहमिव कृतः अहंकारतादात्म्यं प्रापितोऽहंकृतस्तथा न। यस्य बुद्धिर्न लिप्यते आत्मभावेन रञ्जिता न भवति। यस्य बुद्धेर्व्यतिरिक्तमात्मानं पश्यतो बुद्धिधर्माः कर्तृत्वादयो नात्मनि प्रतीयन्त इति कर्त्रात्मवादितार्किकनिरासः। यस्य च आत्मधर्माश्चैतन्यादयो बुद्धौ न संसृज्यन्त इति बुद्धिमेव चेतनां वदतो बौद्धस्य निरासः। चिदचितोरन्योन्यस्मिन्नन्योन्यधर्माध्यासो बाध्यत इति दुःखादिसंसर्गनिषेधेन भोक्तृत्वाभावो दर्शितः।हत्वापि स इमाँल्लोकान्न हन्ति न निबध्यते इति तु स्तुतिमात्रम्। कर्तृत्वस्यैव बाधेन हन्तृत्वायोगात्? दग्धपटवत्कर्तृत्वानुवृत्तावपि हननक्रियायां प्रवर्तकस्य रागद्वेषादेरभावाच्च। एतेनात्मनस्तात्त्विकमकर्तृत्वं भावयता कृतं कर्मातात्त्विककर्तृत्वाभिमाननिमित्तं स्वफलं प्रस्तोतुं नार्हतीति दर्शितम्। नहि रज्जुसर्पे रज्जुबुद्धिं कृत्वा प्रहरतः सर्पक्षोभजं दंशनादिफलं भवति। सर्पे तु तथा कुर्वतस्तद्भवत्येव तद्वदिदमपि ज्ञेयम्।'),
('nilakantha-sc:source:18.18','Nīlakaṇṭha','gita.18.18','sa','commentary','।।18.18।।समाप्तः सात्त्विकत्यागोपपादनोपयोगी आत्मनोऽकर्तृत्वोपपादनप्रकारः। अत्राह सांख्यः -- यदुक्तं पञ्चैते? तस्य हेतव इति? यच्चोक्तं न हन्तीति तन्मृष्यामहे। नह्यपरिणामी चेतनः परिस्पन्दात्मकस्य कायिकादिभेदेन त्रिविधस्य कर्मणः कर्ता भवतीति वक्तुं युज्यते। यत्तु न निबध्यत इति भोक्तृत्वमुक्तमपि प्रत्याख्यातं तन्न मृष्यामहे। नहि कुलालादयः स्वप्रयुक्ता एव घटादीन्निर्वर्तयन्ति किंतु भोक्तृपुरुषप्रयुक्ताः। अन्यथा भोक्तृ़णामभावे व्यर्थैव तत्प्रवृत्तिरित्यापतति। एवं प्रधानमात्राभूताः कर्त्रादयः पुरुषस्य भोगापवर्गसाधनप्रयुक्ताः,सर्वाणि कर्माणि निर्वर्तयन्ति। तस्मात्पुरुषस्य भोक्तृस्वभावत्वादकर्तृत्वानुसंधानपूर्वकमपि कृतं कर्म भोक्त्राऽवश्यमेव भोक्तव्यमिति सात्त्विकत्यागेऽपि कर्मालेपवचनमसंगतमिति। अत्र प्रतिविधत्ते -- ज्ञानं ज्ञेयमिति। ज्ञानं ज्ञायते प्रकाश्यते वस्तुतत्त्वमनेनेति प्रत्यक्षादिप्रमाणजन्यो घटादिप्रकाशः स च वर्तमानोऽतीतो वा। ज्ञेयं बोधविषयो घटादिः। परिज्ञाता विषयी साभासधीरूपो यो भोक्तेत्युच्यते। एवंरूपप्रकारत्रयवती त्रिविधा कर्मणां चोदना। त्रयं समुच्चितं सत्कर्मणि प्रवर्तकमित्यर्थः। सत्यपि ज्ञेये ज्ञातरि वा ज्ञाने प्रवृत्त्यनुपपत्तेः। ज्ञाने ज्ञातरि च सति देशकालव्यवहिते ज्ञेये प्रवृत्त्यनुपपत्तेः। सत्यपि संस्कारात्मके ज्ञाने ज्ञेये च सन्निहिते तथापि सुषुप्तौ प्रमात्रभावात्प्रवृत्त्यदर्शनादेतत्त्रयं त्रिदण्डविष्टम्भवदन्योन्यापेक्षं सत् हानोपादानोपेक्षाबुद्धिरूपं कार्यं जनयित्वा हानाद्यनुकूले व्यापारे प्रवर्तयतीति कर्तृपदाभिधेयमित्यर्थः। चोदनेति कर्तरि नन्द्यादिल्युप्रत्ययान्तत्वे चोदनाशब्दः कर्तृवाची। लिङ्गं त्वविवक्षितम्। लिङ्गमशिष्यं लोकाश्रयत्वाल्लिङ्गस्येति वा। तथा करणमिन्द्रियम्। कर्म तेन यत्क्रियमाणं विषयग्रहणम्। कर्ता पूर्वोक्त एव परिज्ञाता। एतत्त्रयं समुदितं सत् कर्मसंग्रहः कर्मणः ईप्सिततमस्य भोग्यस्य संग्रहः संगृह्यतेऽस्मिन्निति संश्लेषस्थानं भोक्तेत्यर्थः। सत्यपि भोक्तरि करणे च क्रियां विना भोगासंभवात् क्रियायाश्चाश्रयं विना स्वरूपालाभादाश्रयस्य करणं विना भोक्तृत्वाङ्गकर्तृत्वानुपपत्तैश्चैतत्त्रयं मिलितं सत् भोक्तेत्युच्यत इत्यर्थः। तथा च श्रुतिःआत्मेन्द्रियमनोयुक्तं भोक्तेत्याहुर्मनीषिणः इति। इन्द्रियं प्रसिद्धम्। मन इत्यनेन बुद्धिरेव गृह्यते। युक्तं इन्द्रियद्वारा मतेर्भोग्येन सह संबन्धक्रिया। इन्द्रियं च मनश्च युक्तं चेति विग्रहे इन्द्रियमनोयुक्तमिति द्वन्द्वैकवद्भावः। एतत्त्रयं भोक्ता आत्मेत्याहुर्मनीषिण इति श्रुत्यर्थः। एवं हि श्रुतिस्मृत्योर्व्याख्याने तयोर्मूलमूलिभावो युज्यते नान्यथा। तथा च कर्तृवत् भोक्तुरपि अनात्मगणपतितत्वाद्भोक्तृत्वं भोगकर्तृत्वमिति निर्वचनाद्यः कर्ता स एव भोक्तेति प्रतिपादनादहमकर्ताऽभोक्तेति चानुसंधानपूर्वकं कर्माणि कुर्वतः कर्तृत्वभोक्तृत्वकृतः कर्मलेपो नास्तीति सिद्धम्। भाष्यस्य चायमेवार्थः। ये तु करणं क्रियायाः साधकतमं दशविधं बाह्यं मनोबुद्धिरूपमान्तरम्। कर्म कर्तुरीप्सिततमं क्रियया व्याप्यमानं उत्पाद्यमाप्यं विकार्यं संस्कार्यं चेति चतुर्विधम्। कर्ता कारकान्तरप्रयोजकश्चिदचिद्ग्रन्थिः। एतत्त्रयं कर्मसंग्रहः। कर्माश्रयः कर्तेत्यर्थः। तथा ज्ञानं विषयप्रकाशनशक्तिः। ज्ञेयं विषयः। परिज्ञाता ज्ञानाश्रयो भोक्ता। एतत्त्रयं कर्मणि प्रवर्तकमिति व्याचक्षते। तेषामपि आत्मा न कर्ता नापि सांख्यानामिव भोक्तृत्वेन प्रकृतेः प्रवर्तक इत्येवाशयः। तथापि क्रियया व्याप्यमानस्य वक्ष्यमाणसात्त्विकादिभेदानर्हस्य घटादिरूपस्य कर्मणः कर्तृकोटौ प्रवेशायोगः। तस्य क्रियाश्रयत्वमात्रविवक्षायां प्रकृते तत्कथनानुपयोगश्च स्पष्टः। तथा अस्माकं तु घटादिव्यापकक्रियायाः कर्मशब्दवाच्यत्वं मुख्यम्। कर्तृकोटिप्रवेशश्च क्रियाक्रियावतोर्धर्मधर्मिणोरभेदापेक्षया युज्यते। तथा ज्ञानं प्रकाशनक्रियेति मते क्रियारूपेऽस्मिन्प्रवर्तकज्ञानान्तरस्यापेक्षेति तत्र तत्रान्यस्यान्यस्यापेक्षेत्यनवस्था दुर्निवारा।'),
('nilakantha-sc:source:18.19','Nīlakaṇṭha','gita.18.19','sa','commentary','।।18.19।।पूर्वश्लोकोक्ते ज्ञानादिषट्के परिज्ञाता कर्ता चैक एवेति परिशिष्टाः पञ्च तेषां सर्वेषां प्राकृतत्वेन त्रिगुणात्मकत्वे प्राप्ते ज्ञेयकरणयोर्जडयोर्घटकुठारकल्पयोः परिसंख्यार्थं त्रयाणामेव प्रत्येकं त्रिविधत्वं विवरीतुं प्रतिजानीते -- ज्ञानमिति। ज्ञानं कर्म कर्ता चेति त्रयमेव गुणभेदतस्त्रिधा न तु ज्ञेयकरणे। गुणसंख्याने कापिले शास्त्रे। यद्यपि तत्र एकस्यां प्रमदायां भर्तुः सुखं जायते तं प्रति तस्याः सत्त्वोद्भूतत्वात्? तामविन्दतश्चैत्रस्य दुःखं जायते तं प्रति तस्याः रजोद्भूतत्वात्। तस्यामेव सपत्न्या द्वेषस्तां प्रति तस्यास्तमोद्भूतत्वात्। प्रमदयैव सर्वे भावा व्याख्याता इति कापिलानां ज्ञेयकरणयोरपि त्रैविध्यं प्रसिद्धम्। तथापि प्रमदादय एकस्यैव पुंसो निमित्तभेदेन प्रीतिदुःखद्वेषविषया अपि भवन्तीति पूर्वोक्तव्यवस्थाया निर्मूलत्वात्। प्रीत्यादीनां कर्तृसमवायितया प्रतीयमानानामालम्बनभूतायाः प्रमदायाः प्रीत्याद्यात्मकत्वं कल्पयितुं न शक्यत इति न भगवता तयोस्त्रिविधत्वं व्याख्यायते। अक्षरार्थः स्पष्टः।'),
('nilakantha-sc:source:18.20','Nīlakaṇṭha','gita.18.20','sa','commentary','।।18.20।।एवं ज्ञानादित्रयस्य त्रैविध्यं वक्तुं प्रतिज्ञाय ज्ञानत्रैविध्यं तावदाह -- सर्वभूतेष्विति। यथा कटककुण्डलादिषु व्यावर्तमानेषु तत्त्वविवेकं काञ्चनमेवेदमिति पश्यति। एवं येन ज्ञानेन सर्वभूतेषु विभक्तेषु नानानामरूपभेदभिन्नेषु अव्ययमपरिणामिनमेकं भावं चिन्मात्ररूपं ईक्षते सर्वं ब्रह्मैवेदमिति पश्यति तज्ज्ञानं सात्त्विकं विद्धि। ऐकात्म्यज्ञानमेव सात्त्विकमित्यर्थः।'),
('nilakantha-sc:source:18.21','Nīlakaṇṭha','gita.18.21','sa','commentary','।।18.21।।भेदज्ञाने राजसत्वमाह -- पृथक्त्वेनेति। यत्पृथक्त्वेन भिन्नत्वेन। ज्ञानं तद्राजसमिति संबन्धः।,पृथक्त्वेनेत्येतद्विवृणोति। सर्वेषु भूतेषु पाञ्चभौतिकत्वेनाविशिष्टेषु नानाभावान् सुरनरतिर्यक्स्थावरत्वभेदेन नानात्वानि। बहुवचनमत्यन्तभेदप्रदर्शनार्थम्। पृथग्विधान् एकजातीयेष्वपि नरादिषु प्रत्येकं विभिन्नप्रकारान् यज्ज्ञानं वेत्ति विषयीकरोतीति। येन ज्ञानेन वेत्तीति वक्तव्ये एधांसि पचन्तीतिवद्यज्ज्ञानं वेत्तिति करणे कर्तृत्वोपचारो बोध्यः। तेनात्मनां परस्परभेदस्तेषामीश्वराद्भेदस्तेभ्य ईश्वरादन्योन्यतश्च जडवर्गस्य भेद इत्यनौपाधिकभेदपञ्चकज्ञानं कुतार्किकाणां राजसमेवेत्यभिप्रायः।'),
('nilakantha-sc:source:18.22','Nīlakaṇṭha','gita.18.22','sa','commentary','।।18.22। यत्तु ज्ञानमेकस्मिन्कार्ये देहे प्रतिमादौ वा कृत्स्नवत्परीपूर्णवदेतावानेवात्मा ईश्वरो वेति सक्तमभिनिवेशयुक्तम्। अहैतुकं निरुपपत्तिकम्। अतत्त्वार्थवत् परमार्थावलम्बनशून्यम्। अल्पं तुच्छविषयत्वादल्पफलत्वाच्च। यदेवंभूतं ज्ञानं तत्तामसमुदाहृतम्।'),
('nilakantha-sc:source:18.23','Nīlakaṇṭha','gita.18.23','sa','commentary','।।18.23।।अथ कर्मत्रैविध्यमाह -- नियतमित्यादिना। नियतं नित्यम् सङ्गरहितमभिमानवर्जितम्। राग इष्टे प्रीतिर्द्वेषोऽनिष्टेऽप्रीतिस्ताभ्यां कृतमिष्टानिष्टप्राप्तिपरिहारार्थं कृतं रागाद्वेषतः कृतं तदन्यदरागद्वेषतः कृतं निष्काममित्यर्थः। फल्गु च लीयते चेति फलं क्रियया प्राप्यमनात्मवस्तु तदन्यदफलमनागन्तुकं परिपूर्णमविनाशि आत्मतत्त्वं तत्प्रेप्सुना कृतंविविदिषन्ति यज्ञेन इति श्रुत्या आत्मलाभार्थं यज्ञादेर्विनियोगात्। तत्कर्म सात्त्विकमुच्यते।'),
('nilakantha-sc:source:18.24','Nīlakaṇṭha','gita.18.24','sa','commentary','।।18.24।।यत्तु कामेप्सुना फलार्थिना साहंकारेण। यद्यपि सात्त्विकोऽप्यनात्मवित्साहंकारस्तथाप्यहमेव कर्मकुशलो महान् श्रोत्रिय इत्यभिमानोऽहंकारस्तद्वता साहंकारेण। वा शब्दश्चार्थे। क्रियते बहुलायासमतिश्रमकरं तत्कर्म राजसमुदाहृतम्।'),
('nilakantha-sc:source:18.25','Nīlakaṇṭha','gita.18.25','sa','commentary','।।18.25।।अनुबध्यतेऽनेनेत्यनुबन्धः फलम्। क्षयं शक्तेरर्थानां च नाशम्। हिंसां परपीडाम्। पौरुषं स्वसामर्थ्यम्। अनवेक्ष्यानालोच्य केवलमोहादविवेकतो यदारभ्यते कर्म तत्तामसमुदाहृतम्।'),
('nilakantha-sc:source:18.26','Nīlakaṇṭha','gita.18.26','sa','commentary','।।18.26।।कर्तृत्रैविध्यमाह -- मुक्तेत्यादिना। मुक्तसङ्गस्त्यक्ताभिनिवेशः। अनहंवादी पूर्वोक्ताहंकारोक्तिरहितः। धृतिर्धैर्यम्। उत्साहः साधयिष्याम्येवेति बुद्धिनिश्चयः ताभ्यां समन्वितः। सिद्ध्यसिद्ध्योः कर्मण आरब्धस्येति शेषः। निर्विकारो हर्षविषादशून्यः कर्ता सात्त्विक उच्यते।'),
('nilakantha-sc:source:18.27','Nīlakaṇṭha','gita.18.27','sa','commentary','।।18.27।।रागी विषयलोलुपः। अतएव कर्मणः फलं प्रेप्सतीति कर्मफलप्रेप्सुः। लुब्धः परद्रव्यादौ संजाततृष्णस्तीर्थादौ वा द्रव्यापरित्यागी। हिंसात्मकः परपीडाकरस्वभावः। अशुचिर्बाह्यान्तःशौचवर्जित इष्टानिष्टप्राप्तौ हर्षशोकान्वितश्च यः कर्ता स राजसः परिकीर्तितः।'),
('nilakantha-sc:source:18.28','Nīlakaṇṭha','gita.18.28','sa','commentary','।।18.28।।अयुक्तोऽनवहितः। प्राकृतोऽत्यन्तमसंस्कृतबुद्धिर्बालसमः। स्तब्धो दण्डवन्न नमति कस्मैचित्। शठः शक्तिगूहनकारी। नैष्कृतिको वञ्चकः परावमानी वा। अलसः अप्रवृत्तिशीलः कर्तव्येष्वपि। विषादी सर्वदा अवसन्नस्वभावः। दीर्घसूत्री चिरकारी। एकाहसाध्यं कार्यं मासेनापि न करोतीत्यर्थः। य एवंभूतः स कर्ता तामस उच्यते।'),
('nilakantha-sc:source:18.29','Nīlakaṇṭha','gita.18.29','sa','commentary','।।18.29।।बुद्धिधृती त्रैविध्येन व्याख्यातुमाह -- बुद्धेरिति। तत्र बुद्धिविशिष्टश्चिदाभासः कर्ता ज्ञानं च प्रागुक्तम्। अत्रतु केवला बुद्धिर्वृत्तिमती तदीयवृत्त्यन्तरोपलक्षणार्थं तद्वृत्तिविशेषो धृतिश्चत्रैविध्येन कथ्यत इत्यर्थः।'),
('nilakantha-sc:source:18.30','Nīlakaṇṭha','gita.18.30','sa','commentary','।।18.30।।प्रवृत्तिनिवृत्ती शास्त्रविहितप्रतिषिद्धविषयेयजेत स्वर्गकामः?न सुरां पिबेत् इत्यादिरूपे। कार्यं कृतिसाध्यं स्वर्गादि। अकार्यं नित्यसिद्धं तेन नित्यानित्यवस्तुनी उक्ते। भयाभये कार्याकार्यनिमित्ते। बन्धं मोक्षं च या वेत्ति यया वेत्तीति पूर्ववत्करणे कर्तृत्वोपचारः। बुद्धिः सा पार्थ सात्त्विकी।'),
('nilakantha-sc:source:18.31','Nīlakaṇṭha','gita.18.31','sa','commentary','।।18.31।।अयथावत् संदेहास्पदत्वेन। स्पष्टमन्यत्।'),
('nilakantha-sc:source:18.32','Nīlakaṇṭha','gita.18.32','sa','commentary','।।18.32।।अधर्ममिति। विपरीतग्राहिणी बुद्धिस्तामसीत्यर्थः।'),
('nilakantha-sc:source:18.33','Nīlakaṇṭha','gita.18.33','sa','commentary','।।18.33।।यया धृत्या अव्यभिचारिण्या समाध्यनुगतया मनःप्राणेन्द्रियाणां क्रियाश्चेष्टाः संकल्पं श्वासप्रश्वासौ शब्दादिग्रहणं च योगेन चित्तवृत्तिनिरोधेन ऐकाग्र्येण वा संयत्तास्तास्तथैव निरोधावस्थायामैकाग्र्यावस्थायां वा धारयते चिरमवस्थापयति सा धृतिः पार्थ? सात्त्विकी।'),
('nilakantha-sc:source:18.34','Nīlakaṇṭha','gita.18.34','sa','commentary','।।18.34।।यया धृत्या धर्मादीन् धारयतेऽनुरोध्यतया निश्चिनोति प्रसङ्गेन धर्मादेः संबन्धेन फलाकाङ्क्षी च भवति पुरुषो धृतिः सा पार्थ राजसी।'),
('nilakantha-sc:source:18.35','Nīlakaṇṭha','gita.18.35','sa','commentary','।।18.35।।स्वप्नं निद्राम्। भयं त्रासम्। शोकं प्रसिद्धम्। विषादं विषण्णताम्। मदमशास्त्रीयविषयसेवया चित्तस्य विवशत्वम्। एतान्न विमुञ्चति धारयत्येव यया धत्या सा धृतिः पार्थ? तामसी।'),
('nilakantha-sc:source:18.36','Nīlakaṇṭha','gita.18.36','sa','commentary','।।18.36।।गुणभेदेन क्रियाणां कारकाणां च त्रैविध्यमुक्तं तत्फलस्य सुखस्य त्रैविध्यमाह -- सुखं त्वित्यादिना। अभ्यासात्पौनःपुन्येन सेवनात्। यत्र सात्त्विके राजसे तामसे वा सुखे रमते रतिं प्राप्नोति। यया रत्या दुःखस्य पुत्रशोकादेरप्यन्तमवसानं निगच्छति निश्चयेन प्राप्नोति तत्सुखं त्रिविधं श्रृणु। यदा त्वयमप्यर्थः सात्त्विकसुखस्यैव लक्षणार्थस्तदा यत्र समाधिसुखे अभ्यासाद्रमते न तु विषयसुख इव रागात् दुःखान्तं मोक्षं च निगच्छतीत्यर्थः।'),
('nilakantha-sc:source:18.37','Nīlakaṇṭha','gita.18.37','sa','commentary','।।18.37।।यत्तत्प्रसिद्धं सर्वप्राणिप्रेमास्पदम्। अग्रे समारम्भकाले मनःप्राणेन्द्रियस्पन्दनिरोधेन यज्ञे संज्ञप्यमानस्य पशोरिव जायमानं विषमिवातितीव्रवेदनाकरम्। परिणामे सात्त्विक्या धृत्या निरुद्धासु मन आदिक्रियासु अमृतोपममत्याह्लादकरम्। आत्मनः स्वस्यैव बुद्धेः प्रसादो नैर्मल्यं रजस्तमोमलराहित्यं तस्मादाविर्भूतं न तु विषयसङ्गजं निद्रालस्यादिजं वा तत्सुखं सात्त्विकं प्रोक्तम्।'),
('nilakantha-sc:source:18.38','Nīlakaṇṭha','gita.18.38','sa','commentary','।।18.38।।राजसं सुखमाह -- विषयेति। अग्रे भोगकाले। परिणामे विषमिव वियोगकाले। इहामुत्र च दुःखप्रदत्वात्।'),
('nilakantha-sc:source:18.39','Nīlakaṇṭha','gita.18.39','sa','commentary','।।18.39।।अग्रे आरम्भे अनुबन्धे परिणामे। मोहनं मोहकरम्। आत्मनो बुद्धेः। यतो निद्रादिजम्।'),
('nilakantha-sc:source:18.40','Nīlakaṇṭha','gita.18.40','sa','commentary','।।18.40।।प्रकरणार्थमुपसंहरत्यनुक्तमपि संगृह्णन् -- न तदस्तीति। सत्त्वं प्राणिजातम्। इदमुपलक्षणं जडस्यापि। सर्वस्य त्रिगुणविकारत्वात्। प्रकृतिजैर्जन्मान्तरीयधर्माधर्मसंस्कारजैः मायाप्रभवैर्वा। शेषं स्पष्टम्।');
INSERT INTO commentary_fts (unit_id,author,canonical_ref,language,content_type,content) VALUES
('nilakantha-sc:source:18.41','Nīlakaṇṭha','gita.18.41','sa','commentary','।।18.41।।एवं पञ्चदशे संसाराश्वत्थमसङ्गशस्त्रेण च्छित्त्वा परं पदं परिमार्गितव्यमित्युक्तं तत्रात्मनोऽसङ्गत्वोपपादनाय क्रियाकारकफललक्षणस्य कृत्स्नस्य संसारस्य त्रिगुणात्मकत्वमुक्तम्। नह्यात्मानात्मनोर्गुणातीतगुणात्मकयोः सङ्गः संभवति। नह्याकाशान्तर्वर्तिपृथिव्यादिगुणेन गन्धादिनाकाशः संसृज्यते तद्वदित्युक्तम्। समाप्तः शास्त्रार्थः। अथेदानीं सर्वगीताशास्त्रार्थमुपसंहर्तुमसङ्गशस्त्राप्त्युपायं च प्रदर्शयितुं प्रकरणान्तरमारभते -- ब्राह्मणेत्यादिना। शूद्राणामसमासकरणं वेदानधिकारात्। प्रविभक्तानि असंकीर्णानि। तत्र हेतुमाह स्वभावप्रभवैर्गुणैः। स्वभाव ईश्वरस्य प्रकृतिस्त्रिगुणात्मिका सैव प्रभवो हेतुर्येषां गुणानां ते स्वभावप्रभवास्तैः। यद्वा ब्राह्मणस्वभावस्य सत्त्वगुण एव प्रभवः शान्तत्वात्। क्षत्रियस्वभावस्य सत्त्वोपसर्जनं रजः ईश्वरस्वभावत्वात्। वैश्यस्वभावस्य तम उपसर्जनं रजः कृष्यादिस्वभावत्वात्। शूद्रस्वभावस्य रज उपसर्जनं तमः शुश्रूषास्वभावत्वात्। अथवा स्वभावः प्राग्भवीयः संस्कारस्तत्प्रभवैर्न तु जातिमात्रप्रभवैः पक्षिणामाकाशगमनवत्। अतएव जात्यन्तरव्यावृत्तानां धर्माणां शमादिषु पाठो न दृश्यते। नहि शूद्राद्व्यावृत्तं,त्रैवर्णिकानामध्ययनादिकं वा इतरद्वयाद्व्यावृत्तं ब्राह्मणानामध्यापनादिकं वा इह पठ्यते। किंतु सर्वे सर्वजातीयानां साधारणा धर्माः शमादयो दृश्यन्ते। यथाहि द्रोणादिषु ब्राह्मणेष्वपि शौर्यादिकं भरतादिषु क्षत्रियेष्वपि शमादिकं दृष्टम् एवमितरत्र। तस्माद्यस्मिन्कस्मिंश्चिद्वर्णे शमादयो दृश्यन्ते स शूद्रोऽप्येतैर्लक्षणैर्ब्राह्मण एव ज्ञातव्यः। यत्र च ब्राह्मणेऽपि शूद्रधर्मा दृश्यन्ते स शूद्र एव। तथा चारण्यके सर्पभूतं नहुषं प्रति युधिष्ठिरवाक्यम्सत्यं दानं क्षमा शीलमानृशंस्यं तपो घृणा। दृश्यन्ते यत्र नागेन्द्र स ब्राह्मण इति स्मृतः। तथायत्रैतल्लक्ष्यते सर्प वृत्तं स ब्राह्मणः स्मृतः। यत्रैतन्न भवेत्सर्प तं शूद्रमिति निर्दिशेत् इति। जातिधर्मास्तु मनुना दर्शिताःअध्यापनं चाध्ययनं यजनं याजनं तथा। दानं प्रतिग्रहं चैव ब्राह्मणानामकल्पयत्। प्रजानां रक्षणं दानमिज्याध्ययनमेव च। विषयेष्वप्रसक्तिं च क्षत्रियस्य समासतः। पशूनां रक्षणं दानमिज्याध्ययनमेव च। वणिक्पथं कुसीदं च वैश्यस्य कृषिमेव च। एकमेव तु शूद्रस्य प्रभुः कर्म समादिशत्। एतेषामेव वर्णानां शुश्रूषामनसूयया। इति। तस्मात् शमादयो यत्राब्राह्मणे ब्राह्मणे वा दृश्यन्ते स एव ब्राह्मण इत्यत्र विवक्षितम्।स्वे स्वे कर्मण्यभिरतः संसिद्धिं लभते नरः इत्यत्र तु मनूक्तान्यध्यापनादीन्येव स्वकर्माणि ग्राह्याणि न तु शमदमादीनि। नहि ज्ञानविज्ञानवतोऽन्या संसिद्धिर्लब्धव्यास्ति। तस्माच्छमदमादयो ब्रह्मिष्ठस्यैव ब्राह्मणस्य लक्षणमिति दिक्।'),
('nilakantha-sc:source:18.42','Nīlakaṇṭha','gita.18.42','sa','commentary','।।18.42।।ब्राह्मणकर्माण्याह -- शम इति। अन्तःकरणनिग्रहः शमः। बाह्येन्द्रियनिग्रहो दमः। तपः पूर्वोक्तं शारीरादिभेदेन त्रिविधम्। शौचं बाह्यं मृज्जलाभ्यां आभ्यन्तरं भावशुद्धिः। क्षान्तिः क्षमा। आर्जवमकौटिल्यम्। ज्ञानं शास्त्रीयं कर्म ब्रह्मविषयम्। विज्ञानं तदनुष्ठानानुभवात्मकम्। आस्तिक्यं श्रद्धा एतन्नवकं ब्रह्मकर्म ब्राह्मणत्वजात्यभिव्यञ्जकं कर्म। स्वभावजं प्राचीनधर्मसंस्कारजम्।'),
('nilakantha-sc:source:18.43','Nīlakaṇṭha','gita.18.43','sa','commentary','।।18.43।।शौर्यं पराक्रमः। तेजः प्रागल्भ्यम्। धृतिर्धैर्यं। दाक्ष्यं युद्धे कौशलमुत्साहो वा। दानमौदार्यम्। ईश्वरभावः उन्मार्गवर्तिनां नियमनशक्तिः। एतत्क्षात्रं कर्म स्वभावजम्।'),
('nilakantha-sc:source:18.44','Nīlakaṇṭha','gita.18.44','sa','commentary','।।18.44।।वैश्यशूद्रयोः कर्माण्याह -- कृषीति। स्पष्टार्थः श्लोकः।'),
('nilakantha-sc:source:18.45','Nīlakaṇṭha','gita.18.45','sa','commentary','।।5.10।।ब्रह्मणीति। यतो विद्वानसङ्गत्वात्कुर्वन्नपि न लिप्यते तस्मादविद्वानपि ब्रह्मणि सर्वान्तर्यामिणि कर्माण्याधाय अयमेव कारयिता नत्वहं कर्तेति समर्प्य यः कर्माणि करोति सः पापेन न लिप्यतेऽम्भसा पद्मपत्रमिव।'),
('nilakantha-sc:source:18.46','Nīlakaṇṭha','gita.18.46','sa','commentary','।।18.46।।तमेव प्रकारमाह -- यत इति। प्रवृत्तिः कायवाङ्मनोनिर्वर्त्या चेष्टा। यतो हेतोरन्तर्यामिणः।येन वागभ्युद्यते इत्यादिश्रुतेः। येन इदं सर्वं दृश्यं ततं व्याप्तं उपादानत्वात्। स्वकर्मणा तमभ्यर्च्य संतर्प्य सिद्धिं मोक्षं विन्दति लभते मानवः। मनुष्याधिकारिकत्वाच्छास्त्रस्य। परमेश्वरे नित्यकर्मणामर्पणमेव मोक्षद्वारमित्यर्थः।'),
('nilakantha-sc:source:18.47','Nīlakaṇṭha','gita.18.47','sa','commentary','।।18.47।।स्वकर्मणेति विशेषणस्य फलमाह -- श्रेयानिति। स्वधर्मो विगुणः किंचिदङ्गहीनोऽपि श्रेयान् प्रशस्यतरः। किमपेक्ष्य श्रेयान्। परधर्मात्स्वनुष्ठितात् सम्यग्विहितादपि। उक्तं चस्वधर्मे निधनं श्रेयः परधर्मो भयावहः इति। स्वभावनियतं पूर्वोक्तत्रिविधस्वभावाज्जातं कर्म कुर्वन् किल्बिषं दोषं नाप्नोति। विषकृमेर्विषमिव न दोषकरम्। तस्मात्तव भैक्ष्यं हिंसाशून्यमपि न युक्तम्। किंतु हिंसायुक्तोऽपि स्वधर्म एव प्रशस्यतरः। धर्मत्वेन विहितेऽस्मिन्नग्नीषोमीयपश्वालम्भे इव कृते सति न किल्बिषप्रसङ्गोऽस्तीत्यर्थः।'),
('nilakantha-sc:source:18.48','Nīlakaṇṭha','gita.18.48','sa','commentary','।।18.48।।किं च सहजं स्वाभाविकं क्षात्रं कर्म सदोषं हिंसामिश्रमपि न त्यजेत्। हि यस्मात्सर्वारम्भाः सर्वाणि कर्माणि दोषेण हिंसादिना आवृता एव। यस्माच्च परधर्मो भयावहस्तस्मात्स्वकर्म न त्यजेदित्यर्थः।'),
('nilakantha-sc:source:18.49','Nīlakaṇṭha','gita.18.49','sa','commentary','।।18.49।।स्वकर्मणामीश्वरे समर्पणं कर्तव्यमित्युक्त्वानन्तरश्लोकद्वयेन स्वकर्मणामावश्यकत्वमुक्त्वा तेषां परमेश्वरेऽर्पणेन किं फलं स्यादित्यत आह -- असक्तेति। संन्यासेनकार्यमित्येव यत्कर्म नियतं क्रियतेऽर्जुन।,सङ्गं त्यक्त्वा फलं चैव स त्यागः सात्त्विको मतः इति पूर्वोक्तेनामुख्यसात्त्विकत्यागेन। असक्तबुद्धिः पुत्रदारादिषु सक्तिपदेषु आसक्तिवर्जिता बुद्धिर्यस्य सोऽसक्तबुद्धिः विरक्त इत्यर्थः। अतएव जितात्मा शान्तचित्तः। विगतस्पृहः विशेषेण गता स्पृहा तृष्णा यस्य तादृशो भूत्वा नैष्कर्म्यसिद्धिं कात्स्न्र्येन स्वरूपतः कर्मत्यागलक्षणां पारिव्राज्यसिद्धिं परमां पूर्वोक्तामुख्यत्यागापेक्षयातिश्रेष्ठां न द्वेष्ट्यकुशलं कर्मेति श्लोके व्याख्यातां अधिगच्छति प्राप्नोति।'),
('nilakantha-sc:source:18.50','Nīlakaṇṭha','gita.18.50','sa','commentary','।।18.50।।स्वकर्मनिरतः सिद्धिं यथा विन्दतीत्येतत्प्रतिज्ञातमुपपादितम्। इदानीं नैष्कर्म्यसिद्धिं प्राप्तोऽपि परिव्राट् वशीकारसंज्ञकवैराग्यवान् यथा ब्रह्म प्राप्नोति तथा वक्तुं प्रतिजानीते -- सिद्धिमिति। सिद्धिं नैष्कर्म्यसिद्धिं निबोध बुध्यस्व। मे मद्वचनात्समासेन संक्षेपेणैव हे कौन्तेय? या यत्प्राप्यं ब्रह्म। विधेयापेक्षं स्त्रीत्वम्। ज्ञानस्य परा निष्ठा यदपेक्षयाऽन्यज्ज्ञेयं आन्तरतरं नास्तीत्यर्थः।'),
('nilakantha-sc:source:18.51','Nīlakaṇṭha','gita.18.51','sa','commentary','।।18.51।।तमेव ब्रह्मप्राप्तिप्रकारमाह त्रिभिः -- बुद्ध्येति। बुद्ध्या वेदान्तश्रवणमननपरिपाकोत्थयाऽहं ब्रह्मास्मीति परोक्षनिश्चयरूपया विशुद्धया सर्वभूतेषु मैत्र्यादिभावनया सम्यग्विशोधितया। धृत्या धैर्येण योगक्षेमादिनिमित्तवैयग्र्यराहित्येन। आत्मानं देहेन्द्रियसंघातं नियम्य। दृढासनो भूत्वेत्यर्थः। चकारात्प्राणं च नियम्य। शब्दादीन् विषयांस्त्यक्त्वा। तत इन्द्रियाणि प्रत्याहृत्येत्यर्थः। प्रत्याहृतकरणोऽप्यन्तर्मनसैव विषयान्स्मरति तत्परित्यागमाह -- रागद्वेषौ व्युदस्य चेति। संकल्पं त्यक्त्वेत्यर्थः। स हि विषयं परिकल्प्य तत्र रागं जनयतीति प्रसिद्धम्। यथाचाक्षपादाचार्यसूत्रंदोषनिमित्तं रूपादयो विषयाः संकल्पकृताः इति। दोषो रागादिः। चकारादयमहमस्मीत्येतमपि भावं व्युदस्येति ज्ञेयम्। ततो ब्रह्मभूयाय ब्रह्मभावाय तं प्राप्तुं कल्पते योग्यो भवतीति तृतीयेन संबन्धः।'),
('nilakantha-sc:source:18.52','Nīlakaṇṭha','gita.18.52','sa','commentary','।।18.52।।केन साधनजातेनैवंभूतो भवतीत्यत आह -- विविक्तेति। यत्तच्छब्दाध्याहारेण योज्यम्। नित्यमिति सर्वत्र संबन्धनीयम्। यो नित्यं विविक्तसेवी एकान्तशीली। लघ्वाशी मिताशनशीलश्च। तथा नित्यं वैराग्यं रागाभावं समुपाश्रितश्च। तथा नित्यं ध्यानयोगः षष्ठाध्यायोक्तस्तत्परश्च यो नित्यं भवति स यतवाक्कायमानसो भवति। यतकाय आसनदार्ढ्येन। यतवाग् विषयेभ्य इन्द्रियाणां प्रत्याहरणेन। यतमानसः सर्वसंकल्पत्यागेन। अत्र चतुर्भिः साधनैर्यतवाक्कायमानसत्वं साध्यम्। नित्यं विविक्तसेवादिशीलः सन् यतवाक्कायमानसो भूत्वा ब्रह्मभूयाय कल्पत इत्युत्तरेणान्वयः।'),
('nilakantha-sc:source:18.53','Nīlakaṇṭha','gita.18.53','sa','commentary','।।18.53।।एवं यतवाक्कायमानसस्य योगिनो योगजाः सिद्धय उपतिष्ठन्ति। ताश्च श्रुतौ दर्शिताःपृथिव्यप्तेजोऽनिलखे समुत्थिते पञ्चात्मके योगगुणे प्रवृत्ते। न तत्र रोगो न जरा न मृत्युः प्राप्तस्य योगाग्निमयं शरीरम् इति। तथायं यं लोकं मनसा संविभाति विशुद्धसत्त्वः कामयते यांश्च कामान्। तं तं लोकं जयते तांश्च कामांस्तस्मादात्मज्ञं ह्यर्चयेद्भूतिकामः इति च। संविभाति संकल्पयति। लोकं लोचनीयमतीतानागतमर्थजातम्। कामान् काम्यमानान्विषयान्। जयते उपलभते इति श्रुतिपदानामर्थः। तथानाविरतो दुश्चरितान्नाशान्तो नासमाहितः। नाशान्तमानसो वापि प्रज्ञानेनैनमाप्नुयात् इति। प्रज्ञानेन शास्त्राचार्योपदेशजेन ज्ञानेन दुश्चरितादिसेवनाद्विरक्तः शान्तो जितचित्तः समाहितो निरुद्धचित्तवृत्तिरप्यशान्तमानसो योगैश्वर्यासक्तचित्तः एनमात्मानं न प्राप्नुयादिति श्रुत्यर्थः। तदिदमाह -- अहंकारमिति। यदा तु योगी यतमानसोऽस्मितामात्रप्रत्ययो भवति तदा सैवास्मितावस्थितिर्विषयाभिमुखाहंकार इत्युच्यते? विषयविमुखा त्वस्मितेति ततस्तमहंकारं निगृह्णीयात्। तदनिग्रहे योगी बलं सत्यसंकल्पत्वादिसामर्थ्यमात्मनः पश्यन् दर्पं करोति न मत्तुल्योऽन्योऽस्तीति मन्यते। ततश्च दृप्तो धर्ममतिक्रामतीत्यापस्तम्बवचनाद्दिव्यान्कामानिच्छति। तत्र केनचिन्निमित्तेन कामप्रतिबन्धे सति क्रोधवान्भवति। ततः परोत्सादनाय भूयांसं शिष्यादिपरिग्रहं संपादयति ततो नश्यतीति। तस्मात्सर्वानर्थमूलभूतमहंकारमेव विमुच्य तत इतरान्सर्वान् विमुञ्चति। अहंकारविमोकेऽपि निर्ममत्वं तत्प्रदर्शितेषु विषयेषु ममताशून्यत्वे सत्यहंकारः शिथिलीभूतो विषयवैमुख्यं प्राप्य स्वकारणेऽस्मितायां विलीयते। ततः शान्तोऽस्मिताया अपि प्रलयान्निरिन्धनाग्निवदुपरतो योगी ब्रह्मभूयाय कल्पते।'),
('nilakantha-sc:source:18.54','Nīlakaṇṭha','gita.18.54','sa','commentary','।।18.54।।अस्यैवं शान्तस्य केवलस्य योगिनो व्युत्थानावस्थामाह -- ब्रह्मभूत इति। यो हि सुप्तौ वा निपतितो योगी व्युत्थाने जडदेहस्तमोग्रस्तचित्त इव तन्द्रालुरुत्तिष्ठति ब्रह्मभूतस्तु प्रसन्नात्मा प्रसन्नचेताः लघुशरीरः अमृतेनेव समाधिसुखेन तृप्तस्तदेकप्रवणो न शोचति नष्टम्। नाप्यप्राप्तं काङ्क्षति दारादिकम्। सर्वेषु भूतेषु चतुर्विधेषु समः ब्रह्मैवेदं सर्वमिति बुद्ध्या वैषम्यवर्जितः सन् परां मद्भक्तिं द्वैतदृष्टिविवर्जितां भावनां लभते। पातञ्जलयोगी तु न व्युत्थाने परां दृष्टिं लभते भेददर्शित्वात्। अयं च भक्तः श्रीभागवते दर्शितःसर्वभूतेषु येनैकं भगवद्भावमीक्षते। भूतानि भगवत्यात्मन्येष भागवतोत्तमःइति। सोऽयं चतुर्थो भक्तोज्ञानी त्वात्मैव मे मतम् इति भगवतापि दर्शितः।'),
('nilakantha-sc:source:18.55','Nīlakaṇṭha','gita.18.55','sa','commentary','।।18.55।।अस्या अद्वैतात्मतत्त्वज्ञानलक्षणाया भक्तेः फलमाह -- भक्त्येति। मां उक्तविधया भक्त्या ज्ञानी अभितः साकल्येन जानाति। साकल्यमेवाह -- यावानिति। किमहमणुपरिमाणो वा देहसंमितो वा तार्किकाणामिवाकाशवत्सकलमूर्तद्रव्यसंयोगित्वलक्षणविभुत्वाश्रयो वा सप्रपञ्चाद्वैतवादिनामिव स्वगतभेदवान्वाऽखण्डैकरसो वेति परिमाणतस्तत्त्वतो मां तत्पदार्थं जानाति तथा यश्चास्मीति। देहेन्द्रियप्राणमनसामन्यतमः कियत्कालस्थायी वा क्षणिकविज्ञानरूपो वा शून्यं वा कर्ता भोक्ता वा जडो वा जडाजडरूपो वा चिद्रूपो वा कर्तृत्वभोक्तृत्ववर्जित आनन्दघनो वेति तत्त्वतः सर्वसंशयराहित्येन मामजरममरमभयमशोकं जानाति। तथा च श्रुतिःभिद्यते हृदयग्रन्थिश्छिद्यन्ते सर्वसंशयाः। क्षीयन्ते चास्य कर्माणि तस्मिन्दृष्टे परावरे इति आत्मदर्शने सति सर्वसंशयोच्छेदं दर्शयति। एवंक्षेत्रज्ञं चापि मां विद्धि सर्वक्षेत्रेषु भारत इत्युक्तेः सर्वक्षेत्रेष्वेकं मां विभुं सच्चिदानन्दघनं तत्त्वतो ज्ञात्वा सर्वोपाधिविनिर्मुक्तं याथात्म्येन ज्ञात्वा साक्षात्कृत्य ततो व्याप्तो ब्रह्मभावं गतो भवतीत्यर्थः।ब्रह्म वेद ब्रह्मैव भवति इति श्रुतेः। यद्वा तत इति कारणब्रह्मभावापत्तिः सार्वात्म्यरूपा प्रथममुक्ता।य एवं वेदाहं ब्रह्मास्मीति स इदं सर्वं भवतिस एतमेव पुरुषं ब्रह्म ततममपश्यत् इत्यादिश्रुतिभ्यो मुक्तानां सार्वात्म्यावगमात्। ततमं तततमम्। एकस्तकारश्छान्दस्यां प्रक्रियायां लुप्तो द्रष्टव्य इति श्रुतिभाष्यम्। अनन्तरं कारणभावापत्तेरनुपदमेव तत् ब्रह्म तच्छब्दाभिधेयम्तदिति वा एतस्य महतो भूतस्य नाम भवति इति श्रुतेः। शुद्धं ब्रह्म विशते दर्पणापाये प्रतिबिम्बो बिम्बमिव प्रविशति। कार्योपाधिनीं जीवानां कारणोपाधीश्वरप्राप्तिद्वारैव निष्कलब्रह्मप्राप्तिरित्यावेदितं प्रागेव। यद्वा मां ज्ञात्वा तद्विशत इत्येतावतैव ज्ञानप्रवेशयोः पौर्वापर्ये सिद्धे तदनन्तरमिति पदेन तच्छब्देन बुद्धिस्थं देहं परामृश्य तत्पातानन्तरमिति व्याख्येयम्। यतो जातेऽपि तत्त्वज्ञाने यावद्देहपातं प्रारब्धकर्मणां प्रतिबन्धाद्विदेहकैवल्यं न प्राप्यते। अन्यथा ज्ञानसमकालमेव देहपातापत्तिः स्यात्।विमुक्तश्च विमुच्यतेभूयश्चान्ते विश्वमायानिवृत्तिः इति मुक्तस्य मुक्तिं निवृत्तायाश्च मायायाः पुनर्निवृत्तिं वदज्जीवन्मुक्तिशास्त्रं बाधितं स्यात्। यथा तार्किकाणां नष्टेऽपि समवायिकारणे पटादिकं क्षणमात्रमवतिष्ठते एवमस्माकमप्यनादिकालाया देहाद्युपादानभूताया अविद्याया विनाशेऽपि किंचित्कालं देहादिप्रतिभानं युज्यते। ईदृशमेव जीवन्मुक्तमपेक्ष्य भगवतोक्तंउपदेक्ष्यन्ति ते ज्ञानं ज्ञानिनस्तत्त्वदर्शिनः इति। स्थितप्रज्ञलक्षणस्मृतिरपि तल्लक्षणाभिधित्सयैव प्रववृते इति दिक्।'),
('nilakantha-sc:source:18.56','Nīlakaṇṭha','gita.18.56','sa','commentary','।।18.56।।ननुतद्यथैषीकातूलमग्नौ प्रोतं दूयेतैवं हास्य सर्वे पाप्मानः प्रदूयन्ते इति पूर्वकर्मणां ज्ञानेन प्रायश्चित्तेनेव सत्यपि नाशश्रवणे ज्ञानोत्तरकालीनानां कर्मणां नाशाभावात् ज्ञानोत्तरमपि देहधारणे स्वाभाविकानां कर्मणां वर्जनस्यासंभवादवश्यं ज्ञानिनोऽपि बन्धः स्यादित्याशङ्क्याह -- सर्वकर्माणीति। मद्व्यपाश्रयोऽहमेव प्रज्ञानघनः प्रत्यगात्मा व्यपाश्रय आश्रयो यस्य स मद्व्यपाश्रयो ज्ञानी। सर्वकर्माणि विहितानि निषिद्धानि वा सदाऽसकृत्कुर्वाणोऽपि मत्प्रसादान्मदनुग्रहात् शाश्वतं नित्यं अव्ययं परमसर्वोत्कृष्टं पदं पदनीयं मोक्षमवाप्नोति। न तु ज्ञानोत्तरमपि क्रियमाणैः कर्मभिर्बध्यते।तस्य पुत्रा दायमुपयन्ति सुहृदः साधुकृत्यां द्विषन्तः पापकृत्याम् इति?न ह वा एवविदि किंचन राज आध्वंसतेतं विदित्वा न लिप्यते कर्मणा पापकेन इत्यादिशास्त्रेण तत्त्वज्ञानिनः कर्मालेपश्रवणात्।'),
('nilakantha-sc:source:18.57','Nīlakaṇṭha','gita.18.57','sa','commentary','।।18.57।।एवं वर्णाश्रमादिधर्मपुरस्कारेण ससाधना सफला च ब्रह्मविद्या निरूपिता। अस्याः प्राप्तये पुनः साधनत्वेन भक्तिमेव विधत्ते -- चेतसेति। चेतसा विवेकबुद्ध्या सर्वाणि कर्माणि नित्यनैमित्तिकानि मयि भगवति,वासुदेवे संन्यस्ययत्करोषि यदश्नासि इत्युक्तरीत्या समर्प्य मत्परः अहमेव परः प्राप्यो यस्य न तु मद्भक्त्या अर्थादीन्प्रार्थयानः। बुद्धियोगं पूर्वोक्तं सिद्ध्यसिद्ध्योः समत्वलक्षणं बन्धहेतोरपि कर्मणो मोक्षहेतुत्वसंपादकं उपाश्रित्य आश्रित्य मच्चित्तः मदेकशरणः सततं सर्वदा भव।'),
('nilakantha-sc:source:18.58','Nīlakaṇṭha','gita.18.58','sa','commentary','।।18.58।।एतस्य भक्तियोगस्य करणे गुणमकरणे दोषं चाह -- मच्चित्त इति। दुर्गाणि आध्यात्मिकाधिभौतिकादीनि संकटानि। अहंकारात्स्वपाण्डित्याभिमानात् न श्रोष्यसि मद्वाक्यं तर्हि विनङ्क्ष्यसि पुरुषार्थशून्यो भविष्यसि।'),
('nilakantha-sc:source:18.59','Nīlakaṇṭha','gita.18.59','sa','commentary','।।18.59।।स्वतन्त्रोऽहं त्वदुक्तं न करिष्यामीत्याशङ्क्याह -- यदिति। यत् यदि अहंकारं गर्वमाश्रित्य न योत्स्ये युद्धं न करिष्ये इति मन्यसे एष ते तव व्यवसायो निश्चयो मिथ्या। यतः प्रकृतिः क्षात्रस्वभावस्त्वां नियोक्ष्यति।प्रकृतिं यान्ति भूतानि निग्रहः किं करिष्यति इति चोक्तम्।'),
('nilakantha-sc:source:18.60','Nīlakaṇṭha','gita.18.60','sa','commentary','।।18.60।।प्रकृतिस्त्वां नियोक्ष्यतीत्येतदेव व्याचष्टे -- स्वभावजेनेति। स्वभावजेन पूर्वोक्तेन शौर्यादिना अवशोऽपि परवश एव तत्करिष्यसि।'),
('nilakantha-sc:source:18.61','Nīlakaṇṭha','gita.18.61','sa','commentary','।।18.61।।कोऽसौ परो यद्वशेऽहमस्मीत्यत आह -- ईश्वर इति। ईश्वर ईशनशीलोऽन्तर्यामी पृथिव्यादीनामस्माकं च सर्वभूतानां सर्वप्राणिनां हृद्देशे बुद्धिगुहायां सर्वप्राणिप्रवर्तकस्तिष्ठति। कीदृशः। सर्वभूतानि भ्रामयन्नूर्ध्वाधोमार्गेषु संचारयन् काष्ठपुत्तिका इव सूत्रधारः यन्त्रारूढानि यन्त्रमिव यन्त्रं उत्क्रमणादिसाधनं सर्वप्राणाद्यात्मकं लिङ्गं तदारूढानि मायया स्वशक्त्या भ्रामयन्निति संबन्धः। हे अर्जुन शुक्ल विशुद्धान्तःकरण? सेश्वरोऽसीति भावः। अत्राहंकारपूर्वकं यः कर्म करोति यश्च ईश्वरपरवशोऽहंकरोमीति बुद्ध्या करोति तयोरत्यन्तवैलक्षण्यप्रदर्शनार्थो मन्त्रो भाष्ये उदाहृतःअहश्च कृष्णमहरर्जुनं च विवर्तेते रजसी वेद्याभिः इति भारद्वाजार्षंअहश्च कृष्णमहरर्जुनं चइत्याग्निमारुतस्य प्रतिपत् इति ब्राह्मणेन आग्निमारुते शस्त्रे विनियुक्ता प्रथमेयमृक्। यस्मिन् दिवसे सोमः सूयते यागार्थं तदेव जन्मसाफल्यदिनं मुख्यमहःशब्दवाच्यम्। अन्यत्तु दिनमदिनमेव निष्फलत्वात्। तथा च स्मृतिःदशभिर्जन्मभिर्वेदा आधानं शतजन्मभिः। सहस्रैर्जन्मभिः सोमं ब्राह्मण्यं पातुमर्हति इति सोमयागस्य दौर्लभ्यं दर्शयति। तदयमहःशब्दः कालवचनोऽपि सौम्ये कर्मणि वर्तते। यथा दर्शपौर्णमासशब्दौ। तत्रैवं सति अहः यागः कृष्णं अविदुषा कृतं अप्रकाशमिव भवति। तथाऽहरर्जुनं स्वच्छं तदेव विदुषा कृतं प्रकाशरूपमिव भवति। ते एते उभे अपि विद्वदविद्वत्कृते अहनी रजसी प्रवृत्तिरूपत्वात् रजोगुणकार्ये अपि वेद्याभिर्विद्याभिः कर्माङ्गावबद्धोपासनारूपा वा परमेश्वरे सर्वकर्मार्पणरूपा वा अहंकरोमीत्यभिमानरूपा वा विद्या विज्ञानानि ताभिर्विवर्तेते वैपरीत्येन वर्तेते। सोपासनं कर्म श्वेतं परमात्मतत्त्वप्रकाशकं बन्धविच्छेदहेतुः? मूढकृतं कर्म कृष्णं स्वरूपावरकं बन्धहेतुरित्यर्थः। तदेवं भगवान् पार्थं अर्जुनेति संबोधयन् एतस्य स्वच्छान्तःकरणत्वद्योतनेन शुक्ले धर्मेऽधिकारं दर्शयति।'),
('nilakantha-sc:source:18.62','Nīlakaṇṭha','gita.18.62','sa','commentary','।।18.62।।तमेव ईश्वरं सर्वभावेन सर्वात्मना शरणमाश्रयं गच्छ श्रयस्व। तत्प्रसादात् तदनुग्रहात्परां शान्तिमुपरतिं समाधिमितियावत्। तथा च सूत्रंसमाधिसिद्धिरीश्वरप्रणिधानात् इति। स्थानं च परं विष्णोः पदं मोक्षं शाश्वतं नित्यं प्राप्स्यसि।'),
('nilakantha-sc:source:18.63','Nīlakaṇṭha','gita.18.63','sa','commentary','।।18.63।।सर्वगीतार्थमुपसंहरति -- इतीति। इति एवंप्रकारं ते तुभ्यं मया सर्वज्ञेन परमकारुणिकेन ज्ञानम् आख्यातम्। गुह्यान्मन्त्रतन्त्ररसायनरूपाद्गुह्यतरमतिशयितं रहस्यम्। एतद्यथोक्तं शास्त्रार्थजातं विमृश्य सम्यगालोच्य यथेच्छसि तथा कुरु।'),
('nilakantha-sc:source:18.64','Nīlakaṇṭha','gita.18.64','sa','commentary','।।18.64।।एवं यथेष्टकरणमभ्यनुज्ञायापि अतिवात्सल्याच्छ्लोकद्वयेनैव कृत्स्नं शास्त्रार्थमुपदेक्ष्यंस्तद्ग्रहणे ऐकाग्र्यमस्य संपादयितुमाह -- सर्वेति। सर्वेभ्यो गुह्येभ्यः अतिशयितं गुह्यं सर्वगुह्यतमं भूयः पुनरसकृदुक्तमपि मे मम वचनं शृणु। परमं परमार्थविषयत्वात्। न लोभान्नापि भयात्त्वां वक्ष्यामि। किं तर्हि मे मम इष्टोऽसि,परमाप्तोऽसि इति हेतोः द़ृढं अतिशयितं ते तव हितं यतस्ततो वक्ष्यामि। तव इष्टत्वात् विद्यायाश्च हितत्वात् तद्वचनं आप्ते त्वयि अवश्यं वक्तव्यमिति भावः।'),
('nilakantha-sc:source:18.65','Nīlakaṇṭha','gita.18.65','sa','commentary','।।18.65।।तदेव गुह्यतमं हितमाह -- मन्मना इति। अहं प्रत्यगात्मानन्दैकघनः परिपूर्णस्तदाकारं मनो यस्य स मन्मनाः भव। एतेन ब्राह्मात्माभेदोऽपि साक्षात्करणीय इत्युत्तरषट्कार्थ उक्तः। कथमेवंविधा ज्ञाननिष्ठा लभ्यतेऽत आह -- मद्भक्तो भव। एतेन भगवदुपासनात्मको मध्यमषट्कार्थ उक्तः। कथमल्पपुण्यस्य भक्तिरुदेष्यतीत्यत आह -- मद्याजी भगवदर्थकर्मकरणशीलो भव। एतेन कर्मप्रधान आद्यषट्कार्थो विवृतः। ननु यस्य भगवद्याजित्वं न संभवति दारिर्द्यात्स्त्र्याद्यभावाद्वा तस्य भगवद्भक्तिदौर्लभ्याद्ब्रह्माकारा चेतोवृत्तिदुर्लभतरेत्याशङ्क्याह -- मां नमस्कुरु प्राकृतभक्त्यैव प्रतिमादौ भगवन्तं सर्वोपचारसमर्पणेन नमस्कारादिना सम्यगाराधयेत्यर्थः। तथाचाश्वलायनो नमस्कारस्यैव यज्ञत्वमुदाहरतियो नमसा स्वध्वरः इति यज्ञो वै नम इति हि ब्राह्मणं भवति इति च। एवमुक्तस्य सोपानत्रयारूढस्य फलमाह -- मामिति। मामेव तत्पदार्थं सर्वजगत्कारणं सर्वेश्वरं सर्वशक्तिमखण्डैकरसं त्वं एष्यसि प्राप्स्यसि बिम्ब इव प्रतिबिम्बं? घटाकाश इव महाकाशम्। अस्मिन्नर्थे शपथं करोति। ते तव पुरः सत्यं अबाधितार्थभूतं प्रतिजाने प्रतिज्ञां करोमि मामेवैष्यसीति। प्रियोऽसि मे यतस्त्वं मे मम प्रियोऽसि अतः प्रतारणानर्हे त्वयि सत्यमेवाहं ब्रवीमीत्यर्थः।'),
('nilakantha-sc:source:18.66','Nīlakaṇṭha','gita.18.66','sa','commentary','।।18.66।।एवं नमनयजनभजनमननक्रमेण सांख्यनिष्ठा उक्ता या पूर्वं ध्यानेनात्मनि पश्यन्तीत्यनेन श्लोकेन दर्शिता। इदानींअन्ये त्वेवमजानन्तः श्रुत्वान्येभ्य उपासते। तेऽपि चातितरन्त्येव मृत्युं श्रुतिपरायणाः इति केवलोपास्तिनिष्ठा योगाख्योक्ता तामाह -- सर्वेति। सर्वेषां वर्णानामाश्रमाणां देहेन्द्रियबुद्धीनां च धर्मानग्निहोत्रादीन् सुखदुःखादींश्च त्यक्त्वा मामेकं सर्वेश्वरं सर्वशक्तिं सोपाधिं निरुपाधिं वाऽखण्डैकरसमानन्दघनं परमात्मानम्। शरणं शृणाति हिनस्त्यविद्यादीन्क्लेशादीन् शरणमाश्रयः परायणं गच्छ प्राप्नुहि। मदेकशरणो भवेत्यर्थः। अत्र अन्नं भुक्त्वैव तृप्यति नतु जलमात्रं पीत्वेतिवद्धेतुत्वं क्त्वाप्रत्ययार्थः। सर्वधर्मपरित्यागेन मां शरणं व्रजेत्यर्थः। यथोक्तम्अनात्मदर्शनेनैव परात्मानमुपास्महे इति। एतस्य भगवच्छरणीकरणस्य फलमाह -- अहंत्वेति। अहं प्रत्यगात्मा सूर्याद्यन्तर्यामी नारायणः सकलपाप्मविनिर्मुक्तः सम्यग्ज्ञातः सन् त्वा त्वां सर्वपापेभ्यः संचितक्रियमाणेभ्यो गोत्रवधादिजेभ्यो मोक्षयिष्यामि। मा शुचः शोकं माकार्षीः। तथाहि। तत्त्वज्ञानफलं पापास्पर्शः शोकतरणं च सर्वश्रुतिस्मृतिप्रसिद्धम्। आदित्यान्तर्वर्तिनं नारायणं प्रकृत्य च्छान्दोग्ये श्रूयतेस एष सर्वेभ्यः पाप्मभ्य उदित उदेति ह वै सर्वेभ्यः पाप्मभ्यो य एवं वेदतरति शोकमात्मवित्तत्र को मोहः कः शोक एकत्वमनुपश्यतः इति। उदितः ऊर्ध्वमितो गतः पापान्युत्क्रम्य गतो,निष्पाप इति श्रुतिपदार्थः। वर्णाश्रमधर्मसंन्यासपूर्वकं षष्ठाध्यायेनोक्तेन योगेन देहादीनां धर्मांश्च त्यक्त्वा निर्विकल्पमात्मानं साक्षात्कुर्वतो न कर्मलेप इत्यर्थः।'),
('nilakantha-sc:source:18.67','Nīlakaṇṭha','gita.18.67','sa','commentary','।।18.67।।एवं श्लोकद्वयेनज्ञानयोगेन सांख्यानां कर्मयोगेन योगिनाम् इति सांख्ययोगौ द्वितीयाध्याये दर्शितावुपसंहृत्य विद्यासंप्रदायविधिमाह -- इदमिति। अतपस्काय तप आलोचनं तद्रहिताय। अयत्नशीलायेत्यर्थः। अभक्ताय श्रद्धाहीनाय। अशुश्रूषवे गुरुसेवामकुर्वते। मां परमात्मानं योऽभ्यसूयति मदीयगुणासहिष्णुतया मयि दोषारोपपरो भवति तस्मै। नञः प्रत्येकं संबद्धत्वादेतेषां विशेषणानामन्यतमाभावेऽपि कदाचन महत्यपि संकटे इदं न वाच्यं नोपदेष्टव्यम्। अत्रविद्या ह वै ब्राह्मणमाजगाम गोपाय मा शेवधिष्टेऽहमस्मि। असूयकायानृजवेऽयताय न मा ब्रूयाऽवीर्यवती तथा स्याम्।यस्य देवे परा भक्तिर्यथा देवे तथा गुरौ। तस्यैते कथिता ह्यर्थाः प्रकाशन्ते महात्मनः इति श्रवणादसूयारहितायार्जवोपेतायाभ्यासशीलाय गुरुपरमेश्वराराधनपराय च एतद्रहस्य देयं नान्यस्मा इत्यर्थः।'),
('nilakantha-sc:source:18.68','Nīlakaṇṭha','gita.18.68','sa','commentary','।।18.68।।एवं संप्रदायविधिमुक्त्वा संप्रदायकर्तुः फलमाह -- य इदमिति। इदं परमं गुह्यं यो भक्तिहीनो मानपूजाद्यर्थी सन् मद्भक्तेष्वभिधास्यति सोऽपि ततएव पुण्यान्मयि परमेश्वरे चिदेकरसे परां भक्तिमद्वैतलक्षणामुपासनां कृत्वा तत्रादरं प्राप्य तामनुष्ठाय च मामेवैष्यति मुक्तिं प्राप्स्यतीत्यर्थः। असंशयः सशयोऽत्र नास्ति। स्मर्यते हि अजामिलादीनां भक्तिगन्धहीनानामपि पुत्रसंकेतिनेन नारायणेतिनाम्ना,स्नेहवशादाह्वयतां तावन्मात्रतुष्टेन भगवता सद्गतिर्दत्ता किमु वक्तव्यं यो वाचा एतावच्छास्त्ररहस्यं प्रतिपादयति तस्य भक्तिलाभादिक्रमेण कृतकृत्यत्वं भविष्यतीति।'),
('nilakantha-sc:source:18.69','Nīlakaṇṭha','gita.18.69','sa','commentary','।।18.69।।ननु अश्रद्धया कृतं सर्वं व्यर्थमिति त्वयैवोक्तं कथमभक्तस्याप्येतच्छास्त्राभिधानतो भक्त्यादिलाभः संभवेदित्याशङ्क्याह -- न चेति। तस्मादेतच्छास्त्रप्रवर्तकादन्यो मनुष्येषु मे मम प्रियकृत्तमो न च कश्चिदस्ति। इयमेव मम महती वाचिकी भक्तिस्तां कृत्वा सोपानारोहक्रमेण मे मम प्रियतरो भविता भविष्यति।अनिच्छयापि संस्पृष्टो दहत्येव हि पावकः इति। न च भुवि एतस्मादन्यत्परमार्थसाधनमस्तीति भावः। अक्षरार्थः स्पष्टः।'),
('nilakantha-sc:source:18.70','Nīlakaṇṭha','gita.18.70','sa','commentary','।।18.70।।अध्यापकस्य फलमुक्त्वाऽध्येतुः फलमाह -- अध्येष्यते चेति। ज्ञानयज्ञेन निर्विकल्पसमाधिना इष्टः पूजितः स हि धर्ममेघनामा पुष्कलपुण्यवृष्टिकरस्तद्वदेतस्य शास्त्रस्याध्ययनमपीत्यर्थः। इति मे मम सर्वेश्वरस्य मतिः। तेनात्र स्तुतिमात्रमेतदिति न मन्तव्यं किंतु भूतार्थवाद एवायमिति भावः।'),
('nilakantha-sc:source:18.71','Nīlakaṇṭha','gita.18.71','sa','commentary','।।18.71।।प्रवक्तुरध्येतुश्च फलमुक्त्वा श्रोतुरपि फलमाह -- श्रद्धावानिति। शृणुयादपि अक्षरश्रवणं कुर्यादपि किमु वक्तव्यमादरेणार्थग्रहणं यः कुर्यात्स उक्तं फलं प्राप्नुयादिति। स्पष्टार्थः श्लोकः। तथाचोक्तं श्रीभागवते -- वासुदेवकथाप्रश्नः पुरुषांस्त्रीन्पुनाति हि। वक्तारं प्रच्छकं श्रोतृ़ंस्तत्पादसलिलं यथा इति।'),
('nilakantha-sc:source:18.72','Nīlakaṇṭha','gita.18.72','sa','commentary','।।18.72।।सर्वान्तर्यामी सर्वज्ञोऽपि भगवाँल्लोकशिक्षार्थं शिष्यस्य ज्ञानं जातं नवेति पृच्छति। अन्यथा पुनः पुनः स्वयमेत्य उपदेशं कृतवता प्रभुणा निदाघ इव मयायं शतकृत्वोऽप्युपदेशेन कृतार्थः कर्तव्य इत्याशयेनाह -- कच्चिदिति। कच्चिदिति कामप्रवेदने। हे पार्थ? एतत्त्वया एकाग्रेण चेतसा श्रोतव्यं शब्दतोऽर्थतश्च बोद्धव्यमिति मम कामोऽस्ति ततस्त्वां पृच्छामि किमिदं त्वया श्रुतमिति। श्रुतवतोऽपि तव अज्ञानकृतः संमोहो विपर्ययः अनात्मन्यात्मधीरूपः स्वधर्मे युद्धे चाधर्मधीरूप इति स द्विविधोऽपि नष्टः क्वचित्। मच्छ्रमसाफल्यमिच्छुस्त्वामहं पृच्छामीत्यर्थः।'),
('nilakantha-sc:source:18.73','Nīlakaṇṭha','gita.18.73','sa','commentary','।।18.73।।एवं पृष्टः स्वस्य कृतकृत्यतां ज्ञापयन्नर्जुन उवाच -- नष्टो मोह इति। मोहः पूर्वोक्तो द्विविधोऽपि नष्टः। स्मृतिरयमहमस्मि परंब्रह्मेत्यात्मानुसंधानरूपा आत्मतत्त्वविषया लब्धा। यस्य लाभेन सर्वहृदयग्रन्थीनांयावान्यश्चास्मि तत्त्वतः इत्यत्रोदाहृतानां चिज्जडैक्यभ्रमप्रभवानां विमोक्षो भवति। तथा च श्रूयतेवियोगायोग्यस्मृतिलम्भे सर्वग्रन्थीनां विप्रमोक्षः इति। त्वत्प्रसादान्मयाच्युत स्मृतिर्लब्धेति संबन्धः। स्थितोऽस्मि त्वच्छासने इति शेषः। गतसंदेहो नष्टसंदेह इत्यनेनानात्मन्यात्मधीरूपो मोहो नष्ट इति दर्शितम्। करिष्ये वचनं तवेत्यनेन स्वधर्मे युद्धे चाधर्मधीरूपोऽपि मोहो नष्ट इति दर्शितम्।'),
('nilakantha-sc:source:18.74','Nīlakaṇṭha','gita.18.74','sa','commentary','।।18.74।।समाप्तः शास्त्रार्थः। इदानीं कथाप्रबन्धमेवानुवर्तयन्संजय उवाच -- इतीति। अद्भुतं चेतसो विस्मयकरम्। रोमहर्षणं रोमाञ्चोद्भेदजनकम्। शेषं स्पष्टम्।'),
('nilakantha-sc:source:18.75','Nīlakaṇṭha','gita.18.75','sa','commentary','।।18.75।।कथमयं त्वया दूरस्थयोरपि वासुदेवार्जुनयोः संवादः श्रुत इत्यत आह -- व्यासप्रसादादिति। भगवता व्यासेन दिव्यं चक्षुः श्रोत्रादिकं मह्यं दत्तं येनाहं व्यवहितं विप्रकृष्टं वा सर्वं करतलामलकवद्विजानामि। अतो व्यासप्रसादादेतच्छास्त्रं परं गुह्यं गोप्यं अहं श्रुतवान्। योगं चपश्य मे योगमैश्वरम् इति प्रतिज्ञापूर्वकं प्रदर्शितं वैश्वरूप्यं तमपि दृष्टवानिति शेषः। स्वयं कथयत इत्युक्तेअस्य महतो भूतस्य निःश्वसितमेतद्यदृग्वेदः इति श्रुतेः स्वनिःश्वसितं वेदं शिष्याचार्यपरंपरया कथयत इत्यायाति तदर्थं साक्षात्कथयत इति। सृष्ट्यादौ ब्रह्माणं प्रतीव इदानीमर्जुनं प्रति साक्षात्कथयतः श्रुतवानहमित्यर्थः। तेन भगवदनुग्रहपात्रतया ब्रह्मणा समत्वं स्वस्य द्योत्यते। अत्र एतद्योगमित्यभेदेनान्वये तु गुह्यपदापेक्षया एतद्योगमिति पुंनपुंसकलिङ्गयोरपि सामानाधिकरण्यं शक्यं च यत्किंचिदश्नतापि क्षुदुपहन्तुमित्यादाविव पूर्वप्रवृत्तलिङ्गसंस्कारप्राबल्यादुत्तरत्र भिन्नलिङ्गविशेष्यलाभेऽपि पूर्वसंस्कारो न निवर्तत इति सामानाधिकरण्यं विलिङ्गयोरपि वक्तुं शक्यमिति ज्ञेयम्।'),
('nilakantha-sc:source:18.76','Nīlakaṇṭha','gita.18.76','sa','commentary','।।18.76।।केशवार्जुनसंवादश्रवणजं विश्वरूपाख्ययोगदर्शनजं चाह्लादं क्रमेण श्लोकद्वयेनाह -- राजन्निति। हे राजन् हे धृतराष्ट्र? पुण्यं पुण्यकरं पापहरं चेत्यर्थात्। संस्मृत्यसंस्मृत्येति संभ्रमे द्विरुक्तिः। शेषं स्पष्टार्थम्।'),
('nilakantha-sc:source:18.77','Nīlakaṇṭha','gita.18.77','sa','commentary','।।18.77।।तच्चेति। रूपं विश्वरूपम्। एतद्दर्शने हिब्रह्माणमीशम् इति देशतो विप्रकृष्टं?वक्त्राणि ते त्वरमाणा विशन्ति इति कालतो व्यवहितं भीष्मादिक्षयं च करतलामलकवद्दृष्टवान्। तच्च जगतो मिथ्यात्वमन्तरेण न संभवतीति प्रतिपादितं वेदान्तकतकेअतीतानागतं वस्तु वीक्ष्यते करबिल्ववत्। योगी संकल्पमात्रोत्थमिति शास्त्रेषु डिण्डिमाः 1 मायायां सर्वदा सर्वं सर्वावस्थमिदं जगत्। अस्तीति तदुपाधिश्चित्सार्वात्म्यात्सर्वमीक्षते 2 आरम्भपरिणामाभ्यां स्वेन रूपेण यन्न सत्। अतीतानागतं वस्तु योगी तद्वीक्षतां कथम् 3 संकल्पमात्रभातं वस्त्वतीतादि यदीष्यते। नष्टस्त्रीदर्शनाभं तत्स्याद्योगिज्ञानमप्रमा 4 योगिसंकल्पमात्रेण तस्योत्पत्तिर्यदीष्यते। ईशसंकल्पमात्रेण सर्वोत्पत्तिस्तदेष्यताम् 5 आरम्भे परिणामे वा देशकालाद्यतिक्रमः। नैव दृष्टः क्वचित्सोऽयं स्वप्नमायादिषु स्फुटः 6 युगपद्गृह्यते कुम्भो नानादेशस्थयोगिभिः। जलसूर्य इवास्माभिस्तेनासौ कल्पितः स्फुटम् 7 योगिभिर्गृह्यमाणत्वाद्धटः सर्वत्र सर्वदा। सन्नेवास्तीति चेत्कार्यं कथमीदृग्विधं भवेत् 8 व्यावृत्तं हीष्यते कार्यं युगपद्भिन्नदेशता। चेत्कल्पनां विनास्येष्टा दृष्टान्तस्तत्र नास्ति वः 9 तस्मान्नाणुभिरारब्धभित्तिवन्नापि गव्यवत्। प्रकृतेः परिणामो वा जगत्किंत्विन्द्रजालवत् 10 सत्यं बद्धदृशामिन्द्रजालं विश्वं पराक्दृशाम्। अधिष्ठानादृते शुद्धदृशां नास्त्येव तद्वयम्। इति 11 स्पष्टार्थो मूलश्लोकः।'),
('nilakantha-sc:source:18.78','Nīlakaṇṭha','gita.18.78','sa','commentary','।।18.78।।यस्मादनन्तैश्वर्यो भगवांस्तदनुगृहीतोऽर्जुनश्च युधिष्ठिरपक्षेऽस्ति अतस्त्वया जयाशा न कार्येत्याह -- यत्रेति। यत्र पक्षे। ध्रुवेति सर्वत्र संबध्यते। श्रीर्दिव्यसभादिशोभा। विजयः प्रसिद्धः। भूतिरैश्वर्यं सर्वनियन्तृत्वम्। नीतिर्नयश्च एतत्सर्वं तत्र तस्मिन्पक्षे ध्रुवमिति मम मतिः। अतः पाण्डवैः सह संधिरेव कर्तव्य इति भावः।');
